window.AQ_PHONE_UNITS = [{"format":1,"id":"unit-1-equations-inequalities","title":"Unit 1: Equations and Inequalities","levels":[{"id":"real-numbers","title":"Real numbers and properties","lessons":[{"id":"real-numbers-1","teach":[{"title":"The number sets","text":["Natural numbers: 1, 2, 3, … Whole numbers: 0, 1, 2, 3, … Integers: …, −2, −1, 0, 1, 2, …","Rational numbers can be written as a fraction of two integers. That includes terminating decimals like 0.25 and repeating decimals like 0.333…","Irrational numbers cannot be written as a fraction. Their decimals never end and never repeat, like √2 and π. Rational and irrational numbers together make the real numbers."],"example":{"problem":"Classify −6, 3/4, and √5.","steps":["−6 is an integer, so it is also rational and real.","3/4 is a fraction of integers, so it is rational and real, but not an integer.","√5 is not a perfect square root, so it is irrational and real."]}}],"questions":[{"id":"u1-real1-q1","type":"choice","prompt":"Which number is irrational?","choices":["0.25","√16","√7","22/7"],"answer":2,"hint":"A square root of a non-perfect square never ends or repeats.","solution":"0.25 = 1/4 and 22/7 are fractions, so they are rational. √16 = 4 is rational. √7 is not a perfect square root, so it is irrational."},{"id":"u1-real1-q2","type":"choice","prompt":"Which set of numbers contains 0 but does not contain −5?","choices":["Natural numbers","Whole numbers","Integers","Rational numbers"],"answer":1,"hint":"Natural numbers start at 1. Which set has no negatives?","solution":"Natural numbers do not include 0. Integers and rational numbers both include −5. Whole numbers are 0, 1, 2, … so they include 0 but not −5."},{"id":"u1-real1-q3","type":"input","prompt":"How many of these numbers are integers? 4, −7, 1/2, 0, 2.5","answers":["3"],"hint":"An integer has no fraction or decimal part.","solution":"4, −7, and 0 are integers. 1/2 and 2.5 are not. That is 3 integers."},{"id":"u1-real1-q4","type":"choice","prompt":"The repeating decimal 0.333… is","choices":["rational, because it equals 1/3","irrational, because it never ends","an integer, because it repeats","not a real number"],"answer":0,"hint":"Can you write it as a fraction?","solution":"A repeating decimal can be written as a fraction. 0.333… = 1/3, so it is rational."},{"id":"u1-real1-q5","type":"choice","prompt":"Which best describes √49?","choices":["an irrational number, because it has a root","a rational number, and an integer","rational, but not an integer","not a real number"],"answer":1,"hint":"Find the square root first.","solution":"√49 = 7. That is an integer, so it is also rational and real."},{"id":"u1-real1-q6","type":"input","prompt":"How many of these are irrational? −√9, π, 0.5, 8/4, √2","answers":["2"],"hint":"Simplify any root or fraction first.","solution":"−√9 = −3, 0.5 = 1/2, and 8/4 = 2 are all rational. Only π and √2 are irrational. That is 2."},{"id":"u1-real1-q7","type":"choice","prompt":"Which statement is true?","choices":["Every rational number is an integer","Every irrational number is a whole number","Every integer is a rational number","Some natural numbers are irrational"],"answer":2,"hint":"Any integer n can be written as n/1.","solution":"An integer n equals n/1, so it is rational. The other statements fail: 1/2 is rational but not an integer, and no irrational number is whole or natural."},{"id":"u1-real1-q8","type":"input","prompt":"How many whole numbers are greater than −3 and less than 4?","answers":["4"],"hint":"Whole numbers start at 0.","solution":"The whole numbers in that range are 0, 1, 2, 3. That is 4 numbers."}]},{"id":"real-numbers-2","teach":[{"title":"Commutative and associative","text":["Commutative: order does not matter. a + b = b + a and a · b = b · a.","Associative: grouping does not matter. (a + b) + c = a + (b + c) and (a · b) · c = a · (b · c).","Subtraction and division are not commutative: 5 − 3 is not 3 − 5."],"example":{"problem":"Name the property: (2 · 3) · 4 = 2 · (3 · 4)","steps":["The numbers stay in the same order.","Only the grouping moved.","This is the associative property of multiplication."]}},{"title":"Distributive, identity, inverse","text":["Distributive: a(b + c) = ab + ac.","Identity: a + 0 = a and a · 1 = a.","Inverse: a + (−a) = 0 and a · (1/a) = 1 for a ≠ 0."],"example":{"problem":"Name the property: 9 + 0 = 9","steps":["Adding 0 leaves the number the same.","0 is the additive identity.","This is the identity property of addition."]}}],"questions":[{"id":"u1-real2-q1","type":"choice","prompt":"Which property does 7 + 5 = 5 + 7 show?","choices":["Associative property of addition","Distributive property","Commutative property of addition","Identity property of addition"],"answer":2,"hint":"The order of the numbers changed.","solution":"The numbers swapped places. That is the commutative property."},{"id":"u1-real2-q2","type":"choice","prompt":"Which property does (2 · 3) · 4 = 2 · (3 · 4) show?","choices":["Commutative property of multiplication","Associative property of multiplication","Distributive property","Inverse property of multiplication"],"answer":1,"hint":"The order is the same. What moved?","solution":"The parentheses moved but the order did not. That is the associative property."},{"id":"u1-real2-q3","type":"choice","prompt":"Which property does 6(x + 4) = 6x + 24 show?","choices":["Distributive property","Commutative property of multiplication","Associative property of multiplication","Identity property of multiplication"],"answer":0,"hint":"6 is multiplied by each term inside the parentheses.","solution":"6 multiplies both x and 4. That is the distributive property."},{"id":"u1-real2-q4","type":"choice","prompt":"Which property does 9 + 0 = 9 show?","choices":["Additive inverse property","Commutative property of addition","Distributive property","Additive identity property"],"answer":3,"hint":"Adding 0 changes nothing.","solution":"0 is the additive identity because adding it leaves the number unchanged."},{"id":"u1-real2-q5","type":"choice","prompt":"Which property does 5 · (1/5) = 1 show?","choices":["Multiplicative identity property","Multiplicative inverse property","Commutative property of multiplication","Associative property of multiplication"],"answer":1,"hint":"The two numbers multiply to give 1.","solution":"5 and 1/5 multiply to 1, the multiplicative identity. That is the inverse property."},{"id":"u1-real2-q6","type":"input","prompt":"The identity property says a · __ = a. What number goes in the blank?","answers":["1"],"hint":"Which number leaves a unchanged when you multiply?","solution":"Multiplying by 1 leaves a unchanged, so the blank is 1."},{"id":"u1-real2-q7","type":"choice","prompt":"Which property does −8 + 8 = 0 show?","choices":["Additive inverse property","Additive identity property","Commutative property of addition","Distributive property"],"answer":0,"hint":"A number plus its opposite gives what?","solution":"−8 and 8 are opposites. Their sum is 0. That is the additive inverse property."},{"id":"u1-real2-q8","type":"choice","prompt":"Which equation is NOT true for all numbers?","choices":["a + b = b + a","a(b + c) = ab + ac","a · b = b · a","a − b = b − a"],"answer":3,"hint":"Try small numbers such as a = 5, b = 3.","solution":"Subtraction is not commutative. 5 − 3 = 2 but 3 − 5 = −2. The other three equations are always true."}]},{"id":"real-numbers-3","teach":[{"title":"Using properties to simplify","text":["Properties can make a calculation easier. Group numbers that make 10, 100, or other round numbers.","The distributive property also works backward: ab + ac = a(b + c)."],"example":{"problem":"Compute 4 · 25 · 7 in your head.","steps":["Regroup with the associative property: (4 · 25) · 7.","4 · 25 = 100, so you have 100 · 7.","The answer is 700."]}},{"title":"Opposites and reciprocals","text":["The additive inverse of a is −a.","The multiplicative inverse (reciprocal) of a/b is b/a. Flip the fraction and keep the sign."],"example":{"problem":"Find the multiplicative inverse of −3/5.","steps":["Flip the fraction: 5/3.","Keep the sign negative: −5/3.","Check: (−3/5)(−5/3) = 1."]}}],"questions":[{"id":"u1-real3-q1","type":"choice","prompt":"Which property lets you rewrite 4 · (25 · 7) as (4 · 25) · 7 so you can do 100 · 7?","choices":["Commutative property of multiplication","Associative property of multiplication","Distributive property","Identity property of multiplication"],"answer":1,"hint":"The numbers stay in order. Only the parentheses move.","solution":"Moving the parentheses is the associative property."},{"id":"u1-real3-q2","type":"input","prompt":"Use 6(100 − 2) to compute 6 · 98.","answers":["588"],"hint":"Distribute the 6 across 100 − 2.","solution":"6 · 100 − 6 · 2 = 600 − 12 = 588."},{"id":"u1-real3-q3","type":"choice","prompt":"Which property justifies 2x + 3 = 3 + 2x?","choices":["Commutative property of addition","Associative property of addition","Distributive property","Additive inverse property"],"answer":0,"hint":"The two terms traded places.","solution":"The terms swapped places, so this is the commutative property of addition."},{"id":"u1-real3-q4","type":"choice","prompt":"Which pair are additive inverses?","choices":["3/4 and 4/3","3/4 and −4/3","3/4 and −3/4","3/4 and 0.75"],"answer":2,"hint":"Additive inverses add to 0.","solution":"3/4 + (−3/4) = 0. The other pairs do not add to 0."},{"id":"u1-real3-q5","type":"input","prompt":"What is the multiplicative inverse of −2/3? Type it as a fraction.","answers":["-3/2","-1.5"],"hint":"Flip the fraction and keep the sign.","solution":"Flip −2/3 to get −3/2. Check: (−2/3)(−3/2) = 6/6 = 1."},{"id":"u1-real3-q6","type":"choice","prompt":"Which property is used in 5(2x) = (5 · 2)x = 10x?","choices":["Distributive property","Associative property of multiplication","Commutative property of multiplication","Multiplicative inverse property"],"answer":1,"hint":"5 is not spread over two terms here. The grouping changes.","solution":"The grouping changes from 5(2x) to (5 · 2)x. That is the associative property."},{"id":"u1-real3-q7","type":"choice","prompt":"3 + (x + 7) = 3 + (7 + x) = (3 + 7) + x = 10 + x. Which properties are used, in order?","choices":["Associative, then commutative","Distributive, then identity","Commutative, then distributive","Commutative, then associative"],"answer":3,"hint":"First the order of x and 7 flips. Then the grouping changes.","solution":"Step 1 swaps x and 7: commutative. Step 2 moves the parentheses: associative."},{"id":"u1-real3-q8","type":"input","prompt":"Use the distributive property backward: 17 · 5 + 17 · 15 = 17(5 + 15). What is the value?","answers":["340"],"hint":"Add inside the parentheses first.","solution":"17(5 + 15) = 17 · 20 = 340."},{"id":"u1-real3-q9","type":"choice","prompt":"A student writes 4(x − 3) = 4x − 3. What went wrong?","choices":["The 4 was not multiplied by the 3","The commutative property was used wrongly","The 4 should be added to each term","Nothing, it is correct"],"answer":0,"hint":"Check whether 4 multiplies both terms.","solution":"The distributive property needs 4 · x and 4 · (−3). The right answer is 4x − 12."}]},{"id":"real-numbers-4","teach":[{"title":"Mixing it together","text":["Many problems combine ideas. Simplify any roots or fractions first, then name the set or the property.","A number can belong to several sets at once. Every integer is rational, and every rational number is real."],"example":{"problem":"Which sets contain 0?","steps":["0 is not natural, since natural numbers start at 1.","0 is a whole number, an integer, a rational number (0/1), and a real number."]}}],"questions":[{"id":"u1-real4-q1","type":"choice","prompt":"Which number is rational?","choices":["π","−√36","√20","√0.5"],"answer":1,"hint":"Simplify the root before deciding.","solution":"−√36 = −6, an integer, so it is rational. π, √20, and √0.5 never end or repeat."},{"id":"u1-real4-q2","type":"input","prompt":"How many of these numbers are NOT integers? 0, −2, 5/3, √5, 1.25","answers":["3"],"hint":"Check each number for a fraction or decimal part.","solution":"0 and −2 are integers. 5/3, √5, and 1.25 are not. That is 3."},{"id":"u1-real4-q3","type":"choice","prompt":"A number is real and rational but not an integer. Which could it be?","choices":["−5","√3","7/2","0"],"answer":2,"hint":"It must be a fraction that does not simplify to a whole number.","solution":"−5 and 0 are integers. √3 is irrational. 7/2 is rational but not an integer."},{"id":"u1-real4-q4","type":"choice","prompt":"Which statement is false?","choices":["Every whole number is an integer","Every natural number is a rational number","Every rational number is a real number","Every integer is a whole number"],"answer":3,"hint":"Try −2.","solution":"−2 is an integer but not a whole number, so the last statement, every integer is a whole number, is false. The others are true."},{"id":"u1-real4-q5","type":"choice","prompt":"Which equation does NOT use the commutative property?","choices":["2(x + 1) = 2x + 2","3 · x = x · 3","4 + y = y + 4","ab = ba"],"answer":0,"hint":"Commutative means the order swaps.","solution":"Only 2(x + 1) = 2x + 2 spreads a factor over a sum. That is the distributive property."},{"id":"u1-real4-q6","type":"choice","prompt":"12 + (−12) = 0 and (1/3) · 3 = 1 show which pair of properties?","choices":["Additive identity and multiplicative identity","Additive inverse and multiplicative inverse","Commutative and associative","Distributive and identity"],"answer":1,"hint":"Each pair of numbers combines to give an identity.","solution":"Opposites add to 0: additive inverse. Reciprocals multiply to 1: multiplicative inverse."},{"id":"u1-real4-q7","type":"input","prompt":"Compute 8 · 53 as 8(50 + 3).","answers":["424"],"hint":"Distribute the 8 over 50 and 3.","solution":"8 · 50 + 8 · 3 = 400 + 24 = 424."},{"id":"u1-real4-q8","type":"choice","prompt":"The number 0 belongs to which sets?","choices":["Natural and whole only","Whole and integer only","Whole, integer, rational, and real","Whole, integer, and irrational"],"answer":2,"hint":"Natural numbers start at 1.","solution":"0 is not natural. It is a whole number, an integer, a rational number (0/1), and a real number."}]}]},{"id":"order-of-operations","title":"Order of operations and evaluating","lessons":[{"id":"order-of-operations-1","teach":[{"title":"Order of operations","text":["Do operations in this order: grouping symbols, exponents, multiplication and division (left to right), then addition and subtraction (left to right).","Multiplication and division share a level, and so do addition and subtraction. Go left to right."],"example":{"problem":"Evaluate 3 + 4 · 5","steps":["Multiply before adding: 4 · 5 = 20.","3 + 20 = 23."]}}],"questions":[{"id":"u1-order1-q1","type":"input","prompt":"Evaluate: 3 + 4 · 5","answers":["23"],"hint":"Multiply before you add.","solution":"4 · 5 = 20. Then 3 + 20 = 23.","calculator":false},{"id":"u1-order1-q2","type":"input","prompt":"Evaluate: 18 − 12 ÷ 3","answers":["14"],"hint":"Divide before you subtract.","solution":"12 ÷ 3 = 4. Then 18 − 4 = 14.","calculator":false},{"id":"u1-order1-q3","type":"choice","prompt":"What is the first step in evaluating 2 + 3(4 − 1)²?","choices":["Add 2 + 3","Multiply 3 by 4","Subtract inside the parentheses: 4 − 1","Square the 4"],"answer":2,"hint":"Grouping symbols come first.","solution":"Parentheses come first, so do 4 − 1 = 3. Then the exponent, then multiply, then add."},{"id":"u1-order1-q4","type":"input","prompt":"Evaluate: 20 − 2(3 + 1)","answers":["12"],"hint":"Do the parentheses, then multiply.","solution":"3 + 1 = 4. Then 2 · 4 = 8. Then 20 − 8 = 12.","calculator":false},{"id":"u1-order1-q5","type":"input","prompt":"Evaluate: 5² − 3 · 4","answers":["13"],"hint":"Exponent first, then multiply.","solution":"5² = 25. 3 · 4 = 12. 25 − 12 = 13.","calculator":false},{"id":"u1-order1-q6","type":"choice","prompt":"What is the value of −3²?","choices":["−9","9","6","−6"],"answer":0,"hint":"The exponent applies only to the 3, not to the negative sign.","solution":"−3² means −(3 · 3) = −9. Only (−3)² equals 9."},{"id":"u1-order1-q7","type":"input","prompt":"Evaluate: 2³ + 4 · 3 − 5","answers":["15"],"hint":"Exponent, then multiplication, then add and subtract left to right.","solution":"2³ = 8 and 4 · 3 = 12. 8 + 12 − 5 = 15.","calculator":false},{"id":"u1-order1-q8","type":"choice","prompt":"Evaluate: 24 ÷ 4 · 3","choices":["2","18","8","72"],"answer":1,"hint":"Multiplication and division go left to right.","solution":"24 ÷ 4 = 6. Then 6 · 3 = 18."}]},{"id":"order-of-operations-2","teach":[{"title":"Negatives and absolute value","text":["Treat (−3)² as −3 times −3 = 9. But −3² = −(3²) = −9.","Absolute value bars work like parentheses. Simplify inside first, then take the absolute value.","A fraction bar also groups. Work out the top and bottom separately, then divide."],"example":{"problem":"Evaluate (6 + 2) / (5 − 1) + |3 − 7|","steps":["Top: 6 + 2 = 8. Bottom: 5 − 1 = 4. So 8/4 = 2.","Absolute value: |3 − 7| = |−4| = 4.","2 + 4 = 6."]}}],"questions":[{"id":"u1-order2-q1","type":"input","prompt":"Evaluate: −4 + 6(−2)","answers":["-16"],"hint":"Multiply first.","solution":"6(−2) = −12. Then −4 + (−12) = −16.","calculator":false},{"id":"u1-order2-q2","type":"input","prompt":"Evaluate: (−3)² − 2 · 5","answers":["-1"],"hint":"(−3)² means −3 times −3.","solution":"(−3)² = 9. 2 · 5 = 10. 9 − 10 = −1.","calculator":false},{"id":"u1-order2-q3","type":"input","prompt":"Evaluate: |−8| − |5 − 9|","answers":["4"],"hint":"Simplify inside the second bars first.","solution":"|−8| = 8. |5 − 9| = |−4| = 4. 8 − 4 = 4.","calculator":false},{"id":"u1-order2-q4","type":"input","prompt":"Evaluate: (10 + 2) / (7 − 4)","answers":["4"],"hint":"The fraction bar groups the top and the bottom.","solution":"Top: 10 + 2 = 12. Bottom: 7 − 4 = 3. 12/3 = 4.","calculator":false},{"id":"u1-order2-q5","type":"input","prompt":"Evaluate: (−2)³ + 3(−4)","answers":["-20"],"hint":"(−2)³ = (−2)(−2)(−2).","solution":"(−2)³ = −8. 3(−4) = −12. −8 + (−12) = −20.","calculator":false},{"id":"u1-order2-q6","type":"choice","prompt":"Evaluate: (8 − 2 · 5) / (−1 − 1)","choices":["−1","17","1","−3"],"answer":2,"hint":"Work out the top and bottom separately.","solution":"Top: 8 − 10 = −2. Bottom: −1 − 1 = −2. −2 ÷ −2 = 1."},{"id":"u1-order2-q7","type":"input","prompt":"Evaluate: 5 − |2 − 9| · 3","answers":["-16"],"hint":"Simplify inside the bars, then multiply.","solution":"|2 − 9| = |−7| = 7. 7 · 3 = 21. 5 − 21 = −16.","calculator":false},{"id":"u1-order2-q8","type":"choice","prompt":"Which expression equals 25?","choices":["−5²","−(5²)","−5 · 5","(−5)²"],"answer":3,"hint":"Which one squares the negative sign too?","solution":"(−5)² = 25. The others all equal −25."},{"id":"u1-order2-q9","type":"input","prompt":"Evaluate: 6 − 2(3 − 8)² ÷ 5","answers":["-4"],"hint":"Parentheses, then the exponent, then multiply and divide left to right.","solution":"3 − 8 = −5. (−5)² = 25. 2 · 25 = 50. 50 ÷ 5 = 10. 6 − 10 = −4.","calculator":false}]},{"id":"order-of-operations-3","teach":[{"title":"Evaluating an expression","text":["To evaluate, replace each variable with its value. Put the value in parentheses, especially if it is negative. Then follow the order of operations."],"example":{"problem":"Evaluate x² − 2x when x = −3","steps":["Substitute with parentheses: (−3)² − 2(−3).","(−3)² = 9 and −2(−3) = 6.","9 + 6 = 15."]}}],"questions":[{"id":"u1-order3-q1","type":"input","prompt":"Evaluate 3x + 5 when x = 4.","answers":["17"],"hint":"Replace x with 4.","solution":"3(4) + 5 = 12 + 5 = 17."},{"id":"u1-order3-q2","type":"input","prompt":"Evaluate x² − 2x when x = −3.","answers":["15"],"hint":"Use parentheses around −3.","solution":"(−3)² − 2(−3) = 9 + 6 = 15."},{"id":"u1-order3-q3","type":"choice","prompt":"Evaluate −x² when x = 5.","choices":["25","−25","−10","10"],"answer":1,"hint":"Square first, then apply the negative sign.","solution":"x² = 25. Then −25."},{"id":"u1-order3-q4","type":"input","prompt":"Evaluate 2a − 3b when a = −4 and b = 5.","answers":["-23"],"hint":"Replace a and b with parentheses.","solution":"2(−4) − 3(5) = −8 − 15 = −23."},{"id":"u1-order3-q5","type":"input","prompt":"Evaluate (x + y)/(x − y) when x = 7 and y = 3.","answers":["5/2","2.5"],"hint":"The fraction bar groups top and bottom.","solution":"Top: 7 + 3 = 10. Bottom: 7 − 3 = 4. 10/4 = 5/2."},{"id":"u1-order3-q6","type":"choice","prompt":"Evaluate |m − n| when m = −2 and n = 6.","choices":["8","−8","4","−4"],"answer":0,"hint":"Subtract inside first, then take the absolute value.","solution":"m − n = −2 − 6 = −8. |−8| = 8."},{"id":"u1-order3-q7","type":"input","prompt":"Evaluate 2x² + 3x − 1 when x = −2.","answers":["1"],"hint":"Square first: (−2)² = 4.","solution":"2(4) + 3(−2) − 1 = 8 − 6 − 1 = 1."},{"id":"u1-order3-q8","type":"choice","prompt":"Evaluate (−a)² − a² when a = 3.","choices":["18","−18","9","0"],"answer":3,"hint":"Find each part separately.","solution":"(−3)² = 9 and a² = 9. 9 − 9 = 0."},{"id":"u1-order3-q9","type":"input","prompt":"Convert to Fahrenheit with F = (9/5)C + 32 when C = −10.","answers":["14"],"hint":"Multiply (9/5) by −10 first.","solution":"(9/5)(−10) = −18. −18 + 32 = 14."}]},{"id":"order-of-operations-4","teach":[{"title":"Nested grouping and mixed practice","text":["With brackets inside brackets, work from the innermost pair outward.","Then substitute carefully and keep a clear order for every step."],"example":{"problem":"Evaluate 4 − 3[2 − (5 − 8)]","steps":["Innermost: 5 − 8 = −3.","Next: 2 − (−3) = 5.","Then 3 · 5 = 15 and 4 − 15 = −11."]}}],"questions":[{"id":"u1-order4-q1","type":"input","prompt":"Evaluate: 4 − 3[2 − (5 − 8)]","answers":["-11"],"hint":"Start with the innermost parentheses.","solution":"5 − 8 = −3. 2 − (−3) = 5. 3 · 5 = 15. 4 − 15 = −11.","calculator":false},{"id":"u1-order4-q2","type":"input","prompt":"Evaluate (3x − y²)/(2 − x) when x = 5 and y = −4.","answers":["1/3"],"hint":"Square y first: (−4)² = 16.","solution":"Top: 3(5) − (−4)² = 15 − 16 = −1. Bottom: 2 − 5 = −3. −1/−3 = 1/3."},{"id":"u1-order4-q3","type":"choice","prompt":"Evaluate |2x − 3y| − x² when x = −2 and y = −1.","choices":["5","−3","3","−5"],"answer":1,"hint":"Work out the absolute value and the x² separately.","solution":"2x − 3y = −4 + 3 = −1, so |−1| = 1. x² = 4. 1 − 4 = −3."},{"id":"u1-order4-q4","type":"input","prompt":"Evaluate 3(x − 2)² − 4x when x = 5.","answers":["7"],"hint":"Parentheses, exponent, multiply, subtract.","solution":"(5 − 2)² = 9. 3 · 9 = 27. 4 · 5 = 20. 27 − 20 = 7."},{"id":"u1-order4-q5","type":"choice","prompt":"A student evaluates −3² + 4 and gets 13. What was the mistake?","choices":["Treated −3² as (−3)²","Added before squaring","Forgot to add 4","Multiplied 3 by 2"],"answer":0,"hint":"What does the exponent apply to?","solution":"−3² = −9, so the answer is −9 + 4 = −5. The student used 9 instead of −9."},{"id":"u1-order4-q6","type":"input","prompt":"Area of a trapezoid: A = (1/2)h(b₁ + b₂). Find A when h = 6, b₁ = 5, and b₂ = 9.","answers":["42"],"hint":"Add the bases first.","solution":"b₁ + b₂ = 14. (1/2)(6)(14) = 3 · 14 = 42."},{"id":"u1-order4-q7","type":"input","prompt":"Evaluate x² − 4xy + y² when x = 2 and y = −3.","answers":["37"],"hint":"Be careful with −4xy.","solution":"4 − 4(2)(−3) + 9 = 4 + 24 + 9 = 37."},{"id":"u1-order4-q8","type":"choice","prompt":"Evaluate x² + 3x + 2 when x = −2.","choices":["−8","12","0","4"],"answer":2,"hint":"Square first: (−2)² = 4.","solution":"4 + 3(−2) + 2 = 4 − 6 + 2 = 0."}]}]},{"id":"simplifying","title":"Simplifying expressions","lessons":[{"id":"simplifying-1","teach":[{"title":"Like terms","text":["Terms are like terms when they have the same variable part with the same exponent. 5y and −2y are like. 3x and 3x² are not.","Combine like terms by adding their coefficients. The variable part stays the same."],"example":{"problem":"Simplify 7a − 2 − 3a + 6","steps":["Group the a terms: 7a − 3a = 4a.","Group the constants: −2 + 6 = 4.","The answer is 4a + 4."]}}],"questions":[{"id":"u1-simp1-q1","type":"choice","prompt":"Which pair are like terms?","choices":["3x and 3x²","5y and −2y","4x and 4y","7 and 7x"],"answer":1,"hint":"Both the variable and the exponent must match.","solution":"5y and −2y both have y to the first power. The other pairs differ in variable or exponent."},{"id":"u1-simp1-q2","type":"input","prompt":"In 4x² − 7x + 9, what is the coefficient of x?","answers":["-7"],"hint":"The coefficient is the number multiplying the variable, including its sign.","solution":"The term with x is −7x, so the coefficient is −7."},{"id":"u1-simp1-q3","type":"choice","prompt":"Simplify 5x + 3x.","choices":["8x","8x²","15x","15x²"],"answer":0,"hint":"Add the coefficients. Do the exponents change?","solution":"5 + 3 = 8 and the variable part stays x. So 8x."},{"id":"u1-simp1-q4","type":"choice","prompt":"Simplify 7a − 2 − 3a + 6.","choices":["4a − 4","10a + 4","4a + 4","4a + 8"],"answer":2,"hint":"Combine the a terms, then the constants.","solution":"7a − 3a = 4a. −2 + 6 = 4. So 4a + 4."},{"id":"u1-simp1-q5","type":"choice","prompt":"Simplify 2x² + 3x + x².","choices":["6x²","3x² + 3x","3x³ + 3x","5x² + x"],"answer":1,"hint":"x² and x are not like terms.","solution":"2x² + x² = 3x². The 3x has a different exponent, so it stays. 3x² + 3x."},{"id":"u1-simp1-q6","type":"input","prompt":"After simplifying 9x − 4x + 2x, what is the coefficient of x?","answers":["7"],"hint":"Add 9 − 4 + 2.","solution":"9 − 4 + 2 = 7, so the result is 7x."},{"id":"u1-simp1-q7","type":"input","prompt":"Simplify 8n + 5 − 3n − 5. The answer is kn. What is k?","answers":["5"],"hint":"Do the constants cancel?","solution":"8n − 3n = 5n and 5 − 5 = 0. So 5n, and k = 5."},{"id":"u1-simp1-q8","type":"choice","prompt":"Simplify 3m + 2n − m + 5n.","choices":["2m + 3n","4m + 7n","9mn","2m + 7n"],"answer":3,"hint":"Combine m terms with m terms and n terms with n terms.","solution":"3m − m = 2m. 2n + 5n = 7n. So 2m + 7n."}]},{"id":"simplifying-2","teach":[{"title":"The distributive property","text":["a(b + c) = ab + ac. Multiply the outside number by every term inside the parentheses.","Watch signs. A negative outside number flips the sign of every term inside."],"example":{"problem":"Expand −2(x − 4)","steps":["−2 · x = −2x.","−2 · (−4) = +8.","So −2(x − 4) = −2x + 8."]}}],"questions":[{"id":"u1-simp2-q1","type":"choice","prompt":"Expand 3(x + 5).","choices":["3x + 5","x + 15","3x + 8","3x + 15"],"answer":3,"hint":"Multiply 3 by both terms.","solution":"3 · x = 3x and 3 · 5 = 15. So 3x + 15."},{"id":"u1-simp2-q2","type":"choice","prompt":"Expand −2(x − 4).","choices":["−2x − 8","−2x + 8","−2x + 4","2x − 8"],"answer":1,"hint":"A negative times a negative is positive.","solution":"−2 · x = −2x and −2 · (−4) = 8. So −2x + 8."},{"id":"u1-simp2-q3","type":"input","prompt":"Expand −4(3x + 2) to get ax + b. What is a + b?","answers":["-20"],"hint":"Distribute −4 to both terms.","solution":"−4(3x + 2) = −12x − 8. So a = −12 and b = −8, and a + b = −20."},{"id":"u1-simp2-q4","type":"choice","prompt":"Expand (1/2)(8x − 6).","choices":["4x − 6","8x − 3","4x − 3","4x + 3"],"answer":2,"hint":"Half of 8x and half of 6.","solution":"(1/2)(8x) = 4x and (1/2)(−6) = −3. So 4x − 3."},{"id":"u1-simp2-q5","type":"choice","prompt":"Simplify 4(x + 2) + 3(x − 1).","choices":["7x + 11","7x + 5","7x + 7","x + 5"],"answer":1,"hint":"Expand both groups, then combine.","solution":"4x + 8 + 3x − 3 = 7x + 5."},{"id":"u1-simp2-q6","type":"input","prompt":"2(3x + 1) + 5x simplifies to kx + 2. What is k?","answers":["11"],"hint":"Expand first: 6x + 2 + 5x.","solution":"2(3x + 1) = 6x + 2. Then 6x + 5x = 11x. So 11x + 2 and k = 11."},{"id":"u1-simp2-q7","type":"choice","prompt":"Expand −(x − 7).","choices":["−x − 7","x − 7","−x + 1","−x + 7"],"answer":3,"hint":"The minus sign in front means multiply by −1.","solution":"−1 · x = −x and −1 · (−7) = 7. So −x + 7."},{"id":"u1-simp2-q8","type":"choice","prompt":"Simplify 3(2x − 5) − 4x.","choices":["2x − 5","10x − 15","2x − 15","2x + 15"],"answer":2,"hint":"Expand, then combine the x terms.","solution":"6x − 15 − 4x = 2x − 15."},{"id":"u1-simp2-q9","type":"input","prompt":"Simplify 7(a + 2) − 7a. What number do you get?","answers":["14"],"hint":"Expand and look at the a terms.","solution":"7a + 14 − 7a = 14."}]},{"id":"simplifying-3","teach":[{"title":"Subtracting a group","text":["A minus sign in front of parentheses means multiply the group by −1. Every sign inside flips.","So (a + b) − (c − d) = a + b − c + d."],"example":{"problem":"Simplify (5x + 4) − (2x − 3)","steps":["Distribute the minus: 5x + 4 − 2x + 3.","Combine: 5x − 2x = 3x and 4 + 3 = 7.","The answer is 3x + 7."]}}],"questions":[{"id":"u1-simp3-q1","type":"choice","prompt":"Simplify 8x − (3x + 2).","choices":["5x + 2","5x − 2","11x − 2","5x − 6"],"answer":1,"hint":"The minus sign applies to both terms in the group.","solution":"8x − 3x − 2 = 5x − 2."},{"id":"u1-simp3-q2","type":"choice","prompt":"Simplify (5x + 4) − (2x − 3).","choices":["3x + 1","3x + 7","3x − 7","7x + 7"],"answer":1,"hint":"Subtracting −3 adds 3.","solution":"5x + 4 − 2x + 3 = 3x + 7."},{"id":"u1-simp3-q3","type":"input","prompt":"(9x − 1) − (4x + 6) simplifies to kx − 7. What is k?","answers":["5"],"hint":"Subtract both terms of the second group.","solution":"9x − 1 − 4x − 6 = 5x − 7. So k = 5."},{"id":"u1-simp3-q4","type":"choice","prompt":"Simplify 4 − (x − 6).","choices":["−2 − x","x − 2","10 − x","−x − 2"],"answer":2,"hint":"The −6 inside becomes +6.","solution":"4 − x + 6 = 10 − x."},{"id":"u1-simp3-q5","type":"choice","prompt":"A student simplifies (7x + 5) − (3x − 2) and gets 4x + 3. What was the mistake?","choices":["The minus was not applied to the −2","The x terms were added instead of subtracted","The 5 and 2 should be multiplied","Nothing, it is correct"],"answer":0,"hint":"Redo it carefully and compare the constants.","solution":"The correct work is 7x + 5 − 3x + 2 = 4x + 7. The student left −2 as −2 instead of +2."},{"id":"u1-simp3-q6","type":"input","prompt":"3(x + 4) − 2(x − 5) simplifies to x + c. What is c?","answers":["22"],"hint":"Expand both products. Then subtract.","solution":"3x + 12 − 2x + 10 = x + 22. So c = 22."},{"id":"u1-simp3-q7","type":"choice","prompt":"Simplify 2(3x − 1) − (x − 4).","choices":["5x − 6","7x + 2","5x − 2","5x + 2"],"answer":3,"hint":"Expand 2(3x − 1) first, then subtract the group.","solution":"6x − 2 − x + 4 = 5x + 2."},{"id":"u1-simp3-q8","type":"choice","prompt":"Simplify −(2x − 3) − (x + 5).","choices":["−3x + 8","−3x − 2","−x − 2","−3x − 8"],"answer":1,"hint":"Distribute each minus separately.","solution":"−2x + 3 − x − 5 = −3x − 2."},{"id":"u1-simp3-q9","type":"input","prompt":"Subtract (x² + 2x) from (3x² − x). The result is ax² + bx. What is a + b?","answers":["-1"],"hint":"Write it as (3x² − x) − (x² + 2x).","solution":"3x² − x − x² − 2x = 2x² − 3x. So a = 2 and b = −3, and a + b = −1."}]},{"id":"simplifying-4","teach":[{"title":"Perimeter expressions","text":["Perimeter is the sum of all the side lengths. Write the sides as expressions, add them, and combine like terms.","A rectangle with length L and width W has perimeter 2L + 2W."],"example":{"problem":"A triangle has sides x + 4, 2x − 1, and 3x + 2. Find the perimeter.","steps":["Add the three sides: (x + 4) + (2x − 1) + (3x + 2).","x terms: x + 2x + 3x = 6x. Constants: 4 − 1 + 2 = 5.","Perimeter = 6x + 5."]}}],"questions":[{"id":"u1-simp4-q1","type":"choice","prompt":"A rectangle has length 2x + 3 and width x − 1. What is its perimeter?","choices":["3x + 2","6x + 4","6x + 2","4x + 2"],"answer":1,"hint":"Use P = 2L + 2W.","solution":"2(2x + 3) + 2(x − 1) = 4x + 6 + 2x − 2 = 6x + 4."},{"id":"u1-simp4-q2","type":"choice","prompt":"A triangle has sides x + 4, 2x − 1, and 3x + 2. What is its perimeter?","choices":["6x + 7","5x + 5","6x + 5","6x − 5"],"answer":2,"hint":"Add all three sides.","solution":"x + 2x + 3x = 6x and 4 − 1 + 2 = 5. So 6x + 5."},{"id":"u1-simp4-q3","type":"input","prompt":"A square has side 3x − 2. Find its perimeter when x = 5.","answers":["52"],"hint":"The perimeter is 4 times the side.","solution":"Perimeter = 4(3x − 2) = 12x − 8. When x = 5, that is 60 − 8 = 52."},{"id":"u1-simp4-q4","type":"choice","prompt":"A rectangle has width x + 2 and perimeter 8x + 4. What is its length?","choices":["7x + 2","3x + 4","6x","3x"],"answer":3,"hint":"Half the perimeter is length plus width.","solution":"Half of 8x + 4 is 4x + 2. Length = 4x + 2 − (x + 2) = 3x."},{"id":"u1-simp4-q5","type":"choice","prompt":"Simplify 2(x + 3) − 4(x − 1) + 3x.","choices":["x + 2","9x + 10","x − 10","x + 10"],"answer":3,"hint":"Expand both groups, then combine.","solution":"2x + 6 − 4x + 4 + 3x = x + 10."},{"id":"u1-simp4-q6","type":"input","prompt":"5 − 2(x − 3) + 3x simplifies to x + c. What is c?","answers":["11"],"hint":"Expand −2(x − 3) carefully.","solution":"5 − 2x + 6 + 3x = x + 11. So c = 11."},{"id":"u1-simp4-q7","type":"choice","prompt":"Simplify −3(2a − b) + 4(a + 2b).","choices":["−2a + 5b","−2a + 11b","−2a − 5b","10a + 11b"],"answer":1,"hint":"Watch the sign on −3 · (−b).","solution":"−6a + 3b + 4a + 8b = −2a + 11b."},{"id":"u1-simp4-q8","type":"input","prompt":"Simplify 4(x + 3) − 2(3x − 1), then evaluate when x = −1.","answers":["16"],"hint":"Simplify first, then substitute.","solution":"4x + 12 − 6x + 2 = −2x + 14. At x = −1: 2 + 14 = 16."}]}]},{"id":"multi-step","title":"Solving multi-step equations","lessons":[{"id":"multi-step-1","teach":[{"title":"Undo operations in reverse","text":["To solve an equation, get the variable alone. Undo operations with their opposites, doing the same thing to both sides.","If there are parentheses, distribute first. Then combine like terms, then undo adding or subtracting, then undo multiplying or dividing."],"example":{"problem":"Solve 4(x − 1) + 2 = 22","steps":["Distribute: 4x − 4 + 2 = 22, so 4x − 2 = 22.","Add 2: 4x = 24.","Divide by 4: x = 6."]}}],"questions":[{"id":"u1-multi1-q1","type":"input","prompt":"Solve: 3x + 7 = 25","answers":["6"],"hint":"Subtract 7 from both sides first.","solution":"3x = 18, so x = 6."},{"id":"u1-multi1-q2","type":"input","prompt":"Solve: 5x − 9 = 16","answers":["5"],"hint":"Add 9 to both sides.","solution":"5x = 25, so x = 5."},{"id":"u1-multi1-q3","type":"input","prompt":"Solve: 2(x + 4) = 18","answers":["5"],"hint":"Distribute the 2 first, or divide both sides by 2.","solution":"2x + 8 = 18, so 2x = 10 and x = 5."},{"id":"u1-multi1-q4","type":"choice","prompt":"What is a correct first step for solving 3x + 5 = 20?","choices":["Divide both sides by 5","Add 5 to both sides","Subtract 5 from both sides","Subtract 3 from both sides"],"answer":2,"hint":"Undo the addition first.","solution":"The 5 is added to 3x. Subtract 5 from both sides to get 3x = 15."},{"id":"u1-multi1-q5","type":"input","prompt":"Solve: 7x − 3 + 2x = 24","answers":["3"],"hint":"Combine the x terms first.","solution":"9x − 3 = 24, so 9x = 27 and x = 3."},{"id":"u1-multi1-q6","type":"input","prompt":"Solve: −3x + 4 = 19","answers":["-5"],"hint":"Subtract 4, then divide by −3.","solution":"−3x = 15, so x = −5."},{"id":"u1-multi1-q7","type":"input","prompt":"Solve: 4(x − 1) + 2 = 22","answers":["6"],"hint":"Distribute, combine, then undo.","solution":"4x − 4 + 2 = 22, so 4x − 2 = 22, 4x = 24, x = 6."},{"id":"u1-multi1-q8","type":"choice","prompt":"Which value solves 2x − 6 = 10?","choices":["x = 8","x = 2","x = 4","x = −8"],"answer":0,"hint":"Solve, or test each answer.","solution":"2x = 16, so x = 8. Check: 2(8) − 6 = 10."}]},{"id":"multi-step-2","teach":[{"title":"Variables on both sides","text":["Move the variable terms to one side by adding or subtracting. Then solve as usual.","Pick the side that keeps the coefficient positive if you can. It avoids sign errors."],"example":{"problem":"Solve 5x + 3 = 3x + 11","steps":["Subtract 3x from both sides: 2x + 3 = 11.","Subtract 3: 2x = 8.","Divide by 2: x = 4."]}}],"questions":[{"id":"u1-multi2-q1","type":"input","prompt":"Solve: 5x + 3 = 3x + 11","answers":["4"],"hint":"Subtract 3x from both sides.","solution":"2x + 3 = 11, so 2x = 8 and x = 4."},{"id":"u1-multi2-q2","type":"input","prompt":"Solve: 7x − 4 = 2x + 21","answers":["5"],"hint":"Get the x terms on one side.","solution":"5x − 4 = 21, so 5x = 25 and x = 5."},{"id":"u1-multi2-q3","type":"input","prompt":"Solve: 8 − 3x = 2x − 12","answers":["4"],"hint":"Add 3x to both sides.","solution":"8 = 5x − 12, so 20 = 5x and x = 4."},{"id":"u1-multi2-q4","type":"input","prompt":"Solve: 3(x + 2) = 2x + 9","answers":["3"],"hint":"Distribute the 3 first.","solution":"3x + 6 = 2x + 9, so x + 6 = 9 and x = 3."},{"id":"u1-multi2-q5","type":"choice","prompt":"Solve: 4x − 7 = 6x + 5","choices":["x = 6","x = −1","x = 1","x = −6"],"answer":3,"hint":"Subtract 6x, then add 7.","solution":"−2x − 7 = 5, so −2x = 12 and x = −6."},{"id":"u1-multi2-q6","type":"input","prompt":"Solve: 2(3x − 1) = 5(x + 1)","answers":["7"],"hint":"Distribute on both sides.","solution":"6x − 2 = 5x + 5, so x − 2 = 5 and x = 7."},{"id":"u1-multi2-q7","type":"input","prompt":"Solve: 6x − 2(x + 3) = x + 9","answers":["5"],"hint":"Distribute −2 across the group.","solution":"6x − 2x − 6 = x + 9, so 4x − 6 = x + 9, 3x = 15, x = 5."},{"id":"u1-multi2-q8","type":"choice","prompt":"Solve: 9 − 2(x − 1) = 3x − 4","choices":["x = 1","x = −3","x = 3","x = 15"],"answer":2,"hint":"Distribute −2 carefully: −2 · −1 = +2.","solution":"9 − 2x + 2 = 3x − 4, so 11 − 2x = 3x − 4. Then 15 = 5x and x = 3."}]},{"id":"multi-step-3","teach":[{"title":"Clearing fractions and decimals","text":["To clear fractions, multiply every term by the common denominator. To clear decimals, multiply every term by a power of 10.","Multiply every term, not just one side of the first term."],"example":{"problem":"Solve x/2 + x/3 = 10","steps":["The common denominator is 6. Multiply every term by 6: 3x + 2x = 60.","5x = 60.","x = 12."]}}],"questions":[{"id":"u1-multi3-q1","type":"input","prompt":"Solve: x/3 + 2 = 6","answers":["12"],"hint":"Subtract 2, then multiply by 3.","solution":"x/3 = 4, so x = 12."},{"id":"u1-multi3-q2","type":"input","prompt":"Solve: (2/3)x = 10","answers":["15"],"hint":"Multiply by the reciprocal, 3/2.","solution":"x = 10 · (3/2) = 15."},{"id":"u1-multi3-q3","type":"input","prompt":"Solve: x/2 + x/3 = 10","answers":["12"],"hint":"Multiply every term by 6.","solution":"3x + 2x = 60, so 5x = 60 and x = 12."},{"id":"u1-multi3-q4","type":"input","prompt":"Solve: 0.5x + 1.2 = 3.7","answers":["5"],"hint":"Subtract 1.2 first.","solution":"0.5x = 2.5, so x = 5."},{"id":"u1-multi3-q5","type":"choice","prompt":"What is the smallest power of 10 that clears all decimals in 0.3x + 1.25 = 4.1?","choices":["10","100","1000","3"],"answer":1,"hint":"1.25 has two decimal places.","solution":"1.25 needs two places, so multiply by 100: 30x + 125 = 410."},{"id":"u1-multi3-q6","type":"input","prompt":"Solve: (x − 1)/4 = (x + 2)/3","answers":["-11"],"hint":"Cross-multiply or multiply by 12.","solution":"3(x − 1) = 4(x + 2), so 3x − 3 = 4x + 8 and x = −11."},{"id":"u1-multi3-q7","type":"input","prompt":"Solve: 0.4x − 0.1 = 0.3x + 0.6","answers":["7"],"hint":"Subtract 0.3x from both sides.","solution":"0.1x − 0.1 = 0.6, so 0.1x = 0.7 and x = 7."},{"id":"u1-multi3-q8","type":"choice","prompt":"Solve: 3x/4 − 1/2 = 5/2","choices":["x = 11/3","x = 3","x = −4","x = 4"],"answer":3,"hint":"Multiply every term by 4, including the 1/2.","solution":"3x − 2 = 10, so 3x = 12 and x = 4."}]},{"id":"multi-step-4","teach":[{"title":"No solution and all real numbers","text":["If the variables cancel and the result is false, like 3 = 8, there is no solution.","If the variables cancel and the result is true, like 7 = 7, every real number is a solution.","If a variable stays, you get one solution."],"example":{"problem":"Solve 2(x + 3) = 2x + 6","steps":["Distribute: 2x + 6 = 2x + 6.","Subtract 2x: 6 = 6.","This is always true, so all real numbers are solutions."]}}],"questions":[{"id":"u1-multi4-q1","type":"choice","prompt":"Solve: 2(x + 3) = 2x + 6","choices":["x = 0","No solution","All real numbers","x = 6"],"answer":2,"hint":"Distribute, then see what is left after you subtract 2x.","solution":"2x + 6 = 2x + 6 gives 6 = 6, always true. All real numbers."},{"id":"u1-multi4-q2","type":"choice","prompt":"Solve: 3x + 4 = 3x − 1","choices":["x = 0","No solution","All real numbers","x = 5"],"answer":1,"hint":"Subtract 3x from both sides.","solution":"4 = −1 is false, so there is no solution."},{"id":"u1-multi4-q3","type":"input","prompt":"Solve: 3(2x − 1) − 2(x + 4) = 21","answers":["8"],"hint":"Expand both products, then combine.","solution":"6x − 3 − 2x − 8 = 21, so 4x − 11 = 21, 4x = 32, x = 8."},{"id":"u1-multi4-q4","type":"choice","prompt":"Solve: 5x − 3 = 5(x + 1)","choices":["All real numbers","x = −3","No solution","x = 1"],"answer":2,"hint":"Distribute on the right.","solution":"5x − 3 = 5x + 5. Subtract 5x: −3 = 5, which is false. No solution."},{"id":"u1-multi4-q5","type":"choice","prompt":"Solve: 4(x + 1) = 2(2x + 3) − 2","choices":["x = 0","No solution","x = 4","All real numbers"],"answer":3,"hint":"Simplify each side.","solution":"Left: 4x + 4. Right: 4x + 6 − 2 = 4x + 4. Both sides match, so all real numbers."},{"id":"u1-multi4-q6","type":"input","prompt":"Solve: x/2 − (x − 1)/3 = 2","answers":["10"],"hint":"Multiply every term by 6.","solution":"3x − 2(x − 1) = 12, so 3x − 2x + 2 = 12, x = 10."},{"id":"u1-multi4-q7","type":"choice","prompt":"While solving, you reach 7 = 7. What does this mean?","choices":["x = 7","All real numbers are solutions","There is no solution","x = 0"],"answer":1,"hint":"The variable cancelled and the statement is true.","solution":"A true statement with no variable left means every real number works."},{"id":"u1-multi4-q8","type":"input","prompt":"Solve: 2(x − 5) + 3 = 4(x − 4) + 1","answers":["4"],"hint":"Simplify both sides first.","solution":"Left: 2x − 7. Right: 4x − 15. So 2x − 7 = 4x − 15, 8 = 2x, x = 4."}]}]},{"id":"literal","title":"Literal equations and formulas","lessons":[{"id":"literal-1","teach":[{"title":"Solving for a variable","text":["A literal equation has several letters. To solve for one, treat the others like numbers and undo operations in reverse, just as you would with numbers."],"example":{"problem":"Solve P = 2l + 2w for l.","steps":["Subtract 2w from both sides: P − 2w = 2l.","Divide by 2: l = (P − 2w)/2."]}}],"questions":[{"id":"u1-lit1-q1","type":"choice","prompt":"Solve A = bh for h.","choices":["h = A/b","h = Ab","h = A − b","h = b/A"],"answer":0,"hint":"h is multiplied by b. Undo with division.","solution":"Divide both sides by b: h = A/b."},{"id":"u1-lit1-q2","type":"choice","prompt":"Solve d = rt for t.","choices":["t = dr","t = d − r","t = d/r","t = r/d"],"answer":2,"hint":"Divide both sides by r.","solution":"t is multiplied by r. Divide by r: t = d/r."},{"id":"u1-lit1-q3","type":"choice","prompt":"Solve P = 2l + 2w for l.","choices":["l = P − 2w","l = P/2 + w","l = (P − 2w)/2","l = (P + 2w)/2"],"answer":2,"hint":"Subtract 2w, then divide by 2.","solution":"P − 2w = 2l, so l = (P − 2w)/2."},{"id":"u1-lit1-q4","type":"choice","prompt":"Solve y = mx + b for x.","choices":["x = y − b − m","x = (y + b)/m","x = m(y − b)","x = (y − b)/m"],"answer":3,"hint":"Subtract b first, then divide by m.","solution":"y − b = mx, so x = (y − b)/m."},{"id":"u1-lit1-q5","type":"input","prompt":"A = lw. If A = 48 and w = 6, what is l?","answers":["8"],"hint":"Solve for l first: l = A/w.","solution":"l = 48/6 = 8."},{"id":"u1-lit1-q6","type":"choice","prompt":"Solve C = 2πr for r.","choices":["r = 2πC","r = C/(2π)","r = C − 2π","r = C/π"],"answer":1,"hint":"r is multiplied by 2π.","solution":"Divide both sides by 2π: r = C/(2π)."},{"id":"u1-lit1-q7","type":"choice","prompt":"Solve I = Prt for P.","choices":["P = I − rt","P = Irt","P = I/(rt)","P = rt/I"],"answer":2,"hint":"P is multiplied by r and t.","solution":"Divide both sides by rt: P = I/(rt)."},{"id":"u1-lit1-q8","type":"input","prompt":"d = rt. If d = 150 and r = 50, what is t?","answers":["3"],"hint":"t = d/r.","solution":"t = 150/50 = 3."}]},{"id":"literal-2","teach":[{"title":"Multi-step literal equations","text":["Isolate the term with your variable, then undo what is attached to it. Move added or subtracted terms first. Then divide or multiply.","If you divide, divide every term on the other side."],"example":{"problem":"Solve 2x − 5y = 10 for y.","steps":["Subtract 2x: −5y = 10 − 2x.","Divide by −5: y = (10 − 2x)/(−5) = (2x − 10)/5.","So y = (2/5)x − 2."]}}],"questions":[{"id":"u1-lit2-q1","type":"choice","prompt":"Solve 3x + y = 12 for y.","choices":["y = 12 + 3x","y = 12 − 3x","y = 4x","y = 3x − 12"],"answer":1,"hint":"Subtract 3x from both sides.","solution":"y = 12 − 3x."},{"id":"u1-lit2-q2","type":"choice","prompt":"Solve 2x − 5y = 10 for y.","choices":["y = (2/5)x − 2","y = (2/5)x + 2","y = −(2/5)x − 2","y = 2x − 10"],"answer":0,"hint":"Divide every term by −5.","solution":"−5y = 10 − 2x. Divide by −5: y = −2 + (2/5)x = (2/5)x − 2."},{"id":"u1-lit2-q3","type":"choice","prompt":"Solve ax + b = c for x.","choices":["x = c − b − a","x = (c + b)/a","x = c/a − b/a + 1","x = (c − b)/a"],"answer":3,"hint":"Subtract b, then divide by a.","solution":"ax = c − b, so x = (c − b)/a."},{"id":"u1-lit2-q4","type":"choice","prompt":"Solve V = lwh for w.","choices":["w = V − lh","w = Vlh","w = V/(lh)","w = lh/V"],"answer":2,"hint":"w is multiplied by l and h.","solution":"Divide both sides by lh: w = V/(lh)."},{"id":"u1-lit2-q5","type":"choice","prompt":"Solve a/b = c for a.","choices":["a = c/b","a = bc","a = b/c","a = b + c"],"answer":1,"hint":"Multiply both sides by b.","solution":"a/b = c, so a = bc."},{"id":"u1-lit2-q6","type":"choice","prompt":"Solve x/m + n = p for x.","choices":["x = m(p − n)","x = p − n − m","x = m(p + n)","x = (p − n)/m"],"answer":0,"hint":"Subtract n, then multiply by m.","solution":"x/m = p − n, so x = m(p − n)."},{"id":"u1-lit2-q7","type":"input","prompt":"Solve 4x + 3y = 24 for y, then find y when x = 3.","answers":["4"],"hint":"Subtract 4x from both sides, then divide by 3.","solution":"y = (24 − 4x)/3. At x = 3, y = (24 − 12)/3 = 4."},{"id":"u1-lit2-q8","type":"choice","prompt":"Solve A = (1/2)bh for b.","choices":["b = A/(2h)","b = Ah/2","b = A − h/2","b = 2A/h"],"answer":3,"hint":"Multiply by 2, then divide by h.","solution":"2A = bh, so b = 2A/h."}]},{"id":"literal-3","teach":[{"title":"Using a formula","text":["Often it is easiest to substitute the numbers first, then solve. Or solve for the variable first and then substitute. Both give the same answer.","Always check that the answer makes sense for the situation."],"example":{"problem":"Use F = (9/5)C + 32 to find C when F = 50.","steps":["Substitute: 50 = (9/5)C + 32.","Subtract 32: 18 = (9/5)C.","Multiply by 5/9: C = 10."]}}],"questions":[{"id":"u1-lit3-q1","type":"input","prompt":"C = (5/9)(F − 32). Find C when F = 50.","answers":["10"],"hint":"Subtract 32 first, then multiply by 5/9.","solution":"F − 32 = 18. (5/9)(18) = 10."},{"id":"u1-lit3-q2","type":"input","prompt":"A = (1/2)h(b₁ + b₂). A = 40, h = 5, b₁ = 6. Find b₂.","answers":["10"],"hint":"Substitute and solve.","solution":"40 = 2.5(6 + b₂), so 16 = 6 + b₂ and b₂ = 10."},{"id":"u1-lit3-q3","type":"input","prompt":"Simple interest: I = Prt. Find t if I = 90, P = 600, and r = 0.05.","answers":["3"],"hint":"Compute Pr first.","solution":"Pr = 600 · 0.05 = 30. So 90 = 30t and t = 3."},{"id":"u1-lit3-q4","type":"input","prompt":"P = 2l + 2w. If P = 50 and l = 15, find w.","answers":["10"],"hint":"Substitute, then solve.","solution":"50 = 30 + 2w, so 2w = 20 and w = 10."},{"id":"u1-lit3-q5","type":"choice","prompt":"Solve F = (9/5)C + 32 for C.","choices":["C = (9/5)(F − 32)","C = (5/9)F − 32","C = (5/9)(F − 32)","C = (5/9)(F + 32)"],"answer":2,"hint":"Subtract 32 first, then multiply by 5/9.","solution":"F − 32 = (9/5)C. Multiply by 5/9: C = (5/9)(F − 32)."},{"id":"u1-lit3-q6","type":"input","prompt":"v = u + at. If v = 30, u = 6, and t = 4, find a.","answers":["6"],"hint":"Subtract u first.","solution":"30 = 6 + 4a, so 24 = 4a and a = 6."},{"id":"u1-lit3-q7","type":"input","prompt":"y − y₁ = m(x − x₁). If y = 11, y₁ = 3, x = 5, and x₁ = 1, find m.","answers":["2"],"hint":"Compute each difference first.","solution":"11 − 3 = 8 and 5 − 1 = 4. So 8 = 4m and m = 2."},{"id":"u1-lit3-q8","type":"choice","prompt":"Solve S = 2πr² + 2πrh for h.","choices":["h = S − 2πr² − 2πr","h = (S − 2πr²)/(2πr)","h = S/(2πr) + r","h = (S + 2πr²)/(2πr)"],"answer":1,"hint":"Subtract 2πr² and divide by 2πr.","solution":"S − 2πr² = 2πrh, so h = (S − 2πr²)/(2πr)."}]},{"id":"literal-4","teach":[{"title":"Variable in more than one term","text":["If your variable appears in two terms, collect those terms on one side and factor the variable out. Then divide."],"example":{"problem":"Solve A = P + Prt for P.","steps":["Both terms contain P. Factor: A = P(1 + rt).","Divide by (1 + rt).","P = A/(1 + rt)."]}}],"questions":[{"id":"u1-lit4-q1","type":"choice","prompt":"Solve ax + bx = c for x.","choices":["x = c/(a + b)","x = c − a − b","x = c/a + c/b","x = (c − a)/b"],"answer":0,"hint":"Factor x out of the left side.","solution":"x(a + b) = c, so x = c/(a + b)."},{"id":"u1-lit4-q2","type":"choice","prompt":"Solve 3(x − a) = 2x + b for x.","choices":["x = b − 3a","x = (b + 3a)/5","x = b + a","x = b + 3a"],"answer":3,"hint":"Distribute 3, then collect x terms.","solution":"3x − 3a = 2x + b. Subtract 2x: x − 3a = b. Add 3a: x = b + 3a."},{"id":"u1-lit4-q3","type":"choice","prompt":"Solve A = P + Prt for P.","choices":["P = A − rt","P = A/(rt)","P = A/(1 + rt)","P = A − 1 − rt"],"answer":2,"hint":"Factor P out of both terms.","solution":"A = P(1 + rt), so P = A/(1 + rt)."},{"id":"u1-lit4-q4","type":"input","prompt":"A = P(1 + rt). Find t if A = 1250, P = 1000, and r = 0.05.","answers":["5"],"hint":"Divide by P first.","solution":"1250/1000 = 1.25 = 1 + 0.05t. So 0.25 = 0.05t and t = 5."},{"id":"u1-lit4-q5","type":"choice","prompt":"Solve q = (a + b)/2 for b.","choices":["b = q/2 − a","b = 2q − a","b = 2q + a","b = (q − a)/2"],"answer":1,"hint":"Multiply by 2, then subtract a.","solution":"2q = a + b, so b = 2q − a."},{"id":"u1-lit4-q6","type":"input","prompt":"(a + b)/2 = c. If a = 3 and c = 8, find b.","answers":["13"],"hint":"Multiply by 2 first.","solution":"a + b = 16. 3 + b = 16, so b = 13."},{"id":"u1-lit4-q7","type":"choice","prompt":"Solve x − 2y = 8 for y.","choices":["y = x/2 − 4","y = 2x − 8","y = −x/2 + 4","y = x/2 + 4"],"answer":0,"hint":"Subtract x, then divide by −2.","solution":"−2y = 8 − x. Divide by −2: y = −4 + x/2 = x/2 − 4."},{"id":"u1-lit4-q8","type":"input","prompt":"S = 2lw + 2lh + 2wh. If S = 62, w = 3, and h = 2, find l.","answers":["5"],"hint":"Put in w and h, then collect the l terms.","solution":"62 = 6l + 4l + 12, so 10l = 50 and l = 5."}]}]},{"id":"word-problems","title":"Writing and solving equations","lessons":[{"id":"word-problems-1","teach":[{"title":"Turning words into an equation","text":["Pick a letter for the unknown number. Then translate each phrase in order.","\"More than\" and \"plus\" mean add. \"Less than\" means subtract from the other quantity. \"Twice\" and \"times\" mean multiply. \"Is\" means equals."],"example":{"problem":"Three more than twice a number is 17. Find the number.","steps":["Let n be the number.","Twice the number is 2n. Three more than that is 2n + 3.","2n + 3 = 17","Subtract 3: 2n = 14. Divide by 2: n = 7.","Check: 2(7) + 3 = 17. ✓"]}},{"title":"Consecutive integers","text":["Consecutive integers go up by 1: n, n + 1, n + 2.","Consecutive even integers or consecutive odd integers go up by 2: n, n + 2, n + 4."],"example":{"problem":"The sum of three consecutive integers is 72. Find them.","steps":["Let the smallest be n. The others are n + 1 and n + 2.","n + (n + 1) + (n + 2) = 72","3n + 3 = 72, so 3n = 69 and n = 23.","The integers are 23, 24, 25."]}}],"questions":[{"id":"u1-wp1-q1","type":"choice","prompt":"Which equation says \"five less than three times a number is 22\"?","choices":["3n − 5 = 22","5 − 3n = 22","3(n − 5) = 22","3n + 5 = 22"],"answer":0,"hint":"Three times the number comes first. Then take away 5.","solution":"\"Three times a number\" is 3n. \"Five less than\" that is 3n − 5. So 3n − 5 = 22."},{"id":"u1-wp1-q2","type":"input","prompt":"Twice a number decreased by 6 equals 20. Find the number.","answers":["13"],"hint":"Write 2n − 6 = 20.","solution":"2n − 6 = 20. Add 6: 2n = 26. Divide by 2: n = 13. Check: 2(13) − 6 = 20. ✓"},{"id":"u1-wp1-q3","type":"choice","prompt":"Three consecutive integers start at n. Which expression is their sum?","choices":["n + (n + 2) + (n + 4)","3n","n + (n + 1) + (n + 2)","n + 2n + 3n"],"answer":2,"hint":"Each integer is 1 more than the one before it.","solution":"The integers are n, n + 1, n + 2. Their sum is n + (n + 1) + (n + 2) = 3n + 3. Only that choice has the right terms."},{"id":"u1-wp1-q4","type":"input","prompt":"The sum of two consecutive integers is 85. What is the smaller one?","answers":["42"],"hint":"Call them n and n + 1.","solution":"n + (n + 1) = 85, so 2n + 1 = 85 and 2n = 84. n = 42. The integers are 42 and 43."},{"id":"u1-wp1-q5","type":"input","prompt":"The sum of three consecutive integers is 108. What is the smallest?","answers":["35"],"hint":"n + (n + 1) + (n + 2) = 108.","solution":"3n + 3 = 108, so 3n = 105 and n = 35. The integers are 35, 36, 37, which add to 108. ✓"},{"id":"u1-wp1-q6","type":"input","prompt":"Four consecutive integers add up to 138. What is the largest?","answers":["36"],"hint":"Use n, n + 1, n + 2, n + 3. Read the question again: you want the largest.","solution":"n + (n + 1) + (n + 2) + (n + 3) = 138. 4n + 6 = 138, so 4n = 132 and n = 33. The largest is n + 3 = 36."},{"id":"u1-wp1-q7","type":"choice","prompt":"Three consecutive even integers add up to 78. Which list is right?","choices":["24, 26, 28","25, 26, 27","26, 28, 30","22, 24, 26"],"answer":0,"hint":"Even integers go up by 2, so use n, n + 2, n + 4.","solution":"n + (n + 2) + (n + 4) = 78. 3n + 6 = 78, so n = 24. The integers are 24, 26, 28. The list 25, 26, 27 adds to 78 too, but those are not all even."},{"id":"u1-wp1-q8","type":"input","prompt":"The sum of three consecutive odd integers is 189. What is the smallest?","answers":["61"],"hint":"Odd integers go up by 2: n, n + 2, n + 4.","solution":"n + (n + 2) + (n + 4) = 189. 3n + 6 = 189, so 3n = 183 and n = 61. The integers are 61, 63, 65. Check: 61 + 63 + 65 = 189. ✓"}]},{"id":"word-problems-2","teach":[{"title":"Perimeter of a rectangle","text":["Perimeter is the distance around: P = 2L + 2W.","When the length is described using the width, write the length in terms of the width first, then substitute."],"example":{"problem":"A rectangle is 4 cm longer than it is wide. Its perimeter is 44 cm. Find the width and length.","steps":["Let w be the width. The length is w + 4.","2w + 2(w + 4) = 44","2w + 2w + 8 = 44, so 4w = 36 and w = 9.","The length is 9 + 4 = 13. Check: 2(9) + 2(13) = 44. ✓"]}},{"title":"Triangles and other shapes","text":["The perimeter of any polygon is the sum of its side lengths. Add the side expressions, combine like terms, and set the total equal to the perimeter."],"example":{"problem":"A triangle has sides x, x + 3, and 2x − 1. Its perimeter is 30. Find x.","steps":["x + (x + 3) + (2x − 1) = 30","Combine like terms: 4x + 2 = 30.","4x = 28, so x = 7.","The sides are 7, 10, and 13. They add to 30. ✓"]}}],"questions":[{"id":"u1-wp2-q1","type":"choice","prompt":"A rectangle has width w and a length that is 5 more than the width. Which expression is its perimeter?","choices":["2w + (w + 5)","2w + 2(w + 5)","w + (w + 5)","2(w + 5)"],"answer":1,"hint":"The perimeter uses two widths and two lengths.","solution":"Two widths give 2w. Two lengths give 2(w + 5). So P = 2w + 2(w + 5)."},{"id":"u1-wp2-q2","type":"input","prompt":"A rectangle is 6 m longer than it is wide, and its perimeter is 52 m. What is the width in meters?","answers":["10"],"hint":"Write 2w + 2(w + 6) = 52.","solution":"2w + 2(w + 6) = 52. 4w + 12 = 52, so 4w = 40 and w = 10. The length is 16. Check: 2(10) + 2(16) = 52. ✓"},{"id":"u1-wp2-q3","type":"input","prompt":"The length of a rectangle is twice its width. The perimeter is 60 ft. What is the length in feet?","answers":["20"],"hint":"If the width is w, the length is 2w. Then find w.","solution":"2w + 2(2w) = 60. 6w = 60, so w = 10. The length is 2(10) = 20. Check: 2(10) + 2(20) = 60. ✓"},{"id":"u1-wp2-q4","type":"input","prompt":"A rectangle's length is 3 less than 4 times its width. The perimeter is 54 in. What is the width in inches?","answers":["6"],"hint":"Length = 4w − 3. Put that in the perimeter formula.","solution":"2w + 2(4w − 3) = 54. 2w + 8w − 6 = 54, so 10w = 60 and w = 6. The length is 21. Check: 12 + 42 = 54. ✓"},{"id":"u1-wp2-q5","type":"input","prompt":"A triangle has sides x, x + 5, and 2x − 3, and its perimeter is 38. What is the longest side?","answers":["15"],"hint":"Find x first. Then work out all three sides.","solution":"x + (x + 5) + (2x − 3) = 38. 4x + 2 = 38, so x = 9. The sides are 9, 14, and 15. The longest is 15."},{"id":"u1-wp2-q6","type":"input","prompt":"An isosceles triangle has two equal sides of 2x + 1 each, and a base of x + 4. The perimeter is 41. What is the base?","answers":["11"],"hint":"There are two equal sides, so add 2(2x + 1).","solution":"2(2x + 1) + (x + 4) = 41. 4x + 2 + x + 4 = 41, so 5x + 6 = 41 and x = 7. The base is 7 + 4 = 11. The sides are 15, 15, 11, which add to 41. ✓"},{"id":"u1-wp2-q7","type":"choice","prompt":"A garden is 8 ft more than 3 times as long as it is wide. It needs 96 ft of fence around it. What are its dimensions?","choices":["10 ft by 38 ft","11 ft by 41 ft","22 ft by 74 ft","10 ft by 28 ft"],"answer":0,"hint":"Length = 3w + 8. Use P = 2w + 2(3w + 8). Remember to double the 8.","solution":"2w + 2(3w + 8) = 96. 2w + 6w + 16 = 96, so 8w = 80 and w = 10. The length is 3(10) + 8 = 38. Check: 20 + 76 = 96. ✓"},{"id":"u1-wp2-q8","type":"input","prompt":"A rectangle's perimeter is 70 cm and its length is 5 cm more than its width. What is its area in cm²?","answers":["300"],"hint":"Find the width and length first. Area = length × width.","solution":"2w + 2(w + 5) = 70. 4w + 10 = 70, so w = 15. The length is 20. Area = 15 × 20 = 300 cm²."}]},{"id":"word-problems-3","teach":[{"title":"Quantity times price","text":["For money problems, each group is worth (how many) × (price each). Add the groups to get the total.","If two groups add to a known total, call one group x and the other (total − x)."],"example":{"problem":"A show sold 40 tickets. Adult tickets cost $8 and child tickets cost $5. Sales were $260. How many adult tickets were sold?","steps":["Let a be the adult tickets. Child tickets are 40 − a.","8a + 5(40 − a) = 260","8a + 200 − 5a = 260, so 3a = 60 and a = 20.","20 adult tickets and 20 child tickets: 160 + 100 = 260. ✓"]}},{"title":"Flat fee plus a rate","text":["Many costs are a fixed fee plus a rate times a number: total = fee + rate × amount.","To compare two plans, set their totals equal and solve."],"example":{"problem":"A gym charges a $25 sign-up fee plus $18 per month. How many months can you pay for with $187?","steps":["25 + 18m = 187","18m = 162","m = 9","Check: 25 + 18(9) = 187. ✓"]}}],"questions":[{"id":"u1-wp3-q1","type":"choice","prompt":"Concert tickets cost $12 for adults and $7 for children. The venue sold 30 tickets, with x of them adult tickets. Which expression gives the total sales?","choices":["12x + 7x","12x + 7(x − 30)","12x + 7(30 − x)","19(30 − x)"],"answer":2,"hint":"Children are what is left after the adults.","solution":"Adults: 12x dollars. Children: 30 − x tickets at $7, so 7(30 − x). Total: 12x + 7(30 − x)."},{"id":"u1-wp3-q2","type":"input","prompt":"A taxi charges $3 plus $2 per mile. A ride costs $27. How many miles was it?","answers":["12"],"hint":"3 + 2m = 27.","solution":"3 + 2m = 27. 2m = 24, so m = 12 miles. Check: 3 + 24 = 27. ✓"},{"id":"u1-wp3-q3","type":"input","prompt":"A streaming service charges a $9 sign-up fee and $12 each month. Kai has paid $93 in total. For how many months?","answers":["7"],"hint":"Fee + 12 × months = total.","solution":"9 + 12m = 93. 12m = 84, so m = 7. Check: 9 + 84 = 93. ✓"},{"id":"u1-wp3-q4","type":"input","prompt":"A jar has 25 coins, all nickels and dimes, worth $1.90. How many dimes are there?","answers":["13"],"hint":"Use cents: 5 per nickel, 10 per dime. If n is nickels, dimes are 25 − n.","solution":"5n + 10(25 − n) = 190. 5n + 250 − 10n = 190, so −5n = −60 and n = 12 nickels. Dimes: 25 − 12 = 13. Check: 60 + 130 = 190 cents. ✓"},{"id":"u1-wp3-q5","type":"input","prompt":"A school play sold 120 tickets. Student tickets were $5 and adult tickets were $8. Sales were $705. How many adult tickets were sold?","answers":["35"],"hint":"Let a be adult tickets. Students bought 120 − a.","solution":"8a + 5(120 − a) = 705. 8a + 600 − 5a = 705, so 3a = 105 and a = 35. Check: 35(8) + 85(5) = 280 + 425 = 705. ✓"},{"id":"u1-wp3-q6","type":"input","prompt":"Dev has 14 bills, all $5 and $10 bills, worth $95. How many $10 bills does he have?","answers":["5"],"hint":"If f is the number of fives, tens are 14 − f.","solution":"5f + 10(14 − f) = 95. 5f + 140 − 10f = 95, so −5f = −45 and f = 9. Tens: 14 − 9 = 5. Check: 45 + 50 = 95. ✓"},{"id":"u1-wp3-q7","type":"choice","prompt":"Plan A costs $30 to join plus $10 per month. Plan B has no joining fee and costs $15 per month. After how many months do the two plans cost the same?","choices":["3 months","2 months","6 months","1.2 months"],"answer":2,"hint":"Set the two total costs equal: 30 + 10m = 15m.","solution":"30 + 10m = 15m. Subtract 10m: 30 = 5m. So m = 6. Both cost $90 after 6 months."},{"id":"u1-wp3-q8","type":"input","prompt":"Sam has $140 saved and adds $15 each week. Mia has $60 and adds $25 each week. After how many weeks do they have the same amount?","answers":["8"],"hint":"Set 140 + 15w equal to 60 + 25w.","solution":"140 + 15w = 60 + 25w. Subtract 15w and 60: 80 = 10w, so w = 8. Each has $260. ✓"}]},{"id":"word-problems-4","teach":[{"title":"Percent as a decimal","text":["Change a percent to a decimal before you write the equation: 20% = 0.20, 7% = 0.07, 115% = 1.15.","A discount of 20% leaves 80% of the price, so the sale price is 0.80 times the original.","Always say what the unknown stands for. The unknown is usually the original amount."],"example":{"problem":"After a 20% discount, a jacket costs $64. What was the original price?","steps":["Let x be the original price. After 20% off, you pay 80%.","0.80x = 64","x = 64 ÷ 0.80 = 80.","Check: 20% of 80 is 16, and 80 − 16 = 64. ✓"]}},{"title":"Tax, tips, and markups","text":["Adding a percent to a price means you pay 100% + that percent. A 15% tip makes the total 1.15 times the bill."],"example":{"problem":"A meal plus a 15% tip costs $46. What was the meal price?","steps":["Let x be the meal price. Total with tip is 1.15x.","1.15x = 46","x = 46 ÷ 1.15 = 40.","Check: 15% of 40 is 6, and 40 + 6 = 46. ✓"]}}],"questions":[{"id":"u1-wp4-q1","type":"choice","prompt":"A shirt is 30% off. The sale price is $35. Which equation finds the original price x?","choices":["0.70x = 35","x − 0.30 = 35","0.30x = 35","1.30x = 35"],"answer":0,"hint":"A 30% discount means you pay 70% of the original price.","solution":"You pay 100% − 30% = 70% of x. So 0.70x = 35."},{"id":"u1-wp4-q2","type":"input","prompt":"25% of a number is 18. What is the number?","answers":["72"],"hint":"Write 0.25n = 18.","solution":"0.25n = 18, so n = 18 ÷ 0.25 = 72. Check: 25% of 72 is 18. ✓"},{"id":"u1-wp4-q3","type":"input","prompt":"After a 15% discount, a bike costs $51. What was its original price in dollars?","answers":["60"],"hint":"You pay 85% of the original: 0.85x = 51.","solution":"0.85x = 51, so x = 51 ÷ 0.85 = 60. Check: 15% of 60 is 9, and 60 − 9 = 51. ✓"},{"id":"u1-wp4-q4","type":"input","prompt":"A receipt shows $54 including 8% sales tax. What was the price before tax, in dollars?","answers":["50"],"hint":"Total = 1.08 times the price.","solution":"1.08x = 54, so x = 54 ÷ 1.08 = 50. Check: 8% of 50 is 4, and 50 + 4 = 54. ✓"},{"id":"u1-wp4-q5","type":"input","prompt":"Pete earns $12 per hour plus 6% of his sales. One week he worked 20 hours and earned $300. How many dollars of sales did he make?","answers":["1000"],"hint":"Hourly pay is 12 × 20. The rest comes from commission.","solution":"Hourly pay: 12 × 20 = 240. So 240 + 0.06s = 300. 0.06s = 60, so s = 1000. Check: 240 + 60 = 300. ✓"},{"id":"u1-wp4-q6","type":"input","prompt":"A town's population grew by 12% and is now 5600. What was it before the growth?","answers":["5000"],"hint":"Now = 112% of before, so 1.12x = 5600.","solution":"1.12x = 5600, so x = 5600 ÷ 1.12 = 5000. Check: 12% of 5000 is 600, and 5000 + 600 = 5600. ✓"},{"id":"u1-wp4-q7","type":"choice","prompt":"A store marks up the wholesale price by 40% to get a retail price of $84. What was the wholesale price?","choices":["$50.40","$117.60","$44","$60"],"answer":3,"hint":"Retail = 140% of wholesale.","solution":"1.40x = 84, so x = 84 ÷ 1.40 = 60. Check: 40% of 60 is 24, and 60 + 24 = 84. ✓ The wholesale price was $60."},{"id":"u1-wp4-q8","type":"input","prompt":"Maya buys a laptop at 20% off, then pays 10% tax on the sale price. She pays $528 in total. What was the original price in dollars?","answers":["600"],"hint":"Total = 0.80 × 1.10 × original. Multiply the two decimals first.","solution":"0.80 × 1.10 = 0.88, so 0.88x = 528 and x = 600. Check: 20% off 600 is 480, and 10% tax adds 48, so 528. ✓"}]}]},{"id":"inequalities","title":"Solving inequalities","lessons":[{"id":"inequalities-1","teach":[{"title":"Solving like an equation, with one new rule","text":["Solve an inequality the same way as an equation: undo adding and subtracting, then undo multiplying and dividing.","New rule: if you multiply or divide both sides by a negative number, flip the inequality sign."],"example":{"problem":"Solve −3x + 4 > 19","steps":["Subtract 4 from both sides: −3x > 15.","Divide by −3. The sign flips: x < −5.","Check with x = −6: −3(−6) + 4 = 22, and 22 > 19. ✓"]}},{"title":"Graphing on a number line","text":["A circle marks the endpoint. Use an open circle for < and >, because the number is not included. Use a closed circle for ≤ and ≥.","Shade the side where the solutions are. For x < 4, shade to the left of 4."],"example":{"problem":"Graph x ≥ 2","steps":["Put a closed circle at 2, because 2 is included.","Shade to the right, toward the larger numbers."]}}],"questions":[{"id":"u1-ineq1-q1","type":"choice","prompt":"When do you reverse the direction of an inequality sign?","choices":["When you multiply or divide both sides by a negative number","When you add a negative number to both sides","Whenever the answer is negative","When the variable is on the right side"],"answer":0,"hint":"Think about what changes the order of numbers.","solution":"Adding or subtracting never changes the sign. Only multiplying or dividing by a negative does, because it reverses the order of numbers."},{"id":"u1-ineq1-q2","type":"input","prompt":"Solve: x + 7 < 12","answers":["x<5","x<5","5>x","5>x"],"hint":"Subtract 7 from both sides.","solution":"x + 7 < 12. Subtract 7: x < 5."},{"id":"u1-ineq1-q3","type":"input","prompt":"Solve: 4x ≥ 28","answers":["x>=7","x≥7","7<=x","7≤x"],"hint":"Divide both sides by 4. It is positive, so the sign stays.","solution":"4x ≥ 28. Divide by 4: x ≥ 7."},{"id":"u1-ineq1-q4","type":"input","prompt":"Solve: −2x ≤ 10","answers":["x>=-5","x≥-5","-5<=x","-5≤x"],"hint":"You divide by a negative number. What happens to the sign?","solution":"−2x ≤ 10. Divide by −2 and flip the sign: x ≥ −5."},{"id":"u1-ineq1-q5","type":"input","prompt":"Solve: 3x − 5 > 16","answers":["x>7","x>7","7<x","7<x"],"hint":"Add 5 first, then divide.","solution":"3x − 5 > 16. Add 5: 3x > 21. Divide by 3: x > 7."},{"id":"u1-ineq1-q6","type":"input","prompt":"Solve: −4x + 3 ≥ 23","answers":["x<=-5","x≤-5","-5>=x","-5≥x"],"hint":"Subtract 3, then divide by −4 and flip.","solution":"−4x + 3 ≥ 23. Subtract 3: −4x ≥ 20. Divide by −4 and flip the sign: x ≤ −5."},{"id":"u1-ineq1-q7","type":"choice","prompt":"Which graph shows x ≥ −2?","choices":["Open circle at −2, shaded to the right","Closed circle at −2, shaded to the left","Closed circle at −2, shaded to the right","Open circle at −2, shaded to the left"],"answer":2,"hint":"Is −2 included? And is x bigger or smaller than −2?","solution":"≥ includes −2, so the circle is closed. \"Greater than\" means shade to the right, toward larger numbers."},{"id":"u1-ineq1-q8","type":"input","prompt":"Solve: 7 − 2x < 1","answers":["x>3","x>3","3<x","3<x"],"hint":"Subtract 7 from both sides first. Then divide by −2.","solution":"7 − 2x < 1. Subtract 7: −2x < −6. Divide by −2 and flip: x > 3. Check x = 4: 7 − 8 = −1, and −1 < 1. ✓"}]},{"id":"inequalities-2","teach":[{"title":"Variables on both sides","text":["Move the variable terms to one side, as you do with equations. Keep the variable term positive if you can, so you do not have to flip."],"example":{"problem":"Solve 5x − 3 ≤ 2x + 9","steps":["Subtract 2x from both sides: 3x − 3 ≤ 9.","Add 3: 3x ≤ 12.","Divide by 3: x ≤ 4."]}},{"title":"Distributing and fractions","text":["Distribute first and combine like terms. To clear a fraction, multiply every term on both sides by the denominator. A positive multiplier does not flip the sign."],"example":{"problem":"Solve 2(x − 3) > 4x + 6","steps":["Distribute: 2x − 6 > 4x + 6.","Subtract 4x: −2x − 6 > 6.","Add 6: −2x > 12.","Divide by −2 and flip the sign: x < −6."]}}],"questions":[{"id":"u1-ineq2-q1","type":"input","prompt":"Solve: 6x + 1 > 2x + 17","answers":["x>4","x>4","4<x","4<x"],"hint":"Subtract 2x from both sides.","solution":"6x + 1 > 2x + 17. Subtract 2x: 4x + 1 > 17. Subtract 1: 4x > 16. Divide by 4: x > 4."},{"id":"u1-ineq2-q2","type":"input","prompt":"Solve: 3(x + 2) ≤ 21","answers":["x<=5","x≤5","5>=x","5≥x"],"hint":"Distribute the 3, or divide both sides by 3 first.","solution":"3(x + 2) ≤ 21. Divide by 3: x + 2 ≤ 7. Subtract 2: x ≤ 5."},{"id":"u1-ineq2-q3","type":"input","prompt":"Solve: 5x − 8 ≥ 8x + 7","answers":["x<=-5","x≤-5","-5>=x","-5≥x"],"hint":"Subtract 8x from both sides. The x term becomes negative.","solution":"5x − 8 ≥ 8x + 7. Subtract 8x: −3x − 8 ≥ 7. Add 8: −3x ≥ 15. Divide by −3 and flip: x ≤ −5."},{"id":"u1-ineq2-q4","type":"input","prompt":"Solve: 2(3x − 1) < 4x + 10","answers":["x<6","x<6","6>x","6>x"],"hint":"Distribute, then collect the x terms on the left.","solution":"6x − 2 < 4x + 10. Subtract 4x: 2x − 2 < 10. Add 2: 2x < 12. Divide by 2: x < 6."},{"id":"u1-ineq2-q5","type":"input","prompt":"Solve: −3(x − 4) > 2x − 8","answers":["x<4","x<4","4>x","4>x"],"hint":"Distribute the −3 carefully. You will divide by a negative at the end.","solution":"−3x + 12 > 2x − 8. Subtract 2x: −5x + 12 > −8. Subtract 12: −5x > −20. Divide by −5 and flip: x < 4."},{"id":"u1-ineq2-q6","type":"input","prompt":"Solve: x/3 + 2 ≥ 5","answers":["x>=9","x≥9","9<=x","9≤x"],"hint":"Subtract 2 first. Then multiply by 3.","solution":"x/3 + 2 ≥ 5. Subtract 2: x/3 ≥ 3. Multiply by 3: x ≥ 9."},{"id":"u1-ineq2-q7","type":"choice","prompt":"Solve: (2x − 1)/3 < 5","choices":["x < 7","x < 8","x > 8","x < 3"],"answer":1,"hint":"Multiply both sides by 3 first.","solution":"Multiply by 3: 2x − 1 < 15. Add 1: 2x < 16. Divide by 2: x < 8."},{"id":"u1-ineq2-q8","type":"choice","prompt":"Solve: 4x + 5 > 4x − 2","choices":["No solution","x > 0","All real numbers","x > −7/8"],"answer":2,"hint":"Subtract 4x from both sides and look at what is left.","solution":"Subtract 4x: 5 > −2. That is always true, so every real number is a solution."}]},{"id":"inequalities-3","teach":[{"title":"Interval notation","text":["Interval notation writes the solution set as (left end, right end). Use ( ) when the end is not included or is infinite. Use [ ] when it is included.","Infinity always gets a parenthesis. x < 3 is (−∞, 3). x ≥ −1 is [−1, ∞)."],"example":{"problem":"Solve 2x + 1 ≥ −5 and write the answer in interval notation.","steps":["Subtract 1: 2x ≥ −6.","Divide by 2: x ≥ −3.","The −3 is included, so use a bracket: [−3, ∞)."]}},{"title":"Reading a graph","text":["An open circle matches a parenthesis. A closed circle matches a bracket. Shading to the right ends at ∞. Shading to the left starts at −∞."],"example":{"problem":"An open circle at 1 with shading to the left. What is the inequality and interval?","steps":["Open circle at 1 means 1 is not included.","Shading to the left means smaller numbers: x < 1.","Interval: (−∞, 1)."]}}],"questions":[{"id":"u1-ineq3-q1","type":"choice","prompt":"Write x > 4 in interval notation.","choices":["(4, ∞)","[4, ∞)","(−∞, 4)","(−∞, 4]"],"answer":0,"hint":"Greater than 4 goes up toward ∞. Is 4 included?","solution":"x > 4 does not include 4, so use a parenthesis. The values go up forever: (4, ∞)."},{"id":"u1-ineq3-q2","type":"choice","prompt":"Write x ≤ −2 in interval notation.","choices":["(−∞, −2]","(−∞, −2)","[−2, ∞)","(−2, ∞)"],"answer":0,"hint":"Smaller numbers go toward −∞. Is −2 included?","solution":"x ≤ −2 includes −2, so use a bracket on that end. The values go down forever: (−∞, −2]."},{"id":"u1-ineq3-q3","type":"choice","prompt":"Solve 3x + 2 < 11. Which interval is the solution?","choices":["(−∞, 3]","(3, ∞)","(−∞, 9)","(−∞, 3)"],"answer":3,"hint":"Solve for x first. Then decide on brackets.","solution":"3x + 2 < 11. Subtract 2: 3x < 9. Divide by 3: x < 3. Interval: (−∞, 3)."},{"id":"u1-ineq3-q4","type":"choice","prompt":"Solve −5x ≤ 20. Which interval is the solution?","choices":["(−∞, −4]","[−4, ∞)","(−4, ∞)","[4, ∞)"],"answer":1,"hint":"You divide by a negative number, so the sign flips.","solution":"−5x ≤ 20. Divide by −5 and flip: x ≥ −4. Interval: [−4, ∞)."},{"id":"u1-ineq3-q5","type":"choice","prompt":"A graph has an open circle at 1 and shading to the right. Which inequality is it?","choices":["x ≥ 1","x < 1","x > 1","x ≤ 1"],"answer":2,"hint":"Open circle means the number is not included. Right means larger.","solution":"Open circle: not included, so the sign is strict. Shading right: larger numbers. The inequality is x > 1."},{"id":"u1-ineq3-q6","type":"choice","prompt":"Solve 2(x − 1) > 5x + 10. Which interval is the solution?","choices":["(−∞, −4)","(−4, ∞)","(−∞, −4]","(−∞, 4)"],"answer":0,"hint":"Distribute, collect x terms, then divide by a negative.","solution":"2x − 2 > 5x + 10. Subtract 5x: −3x − 2 > 10. Add 2: −3x > 12. Divide by −3 and flip: x < −4. Interval: (−∞, −4)."},{"id":"u1-ineq3-q7","type":"choice","prompt":"Solve 4 − (x − 3) ≥ 10. Which interval is the solution?","choices":["[−3, ∞)","(−∞, 3]","(−∞, −3)","(−∞, −3]"],"answer":3,"hint":"Subtracting a group changes both signs inside it.","solution":"4 − x + 3 ≥ 10. Combine: 7 − x ≥ 10. Subtract 7: −x ≥ 3. Multiply by −1 and flip: x ≤ −3. Interval: (−∞, −3]."},{"id":"u1-ineq3-q8","type":"input","prompt":"What is the largest integer x that satisfies 3x − 4 < 20?","answers":["7"],"hint":"Solve the inequality. Then ask if 8 is allowed.","solution":"3x − 4 < 20. Add 4: 3x < 24. Divide by 3: x < 8. The number 8 is not included, so the largest integer is 7."}]},{"id":"inequalities-4","teach":[{"title":"Key phrases","text":["\"At least\" means ≥. \"At most\" and \"no more than\" mean ≤. \"More than\" means >. \"Fewer than\" and \"less than\" mean <.","Define the variable, write the inequality, solve, and then say what the answer means."],"example":{"problem":"A truck rental costs $40 plus $0.25 per mile. Your budget is at most $100. How many miles can you drive?","steps":["Let m be the miles. Cost: 40 + 0.25m.","\"At most $100\" means ≤ 100: 40 + 0.25m ≤ 100.","Subtract 40: 0.25m ≤ 60.","Divide by 0.25: m ≤ 240. You can drive up to 240 miles."]}},{"title":"Making sense of the answer","text":["If the variable counts whole things, such as tickets or tests, choose a whole number that fits the inequality. For x > 7.5 the smallest whole number is 8."],"example":{"problem":"You need more than 7.5 hours. What is the smallest whole number of hours?","steps":["The solution is h > 7.5.","Hours must be whole here, and 7 is too small.","The smallest is 8."]}}],"questions":[{"id":"u1-ineq4-q1","type":"choice","prompt":"Which symbol goes with the words \"at least\"?","choices":["≥","≤",">","<"],"answer":0,"hint":"At least means that number or more.","solution":"\"At least 5\" means 5 or more, so x ≥ 5."},{"id":"u1-ineq4-q2","type":"choice","prompt":"Twice a number plus 3 is at most 21. Which inequality models this?","choices":["2n + 3 ≤ 21","2n + 3 ≥ 21","2n + 3 < 21","2(n + 3) ≤ 21"],"answer":0,"hint":"\"At most\" means no bigger than. Twice the number is 2n.","solution":"\"Twice a number plus 3\" is 2n + 3. \"At most 21\" means ≤ 21."},{"id":"u1-ineq4-q3","type":"input","prompt":"What is the largest integer n with 2n + 3 ≤ 21?","answers":["9"],"hint":"Solve the inequality first.","solution":"2n + 3 ≤ 21. Subtract 3: 2n ≤ 18. Divide by 2: n ≤ 9. The largest integer is 9."},{"id":"u1-ineq4-q4","type":"input","prompt":"A phone plan costs $20 plus $0.10 per text. The budget is at most $45. What is the most texts you can send?","answers":["250"],"hint":"20 + 0.10t ≤ 45.","solution":"20 + 0.10t ≤ 45. Subtract 20: 0.10t ≤ 25. Divide by 0.10: t ≤ 250. You can send at most 250 texts."},{"id":"u1-ineq4-q5","type":"input","prompt":"Lena needs an average of at least 80 over 4 tests. Her first three scores are 72, 85, and 78. What is the lowest fourth score that works?","answers":["85"],"hint":"The four scores must total at least 4 × 80.","solution":"The total must be at least 320. The first three add to 235. So 235 + x ≥ 320, and x ≥ 85. The lowest score is 85."},{"id":"u1-ineq4-q6","type":"input","prompt":"A club sells tickets for $6 each. Its fixed cost is $150. What is the fewest tickets it must sell to make a profit of more than $300?","answers":["76"],"hint":"Profit = 6t − 150. \"More than\" is strict.","solution":"6t − 150 > 300. Add 150: 6t > 450. Divide by 6: t > 75. Since it must be strictly more than 75, the fewest whole number is 76."},{"id":"u1-ineq4-q7","type":"choice","prompt":"Gym A costs $50 to join plus $20 per month. Gym B costs $30 per month with no joining fee. When is Gym A cheaper?","choices":["Fewer than 5 months","More than 5 months","More than 2.5 months","Fewer than 2.5 months"],"answer":1,"hint":"Write 50 + 20m < 30m and solve.","solution":"50 + 20m < 30m. Subtract 20m: 50 < 10m. So m > 5. Gym A is cheaper after more than 5 months."},{"id":"u1-ineq4-q8","type":"input","prompt":"A rectangle is 12 cm long. Its perimeter must be less than 50 cm. What is the largest whole-number width in centimeters?","answers":["12"],"hint":"Perimeter: 2(12) + 2w < 50.","solution":"24 + 2w < 50. Subtract 24: 2w < 26. Divide by 2: w < 13. The largest whole number is 12."}]}]},{"id":"compound","title":"Compound inequalities","lessons":[{"id":"compound-1","teach":[{"title":"\"And\" means both","text":["A compound inequality joins two inequalities. With \"and\", a number must make both true. The solutions are where the two graphs overlap, which is a segment between two ends.","You can write \"x > 2 and x < 7\" as 2 < x < 7."],"example":{"problem":"Solve 1 < 2x + 3 < 9","steps":["Do the same step to all three parts. Subtract 3: −2 < 2x < 6.","Divide by 2: −1 < x < 3.","Interval: (−1, 3)."]}},{"title":"Reading and graphing","text":["On a number line, shade between the two endpoints. Use an open circle for < and a closed circle for ≤, one for each end."],"example":{"problem":"Which integers satisfy −1 < x < 3?","steps":["The ends −1 and 3 are not included.","The integers between them are 0, 1, and 2."]}}],"questions":[{"id":"u1-comp1-q1","type":"choice","prompt":"Which inequality means the same as \"x > 2 and x < 7\"?","choices":["2 < x < 7","x < 2 or x > 7","7 < x < 2","x > 7 and x < 2"],"answer":0,"hint":"\"And\" keeps only the numbers that fit both parts.","solution":"Numbers greater than 2 and less than 7 lie between 2 and 7. That is 2 < x < 7."},{"id":"u1-comp1-q2","type":"choice","prompt":"Which number is a solution of −3 < x ≤ 4?","choices":["0","−3","5","−4"],"answer":0,"hint":"Test each number against both ends.","solution":"0 is between −3 and 4, so it works. −3 is not included. 5 and −4 are outside."},{"id":"u1-comp1-q3","type":"choice","prompt":"A graph has a closed circle at −1, an open circle at 5, and shading between them. Which inequality is it?","choices":["−1 < x ≤ 5","−1 ≤ x < 5","−1 ≤ x ≤ 5","x ≤ −1 or x > 5"],"answer":1,"hint":"Closed circle means ≤. Open circle means <.","solution":"The left end −1 is closed, so −1 ≤ x. The right end 5 is open, so x < 5. Together: −1 ≤ x < 5."},{"id":"u1-comp1-q4","type":"choice","prompt":"Solve: 3 < x + 1 < 8","choices":["4 < x < 9","2 < x < 9","2 < x < 7","−2 < x < 3"],"answer":2,"hint":"Subtract 1 from all three parts.","solution":"Subtract 1 from every part: 3 − 1 < x < 8 − 1. So 2 < x < 7."},{"id":"u1-comp1-q5","type":"choice","prompt":"Solve: −4 ≤ 2x < 10","choices":["−2 ≤ x < 5","−8 ≤ x < 20","−2 < x ≤ 5","−2 ≤ x < 12"],"answer":0,"hint":"Divide all three parts by 2.","solution":"Divide every part by 2: −2 ≤ x < 5."},{"id":"u1-comp1-q6","type":"input","prompt":"How many integers satisfy −2 ≤ x < 5?","answers":["7"],"hint":"List them. Is −2 included? Is 5?","solution":"The integers are −2, −1, 0, 1, 2, 3, 4. That is 7 integers."},{"id":"u1-comp1-q7","type":"choice","prompt":"Solve: −7 < 3x − 1 < 8","choices":["−6 < x < 9","−2 < x < 7/3","−8/3 < x < 3","−2 < x < 3"],"answer":3,"hint":"Add 1 to all three parts first. Then divide by 3.","solution":"Add 1: −6 < 3x < 9. Divide by 3: −2 < x < 3."},{"id":"u1-comp1-q8","type":"input","prompt":"What is the largest integer that satisfies 5 < 2x + 1 < 15?","answers":["6"],"hint":"Solve for x first. Then check whether the right end is included.","solution":"Subtract 1: 4 < 2x < 14. Divide by 2: 2 < x < 7. The number 7 is not included, so the largest integer is 6."}]},{"id":"compound-2","teach":[{"title":"\"Or\" means either","text":["With \"or\", a number only has to make one of the inequalities true. The graph is both shaded pieces together. The pieces usually point away from each other.","Solve each part separately. Do not combine them into one chain."],"example":{"problem":"Solve x − 2 < −3 or 2x > 8","steps":["First part: x < −1.","Second part: x > 4.","Answer: x < −1 or x > 4.","Interval: (−∞, −1) ∪ (4, ∞). The symbol ∪ means \"or\"."]}},{"title":"When \"or\" overlaps","text":["If the two shaded pieces overlap or touch, they cover the whole line, so the answer is all real numbers."],"example":{"problem":"Solve x ≤ 5 or x > 1","steps":["Every number is either at most 5 or more than 1. A number like 3 is both.","Together they cover everything: all real numbers, (−∞, ∞)."]}}],"questions":[{"id":"u1-comp2-q1","type":"choice","prompt":"Which graph shows x < −2 or x ≥ 3?","choices":["Open circle at −2 shaded left, closed circle at 3 shaded right","Open circle at −2 and closed circle at 3, shaded between them","Closed circle at −2 shaded left, open circle at 3 shaded right","Open circle at −2 shaded right, closed circle at 3 shaded left"],"answer":0,"hint":"\"Or\" gives two pieces, pointing away from each other.","solution":"x < −2 is an open circle at −2 with shading left. x ≥ 3 is a closed circle at 3 with shading right."},{"id":"u1-comp2-q2","type":"choice","prompt":"Solve: x + 3 < 1 or x − 2 > 5","choices":["x < 2 or x > 3","x < −2 or x > 7","x < −2 and x > 7","x < −4 or x > 3"],"answer":1,"hint":"Solve each inequality on its own.","solution":"x + 3 < 1 gives x < −2. x − 2 > 5 gives x > 7. The answer is x < −2 or x > 7."},{"id":"u1-comp2-q3","type":"choice","prompt":"Solve: 2x ≤ −6 or x > 1","choices":["x ≥ −3 or x > 1","x ≤ −3 or x < 1","x ≤ −3 or x > 1","x ≤ −12 or x > 1"],"answer":2,"hint":"Divide 2x ≤ −6 by 2. Positive, so no flip.","solution":"2x ≤ −6 gives x ≤ −3. The second part is already x > 1. The answer is x ≤ −3 or x > 1."},{"id":"u1-comp2-q4","type":"choice","prompt":"Write x ≤ −3 or x > 1 in interval notation.","choices":["(−∞, −3] ∪ (1, ∞)","(−∞, −3) ∪ [1, ∞)","[−3, 1)","(−∞, −3] ∪ [1, ∞)"],"answer":0,"hint":"Closed circle: bracket. Open circle: parenthesis.","solution":"x ≤ −3 is (−∞, −3] and x > 1 is (1, ∞). Join them with ∪."},{"id":"u1-comp2-q5","type":"choice","prompt":"Solve: 3x − 1 ≥ 8 or −2x > 4","choices":["x ≥ 3 or x > −2","x ≥ 3 and x < −2","x ≥ 7/3 or x < −2","x ≥ 3 or x < −2"],"answer":3,"hint":"Dividing by −2 flips the sign.","solution":"3x − 1 ≥ 8 gives 3x ≥ 9, so x ≥ 3. −2x > 4 gives x < −2. The answer is x ≥ 3 or x < −2."},{"id":"u1-comp2-q6","type":"input","prompt":"How many integers from −5 to 5 (both included) satisfy x < −3 or x ≥ 2?","answers":["6"],"hint":"List the integers from each piece. Do not count one twice.","solution":"x < −3 gives −5 and −4. x ≥ 2 gives 2, 3, 4, 5. That is 2 + 4 = 6 integers."},{"id":"u1-comp2-q7","type":"choice","prompt":"Solve: 5 − x < 1 or 2x + 3 < −5","choices":["x < −4 or x > 4","x > 4 or x > −4","x < 4 or x > −4","x < −4 and x > 4"],"answer":0,"hint":"In the first one, you divide by −1 at the end and flip.","solution":"5 − x < 1: subtract 5 to get −x < −4, so x > 4. 2x + 3 < −5: 2x < −8, so x < −4. The answer is x < −4 or x > 4."},{"id":"u1-comp2-q8","type":"choice","prompt":"Solve: x − 1 ≤ 4 or x + 2 > 3","choices":["No solution","1 < x ≤ 5","x ≤ 5","All real numbers"],"answer":3,"hint":"Solve each part, then see whether the pieces overlap.","solution":"x − 1 ≤ 4 gives x ≤ 5. x + 2 > 3 gives x > 1. Every number is at most 5 or more than 1, so the answer is all real numbers."}]},{"id":"compound-3","teach":[{"title":"No solution","text":["With \"and\", if the two pieces do not overlap, no number works. The answer is no solution (the empty set).","Check: x > 6 and x < 1 would need a number above 6 and below 1 at once. That cannot happen."],"example":{"problem":"Solve 2x + 1 > 9 and x − 3 < −5","steps":["2x + 1 > 9 gives x > 4.","x − 3 < −5 gives x < −2.","No number is greater than 4 and less than −2, so there is no solution."]}},{"title":"All real numbers","text":["With \"or\", if the two pieces cover the whole number line, the answer is all real numbers, written (−∞, ∞).","For a chain a < expression < b, do the same step on all three parts. The interval notation is (a, b) with brackets where \"or equal to\" appears."],"example":{"problem":"Solve 4 < 2x − 2 ≤ 10","steps":["Add 2 to all three parts: 6 < 2x ≤ 12.","Divide by 2: 3 < x ≤ 6.","Interval: (3, 6]."]}}],"questions":[{"id":"u1-comp3-q1","type":"choice","prompt":"Solve: x > 6 and x < 1","choices":["No solution","6 < x < 1","All real numbers","x > 6 or x < 1"],"answer":0,"hint":"Is there a number above 6 that is also below 1?","solution":"No number is both greater than 6 and less than 1. So there is no solution."},{"id":"u1-comp3-q2","type":"choice","prompt":"Solve: x < 4 or x > 1","choices":["1 < x < 4","All real numbers","No solution","x < 1 or x > 4"],"answer":1,"hint":"Try a few numbers, such as 0, 2, and 5.","solution":"Any number is either less than 4 or greater than 1. Numbers like 2 are both. So all real numbers work."},{"id":"u1-comp3-q3","type":"choice","prompt":"Solve: 2x + 1 > 9 and x − 3 < −5","choices":["No solution","−2 < x < 4","x > 4","All real numbers"],"answer":0,"hint":"Solve each part. Then look for an overlap.","solution":"2x + 1 > 9 gives x > 4. x − 3 < −5 gives x < −2. They do not overlap, so there is no solution."},{"id":"u1-comp3-q4","type":"choice","prompt":"Solve: 3x − 2 ≤ 7 or x + 5 ≥ 2","choices":["−3 ≤ x ≤ 3","x ≤ 3 or x ≥ 3","All real numbers","No solution"],"answer":2,"hint":"Solve each part. Do the pieces overlap?","solution":"3x − 2 ≤ 7 gives x ≤ 3. x + 5 ≥ 2 gives x ≥ −3. The pieces overlap, so every number works: all real numbers."},{"id":"u1-comp3-q5","type":"choice","prompt":"Solve 4 < 2x − 2 ≤ 10. Which interval is the solution?","choices":["[3, 6)","(3, 6]","(6, 12]","(3, 6)"],"answer":1,"hint":"Add 2 to all three parts. Then divide by 2.","solution":"Add 2: 6 < 2x ≤ 12. Divide by 2: 3 < x ≤ 6. The left end is open and the right end is closed: (3, 6]."},{"id":"u1-comp3-q6","type":"choice","prompt":"Solve −9 ≤ 3x − 3 < 6. Which interval is the solution?","choices":["(−2, 3]","[−3, 3)","[−2, 3]","[−2, 3)"],"answer":3,"hint":"Add 3 to every part first.","solution":"Add 3: −6 ≤ 3x < 9. Divide by 3: −2 ≤ x < 3. Interval: [−2, 3)."},{"id":"u1-comp3-q7","type":"input","prompt":"What is the sum of all the integers that satisfy −2 ≤ x < 3?","answers":["0"],"hint":"List the integers. Is 3 included?","solution":"The integers are −2, −1, 0, 1, 2. Their sum is −2 + −1 + 0 + 1 + 2 = 0."},{"id":"u1-comp3-q8","type":"choice","prompt":"Which compound inequality has no solution?","choices":["x > 3 and x < −1","x > 3 or x < −1","x > −1 and x < 3","x > −1 or x < 3"],"answer":0,"hint":"Look for the one where the two pieces cannot overlap and both must be true.","solution":"\"x > 3 and x < −1\" needs a number above 3 and below −1 at the same time. That is impossible. The others have solutions."}]},{"id":"compound-4","teach":[{"title":"Translating words","text":["\"Between\" with no extra words means the ends are not included: 20 < t < 28. \"At least … and at most …\" includes the ends: 70 ≤ s ≤ 90.","\"Or\" situations, like a discount for kids under 12 or adults over 65, use two separate pieces."],"example":{"problem":"A pool is safe when its temperature T is at least 26° and at most 30°. Write an inequality.","steps":["\"At least 26\" means T ≥ 26.","\"At most 30\" means T ≤ 30.","Together: 26 ≤ T ≤ 30."]}},{"title":"Solve, then answer the question","text":["Write the compound inequality, solve it, and read what it says about the situation. Whole-number answers need a final check at each end."],"example":{"problem":"A taxi charges $4 plus $2 per mile. You want to spend between $10 and $20, ends included. How many miles?","steps":["10 ≤ 4 + 2m ≤ 20","Subtract 4: 6 ≤ 2m ≤ 16.","Divide by 2: 3 ≤ m ≤ 8.","You can go from 3 to 8 miles."]}}],"questions":[{"id":"u1-comp4-q1","type":"choice","prompt":"A score s must be at least 70 and at most 90. Which inequality is that?","choices":["70 ≤ s ≤ 90","70 < s < 90","s ≤ 70 or s ≥ 90","70 ≥ s ≥ 90"],"answer":0,"hint":"\"At least\" and \"at most\" include the ends.","solution":"At least 70 is s ≥ 70, and at most 90 is s ≤ 90. Together: 70 ≤ s ≤ 90."},{"id":"u1-comp4-q2","type":"choice","prompt":"Water must be strictly between 20 °C and 28 °C. Which inequality is that?","choices":["20 ≤ t ≤ 28","20 < t < 28","t < 20 or t > 28","20 < t ≤ 28"],"answer":1,"hint":"\"Strictly between\" does not include the ends.","solution":"Strictly between 20 and 28 means more than 20 and less than 28: 20 < t < 28."},{"id":"u1-comp4-q3","type":"choice","prompt":"A plan costs $15 plus $5 per hour. The total must be between $40 and $65, ends included. Which compound inequality models the hours h?","choices":["40 < 15 + 5h < 65","40 ≤ 5h ≤ 65","40 ≤ 15 + 5h ≤ 65","15 + 5h ≤ 40 or 15 + 5h ≥ 65"],"answer":2,"hint":"The total cost is 15 + 5h. It must stay inside the range.","solution":"The total cost is 15 + 5h. It must be at least 40 and at most 65, so 40 ≤ 15 + 5h ≤ 65."},{"id":"u1-comp4-q4","type":"input","prompt":"Using the plan above, 40 ≤ 15 + 5h ≤ 65, what is the most hours you can use?","answers":["10"],"hint":"Subtract 15 from all three parts. Then divide by 5.","solution":"Subtract 15: 25 ≤ 5h ≤ 50. Divide by 5: 5 ≤ h ≤ 10. The most is 10 hours."},{"id":"u1-comp4-q5","type":"input","prompt":"Skis rent for $12 plus $4 per hour. Joan wants to pay more than $20 and at most $36. How many different whole numbers of hours could she rent for?","answers":["4"],"hint":"Write 20 < 12 + 4h ≤ 36 and solve. Then list the whole numbers.","solution":"Subtract 12: 8 < 4h ≤ 24. Divide by 4: 2 < h ≤ 6. The whole numbers are 3, 4, 5, 6. That is 4 values."},{"id":"u1-comp4-q6","type":"choice","prompt":"A museum gives a discount to anyone under 12 or 65 and older. Which describes the ages a that get the discount?","choices":["12 < a < 65","a < 12 and a ≥ 65","a ≤ 12 or a > 65","a < 12 or a ≥ 65"],"answer":3,"hint":"This is \"or\": two separate pieces.","solution":"Under 12 is a < 12. 65 and older is a ≥ 65. A person is in one group or the other, so use \"or\"."},{"id":"u1-comp4-q7","type":"choice","prompt":"Solve: −5 < (x − 1)/2 < 3","choices":["(−9, 7)","(−11, 5)","(−9, 7]","(−4, 4)"],"answer":0,"hint":"Multiply all three parts by 2, then add 1.","solution":"Multiply by 2: −10 < x − 1 < 6. Add 1: −9 < x < 7. Interval: (−9, 7)."},{"id":"u1-comp4-q8","type":"input","prompt":"How many integers satisfy both 2x − 1 ≤ 7 and 3x + 2 > −4?","answers":["6"],"hint":"Solve each inequality. Then find the overlap.","solution":"2x − 1 ≤ 7 gives x ≤ 4. 3x + 2 > −4 gives 3x > −6, so x > −2. The solutions are −2 < x ≤ 4. The integers are −1, 0, 1, 2, 3, 4. That is 6."}]}]},{"id":"abs-equations","title":"Absolute value equations","lessons":[{"id":"abs-equations-1","teach":[{"title":"Absolute value means distance","text":["|x| is the distance of x from 0, so it is never negative. If |x| = 5, then x is 5 away from 0, so x = 5 or x = −5.","If the inside is more than just x, set it equal to the positive number and to the negative number."],"example":{"problem":"Solve |x| = 7","steps":["Distance 7 from zero gives two points.","x = 7 or x = −7."]}},{"title":"Two cases","text":["To solve |expression| = k with k > 0, solve expression = k and expression = −k."],"example":{"problem":"Solve |x − 3| = 4","steps":["Case 1: x − 3 = 4, so x = 7.","Case 2: x − 3 = −4, so x = −1.","Check: |7 − 3| = 4 and |−1 − 3| = 4. ✓"]}}],"questions":[{"id":"u1-abs1-q1","type":"input","prompt":"Solve: |x| = 9","answers":["9, -9"],"hint":"There are two numbers 9 away from zero.","solution":"x = 9 or x = −9."},{"id":"u1-abs1-q2","type":"choice","prompt":"Which equation has no solution?","choices":["|x| = −3","|x| = 0","|x| = 3","|x| = 1/3"],"answer":0,"hint":"An absolute value can never be negative.","solution":"|x| is a distance and cannot be −3. So |x| = −3 has no solution. The others have solutions."},{"id":"u1-abs1-q3","type":"input","prompt":"Solve: |x − 2| = 6","answers":["8, -4"],"hint":"Write x − 2 = 6 and x − 2 = −6.","solution":"Case 1: x − 2 = 6, so x = 8. Case 2: x − 2 = −6, so x = −4. Check: |8 − 2| = 6 and |−4 − 2| = 6. ✓"},{"id":"u1-abs1-q4","type":"input","prompt":"Solve: |x + 5| = 3","answers":["-2, -8"],"hint":"Two cases: x + 5 = 3 and x + 5 = −3.","solution":"Case 1: x + 5 = 3, so x = −2. Case 2: x + 5 = −3, so x = −8. Check: |−2 + 5| = 3 and |−8 + 5| = 3. ✓"},{"id":"u1-abs1-q5","type":"input","prompt":"Solve: |2x| = 14","answers":["7, -7"],"hint":"2x = 14 or 2x = −14.","solution":"Case 1: 2x = 14, so x = 7. Case 2: 2x = −14, so x = −7."},{"id":"u1-abs1-q6","type":"input","prompt":"Solve: |3x − 1| = 11","answers":["4, -10/3"],"hint":"Set 3x − 1 equal to 11 and to −11.","solution":"Case 1: 3x − 1 = 11, so 3x = 12 and x = 4. Case 2: 3x − 1 = −11, so 3x = −10 and x = −10/3. Check: |3(4) − 1| = 11 and |−10 − 1| = 11. ✓"},{"id":"u1-abs1-q7","type":"choice","prompt":"Which equation finds the numbers that are 5 units from 3 on the number line, and what are they?","choices":["|x − 3| = 5, so x = 8 or x = −2","|x − 3| = 5, so x = 8 or x = 2","|x + 3| = 5, so x = 2 or x = −8","|x − 5| = 3, so x = 8 or x = 2"],"answer":0,"hint":"Distance between x and 3 is |x − 3|.","solution":"The distance from x to 3 is |x − 3|, so |x − 3| = 5. Then x − 3 = 5 gives x = 8, and x − 3 = −5 gives x = −2."},{"id":"u1-abs1-q8","type":"input","prompt":"Solve: |4x + 8| = 12","answers":["1, -5"],"hint":"Write 4x + 8 = 12 and 4x + 8 = −12.","solution":"Case 1: 4x + 8 = 12, so 4x = 4 and x = 1. Case 2: 4x + 8 = −12, so 4x = −20 and x = −5. Check: |4 + 8| = 12 and |−20 + 8| = 12. ✓"}]},{"id":"abs-equations-2","teach":[{"title":"Isolate the absolute value first","text":["Before you split into two cases, get the absolute value expression alone on one side. Undo adding, subtracting, and multiplying outside the bars."],"example":{"problem":"Solve 2|x − 1| + 3 = 11","steps":["Subtract 3: 2|x − 1| = 8.","Divide by 2: |x − 1| = 4.","Case 1: x − 1 = 4, so x = 5. Case 2: x − 1 = −4, so x = −3."]}},{"title":"No solution and one solution","text":["After isolating, look at the other side. If it is negative, there is no solution. If it is 0, there is exactly one solution, because 0 and −0 are the same."],"example":{"problem":"Solve |x − 5| + 8 = 3","steps":["Subtract 8: |x − 5| = −5.","An absolute value cannot be negative, so there is no solution."]}}],"questions":[{"id":"u1-abs2-q1","type":"input","prompt":"Solve: |x| + 4 = 10","answers":["6, -6"],"hint":"Subtract 4 first.","solution":"|x| + 4 = 10. Subtract 4: |x| = 6. So x = 6 or x = −6."},{"id":"u1-abs2-q2","type":"input","prompt":"Solve: 3|x| = 21","answers":["7, -7"],"hint":"Divide both sides by 3 first.","solution":"3|x| = 21. Divide by 3: |x| = 7. So x = 7 or x = −7."},{"id":"u1-abs2-q3","type":"input","prompt":"Solve: 2|x − 4| = 10","answers":["9, -1"],"hint":"Isolate the bars: divide by 2.","solution":"Divide by 2: |x − 4| = 5. Case 1: x − 4 = 5, so x = 9. Case 2: x − 4 = −5, so x = −1."},{"id":"u1-abs2-q4","type":"input","prompt":"Solve: |x + 3| − 7 = 2","answers":["6, -12"],"hint":"Add 7 to both sides first.","solution":"Add 7: |x + 3| = 9. Case 1: x + 3 = 9, so x = 6. Case 2: x + 3 = −9, so x = −12."},{"id":"u1-abs2-q5","type":"input","prompt":"Solve: 5|2x − 1| + 3 = 28","answers":["3, -2"],"hint":"Subtract 3, then divide by 5. Then split into cases.","solution":"Subtract 3: 5|2x − 1| = 25. Divide by 5: |2x − 1| = 5. Case 1: 2x − 1 = 5, so x = 3. Case 2: 2x − 1 = −5, so x = −2. Check x = −2: |−5| = 5. ✓"},{"id":"u1-abs2-q6","type":"choice","prompt":"Solve: |x − 5| + 8 = 3","choices":["No solution","x = 0 only","x = 8 or x = 2","x = 0 or x = 10"],"answer":0,"hint":"Isolate the absolute value and look at the sign of the other side.","solution":"Subtract 8: |x − 5| = −5. An absolute value cannot equal a negative number, so there is no solution."},{"id":"u1-abs2-q7","type":"input","prompt":"Solve: −2|x| + 14 = 4","answers":["5, -5"],"hint":"Subtract 14. Then divide by −2.","solution":"Subtract 14: −2|x| = −10. Divide by −2: |x| = 5. So x = 5 or x = −5."},{"id":"u1-abs2-q8","type":"input","prompt":"Solve: |x − 6| + 9 = 9","answers":["6"],"hint":"After isolating, the right side is 0. How many cases are there?","solution":"Subtract 9: |x − 6| = 0. So x − 6 = 0, and x = 6. There is only one solution."}]},{"id":"abs-equations-3","teach":[{"title":"Absolute value on both sides","text":["If |A| = |B|, then A = B or A = −B. Solve both. Each solution can be checked by plugging it in."],"example":{"problem":"Solve |x + 3| = |2x − 6|","steps":["Case 1: x + 3 = 2x − 6, so x = 9.","Case 2: x + 3 = −(2x − 6) = −2x + 6, so 3x = 3 and x = 1.","Check x = 1: |4| = 4 and |−4| = 4. ✓"]}},{"title":"Variable outside the bars","text":["For |A| = expression, the right side must be 0 or more. Solve both cases, then check each answer in the original equation."],"example":{"problem":"Solve |2x − 1| = x + 4","steps":["Case 1: 2x − 1 = x + 4, so x = 5. Check: |9| = 9. ✓","Case 2: 2x − 1 = −(x + 4), so 3x = −3 and x = −1. Check: |−3| = 3 and −1 + 4 = 3. ✓","Both solutions work."]}}],"questions":[{"id":"u1-abs3-q1","type":"choice","prompt":"In |x − 3| = 2x + 1, what must be true about 2x + 1?","choices":["It must be 0 or positive","It must be negative","It must equal x − 3","It must be less than 1"],"answer":0,"hint":"The left side is an absolute value.","solution":"An absolute value is never negative, so the right side 2x + 1 must be 0 or more."},{"id":"u1-abs3-q2","type":"input","prompt":"Solve: |x − 1| = |x + 7|","answers":["-3"],"hint":"Case 1 gives a false statement. Use case 2: x − 1 = −(x + 7).","solution":"Case 1: x − 1 = x + 7 gives −1 = 7, which is false. Case 2: x − 1 = −x − 7, so 2x = −6 and x = −3. Check: |−4| = 4 and |4| = 4. ✓"},{"id":"u1-abs3-q3","type":"input","prompt":"Solve: |5x − 3| = |3x + 7|","answers":["5, -1/2"],"hint":"A = B or A = −B.","solution":"Case 1: 5x − 3 = 3x + 7, so 2x = 10 and x = 5. Case 2: 5x − 3 = −3x − 7, so 8x = −4 and x = −1/2. Check x = −1/2: |−5.5| = 5.5 and |5.5| = 5.5. ✓"},{"id":"u1-abs3-q4","type":"input","prompt":"Solve: |3x − 4| = x + 8","answers":["6, -1"],"hint":"Solve 3x − 4 = x + 8 and 3x − 4 = −(x + 8).","solution":"Case 1: 3x − 4 = x + 8, so 2x = 12 and x = 6. Case 2: 3x − 4 = −x − 8, so 4x = −4 and x = −1. Check x = 6: |14| = 14. Check x = −1: |−7| = 7 and −1 + 8 = 7. ✓"},{"id":"u1-abs3-q5","type":"input","prompt":"Solve: |4x − 3| = |2x + 9|","answers":["6, -1"],"hint":"Set the insides equal, then set one equal to the negative of the other.","solution":"Case 1: 4x − 3 = 2x + 9, so 2x = 12 and x = 6. Case 2: 4x − 3 = −2x − 9, so 6x = −6 and x = −1. Check x = 6: |21| = 21 and |21| = 21. Check x = −1: |−7| = 7 and |7| = 7. ✓"},{"id":"u1-abs3-q6","type":"choice","prompt":"Solve: |x + 5| = |x − 1|","choices":["x = −2","x = −3","x = 2","No solution"],"answer":0,"hint":"Case 1 gives a false statement. Use the negative case.","solution":"Case 1: x + 5 = x − 1 gives 5 = −1, false. Case 2: x + 5 = −x + 1, so 2x = −4 and x = −2. Check: |3| = 3 and |−3| = 3. ✓"},{"id":"u1-abs3-q7","type":"input","prompt":"Solve: |x + 2| = 3x − 2. Give only the value that works.","answers":["2"],"hint":"Both cases give a candidate. Test each in the original equation.","solution":"Case 1: x + 2 = 3x − 2, so x = 2. Check: |4| = 4 and 3(2) − 2 = 4. ✓ Case 2: x + 2 = −(3x − 2) = −3x + 2, so 4x = 0 and x = 0. Check: |2| = 2, but 3(0) − 2 = −2. ✗ Only x = 2 works."},{"id":"u1-abs3-q8","type":"choice","prompt":"Solve: |2x − 7| = |x − 1|","choices":["x = 6 or x = 3","x = 6 only","x = −6 or x = −8/3","x = 6 or x = 8/3"],"answer":3,"hint":"Use A = B and A = −B.","solution":"Case 1: 2x − 7 = x − 1, so x = 6. Case 2: 2x − 7 = −x + 1, so 3x = 8 and x = 8/3. Check x = 8/3: |16/3 − 7| = 5/3 and |8/3 − 1| = 5/3. ✓"}]},{"id":"abs-equations-4","teach":[{"title":"Extraneous solutions","text":["When a variable appears outside the bars, splitting into cases can create answers that do not actually work. These are extraneous. Always plug each answer back in."],"example":{"problem":"Solve |x − 6| = 2x","steps":["Case 1: x − 6 = 2x, so x = −6. Check: |−12| = 12 but 2(−6) = −12. ✗ Extraneous.","Case 2: x − 6 = −2x, so 3x = 6 and x = 2. Check: |−4| = 4 and 2(2) = 4. ✓","The only solution is x = 2."]}},{"title":"Writing absolute value equations","text":["Distance language gives an equation. \"Numbers 4 units from −2\" is |x − (−2)| = 4, or |x + 2| = 4. A tolerance, like \"within 0.3 of 12\", gives |L − 12| = 0.3 at the edge."],"example":{"problem":"Find the numbers 4 units from −2.","steps":["|x + 2| = 4.","Case 1: x + 2 = 4, so x = 2. Case 2: x + 2 = −4, so x = −6."]}}],"questions":[{"id":"u1-abs4-q1","type":"input","prompt":"Solve: |x − 4| = 3x. Give only valid solutions.","answers":["1"],"hint":"Solve both cases, then check each in the original equation.","solution":"Case 1: x − 4 = 3x, so x = −2. Check: |−6| = 6 but 3(−2) = −6. ✗. Case 2: x − 4 = −3x, so x = 1. Check: |−3| = 3 and 3(1) = 3. ✓ Only x = 1."},{"id":"u1-abs4-q2","type":"input","prompt":"Solve: |2x + 3| = x + 6","answers":["3, -3"],"hint":"Check both answers.","solution":"Case 1: 2x + 3 = x + 6, so x = 3. Check: |9| = 9. ✓ Case 2: 2x + 3 = −x − 6, so 3x = −9 and x = −3. Check: |−3| = 3 and −3 + 6 = 3. ✓ Both work."},{"id":"u1-abs4-q3","type":"input","prompt":"Solve: |x + 1| = 4x − 5. Give only valid solutions.","answers":["2"],"hint":"The right side must not be negative.","solution":"Case 1: x + 1 = 4x − 5, so x = 2. Check: |3| = 3 and 4(2) − 5 = 3. ✓ Case 2: x + 1 = −4x + 5, so 5x = 4 and x = 4/5. Check: 4(0.8) − 5 = −1.8 is negative. ✗ Only x = 2."},{"id":"u1-abs4-q4","type":"choice","prompt":"For |x + 3| = 2x + 9, the cases give x = −6 and x = −4. Which one is extraneous?","choices":["x = −6","x = −4","Both","Neither"],"answer":0,"hint":"Plug each value into the original equation. 2x + 9 cannot be negative.","solution":"x = −6: |−3| = 3 but 2(−6) + 9 = −3. ✗. x = −4: |−1| = 1 and 2(−4) + 9 = 1. ✓ So x = −6 is extraneous."},{"id":"u1-abs4-q5","type":"input","prompt":"Two numbers are each 6 units from −1. What are they?","answers":["5, -7"],"hint":"Write |x + 1| = 6.","solution":"|x − (−1)| = 6, so |x + 1| = 6. Case 1: x + 1 = 6, so x = 5. Case 2: x + 1 = −6, so x = −7."},{"id":"u1-abs4-q6","type":"input","prompt":"A bolt should be 8.5 cm long, give or take 0.2 cm. The two limit lengths solve |L − 8.5| = 0.2. What is the shorter limit, in centimeters?","answers":["8.3"],"hint":"Solve both cases and pick the smaller.","solution":"L − 8.5 = 0.2 gives L = 8.7. L − 8.5 = −0.2 gives L = 8.3. The shortest is 8.3 cm."},{"id":"u1-abs4-q7","type":"input","prompt":"Solve: 3|2x − 5| − 4 = 14","answers":["11/2, -1/2"],"hint":"Add 4, divide by 3, then use two cases.","solution":"Add 4: 3|2x − 5| = 18. Divide by 3: |2x − 5| = 6. Case 1: 2x − 5 = 6, so x = 11/2. Case 2: 2x − 5 = −6, so x = −1/2. Check x = −1/2: |−6| = 6. ✓"},{"id":"u1-abs4-q8","type":"input","prompt":"Solve: |7 − x| = 3x − 5. Give only valid solutions.","answers":["3"],"hint":"Check the right side for each candidate.","solution":"Case 1: 7 − x = 3x − 5, so 4x = 12 and x = 3. Check: |4| = 4 and 3(3) − 5 = 4. ✓ Case 2: 7 − x = −3x + 5, so 2x = −2 and x = −1. Check: 3(−1) − 5 = −8, which is negative. ✗ Only x = 3."}]}]},{"id":"abs-inequalities","title":"Absolute value inequalities","lessons":[{"id":"abs-inequalities-1","teach":[{"title":"Less than gives \"and\"","text":["|x| < a means x is within a of 0. That is between −a and a: −a < x < a.","Use ≤ the same way: |x| ≤ a means −a ≤ x ≤ a."],"example":{"problem":"Solve |x| < 4","steps":["Distance from 0 less than 4.","So −4 < x < 4.","Interval: (−4, 4)."]}},{"title":"Greater than gives \"or\"","text":["|x| > a means x is farther than a from 0. That is x < −a or x > a.","The two pieces point away from each other."],"example":{"problem":"Solve |x| ≥ 3","steps":["Distance from 0 at least 3.","x ≤ −3 or x ≥ 3.","Interval: (−∞, −3] ∪ [3, ∞)."]}}],"questions":[{"id":"u1-absi1-q1","type":"choice","prompt":"Which is the same as |x| < 6?","choices":["−6 < x < 6","x < −6 or x > 6","x < 6","−6 > x > 6"],"answer":0,"hint":"\"Less than\" keeps x close to 0.","solution":"|x| < 6 means x is less than 6 away from 0: −6 < x < 6."},{"id":"u1-absi1-q2","type":"choice","prompt":"Which is the same as |x| > 2?","choices":["−2 < x < 2","x < −2 or x > 2","x > 2","x < −2 and x > 2"],"answer":1,"hint":"\"Greater than\" means far from 0, on either side.","solution":"|x| > 2 means x is more than 2 away from 0. That is x < −2 or x > 2."},{"id":"u1-absi1-q3","type":"choice","prompt":"Which inequality describes numbers whose distance from 0 is at most 5?","choices":["|x| ≥ 5","|x| < 5","|x| ≤ 5","x ≤ 5"],"answer":2,"hint":"\"At most\" includes the end.","solution":"Distance from 0 is |x|. \"At most 5\" is |x| ≤ 5."},{"id":"u1-absi1-q4","type":"choice","prompt":"Write |x| ≤ 3 in interval notation.","choices":["[−3, 3]","(−3, 3)","(−∞, −3] ∪ [3, ∞)","[−3, 3)"],"answer":0,"hint":"|x| ≤ 3 means −3 ≤ x ≤ 3. Both ends are included.","solution":"|x| ≤ 3 gives −3 ≤ x ≤ 3, which is [−3, 3]."},{"id":"u1-absi1-q5","type":"input","prompt":"How many integers satisfy |x| < 4?","answers":["7"],"hint":"Rewrite as −4 < x < 4 and list the integers.","solution":"−4 < x < 4. The integers are −3, −2, −1, 0, 1, 2, 3. That is 7."},{"id":"u1-absi1-q6","type":"choice","prompt":"Write |x| > 8 in interval notation.","choices":["(−8, 8)","(−∞, −8] ∪ [8, ∞)","(8, ∞)","(−∞, −8) ∪ (8, ∞)"],"answer":3,"hint":"Two pieces, both with open ends because it is strict.","solution":"|x| > 8 gives x < −8 or x > 8. Use parentheses: (−∞, −8) ∪ (8, ∞)."},{"id":"u1-absi1-q7","type":"input","prompt":"What is the largest integer that satisfies |x| < 9?","answers":["8"],"hint":"Rewrite as −9 < x < 9.","solution":"−9 < x < 9. The ends are not included, so the largest integer is 8."},{"id":"u1-absi1-q8","type":"choice","prompt":"Which number is a solution of |x| > 5?","choices":["−6","−5","0","4"],"answer":0,"hint":"Find the distance from 0 for each number.","solution":"|−6| = 6, and 6 > 5, so −6 works. |−5| = 5 is not more than 5. |0| = 0 and |4| = 4 are not either."}]},{"id":"abs-inequalities-2","teach":[{"title":"Absolute value of an expression","text":["Treat the whole inside as one piece. |A| < k becomes −k < A < k. |A| > k becomes A < −k or A > k."],"example":{"problem":"Solve |x − 2| < 5","steps":["−5 < x − 2 < 5","Add 2 to all three parts: −3 < x < 7.","Interval: (−3, 7)."]}},{"title":"Isolate first","text":["Get the absolute value alone before you split. Dividing or multiplying by a negative number flips the sign."],"example":{"problem":"Solve 3|x − 1| + 2 < 14","steps":["Subtract 2: 3|x − 1| < 12.","Divide by 3: |x − 1| < 4.","−4 < x − 1 < 4, so −3 < x < 5."]}}],"questions":[{"id":"u1-absi2-q1","type":"choice","prompt":"Solve: |x − 3| < 4","choices":["−1 < x < 7","−7 < x < 1","x < −1 or x > 7","−1 < x < 1"],"answer":0,"hint":"Rewrite as −4 < x − 3 < 4, then add 3 to every part.","solution":"−4 < x − 3 < 4. Add 3: −1 < x < 7."},{"id":"u1-absi2-q2","type":"choice","prompt":"Solve: |x + 2| ≥ 5","choices":["−7 ≤ x ≤ 3","x ≤ −7 or x ≥ 3","x ≤ −3 or x ≥ 7","x ≤ −7 and x ≥ 3"],"answer":1,"hint":"Two pieces: x + 2 ≤ −5 or x + 2 ≥ 5.","solution":"x + 2 ≤ −5 gives x ≤ −7. x + 2 ≥ 5 gives x ≥ 3. The answer is x ≤ −7 or x ≥ 3."},{"id":"u1-absi2-q3","type":"choice","prompt":"Solve: |2x − 1| < 9","choices":["−5 < x < 4","−8 < x < 10","−4 < x < 5","x < −4 or x > 5"],"answer":2,"hint":"Write −9 < 2x − 1 < 9. Add 1, then divide by 2.","solution":"−9 < 2x − 1 < 9. Add 1: −8 < 2x < 10. Divide by 2: −4 < x < 5."},{"id":"u1-absi2-q4","type":"choice","prompt":"Solve: |3x + 2| > 7","choices":["x < −3 or x > 5/3","−3 < x < 5/3","x < −3 or x > 3","x < −5/3 or x > 3"],"answer":0,"hint":"Write 3x + 2 < −7 or 3x + 2 > 7.","solution":"3x + 2 < −7 gives 3x < −9, so x < −3. 3x + 2 > 7 gives 3x > 5, so x > 5/3. The answer is x < −3 or x > 5/3."},{"id":"u1-absi2-q5","type":"choice","prompt":"Solve |x − 5| ≤ 2. Which interval is the solution?","choices":["(3, 7)","[−7, −3]","(−∞, 3] ∪ [7, ∞)","[3, 7]"],"answer":3,"hint":"Rewrite as −2 ≤ x − 5 ≤ 2.","solution":"−2 ≤ x − 5 ≤ 2. Add 5: 3 ≤ x ≤ 7. Interval: [3, 7]."},{"id":"u1-absi2-q6","type":"input","prompt":"How many integers satisfy |x − 1| < 5?","answers":["9"],"hint":"Rewrite as −5 < x − 1 < 5 and solve for x.","solution":"−5 < x − 1 < 5. Add 1: −4 < x < 6. The integers are −3, −2, −1, 0, 1, 2, 3, 4, 5. That is 9."},{"id":"u1-absi2-q7","type":"choice","prompt":"Solve: 2|x + 1| < 10","choices":["−4 < x < 6","−6 < x < 4","−11 < x < 9","x < −6 or x > 4"],"answer":1,"hint":"Divide both sides by 2 before splitting.","solution":"Divide by 2: |x + 1| < 5. So −5 < x + 1 < 5. Subtract 1: −6 < x < 4."},{"id":"u1-absi2-q8","type":"choice","prompt":"Solve: |5x| ≥ 20","choices":["x ≤ −4 or x ≥ 4","−4 ≤ x ≤ 4","x ≤ −100 or x ≥ 100","x ≤ −4 and x ≥ 4"],"answer":0,"hint":"Write 5x ≤ −20 or 5x ≥ 20.","solution":"5x ≤ −20 gives x ≤ −4. 5x ≥ 20 gives x ≥ 4. The answer is x ≤ −4 or x ≥ 4."}]},{"id":"abs-inequalities-3","teach":[{"title":"Impossible and always true","text":["An absolute value is never negative. So |A| < negative number has no solution, and |A| > negative number is true for all real numbers.","Isolate the bars first, then look at the number on the other side."],"example":{"problem":"Solve |x + 1| < −2","steps":["The left side is never negative, so it can never be less than −2.","No solution."]}},{"title":"Flipping the sign","text":["If you divide by a negative while isolating, flip the inequality before you split."],"example":{"problem":"Solve −2|x| + 8 > 2","steps":["Subtract 8: −2|x| > −6.","Divide by −2 and flip: |x| < 3.","So −3 < x < 3."]}}],"questions":[{"id":"u1-absi3-q1","type":"choice","prompt":"Solve: |x + 1| < −2","choices":["No solution","All real numbers","−3 < x < 1","x < −3 or x > 1"],"answer":0,"hint":"Can an absolute value be less than a negative number?","solution":"An absolute value is always 0 or more, so it is never less than −2. There is no solution."},{"id":"u1-absi3-q2","type":"choice","prompt":"Solve: |x − 4| > −1","choices":["No solution","All real numbers","x > 5","x < 3 or x > 5"],"answer":1,"hint":"Can an absolute value ever be less than or equal to −1?","solution":"An absolute value is always at least 0, which is greater than −1. So every real number is a solution."},{"id":"u1-absi3-q3","type":"choice","prompt":"Solve: |2x − 3| + 5 < 2","choices":["No solution","All real numbers","−1/2 < x < 3/2","x < −3 or x > 0"],"answer":0,"hint":"Isolate the bars first.","solution":"Subtract 5: |2x − 3| < −3. An absolute value cannot be less than −3. No solution."},{"id":"u1-absi3-q4","type":"choice","prompt":"Solve: |x| + 6 ≥ 4","choices":["All real numbers","No solution","x ≥ −2","−2 ≤ x ≤ 2"],"answer":0,"hint":"Subtract 6 and look at the right side.","solution":"Subtract 6: |x| ≥ −2. An absolute value is always at least 0, which is more than −2. So all real numbers work."},{"id":"u1-absi3-q5","type":"choice","prompt":"Solve: 4|x − 1| − 3 ≤ 9","choices":["x ≤ −2 or x ≥ 4","−11 ≤ x ≤ 13","−2 ≤ x ≤ 4","−2 < x < 4"],"answer":2,"hint":"Add 3, then divide by 4.","solution":"Add 3: 4|x − 1| ≤ 12. Divide by 4: |x − 1| ≤ 3. So −3 ≤ x − 1 ≤ 3, and −2 ≤ x ≤ 4."},{"id":"u1-absi3-q6","type":"choice","prompt":"Solve: −2|x| + 8 > 2","choices":["x < −3 or x > 3","−3 < x < 3","−3 > x > 3","−4 < x < 4"],"answer":1,"hint":"Dividing by −2 flips the sign.","solution":"Subtract 8: −2|x| > −6. Divide by −2 and flip: |x| < 3. So −3 < x < 3."},{"id":"u1-absi3-q7","type":"input","prompt":"Solve: |x − 5| ≤ 0. What is x?","answers":["5"],"hint":"The only number with absolute value 0 or less is 0.","solution":"|x − 5| cannot be negative, so it must equal 0. Then x − 5 = 0, so x = 5."},{"id":"u1-absi3-q8","type":"choice","prompt":"Solve: |3x − 1| > 0","choices":["All real numbers","No solution","x = 1/3 only","All real numbers except x = 1/3"],"answer":3,"hint":"When is |3x − 1| equal to 0? Everything else works.","solution":"|3x − 1| is greater than 0 whenever 3x − 1 is not 0. 3x − 1 = 0 at x = 1/3. So every real number except 1/3 works."}]},{"id":"abs-inequalities-4","teach":[{"title":"Tolerance and \"within\"","text":["\"Within 5 of 340\" means the distance from 340 is at most 5: |w − 340| ≤ 5. This is the same as 335 ≤ w ≤ 345."],"example":{"problem":"A can must hold 350 mL, within 4 mL. Write and solve an absolute value inequality.","steps":["|v − 350| ≤ 4","−4 ≤ v − 350 ≤ 4","Add 350: 346 ≤ v ≤ 354."]}},{"title":"Writing from a graph or interval","text":["To write an absolute value inequality, find the midpoint m and the distance r from the midpoint to an end. Between the ends: |x − m| < r. Outside the ends: |x − m| > r."],"example":{"problem":"Write −2 < x < 6 as an absolute value inequality.","steps":["Midpoint: (−2 + 6)/2 = 2.","Distance from 2 to 6 is 4.","|x − 2| < 4."]}}],"questions":[{"id":"u1-absi4-q1","type":"choice","prompt":"A cereal box should weigh within 5 g of 340 g. Which inequality describes the weight w?","choices":["|w − 340| ≤ 5","|w + 340| ≤ 5","|w − 5| ≤ 340","|w − 340| ≥ 5"],"answer":0,"hint":"\"Within\" means close, so use ≤. The center is 340.","solution":"The distance from w to 340 is |w − 340|. It must be at most 5, so |w − 340| ≤ 5."},{"id":"u1-absi4-q2","type":"input","prompt":"A cereal box should satisfy |w − 340| ≤ 5. What is the smallest allowed weight in grams?","answers":["335"],"hint":"Solve −5 ≤ w − 340 ≤ 5.","solution":"−5 ≤ w − 340 ≤ 5. Add 340: 335 ≤ w ≤ 345. The smallest is 335 g."},{"id":"u1-absi4-q3","type":"choice","prompt":"Write −3 < x < 9 as an absolute value inequality.","choices":["|x − 3| < 6","|x + 3| < 6","|x − 3| < 9","|x − 6| < 3"],"answer":0,"hint":"Find the midpoint, then the distance to an end.","solution":"Midpoint: (−3 + 9)/2 = 3. Distance from 3 to 9 is 6. So |x − 3| < 6."},{"id":"u1-absi4-q4","type":"choice","prompt":"Write x ≤ −1 or x ≥ 7 as an absolute value inequality.","choices":["|x − 3| ≤ 4","|x + 3| ≥ 4","|x − 3| ≥ 4","|x − 4| ≥ 3"],"answer":2,"hint":"Midpoint of −1 and 7 first. \"Or\" with ends included uses ≥.","solution":"Midpoint: (−1 + 7)/2 = 3. Distance from 3 to 7 is 4. Outside the ends, with ends included: |x − 3| ≥ 4."},{"id":"u1-absi4-q5","type":"choice","prompt":"Solve: 3|2x + 1| − 6 ≥ 9","choices":["−3 ≤ x ≤ 2","x ≤ −3 or x ≥ 2","x ≤ −2 or x ≥ 3","x ≤ −3 and x ≥ 2"],"answer":1,"hint":"Add 6, divide by 3, then split into two pieces.","solution":"Add 6: 3|2x + 1| ≥ 15. Divide by 3: |2x + 1| ≥ 5. Then 2x + 1 ≤ −5 gives x ≤ −3, and 2x + 1 ≥ 5 gives x ≥ 2."},{"id":"u1-absi4-q6","type":"input","prompt":"A thermostat keeps the temperature T within 2° of 68°. How many whole-number temperatures are allowed?","answers":["5"],"hint":"Write |T − 68| ≤ 2 and list the integers.","solution":"|T − 68| ≤ 2 gives 66 ≤ T ≤ 70. The whole numbers are 66, 67, 68, 69, 70. That is 5."},{"id":"u1-absi4-q7","type":"choice","prompt":"Solve: −3|x + 2| > −12","choices":["x < −6 or x > 2","−2 < x < 6","−4 < x < 4","−6 < x < 2"],"answer":3,"hint":"Divide by −3 and flip the sign first.","solution":"Divide by −3 and flip: |x + 2| < 4. So −4 < x + 2 < 4. Subtract 2: −6 < x < 2."},{"id":"u1-absi4-q8","type":"input","prompt":"What is the largest integer that satisfies |2x − 5| < 7?","answers":["5"],"hint":"Write −7 < 2x − 5 < 7 and solve.","solution":"−7 < 2x − 5 < 7. Add 5: −2 < 2x < 12. Divide by 2: −1 < x < 6. The largest integer is 5."}]}]}],"test":{"questions":[{"id":"u1-t-q1","type":"choice","prompt":"Exactly one of these numbers is irrational. Which one?","choices":["√16","−5/8","√50","0.125"],"answer":2,"hint":"A rational number is a fraction of integers. Square roots of perfect squares are rational.","solution":"√16 = 4, −5/8 is a fraction, and 0.125 = 1/8. √50 is not a perfect square root, so it does not end or repeat. It is irrational."},{"id":"u1-t-q2","type":"choice","prompt":"Which property is shown by (2 · 9) · 5 = 2 · (9 · 5)?","choices":["Commutative property of multiplication","Associative property of multiplication","Distributive property","Identity property of multiplication"],"answer":1,"hint":"Look at what changed: the order of the numbers or the grouping?","solution":"The numbers stay in the same order. Only the parentheses move. That is the associative property."},{"id":"u1-t-q3","type":"input","prompt":"Evaluate without a calculator: −4² − 6 ÷ 3 + 5","answers":["-13"],"hint":"The exponent only applies to the 4. Then divide before you add or subtract.","solution":"−4² = −16 (the exponent hits only the 4). 6 ÷ 3 = 2. So −16 − 2 + 5 = −13.","calculator":false},{"id":"u1-t-q4","type":"input","prompt":"Evaluate 2a² − ab when a = −3 and b = 5.","answers":["33"],"hint":"Replace a with (−3). Square before you multiply by 2.","solution":"2(−3)² − (−3)(5) = 2(9) + 15 = 18 + 15 = 33."},{"id":"u1-t-q5","type":"choice","prompt":"Simplify 5(2x − 3) − 4(x − 6).","choices":["6x + 9","6x − 39","6x − 9","14x + 9"],"answer":0,"hint":"The minus sign in front of 4 changes the sign of both terms inside its group.","solution":"5(2x − 3) = 10x − 15. −4(x − 6) = −4x + 24. Add: 6x + 9."},{"id":"u1-t-q6","type":"choice","prompt":"A rectangle has sides 3x + 2 and x − 5. Which is its perimeter, simplified?","choices":["4x − 3","8x − 3","8x + 14","8x − 6"],"answer":3,"hint":"Perimeter = 2(length) + 2(width).","solution":"2(3x + 2) + 2(x − 5) = 6x + 4 + 2x − 10 = 8x − 6."},{"id":"u1-t-q7","type":"input","prompt":"Solve: 3(2x − 1) − 5 = 4x + 10","answers":["9"],"hint":"Distribute and combine like terms on the left first.","solution":"6x − 3 − 5 = 4x + 10. 6x − 8 = 4x + 10. 2x = 18. x = 9. Check: 3(17) − 5 = 46 and 4(9) + 10 = 46. ✓"},{"id":"u1-t-q8","type":"input","prompt":"Solve: x/2 − 3 = (x + 1)/4","answers":["13"],"hint":"Multiply every term by 4 to clear the fractions.","solution":"Multiply by 4: 2x − 12 = x + 1. So x = 13. Check: 6.5 − 3 = 3.5 and 14/4 = 3.5. ✓"},{"id":"u1-t-q9","type":"choice","prompt":"Solve 3x − 4y = 12 for y.","choices":["y = (3x − 12)/4","y = (12 − 3x)/4","y = (3x + 12)/4","y = 3x − 3"],"answer":0,"hint":"Move 3x first, then divide everything by −4.","solution":"Subtract 3x: −4y = 12 − 3x. Divide by −4: y = (3x − 12)/4, or y = 3x/4 − 3."},{"id":"u1-t-q10","type":"input","prompt":"Simple interest is I = Prt. Interest I = $180, principal P = $1500, and time t = 3 years. What is the annual rate r, as a percent?","answers":["4","4%"],"hint":"Solve for r first: r = I ÷ (Pt).","solution":"r = I/(Pt) = 180/(1500 · 3) = 180/4500 = 0.04. As a percent, r = 4%."},{"id":"u1-t-q11","type":"input","prompt":"The sum of three consecutive even integers is 126. What is the largest?","answers":["44"],"hint":"Use n, n + 2, n + 4.","solution":"n + (n + 2) + (n + 4) = 126. 3n + 6 = 126, so n = 40. The integers are 40, 42, 44. The largest is 44."},{"id":"u1-t-q12","type":"input","prompt":"A theater sold 85 tickets. Floor seats were $14 and balcony seats were $9. Sales were $955. How many balcony tickets were sold?","answers":["47"],"hint":"If f is the number of floor tickets, balcony tickets are 85 − f.","solution":"14f + 9(85 − f) = 955. 5f + 765 = 955, so f = 38. Balcony: 85 − 38 = 47. Check: 532 + 423 = 955. ✓"},{"id":"u1-t-q13","type":"input","prompt":"A coat is on sale for 35% off. Sam pays $39. What was the original price in dollars?","answers":["60"],"hint":"He pays 65% of the original price.","solution":"0.65x = 39, so x = 60. Check: 35% of 60 is 21, and 60 − 21 = 39. ✓"},{"id":"u1-t-q14","type":"input","prompt":"Solve: −5x + 2 < 27","answers":["x>-5","x>-5","-5<x","-5<x"],"hint":"Subtract 2, then divide by −5 and flip the sign.","solution":"−5x < 25. Divide by −5 and flip: x > −5."},{"id":"u1-t-q15","type":"choice","prompt":"Solve 3(x − 1) ≥ 7x + 9. Which interval is the solution?","choices":["(−∞, −3]","[−3, ∞)","(−∞, 3]","(−∞, −3)"],"answer":0,"hint":"Distribute, collect x terms, divide by −4 and flip.","solution":"3x − 3 ≥ 7x + 9. Subtract 7x: −4x − 3 ≥ 9. Add 3: −4x ≥ 12. Divide by −4 and flip: x ≤ −3. Interval: (−∞, −3]."},{"id":"u1-t-q16","type":"input","prompt":"A taxi costs $4 plus $1.50 per mile. You can spend at most $25. What is the most whole miles you can ride?","answers":["14"],"hint":"4 + 1.5m ≤ 25.","solution":"4 + 1.5m ≤ 25. 1.5m ≤ 21. m ≤ 14. The most is 14 miles."},{"id":"u1-t-q17","type":"choice","prompt":"Solve −3 < 2x + 1 ≤ 9. Which interval is the solution?","choices":["[−2, 4)","(−4, 8]","(−2, 4]","(−2, 4)"],"answer":2,"hint":"Subtract 1 from all three parts, then divide by 2.","solution":"Subtract 1: −4 < 2x ≤ 8. Divide by 2: −2 < x ≤ 4. Interval: (−2, 4]."},{"id":"u1-t-q18","type":"choice","prompt":"Solve: x + 4 ≤ −1 or 2x − 3 > 7","choices":["−5 ≤ x < 5","x ≤ −5 or x > 5","x ≥ −5 or x < 5","x ≤ −3 or x > 2"],"answer":1,"hint":"Solve each piece on its own.","solution":"x + 4 ≤ −1 gives x ≤ −5. 2x − 3 > 7 gives 2x > 10, so x > 5. The answer is x ≤ −5 or x > 5."},{"id":"u1-t-q19","type":"input","prompt":"Solve: |3x + 1| = 8","answers":["7/3, -3"],"hint":"Two cases: 3x + 1 = 8 and 3x + 1 = −8.","solution":"3x + 1 = 8 gives x = 7/3. 3x + 1 = −8 gives 3x = −9, so x = −3."},{"id":"u1-t-q20","type":"input","prompt":"Solve: 4|x − 2| − 5 = 15","answers":["7, -3"],"hint":"Add 5 and divide by 4 before you split.","solution":"Add 5: 4|x − 2| = 20. Divide by 4: |x − 2| = 5. Then x − 2 = 5 gives x = 7, and x − 2 = −5 gives x = −3."},{"id":"u1-t-q21","type":"input","prompt":"Solve: |x + 5| = 3x − 7. Give only the valid solution.","answers":["6"],"hint":"Check each candidate in the original equation.","solution":"Case 1: x + 5 = 3x − 7, so x = 6. Check: |11| = 11 and 3(6) − 7 = 11. ✓ Case 2: x + 5 = −3x + 7, so x = 1/2. Check: 3(1/2) − 7 is negative. ✗ Only x = 6."},{"id":"u1-t-q22","type":"choice","prompt":"Solve |2x − 4| < 6. Which interval is the solution?","choices":["(−1, 5)","(−5, 1)","(−∞, −1) ∪ (5, ∞)","(−1, 5]"],"answer":0,"hint":"Write −6 < 2x − 4 < 6.","solution":"−6 < 2x − 4 < 6. Add 4: −2 < 2x < 10. Divide by 2: −1 < x < 5. Interval: (−1, 5)."},{"id":"u1-t-q23","type":"choice","prompt":"Solve: 2|x + 1| − 3 ≥ 5","choices":["−5 ≤ x ≤ 3","x ≤ −3 or x ≥ 5","x ≤ −4 or x ≥ 4","x ≤ −5 or x ≥ 3"],"answer":3,"hint":"Add 3, divide by 2, then split into two pieces.","solution":"Add 3: 2|x + 1| ≥ 8. Divide by 2: |x + 1| ≥ 4. Then x + 1 ≤ −4 gives x ≤ −5, and x + 1 ≥ 4 gives x ≥ 3."}]}},{"format":1,"id":"unit-2-linear-functions-systems","title":"Unit 2: Linear Functions and Systems","levels":[{"id":"functions","title":"Relations and functions","lessons":[{"id":"functions-1","teach":[{"title":"Relations, domain, and range","text":["A relation is a set of ordered pairs (x, y). The domain is the set of all x-values (inputs). The range is the set of all y-values (outputs).","List each number once, in order, even if it repeats in the pairs."],"example":{"problem":"Find the domain and range of {(1, 4), (3, 4), (5, 9)}","steps":["Domain: the first numbers are 1, 3, 5. Domain = {1, 3, 5}.","Range: the second numbers are 4, 4, 9. List 4 once. Range = {4, 9}."]}},{"title":"What makes a function","text":["A function is a relation where every input has exactly one output.","Two different x-values may share a y-value. But one x-value may never be paired with two different y-values."],"example":{"problem":"Is {(2, 5), (3, 5), (4, 1)} a function?","steps":["Check each x-value: 2, 3, and 4 each appear once.","Each input has one output, so it is a function. The repeated y-value 5 is fine."]}}],"questions":[{"id":"u2-functions1-q1","type":"choice","prompt":"What is the domain of {(1, 2), (3, 4), (5, 6)}?","choices":["{1, 3, 5}","{2, 4, 6}","{1, 2, 3, 4, 5, 6}","{(1, 3, 5)}"],"answer":0,"hint":"The domain is the set of x-values, the first number in each pair.","solution":"The first numbers are 1, 3, and 5. The domain is {1, 3, 5}."},{"id":"u2-functions1-q2","calculator":false,"type":"input","prompt":"Relation: {(2, 5), (4, −1), (7, 3), (9, 0)}. What is the largest number in the range?","answers":["5"],"hint":"The range is the second number in each pair.","solution":"The range is {5, −1, 3, 0}. The largest is 5."},{"id":"u2-functions1-q3","type":"choice","prompt":"Is {(1, 3), (2, 3), (4, 3)} a function?","choices":["No, because the y-value 3 repeats","Yes, because every x-value has exactly one y-value","No, because the x-values are not consecutive","Yes, but only because the y-values are all positive"],"answer":1,"hint":"Look at the x-values. Does any x-value appear twice?","solution":"The x-values 1, 2, and 4 each appear once, so each has exactly one output. It is a function. Repeating y-values is allowed."},{"id":"u2-functions1-q4","type":"choice","prompt":"Is {(2, 1), (2, 4), (3, 5)} a function?","choices":["Yes, because there are three pairs","No, because x = 2 is paired with two different y-values","Yes, because the y-values are all different","No, because y = 1 and y = 4 differ by 3"],"answer":1,"hint":"Check whether any input shows up more than once with different outputs.","solution":"The input 2 is paired with both 1 and 4. One input with two outputs means it is not a function."},{"id":"u2-functions1-q5","type":"input","prompt":"Relation: {(−3, 4), (0, 4), (5, −2), (8, 1)}. Find the sum of all the numbers in the domain.","answers":["10"],"hint":"The domain uses the x-values only.","solution":"Domain = {−3, 0, 5, 8}. Sum: −3 + 0 + 5 + 8 = 10."},{"id":"u2-functions1-q6","type":"choice","prompt":"Which relation is NOT a function?","choices":["{(1, 2), (2, 3), (3, 4)}","{(0, 5), (1, 5), (2, 5)}","{(4, 1), (5, 2), (4, 3)}","{(−1, 0), (0, −1), (1, 0)}"],"answer":2,"hint":"Hunt for an x-value that appears twice with different y-values.","solution":"In {(4, 1), (5, 2), (4, 3)}, the input 4 goes to both 1 and 3. The other three have all different x-values, so they are functions."},{"id":"u2-functions1-q7","type":"input","prompt":"{(1, 4), (2, 6), (3, 8)} is a function. You add the pair (2, k) and it must still be a function. What must k be?","answers":["6"],"hint":"The input 2 already has an output.","solution":"The input 2 is already paired with 6. For it to stay a function, 2 can only have the output 6. So k = 6."},{"id":"u2-functions1-q8","type":"choice","prompt":"What is the range of {(0, 0), (1, 1), (2, 4), (3, 9)}?","choices":["{0, 1, 2, 3}","{1, 4, 9}","{0, 1, 2, 3, 4, 9}","{0, 1, 4, 9}"],"answer":3,"hint":"The range is the y-values. Include the 0.","solution":"The second numbers are 0, 1, 4, 9. The range is {0, 1, 4, 9}."}]},{"id":"functions-2","teach":[{"title":"Mapping diagrams","text":["A mapping diagram draws arrows from each input to its output. Here we write the arrows as 2 → 5.","It is a function when every input has exactly one arrow leaving it. Two inputs can point to the same output."],"example":{"problem":"Mapping: 1 → 6, 2 → 6, 3 → 9. Is it a function?","steps":["Each input 1, 2, 3 has exactly one arrow.","Two inputs sharing the output 6 is allowed.","It is a function. Domain {1, 2, 3}, range {6, 9}."]}},{"title":"Tables","text":["A table is a list of ordered pairs. Read each column pair as (x, y).","Look down the x column. If an x-value repeats with different y-values, it is not a function."],"example":{"problem":"x: 1, 2, 3, 2 and y: 4, 5, 6, 7. Is it a function?","steps":["The pairs are (1, 4), (2, 5), (3, 6), (2, 7).","The input 2 has outputs 5 and 7.","Not a function."]}}],"questions":[{"id":"u2-functions2-q1","type":"choice","prompt":"Mapping: 1 → 4, 2 → 4, 3 → 7. Is this a function?","choices":["No, because 4 is used twice","Yes, because each input has exactly one arrow","No, because the outputs are not in order","Yes, but only if 3 → 4 too"],"answer":1,"hint":"Count the arrows leaving each input, not the arrows entering each output.","solution":"Inputs 1, 2, and 3 each have one arrow. Two inputs sharing an output is allowed. It is a function."},{"id":"u2-functions2-q2","type":"choice","prompt":"Mapping: 1 → 4, 1 → 6, 2 → 7. Is this a function?","choices":["Yes, because each output appears once","Yes, because there are three arrows","No, because the input 1 has two arrows","No, because 4 and 6 are different"],"answer":2,"hint":"Does any input have more than one arrow?","solution":"The input 1 goes to both 4 and 6. An input with two outputs means it is not a function."},{"id":"u2-functions2-q3","calculator":false,"type":"input","prompt":"Table: x = −2, −1, 0, 1 and y = 5, 3, 1, −1. What y-value goes with x = 0?","answers":["1"],"hint":"Find x = 0 in the top row, then read the y-value in the same column.","solution":"The pairs are (−2, 5), (−1, 3), (0, 1), (1, −1). With x = 0, y = 1."},{"id":"u2-functions2-q4","type":"choice","prompt":"Table: x = 1, 2, 3, 2 and y = 5, 6, 7, 8. Is it a function?","choices":["Yes, because all the y-values are different","No, because x = 2 has two different y-values, 6 and 8","No, because the x-values are not in order","Yes, because there are four pairs"],"answer":1,"hint":"Write out the pairs. Which x-value repeats?","solution":"Pairs: (1, 5), (2, 6), (3, 7), (2, 8). The input 2 gives both 6 and 8, so it is not a function."},{"id":"u2-functions2-q5","type":"input","prompt":"Mapping: 2 → 9, 4 → 9, 6 → 1, 8 → 3. How many different numbers are in the range?","answers":["3"],"hint":"Count each output once, even if two arrows land on it.","solution":"The outputs are 9, 9, 1, 3. The different ones are 9, 1, 3. That is 3 numbers."},{"id":"u2-functions2-q6","type":"choice","prompt":"Table: x = 4, 7, 7, 10 and y = 1, 2, 3, 4. What is the domain?","choices":["{4, 7, 10}","{4, 7, 7, 10}","{1, 2, 3, 4}","{1, 2, 3, 4, 7, 10}"],"answer":0,"hint":"The domain is the x-values. Do not list a value twice.","solution":"The x-values are 4, 7, 7, 10. List 7 once. The domain is {4, 7, 10}."},{"id":"u2-functions2-q7","type":"choice","prompt":"Table: x = 2, 5, 8, k and y = 1, 4, 4, 0. Which value of k makes this table NOT a function?","choices":["k = 3","k = 9","k = 5","k = 12"],"answer":2,"hint":"You need k to match an x-value already in the table, with a different y-value.","solution":"With k = 5, the pairs are (5, 4) and (5, 0). The input 5 has two outputs, so it is not a function. The other choices are new x-values."},{"id":"u2-functions2-q8","type":"choice","prompt":"Which table represents a function? (Each table lists x, then y.)","choices":["x: 1, 2, 1 and y: 3, 4, 5","x: 2, 3, 4 and y: 6, 6, 6","x: 0, 5, 0 and y: 2, 3, 4","x: 7, 8, 7 and y: 1, 2, 3"],"answer":1,"hint":"Rule out any table with an x-value that appears twice with different y-values.","solution":"The first table has (1, 3) and (1, 5). The third has (0, 2) and (0, 4). The fourth has (7, 1) and (7, 3). Only x: 2, 3, 4 and y: 6, 6, 6 has all different inputs, so it is the function."}]},{"id":"functions-3","teach":[{"title":"Vertical line test","text":["If any vertical line crosses a graph in more than one point, that x-value has two outputs. The graph is not a function.","If every vertical line crosses at most once, it is a function."],"example":{"problem":"Does y = x² pass the vertical line test?","steps":["Picture any vertical line, like x = 2. It crosses the parabola once, at (2, 4).","Every vertical line crosses once, so it is a function."]}},{"title":"Domain and range from a graph","text":["Domain: how far left and right the graph goes. Range: how far down and up it goes.","A line that goes on forever in both directions has domain and range of all real numbers."],"example":{"problem":"Find the range of y = |x|","steps":["The graph is a V with its point at (0, 0).","The lowest y-value is 0 and it goes up forever.","Range: y ≥ 0. Domain: all real numbers."]}}],"questions":[{"id":"u2-functions3-q1","type":"choice","prompt":"Does this graph pass the vertical line test? What does that tell you?","graph":{"fn":"x^2","x":[-5,5],"y":[-2,10]},"choices":["Yes, it is a function","No, it is not a function","Yes, but only on one side of the y-axis","It is a relation but cannot be a function"],"answer":0,"hint":"Imagine a vertical line sliding across. Does it ever hit the curve twice?","solution":"Every vertical line crosses the parabola exactly once. It passes the test, so it is a function."},{"id":"u2-functions3-q2","type":"choice","prompt":"What is the range of the graphed function?","graph":{"fn":"abs(x)","x":[-6,6],"y":[-2,8]},"choices":["y ≥ 0","All real numbers","y ≤ 0","x ≥ 0"],"answer":0,"hint":"Range is about y. What is the lowest point of the V?","solution":"The lowest point is (0, 0). The graph goes up forever. The range is y ≥ 0."},{"id":"u2-functions3-q3","type":"choice","prompt":"The graph is a straight line that continues forever in both directions. What are its domain and range?","graph":{"fn":"2*x - 3","x":[-6,6],"y":[-10,10]},"choices":["Domain all real numbers, range y ≥ −3","Domain x ≥ 0, range all real numbers","Domain and range are both all real numbers","Domain x ≠ 0, range y ≠ −3"],"answer":2,"hint":"A non-horizontal line keeps going left, right, up, and down.","solution":"The line extends forever in both directions and covers every y-value. Domain and range are both all real numbers."},{"id":"u2-functions3-q4","type":"input","prompt":"What is the lowest y-value on the graph of y = x² − 4?","graph":{"fn":"x^2 - 4","x":[-5,5],"y":[-6,8]},"answers":["-4"],"hint":"Look at the bottom of the curve, the vertex.","solution":"The vertex is at (0, −4). The curve opens up, so −4 is the lowest y-value. The range is y ≥ −4."},{"id":"u2-functions3-q5","type":"choice","prompt":"What is the domain of y = √x shown in the graph?","graph":{"fn":"sqrt(x)","x":[-3,10],"y":[-2,6]},"choices":["All real numbers","x ≤ 0","x > 0","x ≥ 0"],"answer":3,"hint":"Domain is about x. Where does the graph start, and does it include that point?","solution":"The graph starts at (0, 0), which is included, and goes right forever. The domain is x ≥ 0."},{"id":"u2-functions3-q6","type":"input","prompt":"The range of y = −x² + 9 is y ≤ k. What is k?","graph":{"fn":"-x^2 + 9","x":[-5,5],"y":[-6,11]},"answers":["9"],"hint":"This parabola opens down. Find the highest point.","solution":"The vertex (0, 9) is the highest point and the curve opens down. The range is y ≤ 9, so k = 9."},{"id":"u2-functions3-q7","type":"choice","prompt":"A vertical line crosses a graph at two different points. What does this mean?","choices":["The graph is a function with a repeated output","The graph is not a function","The graph has no domain","The graph is a function with a repeated input"],"answer":1,"hint":"A vertical line sits at one x-value.","solution":"A vertical line fixes one x-value. Two crossing points means that x has two different y-values. So the graph is not a function."},{"id":"u2-functions3-q8","type":"choice","prompt":"What is the domain of the graphed function y = 1/x?","graph":{"fn":"1/x","x":[-5,5],"y":[-5,5]},"choices":["x ≠ 0","All real numbers","x > 0","y ≠ 0"],"answer":0,"hint":"The curve never touches the y-axis. Which x-value is missing?","solution":"There is no point with x = 0, because you cannot divide by zero. The domain is every real number except 0, so x ≠ 0."}]},{"id":"functions-4","teach":[{"title":"Functions from rules and situations","text":["An equation is a function if each x gives only one y. Equations like y = 2x + 1 are functions. A vertical line like x = 4 is not.","If a rule is given with a domain, plug in each domain value to find the range."],"example":{"problem":"Domain {−1, 0, 2} and rule y = 3x − 1. Find the range.","steps":["x = −1: y = 3(−1) − 1 = −4.","x = 0: y = −1.","x = 2: y = 6 − 1 = 5.","Range = {−4, −1, 5}."]}}],"questions":[{"id":"u2-functions4-q1","type":"choice","prompt":"Which equation does NOT describe y as a function of x?","choices":["y = 2x − 5","y = x² + 1","x = 4","y = |x|"],"answer":2,"hint":"Think about the graph. Which one is a vertical line?","solution":"x = 4 is a vertical line. The x-value 4 is paired with every y, so it fails the vertical line test. The other three give one y for each x."},{"id":"u2-functions4-q2","type":"choice","prompt":"What is the range of y = x² − 1?","choices":["All real numbers","y ≥ −1","y ≤ −1","y ≥ 1"],"answer":1,"hint":"x² is never negative. What is the smallest value of x² − 1?","solution":"The smallest x² is 0, giving y = −1. Everything above is reachable. The range is y ≥ −1."},{"id":"u2-functions4-q3","type":"input","prompt":"A taxi charges $3 plus $2 per mile. The domain is the whole-number miles 0, 1, 2, 3, 4, 5. How many ordered pairs are in this function?","answers":["6"],"hint":"There is one pair for each domain value. Count them carefully, starting at 0.","solution":"Each of the six inputs 0, 1, 2, 3, 4, 5 gives one pair, such as (0, 3), (1, 5), and so on. That is 6 pairs."},{"id":"u2-functions4-q4","type":"input","prompt":"A function has domain {−2, −1, 0, 1, 2} and rule y = x². How many different numbers are in its range?","answers":["3"],"hint":"Square each value. Some give the same result.","solution":"(−2)² = 4, (−1)² = 1, 0² = 0, 1² = 1, 2² = 4. The range is {0, 1, 4}, which has 3 numbers."},{"id":"u2-functions4-q5","type":"choice","prompt":"Domain {−1, 0, 1, 2} and rule y = 2x + 1. What is the range?","choices":["{−2, 0, 2, 4}","{−1, 0, 1, 2}","{−1, 1, 3, 5}","{−3, −1, 1, 3}"],"answer":2,"hint":"Plug in each x-value: double it, then add 1.","solution":"x = −1: −2 + 1 = −1. x = 0: 1. x = 1: 3. x = 2: 5. Range = {−1, 1, 3, 5}."},{"id":"u2-functions4-q6","type":"choice","prompt":"Which situation is a function of the first quantity?","choices":["Each student paired with each of their siblings","Each parent paired with their children","Each birthday paired with the students born that day","Each student paired with their date of birth"],"answer":3,"hint":"A function needs exactly one output for each input.","solution":"A student has one date of birth, so that is a function. A student can have several siblings, a parent several children, and one date several students. Those give more than one output."},{"id":"u2-functions4-q7","type":"input","prompt":"A function follows the rule y = 2x + 3 and includes the pairs (1, 5), (2, 7), (3, 9), and (k, 11). Find k.","answers":["4"],"hint":"Set 2k + 3 equal to 11.","solution":"2k + 3 = 11, so 2k = 8 and k = 4. Check: 2(4) + 3 = 11."},{"id":"u2-functions4-q8","type":"choice","prompt":"What are the domain and range of {(−2, 4), (0, 0), (2, 4)}?","choices":["Domain {−2, 0, 2}, range {0, 4}","Domain {−2, 0, 2}, range {4, 0, 4}","Domain {0, 4}, range {−2, 0, 2}","Domain {−2, 2}, range {0, 4}"],"answer":0,"hint":"Domain is x, range is y. List repeats once.","solution":"x-values: −2, 0, 2. y-values: 4, 0, 4, so the range lists 4 once: {0, 4}."}]}]},{"id":"function-notation","title":"Function notation","lessons":[{"id":"function-notation-1","teach":[{"title":"Reading f(x)","text":["f(x) is read 'f of x'. It is the output of the function f when the input is x. It does not mean f times x.","To find f(4), replace every x in the rule with 4 and simplify."],"example":{"problem":"If f(x) = 2x + 3, find f(4).","steps":["Replace x with 4: f(4) = 2(4) + 3.","Multiply: 8 + 3 = 11.","f(4) = 11. The point (4, 11) is on the graph."]}},{"title":"Negative inputs and squares","text":["Put a negative input in parentheses so the signs stay right.","In x², the square applies to the whole input: (−3)² = 9, not −9."],"example":{"problem":"If g(x) = x² − 4x, find g(−3).","steps":["g(−3) = (−3)² − 4(−3).","= 9 + 12.","g(−3) = 21."]}}],"questions":[{"id":"u2-fn1-q1","calculator":false,"type":"input","prompt":"If f(x) = 3x + 2, find f(4).","answers":["14"],"hint":"Replace x with 4, then multiply before adding.","solution":"f(4) = 3(4) + 2 = 12 + 2 = 14."},{"id":"u2-fn1-q2","calculator":false,"type":"input","prompt":"If f(x) = 5 − 2x, find f(3).","answers":["-1"],"hint":"Multiply 2 by 3 first, then subtract from 5.","solution":"f(3) = 5 − 2(3) = 5 − 6 = −1."},{"id":"u2-fn1-q3","type":"choice","prompt":"What does f(4) = 9 tell you?","choices":["When the input is 9, the output is 4","f times 4 equals 9","When the input is 4, the output is 9","The function f has a slope of 9"],"answer":2,"hint":"The number inside the parentheses is the input.","solution":"f(4) = 9 means input 4 gives output 9. The point (4, 9) is on the graph."},{"id":"u2-fn1-q4","calculator":false,"type":"input","prompt":"If g(x) = x² − 4x, find g(−2).","answers":["12"],"hint":"(−2)² is positive. Then −4 times −2 is also positive.","solution":"g(−2) = (−2)² − 4(−2) = 4 + 8 = 12."},{"id":"u2-fn1-q5","type":"choice","prompt":"If f(x) = 4x − 1, which is f(−2)?","choices":["−7","−9","7","−8"],"answer":1,"hint":"4 times −2 is −8. Then subtract 1.","solution":"f(−2) = 4(−2) − 1 = −8 − 1 = −9."},{"id":"u2-fn1-q6","type":"input","prompt":"If h(x) = 2x² − x + 1, find h(−3).","answers":["22"],"hint":"Square −3 first, then double it. Careful with −(−3).","solution":"h(−3) = 2(−3)² − (−3) + 1 = 2(9) + 3 + 1 = 18 + 3 + 1 = 22."},{"id":"u2-fn1-q7","type":"input","prompt":"If f(x) = x² + 1, find f(2) + f(−2).","answers":["10"],"hint":"Find each value separately, then add.","solution":"f(2) = 4 + 1 = 5. f(−2) = 4 + 1 = 5. Sum: 5 + 5 = 10."},{"id":"u2-fn1-q8","type":"input","prompt":"If p(x) = −x² + 3x, find p(4).","answers":["-4"],"hint":"−x² means the negative of (x squared). Find 4² first.","solution":"p(4) = −(4²) + 3(4) = −16 + 12 = −4."}]},{"id":"function-notation-2","teach":[{"title":"Plugging in an expression","text":["The input can be a letter or an expression. Replace every x with the whole expression, in parentheses.","Then simplify. Use the distributive property when needed."],"example":{"problem":"If f(x) = 2x + 3, find f(a + 1).","steps":["Replace x with (a + 1): f(a + 1) = 2(a + 1) + 3.","Distribute: 2a + 2 + 3.","f(a + 1) = 2a + 5."]}},{"title":"Function of a function","text":["In f(g(x)), work from the inside out. Find g first, then put that result into f."],"example":{"problem":"f(x) = x + 4 and g(x) = 2x. Find g(f(1)).","steps":["Inside first: f(1) = 1 + 4 = 5.","Then g(5) = 2(5) = 10."]}}],"questions":[{"id":"u2-fn2-q1","type":"choice","prompt":"If f(x) = 3x − 2, what is f(a + 1)?","choices":["3a − 1","3a − 5","3a + 3","3a + 1"],"answer":3,"hint":"Use parentheses: 3(a + 1) − 2.","solution":"f(a + 1) = 3(a + 1) − 2 = 3a + 3 − 2 = 3a + 1."},{"id":"u2-fn2-q2","type":"choice","prompt":"If f(x) = x², what is f(x + 2)?","choices":["x² + 4","x² + 2","x² + 4x + 4","x² + 2x + 4"],"answer":2,"hint":"Square the whole (x + 2). Remember (x + 2)² = (x + 2)(x + 2).","solution":"f(x + 2) = (x + 2)² = (x + 2)(x + 2) = x² + 2x + 2x + 4 = x² + 4x + 4."},{"id":"u2-fn2-q3","type":"input","prompt":"f(x) = 2x − 1. The difference f(k) − f(k − 1) is a number. What is it?","answers":["2"],"hint":"Find f(k) and f(k − 1) separately. Distribute carefully in the second.","solution":"f(k) = 2k − 1. f(k − 1) = 2(k − 1) − 1 = 2k − 3. The difference: (2k − 1) − (2k − 3) = 2."},{"id":"u2-fn2-q4","type":"choice","prompt":"If f(x) = 2x + 5, what is f(−x)?","choices":["−2x − 5","2x + 5","−2x + 5","2x − 5"],"answer":2,"hint":"Replace x with −x. Only the x term changes sign.","solution":"f(−x) = 2(−x) + 5 = −2x + 5. The +5 does not change."},{"id":"u2-fn2-q5","type":"input","prompt":"g(x) = x + 4 and h(x) = 2x. Find h(g(3)).","answers":["14"],"hint":"Work from the inside: g(3) first.","solution":"g(3) = 3 + 4 = 7. Then h(7) = 2(7) = 14."},{"id":"u2-fn2-q6","type":"choice","prompt":"If f(x) = x² − x, what is f(2a)?","choices":["2a² − 2a","4a² − 2a","4a² − a","2a² − a"],"answer":1,"hint":"(2a)² = 4a². The 2 gets squared too.","solution":"f(2a) = (2a)² − (2a) = 4a² − 2a."},{"id":"u2-fn2-q7","type":"input","prompt":"f(x) = 3x + 1. Then f(x + h) − f(x) = kh for a number k. Find k.","answers":["3"],"hint":"Expand f(x + h) first. Then subtract f(x).","solution":"f(x + h) = 3(x + h) + 1 = 3x + 3h + 1. Subtract f(x) = 3x + 1: the result is 3h. So k = 3."},{"id":"u2-fn2-q8","type":"input","prompt":"If f(x) = x² + x, find f(3) − f(−3).","answers":["6"],"hint":"f(−3) = 9 + (−3). Evaluate each, then subtract.","solution":"f(3) = 9 + 3 = 12. f(−3) = 9 − 3 = 6. Difference: 12 − 6 = 6."}]},{"id":"function-notation-3","teach":[{"title":"Solving f(x) = k","text":["f(x) = k asks: which input x gives the output k? Set the rule equal to k and solve for x.","If x is squared, take the square root and remember both the positive and negative answers."],"example":{"problem":"If f(x) = 2x + 7, find x when f(x) = 15.","steps":["Set 2x + 7 = 15.","Subtract 7: 2x = 8.","Divide by 2: x = 4.","Check: f(4) = 8 + 7 = 15."]}}],"questions":[{"id":"u2-fn3-q1","type":"input","prompt":"If f(x) = 2x + 7 and f(x) = 21, find x.","answers":["7"],"hint":"Write 2x + 7 = 21 and undo the + 7 first.","solution":"2x + 7 = 21. Subtract 7: 2x = 14. Divide by 2: x = 7."},{"id":"u2-fn3-q2","type":"input","prompt":"If f(x) = 5x − 3 and f(x) = 22, find x.","answers":["5"],"hint":"Add 3 to both sides first.","solution":"5x − 3 = 22. Add 3: 5x = 25. Divide by 5: x = 5."},{"id":"u2-fn3-q3","type":"input","prompt":"If f(x) = −3x + 4 and f(x) = −11, find x.","answers":["5"],"hint":"Subtract 4, then divide by −3.","solution":"−3x + 4 = −11. Subtract 4: −3x = −15. Divide by −3: x = 5."},{"id":"u2-fn3-q4","type":"input","prompt":"If f(x) = x/2 + 1 and f(x) = 6, find x.","answers":["10"],"hint":"Subtract 1, then multiply both sides by 2.","solution":"x/2 + 1 = 6. Subtract 1: x/2 = 5. Multiply by 2: x = 10."},{"id":"u2-fn3-q5","type":"input","prompt":"If f(x) = x² and f(x) = 36, find every x that works.","answers":["6, -6"],"hint":"Two numbers have a square of 36.","solution":"x² = 36. Take square roots: x = 6 or x = −6. Both give 36 when squared."},{"id":"u2-fn3-q6","type":"input","prompt":"If f(x) = x² − 5 and f(x) = 20, find every x that works.","answers":["5, -5"],"hint":"Add 5 to both sides first. Then take the square root.","solution":"x² − 5 = 20. Add 5: x² = 25. So x = 5 or x = −5."},{"id":"u2-fn3-q7","type":"choice","prompt":"f(x) = 4x − 9. Which equation do you solve to find a when f(a) = 3?","choices":["4(3) − 9 = a","4a − 9 = 3","4a − 9 = a","4 − 9a = 3"],"answer":1,"hint":"The output f(a) is 3. The input is the unknown a.","solution":"f(a) = 4a − 9. Setting the output equal to 3 gives 4a − 9 = 3. Solving: 4a = 12, a = 3."},{"id":"u2-fn3-q8","type":"input","prompt":"If f(x) = (2x − 1)/3 and f(x) = 5, find x.","answers":["8"],"hint":"Multiply both sides by 3 first.","solution":"(2x − 1)/3 = 5. Multiply by 3: 2x − 1 = 15. Add 1: 2x = 16. Divide by 2: x = 8. Check: (16 − 1)/3 = 5."}]},{"id":"function-notation-4","teach":[{"title":"Reading values from graphs and tables","text":["To find f(a) on a graph, go to x = a and read the height of the curve. To solve f(x) = k, go to height k and read the x-value.","In a table, f(a) is the y-value in the column where x = a."],"example":{"problem":"Table: x = 0, 1, 2 and f(x) = 6, 4, 2. Find f(1) and solve f(x) = 2.","steps":["f(1): the column with x = 1 has y = 4. So f(1) = 4.","f(x) = 2: the column with y = 2 has x = 2. So x = 2."]}}],"questions":[{"id":"u2-fn4-q1","type":"input","prompt":"Using the graph of f, find f(3).","graph":{"fn":"2*x - 1","x":[-5,5],"y":[-5,8]},"answers":["5"],"hint":"Go to x = 3 on the horizontal axis, then up to the line.","solution":"At x = 3 the line is at height 5. So f(3) = 5."},{"id":"u2-fn4-q2","type":"input","prompt":"Using the same line, y = 2x − 1, for what x is f(x) = 3?","graph":{"fn":"2*x - 1","x":[-5,5],"y":[-5,8]},"answers":["2"],"hint":"Start at height 3 on the vertical axis and go across to the line.","solution":"The line reaches height 3 at x = 2. Check: 2(2) − 1 = 3."},{"id":"u2-fn4-q3","type":"input","prompt":"Table: x = −1, 0, 1, 2 and f(x) = 4, 1, −2, −5. Find f(2).","answers":["-5"],"hint":"Find the column where x = 2.","solution":"The column with x = 2 has y = −5. So f(2) = −5."},{"id":"u2-fn4-q4","type":"input","prompt":"Same table: x = −1, 0, 1, 2 and f(x) = 4, 1, −2, −5. For what x is f(x) = −2?","answers":["1"],"hint":"Find −2 in the f(x) row, then look at its x.","solution":"The value −2 is in the column with x = 1. So x = 1."},{"id":"u2-fn4-q5","type":"input","prompt":"From the graph of f(x) = x² − 4, find every x for which f(x) = 0.","graph":{"fn":"x^2 - 4","x":[-5,5],"y":[-6,8]},"answers":["2, -2"],"hint":"These are the x-values where the graph crosses the x-axis.","solution":"The curve crosses the x-axis at x = −2 and x = 2. Check: 2² − 4 = 0 and (−2)² − 4 = 0."},{"id":"u2-fn4-q6","type":"choice","prompt":"Table: x = 0, 1, 2, 3 and f(x) = 3, 5, 7, 9. Which rule matches the table?","choices":["f(x) = 3x + 2","f(x) = x + 3","f(x) = 2x + 3","f(x) = 2x + 1"],"answer":2,"hint":"f(0) tells you the number added. Then see how much f grows each step.","solution":"f(0) = 3 so the constant is 3. The values go up by 2 each step, so the rule is f(x) = 2x + 3. Check f(3) = 9."},{"id":"u2-fn4-q7","type":"input","prompt":"f(x) = 2x + 3 and g(x) = x² − 1. Find f(g(2)).","answers":["9"],"hint":"Do g(2) first, then use that as the input to f.","solution":"g(2) = 4 − 1 = 3. Then f(3) = 2(3) + 3 = 9."},{"id":"u2-fn4-q8","type":"input","prompt":"If f(x) = x² − 2x and f(x) = 3, find every x that works.","answers":["3, -1"],"hint":"Set x² − 2x = 3, move everything to one side, and factor.","solution":"x² − 2x = 3, so x² − 2x − 3 = 0. Factor: (x − 3)(x + 1) = 0. So x = 3 or x = −1. Check: 9 − 6 = 3 and 1 + 2 = 3."}]}]},{"id":"slope","title":"Slope and rate of change","lessons":[{"id":"slope-1","teach":[{"title":"Slope from two points","text":["Slope measures steepness: rise over run. Given (x₁, y₁) and (x₂, y₂), m = (y₂ − y₁) / (x₂ − x₁).","Subtract in the same order on top and bottom. Either point can go first."],"example":{"problem":"Find the slope through (1, 2) and (4, 11).","steps":["Rise: 11 − 2 = 9.","Run: 4 − 1 = 3.","m = 9/3 = 3."]}}],"questions":[{"id":"u2-slope1-q1","calculator":false,"type":"input","prompt":"Find the slope of the line through (1, 2) and (3, 8).","answers":["3"],"hint":"Subtract the y-values, then the x-values, in the same order.","solution":"m = (8 − 2)/(3 − 1) = 6/2 = 3."},{"id":"u2-slope1-q2","type":"input","prompt":"Find the slope of the line through (0, 5) and (4, 1).","answers":["-1"],"hint":"The y-value goes down as x goes up.","solution":"m = (1 − 5)/(4 − 0) = −4/4 = −1."},{"id":"u2-slope1-q3","type":"input","prompt":"Find the slope of the line through (−2, 3) and (4, 6).","answers":["1/2"],"hint":"Run: 4 − (−2) is 4 + 2.","solution":"m = (6 − 3)/(4 − (−2)) = 3/6 = 1/2."},{"id":"u2-slope1-q4","type":"input","prompt":"Find the slope of the line through (−3, −1) and (2, −11).","answers":["-2"],"hint":"Be careful with the double negatives: −11 − (−1) and 2 − (−3).","solution":"m = (−11 − (−1))/(2 − (−3)) = −10/5 = −2."},{"id":"u2-slope1-q5","type":"choice","prompt":"What is the slope through (2, 5) and (6, 1)?","choices":["1","−4","−1","4"],"answer":2,"hint":"Rise is 1 − 5. Run is 6 − 2.","solution":"m = (1 − 5)/(6 − 2) = −4/4 = −1."},{"id":"u2-slope1-q6","type":"input","prompt":"Find the slope of the line through (5, −2) and (−3, 4).","answers":["-3/4"],"hint":"Use the same order for both: 4 − (−2) on top, −3 − 5 on the bottom.","solution":"m = (4 − (−2))/(−3 − 5) = 6/(−8) = −3/4."},{"id":"u2-slope1-q7","type":"input","prompt":"Find the slope of the line through (2, −3) and (7, 9). Give it as a fraction or decimal.","answers":["12/5"],"hint":"9 − (−3) is 12.","solution":"m = (9 − (−3))/(7 − 2) = 12/5 = 2.4."},{"id":"u2-slope1-q8","type":"choice","prompt":"A student finds the slope through (4, 9) and (1, 3) as (9 − 3)/(1 − 4). What went wrong?","choices":["Nothing, that is correct","They subtracted in opposite orders on top and bottom","They should have added the y-values","They should have used the x-values on top"],"answer":1,"hint":"On top they did point 1 minus point 2. On the bottom?","solution":"The top uses (4, 9) first, but the bottom starts with the x of (1, 3). The orders must match: (9 − 3)/(4 − 1) = 6/3 = 2. The student got −2."}]},{"id":"slope-2","teach":[{"title":"Slope from a graph or a table","text":["On a graph, pick two clear points on the line. Count the rise (up is positive, down is negative) and the run (right is positive).","In a table, slope is the change in y divided by the change in x. If it is the same for every pair of rows, the relationship is linear."],"example":{"problem":"Table: x = 0, 2, 4 and y = 1, 7, 13. Find the slope.","steps":["From x = 0 to x = 2: change in x is 2, change in y is 6.","Slope = 6/2 = 3.","Check the next pair: change in x is 2, change in y is 6. Same slope, so it is linear."]}}],"questions":[{"id":"u2-slope2-q1","type":"input","prompt":"What is the slope of the graphed line?","graph":{"fn":"2*x + 1","x":[-5,5],"y":[-5,8]},"answers":["2"],"hint":"The line passes through (0, 1) and (1, 3). How far up per step right?","solution":"From (0, 1) to (1, 3): rise 2, run 1. Slope = 2."},{"id":"u2-slope2-q2","type":"input","prompt":"The graphed line goes down to the right. What is its slope?","graph":{"fn":"-0.5*x + 3","x":[-6,6],"y":[-3,7]},"answers":["-1/2"],"hint":"The line goes down to the right. Use (0, 3) and (2, 2).","solution":"From (0, 3) to (2, 2): rise −1, run 2. Slope = −1/2."},{"id":"u2-slope2-q3","type":"input","prompt":"Table: x = 0, 2, 4, 6 and y = 1, 7, 13, 19. Find the slope.","answers":["3"],"hint":"Pick two rows. Change in y over change in x.","solution":"From (0, 1) to (2, 7): (7 − 1)/(2 − 0) = 3. The other rows also change by 6 in y per 2 in x, so the slope is 3."},{"id":"u2-slope2-q4","type":"input","prompt":"Table: x = −2, 1, 4 and y = 9, 3, −3. Find the slope.","answers":["-2"],"hint":"x goes up 3 each time. How does y change?","solution":"From (−2, 9) to (1, 3): (3 − 9)/(1 − (−2)) = −6/3 = −2. From (1, 3) to (4, −3): −6/3 = −2. Slope = −2."},{"id":"u2-slope2-q5","type":"choice","prompt":"Table: x = 1, 2, 3, 4 and y = 2, 5, 9, 14. Is the rate of change constant?","choices":["Yes, the slope is 3 throughout","Yes, the slope is 4 throughout","No, y changes by 3, then 4, then 5, so it is not linear","No, because y is increasing"],"answer":2,"hint":"Find the change in y between each pair of rows. The x-values go up by 1 each time.","solution":"Changes in y: 5 − 2 = 3, 9 − 5 = 4, 14 − 9 = 5. The change is not constant, so the rate of change is not constant and the table is not linear."},{"id":"u2-slope2-q6","type":"choice","prompt":"The graphed line passes through the origin. Which is its slope?","graph":{"fn":"x/3","x":[-6,6],"y":[-4,4]},"choices":["−3","3","−1/3","1/3"],"answer":3,"hint":"The line passes through (0, 0) and (3, 1). Rise over run.","solution":"From (0, 0) to (3, 1): rise 1, run 3. The line goes up to the right, so the slope is +1/3."},{"id":"u2-slope2-q7","type":"input","prompt":"Table: x = 3, 5, 9 and y = 4, 10, 22. Find the slope.","answers":["3"],"hint":"The x-values are not evenly spaced, so divide each time.","solution":"(10 − 4)/(5 − 3) = 6/2 = 3. Check: (22 − 10)/(9 − 5) = 12/4 = 3. Slope = 3."},{"id":"u2-slope2-q8","type":"input","prompt":"Read two clear points from the graph. What is the slope of the line?","graph":{"fn":"-2*x + 4","x":[-5,5],"y":[-6,10]},"answers":["-2"],"hint":"From (0, 4) to (1, 2), the line goes down.","solution":"From (0, 4) to (1, 2): rise −2, run 1. Slope = −2."}]},{"id":"slope-3","teach":[{"title":"Horizontal and vertical lines","text":["A horizontal line (y = c) has rise 0, so its slope is 0.","A vertical line (x = c) has run 0. You cannot divide by zero, so its slope is undefined."],"example":{"problem":"Slope through (2, 5) and (2, 9).","steps":["Rise: 9 − 5 = 4. Run: 2 − 2 = 0.","4/0 is undefined. The line is vertical, x = 2."]}},{"title":"Rate of change in words","text":["In a real situation the slope is a rate: change in the output per one unit of the input. Always include units, like miles per hour.","A negative rate means the quantity is decreasing."],"example":{"problem":"A candle is 20 cm at 1 hour and 14 cm at 4 hours. Find the rate.","steps":["Change in height: 14 − 20 = −6 cm.","Change in time: 4 − 1 = 3 hours.","Rate = −6/3 = −2 cm per hour."]}}],"questions":[{"id":"u2-slope3-q1","calculator":false,"type":"input","prompt":"Find the slope of the line through (3, 5) and (9, 5).","answers":["0"],"hint":"The y-values match. What is the rise?","solution":"m = (5 − 5)/(9 − 3) = 0/6 = 0. It is a horizontal line."},{"id":"u2-slope3-q2","type":"choice","prompt":"What is the slope of the line through (4, −2) and (4, 7)?","choices":["0","Undefined","9","1"],"answer":1,"hint":"The x-values match. What is the run?","solution":"m = (7 − (−2))/(4 − 4) = 9/0. Dividing by zero is undefined. The line is vertical."},{"id":"u2-slope3-q3","calculator":false,"type":"input","prompt":"What is the slope of the line y = 4?","answers":["0"],"hint":"y = 4 is a horizontal line.","solution":"y = 4 is horizontal at height 4. A flat line rises 0, so the slope is 0."},{"id":"u2-slope3-q4","type":"choice","prompt":"What is the slope of the line x = −2?","choices":["0","−2","Undefined","2"],"answer":2,"hint":"x = −2 is a straight up-and-down line.","solution":"x = −2 is a vertical line. Its run is 0, so its slope is undefined. It is not 0 and it is not −2."},{"id":"u2-slope3-q5","type":"input","prompt":"A car travels 150 miles in 3 hours at a steady pace. What is the rate of change in miles per hour?","answers":["50"],"hint":"Change in distance over change in time.","solution":"150 miles / 3 hours = 50 miles per hour."},{"id":"u2-slope3-q6","type":"input","prompt":"At 2 pm the temperature is 70°F. At 6 pm it is 58°F. What is the rate of change in degrees per hour?","answers":["-3"],"hint":"The temperature went down. Divide the change by the number of hours.","solution":"Change in temperature: 58 − 70 = −12. Change in time: 6 − 2 = 4 hours. Rate = −12/4 = −3 degrees per hour."},{"id":"u2-slope3-q7","type":"input","prompt":"A plant is 12 cm tall at week 2 and 33 cm tall at week 5. How many cm per week does it grow?","answers":["7"],"hint":"Change in height over change in weeks.","solution":"Height change: 33 − 12 = 21 cm. Time: 5 − 2 = 3 weeks. Rate = 21/3 = 7 cm per week."},{"id":"u2-slope3-q8","type":"choice","prompt":"A tank's water level has a slope of −3 gallons per minute. What does that mean?","choices":["The tank gains 3 gallons every minute","The tank loses 3 gallons every minute","The tank holds 3 gallons","The tank empties in 3 minutes"],"answer":1,"hint":"Negative means decreasing.","solution":"The slope is the change in water per minute. −3 means the water goes down by 3 gallons each minute."}]},{"id":"slope-4","teach":[{"title":"Using slope to find missing values","text":["When a slope is given, set up (y₂ − y₁)/(x₂ − x₁) = m with the unknown in it, then solve the equation.","Compare steepness by size: a slope of −5 is steeper than a slope of 3, because 5 > 3."],"example":{"problem":"The line through (1, 4) and (3, k) has slope 5. Find k.","steps":["Set up (k − 4)/(3 − 1) = 5.","Simplify the bottom: (k − 4)/2 = 5.","Multiply by 2: k − 4 = 10, so k = 14."]}}],"questions":[{"id":"u2-slope4-q1","type":"input","prompt":"The line through (2, k) and (5, 10) has slope 3. Find k.","answers":["1"],"hint":"Write (10 − k)/(5 − 2) = 3 and solve.","solution":"(10 − k)/3 = 3. Multiply by 3: 10 − k = 9. So k = 1."},{"id":"u2-slope4-q2","type":"input","prompt":"The line through (1, 4) and (m, −2) has slope −2. Find m.","answers":["4"],"hint":"(−2 − 4)/(m − 1) = −2.","solution":"−6/(m − 1) = −2. Multiply by (m − 1): −6 = −2(m − 1). Divide by −2: 3 = m − 1, so m = 4."},{"id":"u2-slope4-q3","type":"input","prompt":"The line through (−3, y) and (1, 5) has slope 1/2. Find y.","answers":["3"],"hint":"Run is 1 − (−3) = 4. So rise must be half of the run.","solution":"(5 − y)/4 = 1/2. Multiply by 4: 5 − y = 2. So y = 3."},{"id":"u2-slope4-q4","type":"choice","prompt":"Which pair of points gives a line with slope −2/3?","choices":["(0, 0) and (3, 2)","(1, 5) and (4, 3)","(2, 1) and (4, 4)","(0, 4) and (−3, 2)"],"answer":1,"hint":"Find the slope for each pair. The sign matters.","solution":"(1, 5), (4, 3): (3 − 5)/(4 − 1) = −2/3. The others give 2/3, 3/2, and 2/3."},{"id":"u2-slope4-q5","type":"input","prompt":"The points (0, −1), (2, 5), and (5, k) all lie on one line. Find k.","answers":["14"],"hint":"Find the slope from the first two points, then use it to reach x = 5.","solution":"Slope from (0, −1) to (2, 5): 6/2 = 3. From (0, −1), at x = 5 the rise is 3 · 5 = 15. So k = −1 + 15 = 14. Check from (2, 5): (14 − 5)/(5 − 2) = 3."},{"id":"u2-slope4-q6","type":"choice","prompt":"A ramp rises 2 feet over a horizontal distance of 24 feet. What is its slope?","choices":["12","1/12","1/10","1/24"],"answer":1,"hint":"Slope is rise over run.","solution":"Slope = 2/24 = 1/12."},{"id":"u2-slope4-q7","type":"input","prompt":"A company sold 120 items in month 1 and 300 items in month 4. How many more items per month is it selling, on average?","answers":["60"],"hint":"Change in items over change in months. Month 4 minus month 1 is 3 months.","solution":"Items: 300 − 120 = 180. Months: 4 − 1 = 3. Rate = 180/3 = 60 items per month."},{"id":"u2-slope4-q8","type":"choice","prompt":"Which line is steepest: slope 3/4, −5/2, 2, or −1?","choices":["Slope 3/4","Slope −5/2","Slope 2","Slope −1"],"answer":1,"hint":"Steepness depends on the size of the slope, not its sign.","solution":"Compare 3/4, 5/2, 2, 1 as sizes. 5/2 = 2.5 is the largest, so the line with slope −5/2 is steepest."}]}]},{"id":"line-equations","title":"Writing linear equations","lessons":[{"id":"line-equations-1","teach":[{"title":"Slope-intercept form","text":["y = mx + b. The slope is m. The y-intercept is b, where the line crosses the y-axis at (0, b).","If you know the slope and one point, plug them in to find b."],"example":{"problem":"Write the line with slope 3 through (2, 7).","steps":["Start with y = 3x + b.","Plug in (2, 7): 7 = 3(2) + b.","7 = 6 + b, so b = 1.","y = 3x + 1"]}},{"title":"Rewriting into slope-intercept form","text":["Solve for y. Do the same thing to every term, including dividing the whole right side."],"example":{"problem":"Put 2x + y = 5 in slope-intercept form.","steps":["Subtract 2x from both sides: y = −2x + 5.","Slope −2, y-intercept 5."]}}],"questions":[{"id":"u2-lineeq1-q1","type":"choice","prompt":"Which equation has slope 3 and y-intercept −2?","choices":["y = −2x + 3","y = 3x − 2","y = 3x + 2","y = −3x − 2"],"answer":1,"hint":"In y = mx + b, m is the slope and b is the y-intercept.","solution":"m = 3 and b = −2, so y = 3x − 2."},{"id":"u2-lineeq1-q2","calculator":false,"type":"input","prompt":"What is the y-intercept of y = −4x + 9?","answers":["9"],"hint":"It is the constant, the number without x.","solution":"In y = mx + b, b = 9. The line crosses the y-axis at (0, 9)."},{"id":"u2-lineeq1-q3","type":"choice","prompt":"Which equation has slope −1/2 and y-intercept 4?","choices":["y = 4x − 1/2","y = −1/2x − 4","y = −1/2x + 4","y = 1/2x + 4"],"answer":2,"hint":"Slope goes with x. The y-intercept stands alone.","solution":"m = −1/2, b = 4. So y = −1/2x + 4."},{"id":"u2-lineeq1-q4","type":"input","prompt":"A line with slope 3 passes through (2, 7). In y = 3x + b, what is b?","answers":["1"],"hint":"Substitute x = 2 and y = 7 and solve for b.","solution":"7 = 3(2) + b. So 7 = 6 + b and b = 1."},{"id":"u2-lineeq1-q5","type":"input","prompt":"A line with slope −2 passes through (−1, 3). In y = −2x + b, what is b?","answers":["1"],"hint":"−2 times −1 is positive.","solution":"3 = −2(−1) + b. So 3 = 2 + b and b = 1."},{"id":"u2-lineeq1-q6","type":"choice","prompt":"Which equation matches the graph?","graph":{"fn":"2*x - 3","x":[-5,5],"y":[-8,6]},"choices":["y = 2x + 3","y = −2x − 3","y = 3x − 2","y = 2x − 3"],"answer":3,"hint":"Where does the line cross the y-axis? Then count rise over run.","solution":"It crosses the y-axis at (0, −3), so b = −3. From (0, −3) to (1, −1) is rise 2, run 1, so m = 2. y = 2x − 3."},{"id":"u2-lineeq1-q7","type":"input","prompt":"Rewrite 3x + y = 5 in slope-intercept form. What is the slope?","answers":["-3"],"hint":"Subtract 3x from both sides to get y by itself.","solution":"y = −3x + 5. The slope is −3."},{"id":"u2-lineeq1-q8","type":"choice","prompt":"Solve 2y = 6x − 4 for y.","choices":["y = 6x − 2","y = 3x − 4","y = 3x − 2","y = 12x − 8"],"answer":2,"hint":"Divide every term by 2, not just one.","solution":"Divide both sides by 2: y = 3x − 2."}]},{"id":"line-equations-2","teach":[{"title":"Point-slope form","text":["y − y₁ = m(x − x₁) is the line with slope m through the point (x₁, y₁).","The signs flip: the point (3, −2) puts x − 3 and y + 2 in the equation."],"example":{"problem":"Write the line with slope 4 through (3, −2).","steps":["y − (−2) = 4(x − 3).","y + 2 = 4(x − 3).","Slope-intercept form: y = 4x − 12 − 2 = 4x − 14."]}}],"questions":[{"id":"u2-lineeq2-q1","type":"choice","prompt":"Which is the line with slope 4 through (3, −2) in point-slope form?","choices":["y − 2 = 4(x + 3)","y + 2 = 4(x + 3)","y − 3 = 4(x + 2)","y + 2 = 4(x − 3)"],"answer":3,"hint":"y − y₁ = m(x − x₁). Subtracting a negative gives a plus.","solution":"y − (−2) = 4(x − 3), which is y + 2 = 4(x − 3)."},{"id":"u2-lineeq2-q2","type":"choice","prompt":"The line y − 5 = −3(x + 1) has which slope and point?","choices":["Slope −3, point (−1, 5)","Slope −3, point (1, −5)","Slope 3, point (−1, 5)","Slope 5, point (−3, 1)"],"answer":0,"hint":"x + 1 is x − (−1).","solution":"y − 5 = −3(x − (−1)). So m = −3 and the point is (−1, 5)."},{"id":"u2-lineeq2-q3","type":"input","prompt":"The line y − 1 = 2(x − 4) has y-intercept b. Find b.","answers":["-7"],"hint":"Distribute 2, then add 1.","solution":"y − 1 = 2x − 8. So y = 2x − 7. The y-intercept is −7."},{"id":"u2-lineeq2-q4","type":"input","prompt":"A line goes through (1, 3) and (3, 9). Write it in point-slope form, then simplify to y = mx + b. What is b?","answers":["0"],"hint":"First find the slope, then use (1, 3).","solution":"m = (9 − 3)/(3 − 1) = 3. y − 3 = 3(x − 1) gives y − 3 = 3x − 3, so y = 3x. b = 0."},{"id":"u2-lineeq2-q5","type":"choice","prompt":"Which equation is the line through (−2, 5) and (2, −3) in point-slope form using (−2, 5)?","choices":["y − 5 = −2(x − 2)","y − 5 = 2(x + 2)","y − 5 = −2(x + 2)","y + 5 = −2(x + 2)"],"answer":2,"hint":"Find the slope: change in y over change in x.","solution":"m = (−3 − 5)/(2 − (−2)) = −8/4 = −2. Using (−2, 5): y − 5 = −2(x + 2)."},{"id":"u2-lineeq2-q6","type":"input","prompt":"A line has slope −1/2 and passes through (4, 1). Find its y-intercept.","answers":["3"],"hint":"1 = −1/2(4) + b.","solution":"1 = −1/2(4) + b = −2 + b. So b = 3."},{"id":"u2-lineeq2-q7","type":"input","prompt":"Find the x-intercept of y − 2 = 3(x − 1). Give a fraction or decimal.","answers":["1/3"],"hint":"Simplify to y = 3x − 1, then set y = 0.","solution":"y = 3x − 3 + 2 = 3x − 1. Set y = 0: 3x = 1, x = 1/3."},{"id":"u2-lineeq2-q8","type":"choice","prompt":"Which equation is the same line as y − 4 = 2(x − 3)?","choices":["y = 2x + 1","y = 2x − 2","y = 2x − 10","y = 2x + 10"],"answer":1,"hint":"Distribute 2 and then add 4 to both sides.","solution":"y − 4 = 2x − 6. Add 4: y = 2x − 2."}]},{"id":"line-equations-3","teach":[{"title":"Standard form and intercepts","text":["Standard form is Ax + By = C. To find the x-intercept, set y = 0. To find the y-intercept, set x = 0.","Slope in standard form is −A/B."],"example":{"problem":"Find the intercepts of 2x + 3y = 12.","steps":["Set y = 0: 2x = 12, so x = 6. The x-intercept is (6, 0).","Set x = 0: 3y = 12, so y = 4. The y-intercept is (0, 4)."]}}],"questions":[{"id":"u2-lineeq3-q1","type":"input","prompt":"What is the x-intercept (the x-value) of 2x + 3y = 12?","answers":["6"],"hint":"Set y = 0.","solution":"2x + 3(0) = 12. So 2x = 12 and x = 6."},{"id":"u2-lineeq3-q2","type":"input","prompt":"What is the y-intercept (the y-value) of 2x + 3y = 12?","answers":["4"],"hint":"Set x = 0.","solution":"2(0) + 3y = 12. So 3y = 12 and y = 4."},{"id":"u2-lineeq3-q3","type":"input","prompt":"What is the x-intercept (the x-value) of 5x − 2y = 20?","answers":["4"],"hint":"Set y = 0 and divide.","solution":"5x − 2(0) = 20. So 5x = 20 and x = 4."},{"id":"u2-lineeq3-q4","type":"choice","prompt":"Write y = −2x + 5 in standard form Ax + By = C.","choices":["2x − y = 5","−2x + y = 5","2x + y = −5","2x + y = 5"],"answer":3,"hint":"Add 2x to both sides.","solution":"Add 2x to both sides: 2x + y = 5."},{"id":"u2-lineeq3-q5","type":"input","prompt":"What is the y-intercept (the y-value) of 4x − y = 8?","answers":["-8"],"hint":"Set x = 0 and watch the sign on y.","solution":"4(0) − y = 8. So −y = 8 and y = −8."},{"id":"u2-lineeq3-q6","type":"choice","prompt":"What is the slope of 3x − 4y = 12?","choices":["−3/4","3/4","3","−4"],"answer":1,"hint":"Solve for y, or use −A/B.","solution":"−4y = −3x + 12. Divide by −4: y = 3/4x − 3. The slope is 3/4."},{"id":"u2-lineeq3-q7","type":"input","prompt":"A line has x-intercept 3 and y-intercept −6. What is its slope?","answers":["2"],"hint":"The intercepts are the points (3, 0) and (0, −6).","solution":"m = (0 − (−6))/(3 − 0) = 6/3 = 2."},{"id":"u2-lineeq3-q8","type":"choice","prompt":"Which equation has x-intercept (4, 0) and y-intercept (0, −3)?","choices":["3x + 4y = 12","4x − 3y = 12","3x − 4y = −12","3x − 4y = 12"],"answer":3,"hint":"Plug both points into each equation.","solution":"Check 3x − 4y = 12. At (4, 0): 12 − 0 = 12. At (0, −3): 0 + 12 = 12. Both work. The others fail one of the points."}]},{"id":"line-equations-4","teach":[{"title":"Writing from two points, a graph, or a story","text":["With two points: find the slope, then use one point to find b (or write point-slope).","From a story: the rate per unit is the slope. The starting amount is the y-intercept."],"example":{"problem":"A gym charges a $20 signup fee plus $15 per month. Write the cost C after m months.","steps":["The fee per month is the slope: 15.","The signup fee at month 0 is the y-intercept: 20.","C = 15m + 20."]}}],"questions":[{"id":"u2-lineeq4-q1","type":"choice","prompt":"Which is the line through (1, 5) and (3, 11)?","choices":["y = 3x + 2","y = 2x + 3","y = 3x − 2","y = 6x − 1"],"answer":0,"hint":"Slope first. Then use (1, 5) to find b.","solution":"m = (11 − 5)/(3 − 1) = 3. 5 = 3(1) + b gives b = 2. y = 3x + 2."},{"id":"u2-lineeq4-q2","type":"input","prompt":"A line goes through (2, −1) and (6, 7). What is its y-intercept?","answers":["-5"],"hint":"The slope is 8/4. Then plug in (2, −1).","solution":"m = (7 − (−1))/(6 − 2) = 2. −1 = 2(2) + b gives b = −5."},{"id":"u2-lineeq4-q3","type":"choice","prompt":"Which equation describes the graphed line?","graph":{"fn":"0.5*x - 2","x":[-6,6],"y":[-6,4]},"choices":["y = 2x − 2","y = 1/2x + 2","y = −1/2x − 2","y = 1/2x − 2"],"answer":3,"hint":"Read the y-intercept first. Then find rise over run.","solution":"The line crosses the y-axis at −2. From (0, −2) to (2, −1): rise 1, run 2, so m = 1/2. y = 1/2x − 2."},{"id":"u2-lineeq4-q4","type":"input","prompt":"A line goes through (−3, 4) and (3, −2). What is its y-intercept?","answers":["1"],"hint":"The slope is −6/6.","solution":"m = (−2 − 4)/(3 − (−3)) = −1. 4 = −1(−3) + b gives 4 = 3 + b, so b = 1."},{"id":"u2-lineeq4-q5","type":"input","prompt":"A line passes through (0, 3) and (4, 11). What is y when x = 10?","answers":["23"],"hint":"Find the equation first: slope and y-intercept.","solution":"m = (11 − 3)/(4 − 0) = 2 and b = 3. So y = 2x + 3. At x = 10: y = 23."},{"id":"u2-lineeq4-q6","type":"input","prompt":"A gym charges a $20 joining fee plus $15 per month. What is the total cost, in dollars, after 6 months?","answers":["110"],"hint":"Cost = 15 times months plus 20.","solution":"C = 15(6) + 20 = 90 + 20 = 110."},{"id":"u2-lineeq4-q7","type":"input","prompt":"A plumber charges a flat visit fee plus an hourly rate. A 3-hour job costs $135 and the visit fee is $45. What is the hourly rate in dollars?","answers":["30"],"hint":"Take away the visit fee, then divide by the hours.","solution":"135 − 45 = 90 for labor. 90/3 = 30 dollars per hour."},{"id":"u2-lineeq4-q8","type":"choice","prompt":"A plant is 7 cm tall after 2 weeks and 16 cm tall after 5 weeks. Which equation gives its height h after w weeks?","choices":["h = 3w + 1","h = 3w + 7","h = 9w − 11","h = 2w + 3"],"answer":0,"hint":"The growth rate is the slope. Plug in one data point to find b.","solution":"m = (16 − 7)/(5 − 2) = 3. 7 = 3(2) + b gives b = 1. h = 3w + 1. Check: 3(5) + 1 = 16."}]}]},{"id":"parallel-perpendicular","title":"Parallel and perpendicular lines","lessons":[{"id":"parallel-perpendicular-1","teach":[{"title":"Slopes of parallel and perpendicular lines","text":["Parallel lines never meet. They have the same slope.","Perpendicular lines meet at a right angle. Their slopes are negative reciprocals: flip the fraction and change the sign. The product of the two slopes is −1."],"example":{"problem":"Find the slope of a line perpendicular to y = (2/3)x + 1.","steps":["The slope is 2/3.","Flip it: 3/2. Change the sign: −3/2.","Check: (2/3)(−3/2) = −1."]}}],"questions":[{"id":"u2-parperp1-q1","calculator":false,"type":"input","prompt":"What is the slope of any line parallel to y = 4x − 1?","answers":["4"],"hint":"Parallel lines have equal slopes.","solution":"The slope of y = 4x − 1 is 4. A parallel line has the same slope, 4."},{"id":"u2-parperp1-q2","type":"input","prompt":"What is the slope of any line perpendicular to y = 4x − 1? Give a fraction.","answers":["-1/4"],"hint":"Flip 4 (think 4/1) and change the sign.","solution":"The slope is 4 = 4/1. Flip to 1/4 and change the sign: −1/4."},{"id":"u2-parperp1-q3","type":"input","prompt":"A line has slope −2/3. What is the slope of a line perpendicular to it?","answers":["3/2"],"hint":"Flip the fraction, and change the sign from negative to positive.","solution":"Flip −2/3 to get 3/2 and change the sign: +3/2. Check: (−2/3)(3/2) = −1."},{"id":"u2-parperp1-q4","type":"choice","prompt":"Which pair of slopes belongs to perpendicular lines?","choices":["3/4 and 4/3","2 and −2","5 and −1/5","−1/2 and −2"],"answer":2,"hint":"Multiply each pair. Perpendicular slopes multiply to −1.","solution":"3/4 · 4/3 = 1. 2 · (−2) = −4. 5 · (−1/5) = −1. (−1/2)(−2) = 1. Only 5 and −1/5 give −1."},{"id":"u2-parperp1-q5","type":"input","prompt":"A line has slope 1/2. What is the slope of a perpendicular line?","answers":["-2"],"hint":"Flip 1/2 and change the sign.","solution":"Flip 1/2 to 2/1 = 2. Change the sign: −2."},{"id":"u2-parperp1-q6","type":"input","prompt":"What is the slope of a line perpendicular to y = −x + 7?","answers":["1"],"hint":"The slope of y = −x + 7 is −1.","solution":"The slope is −1 = −1/1. Flip: −1. Change the sign: 1."},{"id":"u2-parperp1-q7","type":"choice","prompt":"A line is horizontal. What is true about a line perpendicular to it?","choices":["It also has slope 0","It has slope 1","It is vertical, with an undefined slope","It has slope −1"],"answer":2,"hint":"Picture the x-axis and a line crossing it at a right angle.","solution":"A horizontal line is perpendicular to a vertical line. Vertical lines have an undefined slope."},{"id":"u2-parperp1-q8","type":"input","prompt":"A line with slope k is perpendicular to a line with slope 3/5. Find k.","answers":["-5/3"],"hint":"k is the negative reciprocal of 3/5.","solution":"k · (3/5) = −1. So k = −5/3."}]},{"id":"parallel-perpendicular-2","teach":[{"title":"Telling from equations","text":["Get both equations to slope-intercept form, y = mx + b, and compare the slopes. Same slope with different b means parallel. Slopes with product −1 means perpendicular. Otherwise neither.","For standard form Ax + By = C, the slope is −A/B."],"example":{"problem":"Are 2x + y = 5 and y = (1/2)x − 3 parallel, perpendicular, or neither?","steps":["2x + y = 5 becomes y = −2x + 5. Slope −2.","The other slope is 1/2.","Product: (−2)(1/2) = −1. Perpendicular."]}}],"questions":[{"id":"u2-parperp2-q1","type":"choice","prompt":"y = 2x + 3 and y = 2x − 7 are...","choices":["Perpendicular","Parallel","The same line","Neither"],"answer":1,"hint":"Compare the slopes. Compare the y-intercepts too.","solution":"Both slopes are 2, and the y-intercepts 3 and −7 differ. So the lines are parallel."},{"id":"u2-parperp2-q2","type":"choice","prompt":"y = 3x + 1 and y = −(1/3)x + 4 are...","choices":["Parallel","The same line","Perpendicular","Neither"],"answer":2,"hint":"Multiply the slopes.","solution":"3 · (−1/3) = −1. The slopes are negative reciprocals, so the lines are perpendicular."},{"id":"u2-parperp2-q3","type":"choice","prompt":"2x + y = 5 and 4x + 2y = 3 are...","choices":["Parallel","Perpendicular","Neither","The same line"],"answer":0,"hint":"Solve each for y. Compare the slope and the intercept.","solution":"2x + y = 5 gives y = −2x + 5. 4x + 2y = 3 gives y = −2x + 3/2. Same slope −2, different intercepts: parallel."},{"id":"u2-parperp2-q4","type":"choice","prompt":"y = 2x + 1 and x + 2y = 6 are...","choices":["Parallel","Neither","The same line","Perpendicular"],"answer":3,"hint":"Solve the second equation for y.","solution":"x + 2y = 6 gives 2y = −x + 6, so y = −1/2x + 3. Slopes 2 and −1/2 multiply to −1: perpendicular."},{"id":"u2-parperp2-q5","type":"choice","prompt":"y = 3x + 2 and 3x + y = 5 are...","choices":["Perpendicular","Neither","Parallel","The same line"],"answer":1,"hint":"Rewrite 3x + y = 5 as y = ...","solution":"3x + y = 5 gives y = −3x + 5. Slopes 3 and −3. They are not equal and 3 · (−3) = −9, not −1. So neither."},{"id":"u2-parperp2-q6","type":"input","prompt":"y = kx + 3 is parallel to 2x − 3y = 6. Find k as a fraction.","answers":["2/3"],"hint":"Solve 2x − 3y = 6 for y to find its slope.","solution":"−3y = −2x + 6, so y = 2/3x − 2. The slope is 2/3. Parallel means k = 2/3."},{"id":"u2-parperp2-q7","type":"input","prompt":"y = kx is perpendicular to y = (2/5)x − 1. Find k.","answers":["-5/2"],"hint":"k is the negative reciprocal of 2/5.","solution":"k · (2/5) = −1, so k = −5/2."},{"id":"u2-parperp2-q8","type":"choice","prompt":"6x − 2y = 8 and y = 3x − 5 are...","choices":["The same line","Perpendicular","Parallel but not the same line","Neither"],"answer":2,"hint":"Solve 6x − 2y = 8 for y and compare both slope and intercept.","solution":"−2y = −6x + 8, so y = 3x − 4. The other line is y = 3x − 5. Same slope 3, different intercepts: parallel and not the same line."}]},{"id":"parallel-perpendicular-3","teach":[{"title":"Writing a line through a point","text":["Step 1: get the slope you need (the same, or the negative reciprocal). Step 2: plug the point into y = mx + b to find b, or use y − y₁ = m(x − x₁)."],"example":{"problem":"Write the line parallel to y = 2x + 5 through (1, 4).","steps":["Parallel means slope 2. So y = 2x + b.","Plug in (1, 4): 4 = 2(1) + b, so b = 2.","y = 2x + 2"]}}],"questions":[{"id":"u2-parperp3-q1","type":"choice","prompt":"Which line is parallel to y = 2x + 5 and goes through (3, 1)?","choices":["y = 2x − 5","y = 2x + 1","y = −1/2x + 1","y = 2x + 7"],"answer":0,"hint":"Use slope 2 and solve 1 = 2(3) + b.","solution":"1 = 2(3) + b gives b = −5. y = 2x − 5."},{"id":"u2-parperp3-q2","type":"input","prompt":"A line is perpendicular to y = 2x − 1 and goes through (4, 3). What is its y-intercept?","answers":["5"],"hint":"The new slope is −1/2. Then 3 = −1/2(4) + b.","solution":"The slope is −1/2. 3 = −1/2(4) + b = −2 + b, so b = 5."},{"id":"u2-parperp3-q3","type":"choice","prompt":"Which line is parallel to y = −3x + 1 and goes through (2, −4)?","choices":["y = −3x − 4","y = 1/3x − 4","y = −3x + 2","y = 3x + 2"],"answer":2,"hint":"Slope −3. Solve −4 = −3(2) + b.","solution":"−4 = −6 + b, so b = 2. y = −3x + 2."},{"id":"u2-parperp3-q4","type":"input","prompt":"A line is parallel to y = 3x − 4 and goes through (−2, 1). What is its y-intercept?","answers":["7"],"hint":"3 times −2 is −6.","solution":"The slope is 3. 1 = 3(−2) + b = −6 + b, so b = 7."},{"id":"u2-parperp3-q5","type":"choice","prompt":"Which line is perpendicular to y = (1/2)x + 3 and goes through (−1, 4)?","choices":["y = −2x + 4","y = 2x + 6","y = −2x + 2","y = 1/2x + 4.5"],"answer":2,"hint":"The new slope is −2. Solve 4 = −2(−1) + b.","solution":"4 = −2(−1) + b = 2 + b, so b = 2. y = −2x + 2."},{"id":"u2-parperp3-q6","type":"input","prompt":"A line is parallel to 2x + y = 7 and goes through (3, 2). What is its y-intercept?","answers":["8"],"hint":"The slope of 2x + y = 7 is −2.","solution":"The slope is −2. 2 = −2(3) + b = −6 + b, so b = 8."},{"id":"u2-parperp3-q7","type":"input","prompt":"A line is perpendicular to 4x + y = 3 and goes through (8, 5). What is its y-intercept?","answers":["3"],"hint":"4x + y = 3 has slope −4. The perpendicular slope is 1/4.","solution":"The slope is 1/4. 5 = 1/4(8) + b = 2 + b, so b = 3."},{"id":"u2-parperp3-q8","type":"choice","prompt":"Which is the standard form of the line parallel to x − 2y = 4 through (2, 3)?","choices":["x − 2y = 4","2x − y = −4","x + 2y = 8","x − 2y = −4"],"answer":3,"hint":"A parallel line keeps x − 2y and changes only the right side. Plug in (2, 3).","solution":"Parallel lines have the form x − 2y = C. At (2, 3): 2 − 6 = −4. So x − 2y = −4."}]},{"id":"parallel-perpendicular-4","teach":[{"title":"Putting it together","text":["A missing coordinate can be found by setting the slope between two points equal to the slope you need.","To test for a right angle in a shape, check whether two sides have slopes with product −1."],"example":{"problem":"Line through (0, 1) and (3, k) is parallel to y = 2x. Find k.","steps":["Parallel means slope 2.","(k − 1)/(3 − 0) = 2.","k − 1 = 6, so k = 7."]}}],"questions":[{"id":"u2-parperp4-q1","type":"input","prompt":"A line passes through (1, 2) and (3, 8). What is the slope of a line perpendicular to it? Give a fraction.","answers":["-1/3"],"hint":"Find its slope first, then take the negative reciprocal.","solution":"m = (8 − 2)/(3 − 1) = 3. The perpendicular slope is −1/3."},{"id":"u2-parperp4-q2","type":"choice","prompt":"Line A goes through (0, 1) and (2, 5). Line B goes through (1, 0) and (3, 4). How are they related?","choices":["Perpendicular","Neither","The same line","Parallel"],"answer":3,"hint":"Find each slope.","solution":"Line A: (5 − 1)/(2 − 0) = 2. Line B: (4 − 0)/(3 − 1) = 2. Same slope. Line A has y-intercept 1 and Line B passes through (1, 0), not on Line A, so they are different parallel lines."},{"id":"u2-parperp4-q3","type":"input","prompt":"The line through (−1, 2) and (3, k) is perpendicular to y = −2x + 1. Find k.","answers":["4"],"hint":"The perpendicular slope is 1/2. Set (k − 2)/4 = 1/2.","solution":"The slope must be 1/2. (k − 2)/(3 − (−1)) = 1/2 gives (k − 2)/4 = 1/2. So k − 2 = 2 and k = 4."},{"id":"u2-parperp4-q4","type":"input","prompt":"The line through (2, 1) and (m, 7) is parallel to y = 3x. Find m.","answers":["4"],"hint":"The slope must be 3: 6/(m − 2) = 3.","solution":"(7 − 1)/(m − 2) = 3, so 6 = 3(m − 2) = 3m − 6. Then 3m = 12 and m = 4."},{"id":"u2-parperp4-q5","type":"choice","prompt":"A triangle has vertices A(1, 1), B(5, 3), and C(3, 7). At which vertex is there a right angle?","choices":["A","B","C","There is no right angle"],"answer":1,"hint":"Find the slopes of AB, BC, and AC. Look for slopes that multiply to −1.","solution":"AB: (3 − 1)/(5 − 1) = 1/2. BC: (7 − 3)/(3 − 5) = −2. AC: (7 − 1)/(3 − 1) = 3. AB and BC: (1/2)(−2) = −1, so they are perpendicular. They meet at B."},{"id":"u2-parperp4-q6","type":"input","prompt":"A line is perpendicular to y = −(2/3)x + 5 and goes through (6, −1). What is its y-intercept?","answers":["-10"],"hint":"The new slope is 3/2. Then −1 = 3/2(6) + b.","solution":"The slope is 3/2. −1 = 3/2(6) + b = 9 + b, so b = −10."},{"id":"u2-parperp4-q7","type":"input","prompt":"In a rectangle, one side has slope 5/3. What is the slope of a side that meets it at a corner? Give a fraction.","answers":["-3/5"],"hint":"Adjacent sides of a rectangle are perpendicular.","solution":"Neighboring sides are perpendicular, so the slope is the negative reciprocal of 5/3, which is −3/5."},{"id":"u2-parperp4-q8","type":"choice","prompt":"Which is the equation of the line through (3, −2) that is parallel to the x-axis?","choices":["x = 3","y = 3","x = −2","y = −2"],"answer":3,"hint":"A line parallel to the x-axis is horizontal. What stays the same on it?","solution":"A horizontal line has the same y-value everywhere. It passes through (3, −2), so y = −2."}]}]},{"id":"linear-inequalities","title":"Graphing linear inequalities","lessons":[{"id":"linear-inequalities-1","teach":[{"title":"Solid or dashed boundary","text":["To graph an inequality, first graph its boundary line. Treat the inequality sign as an equals sign.","If the sign is ≤ or ≥, the points on the line are solutions, so draw a solid line.","If the sign is < or >, the points on the line are not solutions, so draw a dashed line."],"example":{"problem":"Is the boundary of y > 2x + 1 solid or dashed?","steps":["The sign is >, with no \"or equal to\" part.","So points on the line do not count. The line is dashed."]}},{"title":"Which side to shade","text":["When y is alone on the left, y > shades above the line and y < shades below it.","With ≥ or ≤ the shading is the same, but the line is solid."],"example":{"problem":"Describe the graph of y ≤ −x + 4.","steps":["The sign is ≤, so the boundary y = −x + 4 is solid.","y is less than the line, so shade below it."]}}],"questions":[{"id":"u2-ineq1-q1","type":"choice","prompt":"Which describes the graph of y > 3x − 2?","choices":["Solid line, shade above","Dashed line, shade above","Dashed line, shade below","Solid line, shade below"],"answer":1,"hint":"The sign is >. Does it include \"equal to\"? And y is greater than the line.","solution":"The sign is >, so the line is dashed. y is greater than the line, so shade above."},{"id":"u2-ineq1-q2","type":"choice","prompt":"Which describes the graph of y ≤ −x + 4?","choices":["Dashed line, shade below","Solid line, shade above","Solid line, shade below","Dashed line, shade above"],"answer":2,"hint":"The sign is ≤, which includes \"equal to\".","solution":"The sign is ≤, so the line is solid. y is less than the line, so shade below."},{"id":"u2-ineq1-q3","type":"input","prompt":"What is the y-intercept of the boundary line of y ≥ 2x − 5?","answers":["-5","(0,-5)"],"hint":"The boundary line is y = 2x − 5. Find the b in y = mx + b.","solution":"The boundary is y = 2x − 5. The y-intercept is −5."},{"id":"u2-ineq1-q4","type":"input","prompt":"What is the slope of the boundary line of y < −(3/4)x + 2?","answers":["-3/4"],"hint":"Ignore the < and read the slope from y = mx + b.","solution":"The boundary is y = −(3/4)x + 2. The slope is −3/4."},{"id":"u2-ineq1-q5","type":"choice","prompt":"Which inequality has a dashed boundary line?","choices":["y ≤ x + 1","y ≥ 2x − 3","x ≤ 4","y < 3x − 1"],"answer":3,"hint":"Dashed lines go with < and > only.","solution":"Only < and > give a dashed line. The others have ≤ or ≥, so they are solid. The answer is y < 3x − 1."},{"id":"u2-ineq1-q6","type":"input","prompt":"A point on the boundary line of y > 5x + 3 has x = 2. What is its y-coordinate?","answers":["13"],"hint":"Put x = 2 into the boundary line y = 5x + 3.","solution":"y = 5(2) + 3 = 10 + 3 = 13."},{"id":"u2-ineq1-q7","type":"choice","prompt":"What is the boundary line of 2x + y ≥ 6?","choices":["2x + y = 6","2x + y > 6","y = 2x + 6","y = −2x − 6"],"answer":0,"hint":"Change the inequality sign to an equals sign. Do not move anything else.","solution":"The boundary line uses = in place of ≥, so it is 2x + y = 6."},{"id":"u2-ineq1-q8","type":"choice","prompt":"The line y = 2x − 1 is drawn. The graph is solid with shading above it. Which inequality is it?","choices":["y > 2x − 1","y ≥ 2x − 1","y ≤ 2x − 1","y < 2x − 1"],"answer":1,"hint":"Solid means the sign has an \"or equal to\". Above means y is greater.","solution":"Solid means ≥ or ≤. Shading above means y is greater than the line. So y ≥ 2x − 1.","graph":{"fn":"2x-1","x":[-5,5],"y":[-5,5]}}]},{"id":"linear-inequalities-2","teach":[{"title":"Is a point a solution?","text":["A point (x, y) is a solution if the inequality is true when you put in its x and y.","Put the numbers in, then check whether the statement is true or false. For ≤ and ≥, \"equal\" counts as true."],"example":{"problem":"Is (1, 4) a solution of y > 2x + 1?","steps":["Put in x = 1 and y = 4: 4 > 2(1) + 1.","4 > 3 is true. So (1, 4) is a solution."]}},{"title":"Test point for shading","text":["Pick a test point that is not on the line. (0, 0) is easiest.","If it makes the inequality true, shade the side with that point. If false, shade the other side."],"example":{"problem":"Which side of the line do you shade for y < 2x − 3?","steps":["Test (0, 0): 0 < 2(0) − 3 means 0 < −3. That is false.","So shade the side that does not contain (0, 0)."]}}],"questions":[{"id":"u2-ineq2-q1","type":"choice","prompt":"Is (1, 4) a solution of y > 2x + 1?","choices":["No, because 4 < 3","Yes, because 4 = 3","Yes, because 4 > 3","No, because the line is dashed"],"answer":2,"hint":"Put x = 1 and y = 4 in. Is the statement true?","solution":"4 > 2(1) + 1 means 4 > 3. That is true, so yes."},{"id":"u2-ineq2-q2","type":"choice","prompt":"Is (−2, 3) a solution of y ≤ −x + 1?","choices":["No, because 3 > 1","Yes, because 3 ≤ 3 is true","No, because the point is on the line","Yes, because 3 < 1"],"answer":1,"hint":"Work out −(−2) + 1 first. With ≤, equal counts.","solution":"−(−2) + 1 = 3. The test is 3 ≤ 3, which is true. The point is on a solid line, so it counts."},{"id":"u2-ineq2-q3","type":"input","prompt":"Look at y > 3x − 4. For the point (2, k), what is the largest whole number k that is NOT a solution?","answers":["2"],"hint":"Find 3(2) − 4. Then ask which k are not greater than that.","solution":"3(2) − 4 = 2. The point is a solution when k > 2. So k = 2 is not a solution, and 2 is the largest whole number that is not."},{"id":"u2-ineq2-q4","type":"choice","prompt":"Is (3, −1) a solution of 2x + 3y < 4?","choices":["No, because 9 < 4 is false","No, because 3 > 4","Yes, because 9 < 4","Yes, because 3 < 4"],"answer":3,"hint":"Work out 2(3) + 3(−1).","solution":"2(3) + 3(−1) = 6 − 3 = 3. Then 3 < 4 is true, so yes."},{"id":"u2-ineq2-q5","type":"input","prompt":"How many of the points (0, 0), (1, 5), (−2, −1), (3, 3) are solutions of y ≥ x + 1?","answers":["2"],"hint":"Test each point. Equal counts because of ≥.","solution":"(0, 0): 0 ≥ 1 is false. (1, 5): 5 ≥ 2 is true. (−2, −1): −1 ≥ −1 is true. (3, 3): 3 ≥ 4 is false. Two points work."},{"id":"u2-ineq2-q6","type":"choice","prompt":"To graph y < 2x − 3, you test (0, 0) and get 0 < −3, which is false. What do you shade?","choices":["The side that contains (0, 0)","The side that does not contain (0, 0)","Only the line itself","Everywhere above the line"],"answer":1,"hint":"A false test point means (0, 0) is not in the solution.","solution":"False means (0, 0) is not a solution. Shade the other side. (Here that is below the line, as y < says.)"},{"id":"u2-ineq2-q7","type":"input","prompt":"The point (a, 7) is on the boundary line of y ≥ 2x + 1. Find a.","answers":["3"],"hint":"Put y = 7 into y = 2x + 1.","solution":"7 = 2a + 1, so 2a = 6 and a = 3."},{"id":"u2-ineq2-q8","type":"choice","prompt":"Which point is a solution of 3x − y ≤ 2?","choices":["(0, −3)","(2, 2)","(1, 0)","(1, 1)"],"answer":3,"hint":"Work out 3x − y for each point. You need a value of 2 or less.","solution":"(1, 1): 3 − 1 = 2 ≤ 2, true. (0, −3): 3, false. (2, 2): 4, false. (1, 0): 3, false. Only (1, 1) works."}]},{"id":"linear-inequalities-3","teach":[{"title":"Get y alone","text":["To read an inequality like a line, solve it for y. Keep the sign the same while you add and subtract.","If you multiply or divide both sides by a negative number, flip the inequality sign."],"example":{"problem":"Solve x − 2y < 6 for y.","steps":["Subtract x: −2y < −x + 6.","Divide by −2. The sign flips: y > (1/2)x − 3.","So the boundary is dashed with shading above."]}}],"questions":[{"id":"u2-ineq3-q1","type":"choice","prompt":"Solve 2x + y ≥ 5 for y.","choices":["y ≤ −2x + 5","y ≥ −2x + 5","y ≥ 2x + 5","y ≥ −2x − 5"],"answer":1,"hint":"Subtract 2x from both sides. No flip is needed.","solution":"Subtract 2x: y ≥ −2x + 5. You did not divide by a negative, so the sign stays."},{"id":"u2-ineq3-q2","type":"choice","prompt":"Solve x − 2y < 6 for y.","choices":["y > (1/2)x − 3","y < (1/2)x − 3","y > −(1/2)x + 3","y > 2x − 6"],"answer":0,"hint":"After subtracting x you divide by −2. What happens to the sign?","solution":"−2y < −x + 6. Divide by −2 and flip: y > (1/2)x − 3."},{"id":"u2-ineq3-q3","type":"input","prompt":"What is the slope of the boundary line of 4x − 2y ≥ 8?","answers":["2"],"hint":"Solve for y first, then read the slope. Dividing by −2 flips the sign but does not change the slope rule.","solution":"−2y ≥ −4x + 8, so y ≤ 2x − 4. The slope is 2."},{"id":"u2-ineq3-q4","type":"input","prompt":"What is the y-intercept of the boundary line of 3x + 4y ≤ 12?","answers":["3","(0,3)"],"hint":"For the intercept, put x = 0 into the boundary 3x + 4y = 12.","solution":"With x = 0: 4y = 12, so y = 3."},{"id":"u2-ineq3-q5","type":"choice","prompt":"Solve 3y − 6x > 9 for y.","choices":["y < 2x + 3","y > 2x + 9","y > 2x + 3","y > −2x + 3"],"answer":2,"hint":"Add 6x first, then divide by 3. Positive 3, so no flip.","solution":"3y > 6x + 9. Divide by 3: y > 2x + 3."},{"id":"u2-ineq3-q6","type":"choice","prompt":"Which is the same as −y > 2x − 1?","choices":["y < −2x + 1","y > −2x + 1","y < 2x − 1","y > 2x − 1"],"answer":0,"hint":"Multiply both sides by −1, and flip the sign.","solution":"Multiply by −1: y < −2x + 1. Every sign changes and the inequality flips."},{"id":"u2-ineq3-q7","type":"input","prompt":"The boundary line of −3y ≤ 6x + 12 crosses the y-axis where? Give the y-value.","answers":["-4","(0,-4)"],"hint":"Put x = 0 in, then divide by −3.","solution":"With x = 0: −3y = 12, so y = −4. (The sign only flips for the inequality, not for the boundary line.)"},{"id":"u2-ineq3-q8","type":"choice","prompt":"The line y = −(1/2)x + 3 is drawn. The graph is solid, shaded below. Which inequality is it?","choices":["y ≥ −(1/2)x + 3","y < −(1/2)x + 3","y ≤ −(1/2)x + 3","y ≤ (1/2)x + 3"],"answer":2,"hint":"Solid means a sign with \"or equal to\". Below means y is less.","solution":"Solid is ≤ or ≥. Shaded below means y is less than the line. So y ≤ −(1/2)x + 3.","graph":{"fn":"-x/2+3","x":[-6,6],"y":[-5,7]}}]},{"id":"linear-inequalities-4","teach":[{"title":"Writing an inequality from a graph","text":["Find the boundary line: its slope and y-intercept. Then decide the sign.","Solid line: ≤ or ≥. Dashed line: < or >. Shaded above: > or ≥. Shaded below: < or ≤.","A vertical line x = a is shaded right for x > a (or ≥) and left for x < a (or ≤)."],"example":{"problem":"A solid line passes through (0, 2) and (4, 0). The side with (3, 3) is shaded. Write the inequality.","steps":["Slope: (0 − 2)/(4 − 0) = −1/2. The y-intercept is 2. Boundary: y = −(1/2)x + 2.","At x = 3 the line is at y = 0.5. The point (3, 3) is above it, so shade above.","The line is solid: y ≥ −(1/2)x + 2."]}}],"questions":[{"id":"u2-ineq4-q1","type":"choice","prompt":"A solid boundary line passes through (0, 4) and (2, 0). The side with the origin is shaded. Which inequality is it?","choices":["y ≥ −2x + 4","y ≤ 2x + 4","y < −2x + 4","y ≤ −2x + 4"],"answer":3,"hint":"Find the slope first. Then test the origin: is (0, 0) above or below the line?","solution":"Slope = (0 − 4)/(2 − 0) = −2, so the line is y = −2x + 4. At x = 0 the line is at 4, and the origin is below it. Solid and below: y ≤ −2x + 4.","graph":{"fn":"-2x+4","x":[-3,6],"y":[-3,7]}},{"id":"u2-ineq4-q2","type":"input","prompt":"A boundary line passes through (0, −1) and (3, 5). What is its slope?","answers":["2"],"hint":"Use rise over run: (5 − (−1)) / (3 − 0).","solution":"(5 + 1)/(3 − 0) = 6/3 = 2."},{"id":"u2-ineq4-q3","type":"choice","prompt":"A solid line passes through (0, 2) and (4, 0). The side with (3, 3) is shaded. Which inequality is it?","choices":["y ≥ −(1/2)x + 2","y ≤ −(1/2)x + 2","y ≥ (1/2)x + 2","y > −(1/2)x + 2"],"answer":0,"hint":"Find the line first. Then check whether (3, 3) is above or below it.","solution":"The slope is −1/2, so the line is y = −(1/2)x + 2. At x = 3 the line is at 0.5, so (3, 3) is above. Solid and above: y ≥ −(1/2)x + 2."},{"id":"u2-ineq4-q4","type":"input","prompt":"You have $30 for movies at $6 each and snacks at $3 each, so 6m + 3s ≤ 30. If m = 4, what is the greatest whole number of snacks s?","answers":["2"],"hint":"Put m = 4 into 6m + 3s ≤ 30 and solve for s.","solution":"24 + 3s ≤ 30, so 3s ≤ 6 and s ≤ 2. The most is 2 snacks."},{"id":"u2-ineq4-q5","type":"choice","prompt":"Which point is a solution of 6m + 3s ≤ 30?","choices":["(4, 3)","(5, 1)","(3, 4)","(1, 9)"],"answer":2,"hint":"Work out 6m + 3s for each pair. It must be 30 or less.","solution":"(3, 4): 18 + 12 = 30, OK. (4, 3): 33. (5, 1): 33. (1, 9): 33. Only (3, 4) works."},{"id":"u2-ineq4-q6","type":"input","prompt":"The boundary of 5x − 2y ≥ 4 has y = 3 at one point. What is x?","answers":["2"],"hint":"Put y = 3 into 5x − 2y = 4.","solution":"5x − 6 = 4, so 5x = 10 and x = 2."},{"id":"u2-ineq4-q7","type":"choice","prompt":"Which describes the graph of x > −2?","choices":["Solid vertical line at x = −2, shade right","Dashed vertical line at x = −2, shade left","Dashed vertical line at x = −2, shade right","Dashed horizontal line at y = −2, shade above"],"answer":2,"hint":"x = −2 is a vertical line. Greater x means further right.","solution":"x = −2 is a vertical line. The sign > means dashed. Larger x is to the right, so shade right."},{"id":"u2-ineq4-q8","type":"input","prompt":"How many points (x, y) with positive whole-number coordinates satisfy y < −x + 6?","answers":["10"],"hint":"This is x + y < 6, so x + y can be 2, 3, 4, or 5. Count the pairs for each.","solution":"x + y < 6 with x, y ≥ 1. Sum 2: 1 pair. Sum 3: 2. Sum 4: 3. Sum 5: 4. Total 1 + 2 + 3 + 4 = 10."}]}]},{"id":"systems-graph-sub","title":"Systems by graphing and substitution","lessons":[{"id":"systems-graph-sub-1","teach":[{"title":"What a solution means","text":["A system is two or more equations. The solution is a point that makes every equation true.","On a graph, it is where the lines cross. To check a point, put its x and y into each equation."],"example":{"problem":"Is (2, 3) a solution of y = x + 1 and y = −x + 5?","steps":["Equation 1: 3 = 2 + 1 is true.","Equation 2: 3 = −2 + 5 is true.","It works in both, so (2, 3) is a solution."]}}],"questions":[{"id":"u2-sys1-q1","type":"choice","prompt":"Is (2, 3) a solution of y = x + 1 and y = −x + 5?","choices":["No, it fails the first equation","Yes, it works in both equations","No, it fails the second equation","Yes, because it works in the first equation"],"answer":1,"hint":"Check the point in each equation. It must work in both.","solution":"First: 3 = 2 + 1 is true. Second: 3 = −2 + 5 is true. So yes."},{"id":"u2-sys1-q2","type":"choice","prompt":"Is (1, 4) a solution of y = 2x + 2 and y = −x + 3?","choices":["No, it works only in the first equation","Yes, it works in both","No, it works only in the second equation","Yes, because the x-values are small"],"answer":0,"hint":"Check the point in each equation separately.","solution":"First: 4 = 2(1) + 2 = 4, true. Second: 4 = −1 + 3 = 2, false. It fails the second equation, so it is not a solution."},{"id":"u2-sys1-q3","type":"input","prompt":"The line y = x + 2 is drawn. A second line is y = −x + 4. At the point where they cross, what is x?","answers":["1"],"hint":"At the crossing, both y-values are the same. Set x + 2 equal to −x + 4.","solution":"x + 2 = −x + 4, so 2x = 2 and x = 1.","graph":{"fn":"x+2","x":[-5,6],"y":[-3,8]}},{"id":"u2-sys1-q4","type":"input","prompt":"The lines y = 2x − 1 and y = x + 2 cross. What is the y-coordinate of the crossing point?","answers":["5"],"hint":"Find x first by setting 2x − 1 = x + 2. Then use either line.","solution":"2x − 1 = x + 2 gives x = 3. Then y = 3 + 2 = 5."},{"id":"u2-sys1-q5","type":"choice","prompt":"The line y = −x + 6 is drawn. A second line is y = x. Where do they cross?","choices":["(6, 0)","(3, 3)","(0, 6)","(−3, 3)"],"answer":1,"hint":"Set −x + 6 equal to x.","solution":"−x + 6 = x, so x = 3 and y = 3. The crossing point is (3, 3).","graph":{"fn":"-x+6","x":[-3,9],"y":[-3,9]}},{"id":"u2-sys1-q6","type":"choice","prompt":"Which system has (−1, 2) as its solution?","choices":["y = x + 3 and y = −x + 3","y = 2x and y = x + 3","y = x + 3 and y = −x + 1","y = −x and y = x + 1"],"answer":2,"hint":"Put x = −1 and y = 2 into both equations of each system.","solution":"For y = x + 3: −1 + 3 = 2, true. For y = −x + 1: 1 + 1 = 2, true. The other systems fail an equation."},{"id":"u2-sys1-q7","type":"input","prompt":"The lines y = 3x − 4 and y = −x + 8 cross at x = 3. What is y?","answers":["5"],"hint":"Put x = 3 into either line.","solution":"y = 3(3) − 4 = 5. Check: −3 + 8 = 5."},{"id":"u2-sys1-q8","type":"input","prompt":"For what value of k is (4, −1) a solution of x + ky = 5?","answers":["-1"],"hint":"Put x = 4 and y = −1 in, then solve for k.","solution":"4 + k(−1) = 5, so 4 − k = 5 and k = −1."}]},{"id":"systems-graph-sub-2","teach":[{"title":"Substitution","text":["If one equation says y = (an expression), put that expression in place of y in the other equation.","Solve for x. Then use x to find y."],"example":{"problem":"Solve y = 2x and x + y = 12.","steps":["Replace y with 2x: x + 2x = 12.","3x = 12, so x = 4.","y = 2(4) = 8. The solution is (4, 8)."]}}],"questions":[{"id":"u2-sys2-q1","type":"input","prompt":"Solve y = 2x and x + y = 12. What is x?","answers":["4"],"hint":"Put 2x in place of y in the second equation.","solution":"x + 2x = 12, so 3x = 12 and x = 4."},{"id":"u2-sys2-q2","type":"input","prompt":"Solve y = x + 4 and 2x + y = 13. What is x?","answers":["3"],"hint":"Replace y with x + 4 in the second equation.","solution":"2x + (x + 4) = 13, so 3x = 9 and x = 3."},{"id":"u2-sys2-q3","type":"input","prompt":"Solve y = 3x − 2 and y = x + 6. What is y?","answers":["10"],"hint":"Both expressions equal y, so set them equal. Then find y.","solution":"3x − 2 = x + 6, so 2x = 8 and x = 4. Then y = 4 + 6 = 10."},{"id":"u2-sys2-q4","type":"choice","prompt":"Solve y = x − 1 and 3x + y = 11. Which is the solution?","choices":["(2, 3)","(3, 2)","(3, 4)","(−3, −4)"],"answer":1,"hint":"Replace y with x − 1, find x, then find y.","solution":"3x + (x − 1) = 11, so 4x = 12 and x = 3. Then y = 3 − 1 = 2. The answer is (3, 2)."},{"id":"u2-sys2-q5","type":"input","prompt":"Solve x = 2y + 1 and 3x − y = 8. What is y?","answers":["1"],"hint":"This time x is alone. Replace x with 2y + 1.","solution":"3(2y + 1) − y = 8, so 6y + 3 − y = 8. That is 5y = 5, so y = 1."},{"id":"u2-sys2-q6","type":"choice","prompt":"To solve y = 4x − 3 and 2x + 3y = 11, what is the correct first substitution?","choices":["2x + 3(4x) − 3 = 11","2x + 4x − 3 = 11","2x + 3(4x − 3) = 11","2x + 3y = 4x − 3"],"answer":2,"hint":"Replace y by the whole expression, in brackets.","solution":"Replace y with (4x − 3) and keep the 3 in front: 2x + 3(4x − 3) = 11."},{"id":"u2-sys2-q7","type":"input","prompt":"Solve x − y = 2 and y = 3x − 10. What is x?","answers":["4"],"hint":"Replace y with 3x − 10. Watch the minus sign in front of y.","solution":"x − (3x − 10) = 2, so x − 3x + 10 = 2. That is −2x = −8, so x = 4."},{"id":"u2-sys2-q8","type":"input","prompt":"One number is 3 more than twice another. Their sum is 21. What is the smaller number?","answers":["6"],"hint":"Let the smaller be b, so the other is 2b + 3. Their sum is 21.","solution":"b + (2b + 3) = 21, so 3b = 18 and b = 6. The other is 15."}]},{"id":"systems-graph-sub-3","teach":[{"title":"Solve for a variable first","text":["If neither equation has y or x alone, pick a variable with a coefficient of 1 and solve for it.","Then substitute into the other equation. Put the whole expression in brackets."],"example":{"problem":"Solve x + y = 10 and 3x − y = 14.","steps":["Solve the first for x: x = 10 − y.","Substitute: 3(10 − y) − y = 14, so 30 − 4y = 14.","y = 4. Then x = 10 − 4 = 6."]}}],"questions":[{"id":"u2-sys3-q1","type":"choice","prompt":"In 3x + 4y = 10 and x − 5y = 2, which is easiest to solve for a variable without fractions?","choices":["x − 5y = 2, solve for x","3x + 4y = 10, solve for x","3x + 4y = 10, solve for y","x − 5y = 2, solve for y"],"answer":0,"hint":"Look for a coefficient of 1 or −1.","solution":"x − 5y = 2 has an x with coefficient 1, so x = 5y + 2 has no fractions."},{"id":"u2-sys3-q2","type":"input","prompt":"Solve x + y = 10 and 3x − y = 14. What is x?","answers":["6"],"hint":"Solve the first for x: x = 10 − y. Substitute.","solution":"3(10 − y) − y = 14 gives 30 − 4y = 14, so y = 4. Then x = 6."},{"id":"u2-sys3-q3","type":"input","prompt":"Solve x − 2y = 4 and 3x + 2y = 20. What is y?","answers":["1"],"hint":"Solve the first for x: x = 2y + 4.","solution":"3(2y + 4) + 2y = 20, so 8y + 12 = 20 and y = 1. Then x = 6."},{"id":"u2-sys3-q4","type":"choice","prompt":"Solve 3x − y = 5 and x + 2y = 4. Which is the solution?","choices":["(1, 2)","(2, −1)","(−1, −8)","(2, 1)"],"answer":3,"hint":"Solve the first for y: y = 3x − 5.","solution":"y = 3x − 5. Then x + 2(3x − 5) = 4, so 7x = 14 and x = 2. Then y = 1."},{"id":"u2-sys3-q5","type":"input","prompt":"Solve 2x + y = 1 and 4x + 3y = 5. What is y?","answers":["3"],"hint":"Solve the first for y: y = 1 − 2x.","solution":"4x + 3(1 − 2x) = 5, so −2x + 3 = 5 and x = −1. Then y = 1 − 2(−1) = 3."},{"id":"u2-sys3-q6","type":"choice","prompt":"Substitute y = 5 − 2x into 3x − 2y = 4. Which equation do you get?","choices":["3x − 2(5) − 2x = 4","3x − 2(5 − 2x) = 4","3x + 2(5 − 2x) = 4","3x − 2y = 5 − 2x"],"answer":1,"hint":"Use brackets so the −2 multiplies the whole expression.","solution":"Replace y with (5 − 2x): 3x − 2(5 − 2x) = 4."},{"id":"u2-sys3-q7","type":"input","prompt":"Solve x + 2y = 3 and 2x + 3y = 4. What is x?","answers":["-1"],"hint":"Solve the first for x: x = 3 − 2y.","solution":"2(3 − 2y) + 3y = 4, so 6 − y = 4 and y = 2. Then x = 3 − 4 = −1."},{"id":"u2-sys3-q8","type":"input","prompt":"A notebook costs $2 more than a pen. 3 notebooks and 2 pens cost $21. What does a pen cost, in dollars?","answers":["3"],"hint":"Let a pen cost p. A notebook costs p + 2.","solution":"3(p + 2) + 2p = 21, so 5p + 6 = 21 and p = 3. A pen costs $3 (a notebook costs $5)."}]},{"id":"systems-graph-sub-4","teach":[{"title":"No solution and infinitely many","text":["If substituting leaves a false statement like 8 = 3, there is no solution. The lines are parallel.","If it leaves a true statement like 5 = 5, there are infinitely many solutions. The lines are the same line.","Lines with the same slope and different intercepts never meet."],"example":{"problem":"Solve y = 2x + 3 and y = 2x − 1.","steps":["Set equal: 2x + 3 = 2x − 1.","Subtract 2x: 3 = −1. That is false.","No solution. The lines are parallel."]}}],"questions":[{"id":"u2-sys4-q1","type":"choice","prompt":"How many solutions do y = 2x + 3 and y = 2x − 1 have?","choices":["One","None, the lines are parallel","Infinitely many","Two"],"answer":1,"hint":"Compare the slopes and the y-intercepts.","solution":"The slopes are both 2 but the intercepts differ. The lines are parallel, so there is no solution."},{"id":"u2-sys4-q2","type":"choice","prompt":"Substitute y = 3x − 4 into 6x − 2y = 8. What do you find?","choices":["It gives 8 = 4, so no solution","It gives x = 8, so one solution","It gives 12x = 0, so one solution","It gives 8 = 8, so infinitely many solutions"],"answer":3,"hint":"Distribute the −2 and combine like terms.","solution":"6x − 2(3x − 4) = 8 gives 6x − 6x + 8 = 8, so 8 = 8. Always true, so infinitely many solutions."},{"id":"u2-sys4-q3","type":"input","prompt":"For y = 4x + 1 and y = 4x + k, what value of k gives infinitely many solutions?","answers":["1"],"hint":"The two equations must describe the same line.","solution":"The slopes already match. The intercepts must match too, so k = 1."},{"id":"u2-sys4-q4","type":"choice","prompt":"Substitute y = −x + 5 into 2x + 2y = 7. What do you find?","choices":["It gives 10 = 10, so infinitely many solutions","It gives x = 3, so one solution","It gives 10 = 7, so no solution","It gives 4x = 17, so one solution"],"answer":2,"hint":"Distribute the 2 and see whether the x terms cancel.","solution":"2x + 2(−x + 5) = 7 gives 2x − 2x + 10 = 7, so 10 = 7. False, so no solution."},{"id":"u2-sys4-q5","type":"input","prompt":"For y = 5x − 2 and y = kx + 7 to have no solution, what must k be?","answers":["5"],"hint":"No solution means parallel lines with different intercepts.","solution":"Parallel lines have the same slope, so k = 5. The intercepts −2 and 7 differ, so they never meet."},{"id":"u2-sys4-q6","type":"input","prompt":"Solve y = x − 3 and 2x + y = 12. What is y?","answers":["2"],"hint":"Replace y with x − 3 in the second equation.","solution":"2x + (x − 3) = 12, so 3x = 15 and x = 5. Then y = 5 − 3 = 2."},{"id":"u2-sys4-q7","type":"choice","prompt":"The line y = 2x + 1 is drawn. A second line has slope 2 and y-intercept 4. How many solutions does the system have?","choices":["One","None","Infinitely many","Two"],"answer":1,"hint":"Same slope, different intercept: what does that mean for the lines?","solution":"Both lines have slope 2 but different intercepts (1 and 4). They are parallel, so the system has no solution.","graph":{"fn":"2x+1","x":[-5,5],"y":[-5,10]}},{"id":"u2-sys4-q8","type":"input","prompt":"Hannah saves y = 20 + 5x dollars after x weeks. Ben saves y = 5 + 8x. After how many weeks do they have the same amount?","answers":["5"],"hint":"Set the two expressions equal.","solution":"20 + 5x = 5 + 8x, so 15 = 3x and x = 5. After 5 weeks each has $45."}]}]},{"id":"elimination","title":"Systems by elimination","lessons":[{"id":"elimination-1","teach":[{"title":"Add or subtract","text":["Line up the equations so the x terms, y terms, and numbers are in columns.","If one variable has opposite coefficients (like +y and −y), add the equations. If it has the same coefficient, subtract.","Solve for the leftover variable, then put it back to find the other."],"example":{"problem":"Solve x + y = 11 and x − y = 3.","steps":["The y terms are +y and −y, so add: 2x = 14.","x = 7.","Then 7 + y = 11, so y = 4. The solution is (7, 4)."]}}],"questions":[{"id":"u2-elim1-q1","type":"input","prompt":"Solve x + y = 11 and x − y = 3. What is x?","answers":["7"],"hint":"The y terms are opposites. Add the equations.","solution":"2x = 14, so x = 7. (Then y = 4.)"},{"id":"u2-elim1-q2","type":"input","prompt":"Solve 3x + y = 14 and 3x − y = 10. What is y?","answers":["2"],"hint":"Add to find x first, then put it back.","solution":"Add: 6x = 24, so x = 4. Then 12 + y = 14, so y = 2."},{"id":"u2-elim1-q3","type":"choice","prompt":"To eliminate y from 4x + 3y = 17 and 2x + 3y = 11, what should you do?","choices":["Add the equations","Subtract the second equation from the first","Subtract, to cancel the x terms","Add, to cancel the x terms"],"answer":1,"hint":"Both y terms are +3y. What cancels same terms?","solution":"The y coefficients are equal (+3y and +3y), so subtract. This leaves 2x = 6."},{"id":"u2-elim1-q4","type":"input","prompt":"Solve x + 2y = 9 and x − 2y = −1. What is y?","answers":["5/2","2.5"],"hint":"Add to get x. Then put x back in.","solution":"Add: 2x = 8, so x = 4. Then 4 + 2y = 9, so 2y = 5 and y = 5/2."},{"id":"u2-elim1-q5","type":"input","prompt":"Solve 5x + 2y = 16 and 3x + 2y = 8. What is y?","answers":["-2"],"hint":"Both have +2y. Subtract the equations.","solution":"Subtract: 2x = 8, so x = 4. Then 20 + 2y = 16, so y = −2."},{"id":"u2-elim1-q6","type":"choice","prompt":"Solve 2x + y = 7 and 4x − y = 5. Which is the solution?","choices":["(3, 1)","(1, 5)","(2, 3)","(2, −3)"],"answer":2,"hint":"The y terms are opposites. Add.","solution":"Add: 6x = 12, so x = 2. Then 4 + y = 7, so y = 3. The solution is (2, 3)."},{"id":"u2-elim1-q7","type":"input","prompt":"Two numbers add to 25 and differ by 7. What is the larger number?","answers":["16"],"hint":"Write x + y = 25 and x − y = 7, then add.","solution":"Add: 2x = 32, so x = 16. The other number is 9."},{"id":"u2-elim1-q8","type":"input","prompt":"Solve 3x − 4y = 1 and 5x + 4y = 23. What is x?","answers":["3"],"hint":"The y terms are −4y and +4y. Add.","solution":"Add: 8x = 24, so x = 3. (Then y = 2.)"}]},{"id":"elimination-2","teach":[{"title":"Multiply one equation","text":["If no variable cancels yet, multiply one whole equation so that one variable has opposite coefficients.","Multiply every term, including the number on the right."],"example":{"problem":"Solve 3x + 2y = 13 and x − y = 1.","steps":["Multiply the second equation by 2: 2x − 2y = 2.","Add: 3x + 2y = 13 and 2x − 2y = 2 give 5x = 15, so x = 3.","Then 3 − y = 1, so y = 2."]}}],"questions":[{"id":"u2-elim2-q1","type":"choice","prompt":"To eliminate y from 3x + 2y = 13 and x − y = 1, what is the best step?","choices":["Multiply x − y = 1 by 2, then add","Multiply x − y = 1 by 3, then add","Multiply x − y = 1 by −2, then add","Multiply 3x + 2y = 13 by 2, then add"],"answer":0,"hint":"You need +2y and −2y.","solution":"Multiplying x − y = 1 by 2 gives 2x − 2y = 2. Now the y terms are +2y and −2y, so add."},{"id":"u2-elim2-q2","type":"input","prompt":"Solve 3x + 2y = 13 and x − y = 1. What is x?","answers":["3"],"hint":"Multiply the second equation by 2 and add.","solution":"2x − 2y = 2. Add: 5x = 15, so x = 3. (Then y = 2.)"},{"id":"u2-elim2-q3","type":"input","prompt":"Solve 2x + y = 10 and 3x + 2y = 17. What is y?","answers":["4"],"hint":"Multiply the first equation by −2 to cancel y.","solution":"−4x − 2y = −20. Add to 3x + 2y = 17: −x = −3, so x = 3. Then 6 + y = 10, so y = 4."},{"id":"u2-elim2-q4","type":"input","prompt":"Solve 3x − y = 3 and 5x + 2y = 16. What is y?","answers":["3"],"hint":"Multiply the first equation by 2.","solution":"6x − 2y = 6. Add to 5x + 2y = 16: 11x = 22, so x = 2. Then 6 − y = 3, so y = 3."},{"id":"u2-elim2-q5","type":"choice","prompt":"Solve x + 3y = 5 and 3x + 2y = 1. Which is the solution?","choices":["(2, 1)","(1, −2)","(5, 0)","(−1, 2)"],"answer":3,"hint":"Multiply the first equation by −3 to cancel x.","solution":"−3x − 9y = −15. Add to 3x + 2y = 1: −7y = −14, so y = 2. Then x + 6 = 5, so x = −1."},{"id":"u2-elim2-q6","type":"input","prompt":"Solve 4x − y = 9 and 2x + 3y = 1. What is x?","answers":["2"],"hint":"Multiply the first equation by 3 to cancel y.","solution":"12x − 3y = 27. Add to 2x + 3y = 1: 14x = 28, so x = 2. (Then y = −1.)"},{"id":"u2-elim2-q7","type":"input","prompt":"3 muffins and 2 coffees cost $13. 1 muffin and 1 coffee cost $5. What does a coffee cost, in dollars?","answers":["2"],"hint":"Write 3m + 2c = 13 and m + c = 5. Multiply the second by 3 and subtract, or by −3 and add.","solution":"3m + 3c = 15. Subtract 3m + 2c = 13: c = 2. A coffee costs $2."},{"id":"u2-elim2-q8","type":"choice","prompt":"What do you get when you multiply every term of x − y = 4 by 3?","choices":["3x − y = 12","3x − 3y = 12","3x − 3y = 4","x − 3y = 12"],"answer":1,"hint":"Multiply each term, including the 4.","solution":"3 · x = 3x, 3 · (−y) = −3y, and 3 · 4 = 12. So 3x − 3y = 12."}]},{"id":"elimination-3","teach":[{"title":"Multiply both equations","text":["Sometimes you must multiply both equations. Choose a variable to cancel, then find a common multiple of its coefficients.","Make one coefficient positive and the other negative so that you can add."],"example":{"problem":"Solve 3x + 4y = 8 and 2x + 5y = 3.","steps":["Cancel x. Multiply the first by 2 and the second by −3: 6x + 8y = 16 and −6x − 15y = −9.","Add: −7y = 7, so y = −1.","Then 3x − 4 = 8, so x = 4. The solution is (4, −1)."]}}],"questions":[{"id":"u2-elim3-q1","type":"choice","prompt":"To eliminate x from 2x + 3y = 7 and 3x + 5y = 11 by adding, what should you do?","choices":["Multiply the first by 3 and the second by 2","Multiply the first by 3 and the second by −2","Multiply the first by 5 and the second by 3","Multiply both by −1"],"answer":1,"hint":"You need +6x and −6x.","solution":"3 × first gives 6x + 9y = 21. −2 × second gives −6x − 10y = −22. The x terms cancel when added."},{"id":"u2-elim3-q2","type":"input","prompt":"Solve 3x + 4y = 8 and 2x + 5y = 3. What is y?","answers":["-1"],"hint":"Multiply the first by 2 and the second by −3.","solution":"6x + 8y = 16 and −6x − 15y = −9. Add: −7y = 7, so y = −1. (Then x = 4.)"},{"id":"u2-elim3-q3","type":"input","prompt":"Solve 5x + 2y = 1 and 3x − 5y = 13. What is x?","answers":["1"],"hint":"To cancel y, multiply the first by 5 and the second by 2.","solution":"25x + 10y = 5 and 6x − 10y = 26. Add: 31x = 31, so x = 1. (Then y = −2.)"},{"id":"u2-elim3-q4","type":"input","prompt":"Solve 2x + 3y = 16 and 5x − 2y = 21. What is y?","answers":["2"],"hint":"To cancel y, multiply the first by 2 and the second by 3.","solution":"4x + 6y = 32 and 15x − 6y = 63. Add: 19x = 95, so x = 5. Then 10 + 3y = 16, so y = 2."},{"id":"u2-elim3-q5","type":"choice","prompt":"Solve 3x − 2y = 8 and 2x + 5y = −1. Which is the solution?","choices":["(−2, 1)","(1, −2)","(2, −1)","(4, 2)"],"answer":2,"hint":"To cancel y, multiply the first by 5 and the second by 2.","solution":"15x − 10y = 40 and 4x + 10y = −2. Add: 19x = 38, so x = 2. Then 6 − 2y = 8, so y = −1."},{"id":"u2-elim3-q6","type":"input","prompt":"Solve 6x + 5y = 3 and 4x − 3y = 21. What is y?","answers":["-3"],"hint":"To cancel y, multiply the first by 3 and the second by 5.","solution":"18x + 15y = 9 and 20x − 15y = 105. Add: 38x = 114, so x = 3. Then 18 + 5y = 3, so y = −3."},{"id":"u2-elim3-q7","type":"input","prompt":"2 sandwiches and 3 drinks cost $19. 3 sandwiches and 2 drinks cost $21. What does a sandwich cost, in dollars?","answers":["5"],"hint":"Write 2s + 3d = 19 and 3s + 2d = 21. Multiply to make the s terms match.","solution":"3 × first: 6s + 9d = 57. 2 × second: 6s + 4d = 42. Subtract: 5d = 15, so d = 3. Then 2s + 9 = 19, so s = 5."},{"id":"u2-elim3-q8","type":"choice","prompt":"You multiply 4x + 3y = 6 by 2 and 5x − 2y = 19 by 3. What is the correct next step?","choices":["Subtract: −7x = −45","Add: 23x = 45","Add: 7x = 69","Add: 23x = 69"],"answer":3,"hint":"Write both new equations first. The y terms should be +6y and −6y.","solution":"8x + 6y = 12 and 15x − 6y = 57. The y terms are opposites, so add: 23x = 69."}]},{"id":"elimination-4","teach":[{"title":"Special cases and rearranging","text":["First put both equations in the form Ax + By = C. Then eliminate.","If everything cancels and you get a false statement like 0 = −3, there is no solution.","If you get a true statement like 0 = 0, there are infinitely many solutions."],"example":{"problem":"Solve 3x − y = 4 and 6x − 2y = 5.","steps":["Multiply the first by −2: −6x + 2y = −8.","Add to 6x − 2y = 5: 0 = −3.","That is false, so there is no solution."]}}],"questions":[{"id":"u2-elim4-q1","type":"choice","prompt":"Solve 2x + 4y = 6 and x + 2y = 3. What happens?","choices":["Infinitely many solutions","No solution","One solution","Two solutions"],"answer":0,"hint":"Multiply the second equation by −2 and add.","solution":"−2x − 4y = −6. Add to 2x + 4y = 6: 0 = 0. That is true, so there are infinitely many solutions."},{"id":"u2-elim4-q2","type":"choice","prompt":"Solve 3x − y = 4 and 6x − 2y = 5. What happens?","choices":["Infinitely many solutions","No solution","One solution","The solution is (0, 0)"],"answer":1,"hint":"Multiply the first equation by −2 and add.","solution":"−6x + 2y = −8. Add to 6x − 2y = 5: 0 = −3. False, so no solution."},{"id":"u2-elim4-q3","type":"input","prompt":"Solve y = 2x − 5 and 3x + y = 5. What is y?","answers":["-1"],"hint":"Rewrite the first as −2x + y = −5. Then subtract or substitute.","solution":"Subtract (−2x + y = −5) from (3x + y = 5): 5x = 10, so x = 2. Then y = 2(2) − 5 = −1."},{"id":"u2-elim4-q4","type":"input","prompt":"For 2x + 3y = 5 and 4x + 6y = k, what k gives infinitely many solutions?","answers":["10"],"hint":"The second equation must be a multiple of the first.","solution":"Multiply the first by 2: 4x + 6y = 10. So k = 10."},{"id":"u2-elim4-q5","type":"input","prompt":"Solve 2x + 5y = 11 and 4x − 3y = −17. What is x?","answers":["-2"],"hint":"Multiply the first equation by −2 to cancel x.","solution":"−4x − 10y = −22. Add to 4x − 3y = −17: −13y = −39, so y = 3. Then 2x + 15 = 11, so x = −2."},{"id":"u2-elim4-q6","type":"choice","prompt":"Solve 5x + 2y = 4 and 3x + 2y = 0. Which is the solution?","choices":["(−2, 3)","(2, −3)","(2, 3)","(4, −8)"],"answer":1,"hint":"Both have +2y. Subtract.","solution":"Subtract: 2x = 4, so x = 2. Then 6 + 2y = 0, so y = −3. The solution is (2, −3)."},{"id":"u2-elim4-q7","type":"input","prompt":"Twice the first number plus the second is 17. The first minus the second is 1. What is the first number?","answers":["6"],"hint":"Write 2a + b = 17 and a − b = 1. Add.","solution":"Add: 3a = 18, so a = 6. Then b = 5."},{"id":"u2-elim4-q8","type":"input","prompt":"The solution of x + y = 7 and x − y = k has x = 5. What is k?","answers":["3"],"hint":"Find y from the first equation, then find k.","solution":"x + y = 7 gives y = 2. Then k = 5 − 2 = 3."}]}]},{"id":"system-applications","title":"System word problems and systems of inequalities","lessons":[{"id":"system-applications-1","teach":[{"title":"Write the system","text":["Choose a variable for each unknown. Write one equation for the counts and one equation for the money (or value).","Solve with substitution or elimination. Then answer the question that was asked."],"example":{"problem":"Tickets cost $9 for adults and $5 for students. 80 tickets sold for $520. How many adult tickets?","steps":["Let a = adults and s = students. a + s = 80 and 9a + 5s = 520.","Substitute s = 80 − a: 9a + 5(80 − a) = 520, so 4a + 400 = 520.","a = 30. There were 30 adult tickets."]}}],"questions":[{"id":"u2-app1-q1","type":"choice","prompt":"Adult tickets cost $9 and student tickets cost $5. 80 tickets sold for $520. Which system fits (a = adults, s = students)?","choices":["a + s = 520 and 9a + 5s = 80","a + s = 80 and 5a + 9s = 520","a + s = 80 and 9a + 5s = 520","a + s = 14 and 9a + 5s = 520"],"answer":2,"hint":"One equation counts tickets. The other adds up the money.","solution":"Number of tickets: a + s = 80. Money: 9a + 5s = 520."},{"id":"u2-app1-q2","type":"input","prompt":"Solve a + s = 80 and 9a + 5s = 520. How many adult tickets were sold?","answers":["30"],"hint":"Replace s with 80 − a in the money equation.","solution":"9a + 5(80 − a) = 520, so 4a + 400 = 520 and a = 30."},{"id":"u2-app1-q3","type":"input","prompt":"A jar has 15 coins, all nickels and dimes, worth 115 cents. How many dimes?","answers":["8"],"hint":"Let n = nickels and d = dimes. n + d = 15 and 5n + 10d = 115.","solution":"n = 15 − d. 5(15 − d) + 10d = 115, so 75 + 5d = 115 and d = 8. (7 nickels, 8 dimes: 35 + 80 = 115.)"},{"id":"u2-app1-q4","type":"choice","prompt":"Two numbers add to 30. One is 4 more than the other. Which system fits?","choices":["x + y = 30 and x = 4y","x + y = 30 and x = y + 4","x + y = 4 and x = y + 30","x − y = 30 and x = y + 4"],"answer":1,"hint":"\"4 more than\" means add 4.","solution":"Sum: x + y = 30. \"4 more than the other\": x = y + 4."},{"id":"u2-app1-q5","type":"input","prompt":"Two numbers add to 30. One is 4 more than the other. What is the larger number?","answers":["17"],"hint":"Replace x with y + 4 in x + y = 30.","solution":"(y + 4) + y = 30, so y = 13. Then x = 17."},{"id":"u2-app1-q6","type":"input","prompt":"Plan A costs $20 to join plus $10 a month. Plan B has no joining fee and costs $15 a month. After how many months do the plans cost the same?","answers":["4"],"hint":"Write each total cost and set them equal.","solution":"20 + 10m = 15m, so 20 = 5m and m = 4. Both cost $60."},{"id":"u2-app1-q7","type":"choice","prompt":"Pens cost $2 and notebooks cost $3. Maria buys 12 items for $31. Which purchase did she make?","choices":["7 pens and 5 notebooks","5 pens and 7 notebooks","6 pens and 6 notebooks","4 pens and 8 notebooks"],"answer":1,"hint":"Check each choice: the count must be 12 and the cost $31.","solution":"5 pens + 7 notebooks: 5 + 7 = 12 and 10 + 21 = 31. The others give $29, $30, and $32."},{"id":"u2-app1-q8","type":"input","prompt":"A shop sells hats for $12 and scarves for $8. It sold 25 items for $260. How many hats?","answers":["15"],"hint":"Let h = hats. Then scarves = 25 − h.","solution":"12h + 8(25 − h) = 260, so 4h + 200 = 260 and h = 15. (10 scarves: 180 + 80 = 260.)"}]},{"id":"system-applications-2","teach":[{"title":"Mixtures, rates, and ages","text":["For a mixture, the amount of pure substance is amount × percent. Use one equation for total amount and one for total pure substance.","For a boat in a current: downstream speed = boat + current, upstream speed = boat − current.","For ages, write each person's age now, then add the years later to each."],"example":{"problem":"Mix 10% and 30% solution to make 20 L of 22% solution.","steps":["x + y = 20 and 0.10x + 0.30y = 0.22(20) = 4.4.","Substitute x = 20 − y: 0.10(20 − y) + 0.30y = 4.4, so 2 + 0.2y = 4.4.","y = 12 L of the 30%, and x = 8 L of the 10%."]}}],"questions":[{"id":"u2-app2-q1","type":"choice","prompt":"Mix x L of 10% solution and y L of 30% solution to make 20 L of 22% solution. Which system fits?","choices":["x + y = 20 and 0.10x + 0.30y = 22","x + y = 20 and 0.10x + 0.30y = 4.4","x + y = 22 and 0.10x + 0.30y = 20","x + y = 20 and 10x + 30y = 4.4"],"answer":1,"hint":"Total pure amount = 0.22 × 20.","solution":"Total volume: x + y = 20. Pure substance: 0.10x + 0.30y = 0.22(20) = 4.4."},{"id":"u2-app2-q2","type":"input","prompt":"Solve x + y = 20 and 0.10x + 0.30y = 4.4. How many litres of 30% solution are needed?","answers":["12"],"hint":"Put x = 20 − y into the second equation.","solution":"0.10(20 − y) + 0.30y = 4.4, so 2 + 0.2y = 4.4 and y = 12."},{"id":"u2-app2-q3","type":"input","prompt":"A $3 per lb coffee is mixed with an $8 per lb coffee to make 20 lb worth $100 in all. How many pounds of the $8 coffee?","answers":["8"],"hint":"x + y = 20 and 3x + 8y = 100.","solution":"x = 20 − y. 3(20 − y) + 8y = 100, so 60 + 5y = 100 and y = 8."},{"id":"u2-app2-q4","type":"input","prompt":"A boat goes 18 mph downstream and 10 mph upstream. What is its speed in still water, in mph?","answers":["14"],"hint":"b + c = 18 and b − c = 10. Add them.","solution":"Add: 2b = 28, so b = 14. (The current is 4 mph.)"},{"id":"u2-app2-q5","type":"choice","prompt":"A boat goes 24 km downstream in 2 hours and 24 km back upstream in 3 hours. Which system gives the boat speed b and current c?","choices":["b + c = 12 and b − c = 8","b + c = 24 and b − c = 24","b + c = 2 and b − c = 3","b + c = 12 and b − c = 24"],"answer":0,"hint":"Speed = distance ÷ time for each trip.","solution":"Downstream speed: 24 ÷ 2 = 12, so b + c = 12. Upstream speed: 24 ÷ 3 = 8, so b − c = 8."},{"id":"u2-app2-q6","type":"choice","prompt":"Can you mix a 10% solution and a 30% solution to make a 35% solution?","choices":["Yes, use more of the 30% solution","Yes, use equal parts","No, a mix must fall between 10% and 30%","No, 35 is not a multiple of 10"],"answer":2,"hint":"Think about what the mixture is made of.","solution":"A mixture of two solutions has a strength between the two. 35% is more than both, so it is impossible."},{"id":"u2-app2-q7","type":"input","prompt":"$5000 is split between a 3% account and a 5% account. After one year the interest is $190. How many dollars are in the 5% account?","answers":["2000"],"hint":"x + y = 5000 and 0.03x + 0.05y = 190.","solution":"x = 5000 − y. 0.03(5000 − y) + 0.05y = 190, so 150 + 0.02y = 190 and y = 2000."},{"id":"u2-app2-q8","type":"input","prompt":"A father is 4 times as old as Ben. In 6 years he will be 3 times as old as Ben. How old is Ben now?","answers":["12"],"hint":"f = 4b. In 6 years: f + 6 = 3(b + 6).","solution":"4b + 6 = 3(b + 6) = 3b + 18, so b = 12. The father is 48 (54 = 3 · 18 in 6 years)."}]},{"id":"system-applications-3","teach":[{"title":"Systems of inequalities","text":["A solution of a system of inequalities must make all of the inequalities true.","On a graph, it is the region where all the shadings overlap. A point is in it only if it passes every test.","Constraints like x ≥ 0 and y ≥ 0 keep the region in the top-right quarter."],"example":{"problem":"Is (2, 3) a solution of y > x and y ≤ 5?","steps":["First: 3 > 2 is true.","Second: 3 ≤ 5 is true.","Both are true, so (2, 3) is in the region."]}}],"questions":[{"id":"u2-app3-q1","type":"choice","prompt":"Is (2, 3) a solution of y > x and y ≤ 5?","choices":["Yes, it satisfies both","No, 3 > 2 is false","No, 3 ≤ 5 is false","Only if y = x"],"answer":0,"hint":"Test each inequality separately.","solution":"3 > 2 is true and 3 ≤ 5 is true. It is in the region."},{"id":"u2-app3-q2","type":"choice","prompt":"Is (3, 3) a solution of x + y ≤ 6 and x − y > 1?","choices":["Yes, it satisfies both","No, it fails x − y > 1","No, it fails x + y ≤ 6","No, it fails both"],"answer":1,"hint":"Test each inequality. Remember that > does not allow equal.","solution":"x + y = 6 ≤ 6 is true. x − y = 0 > 1 is false. So (3, 3) is not a solution."},{"id":"u2-app3-q3","type":"input","prompt":"How many of the points (0, 0), (1, 1), (2, 0), (3, 3), (0, 2) satisfy both y ≤ x + 1 and y ≥ 1?","answers":["2"],"hint":"Test each point in both inequalities.","solution":"(0, 0): y ≥ 1 false. (1, 1): 1 ≤ 2 and 1 ≥ 1, true. (2, 0): false. (3, 3): 3 ≤ 4 and 3 ≥ 1, true. (0, 2): 2 ≤ 1 false. Two points."},{"id":"u2-app3-q4","type":"choice","prompt":"The region is x ≥ 0, y ≥ 0, x + y ≤ 4. Which point is in it?","choices":["(3, 2)","(−1, 2)","(4, 1)","(1, 3)"],"answer":3,"hint":"The point needs both coordinates at least 0 and a sum of 4 or less.","solution":"(1, 3): x, y ≥ 0 and 1 + 3 = 4 ≤ 4, true. (3, 2) has sum 5. (−1, 2) has x < 0. (4, 1) has sum 5."},{"id":"u2-app3-q5","type":"input","prompt":"Take x = 4 in x + y ≤ 10 and y ≥ 2x − 3. What is the largest whole number y that works?","answers":["6"],"hint":"The first gives y ≤ 10 − 4. The second gives y ≥ 2(4) − 3.","solution":"x + y ≤ 10 gives y ≤ 6. y ≥ 2(4) − 3 gives y ≥ 5. So y = 5 or 6, and the largest is 6."},{"id":"u2-app3-q6","type":"input","prompt":"The boundary lines x + y = 4 and y = x cross. What is x at the crossing?","answers":["2"],"hint":"Substitute y = x into x + y = 4.","solution":"x + x = 4, so x = 2. The corner is (2, 2)."},{"id":"u2-app3-q7","type":"choice","prompt":"A student works at most 20 hours a week (x hours tutoring, y hours at a cafe) and wants at least $200. Tutoring pays $15 an hour and the cafe pays $10 an hour. Which system fits?","choices":["x + y ≥ 20 and 15x + 10y ≤ 200","x + y ≤ 20 and 15x + 10y ≥ 200","x + y ≤ 20 and 10x + 15y ≥ 200","x + y ≤ 200 and 15x + 10y ≥ 20"],"answer":1,"hint":"\"At most\" is ≤ and \"at least\" is ≥. Match each pay rate to its hours.","solution":"Hours: x + y ≤ 20. Pay: 15x + 10y ≥ 200."},{"id":"u2-app3-q8","type":"choice","prompt":"Which point works for x + y ≤ 20 and 15x + 10y ≥ 200?","choices":["(5, 10)","(8, 14)","(4, 4)","(10, 5)"],"answer":3,"hint":"Test each point in both inequalities.","solution":"(10, 5): 15 ≤ 20 and 150 + 50 = 200 ≥ 200, true. (5, 10): pay 175, too low. (8, 14): 22 hours, too many. (4, 4): pay 100, too low."}]},{"id":"system-applications-4","teach":[{"title":"Putting it together","text":["Read the problem slowly: name your variables, write the equations, solve, and check in the words of the problem.","A feasible region is the overlap of all the constraint inequalities. Corner points are found where two boundary lines cross."],"example":{"problem":"Adult tickets cost $12 and child tickets cost $7. 150 tickets were sold for $1400. How many child tickets?","steps":["a + c = 150 and 12a + 7c = 1400.","Substitute a = 150 − c: 12(150 − c) + 7c = 1400, so 1800 − 5c = 1400.","c = 80. There were 80 child tickets."]}}],"questions":[{"id":"u2-app4-q1","type":"input","prompt":"Adult tickets cost $12 and child tickets cost $7. 150 tickets were sold for $1400. How many child tickets were sold?","answers":["80"],"hint":"a + c = 150 and 12a + 7c = 1400. Replace a with 150 − c.","solution":"12(150 − c) + 7c = 1400, so 1800 − 5c = 1400 and c = 80. (70 adult tickets: 840 + 560 = 1400.)"},{"id":"u2-app4-q2","type":"input","prompt":"A jar has 30 coins, all quarters and dimes, worth $5.10. How many quarters?","answers":["14"],"hint":"Use cents: q + d = 30 and 25q + 10d = 510.","solution":"d = 30 − q. 25q + 10(30 − q) = 510, so 15q + 300 = 510 and q = 14. (16 dimes: 350 + 160 = 510.)"},{"id":"u2-app4-q3","type":"input","prompt":"How many litres of 50% acid must be mixed with 20% acid to make 30 L of 40% acid?","answers":["20"],"hint":"x + y = 30 and 0.5x + 0.2y = 0.4(30) = 12.","solution":"y = 30 − x. 0.5x + 0.2(30 − x) = 12, so 0.3x + 6 = 12 and x = 20. (10 L of the 20%.)"},{"id":"u2-app4-q4","type":"input","prompt":"A rectangle has a length that is 2 more than twice its width. Its perimeter is 52. What is its width?","answers":["8"],"hint":"L = 2W + 2 and 2L + 2W = 52, so L + W = 26.","solution":"(2W + 2) + W = 26, so 3W = 24 and W = 8. The length is 18."},{"id":"u2-app4-q5","type":"choice","prompt":"Car A costs $30 plus $0.20 per mile. Car B costs $20 plus $0.30 per mile. For which distances is Car A cheaper?","choices":["Less than 100 miles","More than 100 miles","Exactly 100 miles","Always"],"answer":1,"hint":"Find where the costs are equal first. Then test a bigger distance.","solution":"Equal when 30 + 0.2m = 20 + 0.3m, so m = 100. At 200 miles A costs $70 and B costs $80, so A is cheaper for more than 100 miles."},{"id":"u2-app4-q6","type":"input","prompt":"A shop spends $500 to set up and $4 per item. It sells each item for $9. How many items give break-even (cost = revenue)?","answers":["100"],"hint":"Cost is 500 + 4x. Revenue is 9x.","solution":"500 + 4x = 9x, so 500 = 5x and x = 100."},{"id":"u2-app4-q7","type":"choice","prompt":"The region is x ≥ 0, y ≥ 0, 2x + y ≤ 10 and x + 2y ≤ 8. Which point is in it?","choices":["(5, 1)","(2, 4)","(4, 2)","(0, 5)"],"answer":2,"hint":"Test each point in 2x + y ≤ 10 and x + 2y ≤ 8.","solution":"(4, 2): 10 ≤ 10 and 8 ≤ 8, true. (5, 1): 11 > 10. (2, 4): 10 ≤ 10 but 10 > 8. (0, 5): 5 ≤ 10 but 10 > 8."},{"id":"u2-app4-q8","type":"input","prompt":"The boundary lines 2x + y = 10 and x + 2y = 8 cross at a corner of the region. What is its x-coordinate?","answers":["4"],"hint":"Multiply x + 2y = 8 by 2 so the x terms match, then subtract.","solution":"2x + 4y = 16. Subtract 2x + y = 10: 3y = 6, so y = 2. Then 2x + 2 = 10, so x = 4."}]}]},{"id":"three-variables","title":"Systems in three variables","lessons":[{"id":"three-variables-1","teach":[{"title":"Ordered triples","text":["A solution of a system in three variables is an ordered triple (x, y, z). It must make all three equations true.","To check a triple, put it into each equation. If it fails even one, it is not a solution."],"example":{"problem":"Is (1, 2, 3) a solution of x + y + z = 6, 2x − y + z = 3, x + 2y − z = 2?","steps":["First: 1 + 2 + 3 = 6, true.","Second: 2 − 2 + 3 = 3, true.","Third: 1 + 4 − 3 = 2, true.","All three work, so yes."]}}],"questions":[{"id":"u2-tri1-q1","type":"choice","prompt":"Is (1, 2, 3) a solution of x + y + z = 6, 2x − y + z = 3, x + 2y − z = 2?","choices":["Yes, it satisfies all three","No, it fails the first equation","No, it fails the second equation","No, it fails the third equation"],"answer":0,"hint":"Put the triple in each equation in turn.","solution":"1 + 2 + 3 = 6, 2 − 2 + 3 = 3, and 1 + 4 − 3 = 2. All are true."},{"id":"u2-tri1-q2","type":"choice","prompt":"Is (2, 1, 3) a solution of x + y + z = 6, 2x − y + z = 3, x + 2y − z = 2?","choices":["Yes, it satisfies all three","No, it fails the second and third equations","No, it fails only the second equation","No, it fails only the third equation"],"answer":1,"hint":"Check all three. The first one works, but what about the others?","solution":"First: 2 + 1 + 3 = 6, true. Second: 4 − 1 + 3 = 6, not 3. Third: 2 + 2 − 3 = 1, not 2. It fails two equations."},{"id":"u2-tri1-q3","type":"input","prompt":"In x + y + z = 10, x − y = 2, y + z = 7, what is z?","answers":["6"],"hint":"Since y + z = 7, the first equation gives x. Then find y.","solution":"x + 7 = 10, so x = 3. Then y = 3 − 2 = 1, and z = 7 − 1 = 6."},{"id":"u2-tri1-q4","type":"input","prompt":"The triple (2, −1, 3) satisfies 3x + y + kz = 11. What is k?","answers":["2"],"hint":"Put x = 2, y = −1, z = 3 in.","solution":"6 − 1 + 3k = 11, so 3k = 6 and k = 2."},{"id":"u2-tri1-q5","type":"choice","prompt":"Which triple solves x + y + z = 9, x − y = 1, z = 2?","choices":["(3, 4, 2)","(4, 2, 3)","(2, 3, 4)","(4, 3, 2)"],"answer":3,"hint":"z is given. Then x + y = 7 and x − y = 1.","solution":"z = 2, so x + y = 7. With x − y = 1, add: 2x = 8, so x = 4 and y = 3. The triple is (4, 3, 2)."},{"id":"u2-tri1-q6","type":"input","prompt":"Solve y = 4, z = 2y, x + y + z = 20. What is x?","answers":["8"],"hint":"Find z from y. Then use the sum.","solution":"z = 2(4) = 8. Then x + 4 + 8 = 20, so x = 8."},{"id":"u2-tri1-q7","type":"choice","prompt":"A triple makes equations 1 and 2 true but equation 3 false. Is it a solution of the system?","choices":["Yes, two out of three is enough","No, it must make all three equations true","Yes, if equation 3 is the longest","Only if z = 0"],"answer":1,"hint":"A solution has to work in every equation.","solution":"A solution of a system must satisfy every equation. One false equation means it is not a solution."},{"id":"u2-tri1-q8","type":"input","prompt":"x + y + z = 7, x + y = 5, y + z = 4. What is y?","answers":["2"],"hint":"The first two give z. Then use y + z = 4.","solution":"7 − 5 = 2, so z = 2. Then y = 4 − 2 = 2. (And x = 3.)"}]},{"id":"three-variables-2","teach":[{"title":"Eliminate down to two equations","text":["Pick one variable. Eliminate it from two different pairs of equations. This gives two equations in two variables.","Solve those two, then put the values back to find the third variable."],"example":{"problem":"Solve x + y + z = 10, 2x − y + 3z = 19, x + 2y − z = 2.","steps":["Add the first two: 3x + 4z = 29 (y is gone).","Do 2 × (first) − (third): x + 3z = 18 (y is gone).","Solve: x = 18 − 3z, so 54 − 9z + 4z = 29, z = 5, x = 3.","Then y = 10 − 3 − 5 = 2. The solution is (3, 2, 5)."]}}],"questions":[{"id":"u2-tri2-q1","type":"choice","prompt":"Add x + y + z = 10 and 2x − y + 3z = 19. Which equation do you get?","choices":["3x + 2z = 29","3x + 2y + 4z = 29","3x + 4z = 29","3x + 4z = 9"],"answer":2,"hint":"The y terms are +y and −y. Add all terms, including the numbers.","solution":"x + 2x = 3x, y − y = 0, z + 3z = 4z, and 10 + 19 = 29. So 3x + 4z = 29."},{"id":"u2-tri2-q2","type":"input","prompt":"Multiply x + y + z = 10 by 2 and subtract x + 2y − z = 2. The result is x + 3z = k. What is k?","answers":["18"],"hint":"Subtract every term, including the numbers: 20 − 2.","solution":"2x + 2y + 2z = 20. Subtract: x + 3z = 18. So k = 18."},{"id":"u2-tri2-q3","type":"input","prompt":"Solve 3x + 4z = 29 and x + 3z = 18. What is z?","answers":["5"],"hint":"Solve the second for x, then substitute.","solution":"x = 18 − 3z. 3(18 − 3z) + 4z = 29, so 54 − 5z = 29 and z = 5. (Then x = 3.)"},{"id":"u2-tri2-q4","type":"input","prompt":"Solve x + y + z = 10 with x = 3 and z = 5. What is y?","answers":["2"],"hint":"Put the known values in.","solution":"3 + y + 5 = 10, so y = 2."},{"id":"u2-tri2-q5","type":"choice","prompt":"Which triple solves x + y + z = 10, 2x − y + 3z = 19, x + 2y − z = 2?","choices":["(2, 3, 5)","(5, 2, 3)","(3, 5, 2)","(3, 2, 5)"],"answer":3,"hint":"Test each triple in the second equation first. It rules out three of them.","solution":"(3, 2, 5): 10, 6 − 2 + 15 = 19, 3 + 4 − 5 = 2. All true. The others fail the second equation."},{"id":"u2-tri2-q6","type":"choice","prompt":"Add equations (2) and (3) of x + y + z = 5, x − y + z = 7, 2x + y − z = −1. What do you get?","choices":["3x + 2z = 6","3x = 6","x + 2y = 6","3x = 8"],"answer":1,"hint":"In (2) and (3), −y and +y cancel, and +z and −z cancel.","solution":"x + 2x = 3x, −y + y = 0, z − z = 0, and 7 + (−1) = 6. So 3x = 6."},{"id":"u2-tri2-q7","type":"input","prompt":"For x + y + z = 5, x − y + z = 7, 2x + y − z = −1, you find x = 2. Add (1) and (2) to find z.","answers":["4"],"hint":"Add the first two equations: y cancels.","solution":"2x + 2z = 12. With x = 2: 4 + 2z = 12, so z = 4."},{"id":"u2-tri2-q8","type":"input","prompt":"For x + y + z = 5 with x = 2 and z = 4, what is y?","answers":["-1"],"hint":"Put x and z in the first equation.","solution":"2 + y + 4 = 5, so y = −1."}]},{"id":"three-variables-3","teach":[{"title":"Solve a full system","text":["Choose a variable that is easy to cancel. Make two new equations without it, solve them, and go back.","Always check your triple in all three original equations.","If elimination gives a false statement like 0 = 5, there is no solution. A true one like 0 = 0 means infinitely many solutions."],"example":{"problem":"Solve x + y = 5, y + z = 7, x + z = 6.","steps":["Add all three: 2x + 2y + 2z = 18, so x + y + z = 9.","Then z = 9 − 5 = 4, x = 9 − 7 = 2, y = 9 − 6 = 3.","The solution is (2, 3, 4)."]}}],"questions":[{"id":"u2-tri3-q1","type":"input","prompt":"Solve x + y + z = 6, 2x + y − z = 2, x − y + z = 4. What is y?","answers":["1"],"hint":"Subtract the third equation from the first. Which variable is left?","solution":"Subtract (x − y + z = 4) from (x + y + z = 6): 2y = 2, so y = 1. (Then x = 2 and z = 3.)"},{"id":"u2-tri3-q2","type":"input","prompt":"Solve x + y + z = 12, x − y = 2, y − z = −1. What is z?","answers":["4"],"hint":"Write x and z using y.","solution":"x = y + 2 and z = y + 1. So (y + 2) + y + (y + 1) = 12, giving 3y = 9 and y = 3. Then z = 4."},{"id":"u2-tri3-q3","type":"input","prompt":"Solve x + y + z = 4, 2x − y + z = −3, x + 2y − 3z = −1. What is x?","answers":["-1"],"hint":"Add the first two. Then do 2 × (first) − third. Both remove y.","solution":"(1)+(2): 3x + 2z = 1. 2(1) − (3): x + 5z = 9. So x = 9 − 5z, 27 − 15z + 2z = 1, and z = 2. Then x = −1."},{"id":"u2-tri3-q4","type":"choice","prompt":"Which triple solves x + y + z = 0, x − y + 2z = 8, 2x + y − z = −3?","choices":["(−1, 3, −2)","(1, 3, −4)","(1, −3, 2)","(2, −3, 1)"],"answer":2,"hint":"Test the triples in the second equation. Most fail there.","solution":"(1, −3, 2): 0, 1 + 3 + 4 = 8, 2 − 3 − 2 = −3. All true. The others fail the second equation."},{"id":"u2-tri3-q5","type":"input","prompt":"Three numbers add to 24. The second is twice the first. The third is 4 more than the second. What is the largest?","answers":["12"],"hint":"Let the first be a. The second is 2a and the third is 2a + 4.","solution":"a + 2a + (2a + 4) = 24, so 5a = 20 and a = 4. The numbers are 4, 8, 12. The largest is 12."},{"id":"u2-tri3-q6","type":"input","prompt":"Solve x + y = 5, y + z = 7, x + z = 6. What is y?","answers":["3"],"hint":"Add all three equations. That gives the sum x + y + z.","solution":"2(x + y + z) = 18, so the sum is 9. Then y = 9 − (x + z) = 9 − 6 = 3."},{"id":"u2-tri3-q7","type":"choice","prompt":"While eliminating, you reach 0 = 5. What does this tell you?","choices":["The system has infinitely many solutions","The system has no solution","The solution has x = 0","The solution is the origin"],"answer":1,"hint":"Is 0 = 5 ever true?","solution":"0 = 5 is false for every triple, so no triple can satisfy all the equations. The system has no solution."},{"id":"u2-tri3-q8","type":"input","prompt":"A jar has 20 coins: pennies, nickels, and dimes, worth 112 cents. There are 2 more pennies than nickels. How many dimes?","answers":["8"],"hint":"p + n + d = 20, p + 5n + 10d = 112, p = n + 2.","solution":"p = n + 2 gives d = 18 − 2n. Then (n + 2) + 5n + 10(18 − 2n) = 112, so 182 − 14n = 112 and n = 5. Then p = 7 and d = 8."}]},{"id":"three-variables-4","teach":[{"title":"Three-variable word problems","text":["Name three unknowns and write three equations: one for the total count, one for the total value, and one for the extra fact.","Solve, then answer the question and check each fact in words."],"example":{"problem":"Adult, student, and child tickets: 30 sold for $170. Adult costs $8, student $5, child $3. There are twice as many adult as child tickets. How many student tickets?","steps":["a + s + c = 30, 8a + 5s + 3c = 170, a = 2c.","Substitute: s = 30 − 3c, and 16c + 5(30 − 3c) + 3c = 170, so 4c + 150 = 170.","c = 5, a = 10, s = 15."]}}],"questions":[{"id":"u2-tri4-q1","type":"input","prompt":"Adult, student, and child tickets cost $8, $5, and $3. 30 tickets sold for $170, with twice as many adult as child tickets. How many student tickets were sold?","answers":["15"],"hint":"a + s + c = 30, 8a + 5s + 3c = 170, a = 2c.","solution":"Substitute a = 2c: s = 30 − 3c. Then 16c + 5(30 − 3c) + 3c = 170, so 4c + 150 = 170 and c = 5. Then a = 10 and s = 15."},{"id":"u2-tri4-q2","type":"input","prompt":"The first number is 5 less than the second. The third is double the first. The three add to 25. What is the third number?","answers":["10"],"hint":"Let the second be b. First is b − 5, third is 2(b − 5).","solution":"(b − 5) + b + 2(b − 5) = 25, so 4b − 15 = 25 and b = 10. The first is 5, the third is 10."},{"id":"u2-tri4-q3","type":"choice","prompt":"Is (4, −2, 1) a solution of x + y + z = 3, 2x − y = 10, y + 3z = 1?","choices":["No, it fails the first equation","No, it fails the second equation","No, it fails the third equation","Yes, it satisfies all three"],"answer":3,"hint":"Test each equation with x = 4, y = −2, z = 1.","solution":"4 − 2 + 1 = 3, 8 + 2 = 10, and −2 + 3 = 1. All true."},{"id":"u2-tri4-q4","type":"input","prompt":"The triple (1, 2, −1) satisfies x + 2y + kz = 2. What is k?","answers":["3"],"hint":"Put the values in and solve for k.","solution":"1 + 4 + k(−1) = 2, so 5 − k = 2 and k = 3."},{"id":"u2-tri4-q5","type":"choice","prompt":"To solve x + y + z = 11, x − y = 1, y − z = 2, what is the smartest first step?","choices":["Write x and z in terms of y, then substitute into the first equation","Add all three equations","Multiply the first equation by 0","Guess and check large numbers"],"answer":0,"hint":"The last two equations link x and z to y.","solution":"x = y + 1 and z = y − 2. Then (y + 1) + y + (y − 2) = 11 has only one variable."},{"id":"u2-tri4-q6","type":"input","prompt":"Solve x + y + z = 11, x − y = 1, y − z = 2. What is y?","answers":["4"],"hint":"x = y + 1 and z = y − 2.","solution":"(y + 1) + y + (y − 2) = 11, so 3y − 1 = 11 and y = 4. Then x = 5 and z = 2."},{"id":"u2-tri4-q7","type":"input","prompt":"1 pen, 2 notebooks, and 3 folders cost $14. 2 pens, 1 notebook, and 1 folder cost $7. 1 pen, 1 notebook, and 2 folders cost $9. What does a folder cost, in dollars?","answers":["3"],"hint":"p + 2n + 3f = 14, 2p + n + f = 7, p + n + 2f = 9. Subtract the third from the first.","solution":"(1) − (3): n + f = 5, so n = 5 − f. In (3): p + (5 − f) + 2f = 9, so p = 4 − f. In (2): 2(4 − f) + (5 − f) + f = 7, so 13 − 2f = 7 and f = 3. Then n = 2 and p = 1."},{"id":"u2-tri4-q8","type":"choice","prompt":"x + y + z = 6, 2x + 2y + 2z = 12, x − y = 0. How many solutions does the system have?","choices":["Exactly one","None","Infinitely many","Exactly two"],"answer":2,"hint":"Compare the first two equations.","solution":"The second equation is 2 × the first, so it adds nothing. Two equations are left for three variables: x = y and z = 6 − 2x. Any x works, so there are infinitely many solutions."}]}]}],"test":{"questions":[{"id":"u2-t-q1","type":"choice","prompt":"Which statement is true about the relation {(−2, 5), (0, 1), (3, 5), (7, −4)}?","choices":["It is not a function, because the output 5 appears twice","It is a function with domain {−2, 0, 3, 7} and range {−4, 1, 5}","It is a function with domain {−4, 1, 5}","It is not a function, because the x-values are different"],"answer":1,"hint":"A function gives exactly one output for each input. Repeated outputs are allowed.","solution":"Each x-value appears once, so it is a function. The domain is the x-values {−2, 0, 3, 7}. The range is the y-values {−4, 1, 5}."},{"id":"u2-t-q2","type":"choice","prompt":"Exactly one of these relations fails to be a function. Which one?","choices":["{(2, 1), (4, 1), (6, 1)}","{(0, 3), (1, 3), (2, 5)}","{(−1, 4), (0, 4), (1, 4)}","{(5, 0), (5, 2), (6, 1)}"],"answer":3,"hint":"Look for an x-value that appears with two different y-values.","solution":"In the relation {(5, 0), (5, 2), (6, 1)} the input 5 gives both 0 and 2. So it is not a function."},{"id":"u2-t-q3","type":"input","prompt":"f(x) = 3x² − 5x + 2. Find f(−2).","answers":["24"],"hint":"Replace x with −2. Square −2 before multiplying by 3.","solution":"f(−2) = 3(4) − 5(−2) + 2 = 12 + 10 + 2 = 24."},{"id":"u2-t-q4","type":"input","prompt":"g(x) = 4x − 9. For what x is g(x) = 15?","answers":["6"],"hint":"Set 4x − 9 equal to 15.","solution":"4x − 9 = 15, so 4x = 24 and x = 6."},{"id":"u2-t-q5","type":"choice","prompt":"h(x) = 2x + 1. What is h(a + 3)?","choices":["2a + 4","2a + 7","2a + 6","2a + 3"],"answer":1,"hint":"Replace x with the whole expression (a + 3) in brackets.","solution":"h(a + 3) = 2(a + 3) + 1 = 2a + 6 + 1 = 2a + 7."},{"id":"u2-t-q6","type":"input","prompt":"What is the slope of the line through (−4, 9) and (2, −3)?","answers":["-2"],"hint":"Slope = (y₂ − y₁) / (x₂ − x₁).","solution":"(−3 − 9)/(2 − (−4)) = −12/6 = −2."},{"id":"u2-t-q7","type":"input","prompt":"A pool drains from 540 gallons to 360 gallons in 6 minutes. What is the rate of change in gallons per minute?","answers":["-30"],"hint":"Change in gallons divided by change in minutes. Draining is negative.","solution":"(360 − 540)/6 = −180/6 = −30 gallons per minute."},{"id":"u2-t-q8","type":"choice","prompt":"Which is the equation of the line with slope 3/2 and y-intercept −4?","choices":["y = −4x + 3/2","y = (3/2)x − 4","y = (3/2)x + 4","y = (2/3)x − 4"],"answer":1,"hint":"Use y = mx + b. Which number is m and which is b?","solution":"Slope m = 3/2 and intercept b = −4. So y = (3/2)x − 4."},{"id":"u2-t-q9","type":"choice","prompt":"Which is the point-slope form of the line with slope −2 through (3, 5)?","choices":["y + 5 = −2(x + 3)","y − 3 = −2(x − 5)","y − 5 = 2(x − 3)","y − 5 = −2(x − 3)"],"answer":3,"hint":"Point-slope form is y − y₁ = m(x − x₁).","solution":"With (x₁, y₁) = (3, 5) and m = −2: y − 5 = −2(x − 3)."},{"id":"u2-t-q10","type":"input","prompt":"What is the x-intercept of 4x − 3y = 24?","answers":["6","(6,0)"],"hint":"For the x-intercept, set y = 0.","solution":"4x = 24, so x = 6."},{"id":"u2-t-q11","type":"choice","prompt":"Which is the equation of the line perpendicular to y = (2/5)x + 1 that passes through (0, 3)?","choices":["y = −(5/2)x + 3","y = (2/5)x + 3","y = −(2/5)x + 3","y = (5/2)x + 3"],"answer":0,"hint":"A perpendicular slope is the negative reciprocal. The point (0, 3) is the y-intercept.","solution":"The slope is the negative reciprocal of 2/5, which is −5/2. The y-intercept is 3. So y = −(5/2)x + 3."},{"id":"u2-t-q12","type":"input","prompt":"A line is parallel to y = −3x + 4 and passes through (2, 1). What is its y-intercept?","answers":["7","(0,7)"],"hint":"Parallel lines share a slope. Then put (2, 1) in y = mx + b.","solution":"The slope is −3. 1 = −3(2) + b, so b = 7."},{"id":"u2-t-q13","type":"choice","prompt":"The line y = −x + 3 is drawn dashed, and the region containing the origin is shaded. Which inequality is it?","choices":["y ≤ −x + 3","y > −x + 3","y < −x + 3","y < x + 3"],"answer":2,"hint":"Dashed means < or >. Test (0, 0) in the inequality.","solution":"Dashed means < or >. At (0, 0): 0 < 3 is true, so the origin is below the line. The inequality is y < −x + 3.","graph":{"fn":"-x+3","x":[-6,6],"y":[-4,7]}},{"id":"u2-t-q14","type":"choice","prompt":"Solve 5x − 10y > 20 for y.","choices":["y > (1/2)x − 2","y < −(1/2)x + 2","y < 2x − 4","y < (1/2)x − 2"],"answer":3,"hint":"Dividing by −10 flips the sign.","solution":"−10y > −5x + 20. Divide by −10 and flip: y < (1/2)x − 2."},{"id":"u2-t-q15","type":"input","prompt":"How many of the points (1, 1), (2, −2), (−1, 5), (0, −4) satisfy 2x − y ≥ 3?","answers":["2"],"hint":"Work out 2x − y for each point.","solution":"(1, 1): 1. (2, −2): 6. (−1, 5): −7. (0, −4): 4. The values 6 and 4 are at least 3, so two points work."},{"id":"u2-t-q16","type":"input","prompt":"Solve y = 3x − 8 and 2x + y = 7. What is x?","answers":["3"],"hint":"Replace y with 3x − 8 in the second equation.","solution":"2x + 3x − 8 = 7, so 5x = 15 and x = 3. (Then y = 1.)"},{"id":"u2-t-q17","type":"choice","prompt":"Solve y = −2x + 6 and 4x + 2y = 9. What happens?","choices":["There is one solution","There is no solution","There are infinitely many solutions","There are two solutions"],"answer":1,"hint":"Replace y and combine the x terms.","solution":"4x + 2(−2x + 6) = 9 gives 12 = 9. That is false, so there is no solution."},{"id":"u2-t-q18","type":"input","prompt":"Solve 7x + 2y = 12 and 3x − 2y = 8. What is y?","answers":["-1"],"hint":"The y terms are opposites. Add.","solution":"Add: 10x = 20, so x = 2. Then 14 + 2y = 12, so y = −1."},{"id":"u2-t-q19","type":"input","prompt":"Solve 5x + 3y = 1 and 2x + 5y = 8. What is x?","answers":["-1"],"hint":"To cancel x, multiply the first by 2 and the second by −5.","solution":"10x + 6y = 2 and −10x − 25y = −40. Add: −19y = −38, so y = 2. Then 5x + 6 = 1, so x = −1."},{"id":"u2-t-q20","type":"input","prompt":"Child tickets cost $6 and adult tickets cost $11. 200 tickets are sold for $1500. How many adult tickets?","answers":["60"],"hint":"c + a = 200 and 6c + 11a = 1500. Replace c with 200 − a.","solution":"6(200 − a) + 11a = 1500, so 1200 + 5a = 1500 and a = 60."},{"id":"u2-t-q21","type":"choice","prompt":"The region is x ≥ 0, y ≥ 0, 3x + 2y ≤ 12. Which point is in it?","choices":["(4, 1)","(3, 3)","(2, 3)","(−1, 5)"],"answer":2,"hint":"Test each point in all three inequalities.","solution":"(2, 3): 6 + 6 = 12 ≤ 12, true. (4, 1): 14. (3, 3): 15. (−1, 5): x is negative."},{"id":"u2-t-q22","type":"input","prompt":"How many pounds of $5 per lb coffee must be mixed with $2 per lb coffee to make 12 lb worth $3 per lb?","answers":["4"],"hint":"x + y = 12 and 2x + 5y = 3 × 12.","solution":"2x + 5y = 36 and x = 12 − y: 24 − 2y + 5y = 36, so y = 4. (8 lb of the $2 coffee.)"},{"id":"u2-t-q23","type":"input","prompt":"Solve x + y + z = 9, x − z = 1, y = 2z. What is y?","answers":["4"],"hint":"Write x and y using z. Substitute into the first equation.","solution":"x = z + 1 and y = 2z. So (z + 1) + 2z + z = 9, giving 4z = 8 and z = 2. Then y = 4."},{"id":"u2-t-q24","type":"choice","prompt":"Is (−1, 0, 3) a solution of x + y + z = 2, 2x + 3y − z = −5, x − y + 2z = 5?","choices":["Yes, it satisfies all three","No, it fails the first equation","No, it fails the second equation","No, it fails the third equation"],"answer":0,"hint":"Put the triple in each equation.","solution":"−1 + 0 + 3 = 2. −2 + 0 − 3 = −5. −1 − 0 + 6 = 5. All true."}]}},{"format":1,"id":"unit-3-parent-functions-transformations","title":"Unit 3: Parent Functions and Transformations","levels":[{"id":"features-1","title":"Domain, range, and intercepts","lessons":[{"id":"features-1-1","teach":[{"title":"Domain and range","text":["The domain is every x-value (input) a function can use. The range is every y-value (output) it produces.","On a graph, the domain is how far left to right the graph goes. The range is how far down to up it goes."],"example":{"problem":"A graph runs from x = −2 to x = 5 and from y = 0 to y = 9, with solid dots at every end. Find the domain and range.","steps":["Left to right: x goes from −2 to 5, so the domain is −2 to 5.","Bottom to top: y goes from 0 to 9, so the range is 0 to 9."]}},{"title":"Interval notation","text":["Use [ ] when the end value is included. Use ( ) when it is not included.","Infinity is never a real number, so ∞ and −∞ always get a parenthesis."],"example":{"problem":"Write −2 < x ≤ 5 in interval notation.","steps":["−2 is not included, so use a parenthesis on the left: (−2.","5 is included, so use a bracket on the right: 5].","Answer: (−2, 5]"]}}],"questions":[{"id":"u3-f11-q1","type":"choice","prompt":"The domain of a function is the set of all...","choices":["y-values (outputs)","x-values (inputs)","x-intercepts","maximum values"],"answer":1,"hint":"Which variable is the input?","solution":"The domain is every input, so it is the set of x-values. The range is the set of y-values."},{"id":"u3-f11-q2","type":"choice","prompt":"Write x ≥ 3 in interval notation.","choices":["[3, ∞)","(3, ∞)","(−∞, 3]","[3, ∞]"],"answer":0,"hint":"Is 3 included? Does the interval go to the right or left?","solution":"x ≥ 3 includes 3, so use a bracket. It runs up forever to the right, and ∞ gets a parenthesis: [3, ∞)."},{"id":"u3-f11-q3","type":"choice","prompt":"Write −2 < x ≤ 5 in interval notation.","choices":["[−2, 5)","[−2, 5]","(−2, 5)","(−2, 5]"],"answer":3,"hint":"< leaves the number out. ≤ keeps it in.","solution":"−2 is not included, so (−2. 5 is included, so 5]. Answer: (−2, 5]."},{"id":"u3-f11-q4","type":"input","prompt":"Look at the graph of f(x) = x² − 4. What is the smallest y-value on the graph?","answers":["-4"],"hint":"Find the lowest point of the curve.","solution":"The lowest point of the parabola is its vertex, (0, −4). So the smallest y-value is −4.","graph":{"fn":"x^2-4","x":[-6,6],"y":[-6,8]}},{"id":"u3-f11-q5","type":"choice","prompt":"The graph of y = 2x − 1 is a line that goes on forever in both directions. What is its domain?","choices":["[−1, ∞)","(−1, ∞)","(−∞, ∞)","(−∞, 2]"],"answer":2,"hint":"A line never stops going left or right.","solution":"The line extends forever left and right, so every x-value works. The domain is (−∞, ∞).","graph":{"fn":"2x-1","x":[-6,6],"y":[-8,8]}},{"id":"u3-f11-q6","type":"input","prompt":"Look at the graph of f(x) = √(x + 2). What is the smallest x-value on the graph?","answers":["-2"],"hint":"Find where the curve starts on the left.","solution":"The graph starts at the point (−2, 0) and goes right from there. The smallest x-value is −2.","graph":{"fn":"sqrt(x+2)","x":[-5,8],"y":[-3,6]}},{"id":"u3-f11-q7","type":"choice","prompt":"Look at the graph of f(x) = √(x + 2). What is its range?","choices":["[−2, ∞)","[0, ∞)","(0, ∞)","(−∞, ∞)"],"answer":1,"hint":"The range is about y-values. Where does the curve start vertically, and does it go up or down?","solution":"The curve starts at y = 0 and rises forever. The point (−2, 0) is on the graph, so 0 is included. Range: [0, ∞).","graph":{"fn":"sqrt(x+2)","x":[-5,8],"y":[-3,6]}},{"id":"u3-f11-q8","type":"choice","prompt":"Look at the graph of f(x) = −x² + 3. What is its range?","choices":["(−∞, 3]","[3, ∞)","(−∞, ∞)","(−∞, −3]"],"answer":0,"hint":"The parabola opens down. Find its highest point.","solution":"The vertex (0, 3) is the highest point. All y-values are 3 or less, so the range is (−∞, 3].","graph":{"fn":"-x^2+3","x":[-5,5],"y":[-6,5]}}]},{"id":"features-1-2","teach":[{"title":"Domain from an equation","text":["Two things break a function: dividing by zero and taking an even root (like a square root) of a negative number.","If neither happens, the domain is all real numbers. Otherwise, find the x-values that cause trouble and leave them out."],"example":{"problem":"Find the domain of f(x) = 1/(x − 3).","steps":["The bottom cannot be 0: x − 3 = 0 when x = 3.","So every x except 3 is allowed.","Domain: (−∞, 3) ∪ (3, ∞)"]}},{"title":"Range of simple functions","text":["For a parabola, find the vertex. If it opens up, the vertex is the lowest point. If it opens down, the vertex is the highest point."],"example":{"problem":"Find the range of f(x) = x² + 1.","steps":["x² is never negative, so its smallest value is 0.","So x² + 1 is at least 1.","Range: [1, ∞)"]}}],"questions":[{"id":"u3-f12-q1","type":"choice","prompt":"Which function has a domain of all real numbers?","choices":["f(x) = 1/x","f(x) = √x","f(x) = 1/(x − 2)","f(x) = 3x² − 5"],"answer":3,"hint":"Look for a function with no fraction and no square root.","solution":"A polynomial like 3x² − 5 has no division and no root, so every x works. The others have restrictions."},{"id":"u3-f12-q2","type":"input","prompt":"f(x) = 1/(x − 4). Which x-value is not allowed?","answers":["4"],"hint":"Set the bottom equal to 0.","solution":"The bottom is 0 when x − 4 = 0, so x = 4. That value is not allowed."},{"id":"u3-f12-q3","type":"input","prompt":"f(x) = √(x − 6). What is the smallest x-value allowed?","answers":["6"],"hint":"The inside of a square root cannot be negative: x − 6 ≥ 0.","solution":"Solve x − 6 ≥ 0 to get x ≥ 6. The smallest allowed value is 6."},{"id":"u3-f12-q4","type":"choice","prompt":"Find the domain of f(x) = √(x + 3).","choices":["[3, ∞)","(−3, ∞)","[−3, ∞)","(−∞, −3]"],"answer":2,"hint":"Solve x + 3 ≥ 0.","solution":"x + 3 ≥ 0 gives x ≥ −3. At x = −3 the root is √0 = 0, which is fine, so use a bracket. Domain: [−3, ∞)."},{"id":"u3-f12-q5","type":"choice","prompt":"Find the domain of f(x) = 1/(x + 5).","choices":["(−∞, 5) ∪ (5, ∞)","(−∞, −5) ∪ (−5, ∞)","(−∞, ∞)","[−5, ∞)"],"answer":1,"hint":"The bottom is 0 when x + 5 = 0.","solution":"x + 5 = 0 at x = −5, so −5 is the only excluded value. Domain: (−∞, −5) ∪ (−5, ∞)."},{"id":"u3-f12-q6","type":"input","prompt":"f(x) = √(2x − 10). What is the smallest x-value allowed?","answers":["5"],"hint":"Solve 2x − 10 ≥ 0.","solution":"2x − 10 ≥ 0 gives 2x ≥ 10, so x ≥ 5. The smallest x is 5."},{"id":"u3-f12-q7","type":"choice","prompt":"Find the range of f(x) = x² + 3.","choices":["[3, ∞)","[0, ∞)","(−∞, 3]","(3, ∞)"],"answer":0,"hint":"The vertex is the lowest point of a parabola that opens up.","solution":"x² is at least 0, so x² + 3 is at least 3. The vertex (0, 3) is on the graph. Range: [3, ∞)."},{"id":"u3-f12-q8","type":"choice","prompt":"Find the range of f(x) = −x² + 7.","choices":["[7, ∞)","(−∞, −7]","(−∞, ∞)","(−∞, 7]"],"answer":3,"hint":"The negative in front makes the parabola open down.","solution":"−x² is at most 0, so −x² + 7 is at most 7. The vertex (0, 7) is the highest point. Range: (−∞, 7]."},{"id":"u3-f12-q9","type":"input","prompt":"How many x-values are not allowed in the domain of f(x) = 5/(x² − 9)?","answers":["2"],"hint":"Solve x² − 9 = 0.","solution":"x² − 9 = 0 gives x = 3 or x = −3. Two values are excluded."}]},{"id":"features-1-3","teach":[{"title":"Intercepts","text":["The y-intercept is where the graph crosses the y-axis. Set x = 0 and find f(0). It is the point (0, f(0)).","An x-intercept is where the graph crosses the x-axis. Set f(x) = 0 and solve for x. It is a point (x, 0)."],"example":{"problem":"Find the intercepts of f(x) = 2x² − 8.","steps":["y-intercept: f(0) = 2(0)² − 8 = −8, so (0, −8).","x-intercepts: 2x² − 8 = 0, so x² = 4 and x = 2 or x = −2.","The x-intercepts are (−2, 0) and (2, 0)."]}}],"questions":[{"id":"u3-f13-q1","type":"choice","prompt":"What is the y-intercept of f(x) = 3x − 6?","choices":["(−6, 0)","(2, 0)","(0, −6)","(0, 3)"],"answer":2,"hint":"Set x = 0.","solution":"f(0) = 3(0) − 6 = −6. The y-intercept is (0, −6)."},{"id":"u3-f13-q2","type":"input","prompt":"The y-intercept of f(x) = x² − 5x + 8 is (0, k). What is k?","answers":["8"],"hint":"Find f(0).","solution":"f(0) = 0 − 0 + 8 = 8, so k = 8."},{"id":"u3-f13-q3","type":"input","prompt":"Find the x-intercept of f(x) = 2x + 10. Give the x-value.","answers":["-5"],"hint":"Set f(x) = 0.","solution":"2x + 10 = 0, so 2x = −10 and x = −5."},{"id":"u3-f13-q4","type":"choice","prompt":"What are the x-intercepts of f(x) = x² − 9?","choices":["(0, −3) and (0, 3)","(−3, 0) and (3, 0)","(0, −9)","(−9, 0) and (9, 0)"],"answer":1,"hint":"Set x² − 9 = 0. An x-intercept has y = 0.","solution":"x² = 9, so x = 3 or x = −3. The points are (−3, 0) and (3, 0)."},{"id":"u3-f13-q5","type":"input","prompt":"Find the x-intercepts of f(x) = x² − x − 6. Give the x-values.","answers":["3, -2"],"hint":"Factor into two binomials.","solution":"x² − x − 6 = (x − 3)(x + 2) = 0, so x = 3 or x = −2."},{"id":"u3-f13-q6","type":"choice","prompt":"Look at the graph of f(x) = x² + 2x − 3. What are its x-intercepts?","choices":["(−3, 0) and (1, 0)","(3, 0) and (−1, 0)","(0, −3) and (0, 1)","(−3, 0) and (0, −3)"],"answer":0,"hint":"Find where the curve crosses the horizontal axis.","solution":"The curve crosses the x-axis at x = −3 and x = 1. Check: (x + 3)(x − 1) = x² + 2x − 3. The points are (−3, 0) and (1, 0).","graph":{"fn":"x^2+2x-3","x":[-6,4],"y":[-6,8]}},{"id":"u3-f13-q7","type":"input","prompt":"Look at the graph of f(x) = 2x − 4. At what x-value does the line cross the x-axis?","answers":["2"],"hint":"Find where y = 0.","solution":"Set 2x − 4 = 0, so x = 2. The line crosses the x-axis at (2, 0).","graph":{"fn":"2x-4","x":[-6,6],"y":[-8,6]}},{"id":"u3-f13-q8","type":"input","prompt":"How many x-intercepts does f(x) = x² + 4 have?","answers":["0"],"hint":"Try solving x² + 4 = 0. Can a square equal −4?","solution":"x² + 4 = 0 gives x² = −4, which has no real solution. The graph never touches the x-axis, so it has 0 x-intercepts."}]},{"id":"features-1-4","teach":[{"title":"Putting it together","text":["For one function you can often find the domain, range, and intercepts. Take them one at a time.","Domain: look for division and even roots. Range: think about the lowest or highest point. Intercepts: set x = 0 for y, and set f(x) = 0 for x."],"example":{"problem":"For f(x) = √(x + 3) − 1, find the domain, range, and x-intercept.","steps":["Domain: x + 3 ≥ 0, so x ≥ −3. Domain: [−3, ∞).","Range: √(x + 3) is at least 0, so f(x) is at least −1. Range: [−1, ∞).","x-intercept: √(x + 3) − 1 = 0, so √(x + 3) = 1, so x + 3 = 1 and x = −2. The point is (−2, 0)."]}}],"questions":[{"id":"u3-f14-q1","type":"choice","prompt":"Find the domain and range of f(x) = √(x − 1) + 2.","choices":["Domain: [2, ∞); Range: [1, ∞)","Domain: (1, ∞); Range: (2, ∞)","Domain: [−1, ∞); Range: [−2, ∞)","Domain: [1, ∞); Range: [2, ∞)"],"answer":3,"hint":"Domain comes from x − 1 ≥ 0. The root part is at least 0, then add 2.","solution":"x − 1 ≥ 0 gives x ≥ 1, so the domain is [1, ∞). √(x − 1) ≥ 0, so f(x) ≥ 2 and the range is [2, ∞)."},{"id":"u3-f14-q2","type":"choice","prompt":"Find the domain of f(x) = 1/(x − 3).","choices":["(−∞, −3) ∪ (−3, ∞)","(−∞, ∞)","(−∞, 3) ∪ (3, ∞)","[3, ∞)"],"answer":2,"hint":"What x-value makes the bottom 0?","solution":"x − 3 = 0 at x = 3. So x = 3 is the only excluded value. Domain: (−∞, 3) ∪ (3, ∞)."},{"id":"u3-f14-q3","type":"input","prompt":"f(x) = √(12 − 3x). What is the largest x-value allowed?","answers":["4"],"hint":"Solve 12 − 3x ≥ 0. Dividing by a negative flips the inequality.","solution":"12 − 3x ≥ 0 gives −3x ≥ −12, so x ≤ 4. The largest allowed x is 4.","calculator":false},{"id":"u3-f14-q4","type":"choice","prompt":"Look at the graph of f(x) = −x² + 4x. What is its range?","choices":["[4, ∞)","(−∞, 4]","(−∞, 2]","(−∞, ∞)"],"answer":1,"hint":"The parabola opens down. Find the y-value of its highest point.","solution":"The vertex is at x = 2, and y = −4 + 8 = 4. The graph opens down, so the range is (−∞, 4].","graph":{"fn":"-x^2+4x","x":[-3,7],"y":[-8,6]}},{"id":"u3-f14-q5","type":"input","prompt":"Look at the graph of f(x) = −x² + 4x. Where does it cross the x-axis? Give both x-values.","answers":["0, 4"],"hint":"Read the two points where the curve meets the x-axis.","solution":"Set −x² + 4x = 0, so −x(x − 4) = 0. Then x = 0 or x = 4.","graph":{"fn":"-x^2+4x","x":[-3,7],"y":[-8,6]}},{"id":"u3-f14-q6","type":"input","prompt":"f(x) = (x + 2)(x − 5). What is the y-coordinate of the y-intercept?","answers":["-10"],"hint":"Find f(0).","solution":"f(0) = (2)(−5) = −10.","calculator":false},{"id":"u3-f14-q7","type":"choice","prompt":"Which interval notation matches −1 < x ≤ 6?","choices":["(−1, 6]","[−1, 6)","[−1, 6]","(−1, 6)"],"answer":0,"hint":"Check each end separately.","solution":"−1 is not included: (−1. 6 is included: 6]. Answer: (−1, 6]."},{"id":"u3-f14-q8","type":"input","prompt":"Look at the graph of f(x) = √(x + 4) − 3. What is the y-coordinate of its y-intercept?","answers":["-1"],"hint":"Find f(0).","solution":"f(0) = √4 − 3 = 2 − 3 = −1.","graph":{"fn":"sqrt(x+4)-3","x":[-6,8],"y":[-5,5]}},{"id":"u3-f14-q9","type":"input","prompt":"Find the x-values excluded from the domain of f(x) = 6/(x² − 16).","answers":["4, -4"],"hint":"Solve x² − 16 = 0.","solution":"x² = 16, so x = 4 or x = −4. Both make the bottom 0.","calculator":false}]}]},{"id":"features-2","title":"Increasing, decreasing, and end behavior","lessons":[{"id":"features-2-1","teach":[{"title":"Increasing and decreasing","text":["Read a graph from left to right. If it goes uphill, the function is increasing. If it goes downhill, it is decreasing.","Write intervals using x-values, in interval notation. Use parentheses: the function is not increasing or decreasing at the exact turning point."],"example":{"problem":"A parabola has vertex (3, −2) and opens up. Where is it increasing and decreasing?","steps":["To the left of x = 3 the graph goes downhill: decreasing on (−∞, 3).","To the right of x = 3 it goes uphill: increasing on (3, ∞)."]}}],"questions":[{"id":"u3-f21-q1","type":"choice","prompt":"Reading a graph from left to right, it goes uphill. The function is...","choices":["decreasing","constant","undefined","increasing"],"answer":3,"hint":"Think of walking along the graph from left to right.","solution":"Uphill from left to right means the y-values grow as x grows. That is increasing."},{"id":"u3-f21-q2","type":"choice","prompt":"Look at the graph of f(x) = (x − 2)² − 1. On which interval is it decreasing?","choices":["(2, ∞)","(−∞, −1)","(−∞, 2)","(−1, ∞)"],"answer":2,"hint":"Intervals use x-values. Where does the graph go downhill?","solution":"The vertex is (2, −1). To the left of x = 2 the graph falls. It is decreasing on (−∞, 2).","graph":{"fn":"(x-2)^2-1","x":[-3,7],"y":[-3,8]}},{"id":"u3-f21-q3","type":"choice","prompt":"Look at the graph of f(x) = (x − 2)² − 1. On which interval is it increasing?","choices":["(−∞, 2)","(2, ∞)","(−1, ∞)","(−∞, ∞)"],"answer":1,"hint":"The graph goes uphill after the vertex.","solution":"To the right of the vertex x = 2 the graph rises. It is increasing on (2, ∞).","graph":{"fn":"(x-2)^2-1","x":[-3,7],"y":[-3,8]}},{"id":"u3-f21-q4","type":"input","prompt":"Look at the graph of f(x) = (x − 2)² − 1. At what x-value does it switch from decreasing to increasing?","answers":["2"],"hint":"Find the x-coordinate of the lowest point.","solution":"The switch happens at the vertex (2, −1). The x-value is 2.","graph":{"fn":"(x-2)^2-1","x":[-3,7],"y":[-3,8]}},{"id":"u3-f21-q5","type":"choice","prompt":"The graph of f(x) = −2x + 3 is a line. Which statement is true?","choices":["Decreasing on (−∞, ∞)","Increasing on (−∞, ∞)","Constant on (−∞, ∞)","Decreasing only on (0, ∞)"],"answer":0,"hint":"Is the slope positive or negative?","solution":"The slope is −2, so the line falls from left to right everywhere. It is decreasing on (−∞, ∞).","graph":{"fn":"-2x+3","x":[-6,6],"y":[-8,8]}},{"id":"u3-f21-q6","type":"input","prompt":"Look at the graph of f(x) = −(x + 1)² + 4. At what x-value does it turn around?","answers":["-1"],"hint":"Find the x-coordinate of the vertex.","solution":"The vertex is (−1, 4). It turns at x = −1.","graph":{"fn":"-(x+1)^2+4","x":[-6,4],"y":[-6,6]}},{"id":"u3-f21-q7","type":"choice","prompt":"Look at the graph of f(x) = −(x + 1)² + 4. On which interval is it increasing?","choices":["(−1, ∞)","(−∞, 4)","(4, ∞)","(−∞, −1)"],"answer":3,"hint":"This parabola opens down. Which side of the vertex goes uphill?","solution":"It opens down, so it rises on the left of the vertex x = −1. Increasing on (−∞, −1).","graph":{"fn":"-(x+1)^2+4","x":[-6,4],"y":[-6,6]}},{"id":"u3-f21-q8","type":"choice","prompt":"Which function is increasing for all x?","choices":["f(x) = −3x + 1","f(x) = x²","f(x) = 2x − 7","f(x) = 5"],"answer":2,"hint":"Look for a positive slope.","solution":"Only 2x − 7 has a positive slope. −3x + 1 decreases, x² turns around at 0, and 5 is constant."}]},{"id":"features-2-2","teach":[{"title":"Maximum and minimum","text":["A relative maximum is a peak: the graph rises, then falls. A relative minimum is a valley: it falls, then rises.","The value is the y-coordinate. The place where it happens is the x-coordinate. Read each one carefully."],"example":{"problem":"A graph has a peak at (−1, 2). State the maximum value and where it occurs.","steps":["The value is the y-coordinate: the maximum value is 2.","It occurs at the x-coordinate: x = −1."]}}],"questions":[{"id":"u3-f22-q1","type":"choice","prompt":"Look at the graph of f(x) = x³ − 3x. On which intervals is it increasing?","choices":["(−1, 1)","(−∞, −1) and (1, ∞)","(−2, 2)","(−∞, ∞)"],"answer":1,"hint":"Find the two turning points, then see where the graph goes uphill.","solution":"The graph rises up to x = −1, falls between x = −1 and x = 1, then rises again. It is increasing on (−∞, −1) and (1, ∞).","graph":{"fn":"x^3-3x","x":[-3,3],"y":[-5,5]}},{"id":"u3-f22-q2","type":"choice","prompt":"Look at the graph of f(x) = x³ − 3x. On which interval is it decreasing?","choices":["(−1, 1)","(−∞, −1) and (1, ∞)","(−2, 2)","(−∞, 0)"],"answer":0,"hint":"Where does the graph go downhill?","solution":"The graph goes downhill between its two turning points, x = −1 and x = 1. Decreasing on (−1, 1).","graph":{"fn":"x^3-3x","x":[-3,3],"y":[-5,5]}},{"id":"u3-f22-q3","type":"input","prompt":"Look at the graph of f(x) = x³ − 3x. What is the relative maximum value?","answers":["2"],"hint":"The peak is the left turning point. Read its y-coordinate.","solution":"The peak is at (−1, 2). The maximum value is its y-coordinate, 2.","graph":{"fn":"x^3-3x","x":[-3,3],"y":[-5,5]}},{"id":"u3-f22-q4","type":"input","prompt":"Look at the graph of f(x) = x³ − 3x. What is the relative minimum value?","answers":["-2"],"hint":"The valley is the right turning point.","solution":"The valley is at (1, −2). The minimum value is its y-coordinate, −2.","graph":{"fn":"x^3-3x","x":[-3,3],"y":[-5,5]}},{"id":"u3-f22-q5","type":"input","prompt":"Look at the graph of f(x) = x³ − 3x. At what x-value does the relative maximum occur?","answers":["-1"],"hint":"The x-value is where it happens, not the height.","solution":"The peak is at (−1, 2). It occurs at x = −1.","graph":{"fn":"x^3-3x","x":[-3,3],"y":[-5,5]}},{"id":"u3-f22-q6","type":"choice","prompt":"Look at the graph of f(x) = x² − 6x + 5. Which statement is correct?","choices":["Minimum value 3 at x = −4","Minimum value −4 at x = −3","Maximum value −4 at x = 3","Minimum value −4 at x = 3"],"answer":3,"hint":"Find the vertex. The value is y, and where it occurs is x.","solution":"The vertex is (3, −4). The parabola opens up, so it is a minimum. The value is −4 and it occurs at x = 3.","graph":{"fn":"x^2-6x+5","x":[-1,7],"y":[-6,8]}},{"id":"u3-f22-q7","type":"input","prompt":"Look at the graph of f(x) = −x² + 2x + 3. What is its maximum value?","answers":["4"],"hint":"Find the y-coordinate of the vertex.","solution":"The vertex is (1, 4) because f(1) = −1 + 2 + 3 = 4. The maximum value is 4.","graph":{"fn":"-x^2+2x+3","x":[-3,5],"y":[-3,6]}},{"id":"u3-f22-q8","type":"input","prompt":"What is the minimum value of f(x) = (x − 4)² + 7?","answers":["7"],"hint":"Vertex form shows the vertex directly.","solution":"The vertex is (4, 7) and the parabola opens up. The minimum value is 7.","calculator":false},{"id":"u3-f22-q9","type":"choice","prompt":"What is the maximum of f(x) = −(x + 2)² + 9?","choices":["Maximum value 9 at x = 2","Maximum value −2 at x = 9","Maximum value 9 at x = −2","Maximum value −9 at x = −2"],"answer":2,"hint":"Read the vertex (h, k) from the form a(x − h)² + k.","solution":"The vertex is (−2, 9). The parabola opens down, so the vertex is the maximum. Value 9 at x = −2.","calculator":false}]},{"id":"features-2-3","teach":[{"title":"End behavior","text":["End behavior says where the graph goes at the far left and far right. We write x → ∞ (far right) and x → −∞ (far left).","For a polynomial, look at the leading term. Even degree: both ends go the same way. Odd degree: the ends go opposite ways. A positive leading coefficient means the right end goes up. A negative one means the right end goes down."],"example":{"problem":"Describe the end behavior of f(x) = −2x³ + 5x.","steps":["The leading term is −2x³: odd degree, negative coefficient.","Odd degree means opposite ends. Negative means the right end goes down.","As x → ∞, f(x) → −∞. As x → −∞, f(x) → ∞."]}}],"questions":[{"id":"u3-f23-q1","type":"choice","prompt":"Look at the graph of f(x) = x³. Which describes its end behavior?","choices":["Rises to both the left and right","Falls to the left, rises to the right","Falls to both the left and right","Rises to the left, falls to the right"],"answer":1,"hint":"Check the far left and the far right of the curve.","solution":"On the left the graph goes down. On the right it goes up. Falls to the left, rises to the right.","graph":{"fn":"x^3","x":[-3,3],"y":[-10,10]}},{"id":"u3-f23-q2","type":"choice","prompt":"Look at the graph of f(x) = −x³ + 2x. Which describes its end behavior?","choices":["Rises to the left, falls to the right","Falls to the left, rises to the right","Rises to both the left and right","Falls to both the left and right"],"answer":0,"hint":"Look at both ends of the graph.","solution":"The left end is high and the right end is low. Rises to the left, falls to the right.","graph":{"fn":"-x^3+2x","x":[-3,3],"y":[-8,8]}},{"id":"u3-f23-q3","type":"input","prompt":"What is the degree of f(x) = −3x⁴ + x²?","answers":["4"],"hint":"The degree is the highest exponent.","solution":"The highest exponent is 4, so the degree is 4."},{"id":"u3-f23-q4","type":"input","prompt":"What is the leading coefficient of f(x) = 5x − 2x³ + 1?","answers":["-2"],"hint":"Write the terms from highest power to lowest first.","solution":"In order: −2x³ + 5x + 1. The leading term is −2x³, so the leading coefficient is −2."},{"id":"u3-f23-q5","type":"choice","prompt":"Which describes the end behavior of f(x) = −3x⁴ + x²?","choices":["x → −∞: f(x) → ∞; x → ∞: f(x) → ∞","x → −∞: f(x) → ∞; x → ∞: f(x) → −∞","x → −∞: f(x) → −∞; x → ∞: f(x) → ∞","x → −∞: f(x) → −∞; x → ∞: f(x) → −∞"],"answer":3,"hint":"Even degree, negative leading coefficient.","solution":"The degree 4 is even, so both ends match. The coefficient −3 is negative, so both ends go down."},{"id":"u3-f23-q6","type":"choice","prompt":"Which describes the end behavior of f(x) = 2x³ − x?","choices":["x → −∞: f(x) → ∞; x → ∞: f(x) → ∞","x → −∞: f(x) → ∞; x → ∞: f(x) → −∞","x → −∞: f(x) → −∞; x → ∞: f(x) → ∞","x → −∞: f(x) → −∞; x → ∞: f(x) → −∞"],"answer":2,"hint":"Odd degree, positive leading coefficient.","solution":"Degree 3 is odd, so the ends go opposite ways. The coefficient 2 is positive, so the right end goes up and the left end goes down."},{"id":"u3-f23-q7","type":"choice","prompt":"Look at the graph of f(x) = x⁴ − 3x². Which describes its end behavior?","choices":["Falls to both the left and right","Rises to both the left and right","Falls to the left, rises to the right","Rises to the left, falls to the right"],"answer":1,"hint":"Ignore the bumps in the middle. Look at the far ends.","solution":"Both far ends of the graph go up. This matches degree 4 with a positive leading coefficient.","graph":{"fn":"x^4-3x^2","x":[-3,3],"y":[-5,10]}},{"id":"u3-f23-q8","type":"input","prompt":"A polynomial graph falls to the left and rises to the right. Is its degree even or odd? Type even or odd.","answers":["odd"],"hint":"Even degrees have both ends going the same way.","solution":"The ends go in opposite directions, so the degree is odd."},{"id":"u3-f23-q9","type":"choice","prompt":"Which describes the end behavior of f(x) = −x⁵ + 3x²?","choices":["x → −∞: f(x) → ∞; x → ∞: f(x) → −∞","x → −∞: f(x) → −∞; x → ∞: f(x) → ∞","x → −∞: f(x) → ∞; x → ∞: f(x) → ∞","x → −∞: f(x) → −∞; x → ∞: f(x) → −∞"],"answer":0,"hint":"Degree 5 is odd. The leading coefficient is −1.","solution":"Odd degree gives opposite ends. The negative coefficient sends the right end down, so the left end goes up."}]},{"id":"features-2-4","teach":[{"title":"Using all the features","text":["One graph can give you intervals of increase and decrease, relative maximums and minimums, and end behavior. Describe them in order.","The function is increasing or decreasing between turning points. Turning points are exactly where maximums and minimums happen."],"example":{"problem":"A parabola opens down with vertex (4, 9). Describe it.","steps":["Increasing on (−∞, 4) and decreasing on (4, ∞).","Maximum value 9 at x = 4.","Both ends go down."]}}],"questions":[{"id":"u3-f24-q1","type":"choice","prompt":"Look at the graph of f(x) = x⁴ − 2x². On which intervals is it decreasing?","choices":["(−1, 0) and (1, ∞)","(−1, 1)","(−∞, 0)","(−∞, −1) and (0, 1)"],"answer":3,"hint":"The graph has two valleys and one peak in between.","solution":"The graph falls until the valley at x = −1, rises to the peak at x = 0, falls to the valley at x = 1, then rises. Decreasing on (−∞, −1) and (0, 1).","graph":{"fn":"x^4-2x^2","x":[-2.5,2.5],"y":[-2,4]}},{"id":"u3-f24-q2","type":"choice","prompt":"Look at the graph of f(x) = x⁴ − 2x². On which intervals is it increasing?","choices":["(−∞, −1) and (0, 1)","(−1, 1)","(−1, 0) and (1, ∞)","(−1, ∞)"],"answer":2,"hint":"Find the intervals between the valleys and the peak where the graph climbs.","solution":"The graph rises from the left valley (x = −1) to the peak (x = 0), and from the right valley (x = 1) onward. Increasing on (−1, 0) and (1, ∞).","graph":{"fn":"x^4-2x^2","x":[-2.5,2.5],"y":[-2,4]}},{"id":"u3-f24-q3","type":"input","prompt":"Look at the graph of f(x) = x⁴ − 2x². What is the lowest y-value on the graph?","answers":["-1"],"hint":"Read the y-coordinate of either valley.","solution":"Both valleys are at y = −1, for example the point (1, −1). The lowest y-value is −1.","graph":{"fn":"x^4-2x^2","x":[-2.5,2.5],"y":[-2,4]}},{"id":"u3-f24-q4","type":"input","prompt":"Look at the graph of f(x) = x⁴ − 2x². What is the y-value of the peak between the two valleys?","answers":["0"],"hint":"The peak is on the y-axis.","solution":"The peak is at (0, 0). Its value is 0.","graph":{"fn":"x^4-2x^2","x":[-2.5,2.5],"y":[-2,4]}},{"id":"u3-f24-q5","type":"choice","prompt":"Look at the graph of f(x) = x⁴ − 2x². Which describes its end behavior?","choices":["Falls to both the left and right","Rises to both the left and right","Falls to the left, rises to the right","Rises to the left, falls to the right"],"answer":1,"hint":"The degree is 4 and the leading coefficient is 1.","solution":"Even degree means both ends match. The positive coefficient means both go up.","graph":{"fn":"x^4-2x^2","x":[-2.5,2.5],"y":[-2,4]}},{"id":"u3-f24-q6","type":"input","prompt":"A ball is thrown so its height in feet is h(t) = −16t² + 64t, where t is in seconds. At what time is the ball highest?","answers":["2"],"hint":"The vertex has x = −b/(2a).","solution":"t = −64/(2 · −16) = −64/−32 = 2 seconds."},{"id":"u3-f24-q7","type":"input","prompt":"For h(t) = −16t² + 64t, what is the ball's maximum height in feet?","answers":["64"],"hint":"Plug the time of the vertex into h(t). The vertex is at t = 2.","solution":"h(2) = −16(4) + 64(2) = −64 + 128 = 64 feet."},{"id":"u3-f24-q8","type":"choice","prompt":"Look at the graph of f(x) = −x³ + 3x. On which interval is it increasing?","choices":["(−1, 1)","(−∞, −1) and (1, ∞)","(−2, 2)","(−∞, ∞)"],"answer":0,"hint":"Look at the end behavior first: the leading coefficient is negative.","solution":"With a negative leading coefficient the left end is high and goes down first. It falls on (−∞, −1), rises on (−1, 1) between the valley (−1, −2) and peak (1, 2), then falls on (1, ∞). Increasing on (−1, 1).","graph":{"fn":"-x^3+3x","x":[-3,3],"y":[-4,4]}},{"id":"u3-f24-q9","type":"input","prompt":"What is the minimum value of f(x) = x² − 4x + 3?","answers":["-1"],"hint":"Find the vertex first: x = −b/(2a).","solution":"x = 4/2 = 2. f(2) = 4 − 8 + 3 = −1. The minimum value is −1.","calculator":false}]}]},{"id":"parent-functions","title":"Parent functions","lessons":[{"id":"parent-functions-1","teach":[{"title":"Linear, quadratic, cubic, absolute value","text":["A parent function is the simplest version of a function family. Every other function in the family is a transformation of it.","Linear f(x) = x: a straight line. Quadratic f(x) = x²: a U-shaped parabola. Cubic f(x) = x³: an S-shaped curve. Absolute value f(x) = |x|: a V with its corner at (0, 0)."],"example":{"problem":"Complete a table for f(x) = x² at x = −2, −1, 0, 1, 2.","steps":["Square each x: (−2)² = 4, (−1)² = 1, 0² = 0, 1² = 1, 2² = 4.","The values are 4, 1, 0, 1, 4. They are symmetric, which is typical for a parabola."]}}],"questions":[{"id":"u3-pf1-q1","type":"choice","prompt":"Which equation is the parent quadratic function?","choices":["f(x) = x","f(x) = x³","f(x) = |x|","f(x) = x²"],"answer":3,"hint":"Quadratic means the highest power is 2.","solution":"Quadratic functions have an x². The parent is f(x) = x²."},{"id":"u3-pf1-q2","type":"choice","prompt":"This graph has an S-bend at the origin. Which parent function is it?","choices":["Quadratic","Absolute value","Cubic","Linear"],"answer":2,"hint":"It has an S shape and passes through the origin.","solution":"The graph rises from low left to high right with a flat S-bend at the origin. That is the cubic f(x) = x³.","graph":{"fn":"x^3","x":[-4,4],"y":[-8,8]}},{"id":"u3-pf1-q3","type":"choice","prompt":"This graph is a V with a sharp corner. Which parent function is it?","choices":["Quadratic","Absolute value","Linear","Cubic"],"answer":1,"hint":"The graph has a sharp corner, not a smooth curve.","solution":"A V with a sharp corner at the origin is the absolute value function f(x) = |x|.","graph":{"fn":"abs(x)","x":[-6,6],"y":[-2,8]}},{"id":"u3-pf1-q4","type":"choice","prompt":"This graph is a straight line through the origin. Which parent function is it?","choices":["Linear","Quadratic","Cubic","Absolute value"],"answer":0,"hint":"There is no bend at all.","solution":"A straight line through the origin with slope 1 is the linear parent function f(x) = x.","graph":{"fn":"x","x":[-6,6],"y":[-6,6]}},{"id":"u3-pf1-q5","type":"input","prompt":"f(x) = x². Find f(−3).","answers":["9"],"hint":"Square −3. A negative squared is positive.","solution":"f(−3) = (−3)² = 9."},{"id":"u3-pf1-q6","type":"input","prompt":"f(x) = x³. Find f(−2).","answers":["-8"],"hint":"Cube means multiply three times.","solution":"f(−2) = (−2)(−2)(−2) = −8."},{"id":"u3-pf1-q7","type":"input","prompt":"f(x) = |x|. Find f(−7).","answers":["7"],"hint":"Absolute value is the distance from 0.","solution":"|−7| = 7."},{"id":"u3-pf1-q8","type":"choice","prompt":"A table shows x = −2, −1, 0, 1, 2 and f(x) = 4, 1, 0, 1, 4. Which parent function is it?","choices":["Linear","Cubic","Absolute value","Quadratic"],"answer":3,"hint":"Compare with x² and |x|.","solution":"x² gives 4, 1, 0, 1, 4. |x| would give 2, 1, 0, 1, 2. So it is quadratic."},{"id":"u3-pf1-q9","type":"choice","prompt":"A table shows x = −2, −1, 0, 1, 2 and f(x) = −8, −1, 0, 1, 8. Which parent function is it?","choices":["Quadratic","Linear","Cubic","Absolute value"],"answer":2,"hint":"Notice the outputs are negative for negative x.","solution":"x³ gives −8, −1, 0, 1, 8. This is the cubic."}]},{"id":"parent-functions-2","teach":[{"title":"Square root, cube root, reciprocal, exponential","text":["Square root f(x) = √x starts at the origin and curves to the right. Cube root f(x) = ∛x is like a sideways S through the origin.","Reciprocal f(x) = 1/x has two separate branches and never touches either axis. Exponential f(x) = 2ˣ climbs quickly on the right and flattens toward 0 on the left."],"example":{"problem":"Evaluate f(x) = ∛x at x = −8.","steps":["Ask: what number cubed is −8?","(−2)³ = −8, so f(−8) = −2."]}}],"questions":[{"id":"u3-pf2-q1","type":"choice","prompt":"This graph starts at the origin and curves to the right. Which parent function is it?","choices":["Cube root","Square root","Exponential","Quadratic"],"answer":1,"hint":"It begins at a point and goes only to the right.","solution":"The curve starts at (0, 0) and goes right. That is f(x) = √x.","graph":{"fn":"sqrt(x)","x":[-2,10],"y":[-3,5]}},{"id":"u3-pf2-q2","type":"choice","prompt":"This graph is a sideways S that is steep at the origin and flattens out far from it. Which parent function is it?","choices":["Cube root","Square root","Cubic","Reciprocal"],"answer":0,"hint":"It passes through the origin and goes both left and right.","solution":"It goes through (−8, −2), (0, 0), and (8, 2) like a sideways S. That is f(x) = ∛x.","graph":{"fn":"root(3,x)","x":[-8,8],"y":[-4,4]}},{"id":"u3-pf2-q3","type":"choice","prompt":"This graph has two separate branches. Which parent function is it?","choices":["Linear","Exponential","Absolute value","Reciprocal"],"answer":3,"hint":"It has two separate pieces.","solution":"Two branches that never touch the axes make the reciprocal function f(x) = 1/x.","graph":{"fn":"1/x","x":[-6,6],"y":[-6,6]}},{"id":"u3-pf2-q4","type":"choice","prompt":"This graph crosses the y-axis at (0, 1) and climbs fast. Which parent function is it?","choices":["Quadratic","Square root","Exponential","Reciprocal"],"answer":2,"hint":"It never goes below the x-axis and grows faster and faster.","solution":"The curve crosses the y-axis at (0, 1) and climbs quickly. That is f(x) = 2ˣ.","graph":{"fn":"2^x","x":[-4,4],"y":[-2,10]}},{"id":"u3-pf2-q5","type":"input","prompt":"f(x) = 2ˣ. Find f(5).","answers":["32"],"hint":"Multiply 2 by itself 5 times.","solution":"2⁵ = 2 · 2 · 2 · 2 · 2 = 32.","calculator":false},{"id":"u3-pf2-q6","type":"input","prompt":"f(x) = √x. Find f(49).","answers":["7"],"hint":"What number times itself is 49?","solution":"7 · 7 = 49, so f(49) = 7.","calculator":false},{"id":"u3-pf2-q7","type":"input","prompt":"f(x) = ∛x. Find f(−27).","answers":["-3"],"hint":"What number cubed is −27?","solution":"(−3)³ = −27, so f(−27) = −3.","calculator":false},{"id":"u3-pf2-q8","type":"input","prompt":"f(x) = 1/x. Find f(4).","answers":["1/4"],"hint":"The reciprocal of 4 is 1 over 4.","solution":"f(4) = 1/4.","calculator":false},{"id":"u3-pf2-q9","type":"choice","prompt":"Which parent function has a graph made of two separate branches?","choices":["Square root, f(x) = √x","Reciprocal, f(x) = 1/x","Absolute value, f(x) = |x|","Exponential, f(x) = 2ˣ"],"answer":1,"hint":"One function cannot use x = 0.","solution":"Because x = 0 is not allowed, the graph of 1/x breaks into a piece on each side of the y-axis."}]},{"id":"parent-functions-3","teach":[{"title":"Domain and range of the parent functions","text":["Linear, cubic, and cube root: domain (−∞, ∞), range (−∞, ∞).","Quadratic and absolute value: domain (−∞, ∞), range [0, ∞). Square root: domain [0, ∞), range [0, ∞).","Reciprocal: both domain and range are (−∞, 0) ∪ (0, ∞). Exponential 2ˣ: domain (−∞, ∞), range (0, ∞)."],"example":{"problem":"Give the domain and range of f(x) = √x.","steps":["You cannot take the square root of a negative, so x ≥ 0. Domain: [0, ∞).","The root is never negative, and it reaches 0. Range: [0, ∞)."]}}],"questions":[{"id":"u3-pf3-q1","type":"choice","prompt":"What is the domain of f(x) = √x?","choices":["[0, ∞)","(−∞, ∞)","(0, ∞)","(−∞, 0]"],"answer":0,"hint":"Negative numbers have no real square root.","solution":"Only x ≥ 0 works, and 0 is included. Domain: [0, ∞)."},{"id":"u3-pf3-q2","type":"choice","prompt":"What is the range of f(x) = x²?","choices":["(−∞, ∞)","(−∞, 0]","(0, ∞)","[0, ∞)"],"answer":3,"hint":"A square is never negative, but it can be 0.","solution":"x² ≥ 0 and x = 0 gives 0. Range: [0, ∞)."},{"id":"u3-pf3-q3","type":"choice","prompt":"What is the domain of f(x) = 1/x?","choices":["(−∞, ∞)","[0, ∞)","(−∞, 0) ∪ (0, ∞)","(0, ∞)"],"answer":2,"hint":"Which input would divide by zero?","solution":"x = 0 is not allowed. Domain: (−∞, 0) ∪ (0, ∞)."},{"id":"u3-pf3-q4","type":"choice","prompt":"What is the range of f(x) = 2ˣ?","choices":["[0, ∞)","(0, ∞)","(−∞, ∞)","(−∞, 0)"],"answer":1,"hint":"Can a power of 2 ever equal 0?","solution":"2ˣ is always positive but never reaches 0. Range: (0, ∞)."},{"id":"u3-pf3-q5","type":"input","prompt":"Which x-value is excluded from the domain of f(x) = 1/x?","answers":["0"],"hint":"Where would the bottom be zero?","solution":"The bottom is 0 when x = 0, so 0 is excluded."},{"id":"u3-pf3-q6","type":"choice","prompt":"Which parent function has domain [0, ∞) and range [0, ∞)?","choices":["f(x) = √x","f(x) = x²","f(x) = |x|","f(x) = 2ˣ"],"answer":0,"hint":"Both the inputs and outputs must be 0 or more.","solution":"Only the square root function has x ≥ 0 as its domain and y ≥ 0 as its range. x² and |x| allow negative x."},{"id":"u3-pf3-q7","type":"choice","prompt":"Look at the graph. What is the range of f(x) = |x|?","choices":["(−∞, ∞)","(−∞, 0]","(0, ∞)","[0, ∞)"],"answer":3,"hint":"Read the lowest and highest y-values.","solution":"The V opens up from (0, 0). The y-values are 0 and larger. Range: [0, ∞).","graph":{"fn":"abs(x)","x":[-6,6],"y":[-2,8]}},{"id":"u3-pf3-q8","type":"input","prompt":"As x gets more and more negative, 2ˣ gets close to what number?","answers":["0"],"hint":"Try 2⁻¹, 2⁻², 2⁻³ ...","solution":"2⁻¹ = 1/2, 2⁻² = 1/4, 2⁻³ = 1/8. The values shrink toward 0."},{"id":"u3-pf3-q9","type":"choice","prompt":"Look at the graph of f(x) = ∛x. What are its domain and range?","choices":["Domain [0, ∞); Range [0, ∞)","Domain (−∞, ∞); Range [0, ∞)","Domain (−∞, ∞); Range (−∞, ∞)","Domain [0, ∞); Range (−∞, ∞)"],"answer":2,"hint":"Can you cube-root negative numbers?","solution":"You can take a cube root of any real number, and the outputs cover every number too. Both are (−∞, ∞).","graph":{"fn":"root(3,x)","x":[-8,8],"y":[-4,4]}}]},{"id":"parent-functions-4","teach":[{"title":"Even and odd functions","text":["Even: f(−x) = f(x). The graph is symmetric about the y-axis, like a mirror. Examples: x², |x|.","Odd: f(−x) = −f(x). The graph is symmetric about the origin: spin it 180° and it looks the same. Examples: x, x³, ∛x, 1/x.","Neither: √x and 2ˣ."],"example":{"problem":"Is f(x) = x³ even or odd?","steps":["Compute f(−x) = (−x)³ = −x³.","That equals −f(x), so f is odd."]}}],"questions":[{"id":"u3-pf4-q1","type":"choice","prompt":"Which parent function is even?","choices":["f(x) = x³","f(x) = |x|","f(x) = x","f(x) = 1/x"],"answer":1,"hint":"Even means f(−x) = f(x). Try x = 2 and x = −2.","solution":"|−2| = |2| = 2, so |x| is even. The others give opposite values for −2 and 2."},{"id":"u3-pf4-q2","type":"choice","prompt":"Which parent function is odd?","choices":["f(x) = x³","f(x) = x²","f(x) = |x|","f(x) = √x"],"answer":0,"hint":"Odd means f(−x) = −f(x).","solution":"(−2)³ = −8 = −(2³). So x³ is odd. x² and |x| are even, and √x is neither."},{"id":"u3-pf4-q3","type":"choice","prompt":"The graph of f(x) = x² is symmetric about...","choices":["the x-axis","the origin","the line y = x","the y-axis"],"answer":3,"hint":"Mirror the right half onto the left.","solution":"x² is even, and even functions are symmetric about the y-axis."},{"id":"u3-pf4-q4","type":"choice","prompt":"Which parent function is neither even nor odd?","choices":["f(x) = x²","f(x) = x³","f(x) = √x","f(x) = 1/x"],"answer":2,"hint":"It has no values at all for negative x.","solution":"√x is not defined for negative x, so f(−x) cannot match f(x) or −f(x). It is neither."},{"id":"u3-pf4-q5","type":"input","prompt":"g(x) = 1/x. Find g(−5).","answers":["-1/5"],"hint":"Put −5 in the bottom of the fraction.","solution":"g(−5) = 1/(−5) = −1/5."},{"id":"u3-pf4-q6","type":"input","prompt":"f is an even function and f(4) = 11. What is f(−4)?","answers":["11"],"hint":"Even means f(−x) = f(x).","solution":"Even functions match at opposite inputs, so f(−4) = f(4) = 11."},{"id":"u3-pf4-q7","type":"input","prompt":"f is an odd function and f(5) = −6. What is f(−5)?","answers":["6"],"hint":"Odd means f(−x) = −f(x).","solution":"f(−5) = −f(5) = −(−6) = 6."},{"id":"u3-pf4-q8","type":"choice","prompt":"Look at the graph of f(x) = 1/x. How is it symmetric?","choices":["About the y-axis, so it is even","About the origin, so it is odd","About the x-axis, so it is even","It has no symmetry"],"answer":1,"hint":"Rotate the graph 180° around (0, 0).","solution":"The two branches match when you rotate the graph half a turn about the origin. That means odd.","graph":{"fn":"1/x","x":[-6,6],"y":[-6,6]}},{"id":"u3-pf4-q9","type":"choice","prompt":"A table shows x = 0, 1, 4, 9 and f(x) = 0, 1, 2, 3. Which parent function is it?","choices":["Square root","Linear","Quadratic","Cube root"],"answer":0,"hint":"The inputs are perfect squares.","solution":"f(x) = √x gives √0 = 0, √1 = 1, √4 = 2, √9 = 3."}]}]},{"id":"translations","title":"Translations","lessons":[{"id":"translations-1","teach":[{"title":"Vertical shifts","text":["g(x) = f(x) + k moves the graph of f up k units when k is positive and down |k| units when k is negative.","Every point (x, y) on f becomes (x, y + k) on g. Only the y-coordinate changes."],"example":{"problem":"The point (2, 7) is on f. Where is it on g(x) = f(x) − 3?","steps":["−3 means shift down 3.","The y-coordinate drops by 3: 7 − 3 = 4.","The new point is (2, 4)."]}}],"questions":[{"id":"u3-tr1-q1","type":"choice","prompt":"How does the graph of g(x) = x² + 3 compare with f(x) = x²?","choices":["Shifted down 3","Shifted right 3","Shifted left 3","Shifted up 3"],"answer":3,"hint":"The +3 is added outside, to the whole function.","solution":"Adding 3 to the output moves every point up 3."},{"id":"u3-tr1-q2","type":"choice","prompt":"How does the graph of g(x) = |x| − 5 compare with f(x) = |x|?","choices":["Shifted up 5","Shifted right 5","Shifted down 5","Shifted left 5"],"answer":2,"hint":"Subtracting from the output moves the graph down.","solution":"−5 outside the function moves the graph down 5 units."},{"id":"u3-tr1-q3","type":"input","prompt":"g(x) = x² + 4. The vertex of f(x) = x² is (0, 0). What is the y-coordinate of the vertex of g?","answers":["4"],"hint":"Add 4 to the y-coordinate.","solution":"The vertex moves up 4, from (0, 0) to (0, 4). The y-coordinate is 4."},{"id":"u3-tr1-q4","type":"input","prompt":"The point (2, 7) is on the graph of f. If g(x) = f(x) − 3, the point (2, b) is on g. What is b?","answers":["4"],"hint":"Subtract 3 from the y-coordinate.","solution":"b = 7 − 3 = 4."},{"id":"u3-tr1-q5","type":"choice","prompt":"The point (−1, 5) is on f. Which point is on g(x) = f(x) + 2?","choices":["(1, 5)","(−1, 7)","(−1, 3)","(−3, 5)"],"answer":1,"hint":"A vertical shift changes only one coordinate.","solution":"Add 2 to the y-coordinate: (−1, 5 + 2) = (−1, 7)."},{"id":"u3-tr1-q6","type":"choice","prompt":"Look at the graph. It is the graph of f(x) = x² shifted. Which equation is it?","choices":["g(x) = x² − 4","g(x) = x² + 4","g(x) = (x − 4)²","g(x) = (x + 4)²"],"answer":0,"hint":"Where is the vertex? Is it above or below the origin?","solution":"The vertex is at (0, −4), so the parabola moved down 4. g(x) = x² − 4.","graph":{"fn":"x^2-4","x":[-6,6],"y":[-6,8]}},{"id":"u3-tr1-q7","type":"choice","prompt":"Look at the graph. It is the graph of f(x) = √x shifted. Which equation is it?","choices":["g(x) = √x − 3","g(x) = √(x + 3)","g(x) = √(x − 3)","g(x) = √x + 3"],"answer":3,"hint":"Find the starting point of the curve.","solution":"The curve starts at (0, 3), so it moved up 3. g(x) = √x + 3.","graph":{"fn":"sqrt(x)+3","x":[-2,10],"y":[-2,8]}},{"id":"u3-tr1-q8","type":"input","prompt":"Look at the graph of g(x) = |x| + 2. What is the y-coordinate of its y-intercept?","answers":["2"],"hint":"The y-intercept is where the graph crosses the y-axis.","solution":"The graph crosses the y-axis at (0, 2). The y-coordinate is 2.","graph":{"fn":"abs(x)+2","x":[-6,6],"y":[-2,8]}},{"id":"u3-tr1-q9","type":"choice","prompt":"f(x) = x³. Which equation is g(x) = f(x) − 6?","choices":["g(x) = x³ + 6","g(x) = (x − 6)³","g(x) = x³ − 6","g(x) = 6x³"],"answer":2,"hint":"Subtract 6 after cubing.","solution":"f(x) − 6 means x³ − 6."}]},{"id":"translations-2","teach":[{"title":"Horizontal shifts","text":["g(x) = f(x − h) moves the graph right h units. g(x) = f(x + h) moves it left h units. The shift is the opposite of what the sign looks like.","Every point (x, y) on f becomes (x + h, y) on g."],"example":{"problem":"The point (4, 1) is on f. Where is it on g(x) = f(x − 3)?","steps":["x − 3 means shift right 3.","The x-coordinate goes up by 3: 4 + 3 = 7.","The new point is (7, 1)."]}}],"questions":[{"id":"u3-tr2-q1","type":"choice","prompt":"How does the graph of g(x) = (x − 4)² compare with f(x) = x²?","choices":["Shifted left 4","Shifted right 4","Shifted up 4","Shifted down 4"],"answer":1,"hint":"The 4 is inside, next to x.","solution":"x − 4 inside moves the graph right 4 units."},{"id":"u3-tr2-q2","type":"choice","prompt":"How does the graph of g(x) = |x + 3| compare with f(x) = |x|?","choices":["Shifted left 3","Shifted right 3","Shifted up 3","Shifted down 3"],"answer":0,"hint":"Inside changes act opposite to the sign.","solution":"x + 3 inside moves the graph left 3 units."},{"id":"u3-tr2-q3","type":"input","prompt":"g(x) = (x − 5)². The vertex of f(x) = x² is (0, 0). What is the x-coordinate of the vertex of g?","answers":["5"],"hint":"x − 5 shifts right 5.","solution":"The vertex moves right 5, to (5, 0). The x-coordinate is 5."},{"id":"u3-tr2-q4","type":"input","prompt":"g(x) = √(x + 2). The graph of f(x) = √x starts at x = 0. At what x-value does the graph of g start?","answers":["-2"],"hint":"The shift is left 2.","solution":"x + 2 shifts the graph left 2. It starts at x = −2."},{"id":"u3-tr2-q5","type":"choice","prompt":"The point (4, 1) is on f. Which point is on g(x) = f(x − 3)?","choices":["(1, 1)","(4, 4)","(4, −2)","(7, 1)"],"answer":3,"hint":"Right or left? Which coordinate changes?","solution":"f(x − 3) shifts right 3: add 3 to x. (4 + 3, 1) = (7, 1)."},{"id":"u3-tr2-q6","type":"choice","prompt":"The point (−2, 6) is on f. Which point is on g(x) = f(x + 5)?","choices":["(3, 6)","(−2, 11)","(−7, 6)","(−2, 1)"],"answer":2,"hint":"Plus inside means left.","solution":"f(x + 5) shifts left 5: subtract 5 from x. (−2 − 5, 6) = (−7, 6)."},{"id":"u3-tr2-q7","type":"choice","prompt":"Look at the graph. It is the graph of f(x) = |x| shifted. Which equation is it?","choices":["g(x) = |x + 3|","g(x) = |x − 3|","g(x) = |x| − 3","g(x) = |x| + 3"],"answer":1,"hint":"Find the corner of the V.","solution":"The corner is at (3, 0), so the graph shifted right 3. g(x) = |x − 3|.","graph":{"fn":"abs(x-3)","x":[-6,8],"y":[-2,8]}},{"id":"u3-tr2-q8","type":"input","prompt":"Look at the graph of g(x) = (x + 2)². What is the x-coordinate of its vertex?","answers":["-2"],"hint":"Read where the lowest point is.","solution":"The vertex is at (−2, 0). The x-coordinate is −2.","graph":{"fn":"(x+2)^2","x":[-6,4],"y":[-2,8]}},{"id":"u3-tr2-q9","type":"choice","prompt":"f(x − 6) moves the graph of f...","choices":["6 units right","6 units left","6 units up","6 units down"],"answer":0,"hint":"Subtracting inside shifts horizontally in the positive direction.","solution":"f(x − 6) is a horizontal shift right 6."}]},{"id":"translations-3","teach":[{"title":"Shifting both ways","text":["g(x) = f(x − h) + k shifts right h and up k. Read h with the opposite sign, and k with its own sign.","A vertex or key point (a, b) moves to (a + h, b + k)."],"example":{"problem":"Describe the shift of g(x) = (x − 2)² + 5 from f(x) = x².","steps":["x − 2 inside: right 2.","+5 outside: up 5.","The vertex moves from (0, 0) to (2, 5)."]}}],"questions":[{"id":"u3-tr3-q1","type":"choice","prompt":"Describe g(x) = (x − 2)² + 5 compared with f(x) = x².","choices":["Left 2, up 5","Right 5, up 2","Right 2, down 5","Right 2, up 5"],"answer":3,"hint":"Inside tells left/right (opposite sign). Outside tells up/down.","solution":"x − 2 means right 2. +5 means up 5."},{"id":"u3-tr3-q2","type":"input","prompt":"g(x) = (x + 1)² − 6. What is the x-coordinate of its vertex?","answers":["-1"],"hint":"Use the opposite of the number inside.","solution":"x + 1 shifts left 1, so the vertex x is −1."},{"id":"u3-tr3-q3","type":"input","prompt":"g(x) = |x − 7| + 2. What is the y-coordinate of its vertex?","answers":["2"],"hint":"The number added outside is the y-coordinate.","solution":"The vertex is (7, 2). The y-coordinate is 2."},{"id":"u3-tr3-q4","type":"choice","prompt":"Find the vertex of g(x) = |x + 4| − 1.","choices":["(4, −1)","(−4, 1)","(−4, −1)","(4, 1)"],"answer":2,"hint":"Opposite sign inside, same sign outside.","solution":"x + 4 gives x = −4. −1 outside gives y = −1. Vertex (−4, −1)."},{"id":"u3-tr3-q5","type":"choice","prompt":"The point (3, −2) is on f. Which point is on g(x) = f(x − 1) + 4?","choices":["(2, 2)","(4, 2)","(4, −6)","(2, −6)"],"answer":1,"hint":"Add 1 to x for the right shift, then add 4 to y.","solution":"(3 + 1, −2 + 4) = (4, 2)."},{"id":"u3-tr3-q6","type":"choice","prompt":"The graph shown is f(x) = x² shifted. Which equation is it?","choices":["g(x) = (x − 1)² + 2","g(x) = (x + 1)² + 2","g(x) = (x − 1)² − 2","g(x) = (x + 1)² − 2"],"answer":0,"hint":"Read the vertex from the graph.","solution":"The vertex is (1, 2). Right 1 gives (x − 1), up 2 gives + 2. g(x) = (x − 1)² + 2.","graph":{"fn":"(x-1)^2+2","x":[-4,6],"y":[-2,10]}},{"id":"u3-tr3-q7","type":"input","prompt":"Look at the graph of g(x) = √(x − 2) + 1. What is g(6)?","answers":["3"],"hint":"Read the y-value above x = 6.","solution":"g(6) = √4 + 1 = 2 + 1 = 3.","graph":{"fn":"sqrt(x-2)+1","x":[-2,12],"y":[-3,7]}},{"id":"u3-tr3-q8","type":"choice","prompt":"Describe g(x) = ∛(x + 8) − 3 compared with f(x) = ∛x.","choices":["Right 8, down 3","Left 8, up 3","Right 3, up 8","Left 8, down 3"],"answer":3,"hint":"Inside is opposite, outside is the same sign.","solution":"x + 8 shifts left 8. −3 shifts down 3."},{"id":"u3-tr3-q9","type":"input","prompt":"f(x) = x² and g(x) = f(x − 2) + 3. Find g(5).","answers":["12"],"hint":"Find f(5 − 2) first, then add 3.","solution":"g(5) = f(3) + 3 = 9 + 3 = 12.","calculator":false}]},{"id":"translations-4","teach":[{"title":"Writing and analyzing translations","text":["To write an equation: subtract h inside, add k outside. Right 2 becomes (x − 2). Down 7 becomes − 7.","A shift moves the domain and range too. If f has domain [0, ∞), then f(x − h) + k has domain [h, ∞), and the range moves up by k."],"example":{"problem":"Find the domain and range of g(x) = √(x − 4) + 1.","steps":["The parent √x has domain [0, ∞) and range [0, ∞).","Right 4 moves the domain to [4, ∞).","Up 1 moves the range to [1, ∞)."]}}],"questions":[{"id":"u3-tr4-q1","type":"choice","prompt":"Which is the graph of f(x) = |x| shifted left 2 and down 7?","choices":["g(x) = |x − 2| − 7","g(x) = |x + 2| + 7","g(x) = |x + 2| − 7","g(x) = |x − 2| + 7"],"answer":2,"hint":"Left means + inside. Down means − outside.","solution":"Left 2: |x + 2|. Down 7: − 7. So g(x) = |x + 2| − 7."},{"id":"u3-tr4-q2","type":"choice","prompt":"Which is f(x) = x² shifted right 6 and up 1?","choices":["g(x) = (x + 6)² + 1","g(x) = (x − 6)² + 1","g(x) = (x − 6)² − 1","g(x) = (x − 1)² + 6"],"answer":1,"hint":"Right 6 means subtract 6 inside.","solution":"Right 6: (x − 6)². Up 1: + 1. So g(x) = (x − 6)² + 1."},{"id":"u3-tr4-q3","type":"input","prompt":"g(x) = √(x + 3) − 2. Find g(6).","answers":["1"],"hint":"Add 3 to 6 first, then take the square root.","solution":"g(6) = √9 − 2 = 3 − 2 = 1.","calculator":false},{"id":"u3-tr4-q4","type":"choice","prompt":"Find the domain and range of g(x) = √(x − 4) + 1.","choices":["Domain [4, ∞); Range [1, ∞)","Domain [1, ∞); Range [4, ∞)","Domain [−4, ∞); Range [−1, ∞)","Domain (4, ∞); Range (1, ∞)"],"answer":0,"hint":"The parent has domain and range [0, ∞). Shift each.","solution":"Right 4 moves the domain to [4, ∞). Up 1 moves the range to [1, ∞)."},{"id":"u3-tr4-q5","type":"choice","prompt":"Find the range of g(x) = (x + 2)² − 5.","choices":["[5, ∞)","[−2, ∞)","(−∞, −5]","[−5, ∞)"],"answer":3,"hint":"The vertex is the lowest point.","solution":"The vertex is (−2, −5) and the parabola opens up. The range is [−5, ∞)."},{"id":"u3-tr4-q6","type":"input","prompt":"The point (−3, 4) is on f. It becomes (a, b) on g(x) = f(x − 6) + 1. Find a + b.","answers":["8"],"hint":"Add 6 to x and add 1 to y.","solution":"a = −3 + 6 = 3 and b = 4 + 1 = 5. So a + b = 8."},{"id":"u3-tr4-q7","type":"input","prompt":"g(x) = 1/(x − 2) + 3. Which x-value is excluded from its domain?","answers":["2"],"hint":"Set the bottom equal to 0.","solution":"x − 2 = 0 gives x = 2.","calculator":false},{"id":"u3-tr4-q8","type":"choice","prompt":"Look at the graph. It is the graph of f(x) = ∛x shifted. Which equation is it?","choices":["g(x) = ∛(x + 2) + 1","g(x) = ∛(x − 2) − 1","g(x) = ∛(x − 2) + 1","g(x) = ∛(x + 2) − 1"],"answer":2,"hint":"The center point of the cube root was (0, 0). Where is it now?","solution":"The center moved to (2, 1): right 2, up 1. g(x) = ∛(x − 2) + 1.","graph":{"fn":"root(3,x-2)+1","x":[-6,10],"y":[-4,6]}},{"id":"u3-tr4-q9","type":"input","prompt":"g(x) = 2ˣ + 4. As x → −∞, the graph gets close to the horizontal line y = k. What is k?","answers":["4"],"hint":"2ˣ gets close to 0 on the left. Then add 4.","solution":"As x → −∞, 2ˣ → 0, so g(x) → 4. The line is y = 4."}]}]},{"id":"reflections","title":"Reflections","lessons":[{"id":"reflections-1","teach":[{"title":"Reflecting over the x-axis","text":["g(x) = −f(x) flips the graph over the x-axis. Every y-value changes sign.","A point (x, y) on f becomes (x, −y) on g."],"example":{"problem":"The point (3, 5) is on f. Where is it on g(x) = −f(x)?","steps":["The negative sign on f(x) flips the y-value.","The x-coordinate stays 3. The y-coordinate becomes −5.","The new point is (3, −5)."]}}],"questions":[{"id":"u3-rf1-q1","type":"choice","prompt":"The graph of g(x) = −f(x) is a reflection of f over...","choices":["the y-axis","the x-axis","the origin only","the line y = x"],"answer":1,"hint":"The negative is outside the function.","solution":"A negative outside flips the outputs, which reflects the graph over the x-axis."},{"id":"u3-rf1-q2","type":"choice","prompt":"The point (3, 5) is on f. Which point is on g(x) = −f(x)?","choices":["(3, −5)","(−3, 5)","(−3, −5)","(5, 3)"],"answer":0,"hint":"Which coordinate changes sign?","solution":"Reflecting over the x-axis changes the sign of y only: (3, −5)."},{"id":"u3-rf1-q3","type":"input","prompt":"f(2) = −7 and g(x) = −f(x). Find g(2).","answers":["7"],"hint":"Take the opposite of f(2).","solution":"g(2) = −f(2) = −(−7) = 7."},{"id":"u3-rf1-q4","type":"input","prompt":"f(x) = x² + 1 and g(x) = −f(x). Find g(3).","answers":["-10"],"hint":"Find f(3) first, then negate.","solution":"f(3) = 9 + 1 = 10, so g(3) = −10."},{"id":"u3-rf1-q5","type":"choice","prompt":"The graph of g(x) = −x² opens...","choices":["up","left","right","down"],"answer":3,"hint":"The parent x² opens up. What does the negative do?","solution":"The reflection over the x-axis turns the U upside down, so it opens down."},{"id":"u3-rf1-q6","type":"choice","prompt":"Look at the graph. It is f(x) = x² − 4 reflected over the x-axis. Which equation is it?","choices":["g(x) = −x² − 4","g(x) = x² + 4","g(x) = −x² + 4","g(x) = −(x + 4)²"],"answer":2,"hint":"Negate the whole function: −(x² − 4).","solution":"−(x² − 4) = −x² + 4. The vertex (0, −4) flips to (0, 4).","graph":{"fn":"-x^2+4","x":[-5,5],"y":[-6,6]}},{"id":"u3-rf1-q7","type":"choice","prompt":"f(x) = x − 3. What is −f(x)?","choices":["−x − 3","−x + 3","x + 3","x − 3"],"answer":1,"hint":"Distribute the negative to both terms.","solution":"−(x − 3) = −x + 3."},{"id":"u3-rf1-q8","type":"input","prompt":"f(x) = √x and g(x) = −f(x). Find g(16).","answers":["-4"],"hint":"Find f(16), then negate.","solution":"f(16) = 4, so g(16) = −4.","calculator":false},{"id":"u3-rf1-q9","type":"choice","prompt":"Look at the graph of g(x) = −√x. What is its range?","choices":["(−∞, 0]","[0, ∞)","(−∞, ∞)","(0, ∞)"],"answer":0,"hint":"The curve goes downward from the origin.","solution":"The curve starts at (0, 0) and falls. All y-values are 0 or less. Range: (−∞, 0].","graph":{"fn":"-sqrt(x)","x":[-2,10],"y":[-5,3]}}]},{"id":"reflections-2","teach":[{"title":"Reflecting over the y-axis","text":["g(x) = f(−x) flips the graph over the y-axis. The negative is inside, next to x.","A point (x, y) on f becomes (−x, y) on g."],"example":{"problem":"The point (6, −2) is on f. Where is it on g(x) = f(−x)?","steps":["The negative inside flips the x-value.","The y-coordinate stays −2. The x-coordinate becomes −6.","The new point is (−6, −2)."]}}],"questions":[{"id":"u3-rf2-q1","type":"choice","prompt":"The graph of g(x) = f(−x) is a reflection of f over...","choices":["the x-axis","the origin only","the line y = x","the y-axis"],"answer":3,"hint":"The negative is inside, with x.","solution":"A negative inside flips the inputs, which reflects the graph over the y-axis."},{"id":"u3-rf2-q2","type":"choice","prompt":"The point (3, 5) is on f. Which point is on g(x) = f(−x)?","choices":["(3, −5)","(−3, −5)","(−3, 5)","(5, 3)"],"answer":2,"hint":"Which coordinate changes sign this time?","solution":"Reflecting over the y-axis changes the sign of x only: (−3, 5)."},{"id":"u3-rf2-q3","type":"input","prompt":"f(x) = 2x + 1 and g(x) = f(−x). Find g(4).","answers":["-7"],"hint":"g(4) = f(−4).","solution":"g(4) = f(−4) = 2(−4) + 1 = −8 + 1 = −7."},{"id":"u3-rf2-q4","type":"input","prompt":"f(x) = x³ and g(x) = f(−x). Find g(2).","answers":["-8"],"hint":"g(2) = f(−2).","solution":"g(2) = f(−2) = (−2)³ = −8."},{"id":"u3-rf2-q5","type":"choice","prompt":"What is the domain of g(x) = √(−x)?","choices":["[0, ∞)","(−∞, 0]","(−∞, ∞)","(0, ∞)"],"answer":1,"hint":"Solve −x ≥ 0. Dividing by a negative flips the inequality.","solution":"−x ≥ 0 gives x ≤ 0. Domain: (−∞, 0]."},{"id":"u3-rf2-q6","type":"choice","prompt":"Look at the graph. It is f(x) = √x reflected over the y-axis. Which equation is it?","choices":["g(x) = √(−x)","g(x) = −√x","g(x) = √x","g(x) = −√(−x)"],"answer":0,"hint":"The curve goes to the left of the y-axis and stays above the x-axis.","solution":"The curve is on the left and goes up. Replace x with −x: g(x) = √(−x).","graph":{"fn":"sqrt(-x)","x":[-10,2],"y":[-2,5]}},{"id":"u3-rf2-q7","type":"choice","prompt":"f(x) = x² is reflected over the y-axis. What is the new graph?","choices":["The graph of y = −x²","The graph of y = x² shifted left","The graph of y = x² shifted right","The same graph, because x² is even"],"answer":3,"hint":"Compute (−x)².","solution":"(−x)² = x², so f(−x) = f(x). The parabola is symmetric about the y-axis, so it does not change."},{"id":"u3-rf2-q8","type":"input","prompt":"The point (6, −2) is on f. It becomes (a, b) on g(x) = f(−x). Find a + b.","answers":["-8"],"hint":"Only x changes sign.","solution":"The point is (−6, −2). a + b = −6 + (−2) = −8."},{"id":"u3-rf2-q9","type":"choice","prompt":"f(x) = x³ + x. What is f(−x)?","choices":["x³ + x","−x³ + x","−x³ − x","x³ − x"],"answer":2,"hint":"Replace every x with (−x).","solution":"f(−x) = (−x)³ + (−x) = −x³ − x."}]},{"id":"reflections-3","teach":[{"title":"Which reflection is it?","text":["Check where the negative sits. Outside f (−f(x)): x-axis, y changes sign. Inside f (f(−x)): y-axis, x changes sign.","With both, g(x) = −f(−x), the point (x, y) becomes (−x, −y)."],"example":{"problem":"Reflect the point (2, 5) over both axes.","steps":["Over the x-axis: (2, −5).","Then over the y-axis: (−2, −5).","Both changed sign: (−2, −5)."]}}],"questions":[{"id":"u3-rf3-q1","type":"choice","prompt":"g(x) = −|x| is a reflection of f(x) = |x| over...","choices":["the y-axis","the x-axis","both axes","neither axis"],"answer":1,"hint":"Is the negative inside or outside?","solution":"The negative is outside the absolute value, so it flips the outputs: reflection over the x-axis."},{"id":"u3-rf3-q2","type":"choice","prompt":"g(x) = √(−x) is a reflection of f(x) = √x over...","choices":["the y-axis","the x-axis","both axes","neither axis"],"answer":0,"hint":"Is the negative inside or outside?","solution":"The negative is inside, replacing x, so it reflects over the y-axis."},{"id":"u3-rf3-q3","type":"choice","prompt":"For g(x) = −f(−x), the point (a, b) on f goes to...","choices":["(−a, b)","(a, −b)","(a, b)","(−a, −b)"],"answer":3,"hint":"There are two negatives. One flips x and one flips y.","solution":"The inside negative changes x and the outside negative changes y. So (a, b) → (−a, −b)."},{"id":"u3-rf3-q4","type":"input","prompt":"The point (2, 5) is on f, and g(x) = −f(−x). Find g(−2).","answers":["-5"],"hint":"g(−2) = −f(2).","solution":"g(−2) = −f(2) = −5."},{"id":"u3-rf3-q5","type":"input","prompt":"The point (−4, 3) is reflected over the x-axis. What is the y-coordinate of the new point?","answers":["-3"],"hint":"Reflecting over the x-axis negates y.","solution":"The new point is (−4, −3). Its y-coordinate is −3."},{"id":"u3-rf3-q6","type":"choice","prompt":"The point (−4, 3) is reflected over the y-axis. What is the new point?","choices":["(−4, −3)","(4, −3)","(4, 3)","(3, −4)"],"answer":2,"hint":"The y-axis flip changes only x.","solution":"The x-coordinate changes sign and y stays: (4, 3)."},{"id":"u3-rf3-q7","type":"choice","prompt":"Look at the graph of g(x) = −|x| + 3. How is it related to f(x) = |x|?","choices":["Reflected over the y-axis, then shifted up 3","Reflected over the x-axis, then shifted up 3","Reflected over the x-axis, then shifted down 3","Shifted up 3 only"],"answer":1,"hint":"The V opens down and its corner is above the origin.","solution":"The V opens down (reflection over the x-axis) and has its vertex at (0, 3) (up 3).","graph":{"fn":"-abs(x)+3","x":[-6,6],"y":[-6,5]}},{"id":"u3-rf3-q8","type":"input","prompt":"f(x) = x² − 9 and g(x) = −f(x). Find the x-values where g(x) = 0. Give both.","answers":["3, -3"],"hint":"g(x) = −x² + 9. Set it equal to 0.","solution":"−x² + 9 = 0 gives x² = 9, so x = 3 or x = −3. Reflecting over the x-axis does not move the x-intercepts."},{"id":"u3-rf3-q9","type":"choice","prompt":"Which function is unchanged when reflected over the y-axis?","choices":["f(x) = |x|","f(x) = x³","f(x) = √x","f(x) = 1/x"],"answer":0,"hint":"It is the one with f(−x) = f(x).","solution":"|−x| = |x|, so |x| is even and its graph looks the same after the reflection. x³ and 1/x are odd and √x is neither."}]},{"id":"reflections-4","teach":[{"title":"Reflections with shifts","text":["Order matters when you read a function. For −f(x) + k, reflect first, then shift. A vertex (h, k) in −a(x − h)² + k means the parabola opens down.","Reflections change domain and range too: −√x has range (−∞, 0], and √(−x) has domain (−∞, 0]."],"example":{"problem":"Describe g(x) = −|x − 2| + 5.","steps":["Negative outside: reflected over the x-axis, so it opens down.","x − 2: right 2. + 5: up 5.","The vertex is (2, 5), the highest point."]}}],"questions":[{"id":"u3-rf4-q1","type":"choice","prompt":"Which is f(x) = x² reflected over the x-axis, then shifted up 3?","choices":["g(x) = x² − 3","g(x) = −x² − 3","g(x) = (−x)² + 3","g(x) = −x² + 3"],"answer":3,"hint":"Negate first, then add 3.","solution":"Reflecting gives −x². Shifting up 3 gives −x² + 3."},{"id":"u3-rf4-q2","type":"choice","prompt":"Describe g(x) = −|x − 2| + 5.","choices":["Vertex (−2, 5), opens down","Vertex (2, 5), opens up","Vertex (2, 5), opens down","Vertex (2, −5), opens down"],"answer":2,"hint":"The minus sign in front makes the V open down. Read the vertex.","solution":"Opening: negative outside, so down. Vertex: x − 2 gives x = 2, + 5 gives y = 5. Vertex (2, 5)."},{"id":"u3-rf4-q3","type":"input","prompt":"What is the maximum value of g(x) = −(x + 1)² + 6?","answers":["6"],"hint":"The parabola opens down. Find the vertex.","solution":"The vertex is (−1, 6). Since it opens down, the maximum value is 6.","calculator":false},{"id":"u3-rf4-q4","type":"choice","prompt":"Find the domain and range of g(x) = √(−x) + 2.","choices":["Domain [0, ∞); Range [2, ∞)","Domain (−∞, 0]; Range [2, ∞)","Domain (−∞, 0]; Range [−2, ∞)","Domain (−∞, 0]; Range (−∞, 2]"],"answer":1,"hint":"The inside negative flips the domain. The + 2 shifts the range up.","solution":"−x ≥ 0 gives x ≤ 0, so the domain is (−∞, 0]. The root is at least 0, so the range is [2, ∞)."},{"id":"u3-rf4-q5","type":"input","prompt":"f(x) = x³ + 2x and g(x) = f(−x). Find g(1).","answers":["-3"],"hint":"g(1) = f(−1).","solution":"g(1) = f(−1) = (−1)³ + 2(−1) = −1 − 2 = −3.","calculator":false},{"id":"u3-rf4-q6","type":"choice","prompt":"Look at the graph. It is f(x) = x² reflected and shifted. Which equation is it?","choices":["g(x) = −(x − 1)² + 3","g(x) = −(x + 1)² + 3","g(x) = (x − 1)² + 3","g(x) = −(x − 1)² − 3"],"answer":0,"hint":"The parabola opens down, with its vertex at (1, 3).","solution":"It opens down, so there is a negative. The vertex (1, 3) means (x − 1)² and + 3.","graph":{"fn":"-(x-1)^2+3","x":[-4,6],"y":[-6,5]}},{"id":"u3-rf4-q7","type":"input","prompt":"The point (2, −3) is on f. It becomes (2, b) on g(x) = −f(x) + 4. Find b.","answers":["7"],"hint":"Negate the y-value, then add 4.","solution":"b = −(−3) + 4 = 3 + 4 = 7."},{"id":"u3-rf4-q8","type":"choice","prompt":"Find the domain and range of g(x) = −√(x + 5).","choices":["Domain [5, ∞); Range (−∞, 0]","Domain [−5, ∞); Range [0, ∞)","Domain (−∞, −5]; Range (−∞, 0]","Domain [−5, ∞); Range (−∞, 0]"],"answer":3,"hint":"x + 5 ≥ 0 for the domain. The negative outside flips the range.","solution":"x + 5 ≥ 0 gives x ≥ −5, so the domain is [−5, ∞). The root is at least 0 and the negative flips it, so the range is (−∞, 0]."},{"id":"u3-rf4-q9","type":"input","prompt":"Find the x-intercepts of g(x) = −|x| + 4. Give both x-values.","answers":["4, -4"],"hint":"Set −|x| + 4 = 0.","solution":"−|x| + 4 = 0 gives |x| = 4, so x = 4 or x = −4.","calculator":false}]}]},{"id":"stretches","title":"Stretches and compressions","lessons":[{"id":"stretches-1","teach":[{"title":"Vertical stretch and compression","text":["g(x) = a·f(x) multiplies every y-value by a. The x-values do not change.","If |a| > 1, the graph is stretched vertically (it gets taller and narrower). If 0 < |a| < 1, it is compressed vertically (it gets flatter)."],"example":{"problem":"A point (2, 3) is on f. Find its image on g(x) = 4f(x).","steps":["The x-value stays 2.","Multiply the y-value by 4: 4 · 3 = 12.","The image point is (2, 12)."]}}],"questions":[{"id":"u3-str1-q1","type":"choice","prompt":"How does the graph of g(x) = 3f(x) compare with the graph of f(x)?","choices":["Stretched vertically by a factor of 3","Compressed vertically by a factor of 3","Stretched horizontally by a factor of 3","Shifted up 3 units"],"answer":0,"hint":"The 3 is outside f, so it acts on the y-values.","solution":"Multiplying f(x) by 3 triples every y-value. That is a vertical stretch by a factor of 3."},{"id":"u3-str1-q2","type":"input","prompt":"f(2) = 5. If g(x) = 4f(x), what is g(2)?","answers":["20"],"hint":"Multiply the output by 4.","solution":"g(2) = 4 · f(2) = 4 · 5 = 20."},{"id":"u3-str1-q3","type":"choice","prompt":"Which function is a vertical stretch of f(x) = x²?","choices":["g(x) = 0.3x²","g(x) = x² + 3","g(x) = 3x²","g(x) = (x + 3)²"],"answer":2,"hint":"A vertical stretch multiplies the whole function by a number bigger than 1.","solution":"3x² multiplies every y-value by 3, so it is a vertical stretch. 0.3x² is a compression. x² + 3 is a shift up. (x + 3)² is a shift left."},{"id":"u3-str1-q4","type":"input","prompt":"The point (3, −2) is on f. The point (3, k) is on g(x) = 5f(x). What is k?","answers":["-10"],"hint":"Multiply the y-value by 5. Keep the sign.","solution":"k = 5 · (−2) = −10."},{"id":"u3-str1-q5","type":"input","prompt":"f(x) = x² + 2 and g(x) = 3f(x). What is the y-intercept of g?","answers":["6"],"hint":"The y-intercept is g(0).","solution":"g(0) = 3 · f(0) = 3 · (0² + 2) = 3 · 2 = 6."},{"id":"u3-str1-q6","type":"input","prompt":"A table for f has f(1) = 2, f(2) = −3, f(4) = 1.5. If g(x) = 2f(x), what is g(4)?","answers":["3"],"hint":"Find f(4) in the table, then double it.","solution":"f(4) = 1.5, so g(4) = 2 · 1.5 = 3."},{"id":"u3-str1-q7","type":"input","prompt":"f(−4) = 9. If g(x) = (1/3)f(x), what is g(−4)?","answers":["3"],"hint":"A fraction between 0 and 1 compresses the graph. Multiply the output by 1/3.","solution":"g(−4) = (1/3) · 9 = 3."},{"id":"u3-str1-q8","type":"choice","prompt":"g(x) = (1/2)f(x). Which statement is true?","choices":["Every x-value of f is cut in half; the y-values stay the same.","Every y-value of f is doubled; the x-values stay the same.","Every y-value of f goes down by 1/2.","Every y-value of f is cut in half; the x-values stay the same."],"answer":3,"hint":"Which coordinate does a number outside f(x) change?","solution":"Multiplying the output by 1/2 halves every y-value. The x-values do not change. It is a vertical compression by a factor of 1/2."}]},{"id":"stretches-2","teach":[{"title":"Vertical compressions and negative a","text":["If 0 < |a| < 1, g(x) = a·f(x) is a vertical compression. Each y-value shrinks toward the x-axis.","If a is negative, the graph is also reflected over the x-axis. A stretch or compression never moves the x-intercepts, because 0 times anything is still 0."],"example":{"problem":"A point (3, 5) is on f. Find its image on g(x) = −2f(x).","steps":["The x-value stays 3.","Multiply the y-value by −2: −2 · 5 = −10.","The image point is (3, −10). It is stretched by 2 and flipped over the x-axis."]}}],"questions":[{"id":"u3-str2-q1","type":"choice","prompt":"g(x) = 0.25f(x). How does g compare with f?","choices":["Vertical stretch by a factor of 4","Vertical compression by a factor of 1/4","Horizontal compression by a factor of 1/4","Shifted down 0.25 units"],"answer":1,"hint":"0.25 is the same as 1/4. It multiplies the outputs.","solution":"Multiplying outputs by 1/4 shrinks every y-value toward the x-axis. That is a vertical compression by a factor of 1/4."},{"id":"u3-str2-q2","type":"input","prompt":"The point (8, 12) is on f. The point (8, k) is on g(x) = (1/4)f(x). What is k?","answers":["3"],"hint":"Multiply the y-value by 1/4.","solution":"k = (1/4) · 12 = 3."},{"id":"u3-str2-q3","type":"choice","prompt":"The point (2, 4) is on f. Which point is on g(x) = −3f(x)?","choices":["(2, −12)","(−2, 12)","(2, 12)","(−6, 4)"],"answer":0,"hint":"Only the y-value changes. Multiply it by −3.","solution":"The x-value stays 2. The y-value becomes −3 · 4 = −12. The image is (2, −12)."},{"id":"u3-str2-q4","type":"choice","prompt":"How does g(x) = −(1/2)x² compare with f(x) = x²?","choices":["Reflected over the y-axis and vertically stretched by 2","Reflected over the x-axis and vertically stretched by 2","Reflected over the x-axis and vertically compressed by 1/2","Shifted down 1/2 and reflected"],"answer":2,"hint":"The negative sign flips it. The 1/2 changes how tall it is.","solution":"The negative sign reflects the graph over the x-axis. The factor 1/2 compresses it vertically by 1/2."},{"id":"u3-str2-q5","type":"input","prompt":"f(5) = −2. If g(x) = −3f(x), what is g(5)?","answers":["6"],"hint":"Multiply −2 by −3.","solution":"g(5) = −3 · (−2) = 6."},{"id":"u3-str2-q6","type":"choice","prompt":"Which function makes the parabola y = x² narrower?","choices":["y = 5x²","y = 0.2x²","y = x²/2","y = −x²/5"],"answer":0,"hint":"Narrower means the y-values grow faster. You need a multiplier bigger than 1 in size.","solution":"5x² makes every y-value 5 times larger, so the parabola gets narrower. 0.2x², x²/2, and −x²/5 all make it wider."},{"id":"u3-str2-q7","type":"input","prompt":"The point (4, 6) is on f and the point (4, −9) is on g(x) = a·f(x). What is a?","answers":["-3/2","-1.5"],"hint":"Solve a · 6 = −9.","solution":"a · 6 = −9, so a = −9/6 = −3/2 = −1.5."},{"id":"u3-str2-q8","type":"input","prompt":"f has zeros at x = −1 and x = 3. g(x) = 2f(x). What are the zeros of g?","answers":["-1, 3"],"hint":"Where does 2 · f(x) = 0?","solution":"2f(x) = 0 exactly when f(x) = 0. A vertical stretch does not move the zeros. They stay at x = −1 and x = 3."}]},{"id":"stretches-3","teach":[{"title":"Horizontal stretch and compression","text":["g(x) = f(bx) changes the x-values. Each x-value is divided by b. The y-values stay the same.","If |b| > 1 the graph is compressed horizontally by a factor of 1/|b|. If 0 < |b| < 1 it is stretched horizontally by a factor of 1/|b|. This is the opposite of what you might guess."],"example":{"problem":"A point (8, −1) is on f. Find its image on g(x) = f(4x).","steps":["The y-value stays −1.","Divide the x-value by 4: 8 ÷ 4 = 2.","The image point is (2, −1). The graph is squeezed toward the y-axis."]}}],"questions":[{"id":"u3-str3-q1","type":"choice","prompt":"How does g(x) = f(2x) compare with f(x)?","choices":["Stretched horizontally by a factor of 2","Stretched vertically by a factor of 2","Compressed horizontally by a factor of 1/2","Compressed vertically by a factor of 1/2"],"answer":2,"hint":"The 2 is inside f, so it acts on the x-values.","solution":"Inside, 2x reaches each output in half the x-distance. So x-values are halved: a horizontal compression by a factor of 1/2."},{"id":"u3-str3-q2","type":"input","prompt":"The point (6, 5) is on f. The point (k, 5) is on g(x) = f(2x). What is k?","answers":["3"],"hint":"Divide the x-value by 2.","solution":"k = 6 ÷ 2 = 3. Check: g(3) = f(2 · 3) = f(6) = 5."},{"id":"u3-str3-q3","type":"choice","prompt":"How does g(x) = f(x/3) compare with f(x)?","choices":["Compressed horizontally by a factor of 3","Stretched horizontally by a factor of 3","Stretched vertically by a factor of 3","Compressed vertically by a factor of 1/3"],"answer":1,"hint":"x/3 is the same as (1/3)x, so b = 1/3.","solution":"b = 1/3, and each x-value is divided by 1/3, which means multiplied by 3. That is a horizontal stretch by a factor of 3."},{"id":"u3-str3-q4","type":"input","prompt":"The point (4, −1) is on f. The point (k, −1) is on g(x) = f(x/2). What is k?","answers":["8"],"hint":"b = 1/2. Divide the x-value by 1/2.","solution":"Dividing by 1/2 is the same as multiplying by 2. k = 4 · 2 = 8."},{"id":"u3-str3-q5","type":"choice","prompt":"The point (−6, 9) is on f. Which point is on g(x) = f(3x)?","choices":["(−18, 9)","(−6, 3)","(−6, 27)","(−2, 9)"],"answer":3,"hint":"Only the x-value changes. Divide it by 3.","solution":"x becomes −6 ÷ 3 = −2. The y-value stays 9. The image is (−2, 9)."},{"id":"u3-str3-q6","type":"input","prompt":"f has a zero at x = 12. g(x) = f(4x). Where is the zero of g?","answers":["3"],"hint":"Solve 4x = 12.","solution":"g(x) = 0 when 4x = 12, so x = 3."},{"id":"u3-str3-q7","type":"choice","prompt":"Which function is a horizontal compression of f by a factor of 1/5?","choices":["g(x) = f(5x)","g(x) = f(x/5)","g(x) = 5f(x)","g(x) = f(x)/5"],"answer":0,"hint":"A compression by 1/5 means each x-value is divided by 5.","solution":"To divide x-values by 5, use b = 5: g(x) = f(5x). f(x/5) is a stretch, and 5f(x) and f(x)/5 change y-values."},{"id":"u3-str3-q8","type":"input","prompt":"The point (9, 2) on f is mapped to (3, 2) on g(x) = f(bx). What is b?","answers":["3"],"hint":"The new x-value is 9 ÷ b.","solution":"9 ÷ b = 3, so b = 3."}]},{"id":"stretches-4","teach":[{"title":"Both together","text":["For g(x) = a·f(bx), a point (x, y) on f goes to (x/b, a·y). Do the x-value and the y-value separately.","For some functions the two effects look alike. For f(x) = x², f(3x) = 9x², which is also a vertical stretch by 9."],"example":{"problem":"The point (9, 2) is on f. Find its image on g(x) = −3f(x/3).","steps":["Here a = −3 and b = 1/3.","x-value: 9 ÷ (1/3) = 27.","y-value: −3 · 2 = −6.","The image is (27, −6)."]}}],"questions":[{"id":"u3-str4-q1","type":"choice","prompt":"f(x) = x² and g(x) = f(3x). Which is g(x) simplified?","choices":["g(x) = 3x²","g(x) = 6x²","g(x) = x²/9","g(x) = 9x²"],"answer":3,"hint":"Replace x with 3x inside x².","solution":"g(x) = (3x)² = 9x²."},{"id":"u3-str4-q2","type":"input","prompt":"f(x) = x² − 9 has zeros at x = 3 and x = −3. Find the zeros of g(x) = f(x/2).","answers":["6, -6"],"hint":"Solve (x/2)² − 9 = 0, or double each zero.","solution":"g(x) = (x/2)² − 9 = 0 gives x/2 = ±3, so x = ±6. The graph is stretched horizontally by 2, so each zero doubles."},{"id":"u3-str4-q3","type":"choice","prompt":"The point (4, −6) is on f. Which point is on g(x) = −2f(x/2)?","choices":["(2, 12)","(8, 12)","(2, −12)","(8, −12)"],"answer":1,"hint":"x/2 divides by b = 1/2, so x doubles. The −2 acts on y.","solution":"x: 4 ÷ (1/2) = 8. y: −2 · (−6) = 12. The image is (8, 12)."},{"id":"u3-str4-q4","type":"input","prompt":"f(x) = √x and g(x) = 2f(x). What is g(9)?","answers":["6"],"hint":"Find f(9) first.","solution":"f(9) = √9 = 3, so g(9) = 2 · 3 = 6."},{"id":"u3-str4-q5","type":"choice","prompt":"Which describes h(x) = (1/3)f(2x)?","choices":["Horizontal compression by 1/2 and vertical compression by 1/3","Horizontal stretch by 2 and vertical stretch by 3","Horizontal stretch by 2 and vertical compression by 1/3","Horizontal compression by 1/3 and vertical compression by 1/2"],"answer":0,"hint":"The 2 is inside f. The 1/3 is outside f.","solution":"Inside: 2x compresses x-values by 1/2. Outside: 1/3 compresses y-values by 1/3."},{"id":"u3-str4-q6","type":"input","prompt":"f(x) = x² + 1 and g(x) = f(3x). What is g(2)?","answers":["37"],"hint":"g(2) = f(3 · 2).","solution":"g(2) = f(6) = 6² + 1 = 37."},{"id":"u3-str4-q7","type":"choice","prompt":"The point (6, −3) is on f. Which point is on g(x) = 4f(x/3)?","choices":["(2, −12)","(18, −3/4)","(18, −12)","(2, −3/4)"],"answer":2,"hint":"x/3 means b = 1/3. Divide x by 1/3, then multiply y by 4.","solution":"x: 6 ÷ (1/3) = 18. y: 4 · (−3) = −12. The image is (18, −12)."},{"id":"u3-str4-q8","type":"input","prompt":"The point (10, 6) on f is mapped to (5, 18) on g(x) = a·f(bx). What is a · b?","answers":["6"],"hint":"Find b from the x-values and a from the y-values.","solution":"x: 10 ÷ b = 5, so b = 2. y: a · 6 = 18, so a = 3. Then a · b = 6."}]}]},{"id":"combined","title":"Combining transformations","lessons":[{"id":"combined-1","teach":[{"title":"Reading g(x) = a·f(x − h) + k","text":["Each number does one job. h shifts the graph right (if h is positive). a stretches, compresses, or flips it vertically. k shifts it up.","x − h with a minus sign moves right. x + 3 is x − (−3), so it moves left 3."],"example":{"problem":"Describe g(x) = 2f(x − 3) + 1.","steps":["x − 3 inside: shift right 3.","2 outside: vertical stretch by a factor of 2.","+ 1 outside: shift up 1."]}}],"questions":[{"id":"u3-com1-q1","type":"choice","prompt":"Which describes g(x) = 2f(x − 3) + 1?","choices":["Right 3, vertical stretch by 2, up 1","Left 3, vertical stretch by 2, up 1","Right 3, horizontal stretch by 2, up 1","Right 3, vertical stretch by 2, down 1"],"answer":0,"hint":"Inside the parentheses, x − 3 moves the graph right.","solution":"x − 3 shifts right 3. The 2 multiplies the outputs: vertical stretch by 2. The + 1 shifts up 1."},{"id":"u3-com1-q2","type":"input","prompt":"f(x) = x² and g(x) = 2f(x − 3) + 1. What is g(5)?","answers":["9"],"hint":"Work from the inside out: x − 3 first, then f, then 2 times, then + 1.","solution":"g(5) = 2f(5 − 3) + 1 = 2f(2) + 1 = 2 · 4 + 1 = 9."},{"id":"u3-com1-q3","type":"choice","prompt":"Which describes g(x) = −f(x + 4) − 2?","choices":["Reflect over the y-axis, left 4, down 2","Reflect over the x-axis, left 4, down 2","Reflect over the x-axis, right 4, down 2","Reflect over the x-axis, left 4, up 2"],"answer":1,"hint":"x + 4 is x − (−4). The minus in front of f flips the outputs.","solution":"−f flips over the x-axis. x + 4 shifts left 4. − 2 shifts down 2."},{"id":"u3-com1-q4","type":"input","prompt":"The point (1, 3) is on f. The point (k, 5) is on g(x) = f(x − 4) + 2. What is k?","answers":["5"],"hint":"The shift right adds 4 to the x-value.","solution":"x: 1 + 4 = 5. y: 3 + 2 = 5, which matches. So k = 5."},{"id":"u3-com1-q5","type":"choice","prompt":"The point (1, 3) is on f. Which point is on g(x) = f(x − 4) + 2?","choices":["(−3, 5)","(5, 1)","(5, 5)","(−3, 1)"],"answer":2,"hint":"Add 4 to x for the right shift. Add 2 to y for the up shift.","solution":"x: 1 + 4 = 5. y: 3 + 2 = 5. The image is (5, 5)."},{"id":"u3-com1-q6","type":"input","prompt":"The point (−2, 4) is on f. The point (−3, k) is on g(x) = 3f(x + 1) − 5. What is k?","answers":["7"],"hint":"Multiply the y-value by 3 first, then subtract 5.","solution":"x: −2 − 1 = −3. y: 3 · 4 − 5 = 12 − 5 = 7. So k = 7."},{"id":"u3-com1-q7","type":"choice","prompt":"Which function shifts f left 2 units and down 5 units?","choices":["g(x) = f(x − 2) − 5","g(x) = f(x + 2) + 5","g(x) = f(x − 2) + 5","g(x) = f(x + 2) − 5"],"answer":3,"hint":"Left is + inside. Down is − outside.","solution":"Left 2 is f(x + 2). Down 5 is − 5 after f. So g(x) = f(x + 2) − 5."},{"id":"u3-com1-q8","type":"input","prompt":"f(x) = √x and g(x) = 2f(x − 1) + 3. What is g(5)?","answers":["7"],"hint":"x − 1 first: 5 − 1 = 4.","solution":"g(5) = 2f(4) + 3 = 2 · √4 + 3 = 2 · 2 + 3 = 7."}]},{"id":"combined-2","teach":[{"title":"Step by step with a key point","text":["To map a key point (x, y) on f to g(x) = a·f(x − h) + k, use (x + h, a·y + k).","Stretch first, then shift. 3f(x) + 2 means multiply by 3, then add 2. It does not mean add 2, then multiply."],"example":{"problem":"The point (5, −2) is on f. Find its image on g(x) = −2f(x − 1) + 3.","steps":["Here h = 1, a = −2, k = 3.","x: 5 + 1 = 6.","y: −2 · (−2) + 3 = 4 + 3 = 7.","The image is (6, 7)."]}}],"questions":[{"id":"u3-com2-q1","type":"choice","prompt":"The parent function is f(x) = |x| with vertex (0, 0). Where is the vertex of g(x) = −2f(x − 3) + 5?","choices":["(3, 5)","(−3, 5)","(3, −5)","(−2, 5)"],"answer":0,"hint":"Shift (0, 0) right 3, then up 5. The −2 does nothing to 0.","solution":"x: 0 + 3 = 3. y: −2 · 0 + 5 = 5. The vertex is (3, 5)."},{"id":"u3-com2-q2","type":"input","prompt":"The point (2, −1) is on f. The point (0, k) is on g(x) = −3f(x + 2) + 4. What is k?","answers":["7"],"hint":"Multiply by −3 first, then add 4.","solution":"k = −3 · (−1) + 4 = 3 + 4 = 7."},{"id":"u3-com2-q3","type":"choice","prompt":"The point (2, −1) is on f. Which point is on g(x) = −3f(x + 2) + 4?","choices":["(4, 7)","(0, 7)","(0, −7)","(0, 1)"],"answer":1,"hint":"Left 2 changes x from 2 to 0.","solution":"x: 2 − 2 = 0. y: −3 · (−1) + 4 = 7. The image is (0, 7)."},{"id":"u3-com2-q4","type":"input","prompt":"f(x) = x³ and (2, 8) is on f. The point (3, k) is on g(x) = (1/2)f(x − 1) − 3. What is k?","answers":["1"],"hint":"Take half of 8, then subtract 3.","solution":"k = (1/2) · 8 − 3 = 4 − 3 = 1."},{"id":"u3-com2-q5","type":"choice","prompt":"The point (1, 5) is on f. Which point is on g(x) = 3f(x) + 2?","choices":["(1, 21)","(1, 13)","(1, 17)","(4, 7)"],"answer":2,"hint":"Stretch first, then shift: 3 · 5, then + 2.","solution":"y: 3 · 5 + 2 = 15 + 2 = 17. The x-value stays 1. The image is (1, 17). (1, 21) comes from adding 2 before multiplying, which is the wrong order."},{"id":"u3-com2-q6","type":"input","prompt":"f(4) = −2 and g(x) = −2f(x − 1) + 6. What is g(5)?","answers":["10"],"hint":"g(5) = −2f(5 − 1) + 6.","solution":"g(5) = −2f(4) + 6 = −2 · (−2) + 6 = 4 + 6 = 10."},{"id":"u3-com2-q7","type":"choice","prompt":"(−3, 0) is an x-intercept of f. Where is the image of that point on g(x) = 2f(x − 4)?","choices":["(−7, 0)","(1, 2)","(−6, 0)","(1, 0)"],"answer":3,"hint":"There is no + k, so the y-value 0 stays 0.","solution":"x: −3 + 4 = 1. y: 2 · 0 = 0. The image is (1, 0)."},{"id":"u3-com2-q8","type":"input","prompt":"f(x) = |x| and g(x) = −2f(x − 1) + 8. What is g(−3)?","answers":["0"],"hint":"x − 1 first: −3 − 1 = −4.","solution":"g(−3) = −2f(−4) + 8 = −2 · |−4| + 8 = −8 + 8 = 0."}]},{"id":"combined-3","teach":[{"title":"Domain and range after a combined move","text":["Move the endpoints of the domain and range with the same rules. The domain changes only by the shift h (right adds h). The range changes by a and k: multiply, then add k.","If a is negative, the endpoints swap order. Write the smaller number first."],"example":{"problem":"f has domain [0, 8] and range [1, 5]. Find the domain and range of g(x) = 3f(x + 2) − 4.","steps":["Domain: x + 2 shifts left 2, so subtract 2 from each end: [−2, 6].","Range: multiply by 3: [3, 15]. Then subtract 4: [−1, 11]."]}}],"questions":[{"id":"u3-com3-q1","type":"choice","prompt":"f has domain [−2, 6]. What is the domain of g(x) = f(x − 3) + 1?","choices":["[1, 9]","[−5, 3]","[−1, 7]","[−2, 6]"],"answer":0,"hint":"Only the shift inside changes the domain.","solution":"Right 3 adds 3 to each end: [−2 + 3, 6 + 3] = [1, 9]. The + 1 does not affect the domain."},{"id":"u3-com3-q2","type":"choice","prompt":"f has range [−1, 4]. What is the range of g(x) = f(x − 3) + 1?","choices":["[−2, 3]","[0, 5]","[−1, 4]","[1, 9]"],"answer":1,"hint":"Only the shift outside changes the range.","solution":"Up 1 adds 1 to each end: [−1 + 1, 4 + 1] = [0, 5]."},{"id":"u3-com3-q3","type":"choice","prompt":"f has range [−1, 4]. What is the range of g(x) = −2f(x) + 1?","choices":["[−1, 9]","[−3, 8]","[−7, 3]","[−9, 1]"],"answer":2,"hint":"Multiply by −2 first. The ends swap order. Then add 1.","solution":"−2 · (−1) = 2 and −2 · 4 = −8, so after multiplying the range is [−8, 2]. Adding 1 gives [−7, 3]."},{"id":"u3-com3-q4","type":"input","prompt":"f has a minimum value of −3. What is the minimum value of g(x) = 2f(x + 1) + 4?","answers":["-2"],"hint":"Stretch by 2 first, then shift up 4. The shift inside does not change values.","solution":"2 · (−3) = −6, then −6 + 4 = −2. The minimum value of g is −2."},{"id":"u3-com3-q5","type":"input","prompt":"f has a maximum value of 5. What is the maximum value of g(x) = 0.5f(x − 4) − 1?","answers":["3/2","1.5"],"hint":"Half of 5, then subtract 1.","solution":"0.5 · 5 = 2.5, then 2.5 − 1 = 1.5."},{"id":"u3-com3-q6","type":"choice","prompt":"f has a maximum of 5 at x = 2. What does g(x) = −f(x − 1) + 3 have?","choices":["A maximum of −2 at x = 3","A minimum of −2 at x = 1","A maximum of 8 at x = 3","A minimum of −2 at x = 3"],"answer":3,"hint":"The negative sign turns a maximum into a minimum.","solution":"The reflection turns the maximum into a minimum. Value: −5 + 3 = −2. Location: 2 + 1 = 3."},{"id":"u3-com3-q7","type":"input","prompt":"f(x) = √x starts at x = 0. g(x) = −3f(x − 5) + 2. At what x-value does g start?","answers":["5"],"hint":"The domain of g starts where x − 5 = 0.","solution":"x − 5 ≥ 0 means x ≥ 5. The graph of g starts at x = 5."},{"id":"u3-com3-q8","type":"choice","prompt":"f(x) = x². What is the range of g(x) = −f(x + 3) + 4?","choices":["y ≤ 4","y ≥ 4","y ≤ −4","y ≥ −3"],"answer":0,"hint":"The vertex is the highest point because the graph opens down.","solution":"The vertex is at (−3, 4) and the parabola opens down, so every y-value is at most 4. The range is y ≤ 4."}]},{"id":"combined-4","teach":[{"title":"Adding a horizontal stretch","text":["A function can also include f(b(x − h)). A point (x, y) goes to (x/b + h, a·y + k) for g(x) = a·f(b(x − h)) + k.","First divide x by b, then add h. For y, multiply by a, then add k."],"example":{"problem":"The point (4, −5) is on f. Find its image on g(x) = 2f(½(x + 1)).","steps":["Here b = ½, h = −1, a = 2, k = 0.","x: 4 ÷ ½ = 8, then 8 − 1 = 7.","y: 2 · (−5) = −10.","The image is (7, −10)."]}}],"questions":[{"id":"u3-com4-q1","type":"choice","prompt":"The point (4, 1) is on f. Which point is on g(x) = f(2(x − 3))?","choices":["(5, 1)","(11, 1)","(8, 1)","(5, 2)"],"answer":0,"hint":"Divide x by 2, then add 3.","solution":"x: 4 ÷ 2 = 2, then 2 + 3 = 5. The y-value stays 1. The image is (5, 1)."},{"id":"u3-com4-q2","type":"input","prompt":"The point (6, −4) is on f. The point (k, −12) is on g(x) = 3f(½(x − 1)). What is k?","answers":["13"],"hint":"Divide by ½, which is the same as multiplying by 2. Then add 1.","solution":"6 ÷ ½ = 12, and 12 + 1 = 13."},{"id":"u3-com4-q3","type":"choice","prompt":"Which equation is f stretched vertically by 2, compressed horizontally by 1/2, moved right 1 and up 3?","choices":["g(x) = 2f(½(x − 1)) + 3","g(x) = ½f(2(x − 1)) + 3","g(x) = 2f(2(x − 1)) + 3","g(x) = 2f(2(x + 1)) + 3"],"answer":2,"hint":"Compressing by 1/2 horizontally means b = 2.","solution":"Vertical stretch by 2 gives a = 2. Horizontal compression by 1/2 gives b = 2. Right 1 is (x − 1). Up 3 is + 3."},{"id":"u3-com4-q4","type":"input","prompt":"The point (−4, 2) is on f. What is the x-coordinate of its image on g(x) = −f(2(x + 1)) + 5?","answers":["-3"],"hint":"Divide by 2 first, then shift left 1.","solution":"−4 ÷ 2 = −2, then −2 − 1 = −3."},{"id":"u3-com4-q5","type":"choice","prompt":"The point (6, −1) is on f. Which point is on g(x) = −f(2(x + 1)) + 5?","choices":["(2, 4)","(2, 6)","(−4, 6)","(4, 6)"],"answer":1,"hint":"x: divide by 2, then subtract 1. y: negate, then add 5.","solution":"x: 6 ÷ 2 = 3, then 3 − 1 = 2. y: −(−1) + 5 = 6. The image is (2, 6)."},{"id":"u3-com4-q6","type":"input","prompt":"f(6) = 4 and g(x) = 2f(3x) − 1. What is g(2)?","answers":["7"],"hint":"3x = 6 when x = 2.","solution":"g(2) = 2f(3 · 2) − 1 = 2f(6) − 1 = 2 · 4 − 1 = 7."},{"id":"u3-com4-q7","type":"input","prompt":"The point (4, 3) is on f. What is the x-coordinate of its image on g(x) = −2f(2(x − 1)) + 4?","answers":["3"],"hint":"Divide 4 by 2, then add 1.","solution":"x: 4 ÷ 2 = 2, then 2 + 1 = 3. (The y-value is −2 · 3 + 4 = −2.)"},{"id":"u3-com4-q8","type":"choice","prompt":"A student maps (4, 3) to (9, 3) for g(x) = f(2(x − 1)). What was the mistake?","choices":["Multiplied x by 2 instead of dividing by 2","Added 1 instead of subtracting 1","Changed the y-value","Divided x by 2 and forgot the shift"],"answer":0,"hint":"Check what f(2x) does to x-values.","solution":"The correct x is 4 ÷ 2 + 1 = 3. The student did 4 · 2 + 1 = 9. Inside f, a multiplier b divides the x-value."}]}]},{"id":"writing-equations","title":"Writing equations from transformations","lessons":[{"id":"writing-equations-1","teach":[{"title":"From words to an equation","text":["Start with the parent function. Right h means x − h. Left h means x + h. Up k means + k. Down k means − k. A flip over the x-axis puts a minus in front of the function.","Order: do the stretch or flip, then the shift. Example for f(x) = x²: a(x − h)² + k."],"example":{"problem":"Write the equation for y = x² moved left 5 and down 2.","steps":["Left 5 means replace x with x + 5: (x + 5)².","Down 2 means subtract 2 outside.","y = (x + 5)² − 2"]}}],"questions":[{"id":"u3-wri1-q1","type":"choice","prompt":"Which is y = x² shifted right 4 and up 3?","choices":["y = (x − 4)² + 3","y = (x + 4)² + 3","y = (x − 4)² − 3","y = (x − 3)² + 4"],"answer":0,"hint":"Right goes with a minus inside the parentheses.","solution":"Right 4: (x − 4)². Up 3: + 3. So y = (x − 4)² + 3."},{"id":"u3-wri1-q2","type":"choice","prompt":"Which is y = |x| shifted left 2 and down 5?","choices":["y = |x − 2| − 5","y = |x + 2| + 5","y = |x + 2| − 5","y = |x − 5| + 2"],"answer":2,"hint":"Left means + inside. Down means − outside.","solution":"Left 2: |x + 2|. Down 5: − 5. So y = |x + 2| − 5."},{"id":"u3-wri1-q3","type":"input","prompt":"The graph of y = √x is shifted right 6, so the new equation is y = √(x − h). What is h?","answers":["6"],"hint":"Right 6 means x − 6.","solution":"y = √(x − 6), so h = 6."},{"id":"u3-wri1-q4","type":"choice","prompt":"Which is y = x³ reflected over the x-axis and then shifted up 1?","choices":["y = −x³ − 1","y = −x³ + 1","y = (−x)³ + 1","y = −(x + 1)³"],"answer":1,"hint":"The reflection over the x-axis puts a minus on the whole function.","solution":"Reflect: −x³. Shift up 1: −x³ + 1."},{"id":"u3-wri1-q5","type":"input","prompt":"y = |x| is stretched vertically by 3 and then moved down 4. In y = a|x| + k, what is k?","answers":["-4"],"hint":"Down 4 is a negative k.","solution":"The equation is y = 3|x| − 4, so a = 3 and k = −4."},{"id":"u3-wri1-q6","type":"choice","prompt":"Which is y = x² compressed vertically by 1/2 and shifted left 3?","choices":["y = ½(x − 3)²","y = 2(x + 3)²","y = (x + 3)²/2 + 3","y = ½(x + 3)²"],"answer":3,"hint":"A vertical compression by 1/2 multiplies by 1/2.","solution":"Left 3: (x + 3)². Compression by 1/2: ½(x + 3)². So y = ½(x + 3)²."},{"id":"u3-wri1-q7","type":"input","prompt":"y = −2(x + 1)² + 7 has its vertex at (h, k). What is h?","answers":["-1"],"hint":"x + 1 is x − (−1).","solution":"The vertex is (−1, 7), so h = −1."},{"id":"u3-wri1-q8","type":"choice","prompt":"Which is y = √x shifted left 5 and up 2?","choices":["y = √(x + 5) + 2","y = √(x − 5) + 2","y = √(x + 5) − 2","y = √(x + 2) + 5"],"answer":0,"hint":"The shift left goes inside the root.","solution":"Left 5: √(x + 5). Up 2: + 2."}]},{"id":"writing-equations-2","teach":[{"title":"Reading an equation off a graph","text":["Find the key point, the vertex or the start point, to get h and k. Then use one other point to find a.","For y = a(x − h)² + k, plug in the other point and solve for a. If the graph opens down, a is negative."],"example":{"problem":"A parabola has vertex (−2, 5), opens down, and passes through (0, 1). Find its equation.","steps":["Vertex (−2, 5) gives y = a(x + 2)² + 5.","Plug in (0, 1): 1 = a(2)² + 5, so 4a = −4 and a = −1.","y = −(x + 2)² + 5"]}}],"questions":[{"id":"u3-wri2-q1","type":"choice","prompt":"The graph shows a transformation of f(x) = x². Which is its equation?","choices":["y = (x − 3)² + 1","y = (x + 3)² + 1","y = (x − 3)² − 1","y = (x − 1)² + 3"],"answer":0,"hint":"Read the vertex off the graph. Then use it as (h, k).","solution":"The vertex is (3, 1), so h = 3 and k = 1. The equation is y = (x − 3)² + 1.","graph":{"fn":"(x-3)^2+1","x":[-2,8],"y":[-2,8]}},{"id":"u3-wri2-q2","type":"choice","prompt":"Which equation matches this V-shaped graph, a transformation of f(x) = |x|?","choices":["y = |x − 2| − 3","y = |x + 2| − 3","y = |x + 2| + 3","y = −|x + 2| − 3"],"answer":1,"hint":"The vertex is at (−2, −3).","solution":"The vertex (−2, −3) gives h = −2 and k = −3. The graph opens up, so a = 1. The equation is y = |x + 2| − 3.","graph":{"fn":"abs(x+2)-3","x":[-8,2],"y":[-6,4]}},{"id":"u3-wri2-q3","type":"choice","prompt":"The graph shows a transformation of f(x) = √x. Which is its equation?","choices":["y = √(x + 1) + 2","y = √(x − 2) + 1","y = √(x − 1) + 2","y = √(x − 1) − 2"],"answer":2,"hint":"The graph starts at (1, 2).","solution":"The start point (1, 2) gives h = 1 and k = 2. The equation is y = √(x − 1) + 2.","graph":{"fn":"sqrt(x-1)+2","x":[-2,8],"y":[-2,8]}},{"id":"u3-wri2-q4","type":"choice","prompt":"The graph shows a transformation of f(x) = x³. Which is its equation?","choices":["y = (x + 2)³ − 1","y = (x − 2)³ + 1","y = (x − 1)³ − 2","y = (x − 2)³ − 1"],"answer":3,"hint":"The center of the cubic, where it flattens, is at (2, −1).","solution":"The center point (2, −1) gives h = 2 and k = −1. The equation is y = (x − 2)³ − 1.","graph":{"fn":"(x-2)^3-1","x":[-2,6],"y":[-10,10]}},{"id":"u3-wri2-q5","type":"choice","prompt":"This graph is a transformation of f(x) = |x| that opens downward. Which is its equation?","choices":["y = −|x − 1| + 3","y = |x − 1| + 3","y = −|x + 1| + 3","y = −|x − 1| − 3"],"answer":0,"hint":"It opens down, so there is a minus sign in front.","solution":"The vertex (1, 3) gives h = 1 and k = 3. It opens down, so a is negative: y = −|x − 1| + 3.","graph":{"fn":"-abs(x-1)+3","x":[-5,7],"y":[-6,6]}},{"id":"u3-wri2-q6","type":"choice","prompt":"Which equation matches this parabola, a transformation of f(x) = x²?","choices":["y = (x + 1)² − 3","y = 2(x + 1)² − 3","y = 2(x − 1)² − 3","y = ½(x + 1)² − 3"],"answer":1,"hint":"The vertex is (−1, −3). Then check another point, like (0, −1).","solution":"Vertex (−1, −3) gives y = a(x + 1)² − 3. The point (0, −1): a(1) − 3 = −1, so a = 2. The equation is y = 2(x + 1)² − 3.","graph":{"fn":"2*(x+1)^2-3","x":[-5,5],"y":[-4,6]}},{"id":"u3-wri2-q7","type":"input","prompt":"The graph is y = a(x − 1)² + 2. It passes through (3, −2). What is a?","answers":["-1"],"hint":"Plug in x = 3 and y = −2, then solve for a.","solution":"−2 = a(3 − 1)² + 2 = 4a + 2. So 4a = −4 and a = −1.","graph":{"fn":"-(x-1)^2+2","x":[-4,6],"y":[-8,4]}},{"id":"u3-wri2-q8","type":"input","prompt":"The graph is y = a|x + 2| + 1. It passes through (0, 5). What is a?","answers":["2"],"hint":"Plug in x = 0 and y = 5.","solution":"5 = a|0 + 2| + 1 = 2a + 1. So 2a = 4 and a = 2.","graph":{"fn":"2*abs(x+2)+1","x":[-6,4],"y":[-2,8]}}]},{"id":"writing-equations-3","teach":[{"title":"Several transformations at once","text":["Build the equation in order: parent function, then reflection and stretch (a), then the shifts (h and k).","If you are given a vertex and one more point, find h and k from the vertex. Then substitute the point and solve for a."],"example":{"problem":"Write the equation for f(x) = √x reflected over the x-axis, stretched by 2, moved left 1 and down 3.","steps":["Reflect and stretch: a = −2.","Left 1: √(x + 1). Down 3: − 3.","y = −2√(x + 1) − 3"]}}],"questions":[{"id":"u3-wri3-q1","type":"choice","prompt":"Which is y = |x| reflected over the x-axis, stretched by 3, moved right 2 and up 4?","choices":["y = 3|x − 2| + 4","y = −3|x + 2| + 4","y = −3|x − 2| + 4","y = −3|x − 2| − 4"],"answer":2,"hint":"a is −3. Right 2 puts − 2 inside.","solution":"Reflect and stretch: a = −3. Right 2: |x − 2|. Up 4: + 4. y = −3|x − 2| + 4."},{"id":"u3-wri3-q2","type":"choice","prompt":"Which is y = √x compressed vertically by 1/2, moved left 4 and down 1?","choices":["y = ½√(x + 4) − 1","y = ½√(x − 4) − 1","y = 2√(x + 4) − 1","y = ½√(x + 4) + 1"],"answer":0,"hint":"Left 4 is + 4 inside the root.","solution":"Compression: a = ½. Left 4: √(x + 4). Down 1: − 1."},{"id":"u3-wri3-q3","type":"input","prompt":"A parabola y = a(x − 2)² − 5 has vertex (2, −5) and passes through (4, 3). What is a?","answers":["2"],"hint":"Substitute x = 4 and y = 3.","solution":"3 = a(4 − 2)² − 5 = 4a − 5. So 4a = 8 and a = 2."},{"id":"u3-wri3-q4","type":"choice","prompt":"Which is y = x³ reflected over the x-axis, moved right 1 and down 3?","choices":["y = −(x + 1)³ − 3","y = −(x − 1)³ − 3","y = (x − 1)³ − 3","y = −(x − 1)³ + 3"],"answer":1,"hint":"Put the minus on the whole cube. Then shift.","solution":"Reflect: −(…)³. Right 1: (x − 1). Down 3: − 3. y = −(x − 1)³ − 3."},{"id":"u3-wri3-q5","type":"input","prompt":"y = a|x − 3| + 1 has vertex (3, 1) and passes through (5, −3). What is a?","answers":["-2"],"hint":"Substitute x = 5 and y = −3.","solution":"−3 = a|5 − 3| + 1 = 2a + 1. So 2a = −4 and a = −2."},{"id":"u3-wri3-q6","type":"choice","prompt":"A table for g has the points (−1, 5), (0, 2), (1, 5), (2, 14). Which equation fits?","choices":["g(x) = 3x² + 5","g(x) = 2x² + 3","g(x) = (3x)² + 2","g(x) = 3x² + 2"],"answer":3,"hint":"g(0) = 2 gives the vertical shift. Then check g(1).","solution":"g(0) = 2 gives k = 2 and the vertex is (0, 2). g(1) = 5 gives a + 2 = 5, so a = 3. Check g(2) = 12 + 2 = 14. ✓"},{"id":"u3-wri3-q7","type":"input","prompt":"g(x) = a√x + k passes through (0, 3) and (4, 7). What is a?","answers":["2"],"hint":"g(0) gives k. Then use the second point.","solution":"g(0) = 3 gives k = 3. Then g(4) = a · 2 + 3 = 7, so 2a = 4 and a = 2."},{"id":"u3-wri3-q8","type":"choice","prompt":"Which is y = 1/x shifted right 3 and up 2?","choices":["y = 1/(x − 3) + 2","y = 1/(x + 3) + 2","y = 1/(x − 3) − 2","y = 1/(x − 2) + 3"],"answer":0,"hint":"The shift right goes inside the denominator.","solution":"Right 3: 1/(x − 3). Up 2: + 2."}]},{"id":"writing-equations-4","teach":[{"title":"Writing with a point and a description","text":["Use the vertex (h, k) to write y = a(x − h)² + k, or y = a|x − h| + k. Use any extra point to find a.","Check your equation by plugging in a second point. If the answer does not match, recheck the signs of h and k."],"example":{"problem":"Find the equation of a parabola with vertex (2, −1) that passes through (4, 7).","steps":["y = a(x − 2)² − 1.","7 = a(4 − 2)² − 1 = 4a − 1.","4a = 8, so a = 2.","y = 2(x − 2)² − 1"]}}],"questions":[{"id":"u3-wri4-q1","type":"input","prompt":"A parabola y = a(x + 3)² + 4 passes through (−1, −4). What is a?","answers":["-2"],"hint":"Substitute x = −1 and y = −4.","solution":"−4 = a(−1 + 3)² + 4 = 4a + 4. So 4a = −8 and a = −2."},{"id":"u3-wri4-q2","type":"choice","prompt":"Which equation matches this graph, which has a vertex and straight sides like f(x) = |x|?","choices":["y = −½|x − 2| + 3","y = ½|x − 2| + 3","y = −½|x + 2| + 3","y = −2|x − 2| + 3"],"answer":0,"hint":"Vertex first. Then check (4, 2): how far down does it go in 2 steps?","solution":"The vertex is (2, 3), and the graph opens down. One step 2 right goes down 1, so the slope is −½. y = −½|x − 2| + 3.","graph":{"fn":"-0.5*abs(x-2)+3","x":[-4,8],"y":[-3,5]}},{"id":"u3-wri4-q3","type":"choice","prompt":"The graph shows a transformation of f(x) = ∛x. Which is its equation?","choices":["y = 2∛(x + 3) − 1","y = 2∛(x − 3) − 1","y = 2∛(x + 3) + 1","y = ½∛(x + 3) − 1"],"answer":0,"hint":"The center is (−3, −1). One step right, to x = −2, gives y = 1.","solution":"The center (−3, −1) gives h = −3 and k = −1. At x = −2, y = 1: a · ∛1 − 1 = 1, so a = 2. y = 2∛(x + 3) − 1.","graph":{"fn":"2*root(3,x+3)-1","x":[-8,8],"y":[-5,5]}},{"id":"u3-wri4-q4","type":"input","prompt":"y = a|x − 4| − 2 has vertex (4, −2) and passes through (0, 6). What is a?","answers":["2"],"hint":"Substitute x = 0 and y = 6.","solution":"6 = a|0 − 4| − 2 = 4a − 2. So 4a = 8 and a = 2."},{"id":"u3-wri4-q5","type":"choice","prompt":"Which sequence of steps turns y = x² into y = −½(x + 4)² + 1?","choices":["Stretch by 2 and flip over the x-axis, move left 4, move up 1","Compress by ½ and flip over the x-axis, move left 4, move up 1","Compress by ½ and flip over the x-axis, move right 4, move up 1","Compress by ½ and flip over the y-axis, move left 4, move down 1"],"answer":1,"hint":"Read a, then h, then k.","solution":"a = −½ compresses by ½ and flips over the x-axis. (x + 4) moves left 4. + 1 moves up 1."},{"id":"u3-wri4-q6","type":"input","prompt":"y = a/(x − 2) + 1 passes through (3, 4). What is a?","answers":["3"],"hint":"Substitute x = 3 and y = 4.","solution":"4 = a/(3 − 2) + 1 = a + 1, so a = 3."},{"id":"u3-wri4-q7","type":"choice","prompt":"A parabola has vertex (1, −2) and y-intercept −5. Which is its equation?","choices":["y = 3(x − 1)² − 2","y = −3(x + 1)² − 2","y = −3(x − 1)² − 2","y = −5(x − 1)² − 2"],"answer":2,"hint":"The y-intercept is the point (0, −5).","solution":"y = a(x − 1)² − 2. At x = 0: a(1) − 2 = −5, so a = −3. y = −3(x − 1)² − 2."},{"id":"u3-wri4-q8","type":"input","prompt":"g(x) = a√(x + 1) + k passes through (0, 5) and (3, 8). What is k?","answers":["2"],"hint":"Two equations: a + k = 5 and 2a + k = 8.","solution":"g(0) = a · 1 + k = 5 and g(3) = a · 2 + k = 8. Subtract: a = 3. Then k = 5 − 3 = 2."}]}]},{"id":"absolute-value","title":"Absolute value functions","lessons":[{"id":"absolute-value-1","teach":[{"title":"Vertex and direction","text":["y = a|x − h| + k is a V shape. The vertex is the point (h, k). The axis of symmetry is the line x = h.","If a > 0 the V opens up and k is the minimum value. If a < 0 it opens down and k is the maximum value."],"example":{"problem":"Find the vertex of y = |x + 6| − 1 and tell whether it opens up or down.","steps":["x + 6 = x − (−6), so h = −6.","k = −1, so the vertex is (−6, −1).","a = 1 is positive, so it opens up."]}}],"questions":[{"id":"u3-abs1-q1","type":"choice","prompt":"What is the vertex of y = |x − 4| + 2?","choices":["(4, 2)","(−4, 2)","(4, −2)","(2, 4)"],"answer":0,"hint":"The vertex is (h, k) in y = a|x − h| + k.","solution":"x − 4 gives h = 4. + 2 gives k = 2. The vertex is (4, 2)."},{"id":"u3-abs1-q2","type":"choice","prompt":"What is the vertex of y = |x + 3| − 5?","choices":["(3, −5)","(−3, 5)","(−3, −5)","(3, 5)"],"answer":2,"hint":"x + 3 is x − (−3).","solution":"h = −3 and k = −5. The vertex is (−3, −5)."},{"id":"u3-abs1-q3","type":"choice","prompt":"Does y = −2|x − 1| + 6 open up or down?","choices":["Up, because k = 6 is positive","Down, because a = −2 is negative","Up, because h = 1 is positive","Down, because the vertex is at x = 1"],"answer":1,"hint":"Look at the number multiplying the absolute value.","solution":"The sign of a decides the direction. a = −2 is negative, so it opens down."},{"id":"u3-abs1-q4","type":"input","prompt":"What is the x-coordinate of the vertex of y = 3|x + 7| − 1?","answers":["-7"],"hint":"x + 7 is x − (−7).","solution":"h = −7. The vertex is (−7, −1), so the x-coordinate is −7."},{"id":"u3-abs1-q5","type":"input","prompt":"What is the minimum value of y = 2|x − 5| + 3?","answers":["3"],"hint":"The absolute value part is never negative. When is it 0?","solution":"|x − 5| ≥ 0, so y ≥ 3. The minimum value is 3, at x = 5."},{"id":"u3-abs1-q6","type":"choice","prompt":"The graph shows y = |x − 2| + 1. What is its vertex?","choices":["(1, 2)","(−2, 1)","(2, −1)","(2, 1)"],"answer":3,"hint":"Find the lowest point of the V.","solution":"The lowest point of the V is at x = 2, y = 1. The vertex is (2, 1).","graph":{"fn":"abs(x-2)+1","x":[-6,6],"y":[-2,8]}},{"id":"u3-abs1-q7","type":"input","prompt":"The axis of symmetry of y = |x + 6| − 2 is the line x = ?","answers":["-6"],"hint":"The axis passes through the vertex.","solution":"The vertex is (−6, −2), so the axis of symmetry is x = −6."},{"id":"u3-abs1-q8","type":"choice","prompt":"What is true about y = −|x| + 4?","choices":["It has a minimum value of 4 at x = 0","It has a maximum value of 4 at x = 4","It has a maximum value of 4 at x = 0","It has a minimum value of −4 at x = 0"],"answer":2,"hint":"It opens down. The vertex is the top.","solution":"a = −1, so it opens down. The vertex is (0, 4), the highest point. So the maximum is 4 at x = 0."}]},{"id":"absolute-value-2","teach":[{"title":"Slope of each side","text":["The two sides of the V are straight lines. For y = a|x − h| + k, the right side has slope a and the left side has slope −a.","A larger |a| makes the V narrower. A smaller |a| makes it wider."],"example":{"problem":"Find the slope of each side of y = −½|x + 2| + 1.","steps":["a = −½.","Right side slope: a = −½.","Left side slope: −a = ½."]}}],"questions":[{"id":"u3-abs2-q1","type":"input","prompt":"What is the slope of the right side of y = 3|x − 1| + 2?","answers":["3"],"hint":"The right side has slope a.","solution":"a = 3, so the right side has slope 3."},{"id":"u3-abs2-q2","type":"input","prompt":"What is the slope of the left side of y = 3|x − 1| + 2?","answers":["-3"],"hint":"The left side has slope −a.","solution":"The left side has slope −a = −3."},{"id":"u3-abs2-q3","type":"choice","prompt":"What are the slopes of the sides of y = −½|x + 2| + 1?","choices":["Right side −½ and left side ½","Right side ½ and left side −½","Both sides ½","Right side −2 and left side 2"],"answer":0,"hint":"Right side: a. Left side: −a.","solution":"a = −½. The right side has slope −½ and the left side has slope ½."},{"id":"u3-abs2-q4","type":"input","prompt":"What is y when x = 5 for y = 2|x − 3| − 4?","answers":["0"],"hint":"Work inside the absolute value first.","solution":"y = 2|5 − 3| − 4 = 2 · 2 − 4 = 0."},{"id":"u3-abs2-q5","type":"choice","prompt":"The graph shows y = 2|x − 1| − 3. What are the slopes of the two sides?","choices":["1 and −1","2 and −2","2 and 2","−3 and 3"],"answer":1,"hint":"From the vertex (1, −3), go 1 right. How far does y rise?","solution":"From the vertex (1, −3), one step right goes to (2, −1), a rise of 2. The right slope is 2 and the left slope is −2.","graph":{"fn":"2*abs(x-1)-3","x":[-4,6],"y":[-5,5]}},{"id":"u3-abs2-q6","type":"input","prompt":"The left side of y = a|x − 2| + 1 has slope −5. What is a?","answers":["5"],"hint":"The left side has slope −a.","solution":"−a = −5, so a = 5."},{"id":"u3-abs2-q7","type":"choice","prompt":"Which graph is the narrowest?","choices":["y = |x|","y = ½|x|","y = 0.1|x|","y = 4|x|"],"answer":3,"hint":"The steeper the sides, the narrower the V.","solution":"The sides of y = 4|x| have slope ±4, steeper than the others, so it is the narrowest."},{"id":"u3-abs2-q8","type":"input","prompt":"What is y when x = −5 for y = −3|x + 2| + 10?","answers":["1"],"hint":"x + 2 = −3 inside the bars.","solution":"y = −3|−5 + 2| + 10 = −3 · 3 + 10 = 1."}]},{"id":"absolute-value-3","teach":[{"title":"Intercepts","text":["The y-intercept is the value of y when x = 0. Plug in 0 and simplify.","For x-intercepts, set y = 0. Isolate the absolute value, then split into two cases: the inside equals the positive number, or the inside equals the negative number. If the absolute value would equal a negative number, there are no x-intercepts."],"example":{"problem":"Find the x-intercepts of y = 3|x − 2| − 9.","steps":["Set y = 0: 3|x − 2| = 9, so |x − 2| = 3.","x − 2 = 3 gives x = 5. x − 2 = −3 gives x = −1.","The x-intercepts are x = 5 and x = −1."]}}],"questions":[{"id":"u3-abs3-q1","type":"input","prompt":"What is the y-intercept of y = |x − 3| + 1?","answers":["4"],"hint":"Let x = 0.","solution":"y = |0 − 3| + 1 = 3 + 1 = 4."},{"id":"u3-abs3-q2","type":"input","prompt":"What is the y-intercept of y = 2|x + 4| − 5?","answers":["3"],"hint":"Let x = 0.","solution":"y = 2|4| − 5 = 8 − 5 = 3."},{"id":"u3-abs3-q3","type":"input","prompt":"Find the x-intercepts of y = |x − 2| − 5.","answers":["7, -3"],"hint":"Set y = 0 and write |x − 2| = 5. Two cases.","solution":"|x − 2| = 5 gives x − 2 = 5 or x − 2 = −5. So x = 7 or x = −3."},{"id":"u3-abs3-q4","type":"input","prompt":"Find the x-intercepts of y = 2|x + 1| − 8.","answers":["3, -5"],"hint":"Get |x + 1| alone first.","solution":"2|x + 1| = 8, so |x + 1| = 4. Then x + 1 = 4 or x + 1 = −4, so x = 3 or x = −5."},{"id":"u3-abs3-q5","type":"choice","prompt":"How many x-intercepts does y = −|x − 1| − 2 have?","choices":["None","One","Two","Three"],"answer":0,"hint":"It opens down. Where is its vertex?","solution":"The vertex is (1, −2) and the V opens down, so the graph stays below the x-axis. There are no x-intercepts."},{"id":"u3-abs3-q6","type":"choice","prompt":"Which function has two x-intercepts?","choices":["y = |x + 2| + 3","y = −|x + 2| − 3","y = |x + 2| − 3","y = 2|x − 4| + 1"],"answer":2,"hint":"A V that opens up needs its vertex below the x-axis.","solution":"y = |x + 2| − 3 opens up with vertex (−2, −3), below the x-axis, so it crosses the axis twice. The others never reach y = 0."},{"id":"u3-abs3-q7","type":"input","prompt":"Find the x-intercepts of y = −2|x − 3| + 8.","answers":["7, -1"],"hint":"Set y = 0 and divide by −2.","solution":"−2|x − 3| = −8, so |x − 3| = 4. Then x = 7 or x = −1."},{"id":"u3-abs3-q8","type":"input","prompt":"Find the x-intercepts of y = ½|x + 6| − 2.","answers":["-2, -10"],"hint":"Multiply both sides by 2 after moving the 2.","solution":"½|x + 6| = 2, so |x + 6| = 4. Then x + 6 = 4 gives x = −2, and x + 6 = −4 gives x = −10."}]},{"id":"absolute-value-4","teach":[{"title":"Writing and using absolute value equations","text":["To write an equation, use the vertex for h and k. Then use any other point to find a.","To solve a real situation, plug in the value you know, then check whether you need the positive or negative case."],"example":{"problem":"A V has vertex (2, 1) and passes through (4, 7). Find y = a|x − 2| + 1.","steps":["Plug in (4, 7): 7 = a|4 − 2| + 1 = 2a + 1.","2a = 6, so a = 3.","y = 3|x − 2| + 1"]}}],"questions":[{"id":"u3-abs4-q1","type":"choice","prompt":"A V opens up with vertex (3, −2) and sides with slope ±2. Which is its equation?","choices":["y = 2|x − 3| − 2","y = 2|x + 3| − 2","y = 2|x − 3| + 2","y = ½|x − 3| − 2"],"answer":0,"hint":"Use a = 2, h = 3, k = −2.","solution":"Vertex (3, −2) gives h = 3 and k = −2. The slope is 2 on the right, so a = 2."},{"id":"u3-abs4-q2","type":"input","prompt":"y = a|x + 1| + 4 has vertex (−1, 4) and passes through (2, −5). What is a?","answers":["-3"],"hint":"Plug in x = 2 and y = −5.","solution":"−5 = a|2 + 1| + 4 = 3a + 4. So 3a = −9 and a = −3."},{"id":"u3-abs4-q3","type":"choice","prompt":"The graph shows a V. Which is its equation?","choices":["y = |x + 3| + 2","y = −|x + 3| + 2","y = −|x − 3| + 2","y = −|x + 3| − 2"],"answer":1,"hint":"The vertex is at (−3, 2) and the V opens down.","solution":"The vertex (−3, 2) gives h = −3 and k = 2. It opens down with slopes ±1, so a = −1. y = −|x + 3| + 2.","graph":{"fn":"-abs(x+3)+2","x":[-8,2],"y":[-4,6]}},{"id":"u3-abs4-q4","type":"input","prompt":"y = a|x − 4| + 1 passes through (0, 13). What is a?","answers":["3"],"hint":"Plug in x = 0 and y = 13.","solution":"13 = a|0 − 4| + 1 = 4a + 1. So 4a = 12 and a = 3."},{"id":"u3-abs4-q5","type":"input","prompt":"A valley has height h = ½|x − 20| + 3, with x in meters. What is the height at x = 0?","answers":["13"],"hint":"Work inside the bars first.","solution":"h = ½|0 − 20| + 3 = ½ · 20 + 3 = 13."},{"id":"u3-abs4-q6","type":"input","prompt":"Find the x-intercepts of y = −3|x − 2| + 12.","answers":["6, -2"],"hint":"Isolate the absolute value first.","solution":"−3|x − 2| = −12, so |x − 2| = 4. Then x = 6 or x = −2."},{"id":"u3-abs4-q7","type":"choice","prompt":"Which statement about y = −2|x + 5| + 4 is true?","choices":["The vertex is (−5, 4) and the maximum value is 4","The vertex is (5, 4) and the maximum value is 4","The vertex is (−5, 4) and the minimum value is 4","The vertex is (−5, −4) and the maximum value is −4"],"answer":0,"hint":"Read h and k. Then use the sign of a.","solution":"x + 5 gives h = −5. k = 4. The vertex is (−5, 4). a = −2 is negative, so it opens down and the maximum is 4."},{"id":"u3-abs4-q8","type":"input","prompt":"For what x-values does 2|x − 1| − 3 equal 5? Give both.","answers":["5, -3"],"hint":"Solve 2|x − 1| − 3 = 5. First isolate |x − 1|.","solution":"2|x − 1| = 8, so |x − 1| = 4. Then x = 5 or x = −3."}]}]},{"id":"piecewise","title":"Piecewise functions","lessons":[{"id":"piecewise-1","teach":[{"title":"Which piece do I use?","text":["A piecewise function uses a different rule on different parts of the domain. Look at the condition next to each rule. Use the rule whose condition is true for your x-value.","Check the condition first. Then put the x-value into that rule only."],"example":{"problem":"f(x) = x + 2 if x < 1, and f(x) = 3x − 4 if x ≥ 1. Find f(5).","steps":["5 ≥ 1, so use the second rule.","f(5) = 3 · 5 − 4 = 11."]}}],"questions":[{"id":"u3-pie1-q1","type":"choice","prompt":"f(x) = 2x + 1 if x < 0, and x² − 3 if x ≥ 0. Which rule do you use to find f(4)?","choices":["x² − 3, because 4 ≥ 0","2x + 1, because 4 is positive","x² − 3, because 4 < 0","Both rules, then add"],"answer":0,"hint":"Check which condition 4 satisfies.","solution":"4 ≥ 0 is true, so use x² − 3."},{"id":"u3-pie1-q2","type":"input","prompt":"f(x) = 2x + 1 if x < 0, and x² − 3 if x ≥ 0. Find f(4).","answers":["13"],"hint":"Use the rule for x ≥ 0.","solution":"f(4) = 4² − 3 = 16 − 3 = 13."},{"id":"u3-pie1-q3","type":"input","prompt":"f(x) = 2x + 1 if x < 0, and x² − 3 if x ≥ 0. Find f(−2).","answers":["-3"],"hint":"−2 < 0, so use the first rule.","solution":"f(−2) = 2(−2) + 1 = −4 + 1 = −3."},{"id":"u3-pie1-q4","type":"input","prompt":"f(x) = 2x + 1 if x < 0, and x² − 3 if x ≥ 0. Find f(0).","answers":["-3"],"hint":"Is 0 < 0? Is 0 ≥ 0?","solution":"0 < 0 is false, but 0 ≥ 0 is true. Use x² − 3: f(0) = 0 − 3 = −3."},{"id":"u3-pie1-q5","type":"choice","prompt":"g(x) = x + 5 if x ≤ −1, and 2x if x > −1. Which rule do you use to find g(−1)?","choices":["2x, because −1 is not less than −1","2x, because −1 > −1","x + 5, because −1 ≤ −1","Either rule works"],"answer":2,"hint":"Which condition includes the equals sign?","solution":"x ≤ −1 includes −1, so use x + 5. The other rule needs x > −1, which excludes −1."},{"id":"u3-pie1-q6","type":"input","prompt":"g(x) = x + 5 if x ≤ −1, and 2x if x > −1. Find g(−1).","answers":["4"],"hint":"Use x + 5.","solution":"g(−1) = −1 + 5 = 4."},{"id":"u3-pie1-q7","type":"input","prompt":"g(x) = x + 5 if x ≤ −1, and 2x if x > −1. Find g(3).","answers":["6"],"hint":"3 > −1.","solution":"Use 2x: g(3) = 2 · 3 = 6."},{"id":"u3-pie1-q8","type":"input","prompt":"g(x) = x + 5 if x ≤ −1, and 2x if x > −1. Find g(−6).","answers":["-1"],"hint":"−6 ≤ −1.","solution":"Use x + 5: g(−6) = −6 + 5 = −1."}]},{"id":"piecewise-2","teach":[{"title":"Three pieces and the boundary","text":["Some functions have three or more pieces. Compare your x-value with each boundary in order. At a boundary, only the rule with ≤ or ≥ includes it.","The domain is every x-value covered by at least one piece. If the pieces together cover everything, the domain is all real numbers. If a boundary value is left out of every piece, exclude it."],"example":{"problem":"h(x) = −x if x < −2; 4 if −2 ≤ x ≤ 3; 2x − 2 if x > 3. Find h(−5).","steps":["−5 < −2, so use the first rule.","h(−5) = −(−5) = 5."]}}],"questions":[{"id":"u3-pie2-q1","type":"input","prompt":"h(x) = −x if x < −2; 4 if −2 ≤ x ≤ 3; 2x − 2 if x > 3. Find h(−7).","answers":["7"],"hint":"−7 < −2.","solution":"Use −x: h(−7) = −(−7) = 7."},{"id":"u3-pie2-q2","type":"input","prompt":"h(x) = −x if x < −2; 4 if −2 ≤ x ≤ 3; 2x − 2 if x > 3. Find h(1).","answers":["4"],"hint":"Which interval holds 1?","solution":"−2 ≤ 1 ≤ 3, so h(1) = 4."},{"id":"u3-pie2-q3","type":"input","prompt":"h(x) = −x if x < −2; 4 if −2 ≤ x ≤ 3; 2x − 2 if x > 3. Find h(3).","answers":["4"],"hint":"The middle rule includes 3.","solution":"3 is in the middle interval (it has ≤ 3). So h(3) = 4. The third rule would need x > 3."},{"id":"u3-pie2-q4","type":"input","prompt":"h(x) = −x if x < −2; 4 if −2 ≤ x ≤ 3; 2x − 2 if x > 3. Find h(5).","answers":["8"],"hint":"5 > 3.","solution":"Use 2x − 2: h(5) = 2 · 5 − 2 = 8."},{"id":"u3-pie2-q5","type":"choice","prompt":"h(x) = −x if x < −2; 4 if −2 ≤ x ≤ 3; 2x − 2 if x > 3. What happens to the graph at x = −2?","choices":["It has a closed dot at (−2, 2) and an open dot at (−2, 4)","It has a closed dot at (−2, 4) and an open dot at (−2, 2)","It has closed dots at both (−2, 2) and (−2, 4)","It has an open dot at (−2, 4) and no other dot"],"answer":1,"hint":"The first rule has x < −2, so −2 is excluded from it. The second rule includes −2.","solution":"The first rule gives −(−2) = 2 at the edge, but x < −2 excludes it: open dot at (−2, 2). The middle rule includes −2: closed dot at (−2, 4)."},{"id":"u3-pie2-q6","type":"choice","prompt":"What is the domain of h(x) = −x if x < −2; 4 if −2 ≤ x ≤ 3; 2x − 2 if x > 3?","choices":["All real numbers","x ≥ −2","x ≠ 3","−2 ≤ x ≤ 3"],"answer":0,"hint":"Do the three conditions leave any gaps?","solution":"x < −2, then −2 ≤ x ≤ 3, then x > 3 covers every number, so the domain is all real numbers."},{"id":"u3-pie2-q7","type":"choice","prompt":"k(x) = x + 1 if x < 0; x − 1 if x > 0. What is the domain of k?","choices":["All real numbers","x > 0","x < 0","All real numbers except 0"],"answer":3,"hint":"Which x-value is in neither condition?","solution":"x = 0 is not less than 0 and not greater than 0, so no rule covers it. The domain is all real numbers except 0."},{"id":"u3-pie2-q8","type":"input","prompt":"k(x) = x + 1 if x < 0; x − 1 if x > 0. Find k(−3) + k(3).","answers":["0"],"hint":"Find each value separately.","solution":"k(−3) = −3 + 1 = −2 and k(3) = 3 − 1 = 2. The sum is 0."}]},{"id":"piecewise-3","teach":[{"title":"Reading a piecewise graph","text":["A closed dot means the point is on the graph. An open dot means the point is not on the graph, but the graph gets close to it.","Where two pieces meet at the same x-value, a closed dot on one and an open dot on the other tells you which y-value counts there. If both pieces end at the same point, the graph is connected."],"example":{"problem":"The left piece ends at an open dot at (2, 1). The right piece starts with a closed dot at (2, 4). Find f(2).","steps":["The open dot at (2, 1) is not on the graph.","The closed dot at (2, 4) is on the graph.","f(2) = 4."]}}],"questions":[{"id":"u3-pie3-q1","type":"input","prompt":"A graph has a closed dot at (2, 5) and an open dot at (2, 1). What is f(2)?","answers":["5"],"hint":"Which dot is on the graph?","solution":"The closed dot is on the graph, so f(2) = 5. The open dot is not part of the graph."},{"id":"u3-pie3-q2","type":"choice","prompt":"f(x) = x² if x ≤ 1; 3 − x if x > 1. What happens at x = 1?","choices":["Closed dot at (1, 1) and open dot at (1, 2)","Open dot at (1, 1) and closed dot at (1, 2)","Closed dots at (1, 1) and (1, 2)","Open dots at (1, 1) and (1, 2)"],"answer":0,"hint":"Plug x = 1 into each rule. Then see which condition includes 1.","solution":"x² gives 1 at x = 1 and its condition is x ≤ 1, so closed dot at (1, 1). 3 − x gives 2 at x = 1 and its condition is x > 1, so open dot at (1, 2)."},{"id":"u3-pie3-q3","type":"input","prompt":"f(x) = x² if x ≤ 1; 3 − x if x > 1. Find f(1).","answers":["1"],"hint":"The closed dot is on the graph.","solution":"1 ≤ 1 is true, so use x²: f(1) = 1."},{"id":"u3-pie3-q4","type":"input","prompt":"f(x) = x² if x ≤ 1; 3 − x if x > 1. Find f(−3).","answers":["9"],"hint":"−3 ≤ 1.","solution":"Use x²: f(−3) = (−3)² = 9."},{"id":"u3-pie3-q5","type":"choice","prompt":"The left piece ends with an open dot at x = −3 and goes left. The right piece starts with a closed dot at x = −3 and goes right. What is the domain?","choices":["x ≠ −3","All real numbers","x > −3","x ≤ −3"],"answer":1,"hint":"Is x = −3 on the graph?","solution":"The closed dot at x = −3 is on the graph. Left of −3 and right of −3 are covered too. The domain is all real numbers."},{"id":"u3-pie3-q6","type":"choice","prompt":"The left piece ends with an open dot at x = 2. The right piece starts with an open dot at x = 2. What is the domain?","choices":["All real numbers except 2","All real numbers","x > 2","x ≠ 0"],"answer":0,"hint":"Is there a point on the graph at x = 2?","solution":"Both ends at x = 2 are open dots, so no point on the graph has x = 2. The domain is all real numbers except 2."},{"id":"u3-pie3-q7","type":"input","prompt":"For x ≤ 2, a piece is a line through (0, 1) and (2, 5). What is its y-value when x = −3?","answers":["-5"],"hint":"Slope = (5 − 1)/(2 − 0). The y-intercept is 1.","solution":"The slope is 4/2 = 2, so the line is y = 2x + 1. At x = −3: y = 2(−3) + 1 = −5."},{"id":"u3-pie3-q8","type":"choice","prompt":"A piece starts at x = 4 and goes right, with an open dot at x = 4. Which condition describes it?","choices":["x ≥ 4","x < 4","x ≤ 4","x > 4"],"answer":3,"hint":"Open dot means the endpoint is not included.","solution":"An open dot means 4 is not included, and the piece goes right. So the condition is x > 4."}]},{"id":"piecewise-4","teach":[{"title":"Absolute value and real situations","text":["An absolute value function is a piecewise function: |x| = −x if x < 0, and x if x ≥ 0. For |x − a|, change x to x − a.","Prices that change at a cutoff are piecewise too. Find the rule for the interval your input is in, then plug in."],"example":{"problem":"Write |x − 3| as a piecewise function.","steps":["If x − 3 ≥ 0 (x ≥ 3), |x − 3| = x − 3.","If x − 3 < 0 (x < 3), |x − 3| = −(x − 3).","f(x) = −(x − 3) if x < 3; x − 3 if x ≥ 3."]}}],"questions":[{"id":"u3-pie4-q1","type":"choice","prompt":"Which piecewise function equals |x − 3|?","choices":["−(x − 3) if x < 3; x − 3 if x ≥ 3","x − 3 if x < 3; −(x − 3) if x ≥ 3","−(x + 3) if x < −3; x + 3 if x ≥ −3","−x − 3 if x < 0; x − 3 if x ≥ 0"],"answer":0,"hint":"The expression inside is negative when x < 3.","solution":"When x < 3, x − 3 is negative, so |x − 3| = −(x − 3). When x ≥ 3 it is x − 3."},{"id":"u3-pie4-q2","type":"input","prompt":"Use |x − 3| = −(x − 3) for x < 3 and x − 3 for x ≥ 3. What is the value at x = −1?","answers":["4"],"hint":"−1 < 3.","solution":"−(−1 − 3) = −(−4) = 4."},{"id":"u3-pie4-q3","type":"input","prompt":"A garage charges $4 for up to 2 hours. After 2 hours the cost is c(t) = 3t − 2. How much does 5 hours cost?","answers":["13"],"hint":"5 hours is more than 2 hours.","solution":"Use 3t − 2: c(5) = 15 − 2 = 13. The cost is $13."},{"id":"u3-pie4-q4","type":"input","prompt":"The garage in the last question charges $4 for 0 < t ≤ 2. How much does 1.5 hours cost?","answers":["4"],"hint":"Which interval is 1.5 in?","solution":"1.5 ≤ 2, so the flat rate applies. The cost is $4."},{"id":"u3-pie4-q5","type":"input","prompt":"The garage cost for more than 2 hours is c(t) = 3t − 2. For how many hours is the cost $19?","answers":["7"],"hint":"Solve 3t − 2 = 19.","solution":"3t = 21, so t = 7. Check: 7 > 2, so the rule applies."},{"id":"u3-pie4-q6","type":"choice","prompt":"f(x) = x + 5 if x ≤ 1; 3x if x > 1. A student says f(1) = 3. What was the mistake?","choices":["Used x + 5, but f(1) = 3 is correct","Used 3x, but 1 is not greater than 1; f(1) = 6","Used x + 5 but forgot the 5; f(1) = 1","Nothing, since f(1) = 3x = 3"],"answer":1,"hint":"Which condition includes 1?","solution":"x ≤ 1 includes 1, so use x + 5: f(1) = 6. The rule 3x needs x > 1."},{"id":"u3-pie4-q7","type":"input","prompt":"f(x) = −2 if x < −1; x² if −1 ≤ x < 2; 7 if x ≥ 2. Find f(−5) + f(−1) + f(2).","answers":["6"],"hint":"Find each value with the right rule, then add.","solution":"f(−5) = −2. f(−1) = (−1)² = 1. f(2) = 7. Sum: −2 + 1 + 7 = 6."},{"id":"u3-pie4-q8","type":"input","prompt":"f(x) = 2x + 1 if x < 3; x + c if x ≥ 3. For what value of c do the pieces meet at x = 3, with no gap?","answers":["4"],"hint":"Find the first rule at x = 3. Make the second rule match.","solution":"First rule at x = 3: 2 · 3 + 1 = 7. Second rule: 3 + c. Set 3 + c = 7, so c = 4."}]}]}],"test":{"questions":[{"id":"u3-t-q1","type":"choice","prompt":"What is the domain of f(x) = √(x + 7)?","choices":["[−7, ∞)","(−7, ∞)","(−∞, −7]","[7, ∞)"],"answer":0,"hint":"The number under the root cannot be negative. Solve x + 7 ≥ 0.","solution":"x + 7 ≥ 0 gives x ≥ −7. The square root is defined at 0, so −7 is included: [−7, ∞)."},{"id":"u3-t-q2","type":"input","prompt":"Find the x-intercepts of y = 2x² − 18.","answers":["3, -3"],"hint":"Set y = 0 and solve for x².","solution":"2x² = 18, so x² = 9 and x = ±3."},{"id":"u3-t-q3","type":"choice","prompt":"On which interval is the graph of f decreasing?","choices":["(1, 3)","(−∞, 1)","(3, ∞)","(0, 4)"],"answer":0,"hint":"Decreasing means the graph goes down as you move right. Look between the high point and the low point.","solution":"The graph rises to a local maximum at x = 1, falls to a local minimum at x = 3, then rises. So f is decreasing on (1, 3).","graph":{"fn":"x^3-6x^2+9x","x":[-1,5],"y":[-2,6]}},{"id":"u3-t-q4","type":"choice","prompt":"What is the end behavior of f(x) = −2x³ + x?","choices":["As x → ∞, f(x) → ∞, and as x → −∞, f(x) → −∞","As x → ∞, f(x) → −∞, and as x → −∞, f(x) → ∞","As x → ∞, f(x) → ∞, and as x → −∞, f(x) → ∞","As x → ∞, f(x) → −∞, and as x → −∞, f(x) → −∞"],"answer":1,"hint":"The leading term decides. Odd degree with a negative leading coefficient.","solution":"The leading term is −2x³. For large positive x it is very negative. For large negative x it is very positive."},{"id":"u3-t-q5","type":"choice","prompt":"A table has x = −2, −1, 0, 1, 2 and y = 1/4, 1/2, 1, 2, 4. Which parent function fits?","choices":["Quadratic, y = x²","Reciprocal, y = 1/x","Exponential, y = 2ˣ","Absolute value, y = |x|"],"answer":2,"hint":"Each time x goes up by 1, what happens to y?","solution":"y doubles every time x increases by 1, and y = 1 at x = 0. That is y = 2ˣ."},{"id":"u3-t-q6","type":"choice","prompt":"Which parent function is shown?","choices":["Square root","Cubic","Reciprocal","Cube root"],"answer":3,"hint":"It passes through (−8, −2), (0, 0) and (8, 2), and it is steepest at the origin.","solution":"The curve is defined for negative x too and passes through (−8, −2), (0, 0), (8, 2). That is y = ∛x.","graph":{"fn":"root(3,x)","x":[-8,8],"y":[-4,4]}},{"id":"u3-t-q7","type":"choice","prompt":"Which parent function is odd (symmetric about the origin)?","choices":["y = x²","y = x³","y = |x|","y = √x"],"answer":1,"hint":"An odd function satisfies f(−x) = −f(x).","solution":"(−x)³ = −x³, so y = x³ is odd. x² and |x| are even. √x is not defined for negative x, so it is neither."},{"id":"u3-t-q8","type":"choice","prompt":"The point (−1, 4) is on f. Which point is on g(x) = f(x − 6) + 2?","choices":["(5, 6)","(−7, 6)","(5, 2)","(−7, 2)"],"answer":0,"hint":"Right 6 adds 6 to x. Up 2 adds 2 to y.","solution":"x: −1 + 6 = 5. y: 4 + 2 = 6. The image is (5, 6)."},{"id":"u3-t-q9","type":"input","prompt":"f(4) = 10. If g(x) = f(x + 3) − 7, what is g(1)?","answers":["3"],"hint":"Find which input of f you need: x + 3 when x = 1.","solution":"g(1) = f(1 + 3) − 7 = f(4) − 7 = 10 − 7 = 3."},{"id":"u3-t-q10","type":"input","prompt":"The point (−3, 5) is on f. The point (k, 5) is on g(x) = f(−x). What is k?","answers":["3"],"hint":"Reflecting over the y-axis changes the sign of the x-value.","solution":"g(3) = f(−3) = 5, so the point (3, 5) is on g. k = 3."},{"id":"u3-t-q11","type":"input","prompt":"f(x) = x² + 4x and g(x) = f(−x). What is g(3)?","answers":["-3"],"hint":"g(3) = f(−3).","solution":"f(−3) = (−3)² + 4(−3) = 9 − 12 = −3."},{"id":"u3-t-q12","type":"input","prompt":"The point (2, −3) is on f. The point (k, −3) is on g(x) = f(x/4). What is k?","answers":["8"],"hint":"x/4 means b = 1/4. Divide the x-value by 1/4.","solution":"2 ÷ (1/4) = 2 · 4 = 8."},{"id":"u3-t-q13","type":"input","prompt":"f(−2) = 0.4. If g(x) = −5f(x), what is g(−2)?","answers":["-2"],"hint":"Multiply the output by −5.","solution":"g(−2) = −5 · 0.4 = −2."},{"id":"u3-t-q14","type":"input","prompt":"The point (−2, 3) is on f. What is the y-coordinate of its image on g(x) = −2f(x − 1) + 5?","answers":["-1"],"hint":"Multiply the y-value by −2 first, then add 5.","solution":"y: −2 · 3 + 5 = −6 + 5 = −1. (The x-coordinate is −2 + 1 = −1.)"},{"id":"u3-t-q15","type":"input","prompt":"f(x) = x² and g(x) = 3f(x + 2) − 10. What is g(1)?","answers":["17"],"hint":"x + 2 = 3 when x = 1.","solution":"g(1) = 3f(3) − 10 = 3 · 9 − 10 = 17."},{"id":"u3-t-q16","type":"choice","prompt":"Which describes g(x) = ½f(x + 4) − 3?","choices":["Right 4, vertical compression by ½, down 3","Left 4, vertical stretch by 2, down 3","Left 4, horizontal compression by ½, down 3","Left 4, vertical compression by ½, down 3"],"answer":3,"hint":"Inside the parentheses, x + 4 moves left. The ½ is outside f.","solution":"x + 4 shifts left 4. The ½ multiplies outputs: vertical compression by ½. − 3 shifts down 3."},{"id":"u3-t-q17","type":"choice","prompt":"This graph starts at one point and heads down and right. It comes from f(x) = √x. Which is its equation?","choices":["y = −2√(x + 1) + 3","y = 2√(x + 1) + 3","y = −2√(x − 1) + 3","y = −√(x + 1) + 3"],"answer":0,"hint":"The start point is (−1, 3), and the graph goes down from there.","solution":"The start point (−1, 3) gives h = −1 and k = 3. At x = 3 the graph is at y = −1: a · 2 + 3 = −1, so a = −2.","graph":{"fn":"-2*sqrt(x+1)+3","x":[-3,7],"y":[-5,5]}},{"id":"u3-t-q18","type":"input","prompt":"A parabola with vertex (−2, −6) passes through (0, 2). Its equation is y = a(x + 2)² − 6. What is a?","answers":["2"],"hint":"Substitute x = 0 and y = 2.","solution":"2 = a(0 + 2)² − 6 = 4a − 6. So 4a = 8 and a = 2."},{"id":"u3-t-q19","type":"choice","prompt":"What is the vertex of y = −3|x − 8| + 1?","choices":["(−8, 1)","(8, −1)","(8, 1)","(−3, 1)"],"answer":2,"hint":"The vertex is (h, k) in y = a|x − h| + k.","solution":"x − 8 gives h = 8, and + 1 gives k = 1. The vertex is (8, 1)."},{"id":"u3-t-q20","type":"input","prompt":"Find the x-intercepts of y = ½|x − 5| − 3.","answers":["11, -1"],"hint":"Get |x − 5| alone: add 3, then multiply by 2.","solution":"½|x − 5| = 3, so |x − 5| = 6. Then x = 11 or x = −1."},{"id":"u3-t-q21","type":"input","prompt":"What is the slope of the left side of y = −4|x + 1| + 9?","answers":["4"],"hint":"The left side has slope −a.","solution":"a = −4, so the left side has slope −a = 4."},{"id":"u3-t-q22","type":"input","prompt":"f(x) = 3x − 5 if x < −1; x² + 2 if x ≥ −1. Find f(−1).","answers":["3"],"hint":"Which condition includes −1?","solution":"x ≥ −1 includes −1, so use x² + 2: f(−1) = 1 + 2 = 3."},{"id":"u3-t-q23","type":"input","prompt":"Shipping costs s(w) = 6 dollars if 0 < w ≤ 2, and s(w) = 6 + 1.5(w − 2) dollars if w > 2, where w is the weight in pounds. What does it cost to ship 6 pounds?","answers":["12"],"hint":"6 is more than 2, so use the second rule.","solution":"s(6) = 6 + 1.5(6 − 2) = 6 + 6 = 12. It costs $12."},{"id":"u3-t-q24","type":"choice","prompt":"p(x) = x² − 1 if x < 3; 2x + 5 if x > 3. What is the domain of p?","choices":["All real numbers","All real numbers except 3","x < 3","x ≠ 0"],"answer":1,"hint":"Is x = 3 in either condition?","solution":"x = 3 is neither less than 3 nor greater than 3, so no rule covers it. The domain is all real numbers except 3."}]}},{"format":1,"id":"unit-4-quadratics-complex-numbers","title":"Unit 4: Quadratic Equations and Complex Numbers","levels":[{"id":"vertex-form","title":"Quadratics in vertex form","lessons":[{"id":"vertex-form-1","teach":[{"title":"Reading vertex form","text":["Vertex form is y = a(x − h)² + k.","The vertex is (h, k). The axis of symmetry is the vertical line x = h.","If a > 0 the parabola opens up and the vertex is a minimum. If a < 0 it opens down and the vertex is a maximum."],"example":{"problem":"Describe y = −2(x − 3)² + 5","steps":["h = 3 and k = 5, so the vertex is (3, 5).","The axis is x = 3.","a = −2 < 0, so it opens down. The maximum value is 5."]}}],"questions":[{"id":"u4-vf1-q1","type":"choice","prompt":"What is the vertex of y = (x − 4)² + 7?","choices":["(−4, 7)","(4, 7)","(4, −7)","(7, 4)"],"answer":1,"hint":"In (x − h), the vertex uses h. Watch the sign.","solution":"The form is (x − h), so x − 4 gives h = 4. k = 7. Vertex: (4, 7)."},{"id":"u4-vf1-q2","type":"input","prompt":"The axis of symmetry of y = (x − 6)² − 2 is x = h. What is h?","answers":["6"],"hint":"The axis passes through the vertex.","solution":"x − 6 means h = 6. The axis is x = 6."},{"id":"u4-vf1-q3","type":"choice","prompt":"What is the vertex of y = −3(x + 2)² + 1?","choices":["(−2, 1)","(2, 1)","(−2, −1)","(−3, 1)"],"answer":0,"hint":"Write x + 2 as x − (−2).","solution":"x + 2 = x − (−2), so h = −2. k = 1. Vertex: (−2, 1)."},{"id":"u4-vf1-q4","type":"input","prompt":"What is the minimum value of y = 2(x − 5)² + 9?","answers":["9"],"hint":"a is positive, so the vertex is the lowest point. Its y-value is k.","solution":"a = 2 > 0, so the parabola opens up. The minimum is k = 9."},{"id":"u4-vf1-q5","type":"choice","prompt":"Which describes y = −½(x − 1)² + 4?","choices":["Opens up, has a maximum","Opens down, has a minimum","Opens up, has a minimum","Opens down, has a maximum"],"answer":3,"hint":"Look at the sign of a only.","solution":"a = −½ < 0. The parabola opens down, so the vertex is a maximum."},{"id":"u4-vf1-q6","type":"input","prompt":"The vertex of y = (x + 3)² − 8 has x-coordinate h. What is h?","answers":["-3"],"hint":"Write x + 3 as x − (−3).","solution":"x + 3 = x − (−3), so h = −3."},{"id":"u4-vf1-q7","type":"choice","prompt":"Which parabola has vertex (−1, 6) and opens up?","choices":["y = 2(x − 1)² + 6","y = −2(x + 1)² + 6","y = 2(x + 1)² + 6","y = 2(x + 1)² − 6"],"answer":2,"hint":"Check the sign of h, the sign of k, and the sign of a.","solution":"h = −1 gives (x + 1). k = 6 is added. Opening up needs a > 0. So y = 2(x + 1)² + 6."},{"id":"u4-vf1-q8","type":"input","prompt":"What is the maximum value of y = −4(x − 2)² + 11?","answers":["11"],"hint":"a is negative, so the vertex is the highest point.","solution":"a = −4 < 0, so it opens down. The maximum is k = 11."}]},{"id":"vertex-form-2","teach":[{"title":"Transformations of y = x²","text":["In y = a(x − h)² + k, h slides the graph right (positive h) or left (negative h). k slides it up or down.","If |a| > 1 the graph is narrower. If 0 < |a| < 1 it is wider. If a < 0 it is flipped upside down."],"example":{"problem":"Describe y = −½(x + 4)² − 3 compared to y = x²","steps":["x + 4 = x − (−4): shift left 4.","− 3: shift down 3.","a = −½: reflect over the x-axis, and the graph is wider because ½ < 1."]}}],"questions":[{"id":"u4-vf2-q1","type":"choice","prompt":"How does y = (x − 5)² compare to y = x²?","choices":["Shifted left 5","Shifted right 5","Shifted up 5","Shifted down 5"],"answer":1,"hint":"A number inside the parentheses moves the graph sideways.","solution":"x − 5 shifts the graph right 5 units."},{"id":"u4-vf2-q2","type":"choice","prompt":"How does y = x² − 6 compare to y = x²?","choices":["Shifted down 6","Shifted up 6","Shifted left 6","Shifted right 6"],"answer":0,"hint":"A number added outside moves the graph up or down.","solution":"− 6 moves every point down 6 units."},{"id":"u4-vf2-q3","type":"choice","prompt":"Which parabola is the narrowest?","choices":["y = 0.5x²","y = −x²","y = 0.25x²","y = 2x²"],"answer":3,"hint":"Compare the size of |a|. Bigger |a| is narrower.","solution":"|a| is 2, 0.5, 1, and 0.25. The largest is 2, so y = 2x² is narrowest."},{"id":"u4-vf2-q4","type":"choice","prompt":"Describe y = −(x + 2)² + 1 compared to y = x².","choices":["Flipped, right 2, up 1","Flipped, left 2, down 1","Flipped, left 2, up 1","Not flipped, left 2, up 1"],"answer":2,"hint":"a = −1 flips it. x + 2 and + 1 shift it.","solution":"a = −1: reflect over the x-axis. x + 2: left 2. + 1: up 1."},{"id":"u4-vf2-q5","type":"choice","prompt":"Which equation is y = x² shifted right 3 and up 4?","choices":["y = (x + 3)² + 4","y = (x − 3)² + 4","y = (x − 3)² − 4","y = (x − 4)² + 3"],"answer":1,"hint":"Right 3 goes inside as x − 3. Up 4 goes outside as + 4.","solution":"Right 3: (x − 3). Up 4: + 4. So y = (x − 3)² + 4."},{"id":"u4-vf2-q6","type":"input","prompt":"The parabola y = a(x − 1)² + 2 passes through (2, 5). What is a?","answers":["3"],"hint":"Substitute x = 2 and y = 5, then solve for a.","solution":"5 = a(2 − 1)² + 2 = a + 2, so a = 3."},{"id":"u4-vf2-q7","type":"input","prompt":"A parabola has vertex (3, −1) and passes through (5, 7). Its equation is y = a(x − 3)² − 1. What is a?","answers":["2"],"hint":"Put x = 5 and y = 7 into the equation.","solution":"7 = a(5 − 3)² − 1 = 4a − 1. So 4a = 8 and a = 2."},{"id":"u4-vf2-q8","type":"choice","prompt":"What is the vertex of the graph?","choices":["(2, 3)","(−2, 3)","(3, 2)","(2, −3)"],"answer":0,"hint":"Read the x-coordinate of the top point first.","solution":"The highest point is at x = 2 and y = 3. Vertex: (2, 3).","graph":{"fn":"-(x-2)^2+3","x":[-4,8],"y":[-5,5],"numbers":true}}]},{"id":"vertex-form-3","teach":[{"title":"Writing an equation from a graph","text":["Read the vertex (h, k) off the graph and put it in y = a(x − h)² + k.","Then pick one other point on the graph, substitute it, and solve for a."],"example":{"problem":"A parabola has vertex (1, −2) and passes through (3, 2). Write its equation.","steps":["y = a(x − 1)² − 2.","Substitute (3, 2): 2 = a(3 − 1)² − 2 = 4a − 2.","4a = 4, so a = 1.","y = (x − 1)² − 2"]}}],"questions":[{"id":"u4-vf3-q1","type":"choice","prompt":"Read the graph. What is its vertex?","choices":["(2, −3)","(−2, 3)","(−3, −2)","(−2, −3)"],"answer":3,"hint":"The graph opens up, so the vertex is the lowest point.","solution":"The lowest point is at x = −2, y = −3. Vertex: (−2, −3).","graph":{"fn":"(x+2)^2-3","x":[-6,2],"y":[-5,5],"numbers":true}},{"id":"u4-vf3-q2","type":"input","prompt":"The graph shows a parabola. Its axis of symmetry is x = h. What is h?","answers":["1"],"hint":"The axis goes straight through the vertex.","solution":"The vertex is (1, 4), so the axis is x = 1.","graph":{"fn":"-(x-1)^2+4","x":[-4,6],"y":[-4,6],"numbers":true}},{"id":"u4-vf3-q3","type":"input","prompt":"What is the maximum value of the graphed function?","answers":["5"],"hint":"The maximum is the y-value of the top point.","solution":"The top point is (3, 5). The maximum value is 5.","graph":{"fn":"-2*(x-3)^2+5","x":[0,6],"y":[-3,7],"numbers":true}},{"id":"u4-vf3-q4","type":"choice","prompt":"Which equation matches the graph? Check the point (3, −2).","choices":["y = ½(x + 1)² − 4","y = 2(x − 1)² − 4","y = ½(x − 1)² − 4","y = ½(x − 1)² + 4"],"answer":2,"hint":"The vertex is (1, −4). Then test the point (3, −2) in each choice.","solution":"Vertex (1, −4) gives (x − 1)² − 4. At x = 3: a(2)² − 4 = −2, so 4a = 2 and a = ½. y = ½(x − 1)² − 4.","graph":{"fn":"0.5*(x-1)^2-4","x":[-5,7],"y":[-6,6],"numbers":true}},{"id":"u4-vf3-q5","type":"input","prompt":"A parabola has vertex (−1, −3) and passes through (1, 5). Its equation is y = a(x + 1)² − 3. What is a?","answers":["2"],"hint":"Substitute x = 1 and y = 5.","solution":"5 = a(1 + 1)² − 3 = 4a − 3. So 4a = 8 and a = 2."},{"id":"u4-vf3-q6","type":"choice","prompt":"Which equation has vertex (4, −1) and passes through (6, −5)?","choices":["y = (x − 4)² − 1","y = −(x − 4)² − 1","y = −(x + 4)² − 1","y = −(x − 4)² + 1"],"answer":1,"hint":"Find a from the point: substitute x = 6, y = −5 into y = a(x − 4)² − 1.","solution":"−5 = a(2)² − 1 = 4a − 1. So 4a = −4 and a = −1. y = −(x − 4)² − 1."},{"id":"u4-vf3-q7","type":"input","prompt":"What is the y-intercept of y = −(x + 3)² + 8?","answers":["-1"],"hint":"The y-intercept is the value of y when x = 0.","solution":"y = −(0 + 3)² + 8 = −9 + 8 = −1."},{"id":"u4-vf3-q8","type":"input","prompt":"What is the y-intercept of y = 2(x − 1)² − 5?","answers":["-3"],"hint":"Put x = 0 into the equation.","solution":"y = 2(0 − 1)² − 5 = 2 − 5 = −3."}]},{"id":"vertex-form-4","teach":[{"title":"Putting it together","text":["Vertex form gives the vertex, axis, direction, and max or min at a glance.","To find x-intercepts, set y = 0, isolate (x − h)², and take square roots."],"example":{"problem":"Find the x-intercepts of y = −2(x − 3)² + 8","steps":["Set y = 0: −2(x − 3)² + 8 = 0.","(x − 3)² = 4, so x − 3 = ±2.","x = 5 or x = 1."]}}],"questions":[{"id":"u4-vf4-q1","type":"choice","prompt":"Which statement is true about y = 3(x − 2)² − 7?","choices":["Opens up, minimum value −7 at x = 2","Opens up, minimum value 2 at x = −7","Opens down, maximum value −7 at x = 2","Opens up, minimum value −7 at x = −2"],"answer":0,"hint":"Find the vertex, then look at the sign of a.","solution":"Vertex (2, −7). a = 3 > 0, so it opens up and the minimum is −7 at x = 2."},{"id":"u4-vf4-q2","type":"input","prompt":"What is the minimum value of y = 5(x + 4)² + 13?","answers":["13"],"hint":"The minimum is the y-value of the vertex.","solution":"The vertex is (−4, 13) and a > 0. The minimum value is 13."},{"id":"u4-vf4-q3","type":"input","prompt":"The function y = −(x − 3)² + k has a maximum value of 6. What is k?","answers":["6"],"hint":"The maximum of this form is k.","solution":"The vertex is (3, k) and the maximum is k. So k = 6."},{"id":"u4-vf4-q4","type":"choice","prompt":"Which function has the greatest maximum value?","choices":["y = −(x − 1)² + 3","y = −½(x − 7)² + 4","y = (x − 2)² + 9","y = −2(x + 4)² + 5"],"answer":3,"hint":"Only parabolas that open down have a maximum. Compare their k values.","solution":"The last one opens up, so it has no maximum. The maxima of the others are 3, 5, and 4. The greatest is 5."},{"id":"u4-vf4-q5","type":"input","prompt":"A parabola has vertex (2, 3) and passes through (4, −5). Its equation is y = a(x − 2)² + 3. What is a?","answers":["-2"],"hint":"Substitute x = 4 and y = −5.","solution":"−5 = a(2)² + 3 = 4a + 3. So 4a = −8 and a = −2."},{"id":"u4-vf4-q6","type":"input","prompt":"Find the x-intercepts of y = −2(x − 3)² + 8. Give both values.","answers":["1, 5"],"hint":"Set y = 0 and isolate (x − 3)² first.","solution":"−2(x − 3)² + 8 = 0, so (x − 3)² = 4. Then x − 3 = ±2, so x = 1 or x = 5.","calculator":false},{"id":"u4-vf4-q7","type":"input","prompt":"y = 3(x − 2)² + k passes through (4, 10). What is k?","answers":["-2"],"hint":"Substitute x = 4 and y = 10.","solution":"10 = 3(4 − 2)² + k = 12 + k. So k = −2."},{"id":"u4-vf4-q8","type":"choice","prompt":"Which equation has vertex (−2, 5) and opens down?","choices":["y = −3(x − 2)² + 5","y = 3(x + 2)² + 5","y = −3(x + 2)² + 5","y = −3(x + 2)² − 5"],"answer":2,"hint":"Opens down means a < 0. Then fix the signs for h and k.","solution":"h = −2 gives (x + 2). k = 5. Opening down needs a < 0. So y = −3(x + 2)² + 5."}]}]},{"id":"standard-form","title":"Quadratics in standard form","lessons":[{"id":"standard-form-1","teach":[{"title":"Axis and vertex from standard form","text":["Standard form is y = ax² + bx + c. The y-intercept is c.","The axis of symmetry is x = −b / (2a).","The vertex is on the axis. Put the axis value into the equation to find its y-coordinate."],"example":{"problem":"Find the vertex of y = 2x² − 8x + 3","steps":["a = 2, b = −8. Axis: x = 8 / 4 = 2.","y = 2(2)² − 8(2) + 3 = 8 − 16 + 3 = −5.","Vertex: (2, −5)."]}}],"questions":[{"id":"u4-sf1-q1","type":"input","prompt":"The axis of symmetry of y = x² + 6x + 1 is x = ? Type the number.","answers":["-3"],"hint":"Use −b / (2a) with a = 1 and b = 6.","solution":"x = −6 / (2 · 1) = −3."},{"id":"u4-sf1-q2","type":"input","prompt":"The axis of symmetry of y = x² − 10x + 4 is x = ? Type the number.","answers":["5"],"hint":"b is −10. Use −b / (2a).","solution":"x = −(−10) / (2 · 1) = 5."},{"id":"u4-sf1-q3","type":"input","prompt":"The axis of symmetry of y = 2x² + 8x − 1 is x = ? Type the number.","answers":["-2"],"hint":"a = 2, so the denominator is 4.","solution":"x = −8 / (2 · 2) = −8 / 4 = −2."},{"id":"u4-sf1-q4","type":"choice","prompt":"What is the axis of symmetry of y = −x² + 4x + 3?","choices":["x = −2","x = 2","x = 4","x = −4"],"answer":1,"hint":"a is negative here. Keep the signs when you use −b / (2a).","solution":"a = −1, b = 4. x = −4 / (2 · (−1)) = −4 / −2 = 2."},{"id":"u4-sf1-q5","type":"input","prompt":"The vertex of y = 3x² − 12x + 5 is (2, k). What is k?","answers":["-7"],"hint":"Substitute x = 2 into the equation.","solution":"y = 3(4) − 12(2) + 5 = 12 − 24 + 5 = −7."},{"id":"u4-sf1-q6","type":"choice","prompt":"What is the vertex of y = x² − 4x + 1?","choices":["(2, −3)","(−2, −3)","(2, 3)","(4, 1)"],"answer":0,"hint":"Find the axis first, then the y-value.","solution":"Axis: x = 4 / 2 = 2. y = 4 − 8 + 1 = −3. Vertex: (2, −3)."},{"id":"u4-sf1-q7","type":"input","prompt":"What is the y-intercept of y = x² + 2x − 8? Type the y-value.","answers":["-8"],"hint":"The y-intercept is c.","solution":"At x = 0, y = c = −8."},{"id":"u4-sf1-q8","type":"choice","prompt":"What is the y-intercept (as a point) of y = −2x² + 5x + 9?","choices":["(9, 0)","(0, 5)","(0, −2)","(0, 9)"],"answer":3,"hint":"Put x = 0 in. Only c is left.","solution":"At x = 0, y = 9. The point is (0, 9)."}]},{"id":"standard-form-2","teach":[{"title":"Maximum, minimum, domain, and range","text":["If a > 0 the vertex is the minimum. If a < 0 it is the maximum.","The domain of every quadratic is all real numbers.","The range depends on the vertex y-value k: y ≥ k if it opens up, y ≤ k if it opens down."],"example":{"problem":"Find the range of y = −x² + 6x − 5","steps":["Axis: x = −6 / (2 · −1) = 3.","y = −9 + 18 − 5 = 4. The vertex is (3, 4).","a < 0, so it opens down: range y ≤ 4."]}}],"questions":[{"id":"u4-sf2-q1","type":"choice","prompt":"Does y = −3x² + 6x + 1 have a maximum or a minimum?","choices":["Minimum, because a < 0","Maximum, because b > 0","Maximum, because a < 0","Minimum, because c > 0"],"answer":2,"hint":"Only the sign of a decides the direction.","solution":"a = −3 < 0, so it opens down and the vertex is a maximum."},{"id":"u4-sf2-q2","type":"input","prompt":"What is the minimum value of y = x² − 6x + 11?","answers":["2"],"hint":"Axis first: x = −b / (2a). Then find y there.","solution":"Axis x = 3. y = 9 − 18 + 11 = 2. Minimum value: 2."},{"id":"u4-sf2-q3","type":"input","prompt":"What is the maximum value of y = −x² + 8x − 3?","answers":["13"],"hint":"Axis first: x = −b / (2a).","solution":"Axis x = −8 / (−2) = 4. y = −16 + 32 − 3 = 13."},{"id":"u4-sf2-q4","type":"choice","prompt":"What is the domain of y = 2x² + 3x − 5?","choices":["y ≥ 0","All real numbers","x ≥ 0","x ≥ −5"],"answer":1,"hint":"Can you put any x into a quadratic?","solution":"You can substitute any real number for x. The domain is all real numbers."},{"id":"u4-sf2-q5","type":"choice","prompt":"What is the range of y = x² − 4x + 7?","choices":["y ≥ 3","y ≤ 3","y ≥ 2","y ≥ 7"],"answer":0,"hint":"Find the vertex y-value. Then check which way it opens.","solution":"Axis x = 2. y = 4 − 8 + 7 = 3. a > 0, so the range is y ≥ 3."},{"id":"u4-sf2-q6","type":"choice","prompt":"What is the range of y = −2x² + 12x − 5?","choices":["y ≥ 13","y ≤ 3","y ≤ −5","y ≤ 13"],"answer":3,"hint":"Axis is x = −12 / (2 · −2).","solution":"Axis x = 3. y = −18 + 36 − 5 = 13. a < 0, so the range is y ≤ 13."},{"id":"u4-sf2-q7","type":"input","prompt":"What is the minimum value of y = 2x² − 12x + 20?","answers":["2"],"hint":"Axis: x = 12 / 4.","solution":"Axis x = 3. y = 18 − 36 + 20 = 2."},{"id":"u4-sf2-q8","type":"input","prompt":"What is the maximum value of y = −x² − 6x − 2?","answers":["7"],"hint":"Axis: x = −(−6) / (2 · −1).","solution":"Axis x = 6 / (−2) = −3. y = −9 + 18 − 2 = 7."}]},{"id":"standard-form-3","teach":[{"title":"Working backward","text":["The axis formula is an equation. If you know the axis, you can solve for a missing a or b.","Parabolas are symmetric: two points with the same y-value are the same distance from the axis."],"example":{"problem":"y = x² + bx + 1 has axis x = 3. Find b.","steps":["−b / (2 · 1) = 3.","−b = 6, so b = −6."]}}],"questions":[{"id":"u4-sf3-q1","type":"input","prompt":"y = x² + bx + 5 has axis x = 2. What is b?","answers":["-4"],"hint":"Set −b / 2 equal to 2.","solution":"−b / 2 = 2, so −b = 4 and b = −4."},{"id":"u4-sf3-q2","type":"input","prompt":"y = 2x² + bx − 3 has axis x = 3. What is b?","answers":["-12"],"hint":"Set −b / 4 equal to 3.","solution":"−b / 4 = 3, so −b = 12 and b = −12."},{"id":"u4-sf3-q3","type":"input","prompt":"y = −x² + bx has axis x = 5. What is b?","answers":["10"],"hint":"a is −1, so 2a = −2.","solution":"−b / (−2) = 5, so b / 2 = 5 and b = 10."},{"id":"u4-sf3-q4","type":"input","prompt":"y = ax² − 12x + 1 has axis x = 3. What is a?","answers":["2"],"hint":"Put b = −12 into −b / (2a) = 3.","solution":"12 / (2a) = 3, so 2a = 4 and a = 2."},{"id":"u4-sf3-q5","type":"choice","prompt":"Which parabola has axis of symmetry x = 1?","choices":["y = x² + 2x + 5","y = 2x² − 2x","y = x² − 2x + 5","y = x² − x + 1"],"answer":2,"hint":"Compute −b / (2a) for each choice.","solution":"The axes are 1, −1, ½, and ½. Only y = x² − 2x + 5 has x = 1."},{"id":"u4-sf3-q6","type":"input","prompt":"y = x² − 8x + c has a minimum value of 3. What is c?","answers":["19"],"hint":"The minimum is at the axis x = 4.","solution":"At x = 4: 16 − 32 + c = 3, so c = 19."},{"id":"u4-sf3-q7","type":"choice","prompt":"What is the vertex of y = −2x² + 4x + 1?","choices":["(−1, −5)","(1, 3)","(1, −1)","(2, 1)"],"answer":1,"hint":"Axis first, then substitute.","solution":"Axis x = −4 / (−4) = 1. y = −2 + 4 + 1 = 3. Vertex: (1, 3)."},{"id":"u4-sf3-q8","type":"input","prompt":"y = x² − 6x + 4 has y-intercept (0, 4). Another point with y = 4 is (n, 4). What is n?","answers":["6"],"hint":"The axis is x = 3. The point (0, 4) is 3 units from it.","solution":"Axis x = 3. (0, 4) is 3 left of the axis, so the mirror point is 3 right: x = 6."}]},{"id":"standard-form-4","teach":[{"title":"Full problems","text":["Use the axis to find the vertex. Then compare vertices to compare parabolas.","To find x-intercepts, set y = 0 and solve."],"example":{"problem":"Find the minimum value of y = x² + 4x + 9","steps":["Axis x = −4 / 2 = −2.","y = 4 − 8 + 9 = 5.","The minimum value is 5."]}}],"questions":[{"id":"u4-sf4-q1","type":"choice","prompt":"Which statement is true about y = 3x² − 6x + 2?","choices":["Vertex (1, −1), minimum value −1","Vertex (−1, −1), minimum value −1","Vertex (1, −1), maximum value −1","Vertex (1, 2), minimum value 2"],"answer":0,"hint":"Axis, then y-value, then the sign of a.","solution":"Axis x = 6 / 6 = 1. y = 3 − 6 + 2 = −1. a > 0, so it is a minimum."},{"id":"u4-sf4-q2","type":"input","prompt":"What is the minimum value of y = ½x² − 2x + 5?","answers":["3"],"hint":"Axis is x = 2 / (2 · ½).","solution":"Axis x = 2. y = ½(4) − 4 + 5 = 2 − 4 + 5 = 3."},{"id":"u4-sf4-q3","type":"choice","prompt":"What is the range of y = −x² + 2x + 8?","choices":["y ≥ 9","y ≤ 8","y ≤ 1","y ≤ 9"],"answer":3,"hint":"It opens down. Find the vertex y-value.","solution":"Axis x = 1. y = −1 + 2 + 8 = 9. It opens down, so y ≤ 9."},{"id":"u4-sf4-q4","type":"input","prompt":"y = x² + 4x + k has a minimum value of −1. What is k?","answers":["3"],"hint":"The minimum occurs at x = −2.","solution":"At x = −2: 4 − 8 + k = −1, so k = 3."},{"id":"u4-sf4-q5","type":"input","prompt":"y = −3x² + bx + 2 has axis x = 2. What is b?","answers":["12"],"hint":"Use −b / (2a) with a = −3.","solution":"−b / (−6) = 2, so b / 6 = 2 and b = 12."},{"id":"u4-sf4-q6","type":"choice","prompt":"Which function has the lowest minimum value?","choices":["y = x² − 2x + 3","y = 2x² − 8x + 10","y = x² + 4x + 5","y = x² − 6x + 12"],"answer":2,"hint":"Find the vertex y-value of each.","solution":"The minima are 2, 2, 1, and 3. The lowest is 1, from y = x² + 4x + 5."},{"id":"u4-sf4-q7","type":"input","prompt":"Find the x-intercepts of y = x² − 6x + 5. Give both values.","answers":["1, 5"],"hint":"Set y = 0 and factor.","solution":"x² − 6x + 5 = (x − 1)(x − 5) = 0, so x = 1 or x = 5."},{"id":"u4-sf4-q8","type":"input","prompt":"What is the minimum value of y = 2x² − 8x + 6?","answers":["-2"],"hint":"Axis is x = 8 / 4.","solution":"Axis x = 2. y = 8 − 16 + 6 = −2."}]}]},{"id":"factoring","title":"Factoring quadratics","lessons":[{"id":"factoring-1","teach":[{"title":"GCF and trinomials with a = 1","text":["Always pull out the greatest common factor first.","To factor x² + bx + c, find two numbers that multiply to c and add to b. Then write (x + m)(x + n)."],"example":{"problem":"Factor x² + 7x + 12","steps":["Two numbers that multiply to 12 and add to 7: 3 and 4.","(x + 3)(x + 4)","Check: x² + 4x + 3x + 12 = x² + 7x + 12."]}},{"title":"GCF example","text":["The GCF is the biggest number and the highest power of x that divides every term."],"example":{"problem":"Factor 6x² + 9x","steps":["GCF of 6 and 9 is 3. Both terms have x.","GCF = 3x.","6x² + 9x = 3x(2x + 3)"]}}],"questions":[{"id":"u4-fa1-q1","type":"choice","prompt":"Factor 8x² + 12x.","choices":["4(2x² + 3x)","4x(2x + 3)","2x(4x + 6)","4x(2x + 12)"],"answer":1,"hint":"Find the GCF of both the numbers and the x parts. Take out all of it.","solution":"GCF of 8 and 12 is 4, and both have x, so the GCF is 4x. 8x² / 4x = 2x and 12x / 4x = 3. Answer: 4x(2x + 3)."},{"id":"u4-fa1-q2","type":"input","prompt":"x² + 7x + 12 = (x + m)(x + n). Type m and n.","answers":["3, 4"],"hint":"Find two numbers that multiply to 12 and add to 7.","solution":"3 · 4 = 12 and 3 + 4 = 7. So m and n are 3 and 4.","calculator":false},{"id":"u4-fa1-q3","type":"choice","prompt":"Factor x² + 9x + 20.","choices":["(x + 4)(x + 5)","(x + 2)(x + 10)","(x − 4)(x − 5)","(x + 3)(x + 6)"],"answer":0,"hint":"Which pair multiplies to 20 and adds to 9?","solution":"4 · 5 = 20 and 4 + 5 = 9. So (x + 4)(x + 5)."},{"id":"u4-fa1-q4","type":"choice","prompt":"Factor x² − 5x + 6.","choices":["(x + 2)(x + 3)","(x − 1)(x − 6)","(x − 2)(x + 3)","(x − 2)(x − 3)"],"answer":3,"hint":"The middle term is negative and the last term is positive, so both numbers are negative.","solution":"(−2)(−3) = 6 and −2 + −3 = −5. So (x − 2)(x − 3)."},{"id":"u4-fa1-q5","type":"choice","prompt":"Factor x² + 2x − 15.","choices":["(x − 5)(x + 3)","(x + 5)(x + 3)","(x + 5)(x − 3)","(x + 15)(x − 1)"],"answer":2,"hint":"The last term is negative, so one number is positive and one is negative. The bigger one is positive.","solution":"5 · (−3) = −15 and 5 + (−3) = 2. So (x + 5)(x − 3)."},{"id":"u4-fa1-q6","type":"input","prompt":"x² − x − 12 = (x + m)(x + n). Type m and n (they can be negative).","answers":["3, -4"],"hint":"Multiply to −12, add to −1.","solution":"3 · (−4) = −12 and 3 + (−4) = −1. So m and n are 3 and −4."},{"id":"u4-fa1-q7","type":"choice","prompt":"Factor x² − 10x + 16.","choices":["(x + 2)(x + 8)","(x − 2)(x − 8)","(x − 4)(x − 4)","(x − 1)(x − 16)"],"answer":1,"hint":"Both numbers are negative. List the pairs that multiply to 16.","solution":"(−2)(−8) = 16 and −2 + −8 = −10. So (x − 2)(x − 8)."},{"id":"u4-fa1-q8","type":"choice","prompt":"Factor 5x³ − 15x².","choices":["5x²(x − 3)","5x(x − 3)","5x²(x + 3)","5(x³ − 3x²)"],"answer":0,"hint":"Both terms share x², not just x.","solution":"GCF = 5x². 5x³ / 5x² = x and −15x² / 5x² = −3. Answer: 5x²(x − 3)."}]},{"id":"factoring-2","teach":[{"title":"Trinomials with a ≠ 1","text":["Multiply a · c. Find two numbers that multiply to ac and add to b.","Use them to split the middle term, then factor by grouping."],"example":{"problem":"Factor 2x² + 7x + 3","steps":["a · c = 6. Numbers that multiply to 6 and add to 7: 1 and 6.","Split: 2x² + x + 6x + 3.","Group: x(2x + 1) + 3(2x + 1).","(2x + 1)(x + 3)"]}}],"questions":[{"id":"u4-fa2-q1","type":"choice","prompt":"Factor 2x² + 5x + 2.","choices":["(2x − 1)(x − 2)","(2x + 2)(x + 1)","(x + 1)(2x + 4)","(2x + 1)(x + 2)"],"answer":3,"hint":"ac = 4. Which two numbers multiply to 4 and add to 5?","solution":"ac = 4, and 1 + 4 = 5. Split: 2x² + x + 4x + 2 = x(2x + 1) + 2(2x + 1) = (2x + 1)(x + 2)."},{"id":"u4-fa2-q2","type":"input","prompt":"To factor 3x² + 10x + 8, find two numbers that multiply to ac = 24 and add to 10. Type both.","answers":["4, 6"],"hint":"List the pairs that multiply to 24.","solution":"4 · 6 = 24 and 4 + 6 = 10. The numbers are 4 and 6.","calculator":false},{"id":"u4-fa2-q3","type":"choice","prompt":"Factor 3x² + 11x + 6.","choices":["(3x + 3)(x + 2)","(3x + 6)(x + 1)","(3x + 2)(x + 3)","(3x + 1)(x + 6)"],"answer":2,"hint":"ac = 18. Which pair multiplies to 18 and adds to 11?","solution":"2 · 9 = 18 and 2 + 9 = 11. 3x² + 2x + 9x + 6 = x(3x + 2) + 3(3x + 2) = (3x + 2)(x + 3)."},{"id":"u4-fa2-q4","type":"choice","prompt":"Factor 2x² − 7x + 3.","choices":["(2x + 1)(x + 3)","(2x − 1)(x − 3)","(2x − 3)(x − 1)","(2x − 1)(x + 3)"],"answer":1,"hint":"Middle term negative, last term positive: both signs are negative.","solution":"ac = 6. −1 and −6 add to −7. 2x² − x − 6x + 3 = x(2x − 1) − 3(2x − 1) = (2x − 1)(x − 3)."},{"id":"u4-fa2-q5","type":"choice","prompt":"Factor 4x² + 4x − 3.","choices":["(2x − 1)(2x + 3)","(2x + 1)(2x − 3)","(4x − 1)(x + 3)","(4x + 3)(x − 1)"],"answer":0,"hint":"ac = −12. Find two numbers that multiply to −12 and add to 4.","solution":"−2 · 6 = −12 and −2 + 6 = 4. 4x² − 2x + 6x − 3 = 2x(2x − 1) + 3(2x − 1) = (2x − 1)(2x + 3)."},{"id":"u4-fa2-q6","type":"choice","prompt":"Factor 6x² − x − 2.","choices":["(3x + 2)(2x − 1)","(6x − 1)(x + 2)","(3x − 1)(2x + 2)","(3x − 2)(2x + 1)"],"answer":3,"hint":"ac = −12. Find two numbers that multiply to −12 and add to −1.","solution":"−4 · 3 = −12 and −4 + 3 = −1. 6x² − 4x + 3x − 2 = 2x(3x − 2) + 1(3x − 2) = (3x − 2)(2x + 1)."},{"id":"u4-fa2-q7","type":"input","prompt":"To factor 5x² + 13x + 6, find two numbers that multiply to ac = 30 and add to 13. Type both.","answers":["3, 10"],"hint":"List the pairs that multiply to 30.","solution":"3 · 10 = 30 and 3 + 10 = 13. (Then 5x² + 3x + 10x + 6 = (5x + 3)(x + 2).)","calculator":false},{"id":"u4-fa2-q8","type":"choice","prompt":"Factor completely: 12x² + 10x − 12.","choices":["(3x − 2)(2x + 3)","2(3x + 2)(2x − 3)","2(3x − 2)(2x + 3)","2(6x − 2)(x + 3)"],"answer":2,"hint":"Take out the GCF of 2 first. Then factor 6x² + 5x − 6.","solution":"12x² + 10x − 12 = 2(6x² + 5x − 6). For 6x² + 5x − 6, ac = −36 and 9 + (−4) = 5. So 6x² + 9x − 4x − 6 = 3x(2x + 3) − 2(2x + 3) = (3x − 2)(2x + 3). Answer: 2(3x − 2)(2x + 3)."}]},{"id":"factoring-3","teach":[{"title":"Special patterns","text":["Difference of squares: a² − b² = (a − b)(a + b). A sum of squares like x² + 9 does not factor.","Perfect square trinomials: a² + 2ab + b² = (a + b)² and a² − 2ab + b² = (a − b)²."],"example":{"problem":"Factor 9x² − 16","steps":["9x² = (3x)² and 16 = 4².","It is a difference of squares.","(3x − 4)(3x + 4)"]}}],"questions":[{"id":"u4-fa3-q1","type":"choice","prompt":"Factor x² − 49.","choices":["(x − 7)²","(x − 7)(x + 7)","(x + 7)²","(x − 49)(x + 1)"],"answer":1,"hint":"Difference of squares: 49 = 7².","solution":"x² − 49 = x² − 7² = (x − 7)(x + 7)."},{"id":"u4-fa3-q2","type":"choice","prompt":"Factor 9x² − 16.","choices":["(3x − 4)(3x + 4)","(3x − 4)²","(9x − 4)(9x + 4)","(9x − 16)(x + 1)"],"answer":0,"hint":"Take the square root of each term first.","solution":"9x² = (3x)² and 16 = 4². So (3x − 4)(3x + 4)."},{"id":"u4-fa3-q3","type":"choice","prompt":"Factor x² + 10x + 25.","choices":["(x + 5)(x − 5)","(x + 25)(x + 1)","(x − 5)²","(x + 5)²"],"answer":3,"hint":"Is the first term a square, the last term a square, and the middle twice their product?","solution":"x² = x², 25 = 5², and 2 · x · 5 = 10x. So (x + 5)²."},{"id":"u4-fa3-q4","type":"choice","prompt":"Factor x² − 12x + 36.","choices":["(x + 6)²","(x − 6)(x + 6)","(x − 6)²","(x − 12)(x − 3)"],"answer":2,"hint":"The middle term is negative.","solution":"36 = 6² and 2 · 6 = 12. With the − sign: (x − 6)²."},{"id":"u4-fa3-q5","type":"choice","prompt":"Factor 4x² + 12x + 9.","choices":["(2x + 9)(2x + 1)","(2x + 3)²","(4x + 3)(x + 3)","(2x − 3)²"],"answer":1,"hint":"Is the middle term 2 · 2x · 3?","solution":"4x² = (2x)², 9 = 3², and 2 · 2x · 3 = 12x. So (2x + 3)²."},{"id":"u4-fa3-q6","type":"input","prompt":"x² + kx + 49 is a perfect square trinomial, and k is positive. What is k?","answers":["14"],"hint":"The middle term is 2 times the square roots of the first and last terms.","solution":"49 = 7², so k = 2 · 7 = 14. Then x² + 14x + 49 = (x + 7)²."},{"id":"u4-fa3-q7","type":"choice","prompt":"Factor x² + 36.","choices":["It does not factor (prime)","(x + 6)(x − 6)","(x + 6)²","(x − 6)²"],"answer":0,"hint":"Is it a difference or a sum of squares? Multiply your guesses to check.","solution":"A sum of squares does not factor over the real numbers. (x + 6)(x − 6) = x² − 36, which is not it."},{"id":"u4-fa3-q8","type":"choice","prompt":"Factor 2x² − 50.","choices":["2(x − 5)²","(2x − 5)(x + 10)","2(x² − 25)","2(x − 5)(x + 5)"],"answer":3,"hint":"Take out the GCF first. What is left?","solution":"GCF = 2: 2(x² − 25). Then x² − 25 = (x − 5)(x + 5). Answer: 2(x − 5)(x + 5)."}]},{"id":"factoring-4","teach":[{"title":"Choosing a method","text":["Order of steps: GCF first. Then count terms. Two terms: difference of squares? Three terms: trinomial.","Check by multiplying back. Keep factoring until no factor can be broken down more."],"example":{"problem":"Factor x⁴ − 16","steps":["x⁴ = (x²)² and 16 = 4².","x⁴ − 16 = (x² − 4)(x² + 4).","x² − 4 factors again: (x − 2)(x + 2).","(x − 2)(x + 2)(x² + 4)"]}}],"questions":[{"id":"u4-fa4-q1","type":"choice","prompt":"Factor 3x² − 27.","choices":["3(x − 3)²","(3x − 9)(x + 3)","3(x − 3)(x + 3)","3(x² − 9)"],"answer":2,"hint":"GCF first, then a difference of squares.","solution":"3x² − 27 = 3(x² − 9) = 3(x − 3)(x + 3)."},{"id":"u4-fa4-q2","type":"choice","prompt":"Factor completely: x⁴ − 16.","choices":["(x² − 4)(x² + 4)","(x − 2)(x + 2)(x² + 4)","(x − 2)⁴","(x² + 4)²"],"answer":1,"hint":"After the first split, one factor is still a difference of squares.","solution":"(x² − 4)(x² + 4). Then x² − 4 = (x − 2)(x + 2). Answer: (x − 2)(x + 2)(x² + 4)."},{"id":"u4-fa4-q3","type":"choice","prompt":"Factor 2x² + 12x + 18.","choices":["2(x + 3)²","2(x + 9)(x + 1)","(2x + 6)(x + 3)","2(x + 3)(x − 3)"],"answer":0,"hint":"GCF first. The trinomial left is a perfect square.","solution":"2(x² + 6x + 9) = 2(x + 3)²."},{"id":"u4-fa4-q4","type":"choice","prompt":"Factor 6x² + 7x − 3.","choices":["(3x + 1)(2x − 3)","(6x − 1)(x + 3)","(3x + 3)(2x − 1)","(3x − 1)(2x + 3)"],"answer":3,"hint":"ac = −18. Find two numbers that multiply to −18 and add to 7.","solution":"9 + (−2) = 7. 6x² + 9x − 2x − 3 = 3x(2x + 3) − 1(2x + 3) = (3x − 1)(2x + 3)."},{"id":"u4-fa4-q5","type":"choice","prompt":"Factor x³ − 5x² − 14x.","choices":["x(x + 7)(x − 2)","(x − 7)(x + 2)","x(x − 7)(x + 2)","x(x − 14)(x + 1)"],"answer":2,"hint":"Take out x first. Then factor the trinomial.","solution":"x(x² − 5x − 14). −7 · 2 = −14 and −7 + 2 = −5. So x(x − 7)(x + 2)."},{"id":"u4-fa4-q6","type":"input","prompt":"(x + 8)(x − 3) = x² + bx − 24. What is b?","answers":["5"],"hint":"Multiply out and combine the x terms: 8x and −3x.","solution":"(x + 8)(x − 3) = x² − 3x + 8x − 24 = x² + 5x − 24. So b = 5."},{"id":"u4-fa4-q7","type":"choice","prompt":"Factor x² − 6x − 16.","choices":["(x + 8)(x − 2)","(x − 8)(x + 2)","(x − 8)(x − 2)","(x − 4)(x + 4)"],"answer":1,"hint":"Multiply to −16, add to −6.","solution":"−8 · 2 = −16 and −8 + 2 = −6. So (x − 8)(x + 2)."},{"id":"u4-fa4-q8","type":"choice","prompt":"Factor 20x² − 45.","choices":["5(2x − 3)(2x + 3)","5(2x − 3)²","(10x − 15)(2x + 3)","5(4x² − 9)"],"answer":0,"hint":"GCF first, then 4x² − 9.","solution":"20x² − 45 = 5(4x² − 9) = 5(2x − 3)(2x + 3)."}]}]},{"id":"solve-factoring","title":"Solving by factoring","lessons":[{"id":"solve-factoring-1","teach":[{"title":"Zero product property","text":["If A · B = 0, then A = 0 or B = 0. A product is zero only when one of its factors is zero.","So when an equation is already factored and equals 0, set each factor equal to 0 and solve."],"example":{"problem":"Solve (x − 3)(x + 5) = 0","steps":["x − 3 = 0 gives x = 3.","x + 5 = 0 gives x = −5.","Solutions: x = 3 and x = −5."]}}],"questions":[{"id":"u4-sv1-q1","type":"input","prompt":"Solve (x − 2)(x + 7) = 0. Give both solutions.","answers":["2, -7"],"hint":"Set each factor equal to 0.","solution":"x − 2 = 0 gives x = 2. x + 7 = 0 gives x = −7."},{"id":"u4-sv1-q2","type":"input","prompt":"Solve (x + 4)(x + 1) = 0. Give both solutions.","answers":["-4, -1"],"hint":"Each factor equals 0 separately. Watch the signs.","solution":"x + 4 = 0 gives x = −4. x + 1 = 0 gives x = −1."},{"id":"u4-sv1-q3","type":"input","prompt":"Solve x(x − 9) = 0. Give both solutions.","answers":["0, 9"],"hint":"The factor x is also a factor.","solution":"x = 0 or x − 9 = 0. So x = 0 or x = 9."},{"id":"u4-sv1-q4","type":"choice","prompt":"Solve (2x − 1)(x + 6) = 0.","choices":["x = 2 or x = −6","x = −½ or x = 6","x = ½ or x = 6","x = ½ or x = −6"],"answer":3,"hint":"For 2x − 1 = 0, add 1 and then divide by 2.","solution":"2x − 1 = 0 gives x = ½. x + 6 = 0 gives x = −6."},{"id":"u4-sv1-q5","type":"input","prompt":"Solve (3x + 5)(x − 4) = 0. Give both solutions (use a fraction).","answers":["-5/3, 4"],"hint":"Solve 3x + 5 = 0 by subtracting 5 and then dividing by 3.","solution":"3x + 5 = 0 gives x = −5/3. x − 4 = 0 gives x = 4."},{"id":"u4-sv1-q6","type":"choice","prompt":"Why can you set each factor equal to 0 in (x − 1)(x + 2) = 0?","choices":["The factors must be equal to each other","The sum of the factors must be 0","A product is 0 only when at least one factor is 0","Every factor must be positive"],"answer":2,"hint":"Think about what multiplying by 0 does.","solution":"If neither factor is 0, the product cannot be 0. So at least one factor must be 0."},{"id":"u4-sv1-q7","type":"input","prompt":"Solve (x − 8)² = 0.","answers":["8"],"hint":"Both factors are the same: (x − 8)(x − 8).","solution":"x − 8 = 0, so x = 8. It is a double solution."},{"id":"u4-sv1-q8","type":"input","prompt":"Solve 5x(x + 3)(x − 2) = 0. Give all three solutions.","answers":["0, -3, 2"],"hint":"Each factor with x in it can be 0. The 5 cannot.","solution":"5x = 0 gives x = 0. x + 3 = 0 gives x = −3. x − 2 = 0 gives x = 2."}]},{"id":"solve-factoring-2","teach":[{"title":"Set it equal to 0 first","text":["The zero product property only works when one side is 0.","Move every term to one side, factor, then set each factor to 0.","Never divide both sides by x: you will lose the solution x = 0."],"example":{"problem":"Solve x² = 7x − 12","steps":["Move everything to one side: x² − 7x + 12 = 0.","Factor: (x − 3)(x − 4) = 0.","x = 3 or x = 4."]}}],"questions":[{"id":"u4-sv2-q1","type":"input","prompt":"Solve x² − 5x + 6 = 0. Give both solutions.","answers":["2, 3"],"hint":"Factor into (x − m)(x − n).","solution":"(x − 2)(x − 3) = 0, so x = 2 or x = 3."},{"id":"u4-sv2-q2","type":"input","prompt":"Solve x² + 3x − 10 = 0. Give both solutions.","answers":["-5, 2"],"hint":"Two numbers that multiply to −10 and add to 3.","solution":"(x + 5)(x − 2) = 0, so x = −5 or x = 2."},{"id":"u4-sv2-q3","type":"input","prompt":"Solve x² − 9 = 0. Give both solutions.","answers":["3, -3"],"hint":"Difference of squares.","solution":"(x − 3)(x + 3) = 0, so x = 3 or x = −3."},{"id":"u4-sv2-q4","type":"input","prompt":"Solve x² + 8x = 0. Give both solutions.","answers":["0, -8"],"hint":"Factor out x.","solution":"x(x + 8) = 0, so x = 0 or x = −8."},{"id":"u4-sv2-q5","type":"input","prompt":"Solve 2x² − 8x = 0. Give both solutions.","answers":["0, 4"],"hint":"The GCF is 2x.","solution":"2x(x − 4) = 0, so x = 0 or x = 4."},{"id":"u4-sv2-q6","type":"input","prompt":"Solve x² = 7x − 12. Give both solutions.","answers":["3, 4"],"hint":"Move everything to the left side first.","solution":"x² − 7x + 12 = 0, so (x − 3)(x − 4) = 0. x = 3 or x = 4."},{"id":"u4-sv2-q7","type":"input","prompt":"Solve x² + 14x + 49 = 0.","answers":["-7"],"hint":"Perfect square trinomial.","solution":"(x + 7)² = 0, so x = −7."},{"id":"u4-sv2-q8","type":"choice","prompt":"Solve x² − 4x = 5.","choices":["x = 5 or x = 9","x = 5 or x = −1","x = −5 or x = 1","x = 4 or x = 5"],"answer":1,"hint":"Do not factor x(x − 4) = 5. Move the 5 first.","solution":"x² − 4x − 5 = 0, so (x − 5)(x + 1) = 0. x = 5 or x = −1."}]},{"id":"solve-factoring-3","teach":[{"title":"Harder equations to factor","text":["Use all your factoring tools: GCF, a ≠ 1, difference of squares, perfect squares.","A GCF that is just a number never gives a solution. It does not change the answers."],"example":{"problem":"Solve 2x² + 5x − 3 = 0","steps":["ac = −6, and 6 + (−1) = 5.","2x² + 6x − x − 3 = 2x(x + 3) − 1(x + 3) = (2x − 1)(x + 3).","x = ½ or x = −3."]}}],"questions":[{"id":"u4-sv3-q1","type":"input","prompt":"Solve 2x² + 5x − 3 = 0. Give both solutions (use a fraction).","answers":["1/2, -3"],"hint":"Factor into (2x − 1)(x + 3).","solution":"(2x − 1)(x + 3) = 0. x = ½ or x = −3."},{"id":"u4-sv3-q2","type":"input","prompt":"Solve 3x² − 10x + 8 = 0. Give both solutions.","answers":["4/3, 2"],"hint":"ac = 24. Find two numbers that multiply to 24 and add to −10.","solution":"3x² − 6x − 4x + 8 = 3x(x − 2) − 4(x − 2) = (3x − 4)(x − 2). x = 4/3 or x = 2."},{"id":"u4-sv3-q3","type":"input","prompt":"Solve 6x² + x − 2 = 0. Give both solutions.","answers":["-2/3, 1/2"],"hint":"The factors are (3x + 2)(2x − 1).","solution":"(3x + 2)(2x − 1) = 0. x = −2/3 or x = 1/2."},{"id":"u4-sv3-q4","type":"input","prompt":"Solve 4x² − 25 = 0. Give both solutions.","answers":["5/2, -5/2"],"hint":"Difference of squares: (2x)² − 5².","solution":"(2x − 5)(2x + 5) = 0. x = 5/2 or x = −5/2."},{"id":"u4-sv3-q5","type":"input","prompt":"Solve 3x² + 12x + 12 = 0.","answers":["-2"],"hint":"Take out the 3 first.","solution":"3(x² + 4x + 4) = 3(x + 2)² = 0. So x = −2."},{"id":"u4-sv3-q6","type":"input","prompt":"Solve 2x² − 18 = 0. Give both solutions.","answers":["3, -3"],"hint":"GCF of 2 first.","solution":"2(x² − 9) = 2(x − 3)(x + 3) = 0. x = 3 or x = −3."},{"id":"u4-sv3-q7","type":"input","prompt":"Solve 5x² = 20x. Give both solutions.","answers":["0, 4"],"hint":"Do not divide by x. Move 20x to the left.","solution":"5x² − 20x = 0, so 5x(x − 4) = 0. x = 0 or x = 4."},{"id":"u4-sv3-q8","type":"input","prompt":"Solve x³ − 4x = 0. Give all three solutions.","answers":["0, 2, -2"],"hint":"Factor out x. Then use difference of squares.","solution":"x(x² − 4) = x(x − 2)(x + 2) = 0. x = 0, 2, or −2."}]},{"id":"solve-factoring-4","teach":[{"title":"Word problems","text":["Define a variable, write an equation, set it equal to 0, and factor.","Check each answer in the story. A length cannot be negative, so some solutions get thrown out."],"example":{"problem":"A rectangle is 3 cm longer than it is wide. Its area is 40 cm². Find the width.","steps":["Let w = width. Length is w + 3. w(w + 3) = 40.","w² + 3w − 40 = 0, so (w + 8)(w − 5) = 0.","w = −8 or w = 5. A width cannot be negative, so w = 5."]}}],"questions":[{"id":"u4-sv4-q1","type":"input","prompt":"The product of two consecutive positive integers is 56. What is the smaller integer?","answers":["7"],"hint":"Let n and n + 1 be the integers. Write n(n + 1) = 56.","solution":"n² + n − 56 = 0, so (n + 8)(n − 7) = 0. n = 7 (n = −8 is not positive). Check: 7 · 8 = 56."},{"id":"u4-sv4-q2","type":"input","prompt":"A number squared equals 4 times the number plus 12. Find both numbers.","answers":["6, -2"],"hint":"Write x² = 4x + 12, then move everything to one side.","solution":"x² − 4x − 12 = 0, so (x − 6)(x + 2) = 0. x = 6 or x = −2."},{"id":"u4-sv4-q3","type":"input","prompt":"A rectangle is 3 cm longer than it is wide. Its area is 40 cm². What is the width in cm?","answers":["5"],"hint":"Width w, length w + 3. Area = w(w + 3).","solution":"w² + 3w − 40 = 0, so (w + 8)(w − 5) = 0. w = 5 (not −8)."},{"id":"u4-sv4-q4","type":"input","prompt":"A ball is thrown so that its height is h = −16t² + 48t feet after t seconds. When does it land (t > 0)? Type the number of seconds.","answers":["3"],"hint":"It lands when h = 0.","solution":"−16t² + 48t = 0, so −16t(t − 3) = 0. t = 0 (the throw) or t = 3. It lands at t = 3."},{"id":"u4-sv4-q5","type":"input","prompt":"Solve (x + 3)(x − 1) = 12. Give both solutions.","answers":["-5, 3"],"hint":"Do not set each factor equal to 12. Multiply out and move the 12 first.","solution":"x² + 2x − 3 = 12, so x² + 2x − 15 = 0. (x + 5)(x − 3) = 0. x = −5 or x = 3."},{"id":"u4-sv4-q6","type":"choice","prompt":"What is the right first step to solve x² + x = 20?","choices":["Rewrite as x² + x − 20 = 0","Factor x(x + 1) = 20 and set x = 20","Divide both sides by x","Take the square root of both sides"],"answer":0,"hint":"The zero product property needs 0 on one side.","solution":"Subtract 20 from both sides to get x² + x − 20 = 0. Then factor."},{"id":"u4-sv4-q7","type":"input","prompt":"Solve 2x² + 7x = 15. Give both solutions (use a fraction).","answers":["3/2, -5"],"hint":"Move 15 first, then use ac = −30.","solution":"2x² + 7x − 15 = 0. 10 + (−3) = 7: 2x² + 10x − 3x − 15 = (2x − 3)(x + 5). x = 3/2 or x = −5."},{"id":"u4-sv4-q8","type":"input","prompt":"A square has side length x + 2 cm and area 49 cm². What is x?","answers":["5"],"hint":"Write (x + 2)² = 49, multiply out, and move 49 over.","solution":"x² + 4x + 4 = 49, so x² + 4x − 45 = 0. (x + 9)(x − 5) = 0. x = 5 (x = −9 would make a negative side)."}]}]},{"id":"square-roots","title":"Solving by square roots","lessons":[{"id":"square-roots-1","teach":[{"title":"Solving x² = k","text":["If x² = k and k > 0, then x = ±√k: two solutions, one positive and one negative.","If k = 0, then x = 0. If k < 0, there is no real solution, because a real number squared is never negative."],"example":{"problem":"Solve x² = 20","steps":["x = ±√20.","√20 = √(4 · 5) = 2√5.","x = ±2√5"]}}],"questions":[{"id":"u4-sr1-q1","type":"input","prompt":"Solve x² = 49. Give both solutions.","answers":["7, -7"],"hint":"Take the square root of both sides. Remember ±.","solution":"x = ±√49 = ±7.","calculator":false},{"id":"u4-sr1-q2","type":"input","prompt":"Solve x² = 25/4. Give both solutions.","answers":["5/2, -5/2"],"hint":"Take the root of the top and the bottom.","solution":"x = ±√(25/4) = ±5/2.","calculator":false},{"id":"u4-sr1-q3","type":"input","prompt":"Solve x² − 36 = 0. Give both solutions.","answers":["6, -6"],"hint":"Add 36 to both sides first.","solution":"x² = 36, so x = ±6.","calculator":false},{"id":"u4-sr1-q4","type":"choice","prompt":"Solve x² = 20.","choices":["x = ±10","x = ±4√5","x = ±5√2","x = ±2√5"],"answer":3,"hint":"Simplify √20 by pulling out the perfect square 4.","solution":"x = ±√20 = ±√(4 · 5) = ±2√5.","calculator":false},{"id":"u4-sr1-q5","type":"choice","prompt":"Solve x² = −36.","choices":["x = ±3","x = 3","No real solution","x = −3"],"answer":2,"hint":"Can a real number squared be negative?","solution":"A real number squared is never negative. So there is no real solution."},{"id":"u4-sr1-q6","type":"input","prompt":"Solve 3x² = 75. Give both solutions.","answers":["5, -5"],"hint":"Divide both sides by 3 before taking the root.","solution":"x² = 25, so x = ±5.","calculator":false},{"id":"u4-sr1-q7","type":"choice","prompt":"Solve x² = 18.","choices":["x = ±9","x = ±3√2","x = ±2√3","x = ±3√6"],"answer":1,"hint":"The perfect square inside 18 is 9.","solution":"x = ±√18 = ±√(9 · 2) = ±3√2.","calculator":false},{"id":"u4-sr1-q8","type":"input","prompt":"Solve 2x² + 1 = 33. Give both solutions.","answers":["4, -4"],"hint":"Subtract 1, divide by 2, then take the root.","solution":"2x² = 32, x² = 16, so x = ±4.","calculator":false}]},{"id":"square-roots-2","teach":[{"title":"Simplifying radicals","text":["Look for the biggest perfect square factor: 4, 9, 16, 25, 36, 49, ...","Use √(a · b) = √a · √b. The square root of the perfect square comes out front."],"example":{"problem":"Simplify √72","steps":["72 = 36 · 2, and 36 is a perfect square.","√72 = √36 · √2 = 6√2."]}}],"questions":[{"id":"u4-sr2-q1","type":"input","prompt":"What is √49?","answers":["7"],"hint":"What number times itself is 49?","solution":"7 · 7 = 49, so √49 = 7.","calculator":false},{"id":"u4-sr2-q2","type":"choice","prompt":"Simplify √50.","choices":["5√2","25√2","10√5","2√25"],"answer":0,"hint":"50 = 25 · 2.","solution":"√50 = √25 · √2 = 5√2.","calculator":false},{"id":"u4-sr2-q3","type":"input","prompt":"√48 = k√3. What is k?","answers":["4"],"hint":"48 = 16 · 3.","solution":"√48 = √16 · √3 = 4√3. So k = 4.","calculator":false},{"id":"u4-sr2-q4","type":"choice","prompt":"Simplify √75.","choices":["3√5","25√3","15√5","5√3"],"answer":3,"hint":"75 = 25 · 3.","solution":"√75 = √25 · √3 = 5√3.","calculator":false},{"id":"u4-sr2-q5","type":"choice","prompt":"Simplify √200.","choices":["100√2","20√5","10√2","2√10"],"answer":2,"hint":"200 = 100 · 2. Use the biggest perfect square.","solution":"√200 = √100 · √2 = 10√2.","calculator":false},{"id":"u4-sr2-q6","type":"input","prompt":"√72 = k√2. What is k?","answers":["6"],"hint":"72 = 36 · 2.","solution":"√72 = √36 · √2 = 6√2. So k = 6.","calculator":false},{"id":"u4-sr2-q7","type":"choice","prompt":"Simplify 3√28.","choices":["9√7","6√7","2√21","12√7"],"answer":1,"hint":"Simplify √28 first, then multiply by 3.","solution":"√28 = √4 · √7 = 2√7. Then 3 · 2√7 = 6√7.","calculator":false},{"id":"u4-sr2-q8","type":"input","prompt":"√45 = k√5. What is k?","answers":["3"],"hint":"45 = 9 · 5.","solution":"√45 = √9 · √5 = 3√5. So k = 3.","calculator":false}]},{"id":"square-roots-3","teach":[{"title":"Solving (x − h)² = k","text":["When a squared expression equals a number, take the square root of both sides: x − h = ±√k.","Then solve for x. If k is not a perfect square, leave the answer as h ± √k."],"example":{"problem":"Solve (x − 2)² = 9","steps":["Take square roots: x − 2 = ±3.","x = 2 + 3 = 5 or x = 2 − 3 = −1."]}}],"questions":[{"id":"u4-sr3-q1","type":"input","prompt":"Solve (x − 3)² = 16. Give both solutions.","answers":["7, -1"],"hint":"x − 3 = ±4.","solution":"x − 3 = 4 gives x = 7. x − 3 = −4 gives x = −1.","calculator":false},{"id":"u4-sr3-q2","type":"input","prompt":"Solve (x + 5)² = 4. Give both solutions.","answers":["-3, -7"],"hint":"x + 5 = ±2. Subtract 5.","solution":"x + 5 = 2 gives x = −3. x + 5 = −2 gives x = −7.","calculator":false},{"id":"u4-sr3-q3","type":"input","prompt":"Solve (x + 1)² = 25. Give both solutions.","answers":["4, -6"],"hint":"x + 1 = ±5.","solution":"x + 1 = 5 gives x = 4. x + 1 = −5 gives x = −6.","calculator":false},{"id":"u4-sr3-q4","type":"choice","prompt":"Solve (x − 4)² = −1.","choices":["No real solution","x = 5 or x = 3","x = 4","x = −3 or x = −5"],"answer":0,"hint":"Can a square be negative?","solution":"A real square is never −1. No real solution."},{"id":"u4-sr3-q5","type":"choice","prompt":"Solve (x − 2)² = 7.","choices":["x = −2 ± √7","x = 2 ± 7","x = ±√5","x = 2 ± √7"],"answer":3,"hint":"7 is not a perfect square. Leave the root.","solution":"x − 2 = ±√7, so x = 2 ± √7.","calculator":false},{"id":"u4-sr3-q6","type":"input","prompt":"Solve (2x − 1)² = 9. Give both solutions.","answers":["2, -1"],"hint":"2x − 1 = ±3. Then solve each.","solution":"2x − 1 = 3 gives x = 2. 2x − 1 = −3 gives x = −1.","calculator":false},{"id":"u4-sr3-q7","type":"choice","prompt":"Solve (x + 6)² = 12.","choices":["x = 6 ± 2√3","x = −6 ± √6","x = −6 ± 2√3","x = −6 ± 4√3"],"answer":2,"hint":"Simplify √12 = √4 · √3.","solution":"x + 6 = ±√12 = ±2√3. So x = −6 ± 2√3.","calculator":false},{"id":"u4-sr3-q8","type":"input","prompt":"Solve 3(x − 1)² = 48. Give both solutions.","answers":["5, -3"],"hint":"Divide by 3 first.","solution":"(x − 1)² = 16, so x − 1 = ±4. x = 5 or x = −3.","calculator":false}]},{"id":"square-roots-4","teach":[{"title":"Mixed and applied","text":["Isolate the squared part first, then take ±√. Check the sign of what is left: negative means no real solution.","In a word problem, a length or time must be positive, so throw out a negative answer."],"example":{"problem":"An object is dropped. Its height drop is d = 16t². How long to fall 144 feet?","steps":["16t² = 144, so t² = 9.","t = ±3.","Time cannot be negative, so t = 3 seconds."]}}],"questions":[{"id":"u4-sr4-q1","type":"input","prompt":"Solve 4x² = 100. Give both solutions.","answers":["5, -5"],"hint":"Divide by 4 first.","solution":"x² = 25, so x = ±5.","calculator":false},{"id":"u4-sr4-q2","type":"choice","prompt":"Solve 2x² + 18 = 0.","choices":["x = ±3","No real solution","x = ±9","x = 3"],"answer":1,"hint":"Isolate x². What sign does it have?","solution":"2x² = −18, so x² = −36. No real number squared is −36."},{"id":"u4-sr4-q3","type":"input","prompt":"Solve (x − 7)² = 0.","answers":["7"],"hint":"The only number whose square is 0 is 0.","solution":"x − 7 = 0, so x = 7.","calculator":false},{"id":"u4-sr4-q4","type":"choice","prompt":"Solve 2(x + 3)² = 50.","choices":["x = 2 or x = −8","x = 8 or x = −2","x = 22 or x = −28","x = 2 only"],"answer":0,"hint":"Divide by 2, then take ±.","solution":"(x + 3)² = 25, so x + 3 = ±5. x = 2 or x = −8.","calculator":false},{"id":"u4-sr4-q5","type":"input","prompt":"A square has area 81 cm². What is its side length in cm?","answers":["9"],"hint":"Area = side². A side cannot be negative.","solution":"s² = 81, so s = ±9. A length is positive, so s = 9.","calculator":false},{"id":"u4-sr4-q6","type":"input","prompt":"A dropped object falls d = 16t² feet in t seconds. How many seconds to fall 144 feet?","answers":["3"],"hint":"Set 16t² = 144.","solution":"t² = 9, so t = ±3. Time cannot be negative, so t = 3.","calculator":false},{"id":"u4-sr4-q7","type":"choice","prompt":"Solve 3(x − 1)² = 24.","choices":["x = 1 ± 8","x = 1 ± 4√2","x = −1 ± 2√2","x = 1 ± 2√2"],"answer":3,"hint":"Divide by 3. Then simplify √8.","solution":"(x − 1)² = 8, so x − 1 = ±√8 = ±2√2. x = 1 ± 2√2.","calculator":false},{"id":"u4-sr4-q8","type":"input","prompt":"Solve (x + 4)² − 49 = 0. Give both solutions.","answers":["3, -11"],"hint":"Add 49 to both sides.","solution":"(x + 4)² = 49, so x + 4 = ±7. x = 3 or x = −11.","calculator":false},{"id":"u4-sr4-q9","type":"choice","prompt":"For which value of k does (x − 2)² = k have no real solution?","choices":["k = 0","k = 4","k = −4","k = 16"],"answer":2,"hint":"A real square is never negative.","solution":"If k < 0 there is no real solution. Only −4 is negative."}]}]},{"id":"imaginary","title":"Imaginary numbers","lessons":[{"id":"imaginary-1","teach":[{"title":"The number i","text":["No real number squares to a negative. So we define i = √(−1). That gives i² = −1.","For a negative radicand, pull out the −1: √(−n) = i√n."],"example":{"problem":"Simplify √(−16)","steps":["Split off the negative: √(−16) = √16 · √(−1).","√16 = 4 and √(−1) = i.","√(−16) = 4i"]}},{"title":"Simplifying √(−n) when n is not a perfect square","text":["Pull out i first. Then simplify the radical the usual way, by taking out perfect squares.","Write the i in front of the radical so it is not mistaken for part of the root: 2i√3."],"example":{"problem":"Simplify √(−12)","steps":["√(−12) = i√12.","√12 = √4 · √3 = 2√3.","√(−12) = 2i√3"]}}],"questions":[{"id":"u4-im1-q1","type":"choice","prompt":"What is the value of i²?","choices":["1","i","−1","−i"],"answer":2,"hint":"i is defined as √(−1). Square both sides of that.","solution":"i = √(−1), so i² = (√(−1))² = −1."},{"id":"u4-im1-q2","type":"input","prompt":"√(−49) = bi. What is b?","answers":["7"],"hint":"√(−49) = √49 · √(−1).","solution":"√49 = 7 and √(−1) = i, so √(−49) = 7i. b = 7."},{"id":"u4-im1-q3","type":"choice","prompt":"Simplify √(−25).","choices":["5i","−5i","5","25i"],"answer":0,"hint":"Take out the −1 as i, then take the square root of 25.","solution":"√(−25) = √25 · √(−1) = 5i."},{"id":"u4-im1-q4","type":"input","prompt":"√(−81) = bi. What is b?","answers":["9"],"hint":"Think of what number times itself is 81.","solution":"√(−81) = √81 · i = 9i, so b = 9."},{"id":"u4-im1-q5","type":"choice","prompt":"Simplify √(−20).","choices":["4i√5","−2i√5","5i√2","2i√5"],"answer":3,"hint":"Pull out i. Then √20 = √4 · √5.","solution":"√(−20) = i√20 = i · √4 · √5 = 2i√5."},{"id":"u4-im1-q6","type":"input","prompt":"√(−36) + √(−4) = bi. What is b?","answers":["8"],"hint":"Write each term as a multiple of i, then add.","solution":"√(−36) = 6i and √(−4) = 2i. 6i + 2i = 8i, so b = 8."},{"id":"u4-im1-q7","type":"choice","prompt":"Which of these is NOT a real number?","choices":["−√16","√(−16)","∛(−8)","√0"],"answer":1,"hint":"A real number can be placed on the number line. Check each one.","solution":"−√16 = −4, ∛(−8) = −2 and √0 = 0 are all real. √(−16) = 4i is imaginary."},{"id":"u4-im1-q8","type":"input","prompt":"√(−18) = 3i√b. What is b?","answers":["2"],"hint":"18 = 9 · 2.","solution":"√(−18) = i√18 = i · √9 · √2 = 3i√2, so b = 2."}]},{"id":"imaginary-2","teach":[{"title":"The powers of i repeat","text":["i¹ = i, i² = −1, i³ = −i, i⁴ = 1. Then the pattern starts over.","To simplify iⁿ, divide n by 4 and keep the remainder. Remainder 1 gives i, 2 gives −1, 3 gives −i, and 0 gives 1."],"example":{"problem":"Simplify i²³","steps":["23 ÷ 4 = 5 remainder 3.","Remainder 3 means i³ = −i.","i²³ = −i"]}}],"questions":[{"id":"u4-im2-q1","type":"choice","prompt":"What is i³?","choices":["i","−i","−1","1"],"answer":1,"hint":"i³ = i² · i.","solution":"i³ = i² · i = (−1) · i = −i."},{"id":"u4-im2-q2","type":"choice","prompt":"What is i⁴?","choices":["−1","i","−i","1"],"answer":3,"hint":"i⁴ = i² · i².","solution":"i⁴ = (−1)(−1) = 1."},{"id":"u4-im2-q3","type":"input","prompt":"Simplify i⁸. Give a number.","answers":["1"],"hint":"i⁸ = (i⁴)².","solution":"i⁴ = 1, so i⁸ = 1² = 1."},{"id":"u4-im2-q4","type":"choice","prompt":"Simplify i¹³.","choices":["i","−i","1","−1"],"answer":0,"hint":"Divide 13 by 4 and use the remainder.","solution":"13 ÷ 4 = 3 remainder 1, so i¹³ = i¹ = i."},{"id":"u4-im2-q5","type":"choice","prompt":"Simplify i²².","choices":["1","i","−1","−i"],"answer":2,"hint":"Divide 22 by 4 and use the remainder.","solution":"22 ÷ 4 = 5 remainder 2, so i²² = i² = −1."},{"id":"u4-im2-q6","type":"input","prompt":"To simplify i⁴⁷, divide 47 by 4. What is the remainder?","answers":["3"],"hint":"4 · 11 = 44.","solution":"47 = 4 · 11 + 3. The remainder is 3."},{"id":"u4-im2-q7","type":"choice","prompt":"Simplify i⁴⁷.","choices":["i","1","−i","−1"],"answer":2,"hint":"Use the remainder from dividing 47 by 4.","solution":"47 ÷ 4 leaves remainder 3. i³ = −i, so i⁴⁷ = −i."},{"id":"u4-im2-q8","type":"choice","prompt":"Simplify i³⁸ + i⁴¹.","choices":["−1 + i","1 + i","−1 − i","1 − i"],"answer":0,"hint":"Simplify each power on its own first.","solution":"38 ÷ 4 leaves remainder 2, so i³⁸ = −1. 41 ÷ 4 leaves remainder 1, so i⁴¹ = i. The sum is −1 + i."}]},{"id":"imaginary-3","teach":[{"title":"Solving x² = −k","text":["Take the square root of both sides, as always. When the number is negative, the answers are imaginary.","x² = −k gives x = ±i√k. There are two solutions, and neither is a real number."],"example":{"problem":"Solve x² = −16","steps":["Square root of both sides: x = ±√(−16).","√(−16) = 4i.","x = ±4i"]}},{"title":"Get x² alone first","text":["If there is a number added to or multiplying x², undo it before you take the square root."],"example":{"problem":"Solve x² + 20 = 0","steps":["Subtract 20: x² = −20.","x = ±√(−20) = ±i√20.","√20 = 2√5, so x = ±2i√5."]}}],"questions":[{"id":"u4-im3-q1","type":"choice","prompt":"Solve x² = −9.","choices":["x = ±3","x = 3i","x = ±9i","x = ±3i"],"answer":3,"hint":"A negative number under the root gives i. There are two solutions.","solution":"x = ±√(−9) = ±3i."},{"id":"u4-im3-q2","type":"choice","prompt":"Solve x² = −64.","choices":["x = ±8","x = ±8i","x = ±32i","x = −8i"],"answer":1,"hint":"Take the square root of both sides.","solution":"x = ±√(−64) = ±8i."},{"id":"u4-im3-q3","type":"input","prompt":"The solutions of x² = −49 are ±bi. What is b?","answers":["7"],"hint":"√49 = 7.","solution":"x = ±√(−49) = ±7i, so b = 7."},{"id":"u4-im3-q4","type":"choice","prompt":"Solve x² + 25 = 0.","choices":["x = ±5","x = ±5i","x = ±25i","x = 5i"],"answer":1,"hint":"Subtract 25 from both sides first.","solution":"x² = −25, so x = ±5i."},{"id":"u4-im3-q5","type":"choice","prompt":"Solve x² + 12 = 0.","choices":["x = ±4i√3","x = ±2√3","x = ±6i","x = ±2i√3"],"answer":3,"hint":"x² = −12. Then simplify √12.","solution":"x² = −12, so x = ±i√12 = ±i · 2√3 = ±2i√3."},{"id":"u4-im3-q6","type":"choice","prompt":"Solve 3x² = −75.","choices":["x = ±5i","x = ±25i","x = ±5","x = ±15i"],"answer":0,"hint":"Divide both sides by 3 first.","solution":"x² = −25, so x = ±5i."},{"id":"u4-im3-q7","type":"input","prompt":"How many real solutions does x² = −10 have?","answers":["0"],"hint":"The square of a real number is never negative.","solution":"x = ±i√10 are not real numbers. There are 0 real solutions."},{"id":"u4-im3-q8","type":"choice","prompt":"Solve 2x² + 32 = 0.","choices":["x = ±16i","x = ±4","x = ±4i","x = ±2i√2"],"answer":2,"hint":"Subtract 32, then divide by 2.","solution":"2x² = −32, x² = −16, x = ±4i."}]},{"id":"imaginary-4","teach":[{"title":"Convert to i before you multiply","text":["The rule √a · √b = √(ab) only works when a and b are not both negative. So write each root with i first, then multiply.","Remember i · i = i² = −1."],"example":{"problem":"Simplify √(−4) · √(−9)","steps":["Write each with i: √(−4) = 2i and √(−9) = 3i.","Multiply: 2i · 3i = 6i².","6i² = −6. (Not 6.)"]}}],"questions":[{"id":"u4-im4-q1","type":"choice","prompt":"Simplify √(−4) · √(−9).","choices":["6","6i","−6","−6i"],"answer":2,"hint":"Convert each root to a multiple of i first.","solution":"2i · 3i = 6i² = −6."},{"id":"u4-im4-q2","type":"input","prompt":"Simplify √(−4) · √(−25). Give a number.","answers":["-10"],"hint":"√(−4) = 2i and √(−25) = 5i.","solution":"2i · 5i = 10i² = −10."},{"id":"u4-im4-q3","type":"choice","prompt":"Simplify (√(−3))².","choices":["−3","3","3i","−3i"],"answer":0,"hint":"√(−3) = i√3. Square it.","solution":"(i√3)² = i² · 3 = −3."},{"id":"u4-im4-q4","type":"choice","prompt":"Write 5 + √(−32) in the form a + bi.","choices":["5 + 16i√2","5 − 4i√2","5 + 8i√2","5 + 4i√2"],"answer":3,"hint":"√32 = √16 · √2.","solution":"√(−32) = i√32 = 4i√2. So 5 + √(−32) = 5 + 4i√2."},{"id":"u4-im4-q5","type":"input","prompt":"In 7 − 3i, what number multiplies i? Give the number, including its sign.","answers":["-3"],"hint":"Write 7 − 3i as 7 + (−3)i.","solution":"7 − 3i = 7 + (−3)i, so the number is −3."},{"id":"u4-im4-q6","type":"choice","prompt":"Simplify i⁶ · √(−16).","choices":["4i","−4i","4","−4"],"answer":1,"hint":"i⁶ is i² after dividing 6 by 4. And √(−16) = 4i.","solution":"i⁶ = −1 and √(−16) = 4i. The product is −4i."},{"id":"u4-im4-q7","type":"input","prompt":"Solve x² + 3 = −6. The solutions are ±bi. What is b?","answers":["3"],"hint":"Subtract 3 from both sides first.","solution":"x² = −9, so x = ±3i and b = 3."},{"id":"u4-im4-q8","type":"choice","prompt":"Which expression is a real number?","choices":["i⁷","i⁶","i⁹","√(−7)"],"answer":1,"hint":"Check what each one simplifies to.","solution":"i⁶ = −1 is real. i⁷ = −i, i⁹ = i and √(−7) = i√7 are imaginary."}]}]},{"id":"complex-operations","title":"Operations with complex numbers","lessons":[{"id":"complex-operations-1","teach":[{"title":"Adding and subtracting","text":["A complex number is a + bi. Add or subtract the real parts together and the i parts together, like combining like terms.","When you subtract, distribute the minus sign to both parts of the second number."],"example":{"problem":"Simplify (3 + 2i) − (1 + 5i)","steps":["Distribute the minus: 3 + 2i − 1 − 5i.","Real parts: 3 − 1 = 2. Imaginary parts: 2i − 5i = −3i.","Answer: 2 − 3i"]}}],"questions":[{"id":"u4-co1-q1","type":"choice","prompt":"Add: (3 + 2i) + (4 + i)","choices":["7 + 2i","12 + 2i","7 + 3i","10i"],"answer":2,"hint":"Add the real parts. Add the i parts.","solution":"3 + 4 = 7 and 2i + i = 3i. Answer: 7 + 3i."},{"id":"u4-co1-q2","type":"choice","prompt":"Add: (5 − 2i) + (−3 + 6i)","choices":["2 + 4i","2 − 4i","8 + 4i","2 + 8i"],"answer":0,"hint":"Real with real, imaginary with imaginary. Watch the signs.","solution":"5 + (−3) = 2 and −2i + 6i = 4i. Answer: 2 + 4i."},{"id":"u4-co1-q3","type":"choice","prompt":"Subtract: (6 + 4i) − (2 + i)","choices":["4 + 5i","8 + 5i","4 + 4i","4 + 3i"],"answer":3,"hint":"Subtract the real parts and subtract the i parts.","solution":"6 − 2 = 4 and 4i − i = 3i. Answer: 4 + 3i."},{"id":"u4-co1-q4","type":"choice","prompt":"Subtract: (3 − 5i) − (−2 + 4i)","choices":["1 − i","5 − 9i","5 − i","1 − 9i"],"answer":1,"hint":"Distribute the minus sign to both parts of −2 + 4i.","solution":"3 − (−2) = 5 and −5i − 4i = −9i. Answer: 5 − 9i."},{"id":"u4-co1-q5","type":"input","prompt":"What is the real part of (9 + 2i) − (4 + 7i)?","answers":["5"],"hint":"Only subtract the real numbers: 9 and 4.","solution":"9 − 4 = 5. The result is 5 − 5i, so the real part is 5."},{"id":"u4-co1-q6","type":"input","prompt":"(2 + 5i) + (−2 − 3i) = bi. What is b?","answers":["2"],"hint":"The real parts cancel. Add the i parts.","solution":"2 + (−2) = 0 and 5i − 3i = 2i. So the sum is 2i and b = 2."},{"id":"u4-co1-q7","type":"choice","prompt":"Add 4i to (−3 + 2i).","choices":["−3 + 2i","−3 + 6i","1 + 2i","−3 + 8i"],"answer":1,"hint":"4i is an imaginary term, so it joins the 2i.","solution":"2i + 4i = 6i. The real part stays −3. Answer: −3 + 6i."},{"id":"u4-co1-q8","type":"input","prompt":"(4 + 3i) + (x + yi) = 10 − i. What is x?","answers":["6"],"hint":"Match the real parts on both sides.","solution":"Real parts: 4 + x = 10, so x = 6. (The i parts give 3 + y = −1, so y = −4.)"}]},{"id":"complex-operations-2","teach":[{"title":"Multiplying complex numbers","text":["Multiply like binomials (FOIL). Then replace i² with −1 and combine.","A number times a + bi is distributed to both parts."],"example":{"problem":"Multiply (2 + 3i)(1 + 4i)","steps":["First: 2 · 1 = 2. Outer: 2 · 4i = 8i. Inner: 3i · 1 = 3i. Last: 3i · 4i = 12i².","12i² = −12.","Combine: 2 − 12 + 8i + 3i = −10 + 11i."]}}],"questions":[{"id":"u4-co2-q1","type":"choice","prompt":"Multiply: 2(3 + 4i)","choices":["6 + 4i","5 + 6i","6 + 8","6 + 8i"],"answer":3,"hint":"Distribute the 2 to both parts.","solution":"2 · 3 = 6 and 2 · 4i = 8i. Answer: 6 + 8i."},{"id":"u4-co2-q2","type":"choice","prompt":"Multiply: i(3 + 2i)","choices":["−2 + 3i","2 + 3i","3 + 2i","−2 − 3i"],"answer":0,"hint":"Distribute i. Remember i² = −1.","solution":"i · 3 = 3i and i · 2i = 2i² = −2. Answer: −2 + 3i."},{"id":"u4-co2-q3","type":"choice","prompt":"Multiply: (4i)(5i)","choices":["20","20i","−20","−20i"],"answer":2,"hint":"4 · 5 = 20 and i · i = i².","solution":"20i² = 20(−1) = −20."},{"id":"u4-co2-q4","type":"choice","prompt":"Multiply: (1 + 2i)(3 + i)","choices":["5 + 7i","1 + 5i","1 + 7i","3 + 2i"],"answer":2,"hint":"FOIL, then use i² = −1.","solution":"3 + i + 6i + 2i² = 3 + 7i − 2 = 1 + 7i."},{"id":"u4-co2-q5","type":"choice","prompt":"Multiply: (2 − i)(4 + 3i)","choices":["11 + 2i","5 + 2i","11 − 2i","11 + 10i"],"answer":0,"hint":"The last term is (−i)(3i) = −3i², which is +3.","solution":"8 + 6i − 4i − 3i² = 8 + 2i + 3 = 11 + 2i."},{"id":"u4-co2-q6","type":"input","prompt":"(3 + 2i)(3 − 2i) is a real number. What is it?","answers":["13"],"hint":"The i terms cancel. The last term is −4i² = +4.","solution":"9 − 6i + 6i − 4i² = 9 + 4 = 13."},{"id":"u4-co2-q7","type":"choice","prompt":"Multiply: (4 − 3i)²","choices":["25 − 24i","7 + 24i","16 − 9i","7 − 24i"],"answer":3,"hint":"Write (4 − 3i)(4 − 3i) and FOIL. Do not just square each term.","solution":"16 − 12i − 12i + 9i² = 16 − 24i − 9 = 7 − 24i."},{"id":"u4-co2-q8","type":"input","prompt":"(2 + 3i)(1 − i) = a + bi. What is a?","answers":["5"],"hint":"FOIL. The last term is −3i².","solution":"2 − 2i + 3i − 3i² = 2 + i + 3 = 5 + i. So a = 5."}]},{"id":"complex-operations-3","teach":[{"title":"Conjugates","text":["The conjugate of a + bi is a − bi. Only the sign of the i part changes.","A number times its conjugate is always real: (a + bi)(a − bi) = a² + b²."],"example":{"problem":"Multiply (5 + 2i)(5 − 2i)","steps":["This is a number times its conjugate.","a² + b² = 25 + 4 = 29.","Answer: 29"]}},{"title":"Dividing complex numbers","text":["You cannot leave i in the denominator. Multiply the top and bottom by the conjugate of the denominator.","The denominator becomes a real number, then split into a + bi form."],"example":{"problem":"Simplify 6 / (1 + i)","steps":["Multiply top and bottom by 1 − i.","Top: 6(1 − i) = 6 − 6i. Bottom: (1 + i)(1 − i) = 1 + 1 = 2.","6 − 6i over 2 = 3 − 3i."]}}],"questions":[{"id":"u4-co3-q1","type":"choice","prompt":"What is the conjugate of 3 + 7i?","choices":["−3 + 7i","3 − 7i","−3 − 7i","7 + 3i"],"answer":1,"hint":"Change only the sign of the i part.","solution":"The conjugate of 3 + 7i is 3 − 7i."},{"id":"u4-co3-q2","type":"choice","prompt":"What is the conjugate of −2 − 5i?","choices":["2 + 5i","−2 + 5i","2 − 5i","−5 − 2i"],"answer":1,"hint":"Keep the real part. Flip the sign of the i part.","solution":"The conjugate of −2 − 5i is −2 + 5i."},{"id":"u4-co3-q3","type":"input","prompt":"(4 + 3i)(4 − 3i) = ?","answers":["25"],"hint":"A number times its conjugate is a² + b².","solution":"4² + 3² = 16 + 9 = 25."},{"id":"u4-co3-q4","type":"choice","prompt":"Simplify 4 / (1 + i).","choices":["2 + 2i","4 − 4i","4 − i","2 − 2i"],"answer":3,"hint":"Multiply top and bottom by 1 − i.","solution":"4(1 − i) = 4 − 4i. Bottom: 1² + 1² = 2. (4 − 4i) / 2 = 2 − 2i."},{"id":"u4-co3-q5","type":"choice","prompt":"Simplify 10 / (3 − i).","choices":["3 + i","3 − i","30 + 10i","1 + 3i"],"answer":0,"hint":"The conjugate of 3 − i is 3 + i.","solution":"10(3 + i) = 30 + 10i. Bottom: 9 + 1 = 10. (30 + 10i) / 10 = 3 + i."},{"id":"u4-co3-q6","type":"choice","prompt":"Simplify (2 + i) / (1 − i).","choices":["3/2 + (1/2)i","1/2 − (3/2)i","1/2 + (3/2)i","1 + 3i"],"answer":2,"hint":"Multiply top and bottom by 1 + i. Then divide both parts by the denominator.","solution":"Top: (2 + i)(1 + i) = 2 + 2i + i + i² = 1 + 3i. Bottom: 1 + 1 = 2. So the answer is 1/2 + (3/2)i."},{"id":"u4-co3-q7","type":"input","prompt":"You multiply (3 + i)/(2 + i) top and bottom by 2 − i. What is the new denominator?","answers":["5"],"hint":"(2 + i)(2 − i) = 2² + 1².","solution":"4 + 1 = 5."},{"id":"u4-co3-q8","type":"choice","prompt":"Simplify (3 + i) / (2 + i).","choices":["7/5 + (1/5)i","5 − i","7/5 − (1/5)i","1/5 − (7/5)i"],"answer":2,"hint":"Multiply top and bottom by 2 − i.","solution":"Top: (3 + i)(2 − i) = 6 − 3i + 2i − i² = 7 − i. Bottom: 5. So the answer is 7/5 − (1/5)i."}]},{"id":"complex-operations-4","teach":[{"title":"Putting it together","text":["Work in steps: do powers and products first, then add and subtract, and divide last. Always finish in a + bi form.","Check: i² = −1 and 1/i = −i."],"example":{"problem":"Simplify (2 + i)² + 3i","steps":["(2 + i)² = 4 + 4i + i² = 3 + 4i.","Add 3i: 3 + 4i + 3i = 3 + 7i."]}}],"questions":[{"id":"u4-co4-q1","type":"choice","prompt":"Simplify (1 + i)².","choices":["2i","2","2 + 2i","0"],"answer":0,"hint":"(1 + i)(1 + i) = 1 + 2i + i².","solution":"1 + 2i + i² = 1 + 2i − 1 = 2i."},{"id":"u4-co4-q2","type":"choice","prompt":"Simplify (2 + 3i) + (1 − i)(2 + i).","choices":["5 + 4i","3 + 2i","5 − 2i","5 + 2i"],"answer":3,"hint":"Do the multiplication first.","solution":"(1 − i)(2 + i) = 2 + i − 2i − i² = 3 − i. Then (2 + 3i) + (3 − i) = 5 + 2i."},{"id":"u4-co4-q3","type":"input","prompt":"Evaluate (2 + 3i)(2 − 3i) + i². Give a number.","answers":["12"],"hint":"The first product is a number times its conjugate.","solution":"(2 + 3i)(2 − 3i) = 4 + 9 = 13. i² = −1. 13 + (−1) = 12."},{"id":"u4-co4-q4","type":"input","prompt":"Evaluate x² − 2x + 2 when x = 1 + i. Give a number.","answers":["0"],"hint":"Find (1 + i)² first.","solution":"(1 + i)² = 2i. Then 2i − 2(1 + i) + 2 = 2i − 2 − 2i + 2 = 0."},{"id":"u4-co4-q5","type":"choice","prompt":"Simplify (3 + 2i) / i.","choices":["2 + 3i","2 − 3i","−2 − 3i","3 + 2i"],"answer":1,"hint":"Multiply top and bottom by −i (the conjugate of i).","solution":"(3 + 2i)(−i) = −3i − 2i² = 2 − 3i. Bottom: i · (−i) = −i² = 1. Answer: 2 − 3i."},{"id":"u4-co4-q6","type":"input","prompt":"If z = 2 + 5i, what is z times its conjugate?","answers":["29"],"hint":"Use a² + b².","solution":"2² + 5² = 4 + 25 = 29."},{"id":"u4-co4-q7","type":"choice","prompt":"Simplify (5 + 5i) / (1 + 2i).","choices":["3 + i","3 − i","15 − 5i","−1 − i"],"answer":1,"hint":"Multiply top and bottom by 1 − 2i.","solution":"Top: 5 − 10i + 5i − 10i² = 15 − 5i. Bottom: 1 + 4 = 5. (15 − 5i) / 5 = 3 − i."},{"id":"u4-co4-q8","type":"input","prompt":"(1 + 2i)(3 − i) = a + bi. What is b?","answers":["5"],"hint":"FOIL carefully, then use i² = −1.","solution":"3 − i + 6i − 2i² = 3 + 5i + 2 = 5 + 5i. So b = 5."}]}]},{"id":"completing-square","title":"Completing the square","lessons":[{"id":"completing-square-1","teach":[{"title":"The number that completes the square","text":["x² + bx + c is a perfect square when c = (b/2)². Half of b, squared.","Then x² + bx + (b/2)² = (x + b/2)²."],"example":{"problem":"Find c so that x² + 6x + c is a perfect square","steps":["Half of 6 is 3.","3² = 9, so c = 9.","x² + 6x + 9 = (x + 3)²."]}}],"questions":[{"id":"u4-cs1-q1","type":"input","prompt":"x² + 8x + c is a perfect square. What is c?","answers":["16"],"hint":"Half of 8, then square it.","solution":"8/2 = 4 and 4² = 16."},{"id":"u4-cs1-q2","type":"input","prompt":"x² + 10x + c is a perfect square. What is c?","answers":["25"],"hint":"Half of 10, then square it.","solution":"10/2 = 5 and 5² = 25."},{"id":"u4-cs1-q3","type":"input","prompt":"x² − 12x + c is a perfect square. What is c?","answers":["36"],"hint":"Half of −12 is −6. Squaring removes the sign.","solution":"(−12/2)² = (−6)² = 36."},{"id":"u4-cs1-q4","type":"choice","prompt":"Which is the factored form of x² + 6x + 9?","choices":["(x − 3)²","(x + 9)²","(x + 3)²","(x + 3)(x − 3)"],"answer":2,"hint":"The middle term is 2 · 3 · x.","solution":"x² + 6x + 9 = (x + 3)(x + 3) = (x + 3)²."},{"id":"u4-cs1-q5","type":"choice","prompt":"Which is the factored form of x² − 14x + 49?","choices":["(x − 7)²","(x + 7)²","(x − 14)²","(x − 7)(x + 7)"],"answer":0,"hint":"The middle term is negative, so the sign inside is negative.","solution":"49 = 7² and 2 · 7 = 14. So x² − 14x + 49 = (x − 7)²."},{"id":"u4-cs1-q6","type":"input","prompt":"x² + 3x + c is a perfect square. What is c? Give a fraction or decimal.","answers":["9/4"],"hint":"Half of 3 is 3/2.","solution":"(3/2)² = 9/4."},{"id":"u4-cs1-q7","type":"input","prompt":"x² − 5x + c is a perfect square. What is c? Give a fraction or decimal.","answers":["25/4"],"hint":"Half of −5 is −5/2.","solution":"(−5/2)² = 25/4."},{"id":"u4-cs1-q8","type":"choice","prompt":"Which is a perfect square trinomial?","choices":["x² + 10x + 10","x² + 10x + 20","x² + 10x + 100","x² + 10x + 25"],"answer":3,"hint":"Check whether the last term is (half of 10) squared.","solution":"Half of 10 is 5 and 5² = 25. Only x² + 10x + 25 = (x + 5)² works."}]},{"id":"completing-square-2","teach":[{"title":"Solving by completing the square (a = 1)","text":["1) Move the constant to the right side. 2) Add (b/2)² to both sides. 3) Factor the left side as a square. 4) Take square roots, remembering ±. 5) Solve for x."],"example":{"problem":"Solve x² + 6x = 7","steps":["Half of 6 is 3. 3² = 9. Add 9 to both sides: x² + 6x + 9 = 16.","Factor: (x + 3)² = 16.","Square root: x + 3 = ±4.","x = −3 + 4 = 1 or x = −3 − 4 = −7."]}}],"questions":[{"id":"u4-cs2-q1","type":"input","prompt":"Solve by completing the square: x² + 4x = 5","answers":["1, -5"],"hint":"Add (4/2)² = 4 to both sides.","solution":"x² + 4x + 4 = 9, so (x + 2)² = 9. x + 2 = ±3, so x = 1 or x = −5."},{"id":"u4-cs2-q2","type":"input","prompt":"Solve by completing the square: x² − 6x = 16","answers":["8, -2"],"hint":"Add 9 to both sides.","solution":"x² − 6x + 9 = 25, so (x − 3)² = 25. x − 3 = ±5, so x = 8 or x = −2."},{"id":"u4-cs2-q3","type":"input","prompt":"Solve: x² + 10x + 21 = 0","answers":["-3, -7"],"hint":"Move 21 to the right side first.","solution":"x² + 10x = −21. Add 25: (x + 5)² = 4. x + 5 = ±2, so x = −3 or x = −7."},{"id":"u4-cs2-q4","type":"input","prompt":"Solve: x² − 2x − 15 = 0","answers":["5, -3"],"hint":"Move 15 to the right. Then add (−2/2)² = 1.","solution":"x² − 2x = 15, so (x − 1)² = 16. x − 1 = ±4, so x = 5 or x = −3."},{"id":"u4-cs2-q5","type":"input","prompt":"To complete the square for x² + 12x = 5, what number do you add to both sides?","answers":["36"],"hint":"(b/2)² with b = 12.","solution":"12/2 = 6 and 6² = 36."},{"id":"u4-cs2-q6","type":"input","prompt":"Solve: x² − 8x + 7 = 0","answers":["7, 1"],"hint":"x² − 8x = −7. Add 16.","solution":"(x − 4)² = 9, so x − 4 = ±3. x = 7 or x = 1."},{"id":"u4-cs2-q7","type":"choice","prompt":"Solve x² + 4x − 1 = 0 by completing the square.","choices":["x = 2 ± √5","x = −2 ± √5","x = −2 ± √3","x = −4 ± √5"],"answer":1,"hint":"x² + 4x = 1. Add 4 to both sides.","solution":"(x + 2)² = 5. x + 2 = ±√5, so x = −2 ± √5."},{"id":"u4-cs2-q8","type":"choice","prompt":"Solve x² + 2x + 5 = 0 by completing the square.","choices":["x = 1 ± 2i","x = −1 ± 2i","x = −1 ± 2","x = −1 ± 4i"],"answer":1,"hint":"x² + 2x = −5. Add 1 to both sides.","solution":"(x + 1)² = −4. x + 1 = ±2i, so x = −1 ± 2i."}]},{"id":"completing-square-3","teach":[{"title":"When a is not 1","text":["Divide every term by a first so the x² coefficient is 1. Then complete the square as before.","You can also solve a fractional b, such as x² + 5x: half of 5 is 5/2."],"example":{"problem":"Solve 2x² + 8x = 10","steps":["Divide by 2: x² + 4x = 5.","Add 4: (x + 2)² = 9.","x + 2 = ±3, so x = 1 or x = −5."]}}],"questions":[{"id":"u4-cs3-q1","type":"input","prompt":"Solve: 2x² + 12x = 14","answers":["1, -7"],"hint":"Divide every term by 2.","solution":"x² + 6x = 7. Add 9: (x + 3)² = 16. x = 1 or x = −7."},{"id":"u4-cs3-q2","type":"input","prompt":"Solve: 3x² − 12x = 15","answers":["5, -1"],"hint":"Divide every term by 3.","solution":"x² − 4x = 5. Add 4: (x − 2)² = 9. x − 2 = ±3, so x = 5 or x = −1."},{"id":"u4-cs3-q3","type":"input","prompt":"Solve: x² + 3x − 10 = 0","answers":["2, -5"],"hint":"Add (3/2)² = 9/4 to both sides.","solution":"x² + 3x = 10. Add 9/4: (x + 3/2)² = 49/4. x + 3/2 = ±7/2, so x = 2 or x = −5."},{"id":"u4-cs3-q4","type":"input","prompt":"Solve: 2x² + 12x − 14 = 0","answers":["1, -7"],"hint":"Move the 14 first, then divide by 2.","solution":"2x² + 12x = 14, so x² + 6x = 7. This gives (x + 3)² = 16, x = 1 or x = −7."},{"id":"u4-cs3-q5","type":"choice","prompt":"What is the first step in solving 4x² − 8x = 12 by completing the square?","choices":["Add 4 to both sides","Add 16 to both sides","Take the square root of both sides","Divide every term by 4"],"answer":3,"hint":"Get the coefficient of x² to be 1.","solution":"Divide by 4: x² − 2x = 3. Then add (−2/2)² = 1."},{"id":"u4-cs3-q6","type":"input","prompt":"Solve: 5x² + 20x = −15","answers":["-1, -3"],"hint":"Divide by 5 first.","solution":"x² + 4x = −3. Add 4: (x + 2)² = 1. x + 2 = ±1, so x = −1 or x = −3."},{"id":"u4-cs3-q7","type":"input","prompt":"Solve: 2x² − 12x + 10 = 0","answers":["5, 1"],"hint":"Move 10, then divide by 2.","solution":"2x² − 12x = −10, so x² − 6x = −5. Add 9: (x − 3)² = 4. x = 5 or x = 1."},{"id":"u4-cs3-q8","type":"input","prompt":"Solve: x² + 5x + 4 = 0","answers":["-1, -4"],"hint":"x² + 5x = −4. Half of 5 is 5/2.","solution":"Add 25/4: (x + 5/2)² = 9/4. x + 5/2 = ±3/2, so x = −1 or x = −4."}]},{"id":"completing-square-4","teach":[{"title":"Rewriting in vertex form","text":["Vertex form is y = a(x − h)² + k. To get it, complete the square on the x terms. Whatever you add inside, subtract right away so nothing changes.","The vertex is (h, k)."],"example":{"problem":"Write y = x² + 6x + 5 in vertex form","steps":["Group x terms: y = (x² + 6x) + 5.","Add and subtract 9: y = (x² + 6x + 9) − 9 + 5.","y = (x + 3)² − 4. The vertex is (−3, −4)."]}},{"title":"Vertex form when a is not 1","text":["Factor a out of the x terms first. Then complete the square inside. Remember what you add inside is multiplied by a."],"example":{"problem":"Write y = 2x² + 8x + 3 in vertex form","steps":["Factor 2 from the x terms: y = 2(x² + 4x) + 3.","Add 4 inside. That is really adding 2 · 4 = 8, so subtract 8: y = 2(x² + 4x + 4) − 8 + 3.","y = 2(x + 2)² − 5."]}}],"questions":[{"id":"u4-cs4-q1","type":"choice","prompt":"Write y = x² + 4x + 1 in vertex form.","choices":["y = (x + 2)² − 3","y = (x + 2)² + 1","y = (x − 2)² − 3","y = (x + 4)² − 15"],"answer":0,"hint":"Add and subtract 4.","solution":"y = (x² + 4x + 4) − 4 + 1 = (x + 2)² − 3."},{"id":"u4-cs4-q2","type":"choice","prompt":"Write y = x² − 10x + 30 in vertex form.","choices":["y = (x + 5)² + 5","y = (x − 5)² + 30","y = (x − 5)² + 5","y = (x − 5)² − 5"],"answer":2,"hint":"Add and subtract 25.","solution":"y = (x² − 10x + 25) − 25 + 30 = (x − 5)² + 5."},{"id":"u4-cs4-q3","type":"input","prompt":"y = x² + 8x + 20 in vertex form is y = (x + 4)² + k. What is k?","answers":["4"],"hint":"Add and subtract 16.","solution":"y = (x² + 8x + 16) − 16 + 20 = (x + 4)² + 4. So k = 4."},{"id":"u4-cs4-q4","type":"choice","prompt":"What is the vertex of y = x² − 6x + 2?","choices":["(−3, −7)","(3, 7)","(3, −7)","(6, 2)"],"answer":2,"hint":"Complete the square, then read (h, k) from y = (x − h)² + k.","solution":"y = (x² − 6x + 9) − 9 + 2 = (x − 3)² − 7. The vertex is (3, −7)."},{"id":"u4-cs4-q5","type":"choice","prompt":"Write y = 2x² + 12x + 7 in vertex form.","choices":["y = 2(x + 3)² − 11","y = 2(x + 3)² − 2","y = 2(x + 3)² + 7","y = (x + 3)² − 11"],"answer":0,"hint":"Factor 2 from the x terms. The 9 you add inside counts 2 · 9 = 18.","solution":"y = 2(x² + 6x + 9) − 18 + 7 = 2(x + 3)² − 11."},{"id":"u4-cs4-q6","type":"choice","prompt":"Write y = −x² + 4x − 3 in vertex form.","choices":["y = −(x − 2)² − 7","y = −(x + 2)² + 1","y = (x − 2)² + 1","y = −(x − 2)² + 1"],"answer":3,"hint":"Factor −1 from the x terms: −(x² − 4x). Then add 4 inside.","solution":"y = −(x² − 4x + 4) + 4 − 3 = −(x − 2)² + 1."},{"id":"u4-cs4-q7","type":"input","prompt":"y = x² − 4x + 9 in vertex form is y = (x − 2)² + k. What is k?","answers":["5"],"hint":"Add and subtract 4.","solution":"y = (x² − 4x + 4) − 4 + 9 = (x − 2)² + 5. So k = 5."},{"id":"u4-cs4-q8","type":"choice","prompt":"What is the vertex of y = 3x² − 12x + 5?","choices":["(−2, −7)","(2, −7)","(2, 5)","(2, −12)"],"answer":1,"hint":"Factor 3 from the x terms, complete the square, and remember the 3.","solution":"y = 3(x² − 4x + 4) − 12 + 5 = 3(x − 2)² − 7. The vertex is (2, −7)."}]}]},{"id":"quadratic-formula","title":"Quadratic formula and discriminant","lessons":[{"id":"quadratic-formula-1","teach":[{"title":"The discriminant","text":["For ax² + bx + c = 0, the discriminant is D = b² − 4ac. It tells you what kind of solutions to expect.","D > 0: two real solutions. D = 0: one real solution (repeated). D < 0: no real solutions, two complex solutions."],"example":{"problem":"Find the discriminant of x² + 2x + 5","steps":["a = 1, b = 2, c = 5.","D = b² − 4ac = 2² − 4(1)(5) = 4 − 20 = −16.","D < 0, so there are two complex solutions."]}}],"questions":[{"id":"u4-qf1-q1","type":"input","prompt":"Find the discriminant of x² − 6x + 5.","answers":["16"],"hint":"a = 1, b = −6, c = 5. Square b first: (−6)² = 36.","solution":"D = 36 − 4(1)(5) = 36 − 20 = 16."},{"id":"u4-qf1-q2","type":"input","prompt":"Find the discriminant of 2x² + 3x − 2.","answers":["25"],"hint":"c is negative, so −4ac adds.","solution":"D = 9 − 4(2)(−2) = 9 + 16 = 25."},{"id":"u4-qf1-q3","type":"input","prompt":"Find the discriminant of x² + 4x + 4.","answers":["0"],"hint":"b² = 16 and 4ac = 16.","solution":"D = 16 − 16 = 0."},{"id":"u4-qf1-q4","type":"input","prompt":"Find the discriminant of 3x² − 2x + 1.","answers":["-8"],"hint":"4ac = 4 · 3 · 1 = 12.","solution":"D = (−2)² − 12 = 4 − 12 = −8."},{"id":"u4-qf1-q5","type":"choice","prompt":"Find the discriminant of x² + 3x − 10. What does it tell you?","choices":["D = 49: two complex solutions","D = −31: two complex solutions","D = 49: two real solutions","D = 0: one real solution"],"answer":2,"hint":"D = 9 − 4(1)(−10). Is it positive, zero or negative?","solution":"D = 9 + 40 = 49 > 0, so there are two real solutions."},{"id":"u4-qf1-q6","type":"choice","prompt":"The discriminant of a quadratic is 0. How many real solutions does it have?","choices":["One real solution","Two real solutions","Two complex solutions","No solutions of any kind"],"answer":0,"hint":"The ± √D part disappears when D = 0.","solution":"If D = 0, then x = −b / 2a only. One real (repeated) solution."},{"id":"u4-qf1-q7","type":"choice","prompt":"What type of solutions does x² + 2x + 7 = 0 have?","choices":["Two real solutions","One real solution","Two real irrational solutions","Two complex solutions"],"answer":3,"hint":"Find D = b² − 4ac first.","solution":"D = 4 − 28 = −24 < 0, so there are two complex (non-real) solutions."},{"id":"u4-qf1-q8","type":"input","prompt":"x² + kx + 9 = 0 has exactly one real solution, and k > 0. What is k?","answers":["6"],"hint":"One solution means D = 0. Write D = k² − 36.","solution":"k² − 36 = 0, so k² = 36 and k = 6 (since k > 0)."}]},{"id":"quadratic-formula-2","teach":[{"title":"Number and type of solutions","text":["If D > 0 and D is a perfect square (1, 4, 9, 16, 25, ...), the two real solutions are rational. If D > 0 and not a perfect square, they are irrational.","For a parabola, D < 0 means it never crosses the x-axis. D = 0 means it touches the x-axis once."],"example":{"problem":"What type of solutions does x² − x − 1 = 0 have?","steps":["D = (−1)² − 4(1)(−1) = 1 + 4 = 5.","5 > 0, so two real solutions.","5 is not a perfect square, so they are irrational."]}}],"questions":[{"id":"u4-qf2-q1","type":"choice","prompt":"What type of solutions does 5x² − x + 2 = 0 have?","choices":["Two real solutions","Two complex solutions","One real solution","Two real rational solutions"],"answer":1,"hint":"D = (−1)² − 4(5)(2).","solution":"D = 1 − 40 = −39 < 0, so two complex solutions."},{"id":"u4-qf2-q2","type":"choice","prompt":"What type of solutions does 4x² − 12x + 9 = 0 have?","choices":["Two real solutions","One real solution","Two complex solutions","Two irrational solutions"],"answer":1,"hint":"D = 144 − 4(4)(9).","solution":"D = 144 − 144 = 0, so one real (repeated) solution."},{"id":"u4-qf2-q3","type":"choice","prompt":"What type of solutions does x² − x − 1 = 0 have?","choices":["Two real rational solutions","One real solution","Two complex solutions","Two real irrational solutions"],"answer":3,"hint":"D = 1 + 4. Is it a perfect square?","solution":"D = 5 > 0 but 5 is not a perfect square. So two real irrational solutions."},{"id":"u4-qf2-q4","type":"choice","prompt":"What type of solutions does 6x² + x − 2 = 0 have?","choices":["Two real rational solutions","Two real irrational solutions","One real solution","Two complex solutions"],"answer":0,"hint":"D = 1 − 4(6)(−2).","solution":"D = 1 + 48 = 49 = 7². A positive perfect square, so two real rational solutions."},{"id":"u4-qf2-q5","type":"input","prompt":"x² + 5x + c = 0 has discriminant 9. What is c?","answers":["4"],"hint":"D = 25 − 4c.","solution":"25 − 4c = 9, so 4c = 16 and c = 4."},{"id":"u4-qf2-q6","type":"choice","prompt":"For which values of c does x² + 4x + c = 0 have two complex solutions?","choices":["c < 4","c > 16","c > 4","c = 4"],"answer":2,"hint":"You need D < 0. D = 16 − 4c.","solution":"16 − 4c < 0, so 4c > 16 and c > 4. Dividing by a positive number does not flip the sign."},{"id":"u4-qf2-q7","type":"input","prompt":"How many real solutions does −2x² + 3x − 5 = 0 have?","answers":["0"],"hint":"D = 9 − 4(−2)(−5). Careful with signs.","solution":"D = 9 − 40 = −31 < 0. There are 0 real solutions."},{"id":"u4-qf2-q8","type":"choice","prompt":"Does the parabola y = x² − 4x + 7 cross the x-axis?","choices":["Yes, twice, because D = 44","Yes, once, because D = 0","No, because D = −12","No, because D = 12"],"answer":2,"hint":"The x-intercepts are the solutions of x² − 4x + 7 = 0.","solution":"D = 16 − 28 = −12 < 0. No real solutions, so no x-intercepts."}]},{"id":"quadratic-formula-3","teach":[{"title":"The quadratic formula","text":["For ax² + bx + c = 0: x = (−b ± √(b² − 4ac)) / (2a).","Put the equation in standard form first so you read a, b, c correctly. The ± gives two answers."],"example":{"problem":"Solve 2x² + 5x − 3 = 0","steps":["a = 2, b = 5, c = −3. D = 25 + 24 = 49.","x = (−5 ± 7) / 4.","x = 2/4 = 1/2 or x = −12/4 = −3."]}}],"questions":[{"id":"u4-qf3-q1","type":"input","prompt":"Solve with the quadratic formula: x² + 5x + 6 = 0","answers":["-2, -3"],"hint":"D = 25 − 24 = 1.","solution":"x = (−5 ± 1) / 2, so x = −2 or x = −3."},{"id":"u4-qf3-q2","type":"input","prompt":"Solve with the quadratic formula: x² − 7x + 10 = 0","answers":["5, 2"],"hint":"a = 1, b = −7, so −b = 7.","solution":"D = 49 − 40 = 9. x = (7 ± 3) / 2 = 5 or 2."},{"id":"u4-qf3-q3","type":"input","prompt":"Solve: 2x² − 7x + 3 = 0","answers":["3, 1/2"],"hint":"D = 49 − 24 = 25.","solution":"x = (7 ± 5) / 4. x = 12/4 = 3 or x = 2/4 = 1/2."},{"id":"u4-qf3-q4","type":"input","prompt":"Solve: 3x² + 10x + 8 = 0","answers":["-4/3, -2"],"hint":"D = 100 − 96 = 4.","solution":"x = (−10 ± 2) / 6. x = −8/6 = −4/3 or x = −12/6 = −2."},{"id":"u4-qf3-q5","type":"input","prompt":"Solve: 4x² − 4x − 3 = 0","answers":["3/2, -1/2"],"hint":"D = 16 + 48 = 64.","solution":"x = (4 ± 8) / 8. x = 12/8 = 3/2 or x = −4/8 = −1/2."},{"id":"u4-qf3-q6","type":"choice","prompt":"Solve x² − 2x − 1 = 0.","choices":["x = 1 ± √2","x = 2 ± √2","x = −1 ± √2","x = 1 ± 2√2"],"answer":0,"hint":"D = 4 + 4 = 8. √8 = 2√2.","solution":"x = (2 ± 2√2) / 2 = 1 ± √2."},{"id":"u4-qf3-q7","type":"choice","prompt":"Solve x² + 6x + 4 = 0.","choices":["x = −3 ± 2√5","x = 3 ± √5","x = −6 ± 2√5","x = −3 ± √5"],"answer":3,"hint":"D = 36 − 16 = 20. √20 = 2√5.","solution":"x = (−6 ± 2√5) / 2 = −3 ± √5. Divide both parts by 2."},{"id":"u4-qf3-q8","type":"input","prompt":"Solve: x² − 4x − 12 = 0","answers":["6, -2"],"hint":"D = 16 + 48 = 64.","solution":"x = (4 ± 8) / 2 = 6 or −2."}]},{"id":"quadratic-formula-4","teach":[{"title":"When the discriminant is negative","text":["A negative D gives √(−D) = i√D. The solutions are complex, in the form a ± bi.","Simplify by dividing every part of the numerator by 2a."],"example":{"problem":"Solve x² − 2x + 5 = 0","steps":["D = 4 − 20 = −16.","x = (2 ± √(−16)) / 2 = (2 ± 4i) / 2.","x = 1 ± 2i."]}}],"questions":[{"id":"u4-qf4-q1","type":"choice","prompt":"Solve x² + 2x + 5 = 0.","choices":["x = 1 ± 2i","x = −1 ± 2i","x = −2 ± 4i","x = −1 ± 2"],"answer":1,"hint":"D = 4 − 20 = −16, so √D = 4i.","solution":"x = (−2 ± 4i) / 2 = −1 ± 2i."},{"id":"u4-qf4-q2","type":"choice","prompt":"Solve x² − 4x + 13 = 0.","choices":["x = 2 ± 6i","x = 2 ± 3i","x = −2 ± 3i","x = 4 ± 3i"],"answer":1,"hint":"D = 16 − 52 = −36.","solution":"x = (4 ± 6i) / 2 = 2 ± 3i."},{"id":"u4-qf4-q3","type":"choice","prompt":"Solve x² + 6x + 10 = 0.","choices":["x = −3 ± 2i","x = 3 ± i","x = −6 ± i","x = −3 ± i"],"answer":3,"hint":"D = 36 − 40 = −4.","solution":"x = (−6 ± 2i) / 2 = −3 ± i."},{"id":"u4-qf4-q4","type":"choice","prompt":"Solve 2x² − 4x + 5 = 0.","choices":["x = 1 ± (√6/2)i","x = 1 ± i√6","x = 2 ± (√6/2)i","x = −1 ± (√6/2)i"],"answer":0,"hint":"D = 16 − 40 = −24. √(−24) = 2i√6.","solution":"x = (4 ± 2i√6) / 4 = 1 ± (√6/2)i."},{"id":"u4-qf4-q5","type":"input","prompt":"Solve: x² − 6x + 9 = 0","answers":["3"],"hint":"Find D first. It is 0.","solution":"D = 36 − 36 = 0, so x = 6/2 = 3."},{"id":"u4-qf4-q6","type":"input","prompt":"The solutions of x² − 10x + 34 = 0 are 5 ± 3i. What is the real part of each solution?","answers":["5"],"hint":"Read the part with no i.","solution":"D = 100 − 136 = −36, x = (10 ± 6i) / 2 = 5 ± 3i. The real part is 5."},{"id":"u4-qf4-q7","type":"input","prompt":"Solve: x² − 3x − 4 = 0","answers":["4, -1"],"hint":"D = 9 + 16 = 25.","solution":"x = (3 ± 5) / 2 = 4 or −1."},{"id":"u4-qf4-q8","type":"choice","prompt":"Which equation has a discriminant of −7?","choices":["x² − x − 2 = 0","x² + 3x + 2 = 0","x² + x + 2 = 0","x² + 4x + 4 = 0"],"answer":2,"hint":"Work out b² − 4ac for each.","solution":"x² + x + 2: 1 − 8 = −7. The others give 9, 1 and 0."}]}]},{"id":"applications","title":"Quadratic applications","lessons":[{"id":"applications-1","teach":[{"title":"The projectile model","text":["An object thrown or dropped, with height in feet and time in seconds: h(t) = −16t² + vt + s.","v is the starting upward speed in ft/s (0 if dropped). s is the starting height in feet. At t = 0, h = s."],"example":{"problem":"Describe h(t) = −16t² + 48t + 5","steps":["s = 5, so it starts 5 ft above the ground.","v = 48, so it is thrown upward at 48 ft/s.","At t = 1: h(1) = −16 + 48 + 5 = 37 ft."]}}],"questions":[{"id":"u4-ap1-q1","type":"input","prompt":"h(t) = −16t² + 32t + 6. How many feet above the ground does it start?","answers":["6"],"hint":"Set t = 0.","solution":"h(0) = 6, so it starts 6 ft up."},{"id":"u4-ap1-q2","type":"input","prompt":"h(t) = −16t² + 60t + 2. What is the initial upward velocity in ft/s?","answers":["60"],"hint":"Look at the coefficient of t.","solution":"v is the coefficient of t, so v = 60 ft/s."},{"id":"u4-ap1-q3","type":"input","prompt":"h(t) = −16t² + 40t + 3. Find h(1), the height in feet after 1 second.","answers":["27"],"hint":"Substitute t = 1.","solution":"h(1) = −16 + 40 + 3 = 27 ft."},{"id":"u4-ap1-q4","type":"choice","prompt":"A ball is thrown upward at 50 ft/s from a height of 8 ft. Which model fits?","choices":["h(t) = −16t² + 8t + 50","h(t) = 16t² + 50t + 8","h(t) = −16t² + 50t + 8","h(t) = −16t² − 50t + 8"],"answer":2,"hint":"v goes with t. The starting height is the constant. Gravity makes the t² term negative.","solution":"h(t) = −16t² + vt + s with v = 50 and s = 8."},{"id":"u4-ap1-q5","type":"input","prompt":"h(t) = −16t² + 64t + 4. Find h(2).","answers":["68"],"hint":"t² = 4.","solution":"h(2) = −16(4) + 64(2) + 4 = −64 + 128 + 4 = 68 ft."},{"id":"u4-ap1-q6","type":"input","prompt":"A rock is dropped from 100 ft, so h(t) = −16t² + 100. Find h(2).","answers":["36"],"hint":"Dropped means no upward velocity.","solution":"h(2) = −16(4) + 100 = −64 + 100 = 36 ft."},{"id":"u4-ap1-q7","type":"choice","prompt":"A ball is dropped from the top of a 144-ft building. Which model fits?","choices":["h(t) = −16t² + 144","h(t) = −16t² + 144t","h(t) = −16t² + 144t + 144","h(t) = 16t² + 144"],"answer":0,"hint":"Dropped means v = 0, so there is no t term.","solution":"v = 0 and s = 144, so h(t) = −16t² + 144."},{"id":"u4-ap1-q8","type":"input","prompt":"h(t) = −16t² + 48t + 10. Find h(3).","answers":["10"],"hint":"Compute −16(9) + 48(3).","solution":"h(3) = −144 + 144 + 10 = 10 ft. It is back at its starting height."}]},{"id":"applications-2","teach":[{"title":"Maximum height and time to the top","text":["The graph is a parabola that opens down, so the vertex is the highest point.","Time to the top: t = −b/(2a). Max height: plug that t into h(t)."],"example":{"problem":"Find the max height of h(t) = −16t² + 64t + 5","steps":["t = −64 / (2 · −16) = 2 seconds.","h(2) = −16(4) + 64(2) + 5 = −64 + 128 + 5.","Max height: 69 ft."]}}],"questions":[{"id":"u4-ap2-q1","type":"input","prompt":"h(t) = −16t² + 32t + 4. At what time (in seconds) is the ball highest?","answers":["1"],"hint":"t = −b / (2a).","solution":"t = −32 / (2 · −16) = 1 second."},{"id":"u4-ap2-q2","type":"input","prompt":"h(t) = −16t² + 32t + 4. What is the maximum height in feet?","answers":["20"],"hint":"Plug the time from the last question into h(t).","solution":"h(1) = −16 + 32 + 4 = 20 ft."},{"id":"u4-ap2-q3","type":"input","prompt":"h(t) = −16t² + 80t. At what time (in seconds) is the object highest?","answers":["5/2"],"hint":"a = −16 and b = 80.","solution":"t = −80 / (−32) = 2.5 seconds."},{"id":"u4-ap2-q4","type":"input","prompt":"h(t) = −16t² + 80t. What is the maximum height in feet?","answers":["100"],"hint":"Use t = 2.5.","solution":"h(2.5) = −16(6.25) + 80(2.5) = −100 + 200 = 100 ft."},{"id":"u4-ap2-q5","type":"input","prompt":"h(t) = −16t² + 96t + 10. At what time (in seconds) is it highest?","answers":["3"],"hint":"t = −b / (2a).","solution":"t = −96 / (−32) = 3 seconds."},{"id":"u4-ap2-q6","type":"input","prompt":"h(t) = −16t² + 96t + 10. What is the maximum height in feet?","answers":["154"],"hint":"Plug t = 3 into h(t).","solution":"h(3) = −16(9) + 96(3) + 10 = −144 + 288 + 10 = 154 ft."},{"id":"u4-ap2-q7","type":"choice","prompt":"Which formula gives the time when h(t) = at² + bt + c is at its maximum?","choices":["t = b / (2a)","t = −b / a","t = −2a / b","t = −b / (2a)"],"answer":3,"hint":"This is the x-coordinate of the vertex.","solution":"The vertex of a parabola is at t = −b / (2a)."},{"id":"u4-ap2-q8","type":"input","prompt":"h(t) = −16t² + 16t + 3. What is the maximum height in feet?","answers":["7"],"hint":"The top is at t = 16/32 = 1/2.","solution":"h(0.5) = −16(0.25) + 16(0.5) + 3 = −4 + 8 + 3 = 7 ft."}]},{"id":"applications-3","teach":[{"title":"When does it hit the ground?","text":["The ground is height 0. Set h(t) = 0 and solve. Factor or use the quadratic formula.","Time cannot be negative, so throw away any negative solution."],"example":{"problem":"When does h(t) = −16t² + 32t + 48 hit the ground?","steps":["Set −16t² + 32t + 48 = 0 and divide by −16: t² − 2t − 3 = 0.","Factor: (t − 3)(t + 1) = 0, so t = 3 or t = −1.","Negative time is not possible. It lands after 3 seconds."]}}],"questions":[{"id":"u4-ap3-q1","type":"input","prompt":"h(t) = −16t² + 64t. At what time (in seconds, other than t = 0) is h = 0?","answers":["4"],"hint":"Factor out −16t.","solution":"−16t(t − 4) = 0, so t = 0 or t = 4. It lands at t = 4 seconds."},{"id":"u4-ap3-q2","type":"input","prompt":"A rock is dropped from 144 ft: h(t) = −16t² + 144. How many seconds until it lands?","answers":["3"],"hint":"Set h = 0 and solve for t².","solution":"16t² = 144, t² = 9, t = 3 (not −3)."},{"id":"u4-ap3-q3","type":"input","prompt":"h(t) = −16t² + 16t + 32. How many seconds until it lands?","answers":["2"],"hint":"Divide by −16: t² − t − 2 = 0.","solution":"(t − 2)(t + 1) = 0, so t = 2 or t = −1. Only t = 2 makes sense."},{"id":"u4-ap3-q4","type":"input","prompt":"h(t) = −16t² + 48t + 160. How many seconds until it lands?","answers":["5"],"hint":"Divide by −16: t² − 3t − 10 = 0.","solution":"(t − 5)(t + 2) = 0, so t = 5 or t = −2. It lands at 5 seconds."},{"id":"u4-ap3-q5","type":"choice","prompt":"When solving h(t) = 0 you get t = 4 and t = −1. Which do you keep, and why?","choices":["t = −1, because it is smaller","t = 4, because time cannot be negative","Both, because a quadratic has two answers","t = 4, because it is the larger zero"],"answer":1,"hint":"Think about what t stands for.","solution":"t is time after launch, so it has to be 0 or more. Keep t = 4."},{"id":"u4-ap3-q6","type":"input","prompt":"h(t) = −16t² + 20t + 6. Use the formula to find the landing time in seconds.","answers":["3/2"],"hint":"D = 400 + 384 = 784 = 28².","solution":"a = −16, b = 20, c = 6. t = (−20 ± 28) / (−32). That gives (−48) / (−32) = 3/2 or 8 / (−32) = −1/4. Keep 3/2 seconds."},{"id":"u4-ap3-q7","type":"input","prompt":"A rock is dropped from 400 ft. How many seconds until it lands?","answers":["5"],"hint":"h(t) = −16t² + 400. Set it to 0.","solution":"16t² = 400, t² = 25, t = 5 seconds."},{"id":"u4-ap3-q8","type":"choice","prompt":"h(t) = −16t² + 8t + 3. When does it hit the ground?","choices":["−1/4 second","3/4 second","1/4 second","3/2 seconds"],"answer":1,"hint":"D = 64 + 192 = 256 = 16².","solution":"a = −16, b = 8, c = 3. t = (−8 ± 16) / (−32). That gives (−24) / (−32) = 3/4 or 8 / (−32) = −1/4. Keep 3/4."}]},{"id":"applications-4","teach":[{"title":"Area problems","text":["Name the unknown side x. Write the other side in terms of x. Write area = length × width, set up the equation, and solve. Reject answers that are negative or make no sense.","For a fence problem, the perimeter or fence length gives a relationship between the sides."],"example":{"problem":"A rectangle is 3 ft longer than it is wide and has area 40 ft². Find the width.","steps":["Let width = w, so length = w + 3. Then w(w + 3) = 40.","w² + 3w − 40 = 0, so (w + 8)(w − 5) = 0.","w = 5 (not −8). The width is 5 ft."]}},{"title":"Maximum area","text":["If the area is a quadratic with a negative leading coefficient, its vertex gives the maximum area."],"example":{"problem":"60 ft of fence makes 3 sides of a rectangle against a barn. What width x gives the most area?","steps":["The two widths use 2x. The length is 60 − 2x.","Area A = x(60 − 2x) = −2x² + 60x.","Vertex: x = −60 / (2 · −2) = 15 ft."]}}],"questions":[{"id":"u4-ap4-q1","type":"input","prompt":"A rectangle is 4 ft longer than it is wide, and its area is 60 ft². What is the width in feet?","answers":["6"],"hint":"w(w + 4) = 60 gives w² + 4w − 60 = 0.","solution":"(w + 10)(w − 6) = 0. The width is 6 ft."},{"id":"u4-ap4-q2","type":"input","prompt":"The length of a garden is twice its width, and the area is 72 ft². What is the width in feet?","answers":["6"],"hint":"w · 2w = 72.","solution":"2w² = 72, so w² = 36 and w = 6."},{"id":"u4-ap4-q3","type":"input","prompt":"A rectangle has perimeter 36 ft and area 80 ft². How long is its shorter side in feet?","answers":["8"],"hint":"The sides add to 18. If one side is w, the other is 18 − w.","solution":"w(18 − w) = 80, so w² − 18w + 80 = 0. (w − 8)(w − 10) = 0. The sides are 8 and 10. The shorter is 8."},{"id":"u4-ap4-q4","type":"input","prompt":"60 ft of fence makes 3 sides of a rectangle against a barn. The width is x, so A = x(60 − 2x). What x gives the most area?","answers":["15"],"hint":"A = −2x² + 60x. Use x = −b / (2a).","solution":"x = −60 / (−4) = 15 ft."},{"id":"u4-ap4-q5","type":"input","prompt":"For the fence above, what is the maximum area in ft²?","answers":["450"],"hint":"Use x = 15 in A = x(60 − 2x).","solution":"A = 15 · (60 − 30) = 15 · 30 = 450 ft²."},{"id":"u4-ap4-q6","type":"input","prompt":"A ball is thrown from 24 ft at 40 ft/s: h(t) = −16t² + 40t + 24. What is its height after 2 seconds?","answers":["40"],"hint":"Substitute t = 2.","solution":"h(2) = −64 + 80 + 24 = 40 ft."},{"id":"u4-ap4-q7","type":"input","prompt":"For h(t) = −16t² + 40t + 24, how many seconds until it hits the ground?","answers":["3"],"hint":"Divide by −8: 2t² − 5t − 3 = 0.","solution":"(2t + 1)(t − 3) = 0, so t = −1/2 or t = 3. Keep t = 3 seconds."},{"id":"u4-ap4-q8","type":"choice","prompt":"For h(t) = −16t² + 40t + 24, what is the maximum height?","choices":["74 ft","40 ft","25 ft","49 ft"],"answer":3,"hint":"The top is at t = −40 / (−32) = 1.25 seconds.","solution":"h(1.25) = −16(1.5625) + 40(1.25) + 24 = −25 + 50 + 24 = 49 ft."}]}]}],"test":{"questions":[{"id":"u4-t-q1","type":"choice","prompt":"What is the vertex of y = −2(x + 4)² + 9, and does it open up or down?","choices":["(4, 9), opens down","(−4, 9), opens up","(−4, 9), opens down","(−4, −9), opens down"],"answer":2,"hint":"In y = a(x − h)² + k the vertex is (h, k). The sign of a decides the direction.","solution":"x + 4 = x − (−4), so h = −4. k = 9. a = −2 is negative, so it opens down."},{"id":"u4-t-q2","type":"input","prompt":"What is the minimum value of y = (x − 7)² − 11?","answers":["-11"],"hint":"The minimum of a parabola that opens up is the k value of the vertex.","solution":"Vertex is (7, −11). a = 1 > 0, so the minimum value is −11."},{"id":"u4-t-q3","type":"input","prompt":"Find the axis of symmetry of y = 3x² − 18x + 4. Give the value of x.","answers":["3"],"hint":"x = −b / (2a).","solution":"x = 18 / 6 = 3."},{"id":"u4-t-q4","type":"choice","prompt":"What is the range of y = −x² + 6x − 5?","choices":["y ≤ 4","y ≥ 4","y ≤ 3","y ≥ 3"],"answer":0,"hint":"Find the vertex. The parabola opens down.","solution":"x = −6 / (−2) = 3. y = −9 + 18 − 5 = 4. It opens down, so the range is y ≤ 4."},{"id":"u4-t-q5","type":"choice","prompt":"Factor 10x² − 9x − 9.","choices":["(2x + 3)(5x − 3)","(10x + 3)(x − 3)","(2x − 3)(5x − 3)","(2x − 3)(5x + 3)"],"answer":3,"hint":"Try pairs for 6x² and for −3. Check the middle term by FOIL.","solution":"(2x − 3)(5x + 3) = 10x² + 6x − 15x − 9 = 10x² − 9x − 9."},{"id":"u4-t-q6","type":"choice","prompt":"Factor 49x² − 64.","choices":["(7x − 8)²","(7x − 8)(7x + 8)","(7x + 8)²","(49x − 8)(x + 8)"],"answer":1,"hint":"This is a difference of squares: a² − b².","solution":"49x² = (7x)² and 64 = 8². So it is (7x − 8)(7x + 8)."},{"id":"u4-t-q7","type":"input","prompt":"Solve: x² − x = 42","answers":["7, -6"],"hint":"Subtract 42 from both sides first.","solution":"x² − x − 42 = 0. (x − 7)(x + 6) = 0, so x = 7 or x = −6."},{"id":"u4-t-q8","type":"input","prompt":"Solve: 3x² = 12x","answers":["0, 4"],"hint":"Do not divide by x. Move everything to one side and factor.","solution":"3x² − 12x = 0. 3x(x − 4) = 0. x = 0 or x = 4."},{"id":"u4-t-q9","type":"input","prompt":"Solve: 2(x − 1)² = 50","answers":["6, -4"],"hint":"Divide by 2 first.","solution":"(x − 1)² = 25. x − 1 = ±5. x = 6 or x = −4."},{"id":"u4-t-q10","type":"choice","prompt":"Solve x² = 45.","choices":["x = ±9√5","x = ±3√5","x = ±5√3","x = ±15"],"answer":1,"hint":"√45 = √9 · √5.","solution":"x = ±√45 = ±√9 · √5 = ±3√5."},{"id":"u4-t-q11","type":"choice","prompt":"What are the solutions of (x + 5)² = −4?","choices":["x = −5 ± 2, two real solutions","x = 5 ± 2i, no real solutions","x = −5 ± 4i, no real solutions","x = −5 ± 2i, no real solutions"],"answer":3,"hint":"The square root of a negative number is not real.","solution":"x + 5 = ±√(−4) = ±2i. So x = −5 ± 2i. There are no real solutions."},{"id":"u4-t-q12","type":"choice","prompt":"Simplify √(−72).","choices":["6i√2","2i√6","36i√2","6√2"],"answer":0,"hint":"72 = 36 · 2.","solution":"√(−72) = i√72 = i · 6√2 = 6i√2."},{"id":"u4-t-q13","type":"choice","prompt":"Simplify i³¹.","choices":["i","1","−i","−1"],"answer":2,"hint":"Divide 31 by 4. Use the remainder.","solution":"31 = 4 · 7 + 3. i³ = −i."},{"id":"u4-t-q14","type":"input","prompt":"x² = −121. The solutions are ±bi. What is b?","answers":["11"],"hint":"11 · 11 = 121.","solution":"x = ±√(−121) = ±11i. So b = 11."},{"id":"u4-t-q15","type":"choice","prompt":"Simplify (7 − 2i) − (3 − 9i).","choices":["4 − 11i","10 + 7i","4 + 7i","4 − 7i"],"answer":2,"hint":"Distribute the minus sign to both parts.","solution":"7 − 3 = 4 and −2i + 9i = 7i. Answer: 4 + 7i."},{"id":"u4-t-q16","type":"choice","prompt":"Multiply: (3 + 4i)(2 − 5i)","choices":["26 − 7i","−14 − 7i","26 + 7i","6 − 20i"],"answer":0,"hint":"FOIL. The last term is (4i)(−5i) = −20i² = +20.","solution":"6 − 15i + 8i − 20i² = 6 − 7i + 20 = 26 − 7i."},{"id":"u4-t-q17","type":"choice","prompt":"Simplify 12 / (3 − 3i).","choices":["2 − 2i","4 + 4i","36 + 36i","2 + 2i"],"answer":3,"hint":"Multiply top and bottom by 3 + 3i.","solution":"Top: 12(3 + 3i) = 36 + 36i. Bottom: 9 + 9 = 18. (36 + 36i) / 18 = 2 + 2i."},{"id":"u4-t-q18","type":"input","prompt":"x² + 14x + c is a perfect square. What is c?","answers":["49"],"hint":"(b/2)².","solution":"(14/2)² = 49."},{"id":"u4-t-q19","type":"choice","prompt":"Solve x² − 8x + 3 = 0 by completing the square.","choices":["x = 4 ± √3","x = 4 ± √13","x = −4 ± √13","x = 4 ± √19"],"answer":1,"hint":"x² − 8x = −3. Add 16 to both sides.","solution":"(x − 4)² = 13. x = 4 ± √13."},{"id":"u4-t-q20","type":"input","prompt":"Find the discriminant of 5x² − 4x − 2.","answers":["56"],"hint":"D = b² − 4ac, and c is negative.","solution":"D = 16 − 4(5)(−2) = 16 + 40 = 56."},{"id":"u4-t-q21","type":"choice","prompt":"Solve x² − 4x + 6 = 0.","choices":["x = 4 ± i√2","x = 2 ± i√2","x = 2 ± 2i√2","x = 2 ± √2"],"answer":1,"hint":"D = 16 − 24 = −8.","solution":"x = (4 ± √(−8)) / 2 = (4 ± 2i√2) / 2 = 2 ± i√2."},{"id":"u4-t-q22","type":"input","prompt":"Solve with the quadratic formula: 6x² + x − 2 = 0","answers":["1/2, -2/3"],"hint":"D = 1 + 48 = 49.","solution":"x = (−1 ± 7) / 12. x = 6/12 = 1/2 or x = −8/12 = −2/3."},{"id":"u4-t-q23","type":"input","prompt":"h(t) = −16t² + 72t + 8. What is the maximum height in feet?","answers":["89"],"hint":"The top is at t = 72 / 32 = 2.25.","solution":"h(2.25) = −16(5.0625) + 72(2.25) + 8 = −81 + 162 + 8 = 89 ft."},{"id":"u4-t-q24","type":"input","prompt":"A rock is dropped from 256 ft. How many seconds until it lands?","answers":["4"],"hint":"h(t) = −16t² + 256. Set h = 0.","solution":"16t² = 256, t² = 16, t = 4 seconds."}]}},{"format":1,"id":"unit-5-polynomial-functions","title":"Unit 5: Polynomial Functions","levels":[{"id":"monomials","title":"Monomials and exponent rules","lessons":[{"id":"monomials-1","teach":[{"title":"What a monomial is","text":["A monomial is a number, a variable, or a product of numbers and variables, like 7, x, or −4a²b.","To simplify, multiply the numbers together. Then use the exponent rules on each variable."],"example":{"problem":"Simplify 5x² · −7x⁶","steps":["Numbers first: 5 · −7 = −35.","Same base x, so add the exponents: 2 + 6 = 8.","5x² · −7x⁶ = −35x⁸"]}},{"title":"Product rule and power rule","text":["Product rule: x^a · x^b = x^(a + b). Same base, so add the exponents.","Power rule: (x^a)^b = x^(a · b). A power of a power, so multiply the exponents.","A power of a product raises every factor, including the number: (2x³)² = 4x⁶."],"example":{"problem":"Simplify (−2a³b)² · 8ab⁹","steps":["Square everything in the parentheses: (−2)² = 4, (a³)² = a⁶, b² stays b².","So you have 4a⁶b² · 8ab⁹.","Multiply the numbers: 4 · 8 = 32. Add exponents: a⁶ · a¹ = a⁷ and b² · b⁹ = b¹¹.","Answer: 32a⁷b¹¹"]}}],"questions":[{"id":"mo1-q1","type":"choice","prompt":"Which shows the right way to simplify x⁴ · x⁵?","choices":["Add the exponents: x⁹","Multiply the exponents: x²⁰","Subtract the exponents: x⁻¹","Add the bases: 2x⁹"],"answer":0,"hint":"The bases are the same and they are being multiplied.","solution":"Product rule: same base, so add the exponents. x⁴ · x⁵ = x⁴⁺⁵ = x⁹."},{"id":"mo1-q2","type":"input","prompt":"x³ · x⁸ = x^n. What is n?","answers":["11"],"hint":"Multiplying with the same base means adding the exponents.","solution":"Product rule: 3 + 8 = 11, so x³ · x⁸ = x¹¹."},{"id":"mo1-q3","type":"input","prompt":"(x⁴)⁵ = x^n. What is n?","answers":["20"],"hint":"A power raised to a power: multiply the exponents.","solution":"Power rule: 4 · 5 = 20, so (x⁴)⁵ = x²⁰."},{"id":"mo1-q4","type":"choice","prompt":"Simplify (2x³y)³.","choices":["8x⁹y³","6x⁹y³","8x⁶y³","2x⁹y³"],"answer":0,"hint":"Cube every factor in the parentheses, including the 2.","solution":"2³ = 8, (x³)³ = x⁹, and y³ stays y³. So (2x³y)³ = 8x⁹y³."},{"id":"mo1-q5","type":"choice","prompt":"Simplify (−4a³b²)² · (3a²b).","choices":["48a⁸b⁵","−48a⁸b⁵","−24a⁸b⁵","48a¹²b³"],"answer":0,"hint":"Square the first part first. A negative number squared is positive.","solution":"(−4a³b²)² = 16a⁶b⁴. Then 16a⁶b⁴ · 3a²b: 16 · 3 = 48, a⁶ · a² = a⁸, b⁴ · b = b⁵. Answer: 48a⁸b⁵."},{"id":"mo1-q6","type":"choice","prompt":"Simplify (−8x⁴y³)(2x⁵y²) + 7x⁹y⁵.","choices":["−9x⁹y⁵","−23x⁹y⁵","−16x²⁰y⁶ + 7x⁹y⁵","9x⁹y⁵"],"answer":0,"hint":"Multiply first. Then check whether the two terms are like terms.","solution":"(−8x⁴y³)(2x⁵y²) = −16x⁹y⁵. It is a like term with 7x⁹y⁵, so combine: −16 + 7 = −9. Answer: −9x⁹y⁵."},{"id":"mo1-q7","type":"input","prompt":"Subtract −3n² from −7n². The answer is kn². What is k?","answers":["-4"],"hint":"\"Subtract A from B\" means B − A.","solution":"−7n² − (−3n²) = −7n² + 3n² = −4n², so k = −4."},{"id":"mo1-q8","type":"choice","prompt":"The side of a cube is 2x⁵. If the side length is doubled, which expression is the new volume?","choices":["64x¹⁵","16x¹⁵","8x¹⁵","64x⁸"],"answer":0,"hint":"Double the side first: 2 · 2x⁵. Then cube it.","solution":"New side = 4x⁵. Volume = (4x⁵)³ = 4³ · x¹⁵ = 64x¹⁵."}]},{"id":"monomials-2","teach":[{"title":"Quotient rule","text":["Quotient rule: x^a / x^b = x^(a − b). Same base, so subtract the exponents.","Reduce the numbers like a fraction. If a variable ends up with a negative exponent, move it to the bottom."],"example":{"problem":"Simplify 15x¹⁰y⁴ / (24x¹²y³)","steps":["Numbers: 15/24 reduces to 5/8.","x: 10 − 12 = −2, so x⁻² = 1/x². The x² goes on the bottom.","y: 4 − 3 = 1, so y stays on top.","Answer: 5y / (8x²)"]}},{"title":"Negative and zero exponents","text":["Negative exponent rule: x^(−a) = 1/x^a. A negative exponent means \"flip it to the other side of the fraction.\"","Zero exponent rule: x⁰ = 1, for any base that is not 0. So (2x³)⁰ = 1.","Final answers use positive exponents only."],"example":{"problem":"Simplify (14w¹² / 7w³)⁻¹","steps":["Simplify inside first: 14/7 = 2 and w¹²⁻³ = w⁹. So you have (2w⁹)⁻¹.","A −1 exponent flips it: (2w⁹)⁻¹ = 1 / (2w⁹).","Answer: 1 / (2w⁹)"]}}],"questions":[{"id":"mo2-q1","type":"choice","prompt":"What is x⁻⁴ written with a positive exponent?","choices":["1/x⁴","−x⁴","x⁴","−1/x⁴"],"answer":0,"hint":"A negative exponent does not make the number negative.","solution":"Negative exponent rule: x⁻⁴ = 1/x⁴."},{"id":"mo2-q2","type":"input","prompt":"What is (5a²b⁷)⁰?","answers":["1"],"hint":"Think about the zero exponent rule.","solution":"Anything (except 0) raised to the zero power is 1. So (5a²b⁷)⁰ = 1."},{"id":"mo2-q3","type":"input","prompt":"x¹² / x⁴ = x^n. What is n?","answers":["8"],"hint":"Dividing with the same base means subtracting the exponents.","solution":"Quotient rule: 12 − 4 = 8, so x¹² / x⁴ = x⁸."},{"id":"mo2-q4","type":"choice","prompt":"Simplify 18w⁴x⁹ / (14w⁵x⁵).","choices":["9x⁴/(7w)","9wx⁴/7","9x¹⁴/(7w⁹)","4x⁴/w"],"answer":0,"hint":"Reduce 18/14. Then subtract the exponents for w and for x.","solution":"18/14 = 9/7. w: 4 − 5 = −1, so w goes on the bottom. x: 9 − 5 = 4. Answer: 9x⁴/(7w)."},{"id":"mo2-q5","type":"choice","prompt":"Simplify 5c⁻⁷d² · (−cd²)⁴.","choices":["5d¹⁰/c³","−5d¹⁰/c³","5c³d¹⁰","5d¹⁰/c¹¹"],"answer":0,"hint":"Raise (−cd²) to the 4th power first. An even power makes the negative positive.","solution":"(−cd²)⁴ = c⁴d⁸. Then 5c⁻⁷d² · c⁴d⁸ = 5c⁻³d¹⁰. Move c⁻³ to the bottom: 5d¹⁰/c³."},{"id":"mo2-q6","type":"choice","prompt":"Simplify 15x²y · −6x⁷y / (3xy)².","choices":["−10x⁷","10x⁷","−30x⁷","−10x⁷y"],"answer":0,"hint":"Simplify the top, then square every factor in (3xy)².","solution":"Top: 15 · −6 = −90, x²·x⁷ = x⁹, y·y = y². So −90x⁹y². Bottom: (3xy)² = 9x²y². Divide: −90/9 = −10, x⁹⁻² = x⁷, y²⁻² = y⁰ = 1. Answer: −10x⁷."},{"id":"mo2-q7","type":"input","prompt":"Simplify (c/c²)⁴ · (−3c)⁴. The answer is a whole number. What is it?","answers":["81"],"hint":"c/c² = c⁻¹. Then raise each part to the 4th power.","solution":"(c/c²)⁴ = (c⁻¹)⁴ = c⁻⁴. (−3c)⁴ = 81c⁴. Multiply: 81c⁻⁴⁺⁴ = 81c⁰ = 81."},{"id":"mo2-q8","type":"choice","prompt":"Simplify 54m⁶n⁴ / (3m²n) − 10m⁴n³.","choices":["8m⁴n³","28m⁴n³","8m⁸n⁵","−8m⁴n³"],"answer":0,"hint":"Divide first. Then check whether you can combine like terms.","solution":"54m⁶n⁴ / (3m²n) = 18m⁴n³. That is a like term with 10m⁴n³: 18 − 10 = 8. Answer: 8m⁴n³."},{"id":"mo2-q9","type":"choice","prompt":"Which two monomials have a product of −84a⁶b¹⁰?","choices":["12a²b⁵ and −7a⁴b⁵","12a³b⁵ and −7a²b⁵","−42a⁶b⁵ and 2b²","−12a³b² and 7a²b⁸"],"answer":0,"hint":"Multiply the numbers and add the exponents for each choice.","solution":"12 · −7 = −84, a²·a⁴ = a⁶, b⁵·b⁵ = b¹⁰. So 12a²b⁵ · −7a⁴b⁵ = −84a⁶b¹⁰."}]},{"id":"monomials-3","teach":[{"title":"Signs and powers","text":["A negative number raised to an even power is positive. Raised to an odd power, it stays negative: (−2)⁴ = 16, but (−2)³ = −8.","Watch the parentheses. In −x², only x is squared, so −x² is negative. In (−x)², the negative is squared too, so (−x)² = x²."],"example":{"problem":"Simplify (−3x²y⁴)³ · 2xy","steps":["Cube everything in the parentheses: (−3)³ = −27, (x²)³ = x⁶, (y⁴)³ = y¹².","So you have −27x⁶y¹² · 2xy.","Multiply the numbers: −27 · 2 = −54. Add the exponents: x⁶ · x = x⁷ and y¹² · y = y¹³.","Answer: −54x⁷y¹³"]}},{"title":"A variable with no exponent","text":["A variable written alone has an exponent of 1: x = x¹.","Count that 1 when you add exponents: x⁴ · x = x⁵, not x⁴."],"example":{"problem":"Simplify 4a³b · 5ab²","steps":["Numbers: 4 · 5 = 20.","a: a³ · a¹ = a⁴.","b: b¹ · b² = b³.","Answer: 20a⁴b³"]}}],"questions":[{"id":"mo3-q1","type":"input","prompt":"x⁶ · x · x³ = x^n. What is n?","answers":["10"],"hint":"The x in the middle has an exponent of 1.","solution":"Add all three exponents: 6 + 1 + 3 = 10, so x⁶ · x · x³ = x¹⁰."},{"id":"mo3-q2","type":"input","prompt":"What is (−2)⁵?","answers":["-32"],"hint":"An odd power of a negative number stays negative.","solution":"(−2)⁵ = (−2)(−2)(−2)(−2)(−2) = −32. The exponent 5 is odd, so the answer is negative."},{"id":"mo3-q3","type":"choice","prompt":"Simplify (−5a³b)³.","choices":["−125a⁹b³","125a⁹b³","−15a⁹b³","−125a⁶b³"],"answer":0,"hint":"Cube every factor: the −5, the a³, and the b.","solution":"(−5)³ = −125, (a³)³ = a⁹, and b³ stays b³. Answer: −125a⁹b³."},{"id":"mo3-q4","type":"choice","prompt":"Simplify 4m³n² · (−6mn⁵).","choices":["−24m⁴n⁷","−24m³n⁷","−24m³n¹⁰","−2m⁴n⁷"],"answer":0,"hint":"Multiply the numbers. Then add the exponents of m and of n. The m in −6mn⁵ has an exponent of 1.","solution":"4 · (−6) = −24. m³ · m = m⁴. n² · n⁵ = n⁷. Answer: −24m⁴n⁷."},{"id":"mo3-q5","type":"input","prompt":"(3x⁴)² = kx⁸. What is k?","answers":["9"],"hint":"Square the 3 as well as the x⁴.","solution":"(3x⁴)² = 3² · (x⁴)² = 9x⁸, so k = 9."},{"id":"mo3-q6","type":"choice","prompt":"Simplify (2x⁴y)³ · (−x²y³)².","choices":["8x¹⁶y⁹","−8x¹⁶y⁹","6x¹⁶y⁹","8x⁴⁸y¹⁸"],"answer":0,"hint":"Do each power first. An even power makes the negative positive.","solution":"(2x⁴y)³ = 8x¹²y³ and (−x²y³)² = x⁴y⁶. Multiply: 8 · 1 = 8, x¹² · x⁴ = x¹⁶, y³ · y⁶ = y⁹. Answer: 8x¹⁶y⁹."},{"id":"mo3-q7","type":"choice","prompt":"Simplify (−2a²b³)⁴ · 3ab.","choices":["48a⁹b¹³","−48a⁹b¹³","−24a⁹b¹³","48a⁸b¹²"],"answer":0,"hint":"(−2)⁴ is positive. Don't forget the a and b in 3ab.","solution":"(−2a²b³)⁴ = 16a⁸b¹². Times 3ab: 16 · 3 = 48, a⁸ · a = a⁹, b¹² · b = b¹³. Answer: 48a⁹b¹³."},{"id":"mo3-q8","type":"choice","prompt":"Simplify 6x³y · (−2x²y)³ − 10x⁹y⁴.","choices":["−58x⁹y⁴","−38x⁹y⁴","−46x⁹y⁴","58x⁹y⁴"],"answer":0,"hint":"Cube first, then multiply, then combine the like terms.","solution":"(−2x²y)³ = −8x⁶y³. 6x³y · (−8x⁶y³) = −48x⁹y⁴. Then −48x⁹y⁴ − 10x⁹y⁴ = −58x⁹y⁴."},{"id":"mo3-q9","type":"choice","prompt":"A box has length 2x³, width 3x², and height 5x. Which expression is its volume?","choices":["30x⁶","30x⁵","10x⁶","10x⁵"],"answer":0,"hint":"Volume = length · width · height. The x in 5x has an exponent of 1.","solution":"2 · 3 · 5 = 30 and x³ · x² · x = x⁶. Volume: 30x⁶."}]},{"id":"monomials-4","teach":[{"title":"Negative exponents on the top and bottom","text":["Use the quotient rule on each variable: top exponent minus bottom exponent. Subtracting a negative exponent is the same as adding.","If an exponent ends up negative, move that variable to the bottom and make the exponent positive."],"example":{"problem":"Simplify 12a⁻²b⁵ / (−4a³b⁻¹)","steps":["Numbers: 12 / (−4) = −3.","a: −2 − 3 = −5, so a⁻⁵ = 1/a⁵. The a⁵ goes on the bottom.","b: 5 − (−1) = 6.","Answer: −3b⁶/a⁵"]}},{"title":"Power of a fraction","text":["Raise the top and the bottom to the power: (a/b)^n = a^n / b^n.","A negative power flips the fraction first: (a/b)^(−n) = (b/a)^n."],"example":{"problem":"Simplify (x²/(3y))⁻²","steps":["Flip the fraction to make the power positive: (3y/x²)².","Square the top and the bottom: (3y)² = 9y² and (x²)² = x⁴.","Answer: 9y²/x⁴"]}}],"questions":[{"id":"mo4-q1","type":"input","prompt":"x⁻³ · x⁷ = x^n. What is n?","answers":["4"],"hint":"Same base, so add the exponents. One of them is negative.","solution":"−3 + 7 = 4, so x⁻³ · x⁷ = x⁴."},{"id":"mo4-q2","type":"input","prompt":"y² / y⁹ = y^n. What is n?","answers":["-7"],"hint":"Same base, so subtract the exponents: top minus bottom.","solution":"2 − 9 = −7, so y² / y⁹ = y⁻⁷ = 1/y⁷."},{"id":"mo4-q3","type":"choice","prompt":"Write 6x⁻²y³ using positive exponents only.","choices":["6y³/x²","−6x²y³","y³/(6x²)","6x²y³"],"answer":0,"hint":"Only the x has a negative exponent. A negative exponent does not make the number negative.","solution":"x⁻² = 1/x², so x² moves to the bottom. The 6 and y³ stay on top: 6y³/x²."},{"id":"mo4-q4","type":"choice","prompt":"Simplify 20a⁵b² / (−5a²b⁶).","choices":["−4a³/b⁴","4a³/b⁴","−4a³b⁴","−4a⁷b⁸"],"answer":0,"hint":"Divide the numbers. Subtract the exponents: top minus bottom.","solution":"20 / (−5) = −4. a: 5 − 2 = 3. b: 2 − 6 = −4, so b⁴ goes on the bottom. Answer: −4a³/b⁴."},{"id":"mo4-q5","type":"choice","prompt":"Simplify (3x²/y⁴)³.","choices":["27x⁶/y¹²","9x⁶/y¹²","3x⁶/y¹²","27x⁵/y⁷"],"answer":0,"hint":"Cube the top and the bottom. Cube the 3 too.","solution":"Top: (3x²)³ = 27x⁶. Bottom: (y⁴)³ = y¹². Answer: 27x⁶/y¹²."},{"id":"mo4-q6","type":"choice","prompt":"Simplify (2a³b⁻²)⁻².","choices":["b⁴/(4a⁶)","4b⁴/a⁶","b⁴/(2a⁶)","a⁶/(4b⁴)"],"answer":0,"hint":"Multiply every exponent by −2, including the invisible 1 on the 2.","solution":"2⁻² = 1/4, (a³)⁻² = a⁻⁶, (b⁻²)⁻² = b⁴. So (1/4) · a⁻⁶ · b⁴ = b⁴/(4a⁶)."},{"id":"mo4-q7","type":"choice","prompt":"A rectangle has area 36x⁷y⁵ and length 4x³y². Which expression is its width?","choices":["9x⁴y³","32x⁴y³","9x¹⁰y⁷","144x¹⁰y⁷"],"answer":0,"hint":"Width = area ÷ length. Divide the numbers and subtract the exponents.","solution":"36 / 4 = 9. x: 7 − 3 = 4. y: 5 − 2 = 3. Width: 9x⁴y³."},{"id":"mo4-q8","type":"choice","prompt":"Simplify (4x³y⁻¹)² / (8x⁻²y³).","choices":["2x⁸/y⁵","2x⁴/y⁵","2x⁸y","x⁸/y⁵"],"answer":0,"hint":"Square the top first. Then subtract exponents. 6 − (−2) means 6 + 2.","solution":"Top: (4x³y⁻¹)² = 16x⁶y⁻². Divide: 16/8 = 2, x: 6 − (−2) = 8, y: −2 − 3 = −5. Answer: 2x⁸/y⁵."},{"id":"mo4-q9","type":"choice","prompt":"Simplify (9m⁴n⁻³ · 2m⁻⁶n⁵) / (6m⁻¹n).","choices":["3n/m","3n/m³","12n/m","3mn"],"answer":0,"hint":"Simplify the top first. Then subtract the exponents, watching the negatives.","solution":"Top: 18m⁻²n². Divide by 6m⁻¹n: 18/6 = 3, m: −2 − (−1) = −1, n: 2 − 1 = 1. So 3m⁻¹n = 3n/m."}]}]},{"id":"classify","title":"Standard form and classifying","lessons":[{"id":"classify-1","teach":[{"title":"Polynomials and degree","text":["A polynomial is a sum or difference of monomials. Each monomial is called a term.","The degree of a polynomial is its highest exponent.","Standard form lists the terms from the highest exponent to the lowest."],"example":{"problem":"Write −k⁵ − 1 + 8k − 3k³ + ¼k² in standard form.","steps":["Find each exponent: k⁵ (5), 1 (0), 8k (1), −3k³ (3), ¼k² (2).","Order them from 5 down to 0, keeping each sign with its term.","Answer: −k⁵ − 3k³ + ¼k² + 8k − 1"]}},{"title":"Naming polynomials","text":["By degree: 0 is constant, 1 is linear, 2 is quadratic, 3 is cubic, 4 is quartic, 5 is quintic.","By number of terms: 1 is a monomial, 2 is a binomial, 3 is a trinomial, 4 or more is a polynomial.","Give both names, degree first, like \"cubic binomial\"."],"example":{"problem":"Classify 9x⁵ − x⁴ + 2x.","steps":["The highest exponent is 5, so it is quintic.","It has 3 terms, so it is a trinomial.","Answer: quintic trinomial"]}}],"questions":[{"id":"cl1-q1","type":"input","prompt":"What is the degree of 4m³ − 9m² − m + 25?","answers":["3"],"hint":"The degree is the highest exponent.","solution":"The exponents are 3, 2, 1, and 0. The highest is 3, so the degree is 3."},{"id":"cl1-q2","type":"choice","prompt":"Write 25 − 9m² − m + 4m³ in standard form.","choices":["4m³ − 9m² − m + 25","25 − m − 9m² + 4m³","4m³ − m − 9m² + 25","−9m² + 4m³ − m + 25"],"answer":0,"hint":"Standard form goes from the highest exponent down to the lowest.","solution":"Exponents: 4m³ (3), −9m² (2), −m (1), 25 (0). In order: 4m³ − 9m² − m + 25."},{"id":"cl1-q3","type":"choice","prompt":"Classify 4m³ − 9m² − m + 25 by degree and number of terms.","choices":["cubic polynomial","cubic trinomial","quartic polynomial","quadratic polynomial"],"answer":0,"hint":"Count the terms. 4 or more terms is called a polynomial.","solution":"Degree 3 is cubic. It has 4 terms, so it is a polynomial. Answer: cubic polynomial."},{"id":"cl1-q4","type":"choice","prompt":"Write −½k³ + ¾k⁵ in standard form.","choices":["¾k⁵ − ½k³","−½k³ + ¾k⁵","¾k³ − ½k⁵","−¾k⁵ + ½k³"],"answer":0,"hint":"Put the k⁵ term first. Each sign stays with its own term.","solution":"The k⁵ term has the higher exponent, so it goes first: ¾k⁵ − ½k³."},{"id":"cl1-q5","type":"choice","prompt":"Classify ¾k⁵ − ½k³.","choices":["quintic binomial","cubic binomial","quintic trinomial","quartic binomial"],"answer":0,"hint":"Use the highest exponent for the degree name.","solution":"The highest exponent is 5 (quintic) and there are 2 terms (binomial). Answer: quintic binomial."},{"id":"cl1-q6","type":"input","prompt":"What is the degree of 14y² − x² − 3xy?","answers":["2"],"hint":"For a term like 3xy, add the exponents of x and y.","solution":"14y² has degree 2, −x² has degree 2, and −3xy has degree 1 + 1 = 2. The highest is 2."},{"id":"cl1-q7","type":"choice","prompt":"Classify 9x.","choices":["linear monomial","constant monomial","linear binomial","quadratic monomial"],"answer":0,"hint":"x has an exponent of 1.","solution":"9x has degree 1 (linear) and 1 term (monomial). Answer: linear monomial."},{"id":"cl1-q8","type":"choice","prompt":"Classify 24.","choices":["constant monomial","linear monomial","constant binomial","quadratic monomial"],"answer":0,"hint":"A number by itself has degree 0.","solution":"24 = 24x⁰, so the degree is 0 (constant). It is 1 term (monomial). Answer: constant monomial."}]},{"id":"classify-2","teach":[{"title":"Leading coefficient","text":["Once a polynomial is in standard form, the leading coefficient is the number in front of the first term.","If the first term is −x³, the leading coefficient is −1."],"example":{"problem":"Write y = 7 − 2x in standard form. Give its degree, name, and leading coefficient.","steps":["Standard form: y = −2x + 7.","Degree 1, so it is linear. 2 terms, so it is a binomial.","The first term is −2x, so the leading coefficient is −2."]}},{"title":"Simplify first, then classify","text":["If there are parentheses or like terms, simplify before you name the polynomial.","Expand any powers, combine like terms, then write it in standard form."],"example":{"problem":"Classify y = (x − 1)² + 2x.","steps":["(x − 1)² = x² − 2x + 1.","Add 2x: x² − 2x + 1 + 2x = x² + 1.","Degree 2 and 2 terms: quadratic binomial. Leading coefficient 1."]}}],"questions":[{"id":"cl2-q1","type":"input","prompt":"y = 2x − x³ − 8. What is the leading coefficient?","answers":["-1"],"hint":"Write it in standard form first. What number is in front of x³?","solution":"Standard form: y = −x³ + 2x − 8. The first term is −x³ = −1x³, so the leading coefficient is −1."},{"id":"cl2-q2","type":"choice","prompt":"Classify y = 2x − x³ − 8.","choices":["cubic trinomial","linear trinomial","cubic polynomial","cubic binomial"],"answer":0,"hint":"Find the highest exponent and count the terms.","solution":"Standard form is −x³ + 2x − 8: degree 3 (cubic) and 3 terms (trinomial)."},{"id":"cl2-q3","type":"choice","prompt":"Simplify y = 3x² + x³ − (x³ + x²), then classify it.","choices":["2x², quadratic monomial","2x³ + 4x², cubic binomial","2x² + 2x³, cubic binomial","2x², quadratic binomial"],"answer":0,"hint":"The minus sign goes to both terms in the parentheses.","solution":"3x² + x³ − x³ − x² = 2x². That is degree 2 (quadratic) with 1 term (monomial)."},{"id":"cl2-q4","type":"input","prompt":"y = (2x)³ + 3x − 1. What is the leading coefficient?","answers":["8"],"hint":"Cube both the 2 and the x.","solution":"(2x)³ = 8x³, so y = 8x³ + 3x − 1. The leading coefficient is 8."},{"id":"cl2-q5","type":"choice","prompt":"Write y = (x + 2)² + 3 in standard form.","choices":["x² + 4x + 7","x² + 7","x² + 2x + 7","x² + 4x + 5"],"answer":0,"hint":"(x + 2)² means (x + 2)(x + 2). Don't forget the middle term.","solution":"(x + 2)² = x² + 4x + 4. Add 3: x² + 4x + 7."},{"id":"cl2-q6","type":"choice","prompt":"Classify ½x³ − 2x² + 4x + 15.","choices":["cubic polynomial","cubic trinomial","quartic polynomial","cubic binomial"],"answer":0,"hint":"Count all 4 terms.","solution":"The highest exponent is 3 (cubic) and there are 4 terms (polynomial)."},{"id":"cl2-q7","type":"choice","prompt":"Classify −(3/2)x⁴.","choices":["quartic monomial","quadratic monomial","quartic binomial","constant monomial"],"answer":0,"hint":"A fraction in front does not change the degree.","solution":"The exponent is 4 (quartic) and there is 1 term (monomial)."},{"id":"cl2-q8","type":"choice","prompt":"Which is an example of a cubic binomial?","choices":["x³ − 2x","x³ − 2x² + 1","3x + 2","x² − 8"],"answer":0,"hint":"You need degree 3 and exactly 2 terms.","solution":"x³ − 2x has degree 3 and 2 terms. x³ − 2x² + 1 has 3 terms. 3x + 2 and x² − 8 are not degree 3."}]},{"id":"classify-3","teach":[{"title":"Degree with more than one variable","text":["The degree of a term is the sum of the exponents of its variables. 3x²y⁴ has degree 2 + 4 = 6.","The degree of the polynomial is the highest degree of any of its terms."],"example":{"problem":"Find the degree of 3x²y⁴ − 7xy³ + 2x⁵.","steps":["3x²y⁴: 2 + 4 = 6.","−7xy³: 1 + 3 = 4.","2x⁵: 5.","The highest is 6, so the degree is 6."]}},{"title":"Combine like terms before you count","text":["Count the terms only after the polynomial is simplified. Like terms combine into one term, and some may cancel."],"example":{"problem":"Classify 4x³ − 2x + 7 − 4x³ + x.","steps":["4x³ − 4x³ = 0, so the x³ terms cancel.","−2x + x = −x.","What is left: −x + 7.","Degree 1 and 2 terms: linear binomial."]}}],"questions":[{"id":"cl3-q1","type":"input","prompt":"What is the degree of the term −6x³y⁵?","answers":["8"],"hint":"Add the exponents of the variables.","solution":"x has exponent 3 and y has exponent 5. 3 + 5 = 8."},{"id":"cl3-q2","type":"input","prompt":"How many terms does 5x⁴ − 2x³ + x − 11 have?","answers":["4"],"hint":"Terms are separated by + and − signs.","solution":"The terms are 5x⁴, −2x³, x, and −11. That is 4 terms."},{"id":"cl3-q3","type":"input","prompt":"What is the degree of 2a⁴b − 9a²b³c + ab?","answers":["6"],"hint":"Find the degree of each term by adding its exponents. c has an exponent of 1.","solution":"2a⁴b: 4 + 1 = 5. −9a²b³c: 2 + 3 + 1 = 6. ab: 1 + 1 = 2. The highest is 6."},{"id":"cl3-q4","type":"choice","prompt":"Classify 7 − 3x² + x.","choices":["quadratic trinomial","linear trinomial","quadratic binomial","cubic trinomial"],"answer":0,"hint":"Find the highest exponent and count the terms.","solution":"The highest exponent is 2 (quadratic) and there are 3 terms (trinomial)."},{"id":"cl3-q5","type":"choice","prompt":"Classify −2y⁴ + 6.","choices":["quartic binomial","quadratic binomial","quartic monomial","cubic binomial"],"answer":0,"hint":"Degree 4 has a special name.","solution":"The highest exponent is 4 (quartic) and there are 2 terms (binomial)."},{"id":"cl3-q6","type":"choice","prompt":"Write 3x − 5x⁴ + 8 − x³ in standard form.","choices":["−5x⁴ − x³ + 3x + 8","5x⁴ − x³ + 3x + 8","−5x⁴ + x³ + 3x + 8","−5x⁴ − x³ + 3x − 8"],"answer":0,"hint":"Order the terms from the highest exponent down. Each sign moves with its own term.","solution":"Exponents: −5x⁴ (4), −x³ (3), 3x (1), 8 (0). In order: −5x⁴ − x³ + 3x + 8."},{"id":"cl3-q7","type":"choice","prompt":"Combine like terms, then classify: 4x³ − x + 2x³ + 9.","choices":["cubic trinomial","cubic polynomial","quadratic trinomial","cubic binomial"],"answer":0,"hint":"4x³ and 2x³ are like terms. Count the terms after you combine them.","solution":"4x³ + 2x³ = 6x³, so it simplifies to 6x³ − x + 9. Degree 3 (cubic) and 3 terms (trinomial)."},{"id":"cl3-q8","type":"choice","prompt":"Which polynomial is a quartic trinomial?","choices":["x⁴ − 3x² + 7","x⁴ − 3x³ + x² − 7","4x³ − x + 2","x⁴ + 3x"],"answer":0,"hint":"You need degree 4 and exactly 3 terms.","solution":"x⁴ − 3x² + 7 has degree 4 and 3 terms. x⁴ − 3x³ + x² − 7 has 4 terms, 4x³ − x + 2 is cubic, and x⁴ + 3x has 2 terms."},{"id":"cl3-q9","type":"input","prompt":"What is the degree of 8m²n³ − m⁴ + 5mn?","answers":["5"],"hint":"The biggest single exponent is not always the degree. Add the exponents in each term.","solution":"8m²n³: 2 + 3 = 5. −m⁴: 4. 5mn: 2. The highest is 5, so the degree is 5."}]},{"id":"classify-4","teach":[{"title":"Standard form with two variables","text":["Find the degree of each term by adding its exponents.","Write the terms from the highest degree to the lowest. A number with no variable goes last."],"example":{"problem":"Write 6x²y − 4 + x³y² + 2xy in standard form.","steps":["Degrees: 6x²y is 3, −4 is 0, x³y² is 5, 2xy is 2.","Order them 5, 3, 2, 0.","Answer: x³y² + 6x²y + 2xy − 4"]}},{"title":"Expand before you classify","text":["Multiply out any parentheses and combine like terms first. Terms can cancel, so the degree can drop.","Then name the polynomial and read the leading coefficient from standard form."],"example":{"problem":"Classify y = (2x − 1)² − 4x² and give its leading coefficient.","steps":["(2x − 1)² = 4x² − 4x + 1.","Subtract 4x²: 4x² − 4x + 1 − 4x² = −4x + 1.","Degree 1 and 2 terms: linear binomial. The leading coefficient is −4."]}}],"questions":[{"id":"cl4-q1","type":"input","prompt":"y = 5x² − 3x⁴ + x − 2. What is the leading coefficient?","answers":["-3"],"hint":"Find the term with the highest exponent. Its number is the leading coefficient.","solution":"The highest exponent is 4, in −3x⁴. In standard form y = −3x⁴ + 5x² + x − 2, so the leading coefficient is −3."},{"id":"cl4-q2","type":"input","prompt":"y = −(2x)³ + x² − 1. What is the leading coefficient?","answers":["-8"],"hint":"Cube the 2 and the x, then keep the minus sign in front.","solution":"(2x)³ = 8x³, so −(2x)³ = −8x³. y = −8x³ + x² − 1, and the leading coefficient is −8."},{"id":"cl4-q3","type":"choice","prompt":"Write 4ab − 2a³b² + 7 + a²b in standard form.","choices":["−2a³b² + a²b + 4ab + 7","2a³b² + a²b + 4ab + 7","−2a³b² + a²b + 4ab − 7","−2a³b² − a²b + 4ab + 7"],"answer":0,"hint":"Add the exponents in each term to get its degree. Keep each sign with its term.","solution":"Degrees: 4ab is 2, −2a³b² is 5, 7 is 0, a²b is 3. Order 5, 3, 2, 0: −2a³b² + a²b + 4ab + 7."},{"id":"cl4-q4","type":"input","prompt":"Simplify y = (x − 5)(x + 2) − x². What is the degree of the result?","answers":["1"],"hint":"Multiply out (x − 5)(x + 2) first. Then see what happens to the x².","solution":"(x − 5)(x + 2) = x² − 3x − 10. Subtract x²: −3x − 10. The highest exponent left is 1."},{"id":"cl4-q5","type":"choice","prompt":"Simplify y = 2x³ − x(x² + 4), then classify it.","choices":["x³ − 4x, cubic binomial","x³ + 4x, cubic binomial","3x³ + 4x, cubic binomial","x³ − 4, cubic binomial"],"answer":0,"hint":"Distribute −x to both terms in the parentheses.","solution":"−x(x² + 4) = −x³ − 4x. Then 2x³ − x³ − 4x = x³ − 4x. Degree 3 (cubic) and 2 terms (binomial)."},{"id":"cl4-q6","type":"choice","prompt":"Simplify y = (x + 4)² − (x² + 16), then classify it.","choices":["8x, linear monomial","8x + 32, linear binomial","2x² + 8x + 32, quadratic trinomial","8x + 16, linear binomial"],"answer":0,"hint":"(x + 4)² has a middle term. The minus sign goes to both terms in (x² + 16).","solution":"(x + 4)² = x² + 8x + 16. Subtract: x² + 8x + 16 − x² − 16 = 8x. Degree 1 (linear) and 1 term (monomial)."},{"id":"cl4-q7","type":"choice","prompt":"Simplify y = 4x²(x − 1) + 4x², then classify it.","choices":["cubic monomial","cubic trinomial","cubic binomial","quadratic monomial"],"answer":0,"hint":"Distribute 4x² first. Then combine like terms.","solution":"4x²(x − 1) = 4x³ − 4x². Add 4x²: 4x³. Degree 3 (cubic) and 1 term (monomial)."},{"id":"cl4-q8","type":"choice","prompt":"Simplify y = (x² + 1)(x² − 1) + 1, then classify it.","choices":["x⁴, quartic monomial","x⁴ + 2, quartic binomial","x⁴ − 2x², quartic binomial","x⁴ + 2x², quartic binomial"],"answer":0,"hint":"(x² + 1)(x² − 1) is a sum times a difference, so the middle terms cancel.","solution":"(x² + 1)(x² − 1) = x⁴ − 1. Add 1: x⁴. Degree 4 (quartic) and 1 term (monomial)."},{"id":"cl4-q9","type":"input","prompt":"f(x) = 6 − x³ + 2x(x² − 1). What is the leading coefficient after you simplify?","answers":["1"],"hint":"Distribute 2x, then combine the x³ terms.","solution":"2x(x² − 1) = 2x³ − 2x. So f(x) = 6 − x³ + 2x³ − 2x = x³ − 2x + 6. The leading coefficient is 1."}]}]},{"id":"add-subtract","title":"Adding and subtracting polynomials","lessons":[{"id":"add-subtract-1","teach":[{"title":"Combine like terms","text":["Like terms have the same variables raised to the same exponents, like 4x² and −9x².","To add polynomials, add the coefficients of like terms. The exponents do not change.","Write the answer in standard form."],"example":{"problem":"(3x² + 11x + 4) + (−5x + x² − 13)","steps":["x² terms: 3x² + x² = 4x².","x terms: 11x − 5x = 6x.","Numbers: 4 − 13 = −9.","Answer: 4x² + 6x − 9"]}}],"questions":[{"id":"as1-q1","type":"choice","prompt":"Which pair are like terms?","choices":["4x² and −9x²","4x² and 4x³","3x and 3y","5x²y and 5xy²"],"answer":0,"hint":"Like terms have the same variables with the same exponents. The numbers in front can differ.","solution":"4x² and −9x² both have x². The other pairs have different exponents or different variables."},{"id":"as1-q2","type":"input","prompt":"3x² + 5x² = kx². What is k?","answers":["8"],"hint":"Add the coefficients. The exponent stays 2.","solution":"3 + 5 = 8, so 3x² + 5x² = 8x². (Not 8x⁴: adding does not change exponents.)"},{"id":"as1-q3","type":"choice","prompt":"Simplify (9n³ − 4n² + 2n − 10) + (−2n² + n + 7).","choices":["9n³ − 6n² + 3n − 3","9n³ − 2n² + 3n − 3","7n³ − 4n² + 3n − 3","9n³ − 6n² + 3n − 17"],"answer":0,"hint":"Line up like terms: n³, n², n, and numbers.","solution":"n³: 9n³. n²: −4n² − 2n² = −6n². n: 2n + n = 3n. Numbers: −10 + 7 = −3. Answer: 9n³ − 6n² + 3n − 3."},{"id":"as1-q4","type":"choice","prompt":"Simplify (2x³ − 5x + 8) + (4x² + 3x − 10).","choices":["2x³ + 4x² − 2x − 2","6x³ − 2x − 2","2x³ + 4x² − 8x − 2","2x³ + 4x² − 2x + 18"],"answer":0,"hint":"There is only one x³ term and only one x² term.","solution":"x³: 2x³. x²: 4x². x: −5x + 3x = −2x. Numbers: 8 − 10 = −2. Answer: 2x³ + 4x² − 2x − 2."},{"id":"as1-q5","type":"input","prompt":"(4a² + 3a − 1) + (a² − 7a + 6). What is the coefficient of a in the answer?","answers":["-4"],"hint":"Add only the a terms: 3a and −7a.","solution":"3a + (−7a) = −4a, so the coefficient is −4. The full answer is 5a² − 4a + 5."},{"id":"as1-q6","type":"choice","prompt":"Simplify (x⁴ − 3x² + 2) + (−x⁴ + 5x³ − x).","choices":["5x³ − 3x² − x + 2","2x⁴ + 5x³ − 3x² − x + 2","5x³ − 4x² + 2","5x³ − 3x² + x + 2"],"answer":0,"hint":"x⁴ and −x⁴ are like terms. x² and x are not like terms.","solution":"x⁴ − x⁴ = 0. Then 5x³, −3x², −x, and 2 have no partners. Answer: 5x³ − 3x² − x + 2."},{"id":"as1-q7","type":"input","prompt":"(5y² − 2y) + (−5y² + 9y) = ky. What is k?","answers":["7"],"hint":"The y² terms cancel.","solution":"5y² − 5y² = 0 and −2y + 9y = 7y. So k = 7."}]},{"id":"add-subtract-2","teach":[{"title":"Subtracting: change every sign","text":["Subtracting a polynomial means adding its opposite.","Change the sign of every term in the second parentheses, then combine like terms.","Watch out: the minus sign goes to every term, not just the first one."],"example":{"problem":"(5k³ − 2k² + 2k) − (2k² + 2k + 17)","steps":["Change the signs in the second part: 5k³ − 2k² + 2k − 2k² − 2k − 17.","k²: −2k² − 2k² = −4k². k: 2k − 2k = 0.","Answer: 5k³ − 4k² − 17"]}},{"title":"\"Subtract A from B\" means B − A","text":["The word \"from\" tells you which polynomial comes first.","\"Subtract A from B\" means start with B and take away A: B − A."],"example":{"problem":"Subtract (−10ab + 7a² − b²) from (8b² + ab − 2a²).","steps":["Write it as (8b² + ab − 2a²) − (−10ab + 7a² − b²).","Change the signs: 8b² + ab − 2a² + 10ab − 7a² + b².","a²: −2a² − 7a² = −9a². ab: ab + 10ab = 11ab. b²: 8b² + b² = 9b².","Answer: −9a² + 11ab + 9b²"]}}],"questions":[{"id":"as2-q1","type":"choice","prompt":"What is −(2y² − 5y − 1)?","choices":["−2y² + 5y + 1","−2y² − 5y − 1","2y² + 5y + 1","−2y² + 5y − 1"],"answer":0,"hint":"Change the sign of every term inside.","solution":"Each sign flips: 2y² → −2y², −5y → +5y, −1 → +1. Answer: −2y² + 5y + 1."},{"id":"as2-q2","type":"choice","prompt":"Simplify (8x³ − 6x⁴ + 3) − (3x³ − 3 + 8x⁴).","choices":["−14x⁴ + 5x³ + 6","−14x⁴ + 5x³","2x⁴ + 5x³ + 6","−14x⁴ + 11x³ + 6"],"answer":0,"hint":"Change every sign in the second part. Then combine like terms.","solution":"8x³ − 6x⁴ + 3 − 3x³ + 3 − 8x⁴. x⁴: −6x⁴ − 8x⁴ = −14x⁴. x³: 8x³ − 3x³ = 5x³. Numbers: 3 + 3 = 6. Answer: −14x⁴ + 5x³ + 6."},{"id":"as2-q3","type":"choice","prompt":"Simplify (2a²b − 5b³ + 4a⁴b²) − (7b³ + 8a⁴b² − 7a²b).","choices":["−4a⁴b² + 9a²b − 12b³","12a⁴b² − 5a²b + 2b³","−4a⁴b² − 5a²b − 12b³","−4a⁴b² + 9a²b + 2b³"],"answer":0,"hint":"Subtracting −7a²b is the same as adding 7a²b.","solution":"Change signs: 2a²b − 5b³ + 4a⁴b² − 7b³ − 8a⁴b² + 7a²b. a⁴b²: 4 − 8 = −4. a²b: 2 + 7 = 9. b³: −5 − 7 = −12. Answer: −4a⁴b² + 9a²b − 12b³."},{"id":"as2-q4","type":"choice","prompt":"Simplify (y + 4y² − 3) − (1 + 2y² − 5y − y³).","choices":["y³ + 2y² + 6y − 4","−y³ + 2y² − 4y − 4","y³ + 2y² + 6y − 2","y³ + 6y² + 6y − 4"],"answer":0,"hint":"Subtracting −y³ gives +y³, and subtracting −5y gives +5y.","solution":"y + 4y² − 3 − 1 − 2y² + 5y + y³. y³: y³. y²: 4y² − 2y² = 2y². y: y + 5y = 6y. Numbers: −3 − 1 = −4. Answer: y³ + 2y² + 6y − 4."},{"id":"as2-q5","type":"input","prompt":"Subtract (3m² − 4) from (m² + 6). What is the constant term of the answer?","answers":["10"],"hint":"Write it as (m² + 6) − (3m² − 4).","solution":"(m² + 6) − (3m² − 4) = m² + 6 − 3m² + 4 = −2m² + 10. The constant term is 10."},{"id":"as2-q6","type":"choice","prompt":"Subtract 4x² − x from 3x² + 2x.","choices":["−x² + 3x","x² − 3x","−x² + x","7x² + x"],"answer":0,"hint":"\"Subtract A from B\" means B − A. Here B is 3x² + 2x.","solution":"(3x² + 2x) − (4x² − x) = 3x² + 2x − 4x² + x = −x² + 3x."},{"id":"as2-q7","type":"choice","prompt":"Simplify (5k² − 3k + 2) − (5k² + 3k − 2).","choices":["−6k + 4","10k² − 6k + 4","−6k","4"],"answer":0,"hint":"Change every sign in the second part. The k² terms cancel.","solution":"5k² − 3k + 2 − 5k² − 3k + 2. k²: 0. k: −3k − 3k = −6k. Numbers: 2 + 2 = 4. Answer: −6k + 4."}]},{"id":"add-subtract-3","teach":[{"title":"Like terms with two variables","text":["Like terms have the same variables with the same exponents. 3x²y and −5x²y are like terms. 3x²y and 3xy² are not.","Add the coefficients of like terms. The variables and exponents stay the same."],"example":{"problem":"(4x²y − 3xy + 2y²) + (−x²y + 5xy² + 7xy)","steps":["x²y: 4x²y − x²y = 3x²y.","xy: −3xy + 7xy = 4xy.","5xy² and 2y² have no like terms to combine with.","Answer: 3x²y + 5xy² + 4xy + 2y²"]}},{"title":"Adding three polynomials","text":["Line up like terms in columns, one column for each power. Leave a gap where a power is missing.","Then add down each column."],"example":{"problem":"(2x³ − x + 4) + (x² + 3x) + (−5x³ + 2x² − 6)","steps":["x³: 2x³ − 5x³ = −3x³.","x²: x² + 2x² = 3x².","x: −x + 3x = 2x.","Numbers: 4 − 6 = −2.","Answer: −3x³ + 3x² + 2x − 2"]}}],"questions":[{"id":"as3-q1","type":"choice","prompt":"Which term is a like term with 6a²b?","choices":["−a²b","6ab²","6a²","6a²b²"],"answer":0,"hint":"Like terms need the same variables with the same exponents. The number in front can be different.","solution":"−a²b has a² and b, just like 6a²b. 6ab² has the exponents switched, 6a² has no b, and 6a²b² has b²."},{"id":"as3-q2","type":"input","prompt":"4y³ − 9y³ + 2y³ = ky³. What is k?","answers":["-3"],"hint":"Add the coefficients. The exponent stays 3.","solution":"4 − 9 + 2 = −3, so the answer is −3y³ and k = −3."},{"id":"as3-q3","type":"choice","prompt":"Simplify (6x² − 2x + 9) + (−4x² − 7x + 1).","choices":["2x² − 9x + 10","2x² − 5x + 10","10x² − 9x + 10","2x⁴ − 9x² + 10"],"answer":0,"hint":"Combine x² with x², x with x, and numbers with numbers. Adding does not change exponents.","solution":"x²: 6x² − 4x² = 2x². x: −2x − 7x = −9x. Numbers: 9 + 1 = 10. Answer: 2x² − 9x + 10."},{"id":"as3-q4","type":"choice","prompt":"Simplify (3a³ + a − 5) + (2a² − 4a + 5).","choices":["3a³ + 2a² − 3a","5a³ − 3a","3a³ + 2a² − 3a − 10","3a³ + 2a² + 5a"],"answer":0,"hint":"a³ and a² are not like terms. The numbers cancel.","solution":"a³: 3a³. a²: 2a². a: a − 4a = −3a. Numbers: −5 + 5 = 0. Answer: 3a³ + 2a² − 3a."},{"id":"as3-q5","type":"choice","prompt":"Simplify (5ab² − 2a²b + 3) + (4a²b − ab² − 8).","choices":["2a²b + 4ab² − 5","−6a²b + 4ab² − 5","2a²b + 6ab² − 5","2a²b + 4ab² − 11"],"answer":0,"hint":"a²b and ab² are different terms. Combine each one with its own match.","solution":"a²b: −2a²b + 4a²b = 2a²b. ab²: 5ab² − ab² = 4ab². Numbers: 3 − 8 = −5. Answer: 2a²b + 4ab² − 5."},{"id":"as3-q6","type":"input","prompt":"(2n⁴ − 5n² + n) + (n³ + 5n² − 6). What is the coefficient of n² in the answer?","answers":["0"],"hint":"Add only the n² terms.","solution":"−5n² + 5n² = 0n², so the n² terms cancel. The answer is 2n⁴ + n³ + n − 6, with no n² term."},{"id":"as3-q7","type":"choice","prompt":"Simplify (x³ + 2x) + (4x² − 3x + 1) + (−2x³ − x² + 5).","choices":["−x³ + 3x² − x + 6","3x³ + 3x² − x + 6","−x³ + 3x² + 5x + 6","−x³ + 5x² − x + 6"],"answer":0,"hint":"Line up the columns: x³, x², x, and numbers.","solution":"x³: x³ − 2x³ = −x³. x²: 4x² − x² = 3x². x: 2x − 3x = −x. Numbers: 1 + 5 = 6. Answer: −x³ + 3x² − x + 6."},{"id":"as3-q8","type":"choice","prompt":"A triangle has sides 3x² + 2, x² − 4x, and 5x + 7. Which expression is its perimeter?","choices":["4x² + x + 9","4x² + 9x + 9","4x² − x + 9","4x² + x + 5"],"answer":0,"hint":"Perimeter = the sum of all three sides.","solution":"x²: 3x² + x² = 4x². x: −4x + 5x = x. Numbers: 2 + 7 = 9. Perimeter: 4x² + x + 9."}]},{"id":"add-subtract-4","teach":[{"title":"Subtract by adding the opposite","text":["Rewrite A − B as A + (−B): change the sign of every term in B.","Then combine like terms, just as you do when adding."],"example":{"problem":"(6x³ − 2x² + 5) − (−3x³ + 4x − 1)","steps":["Change every sign in the second part: −3x³ becomes +3x³, 4x becomes −4x, −1 becomes +1.","6x³ − 2x² + 5 + 3x³ − 4x + 1.","x³: 6x³ + 3x³ = 9x³. Numbers: 5 + 1 = 6.","Answer: 9x³ − 2x² − 4x + 6"]}},{"title":"Adding and subtracting together","text":["Remove the parentheses one group at a time. A plus sign in front leaves the signs alone. A minus sign changes every sign in that group."],"example":{"problem":"(2y² + y) − (y² − 3) + (4y − 5)","steps":["Remove the parentheses: 2y² + y − y² + 3 + 4y − 5.","y²: 2y² − y² = y². y: y + 4y = 5y. Numbers: 3 − 5 = −2.","Answer: y² + 5y − 2"]}}],"questions":[{"id":"as4-q1","type":"choice","prompt":"What is −(−4m³ + m − 6)?","choices":["4m³ − m + 6","4m³ + m − 6","−4m³ − m + 6","4m³ − m − 6"],"answer":0,"hint":"The minus sign changes the sign of every term inside.","solution":"−4m³ becomes 4m³, m becomes −m, and −6 becomes 6. Answer: 4m³ − m + 6."},{"id":"as4-q2","type":"choice","prompt":"Simplify (7x² + 3x − 2) − (4x² − 5x + 6).","choices":["3x² + 8x − 8","3x² − 2x + 4","3x² + 8x + 4","11x² + 8x − 8"],"answer":0,"hint":"Change every sign in the second part, then combine like terms.","solution":"7x² + 3x − 2 − 4x² + 5x − 6. x²: 3x². x: 3x + 5x = 8x. Numbers: −2 − 6 = −8. Answer: 3x² + 8x − 8."},{"id":"as4-q3","type":"choice","prompt":"Simplify (2a³ − a² + 9) − (5a³ + 3a − 4).","choices":["−3a³ − a² − 3a + 13","−3a³ − a² + 3a + 5","−3a³ − a² − 3a + 5","−3a³ − 4a² + 13"],"answer":0,"hint":"The minus sign goes to 5a³, to 3a, and to −4.","solution":"2a³ − a² + 9 − 5a³ − 3a + 4. a³: 2a³ − 5a³ = −3a³. a²: −a². a: −3a. Numbers: 9 + 4 = 13. Answer: −3a³ − a² − 3a + 13."},{"id":"as4-q4","type":"input","prompt":"Subtract (2x² − 7x) from (5x² + x). What is the coefficient of x in the answer?","answers":["8"],"hint":"\"Subtract A from B\" means B − A. Here that is (5x² + x) − (2x² − 7x).","solution":"(5x² + x) − (2x² − 7x) = 5x² + x − 2x² + 7x = 3x² + 8x. The coefficient of x is 8."},{"id":"as4-q5","type":"choice","prompt":"Subtract 3k³ − 2k + 1 from k³ + 4k² − 2k.","choices":["−2k³ + 4k² − 1","2k³ − 4k² + 1","−2k³ + 4k² − 4k − 1","−2k³ + 4k² + 1"],"answer":0,"hint":"Start with k³ + 4k² − 2k, then take away 3k³ − 2k + 1.","solution":"(k³ + 4k² − 2k) − (3k³ − 2k + 1) = k³ + 4k² − 2k − 3k³ + 2k − 1. k³: −2k³. k: −2k + 2k = 0. Answer: −2k³ + 4k² − 1."},{"id":"as4-q6","type":"choice","prompt":"Simplify (3x²y − 4xy² + y³) − (−x²y + 2xy² − 5y³).","choices":["4x²y − 6xy² + 6y³","2x²y − 2xy² − 4y³","4x²y − 2xy² + 6y³","4x²y − 6xy² − 4y³"],"answer":0,"hint":"Change every sign in the second part: −x²y becomes +x²y and −5y³ becomes +5y³.","solution":"3x²y − 4xy² + y³ + x²y − 2xy² + 5y³. x²y: 4x²y. xy²: −6xy². y³: 6y³. Answer: 4x²y − 6xy² + 6y³."},{"id":"as4-q7","type":"choice","prompt":"Simplify (4n² − 3) − (n² + 2n) + (6n − 1).","choices":["3n² + 4n − 4","3n² + 8n − 4","3n² − 8n − 4","5n² + 4n − 4"],"answer":0,"hint":"Only the middle group has a minus sign in front of it.","solution":"4n² − 3 − n² − 2n + 6n − 1. n²: 3n². n: −2n + 6n = 4n. Numbers: −3 − 1 = −4. Answer: 3n² + 4n − 4."},{"id":"as4-q8","type":"choice","prompt":"A company's revenue is 5x² + 30x − 40 dollars and its cost is 2x² + 12x + 60 dollars. Profit is revenue minus cost. Which expression is the profit?","choices":["3x² + 18x − 100","3x² + 18x + 20","7x² + 42x + 20","3x² + 42x − 100"],"answer":0,"hint":"Write (5x² + 30x − 40) − (2x² + 12x + 60) and change every sign in the cost.","solution":"5x² + 30x − 40 − 2x² − 12x − 60 = 3x² + 18x − 100."},{"id":"as4-q9","type":"input","prompt":"(a² − 2ab + b²) − (a² + 2ab + b²) = k·ab. What is k?","answers":["-4"],"hint":"The a² terms cancel and so do the b² terms.","solution":"a² − 2ab + b² − a² − 2ab − b² = −4ab. So k = −4."}]}]},{"id":"multiply-divide","title":"Multiplying and dividing polynomials","lessons":[{"id":"multiply-divide-1","teach":[{"title":"Multiply every term by every term","text":["Distribute: multiply each term in the first polynomial by each term in the second. For two binomials this is FOIL. A box works for bigger ones.","Then combine like terms and write the answer in standard form."],"example":{"problem":"(w − 7)(w² + 2w + 1)","steps":["w times each term: w³ + 2w² + w.","−7 times each term: −7w² − 14w − 7.","Combine: w³ + (2w² − 7w²) + (w − 14w) − 7.","Answer: w³ − 5w² − 13w − 7"]}},{"title":"Three factors","text":["Multiply two of the factors first. Then multiply that answer by the third factor.","A power like (a + b)³ means (a + b)(a + b)(a + b). It is NOT a³ + b³."],"example":{"problem":"−3(a + 5)(a − 2)(a + 8)","steps":["(a + 5)(a − 2) = a² + 3a − 10.","(a² + 3a − 10)(a + 8) = a³ + 8a² + 3a² + 24a − 10a − 80 = a³ + 11a² + 14a − 80.","Multiply by −3: −3a³ − 33a² − 42a + 240."]}}],"questions":[{"id":"md1-q1","type":"choice","prompt":"Multiply (x + 4)(x − 6).","choices":["x² − 2x − 24","x² + 2x − 24","x² − 24","x² − 10x − 24"],"answer":0,"hint":"FOIL: First, Outer, Inner, Last. Then combine the middle terms.","solution":"x·x = x², x·(−6) = −6x, 4·x = 4x, 4·(−6) = −24. Middle: −6x + 4x = −2x. Answer: x² − 2x − 24."},{"id":"md1-q2","type":"choice","prompt":"Simplify (2x + 1)(4 − 9x) − 2x(3x + 11).","choices":["−24x² − 23x + 4","−12x² − 23x + 4","−24x² + 21x + 4","−24x² − 23x − 4"],"answer":0,"hint":"Multiply each part first. Then subtract every term of 2x(3x + 11).","solution":"(2x + 1)(4 − 9x) = 8x − 18x² + 4 − 9x = −18x² − x + 4. 2x(3x + 11) = 6x² + 22x. Subtract: −18x² − x + 4 − 6x² − 22x = −24x² − 23x + 4."},{"id":"md1-q3","type":"choice","prompt":"Multiply −3x(5x + 1)(8 − 2x).","choices":["30x³ − 114x² − 24x","30x³ − 126x² − 24x","−30x³ + 114x² + 24x","30x³ − 114x² + 24x"],"answer":0,"hint":"Multiply (5x + 1)(8 − 2x) first, then multiply by −3x.","solution":"(5x + 1)(8 − 2x) = 40x − 10x² + 8 − 2x = −10x² + 38x + 8. Times −3x: 30x³ − 114x² − 24x."},{"id":"md1-q4","type":"choice","prompt":"Multiply (3m² − 4m + 1)(2m² + 5m − 9).","choices":["6m⁴ + 7m³ − 45m² + 41m − 9","6m⁴ + 7m³ − 25m² + 41m − 9","6m⁴ + 23m³ − 45m² + 41m − 9","6m⁴ + 7m³ − 45m² + 31m − 9"],"answer":0,"hint":"Use a 3-by-3 box. There are three m² products to add up.","solution":"3m² row: 6m⁴, 15m³, −27m². −4m row: −8m³, −20m², 36m. 1 row: 2m², 5m, −9. Combine: 6m⁴ + 7m³ − 45m² + 41m − 9."},{"id":"md1-q5","type":"input","prompt":"(2c + 5d)³ = 8c³ + 60c²d + k·cd² + 125d³. What is k?","answers":["150"],"hint":"Multiply (2c + 5d)(2c + 5d) first, then multiply by (2c + 5d) again.","solution":"(2c + 5d)² = 4c² + 20cd + 25d². Times (2c + 5d): 8c³ + 20c²d + 40c²d + 100cd² + 50cd² + 125d³ = 8c³ + 60c²d + 150cd² + 125d³. So k = 150."},{"id":"md1-q6","type":"choice","prompt":"Multiply 4(2 − 3w)(w² − 2w + 10).","choices":["−12w³ + 32w² − 136w + 80","−12w³ + 32w² − 136w + 20","12w³ + 32w² − 136w + 80","−12w³ + 8w² − 136w + 80"],"answer":0,"hint":"Multiply the two parentheses first, then multiply every term by 4.","solution":"(2 − 3w)(w² − 2w + 10) = 2w² − 4w + 20 − 3w³ + 6w² − 30w = −3w³ + 8w² − 34w + 20. Times 4: −12w³ + 32w² − 136w + 80."},{"id":"md1-q7","type":"choice","prompt":"Simplify (1 − 2n)³ − 7n(n² − 2).","choices":["−15n³ + 12n² + 8n + 1","−n³ + 12n² + 8n + 1","−15n³ + 12n² − 20n + 1","14n⁶ − 28n⁴ − 7n³ + 14n"],"answer":0,"hint":"Expand (1 − 2n)³ on its own first. Then subtract 7n³ − 14n.","solution":"(1 − 2n)² = 1 − 4n + 4n². Times (1 − 2n): 1 − 6n + 12n² − 8n³. Then − 7n(n² − 2) = −7n³ + 14n. Combine: −15n³ + 12n² + 8n + 1."},{"id":"md1-q8","type":"choice","prompt":"A trapezoid has height 2x + 9 and bases 3x − 7 and x + 5. Which expression is its area?","choices":["4x² + 16x − 9","8x² + 32x − 18","4x² + 20x − 9","4x² + 16x + 9"],"answer":0,"hint":"Area of a trapezoid = ½(base₁ + base₂)(height).","solution":"Bases: (3x − 7) + (x + 5) = 4x − 2. Half of that is 2x − 1. Area = (2x − 1)(2x + 9) = 4x² + 18x − 2x − 9 = 4x² + 16x − 9."},{"id":"md1-q9","type":"choice","prompt":"A rectangular prism has length x + 3, width x + 7, and height x − 1. Which expression is its surface area?","choices":["6x² + 36x + 22","3x² + 18x + 11","x³ + 9x² + 11x − 21","6x² + 20x + 22"],"answer":0,"hint":"Surface area = 2(lw + lh + wh).","solution":"lw = x² + 10x + 21, lh = x² + 2x − 3, wh = x² + 6x − 7. Sum: 3x² + 18x + 11. Double it: 6x² + 36x + 22."}]},{"id":"multiply-divide-2","teach":[{"title":"Dividing by a monomial","text":["Split the fraction: divide every term on top by the monomial on the bottom.","For each term, divide the numbers and subtract the exponents (quotient rule).","Write the answer in standard form."],"example":{"problem":"(9m³ − 24m²) / (3m)","steps":["9m³ / 3m = 3m².","−24m² / 3m = −8m.","Answer: 3m² − 8m"]}},{"title":"When an exponent goes negative","text":["If a term on top has a smaller exponent than the bottom, its exponent becomes negative.","Rewrite it with a positive exponent by moving the variable to the bottom: 3x⁻¹ = 3/x."],"example":{"problem":"(30x³ − 12x² + 9x) / (3x²)","steps":["30x³ / 3x² = 10x.","−12x² / 3x² = −4.","9x / 3x² = 3x⁻¹ = 3/x.","Answer: 10x − 4 + 3/x"]}}],"questions":[{"id":"md2-q1","type":"choice","prompt":"Divide (20x³ − 4x² − 8x) / (4x).","choices":["5x² − x − 2","5x³ − x² − 2x","5x² − 4x − 2","5x² − x"],"answer":0,"hint":"Divide every term by 4x, including the last one.","solution":"20x³/4x = 5x². −4x²/4x = −x. −8x/4x = −2. Answer: 5x² − x − 2."},{"id":"md2-q2","type":"choice","prompt":"Simplify (14a⁴b³ − 20a²b² + 2ab) · (2ab)⁻¹.","choices":["7a³b² − 10ab + 1","7a³b² − 10ab","28a⁵b⁴ − 40a³b³ + 4a²b²","7a⁴b³ − 10a²b² + 1"],"answer":0,"hint":"Multiplying by (2ab)⁻¹ is the same as dividing by 2ab.","solution":"14a⁴b³/2ab = 7a³b². −20a²b²/2ab = −10ab. 2ab/2ab = 1. Answer: 7a³b² − 10ab + 1."},{"id":"md2-q3","type":"choice","prompt":"Divide (30c⁸d³ − 36c⁶d² + 6c³d) / (12c²d).","choices":["(5/2)c⁶d² − 3c⁴d + (1/2)c","(5/2)c⁶d² − 3c⁴d + 2c","(5/2)c⁴d³ − 3c³d² + (1/2)c","18c⁶d² − 24c⁴d − 6c"],"answer":0,"hint":"Reduce each number over 12, and subtract exponents.","solution":"30/12 = 5/2 and c⁸⁻²d³⁻¹ = c⁶d². −36/12 = −3 and c⁶⁻²d²⁻¹ = c⁴d. 6/12 = 1/2 and c³⁻²d¹⁻¹ = c. Answer: (5/2)c⁶d² − 3c⁴d + (1/2)c."},{"id":"md2-q4","type":"choice","prompt":"Divide (40m³n⁴ − 24m²n⁷) / (8m²n⁵).","choices":["5m/n − 3n²","5mn − 3n²","5m − 3n²","5m/n − 3n¹²"],"answer":0,"hint":"For n: 4 − 5 is negative, so n ends up on the bottom.","solution":"40m³n⁴/8m²n⁵ = 5mn⁻¹ = 5m/n. −24m²n⁷/8m²n⁵ = −3n². Answer: 5m/n − 3n²."},{"id":"md2-q5","type":"choice","prompt":"Divide (−42x¹⁰y⁵ + 12x⁸y³ − 6x²y) / (6x²y).","choices":["−7x⁸y⁴ + 2x⁶y² − 1","−7x⁸y⁴ + 2x⁶y²","−7x⁵y⁵ + 2x⁴y³ − 1","7x⁸y⁴ − 2x⁶y² + 1"],"answer":0,"hint":"Subtract exponents. Don't divide them. The last term divides to −1.","solution":"−42/6 = −7, x¹⁰⁻² = x⁸, y⁵⁻¹ = y⁴. 12/6 = 2, x⁶, y². −6x²y/6x²y = −1. Answer: −7x⁸y⁴ + 2x⁶y² − 1."},{"id":"md2-q6","type":"choice","prompt":"Divide (16a⁴ − 40a² + 24a) / (12a³).","choices":["(4/3)a − 10/(3a) + 2/a²","(4/3)a⁷ − (10/3)a⁵ + 2a⁴","(4/3)a − 10/(3a) + 2a²","(4/3)a − 10a + 2a²"],"answer":0,"hint":"Two of the terms end up with negative exponents. Move those variables to the bottom.","solution":"16a⁴/12a³ = (4/3)a. −40a²/12a³ = −(10/3)a⁻¹ = −10/(3a). 24a/12a³ = 2a⁻² = 2/a². Answer: (4/3)a − 10/(3a) + 2/a²."},{"id":"md2-q7","type":"input","prompt":"A triangle has area 14x⁵ + 63x² and base 7x². Its height is kx³ + 18. What is k?","answers":["4"],"hint":"Area = ½ · base · height, so height = 2 · area ÷ base.","solution":"Height = 2(14x⁵ + 63x²) / 7x² = (28x⁵ + 126x²) / 7x² = 4x³ + 18. So k = 4."}]},{"id":"multiply-divide-3","teach":[{"title":"A monomial times a polynomial","text":["Multiply the monomial by every term inside the parentheses.","For each product, multiply the numbers and add the exponents. Watch the signs."],"example":{"problem":"−4x²(3x² − 5x + 2)","steps":["−4x² · 3x² = −12x⁴.","−4x² · (−5x) = 20x³.","−4x² · 2 = −8x².","Answer: −12x⁴ + 20x³ − 8x²"]}},{"title":"Squaring a binomial","text":["(a + b)² = (a + b)(a + b) = a² + 2ab + b². Do not forget the middle term.","(a − b)² = a² − 2ab + b²."],"example":{"problem":"(3x − 4)²","steps":["Here a = 3x and b = 4.","a² = 9x². 2ab = 2 · 3x · 4 = 24x. b² = 16.","It is a minus, so the middle term is negative.","Answer: 9x² − 24x + 16"]}}],"questions":[{"id":"md3-q1","type":"choice","prompt":"Multiply −2y³(y² − 6y + 3).","choices":["−2y⁵ + 12y⁴ − 6y³","−2y⁵ − 12y⁴ − 6y³","−2y⁵ − 6y + 3","2y⁵ − 12y⁴ + 6y³"],"answer":0,"hint":"Multiply −2y³ by all three terms. A negative times a negative is positive.","solution":"−2y³ · y² = −2y⁵. −2y³ · (−6y) = 12y⁴. −2y³ · 3 = −6y³. Answer: −2y⁵ + 12y⁴ − 6y³."},{"id":"md3-q2","type":"input","prompt":"(x + 7)(x − 3) = x² + bx − 21. What is b?","answers":["4"],"hint":"The middle term comes from the Outer and Inner products.","solution":"Outer: x · (−3) = −3x. Inner: 7 · x = 7x. −3x + 7x = 4x, so b = 4."},{"id":"md3-q3","type":"choice","prompt":"Multiply (2x − 5)(3x + 4).","choices":["6x² − 7x − 20","6x² + 7x − 20","6x² − 20","6x² − 23x − 20"],"answer":0,"hint":"FOIL, then combine the two middle terms.","solution":"First: 6x². Outer: 8x. Inner: −15x. Last: −20. 8x − 15x = −7x. Answer: 6x² − 7x − 20."},{"id":"md3-q4","type":"choice","prompt":"Multiply (4m + 3)².","choices":["16m² + 24m + 9","16m² + 9","16m² + 12m + 9","4m² + 12m + 9"],"answer":0,"hint":"(a + b)² = a² + 2ab + b² with a = 4m and b = 3.","solution":"a² = 16m². 2ab = 2 · 4m · 3 = 24m. b² = 9. Answer: 16m² + 24m + 9."},{"id":"md3-q5","type":"choice","prompt":"Multiply (x − 2)(x² + 5x − 3).","choices":["x³ + 3x² − 13x + 6","x³ + 3x² − 13x − 6","x³ + 7x² − 13x + 6","x³ + 3x² + 7x + 6"],"answer":0,"hint":"Multiply x by each term, then −2 by each term. Then combine.","solution":"x: x³ + 5x² − 3x. −2: −2x² − 10x + 6. Combine: x³ + 3x² − 13x + 6."},{"id":"md3-q6","type":"choice","prompt":"Multiply (a + 3b)(2a − b).","choices":["2a² + 5ab − 3b²","2a² − 5ab − 3b²","2a² + 7ab − 3b²","2a² + 5ab + 3b²"],"answer":0,"hint":"FOIL. The Outer and Inner products are both ab terms.","solution":"First: 2a². Outer: −ab. Inner: 6ab. Last: −3b². −ab + 6ab = 5ab. Answer: 2a² + 5ab − 3b²."},{"id":"md3-q7","type":"choice","prompt":"Multiply 2x(x + 3)(x − 4).","choices":["2x³ − 2x² − 24x","2x³ + 2x² − 24x","2x² − 2x − 24","2x³ − 2x² − 12x"],"answer":0,"hint":"Multiply the two binomials first. Then multiply every term by 2x.","solution":"(x + 3)(x − 4) = x² − x − 12. Times 2x: 2x³ − 2x² − 24x."},{"id":"md3-q8","type":"choice","prompt":"A rectangle has length 3x + 2 and width x − 6. Which expression is its area?","choices":["3x² − 16x − 12","3x² − 12","3x² + 16x − 12","3x² − 20x − 12"],"answer":0,"hint":"Area = length · width. FOIL the two binomials.","solution":"(3x + 2)(x − 6) = 3x² − 18x + 2x − 12 = 3x² − 16x − 12."}]},{"id":"multiply-divide-4","teach":[{"title":"Divide, then check","text":["Split the fraction: put each term of the top over the monomial and simplify each small fraction.","Check your answer by multiplying it by the monomial. You should get the top back."],"example":{"problem":"(18x⁴ − 12x³ + 6x²) / (6x²)","steps":["18x⁴ / 6x² = 3x².","−12x³ / 6x² = −2x.","6x² / 6x² = 1.","Answer: 3x² − 2x + 1. Check: 6x²(3x² − 2x + 1) = 18x⁴ − 12x³ + 6x²."]}},{"title":"Cubing a binomial","text":["(a + b)³ = (a + b)²(a + b). Square it first, then multiply by the binomial one more time.","It is never just a³ + b³."],"example":{"problem":"(x + 2)³","steps":["(x + 2)² = x² + 4x + 4.","(x² + 4x + 4)(x + 2) = x³ + 2x² + 4x² + 8x + 4x + 8.","Answer: x³ + 6x² + 12x + 8"]}}],"questions":[{"id":"md4-q1","type":"input","prompt":"15x⁶ ÷ 3x² = kx⁴. What is k?","answers":["5"],"hint":"Divide the numbers and subtract the exponents.","solution":"15 ÷ 3 = 5 and x⁶⁻² = x⁴. So k = 5."},{"id":"md4-q2","type":"choice","prompt":"Divide (12y⁵ − 18y³ + 6y) / (6y).","choices":["2y⁴ − 3y² + 1","2y⁴ − 3y²","2y⁵ − 3y³ + y","2y⁴ − 18y³ + 6y"],"answer":0,"hint":"Divide every term by 6y, including the last one.","solution":"12y⁵/6y = 2y⁴. −18y³/6y = −3y². 6y/6y = 1. Answer: 2y⁴ − 3y² + 1."},{"id":"md4-q3","type":"choice","prompt":"Divide (8a⁴b³ − 20a³b² + 4a²b) / (4a²b).","choices":["2a²b² − 5ab + 1","2a²b² − 5ab","2a²b³ − 5ab² + 1","2a⁶b⁴ − 5a⁵b³ + a⁴b²"],"answer":0,"hint":"For each term, divide the numbers and subtract the exponents of a and of b.","solution":"8a⁴b³/4a²b = 2a²b². −20a³b²/4a²b = −5ab. 4a²b/4a²b = 1. Answer: 2a²b² − 5ab + 1."},{"id":"md4-q4","type":"choice","prompt":"Divide (10x³ + 15x² − 5x) / (5x²).","choices":["2x + 3 − 1/x","2x + 3 − x","2x + 3 − 1","2x² + 3x − 1"],"answer":0,"hint":"The last term has a smaller exponent than 5x². Its x ends up on the bottom.","solution":"10x³/5x² = 2x. 15x²/5x² = 3. −5x/5x² = −x⁻¹ = −1/x. Answer: 2x + 3 − 1/x."},{"id":"md4-q5","type":"choice","prompt":"Simplify (6m⁵n² − 9m³n⁴) · (3m²n)⁻¹.","choices":["2m³n − 3mn³","2m⁷n³ − 3m⁵n⁵","2m³n − 9m³n⁴","18m⁷n³ − 27m⁵n⁵"],"answer":0,"hint":"Multiplying by (3m²n)⁻¹ means dividing by 3m²n.","solution":"6m⁵n²/3m²n = 2m³n. −9m³n⁴/3m²n = −3mn³. Answer: 2m³n − 3mn³."},{"id":"md4-q6","type":"choice","prompt":"Multiply (x + 3)(x² − 3x + 9).","choices":["x³ + 27","x³ − 27","x³ + 6x² + 18x + 27","x³ + 9"],"answer":0,"hint":"Multiply x by each term, then 3 by each term. Most of the terms cancel.","solution":"x: x³ − 3x² + 9x. 3: 3x² − 9x + 27. The x² and x terms cancel: x³ + 27."},{"id":"md4-q7","type":"choice","prompt":"Simplify (3x − 1)(x + 2) − (x − 4)².","choices":["2x² + 13x − 18","2x² − 3x + 14","2x² + 5x + 14","4x² − 3x + 14"],"answer":0,"hint":"Multiply out each part first. Then subtract every term of (x − 4)².","solution":"(3x − 1)(x + 2) = 3x² + 5x − 2. (x − 4)² = x² − 8x + 16. Subtract: 3x² + 5x − 2 − x² + 8x − 16 = 2x² + 13x − 18."},{"id":"md4-q8","type":"choice","prompt":"Multiply (x − 1)³.","choices":["x³ − 3x² + 3x − 1","x³ − 1","x³ − 3x² − 3x − 1","x³ + 3x² + 3x − 1"],"answer":0,"hint":"Square (x − 1) first, then multiply by (x − 1) again.","solution":"(x − 1)² = x² − 2x + 1. Times (x − 1): x³ − x² − 2x² + 2x + x − 1 = x³ − 3x² + 3x − 1."},{"id":"md4-q9","type":"input","prompt":"A rectangle has area 12x³ + 8x² and width 4x. Its length is 3x² + kx. What is k?","answers":["2"],"hint":"Length = area ÷ width. Divide each term by 4x.","solution":"12x³/4x = 3x² and 8x²/4x = 2x. The length is 3x² + 2x, so k = 2."}]}]},{"id":"factor-special","title":"Factoring: GCF and special patterns","lessons":[{"id":"factor-special-1","teach":[{"title":"Always check for a GCF first","text":["The greatest common factor (GCF) is the biggest number and the lowest power of each variable that every term shares.","Pull it out front, then write what is left of each term inside the parentheses."],"example":{"problem":"Factor 16x³y − 12x²y² + 32xy³.","steps":["Numbers: the GCF of 16, 12, and 32 is 4.","Lowest powers in every term: x¹ and y¹. So the GCF is 4xy.","Divide each term by 4xy: 4x², −3xy, 8y².","Answer: 4xy(4x² − 3xy + 8y²)"]}},{"title":"Difference of squares","text":["a² − b² = (a + b)(a − b).","It only works when both terms are perfect squares and they are subtracted. A sum of squares like x² + 9 does not factor.","Perfect squares: 1, 4, 9, 16, 25, 36, 49, 64, 81, 100, and even powers like x², x⁴, x⁶."],"example":{"problem":"Factor 9x² − 49y².","steps":["9x² = (3x)² and 49y² = (7y)².","So a = 3x and b = 7y.","Answer: (3x + 7y)(3x − 7y)"]}},{"title":"Factor completely","text":["After you factor once, check every factor again. Keep going until nothing else factors."],"example":{"problem":"Factor 10w⁵ − 10w completely.","steps":["GCF: 10w(w⁴ − 1).","w⁴ − 1 is a difference of squares: (w² + 1)(w² − 1).","w² − 1 is another difference of squares: (w + 1)(w − 1).","Answer: 10w(w² + 1)(w + 1)(w − 1)"]}}],"questions":[{"id":"fs1-q1","type":"choice","prompt":"What is the GCF of 12a³ + 10a²?","choices":["2a²","2a³","12a²","a²"],"answer":0,"hint":"Find the GCF of 12 and 10, and the lowest power of a.","solution":"The GCF of 12 and 10 is 2. The lowest power of a is a². So the GCF is 2a², and 12a³ + 10a² = 2a²(6a + 5)."},{"id":"fs1-q2","type":"choice","prompt":"Factor 14m⁸n⁵ − 7m²n².","choices":["7m²n²(2m⁶n³ − 1)","7m²n²(2m⁶n³)","7m²n²(2m⁴n³ − 1)","7m⁸n⁵(2 − 1)"],"answer":0,"hint":"When a term is exactly the GCF, a 1 is left behind.","solution":"GCF: 7m²n². 14m⁸n⁵ ÷ 7m²n² = 2m⁶n³ and 7m²n² ÷ 7m²n² = 1. Answer: 7m²n²(2m⁶n³ − 1)."},{"id":"fs1-q3","type":"choice","prompt":"Factor 18p⁸q³ + 28p⁶q⁵.","choices":["2p⁶q³(9p² + 14q²)","p⁶q³(18p² + 28q²)","2p²q²(9p⁶q + 14p⁴q³)","2p⁶q³(9p² + 14q⁵)"],"answer":0,"hint":"Use the greatest number and the lowest power of each variable.","solution":"GCF of 18 and 28 is 2. Lowest powers: p⁶ and q³. 18p⁸q³ ÷ 2p⁶q³ = 9p², 28p⁶q⁵ ÷ 2p⁶q³ = 14q². Answer: 2p⁶q³(9p² + 14q²)."},{"id":"fs1-q4","type":"choice","prompt":"Factor m² − 25.","choices":["(m + 5)(m − 5)","(m − 5)²","(m + 25)(m − 1)","m(m − 25)"],"answer":0,"hint":"m² − 25 is a difference of squares.","solution":"m² = (m)² and 25 = 5². So m² − 25 = (m + 5)(m − 5)."},{"id":"fs1-q5","type":"choice","prompt":"Factor 72c⁴ − 2 completely.","choices":["2(6c² + 1)(6c² − 1)","2(36c⁴ − 1)","2(6c² − 1)²","2(18c² + 1)(18c² − 1)"],"answer":0,"hint":"Take out the GCF 2 first. Then look for a difference of squares.","solution":"72c⁴ − 2 = 2(36c⁴ − 1). 36c⁴ = (6c²)² and 1 = 1². So 2(6c² + 1)(6c² − 1)."},{"id":"fs1-q6","type":"choice","prompt":"Factor 7m⁷n − 28mn³ completely.","choices":["7mn(m³ + 2n)(m³ − 2n)","7mn(m⁶ − 4n²)","7mn(m³ − 2n)²","7m(m⁶n − 4n³)"],"answer":0,"hint":"GCF first, then check what is left for a difference of squares.","solution":"GCF: 7mn(m⁶ − 4n²). m⁶ = (m³)² and 4n² = (2n)². Answer: 7mn(m³ + 2n)(m³ − 2n)."},{"id":"fs1-q7","type":"choice","prompt":"Factor x⁴ − 36 completely.","choices":["(x² + 6)(x² − 6)","(x² − 6)²","(x + 6)(x − 6)","(x² + 6)(x + 6)(x − 6)"],"answer":0,"hint":"x⁴ = (x²)². Is 6 a perfect square?","solution":"x⁴ − 36 = (x² + 6)(x² − 6). 6 is not a perfect square, so x² − 6 does not factor any further."},{"id":"fs1-q8","type":"choice","prompt":"Factor 9y⁷ − 144y completely.","choices":["9y(y³ + 4)(y³ − 4)","9y(y⁶ − 16)","9y(y³ − 4)²","9y(y² + 4)(y² − 4)"],"answer":0,"hint":"GCF is 9y. What is left is a difference of squares.","solution":"9y⁷ − 144y = 9y(y⁶ − 16). y⁶ = (y³)² and 16 = 4². Answer: 9y(y³ + 4)(y³ − 4)."},{"id":"fs1-q9","type":"choice","prompt":"Factor 3m⁴ − 48n² completely.","choices":["3(m² + 4n)(m² − 4n)","3(m⁴ − 16n²)","3(m² − 4n)²","3(m² + 8n)(m² − 8n)"],"answer":0,"hint":"GCF 3 first. Then m⁴ = (m²)² and 16n² = (4n)².","solution":"3m⁴ − 48n² = 3(m⁴ − 16n²) = 3(m² + 4n)(m² − 4n)."}]},{"id":"factor-special-2","teach":[{"title":"Sum of cubes","text":["a³ + b³ = (a + b)(a² − ab + b²).","Perfect cubes: 1, 8, 27, 64, 125, 216, 343, 512, 1000, and powers like x³, x⁶.","SOAP helps with the signs: Same sign, Opposite sign, Always Positive."],"example":{"problem":"Factor x³ + 27.","steps":["x³ = (x)³ and 27 = 3³. So a = x and b = 3.","(a + b) = (x + 3).","a² − ab + b² = x² − 3x + 9.","Answer: (x + 3)(x² − 3x + 9)"]}},{"title":"Difference of cubes","text":["a³ − b³ = (a − b)(a² + ab + b²).","Same SOAP pattern: the first sign matches, the middle sign is opposite, the last sign is always +."],"example":{"problem":"Factor 216k³ − 125.","steps":["216k³ = (6k)³ and 125 = 5³. So a = 6k and b = 5.","(a − b) = (6k − 5).","a² + ab + b² = 36k² + 30k + 25.","Answer: (6k − 5)(36k² + 30k + 25)"]}},{"title":"GCF first, then cubes","text":["If the numbers are not perfect cubes, look for a GCF that leaves perfect cubes behind."],"example":{"problem":"Factor 500a³ + 4.","steps":["GCF 4: 4(125a³ + 1).","125a³ = (5a)³ and 1 = 1³.","Answer: 4(5a + 1)(25a² − 5a + 1)"]}}],"questions":[{"id":"fs2-q1","type":"choice","prompt":"Which is the sum of cubes pattern for a³ + b³?","choices":["(a + b)(a² − ab + b²)","(a + b)(a² + ab + b²)","(a + b)(a − b)","(a + b)³"],"answer":0,"hint":"SOAP: Same, Opposite, Always Positive.","solution":"a³ + b³ = (a + b)(a² − ab + b²). The first sign is the same (+), the middle is opposite (−), the last is always positive (+)."},{"id":"fs2-q2","type":"choice","prompt":"Factor 8w³ + 1.","choices":["(2w + 1)(4w² − 2w + 1)","(2w + 1)(4w² + 2w + 1)","(2w − 1)(4w² + 2w + 1)","(2w + 1)(4w² − 4w + 1)"],"answer":0,"hint":"8w³ = (2w)³ and 1 = 1³.","solution":"a = 2w, b = 1. (a + b)(a² − ab + b²) = (2w + 1)(4w² − 2w + 1)."},{"id":"fs2-q3","type":"choice","prompt":"Factor x³ − 1.","choices":["(x − 1)(x² + x + 1)","(x − 1)(x² − x + 1)","(x − 1)(x² + 1)","(x + 1)(x² − x + 1)"],"answer":0,"hint":"Difference of cubes: (a − b)(a² + ab + b²).","solution":"a = x, b = 1. (x − 1)(x² + x + 1)."},{"id":"fs2-q4","type":"choice","prompt":"Factor 64 − w³.","choices":["(4 − w)(16 + 4w + w²)","(4 − w)(16 − 4w + w²)","(w − 4)(w² + 4w + 16)","(4 + w)(16 − 4w + w²)"],"answer":0,"hint":"Here a = 4 and b = w. Keep the order: 64 comes first.","solution":"64 = 4³. a³ − b³ = (a − b)(a² + ab + b²) = (4 − w)(16 + 4w + w²)."},{"id":"fs2-q5","type":"choice","prompt":"Factor m³ + 216n³.","choices":["(m + 6n)(m² − 6mn + 36n²)","(m + 6n)(m² + 6mn + 36n²)","(m − 6n)(m² + 6mn + 36n²)","(m + 6n)(m² − 12mn + 36n²)"],"answer":0,"hint":"216n³ = (6n)³.","solution":"a = m, b = 6n. (m + 6n)(m² − 6mn + 36n²)."},{"id":"fs2-q6","type":"choice","prompt":"Factor 343p³ + 64q³.","choices":["(7p + 4q)(49p² − 28pq + 16q²)","(7p + 4q)(49p² + 28pq + 16q²)","(7p + 4q)(49p² − 56pq + 16q²)","(7p − 4q)(49p² + 28pq + 16q²)"],"answer":0,"hint":"343 = 7³ and 64 = 4³.","solution":"a = 7p, b = 4q. a² = 49p², ab = 28pq, b² = 16q². Answer: (7p + 4q)(49p² − 28pq + 16q²)."},{"id":"fs2-q7","type":"choice","prompt":"Factor 2x³ − 54y³ completely.","choices":["2(x − 3y)(x² + 3xy + 9y²)","2(x − 3y)(x² − 3xy + 9y²)","2(x + 3y)(x² − 3xy + 9y²)","(2x − 3y)(4x² + 6xy + 9y²)"],"answer":0,"hint":"Take out the GCF 2 first. 27y³ = (3y)³.","solution":"2x³ − 54y³ = 2(x³ − 27y³) = 2(x − 3y)(x² + 3xy + 9y²)."},{"id":"fs2-q8","type":"choice","prompt":"Factor 54x³ + 250y³ completely.","choices":["2(3x + 5y)(9x² − 15xy + 25y²)","2(3x + 5y)(9x² + 15xy + 25y²)","(3x + 5y)(9x² − 15xy + 25y²)","2(3x − 5y)(9x² + 15xy + 25y²)"],"answer":0,"hint":"GCF 2 first: 54 = 2 · 27 and 250 = 2 · 125.","solution":"54x³ + 250y³ = 2(27x³ + 125y³). a = 3x, b = 5y. Answer: 2(3x + 5y)(9x² − 15xy + 25y²)."},{"id":"fs2-q9","type":"choice","prompt":"Factor x³y² − 343y⁵ completely.","choices":["y²(x − 7y)(x² + 7xy + 49y²)","y²(x − 7y)(x² − 7xy + 49y²)","y²(x + 7y)(x² − 7xy + 49y²)","y(x − 7y)(x² + 7xy + 49y²)"],"answer":0,"hint":"GCF y² first. Then 343y³ = (7y)³.","solution":"x³y² − 343y⁵ = y²(x³ − 343y³) = y²(x − 7y)(x² + 7xy + 49y²)."}]},{"id":"factor-special-3","teach":[{"title":"Taking out a negative GCF","text":["If the first term is negative, take out a negative GCF. Then every sign inside the parentheses changes.","Check by distributing back."],"example":{"problem":"Factor −6x³ + 9x² − 12x.","steps":["The GCF of 6, 9, and 12 is 3, and the lowest power of x is x. The first term is negative, so use −3x.","−6x³ ÷ (−3x) = 2x². 9x² ÷ (−3x) = −3x. −12x ÷ (−3x) = 4.","Answer: −3x(2x² − 3x + 4)"]}},{"title":"Difference of squares, twice","text":["After you factor a² − b² into (a + b)(a − b), look at a − b again. If it is still a difference of squares, factor it again.","A sum of squares like a² + b² does not factor."],"example":{"problem":"Factor 16a⁴ − 81 completely.","steps":["16a⁴ = (4a²)² and 81 = 9². So 16a⁴ − 81 = (4a² + 9)(4a² − 9).","4a² − 9 = (2a)² − 3², so it factors again: (2a + 3)(2a − 3).","4a² + 9 is a sum, so it stays.","Answer: (4a² + 9)(2a + 3)(2a − 3)"]}}],"questions":[{"id":"fs3-q1","type":"choice","prompt":"What is the GCF of 20x⁴y² − 15x³y⁵?","choices":["5x³y²","5x⁴y⁵","5xy","15x³y²"],"answer":0,"hint":"Use the GCF of 20 and 15, and the lowest power of each variable.","solution":"The GCF of 20 and 15 is 5. The lowest powers are x³ and y². GCF: 5x³y². Then 20x⁴y² − 15x³y⁵ = 5x³y²(4x − 3y³)."},{"id":"fs3-q2","type":"choice","prompt":"Factor 18x⁵ − 30x³ + 6x².","choices":["6x²(3x³ − 5x + 1)","6x²(3x³ − 5x)","6x²(3x² − 5x + 1)","6x²(3x³ + 5x + 1)"],"answer":0,"hint":"The GCF is 6x². When a term is exactly the GCF, a 1 is left.","solution":"18x⁵ ÷ 6x² = 3x³. −30x³ ÷ 6x² = −5x. 6x² ÷ 6x² = 1. Answer: 6x²(3x³ − 5x + 1)."},{"id":"fs3-q3","type":"choice","prompt":"Factor 4x² − 121.","choices":["(2x + 11)(2x − 11)","(2x − 11)²","(4x + 11)(4x − 11)","(2x + 11)²"],"answer":0,"hint":"4x² = (2x)² and 121 = 11².","solution":"a = 2x and b = 11, so 4x² − 121 = (2x + 11)(2x − 11)."},{"id":"fs3-q4","type":"choice","prompt":"Factor −4m³ + 10m² − 2m.","choices":["−2m(2m² − 5m + 1)","−2m(−2m² + 5m − 1)","−2m(2m² − 5m)","2m(2m² − 5m + 1)"],"answer":0,"hint":"The first term is negative, so take out −2m. Every sign inside changes.","solution":"−4m³ ÷ (−2m) = 2m². 10m² ÷ (−2m) = −5m. −2m ÷ (−2m) = 1. Answer: −2m(2m² − 5m + 1)."},{"id":"fs3-q5","type":"choice","prompt":"Factor 25a² − 64b².","choices":["(5a + 8b)(5a − 8b)","(5a − 8b)²","(25a + 64b)(25a − 64b)","(5a + 4b)(5a − 16b)"],"answer":0,"hint":"Write each term as something squared.","solution":"25a² = (5a)² and 64b² = (8b)². Answer: (5a + 8b)(5a − 8b)."},{"id":"fs3-q6","type":"choice","prompt":"Factor 81y⁴ − 1 completely.","choices":["(9y² + 1)(3y + 1)(3y − 1)","(9y² + 1)(3y − 1)²","(9y² − 1)²","(9y + 1)(9y − 1)"],"answer":0,"hint":"81y⁴ = (9y²)². After the first step, one factor is another difference of squares.","solution":"81y⁴ − 1 = (9y² + 1)(9y² − 1). 9y² − 1 = (3y + 1)(3y − 1). 9y² + 1 is a sum, so it stays. Answer: (9y² + 1)(3y + 1)(3y − 1)."},{"id":"fs3-q7","type":"choice","prompt":"Factor 12x³ − 75x completely.","choices":["3x(2x + 5)(2x − 5)","3x(2x − 5)²","3(2x + 5)(2x − 5)","3x(2x² + 5)(2x² − 5)"],"answer":0,"hint":"Take out the GCF 3x first. What is left is a difference of squares.","solution":"12x³ − 75x = 3x(4x² − 25). 4x² = (2x)² and 25 = 5². Answer: 3x(2x + 5)(2x − 5)."},{"id":"fs3-q8","type":"choice","prompt":"Factor 2x⁶ − 32x² completely.","choices":["2x²(x² + 4)(x + 2)(x − 2)","2x²(x² + 4)(x − 2)²","2x²(x² − 4)²","2x(x² + 4)(x + 2)(x − 2)"],"answer":0,"hint":"GCF 2x² first. Then x⁴ − 16 is a difference of squares, twice.","solution":"2x²(x⁴ − 16) = 2x²(x² + 4)(x² − 4) = 2x²(x² + 4)(x + 2)(x − 2)."}]},{"id":"factor-special-4","teach":[{"title":"Which pattern?","text":["Always take out a GCF first.","Two terms with a minus sign: look for a difference of squares or a difference of cubes.","Two terms with a plus sign: look for a sum of cubes. A sum of squares does not factor."],"example":{"problem":"Factor 3x³ + 24.","steps":["GCF 3: 3(x³ + 8).","x³ = (x)³ and 8 = 2³, so x³ + 8 is a sum of cubes with a = x and b = 2.","(a + b)(a² − ab + b²) = (x + 2)(x² − 2x + 4).","Answer: 3(x + 2)(x² − 2x + 4)"]}},{"title":"Cubes with two variables","text":["Write each term as something cubed: 27a³ = (3a)³ and 8b³ = (2b)³.","Then use the pattern with 3a in place of a and 2b in place of b."],"example":{"problem":"Factor 27a³ − 8b³.","steps":["27a³ = (3a)³ and 8b³ = (2b)³.","Difference of cubes: (3a − 2b)((3a)² + (3a)(2b) + (2b)²).","Answer: (3a − 2b)(9a² + 6ab + 4b²)"]}}],"questions":[{"id":"fs4-q1","type":"choice","prompt":"Which binomial is a difference of cubes?","choices":["8x³ − 27","x² − 49","8x³ + 27","x³ − 12"],"answer":0,"hint":"You need two perfect cubes with a minus sign between them.","solution":"8x³ = (2x)³ and 27 = 3³, with a minus sign. x² − 49 is a difference of squares, 8x³ + 27 is a sum, and 12 is not a perfect cube."},{"id":"fs4-q2","type":"choice","prompt":"Factor y³ + 64.","choices":["(y + 4)(y² − 4y + 16)","(y + 4)(y² + 4y + 16)","(y − 4)(y² + 4y + 16)","(y + 4)(y² − 8y + 16)"],"answer":0,"hint":"64 = 4³. Use the sum of cubes pattern. SOAP: Same, Opposite, Always Positive.","solution":"a = y and b = 4. (a + b)(a² − ab + b²) = (y + 4)(y² − 4y + 16)."},{"id":"fs4-q3","type":"choice","prompt":"Factor 125x³ − 1.","choices":["(5x − 1)(25x² + 5x + 1)","(5x − 1)(25x² − 5x + 1)","(5x + 1)(25x² − 5x + 1)","(5x − 1)(25x² + 10x + 1)"],"answer":0,"hint":"125x³ = (5x)³ and 1 = 1³. The middle term is ab, not 2ab.","solution":"a = 5x and b = 1. (a − b)(a² + ab + b²) = (5x − 1)(25x² + 5x + 1)."},{"id":"fs4-q4","type":"choice","prompt":"Factor 8a³ + 27b³.","choices":["(2a + 3b)(4a² − 6ab + 9b²)","(2a + 3b)(4a² + 6ab + 9b²)","(2a − 3b)(4a² + 6ab + 9b²)","(2a + 3b)(4a² − 12ab + 9b²)"],"answer":0,"hint":"8a³ = (2a)³ and 27b³ = (3b)³.","solution":"Use 2a and 3b: (2a + 3b)((2a)² − (2a)(3b) + (3b)²) = (2a + 3b)(4a² − 6ab + 9b²)."},{"id":"fs4-q5","type":"choice","prompt":"Factor 3x³ − 81 completely.","choices":["3(x − 3)(x² + 3x + 9)","3(x − 3)(x² − 3x + 9)","3(x + 3)(x² − 3x + 9)","3(x − 3)(x² + 9)"],"answer":0,"hint":"Take out 3 first. 81 ÷ 3 = 27 = 3³.","solution":"3x³ − 81 = 3(x³ − 27) = 3(x − 3)(x² + 3x + 9)."},{"id":"fs4-q6","type":"choice","prompt":"Factor 16m⁴ + 54m completely.","choices":["2m(2m + 3)(4m² − 6m + 9)","2m(2m + 3)(4m² + 6m + 9)","2m(2m − 3)(4m² + 6m + 9)","2(2m + 3)(4m² − 6m + 9)"],"answer":0,"hint":"The GCF is 2m. What is left is a sum of cubes.","solution":"16m⁴ + 54m = 2m(8m³ + 27). 8m³ = (2m)³ and 27 = 3³. Answer: 2m(2m + 3)(4m² − 6m + 9)."},{"id":"fs4-q7","type":"choice","prompt":"Factor 2x⁴ − 2x completely.","choices":["2x(x − 1)(x² + x + 1)","2x(x − 1)(x² − x + 1)","2x(x + 1)(x² − x + 1)","2x(x − 1)(x² + 1)"],"answer":0,"hint":"GCF 2x first. Then x³ − 1 is a difference of cubes.","solution":"2x⁴ − 2x = 2x(x³ − 1) = 2x(x − 1)(x² + x + 1)."},{"id":"fs4-q8","type":"choice","prompt":"Factor 5x²y − 45y³ completely.","choices":["5y(x + 3y)(x − 3y)","5y(x − 3y)²","5(x + 3y)(x − 3y)","5y(x − 3y)(x² + 3xy + 9y²)"],"answer":0,"hint":"GCF 5y first. Then decide: squares or cubes?","solution":"5x²y − 45y³ = 5y(x² − 9y²). The exponents are 2, so it is a difference of squares: 5y(x + 3y)(x − 3y)."},{"id":"fs4-q9","type":"choice","prompt":"Factor 1000 − 27k³.","choices":["(10 − 3k)(100 + 30k + 9k²)","(10 − 3k)(100 − 30k + 9k²)","(3k − 10)(9k² + 30k + 100)","(10 + 3k)(100 − 30k + 9k²)"],"answer":0,"hint":"1000 = 10³ and 27k³ = (3k)³. Keep the order: 1000 comes first.","solution":"a = 10 and b = 3k. (a − b)(a² + ab + b²) = (10 − 3k)(100 + 30k + 9k²)."}]}]},{"id":"factor-trinomials","title":"Factoring: trinomials and grouping","lessons":[{"id":"factor-trinomials-1","teach":[{"title":"Trinomials with a = 1","text":["For x² + bx + c, find two numbers that multiply to c and add to b.","Then x² + bx + c = (x + first number)(x + second number)."],"example":{"problem":"Factor k² + 15k + 56.","steps":["You need two numbers that multiply to 56 and add to 15.","7 · 8 = 56 and 7 + 8 = 15.","Answer: (k + 7)(k + 8)"]}},{"title":"Trinomials with a > 1","text":["For ax² + bx + c, multiply a · c. Find two numbers that multiply to ac and add to b.","Split the middle term with those two numbers, then factor by grouping."],"example":{"problem":"Factor 3x² − 10x + 8.","steps":["a · c = 3 · 8 = 24. Two numbers that multiply to 24 and add to −10: −4 and −6.","Split: 3x² − 4x − 6x + 8.","Group: x(3x − 4) − 2(3x − 4).","Answer: (x − 2)(3x − 4)"]}},{"title":"GCF first","text":["Always pull out a GCF before you factor the trinomial. It makes the numbers smaller."],"example":{"problem":"Factor w³ + w² − 20w.","steps":["GCF: w(w² + w − 20).","Two numbers that multiply to −20 and add to 1: 5 and −4.","Answer: w(w + 5)(w − 4)"]}}],"questions":[{"id":"ft1-q1","type":"choice","prompt":"Factor n² + 7n − 30.","choices":["(n + 10)(n − 3)","(n − 10)(n + 3)","(n + 6)(n − 5)","(n + 15)(n − 2)"],"answer":0,"hint":"Find two numbers that multiply to −30 and add to 7.","solution":"10 · (−3) = −30 and 10 + (−3) = 7. Answer: (n + 10)(n − 3)."},{"id":"ft1-q2","type":"choice","prompt":"Factor p² − 16p + 64.","choices":["(p − 8)²","(p + 8)²","(p + 8)(p − 8)","(p − 16)(p − 4)"],"answer":0,"hint":"Two numbers that multiply to 64 and add to −16.","solution":"(−8)(−8) = 64 and −8 + (−8) = −16. So (p − 8)(p − 8) = (p − 8)²."},{"id":"ft1-q3","type":"choice","prompt":"Factor r² − 11r − 42.","choices":["(r − 14)(r + 3)","(r + 14)(r − 3)","(r − 7)(r + 6)","(r − 6)(r − 7)"],"answer":0,"hint":"Two numbers that multiply to −42 and add to −11.","solution":"−14 · 3 = −42 and −14 + 3 = −11. Answer: (r − 14)(r + 3)."},{"id":"ft1-q4","type":"choice","prompt":"Factor 2a³ + 38a² + 68a completely.","choices":["2a(a + 17)(a + 2)","2a(a + 34)(a + 1)","2(a + 17)(a + 2)","a(2a + 34)(a + 2)"],"answer":0,"hint":"Take out the GCF 2a first.","solution":"2a(a² + 19a + 34). 17 · 2 = 34 and 17 + 2 = 19. Answer: 2a(a + 17)(a + 2)."},{"id":"ft1-q5","type":"choice","prompt":"Factor 8x² − 6x − 5.","choices":["(2x + 1)(4x − 5)","(2x − 1)(4x + 5)","(8x − 5)(x + 1)","(4x + 1)(2x − 5)"],"answer":0,"hint":"a · c = 8 · (−5) = −40. Find numbers that multiply to −40 and add to −6.","solution":"−10 and 4. Split: 8x² − 10x + 4x − 5 = 2x(4x − 5) + 1(4x − 5) = (2x + 1)(4x − 5)."},{"id":"ft1-q6","type":"choice","prompt":"Factor w² − 13w + 36.","choices":["(w − 4)(w − 9)","(w + 4)(w + 9)","(w − 6)²","(w − 12)(w − 3)"],"answer":0,"hint":"Two numbers that multiply to +36 and add to −13. Both must be negative.","solution":"(−4)(−9) = 36 and −4 + (−9) = −13. Answer: (w − 4)(w − 9)."},{"id":"ft1-q7","type":"choice","prompt":"Factor p³ + 5p² − 84p completely.","choices":["p(p + 12)(p − 7)","p(p − 12)(p + 7)","p(p + 14)(p − 6)","p(p + 21)(p − 4)"],"answer":0,"hint":"GCF p first. Then two numbers that multiply to −84 and add to 5.","solution":"p(p² + 5p − 84). 12 · (−7) = −84 and 12 + (−7) = 5. Answer: p(p + 12)(p − 7)."},{"id":"ft1-q8","type":"choice","prompt":"Factor −x³ + 4x² + 21x completely.","choices":["−x(x − 7)(x + 3)","−x(x + 7)(x − 3)","x(x − 7)(x + 3)","−x(x − 7)(x − 3)"],"answer":0,"hint":"When the leading term is negative, take out −x so the trinomial starts with +x².","solution":"−x(x² − 4x − 21). −7 · 3 = −21 and −7 + 3 = −4. Answer: −x(x − 7)(x + 3)."}]},{"id":"factor-trinomials-2","teach":[{"title":"Quadratic form","text":["When the exponents are 4 and 2 (or 6, 4, and 2), treat x² like one variable.","Factor it like a normal trinomial, then check whether any factor is a difference of squares."],"example":{"problem":"Factor n⁴ + 2n² − 24 completely.","steps":["Think of n² as one thing: (n²)² + 2(n²) − 24.","6 · (−4) = −24 and 6 + (−4) = 2, so (n² + 6)(n² − 4).","n² − 4 is a difference of squares: (n + 2)(n − 2).","Answer: (n² + 6)(n + 2)(n − 2)"]}},{"title":"Four terms: grouping","text":["Step 1: group the first two terms and the last two terms.","Step 2: factor the GCF out of each group.","Step 3: factor out the binomial the groups share."],"example":{"problem":"Factor x³ + x² − 4x − 4 completely.","steps":["Group: (x³ + x²) + (−4x − 4).","GCF of each: x²(x + 1) − 4(x + 1).","Common binomial: (x² − 4)(x + 1).","x² − 4 is a difference of squares. Answer: (x + 2)(x − 2)(x + 1)"]}}],"questions":[{"id":"ft2-q1","type":"choice","prompt":"Factor 3x⁴ + 14x² − 5.","choices":["(3x² − 1)(x² + 5)","(3x² + 1)(x² − 5)","(3x² − 5)(x² + 1)","(3x² + 5)(x² − 1)"],"answer":0,"hint":"Treat x² as one variable: 3u² + 14u − 5. a · c = −15.","solution":"Numbers that multiply to −15 and add to 14: 15 and −1. 3x⁴ + 15x² − x² − 5 = 3x²(x² + 5) − 1(x² + 5) = (3x² − 1)(x² + 5)."},{"id":"ft2-q2","type":"choice","prompt":"Factor 12m⁴ − 11m² + 2 completely.","choices":["(3m² − 2)(2m + 1)(2m − 1)","(3m² − 2)(4m² − 1)","(3m² + 2)(2m + 1)(2m − 1)","(4m² − 2)(3m² − 1)"],"answer":0,"hint":"Factor like a trinomial in m², then check each factor for a difference of squares.","solution":"a · c = 24; −3 and −8 add to −11. 12m⁴ − 3m² − 8m² + 2 = 3m²(4m² − 1) − 2(4m² − 1) = (3m² − 2)(4m² − 1). 4m² − 1 = (2m + 1)(2m − 1)."},{"id":"ft2-q3","type":"choice","prompt":"Factor x³ − x² + 9x − 9.","choices":["(x² + 9)(x − 1)","(x + 3)(x − 3)(x − 1)","(x² + 9)(x + 1)","(x² − 9)(x + 1)"],"answer":0,"hint":"Group the first two terms and the last two terms.","solution":"x²(x − 1) + 9(x − 1) = (x² + 9)(x − 1). x² + 9 is a sum of squares, so it does not factor."},{"id":"ft2-q4","type":"choice","prompt":"Factor k³ + 5k² − k − 5 completely.","choices":["(k + 1)(k − 1)(k + 5)","(k² − 1)(k + 5)","(k² + 1)(k + 5)","(k + 1)(k − 1)(k − 5)"],"answer":0,"hint":"After grouping, check whether a factor is a difference of squares.","solution":"k²(k + 5) − 1(k + 5) = (k² − 1)(k + 5) = (k + 1)(k − 1)(k + 5)."},{"id":"ft2-q5","type":"choice","prompt":"Factor 4v³ − 5v² − 16v + 20 completely.","choices":["(v + 2)(v − 2)(4v − 5)","(v² + 4)(4v − 5)","(v + 2)(v − 2)(4v + 5)","(v − 2)²(4v − 5)"],"answer":0,"hint":"Take −4 out of the second group so both groups share (4v − 5).","solution":"v²(4v − 5) − 4(4v − 5) = (v² − 4)(4v − 5) = (v + 2)(v − 2)(4v − 5)."},{"id":"ft2-q6","type":"choice","prompt":"Factor 2x⁵ − 18x⁴ + 7x − 63.","choices":["(2x⁴ + 7)(x − 9)","(2x⁴ − 7)(x − 9)","(2x⁴ + 7)(x + 9)","2x⁴(x − 9) + 7(x − 9)"],"answer":0,"hint":"Group and factor 2x⁴ out of the first pair and 7 out of the second.","solution":"2x⁴(x − 9) + 7(x − 9) = (2x⁴ + 7)(x − 9). The last choice is not finished: the common (x − 9) still has to come out."},{"id":"ft2-q7","type":"choice","prompt":"Factor x⁴ − 12x² + 36.","choices":["(x² − 6)²","(x² + 6)²","(x² + 6)(x² − 6)","(x − 6)²"],"answer":0,"hint":"Treat x² as one variable: u² − 12u + 36.","solution":"(−6)(−6) = 36 and −6 + (−6) = −12. So (x² − 6)(x² − 6) = (x² − 6)²."},{"id":"ft2-q8","type":"choice","prompt":"Factor w⁴ − 14w² − 32 completely.","choices":["(w + 4)(w − 4)(w² + 2)","(w² − 16)(w² + 2)","(w + 4)(w − 4)(w² − 2)","(w² + 16)(w² − 2)"],"answer":0,"hint":"Two numbers that multiply to −32 and add to −14. Then check for a difference of squares.","solution":"−16 and 2: (w² − 16)(w² + 2). w² − 16 = (w + 4)(w − 4). Answer: (w + 4)(w − 4)(w² + 2)."},{"id":"ft2-q9","type":"choice","prompt":"Factor x³ − 7x² + x − 7.","choices":["(x² + 1)(x − 7)","(x² − 1)(x − 7)","(x + 1)(x − 1)(x − 7)","(x² + 1)(x + 7)"],"answer":0,"hint":"The second group is x − 7, so its GCF is 1.","solution":"x²(x − 7) + 1(x − 7) = (x² + 1)(x − 7)."}]},{"id":"factor-trinomials-3","teach":[{"title":"Sign patterns","text":["For x² + bx + c, look at the sign of c first.","If c is positive, both numbers have the same sign as b. If c is negative, the numbers have opposite signs, and the one farther from 0 has the sign of b."],"example":{"problem":"Factor x² − 3x − 40.","steps":["c = −40 is negative, so the signs are opposite. b = −3, so the bigger number is negative.","Pairs for 40: 1 and 40, 2 and 20, 4 and 10, 5 and 8. −8 + 5 = −3.","Answer: (x − 8)(x + 5)"]}},{"title":"Check by multiplying back","text":["After you factor, multiply the factors back out (FOIL). You should get the trinomial you started with.","This catches sign mistakes."],"example":{"problem":"Factor 2x² + 7x + 3 and check.","steps":["a · c = 6. Two numbers that multiply to 6 and add to 7: 6 and 1.","Split: 2x² + 6x + x + 3 = 2x(x + 3) + 1(x + 3) = (2x + 1)(x + 3).","Check: (2x + 1)(x + 3) = 2x² + 6x + x + 3 = 2x² + 7x + 3. It matches."]}}],"questions":[{"id":"ft3-q1","type":"input","prompt":"Two numbers multiply to −24 and add to 5. What are they? Type them separated by a comma.","answers":["8, -3"],"hint":"The product is negative, so one number is negative. The sum is positive, so the bigger one is positive.","solution":"8 · (−3) = −24 and 8 + (−3) = 5. The numbers are 8 and −3."},{"id":"ft3-q2","type":"choice","prompt":"Factor x² + 9x + 20.","choices":["(x + 4)(x + 5)","(x + 2)(x + 10)","(x − 4)(x − 5)","(x + 1)(x + 20)"],"answer":0,"hint":"Two numbers that multiply to 20 and add to 9.","solution":"4 · 5 = 20 and 4 + 5 = 9. Answer: (x + 4)(x + 5)."},{"id":"ft3-q3","type":"choice","prompt":"Factor y² − 2y − 35.","choices":["(y − 7)(y + 5)","(y + 7)(y − 5)","(y − 7)(y − 5)","(y − 35)(y + 1)"],"answer":0,"hint":"c is negative, so the signs are opposite. The bigger number is negative because b is negative.","solution":"−7 · 5 = −35 and −7 + 5 = −2. Answer: (y − 7)(y + 5)."},{"id":"ft3-q4","type":"choice","prompt":"Factor m² − 14m + 45.","choices":["(m − 5)(m − 9)","(m + 5)(m + 9)","(m − 3)(m − 15)","(m + 5)(m − 9)"],"answer":0,"hint":"c is positive and b is negative, so both numbers are negative.","solution":"(−5)(−9) = 45 and −5 + (−9) = −14. Answer: (m − 5)(m − 9)."},{"id":"ft3-q5","type":"choice","prompt":"Factor 2x² + 11x + 12.","choices":["(2x + 3)(x + 4)","(2x + 4)(x + 3)","(2x + 1)(x + 12)","(2x − 3)(x − 4)"],"answer":0,"hint":"a · c = 24. Find two numbers that multiply to 24 and add to 11.","solution":"8 and 3. Split: 2x² + 8x + 3x + 12 = 2x(x + 4) + 3(x + 4) = (2x + 3)(x + 4)."},{"id":"ft3-q6","type":"choice","prompt":"Factor 3x² − 7x − 6.","choices":["(3x + 2)(x − 3)","(3x − 2)(x + 3)","(3x − 3)(x + 2)","(3x + 1)(x − 6)"],"answer":0,"hint":"a · c = −18. Find two numbers that multiply to −18 and add to −7.","solution":"−9 and 2. Split: 3x² − 9x + 2x − 6 = 3x(x − 3) + 2(x − 3) = (3x + 2)(x − 3)."},{"id":"ft3-q7","type":"choice","prompt":"Factor 5x³ − 15x² − 50x completely.","choices":["5x(x − 5)(x + 2)","5x(x + 5)(x − 2)","5(x − 5)(x + 2)","5x(x − 10)(x + 1)"],"answer":0,"hint":"Take out the GCF 5x first.","solution":"5x(x² − 3x − 10). −5 · 2 = −10 and −5 + 2 = −3. Answer: 5x(x − 5)(x + 2)."},{"id":"ft3-q8","type":"choice","prompt":"Factor 6x² + x − 15.","choices":["(2x − 3)(3x + 5)","(2x + 3)(3x − 5)","(6x − 5)(x + 3)","(3x − 3)(2x + 5)"],"answer":0,"hint":"a · c = −90. Find two numbers that multiply to −90 and add to 1.","solution":"10 and −9. Split: 6x² + 10x − 9x − 15 = 2x(3x + 5) − 3(3x + 5) = (2x − 3)(3x + 5)."}]},{"id":"factor-trinomials-4","teach":[{"title":"Grouping with a negative","text":["When the third term is negative, take a negative GCF out of the second group. Then both groups share the same binomial."],"example":{"problem":"Factor 2x³ − 3x² − 8x + 12 completely.","steps":["Group: (2x³ − 3x²) + (−8x + 12).","GCF of each: x²(2x − 3) − 4(2x − 3).","Common binomial: (x² − 4)(2x − 3).","x² − 4 is a difference of squares. Answer: (x + 2)(x − 2)(2x − 3)"]}},{"title":"Quadratic form with a > 1","text":["Treat x² as one variable and use the a · c method.","Then check each factor for a difference of squares."],"example":{"problem":"Factor 2x⁴ − 7x² − 4 completely.","steps":["a · c = −8. Two numbers that multiply to −8 and add to −7: −8 and 1.","Split: 2x⁴ − 8x² + x² − 4 = 2x²(x² − 4) + 1(x² − 4) = (2x² + 1)(x² − 4).","x² − 4 = (x + 2)(x − 2).","Answer: (2x² + 1)(x + 2)(x − 2)"]}}],"questions":[{"id":"ft4-q1","type":"input","prompt":"2x⁴ + 5x² − 3 = (2x² − 1)(x² + k). What is k?","answers":["3"],"hint":"Multiply out (2x² − 1)(x² + k). The last term is −k.","solution":"The constant term of (2x² − 1)(x² + k) is −k. It must be −3, so k = 3. Check: (2x² − 1)(x² + 3) = 2x⁴ + 6x² − x² − 3 = 2x⁴ + 5x² − 3."},{"id":"ft4-q2","type":"choice","prompt":"Factor 9x² − 30x + 25.","choices":["(3x − 5)²","(3x + 5)(3x − 5)","(3x + 5)²","(9x − 5)(x − 5)"],"answer":0,"hint":"9x² = (3x)² and 25 = 5². Is the middle term 2 · 3x · 5?","solution":"2 · 3x · 5 = 30x, and the middle term is −30x. So it is a perfect square: (3x − 5)²."},{"id":"ft4-q3","type":"choice","prompt":"Factor x⁴ − 5x² + 4 completely.","choices":["(x + 1)(x − 1)(x + 2)(x − 2)","(x² + 1)(x + 2)(x − 2)","(x + 1)(x − 1)(x² + 4)","(x − 1)²(x − 2)²"],"answer":0,"hint":"Treat x² as one variable: u² − 5u + 4. Then check both factors for a difference of squares.","solution":"(x² − 1)(x² − 4). Both are differences of squares: (x + 1)(x − 1)(x + 2)(x − 2)."},{"id":"ft4-q4","type":"choice","prompt":"Factor y⁴ + 3y² − 28 completely.","choices":["(y² + 7)(y + 2)(y − 2)","(y² − 7)(y + 2)(y − 2)","(y² + 7)(y² + 4)","(y² + 4)(y² − 7)"],"answer":0,"hint":"Two numbers that multiply to −28 and add to 3.","solution":"7 and −4: (y² + 7)(y² − 4). y² − 4 = (y + 2)(y − 2). Answer: (y² + 7)(y + 2)(y − 2)."},{"id":"ft4-q5","type":"choice","prompt":"Factor x³ + 4x² − 9x − 36 completely.","choices":["(x + 3)(x − 3)(x + 4)","(x² + 9)(x + 4)","(x + 3)(x − 3)(x − 4)","(x − 3)²(x + 4)"],"answer":0,"hint":"Group, and take −9 out of the second group.","solution":"x²(x + 4) − 9(x + 4) = (x² − 9)(x + 4) = (x + 3)(x − 3)(x + 4)."},{"id":"ft4-q6","type":"choice","prompt":"Factor 5x³ + 2x² + 15x + 6.","choices":["(x² + 3)(5x + 2)","(x² + 3)(5x − 2)","(x² − 3)(5x + 2)","(x² + 2)(5x + 3)"],"answer":0,"hint":"Group the first two terms and the last two terms.","solution":"x²(5x + 2) + 3(5x + 2) = (x² + 3)(5x + 2). x² + 3 does not factor."},{"id":"ft4-q7","type":"choice","prompt":"Factor 2x³ − 6x² − x + 3.","choices":["(2x² − 1)(x − 3)","(2x² + 1)(x − 3)","(2x² − 1)(x + 3)","(2x − 1)(x² − 3)"],"answer":0,"hint":"Take −1 out of the second group so it matches the first: −x + 3 = −1(x − 3).","solution":"2x²(x − 3) − 1(x − 3) = (2x² − 1)(x − 3). 2 is not a perfect square, so 2x² − 1 stays."},{"id":"ft4-q8","type":"choice","prompt":"Factor 4x⁴ − 13x² + 9 completely.","choices":["(2x + 3)(2x − 3)(x + 1)(x − 1)","(2x + 3)(2x − 3)(x² + 1)","(4x² + 9)(x + 1)(x − 1)","(2x − 3)²(x − 1)²"],"answer":0,"hint":"a · c = 36. Two numbers that multiply to 36 and add to −13. Then look for differences of squares.","solution":"−9 and −4: 4x⁴ − 9x² − 4x² + 9 = x²(4x² − 9) − 1(4x² − 9) = (x² − 1)(4x² − 9). Both factor: (2x + 3)(2x − 3)(x + 1)(x − 1)."},{"id":"ft4-q9","type":"choice","prompt":"Factor −2x³ − 4x² + 30x completely.","choices":["−2x(x + 5)(x − 3)","−2x(x − 5)(x + 3)","2x(x + 5)(x − 3)","−2x(x + 15)(x − 1)"],"answer":0,"hint":"The first term is negative, so take out −2x. Every sign inside changes.","solution":"−2x(x² + 2x − 15). 5 · (−3) = −15 and 5 + (−3) = 2. Answer: −2x(x + 5)(x − 3)."}]}]},{"id":"end-behavior","title":"Polynomial functions and end behavior","lessons":[{"id":"end-behavior-1","teach":[{"title":"Polynomial functions","text":["A polynomial function is a sum of terms like 4x³, −2x, and 7. Each term is a real number times x raised to a whole-number exponent (0, 1, 2, 3, …).","The degree is the greatest exponent. The leading coefficient is the number in front of that term, once it is in standard form.","Parent functions: constant y = c, linear y = x, quadratic y = x², cubic y = x³, quartic y = x⁴, quintic y = x⁵. The graph shows the cubic y = x³."],"example":{"problem":"f(x) = 4x³ − 2x + 7. Give its degree and leading coefficient.","steps":["It is already in standard form.","The greatest exponent is 3, so the degree is 3 (cubic).","The number in front of x³ is 4, so the leading coefficient is 4."]},"graph":{"fn":"x^3","x":[-3,3],"y":[-10,10]}},{"title":"End behavior rules","text":["End behavior is what f(x) does at the far left (x → −∞) and far right (x → ∞). Only the degree and the leading coefficient matter.","Even degree, positive: up on both ends. Even degree, negative: down on both ends.","Odd degree, positive: down on the left, up on the right. Odd degree, negative: up on the left, down on the right."],"example":{"problem":"Describe the end behavior of f(x) = −x⁴ + 3x³ − x².","steps":["The degree is 4 (even) and the leading coefficient is −1 (negative).","Even and negative: both ends go down.","As x → −∞, f(x) → −∞; as x → ∞, f(x) → −∞."]},"graph":{"fn":"-x^4+3x^3-x^2","x":[-2,4],"y":[-10,10]}}],"questions":[{"id":"eb1-q1","type":"input","prompt":"f(x) = 5x⁴ + 2x³ − 17x + 1. What is the degree?","answers":["4"],"hint":"The degree is the greatest exponent.","solution":"The exponents are 4, 3, 1, and 0. The greatest is 4."},{"id":"eb1-q2","type":"input","prompt":"f(x) = −x⁷ − 5x⁴ + 2x². What is the leading coefficient?","answers":["-1"],"hint":"Look at the number in front of the term with the greatest exponent.","solution":"The first term is −x⁷ = −1x⁷, so the leading coefficient is −1."},{"id":"eb1-q3","type":"choice","prompt":"f(x) = 3x² + 6x − 1. What is its end behavior?","choices":["As x → −∞, f(x) → ∞; as x → ∞, f(x) → ∞","As x → −∞, f(x) → −∞; as x → ∞, f(x) → −∞","As x → −∞, f(x) → −∞; as x → ∞, f(x) → ∞","As x → −∞, f(x) → ∞; as x → ∞, f(x) → −∞"],"answer":0,"hint":"Degree 2 is even. The leading coefficient 3 is positive.","solution":"Even degree with a positive leading coefficient: both ends go up. As x → −∞, f(x) → ∞; as x → ∞, f(x) → ∞."},{"id":"eb1-q4","type":"choice","prompt":"f(x) = −x² + x. What is its end behavior?","choices":["As x → −∞, f(x) → −∞; as x → ∞, f(x) → −∞","As x → −∞, f(x) → ∞; as x → ∞, f(x) → ∞","As x → −∞, f(x) → −∞; as x → ∞, f(x) → ∞","As x → −∞, f(x) → ∞; as x → ∞, f(x) → −∞"],"answer":0,"hint":"Degree 2 is even. The leading coefficient is −1.","solution":"Even degree with a negative leading coefficient: both ends go down. As x → −∞, f(x) → −∞; as x → ∞, f(x) → −∞."},{"id":"eb1-q5","type":"choice","prompt":"f(x) = 2x³ − 8x + 2. What is its end behavior?","choices":["As x → −∞, f(x) → −∞; as x → ∞, f(x) → ∞","As x → −∞, f(x) → ∞; as x → ∞, f(x) → ∞","As x → −∞, f(x) → −∞; as x → ∞, f(x) → −∞","As x → −∞, f(x) → ∞; as x → ∞, f(x) → −∞"],"answer":0,"hint":"Degree 3 is odd. The leading coefficient 2 is positive.","solution":"Odd degree with a positive leading coefficient: down on the left, up on the right. As x → −∞, f(x) → −∞; as x → ∞, f(x) → ∞."},{"id":"eb1-q6","type":"choice","prompt":"f(x) = −x³ + 5x + 1. What is its end behavior?","choices":["As x → −∞, f(x) → ∞; as x → ∞, f(x) → −∞","As x → −∞, f(x) → ∞; as x → ∞, f(x) → ∞","As x → −∞, f(x) → −∞; as x → ∞, f(x) → −∞","As x → −∞, f(x) → −∞; as x → ∞, f(x) → ∞"],"answer":0,"hint":"Degree 3 is odd. The leading coefficient −1 is negative.","solution":"Odd degree with a negative leading coefficient: up on the left, down on the right. As x → −∞, f(x) → ∞; as x → ∞, f(x) → −∞."},{"id":"eb1-q7","type":"choice","prompt":"f(x) = x⁴ + 2x³ − x − 9. What is its end behavior?","choices":["As x → −∞, f(x) → ∞; as x → ∞, f(x) → ∞","As x → −∞, f(x) → −∞; as x → ∞, f(x) → −∞","As x → −∞, f(x) → −∞; as x → ∞, f(x) → ∞","As x → −∞, f(x) → ∞; as x → ∞, f(x) → −∞"],"answer":0,"hint":"Degree 4 is even. The leading coefficient 1 is positive.","solution":"Even and positive: both ends go up. As x → −∞, f(x) → ∞; as x → ∞, f(x) → ∞."},{"id":"eb1-q8","type":"choice","prompt":"f(x) = −3x² − 14x + 28. Is the degree even or odd, and is the leading coefficient positive or negative?","choices":["Even degree, negative leading coefficient","Odd degree, positive leading coefficient","Odd degree, negative leading coefficient","Even degree, positive leading coefficient"],"answer":0,"hint":"The degree is the greatest exponent. The leading coefficient is the number in front of it.","solution":"The degree is 2 (even) and the leading coefficient is −3 (negative)."},{"id":"eb1-q9","type":"choice","prompt":"f(x) = 9x⁵ + 2x⁴ − x³ + 9x² − 2. What is its end behavior?","choices":["As x → −∞, f(x) → −∞; as x → ∞, f(x) → ∞","As x → −∞, f(x) → ∞; as x → ∞, f(x) → ∞","As x → −∞, f(x) → −∞; as x → ∞, f(x) → −∞","As x → −∞, f(x) → ∞; as x → ∞, f(x) → −∞"],"answer":0,"hint":"Degree 5 is odd. The leading coefficient 9 is positive.","solution":"Odd and positive: down on the left, up on the right. As x → −∞, f(x) → −∞; as x → ∞, f(x) → ∞."}]},{"id":"end-behavior-2","teach":[{"title":"Reading the ends of a graph","text":["Both ends point the same way: the degree is even. The ends point opposite ways: the degree is odd.","Look at the right end. If it goes up, the leading coefficient is positive. If it goes down, it is negative."],"example":{"problem":"The graph shows f(x) = x⁴ − 5x² + 4. Read its degree type and leading coefficient sign.","steps":["Both ends go up, so they point the same way: even degree.","The right end goes up: positive leading coefficient.","That matches the equation: degree 4 and leading coefficient 1."]},"graph":{"fn":"x^4-5x^2+4","x":[-3,3],"y":[-5,10]}},{"title":"Writing end behavior","text":["Use arrow notation: \"As x → −∞, f(x) → ___; as x → ∞, f(x) → ___.\"","Fill each blank with ∞ (the graph goes up) or −∞ (the graph goes down)."],"example":{"problem":"Describe the end behavior of a 6th-degree polynomial with a negative leading coefficient.","steps":["Degree 6 is even, so both ends point the same way.","Negative leading coefficient, so both ends go down.","As x → −∞, f(x) → −∞; as x → ∞, f(x) → −∞."]}}],"questions":[{"id":"eb2-q1","type":"choice","prompt":"Look at the graph. Is the degree even or odd, and is the leading coefficient positive or negative?","choices":["Odd degree, positive leading coefficient","Odd degree, negative leading coefficient","Even degree, positive leading coefficient","Even degree, negative leading coefficient"],"answer":0,"hint":"Do the two ends point the same way or opposite ways? Which way does the right end go?","solution":"The left end goes down and the right end goes up. Opposite ways means odd degree. The right end goes up, so the leading coefficient is positive.","graph":{"fn":"x^3-4x","x":[-4,4],"y":[-10,10]}},{"id":"eb2-q2","type":"choice","prompt":"Look at the graph. Is the degree even or odd, and is the leading coefficient positive or negative?","choices":["Even degree, negative leading coefficient","Odd degree, positive leading coefficient","Odd degree, negative leading coefficient","Even degree, positive leading coefficient"],"answer":0,"hint":"Do the two ends point the same way or opposite ways? Which way does the right end go?","solution":"Both ends go down. Same way means even degree. The right end goes down, so the leading coefficient is negative.","graph":{"fn":"-x^4+5x^2-2","x":[-3,3],"y":[-10,10]}},{"id":"eb2-q3","type":"choice","prompt":"Look at the graph. Is the degree even or odd, and is the leading coefficient positive or negative?","choices":["Odd degree, negative leading coefficient","Odd degree, positive leading coefficient","Even degree, positive leading coefficient","Even degree, negative leading coefficient"],"answer":0,"hint":"Do the two ends point the same way or opposite ways? Which way does the right end go?","solution":"The left end goes up and the right end goes down. Opposite ways means odd degree. The right end goes down, so the leading coefficient is negative.","graph":{"fn":"-x^3+3x^2+x-3","x":[-3,5],"y":[-10,10]}},{"id":"eb2-q4","type":"choice","prompt":"Look at the graph. Is the degree even or odd, and is the leading coefficient positive or negative?","choices":["Even degree, positive leading coefficient","Odd degree, positive leading coefficient","Odd degree, negative leading coefficient","Even degree, negative leading coefficient"],"answer":0,"hint":"Do the two ends point the same way or opposite ways? Which way does the right end go?","solution":"Both ends go up. Same way means even degree. The right end goes up, so the leading coefficient is positive.","graph":{"fn":"x^4-4x^2+1","x":[-3,3],"y":[-5,10]}},{"id":"eb2-q5","type":"choice","prompt":"Describe the end behavior of a 14th-degree polynomial with a positive leading coefficient.","choices":["As x → −∞, f(x) → ∞; as x → ∞, f(x) → ∞","As x → −∞, f(x) → −∞; as x → ∞, f(x) → −∞","As x → −∞, f(x) → −∞; as x → ∞, f(x) → ∞","As x → −∞, f(x) → ∞; as x → ∞, f(x) → −∞"],"answer":0,"hint":"14 is even.","solution":"Even degree, positive leading coefficient: both ends go up. As x → −∞, f(x) → ∞; as x → ∞, f(x) → ∞."},{"id":"eb2-q6","type":"choice","prompt":"Describe the end behavior of a 9th-degree polynomial with a negative leading coefficient.","choices":["As x → −∞, f(x) → ∞; as x → ∞, f(x) → −∞","As x → −∞, f(x) → ∞; as x → ∞, f(x) → ∞","As x → −∞, f(x) → −∞; as x → ∞, f(x) → −∞","As x → −∞, f(x) → −∞; as x → ∞, f(x) → ∞"],"answer":0,"hint":"9 is odd.","solution":"Odd degree, negative leading coefficient: up on the left, down on the right. As x → −∞, f(x) → ∞; as x → ∞, f(x) → −∞."},{"id":"eb2-q7","type":"choice","prompt":"Without graphing: which function has this end behavior? As x → −∞, f(x) → −∞; as x → ∞, f(x) → −∞","choices":["f(x) = −4x⁴ − x³ + 8x² − 2x","f(x) = −x³ + 10x² − 6x + 8","f(x) = 2x⁵ + 8x⁴ − 10x³","f(x) = 3x² − 17x − 11"],"answer":0,"hint":"Both ends go down. That means even degree and a negative leading coefficient.","solution":"You need even degree and a negative leading coefficient. −4x⁴ − x³ + 8x² − 2x has degree 4 (even) and leading coefficient −4.","calculator":false},{"id":"eb2-q8","type":"choice","prompt":"Without graphing: which function has this end behavior? As x → −∞, f(x) → −∞; as x → ∞, f(x) → ∞","choices":["f(x) = x³ + x² − 13x","f(x) = −x² − 14x + 32","f(x) = −x⁵ + 5x² − 13x − 4","f(x) = −3x⁴ + 2x³ − x² + x"],"answer":0,"hint":"Down on the left and up on the right means odd degree and a positive leading coefficient.","solution":"x³ + x² − 13x has degree 3 (odd) and leading coefficient 1 (positive).","calculator":false},{"id":"eb2-q9","type":"choice","prompt":"Without graphing: which function has this end behavior? As x → −∞, f(x) → ∞; as x → ∞, f(x) → ∞","choices":["f(x) = 2x⁶ + 5x³ − 14x","f(x) = 4x³ − 8x² − 2","f(x) = −x⁴ + x³ − 6x² + x","f(x) = −x² + 10x − 2"],"answer":0,"hint":"Both ends go up. That means even degree and a positive leading coefficient.","solution":"2x⁶ + 5x³ − 14x has degree 6 (even) and leading coefficient 2 (positive).","calculator":false}]},{"id":"end-behavior-3","teach":[{"title":"Find the leading term first","text":["The terms are not always in order. Find the term with the greatest exponent: that is the leading term.","Its exponent is the degree, and its number is the leading coefficient. Only the leading term decides the end behavior."],"example":{"problem":"Describe the end behavior of f(x) = 3x² − 2x⁵ + 7.","steps":["The greatest exponent is 5, in −2x⁵. So the degree is 5 (odd) and the leading coefficient is −2 (negative).","Odd and negative: up on the left, down on the right.","As x → −∞, f(x) → ∞; as x → ∞, f(x) → −∞."]},"graph":{"fn":"3x^2-2x^5+7","x":[-2,2],"y":[-10,20]}},{"title":"End behavior from factored form","text":["You do not have to multiply everything out. Multiply only the x part of each factor: that gives the leading term.","Add the exponents to get the degree."],"example":{"problem":"Describe the end behavior of f(x) = −2x(x − 1)²(x + 3).","steps":["Leading parts: −2x · x² · x = −2x⁴.","Degree 4 (even) and leading coefficient −2 (negative).","Even and negative: both ends go down. As x → −∞, f(x) → −∞; as x → ∞, f(x) → −∞."]},"graph":{"fn":"-2x(x-1)^2(x+3)","x":[-4,2.5],"y":[-20,40]}}],"questions":[{"id":"eb3-q1","type":"input","prompt":"f(x) = 4x − 7x³ + x² − 2. What is the leading coefficient?","answers":["-7"],"hint":"Find the term with the greatest exponent.","solution":"The greatest exponent is 3, in −7x³. The leading coefficient is −7."},{"id":"eb3-q2","type":"input","prompt":"f(x) = 6 + x² − 2x⁶ + 5x³. What is the degree?","answers":["6"],"hint":"The degree is the greatest exponent, wherever that term is.","solution":"The exponents are 0, 2, 6, and 3. The greatest is 6."},{"id":"eb3-q3","type":"choice","prompt":"f(x) = 8x − 3x³ + 1. What is its end behavior?","choices":["As x → −∞, f(x) → ∞; as x → ∞, f(x) → −∞","As x → −∞, f(x) → ∞; as x → ∞, f(x) → ∞","As x → −∞, f(x) → −∞; as x → ∞, f(x) → −∞","As x → −∞, f(x) → −∞; as x → ∞, f(x) → ∞"],"answer":0,"hint":"The leading term is −3x³. Odd or even? Positive or negative?","solution":"The leading term −3x³ has odd degree and a negative coefficient: up on the left, down on the right. As x → −∞, f(x) → ∞; as x → ∞, f(x) → −∞."},{"id":"eb3-q4","type":"choice","prompt":"f(x) = 2x² + 5x⁴ − x. What is its end behavior?","choices":["As x → −∞, f(x) → ∞; as x → ∞, f(x) → ∞","As x → −∞, f(x) → −∞; as x → ∞, f(x) → −∞","As x → −∞, f(x) → −∞; as x → ∞, f(x) → ∞","As x → −∞, f(x) → ∞; as x → ∞, f(x) → −∞"],"answer":0,"hint":"The leading term is 5x⁴, not 2x².","solution":"The leading term 5x⁴ has even degree and a positive coefficient: both ends go up. As x → −∞, f(x) → ∞; as x → ∞, f(x) → ∞."},{"id":"eb3-q5","type":"choice","prompt":"f(x) = −x⁶ + 4x⁵ + 9. What is its end behavior?","choices":["As x → −∞, f(x) → −∞; as x → ∞, f(x) → −∞","As x → −∞, f(x) → ∞; as x → ∞, f(x) → ∞","As x → −∞, f(x) → −∞; as x → ∞, f(x) → ∞","As x → −∞, f(x) → ∞; as x → ∞, f(x) → −∞"],"answer":0,"hint":"Degree 6 is even. The leading coefficient is −1.","solution":"Even degree with a negative leading coefficient: both ends go down. As x → −∞, f(x) → −∞; as x → ∞, f(x) → −∞."},{"id":"eb3-q6","type":"choice","prompt":"f(x) = (x + 2)(x − 3)(x − 5). What is its end behavior?","choices":["As x → −∞, f(x) → −∞; as x → ∞, f(x) → ∞","As x → −∞, f(x) → ∞; as x → ∞, f(x) → ∞","As x → −∞, f(x) → −∞; as x → ∞, f(x) → −∞","As x → −∞, f(x) → ∞; as x → ∞, f(x) → −∞"],"answer":0,"hint":"Multiply the x parts of the factors: x · x · x.","solution":"The leading term is x³: odd degree and a positive leading coefficient. As x → −∞, f(x) → −∞; as x → ∞, f(x) → ∞."},{"id":"eb3-q7","type":"choice","prompt":"f(x) = −x²(x − 4)(x + 1). What is its end behavior?","choices":["As x → −∞, f(x) → −∞; as x → ∞, f(x) → −∞","As x → −∞, f(x) → ∞; as x → ∞, f(x) → ∞","As x → −∞, f(x) → −∞; as x → ∞, f(x) → ∞","As x → −∞, f(x) → ∞; as x → ∞, f(x) → −∞"],"answer":0,"hint":"Multiply the leading parts: −x² · x · x.","solution":"The leading term is −x⁴: even degree and a negative leading coefficient. Both ends go down. As x → −∞, f(x) → −∞; as x → ∞, f(x) → −∞."},{"id":"eb3-q8","type":"choice","prompt":"Without graphing, find the function with this end behavior: As x → −∞, f(x) → ∞; as x → ∞, f(x) → ∞.","choices":["f(x) = 7 − x + 3x⁴","f(x) = 3x³ − x + 7","f(x) = −3x⁴ + x + 7","f(x) = 7 + x − x⁵"],"answer":0,"hint":"Both ends go up: even degree and a positive leading coefficient. Find each leading term first.","solution":"In 7 − x + 3x⁴ the leading term is 3x⁴: degree 4 (even) and a positive coefficient. The others have leading terms 3x³, −3x⁴, and −x⁵.","calculator":false}]},{"id":"end-behavior-4","teach":[{"title":"Match a graph to its equation","text":["Read the ends of the graph first. Then find the equation whose degree and leading coefficient give those ends.","Find the leading term of each equation before you decide: put it in standard form, or multiply the leading parts of the factors."],"example":{"problem":"The graph shows one of these: f(x) = x³ − 4x or g(x) = −x³ + 4x. Which one?","steps":["The left end goes up and the right end goes down: odd degree, negative leading coefficient.","x³ − 4x has leading coefficient 1. −x³ + 4x has leading coefficient −1.","The graph is g(x) = −x³ + 4x."]},"graph":{"fn":"-x^3+4x","x":[-3,3],"y":[-8,8]}}],"questions":[{"id":"eb4-q1","type":"choice","prompt":"The graph shows g(x). Is the degree even or odd, and is the leading coefficient positive or negative?","choices":["Odd degree, negative leading coefficient","Odd degree, positive leading coefficient","Even degree, positive leading coefficient","Even degree, negative leading coefficient"],"answer":0,"hint":"Compare the two ends. Then look at the right end.","solution":"The left end goes up and the right end goes down. Opposite ways means odd degree. The right end goes down, so the leading coefficient is negative.","graph":{"fn":"-x^5+5x^3-4x","x":[-2.5,2.5],"y":[-6,6]}},{"id":"eb4-q2","type":"choice","prompt":"The graph shows h(x). Is the degree even or odd, and is the leading coefficient positive or negative?","choices":["Even degree, positive leading coefficient","Odd degree, positive leading coefficient","Odd degree, negative leading coefficient","Even degree, negative leading coefficient"],"answer":0,"hint":"Compare the two ends. The wiggles in the middle do not matter.","solution":"Both ends go up. Same way means even degree. The right end goes up, so the leading coefficient is positive.","graph":{"fn":"(x^4-4x^3+8x)/2","x":[-2,4],"y":[-5,8]}},{"id":"eb4-q3","type":"choice","prompt":"The graph shows p(x). What is its end behavior?","choices":["As x → −∞, f(x) → −∞; as x → ∞, f(x) → −∞","As x → −∞, f(x) → ∞; as x → ∞, f(x) → ∞","As x → −∞, f(x) → −∞; as x → ∞, f(x) → ∞","As x → −∞, f(x) → ∞; as x → ∞, f(x) → −∞"],"answer":0,"hint":"Follow each end of the graph off the edge of the picture.","solution":"Both ends go down. As x → −∞, p(x) → −∞; as x → ∞, p(x) → −∞.","graph":{"fn":"-(x+2)(x-1)^2(x-3)/2","x":[-3,4],"y":[-10,10]}},{"id":"eb4-q4","type":"choice","prompt":"The graph shows k(x). What is its end behavior?","choices":["As x → −∞, f(x) → −∞; as x → ∞, f(x) → ∞","As x → −∞, f(x) → ∞; as x → ∞, f(x) → ∞","As x → −∞, f(x) → −∞; as x → ∞, f(x) → −∞","As x → −∞, f(x) → ∞; as x → ∞, f(x) → −∞"],"answer":0,"hint":"Follow each end of the graph off the edge of the picture.","solution":"The left end goes down and the right end goes up. As x → −∞, k(x) → −∞; as x → ∞, k(x) → ∞.","graph":{"fn":"x^3-2x^2-5x+6","x":[-4,5],"y":[-10,10]}},{"id":"eb4-q5","type":"choice","prompt":"The graph shows y = f(x). Which equation could it be?","choices":["f(x) = −x³ + x² + 6x","f(x) = x³ − x² − 6x","f(x) = −x⁴ + x² + 6x","f(x) = x⁴ + x² + 6x"],"answer":0,"hint":"Read the ends of the graph. Then check the degree and leading coefficient of each choice.","solution":"Up on the left and down on the right means odd degree and a negative leading coefficient. Only −x³ + x² + 6x has both.","graph":{"fn":"-x^3+x^2+6x","x":[-3.5,4.5],"y":[-10,10]}},{"id":"eb4-q6","type":"choice","prompt":"Describe the end behavior of an 11th-degree polynomial with a positive leading coefficient.","choices":["As x → −∞, f(x) → −∞; as x → ∞, f(x) → ∞","As x → −∞, f(x) → ∞; as x → ∞, f(x) → ∞","As x → −∞, f(x) → −∞; as x → ∞, f(x) → −∞","As x → −∞, f(x) → ∞; as x → ∞, f(x) → −∞"],"answer":0,"hint":"11 is odd.","solution":"Odd degree, positive leading coefficient: down on the left, up on the right. As x → −∞, f(x) → −∞; as x → ∞, f(x) → ∞."},{"id":"eb4-q7","type":"choice","prompt":"Without graphing: f(x) = −3x(x − 2)³. What is its end behavior?","choices":["As x → −∞, f(x) → −∞; as x → ∞, f(x) → −∞","As x → −∞, f(x) → ∞; as x → ∞, f(x) → ∞","As x → −∞, f(x) → −∞; as x → ∞, f(x) → ∞","As x → −∞, f(x) → ∞; as x → ∞, f(x) → −∞"],"answer":0,"hint":"Multiply the leading parts: −3x · x³.","solution":"The leading term is −3x⁴: even degree and a negative leading coefficient. As x → −∞, f(x) → −∞; as x → ∞, f(x) → −∞.","calculator":false},{"id":"eb4-q8","type":"choice","prompt":"Without graphing, find the function with this end behavior: As x → −∞, f(x) → ∞; as x → ∞, f(x) → −∞.","choices":["f(x) = 2x² − x⁵ + 3","f(x) = x⁵ − 2x² + 3","f(x) = −x⁴ + 2x² + 3","f(x) = (x − 1)²(x + 4)²"],"answer":0,"hint":"Up on the left and down on the right means odd degree and a negative leading coefficient.","solution":"In 2x² − x⁵ + 3 the leading term is −x⁵: odd degree, negative coefficient. x⁵ − 2x² + 3 is odd but positive, −x⁴ + 2x² + 3 is even, and (x − 1)²(x + 4)² has leading term x⁴.","calculator":false},{"id":"eb4-q9","type":"choice","prompt":"Without graphing: f(x) = (2 − x)(x + 1)². What is its end behavior?","choices":["As x → −∞, f(x) → ∞; as x → ∞, f(x) → −∞","As x → −∞, f(x) → ∞; as x → ∞, f(x) → ∞","As x → −∞, f(x) → −∞; as x → ∞, f(x) → −∞","As x → −∞, f(x) → −∞; as x → ∞, f(x) → ∞"],"answer":0,"hint":"In (2 − x), the x part is −x. Multiply the leading parts: −x · x².","solution":"The leading term is −x³: odd degree and a negative leading coefficient. As x → −∞, f(x) → ∞; as x → ∞, f(x) → −∞.","calculator":false}]}]},{"id":"turning-points","title":"Turning points and key features","lessons":[{"id":"turning-points-1","teach":[{"title":"Turning points","text":["A turning point is where the graph switches direction.","A turning point higher than every nearby point is a relative maximum. One lower than every nearby point is a relative minimum. Together they are called extrema.","To find them, graph the function in the calculator. It lists the turning points under the graph."],"example":{"problem":"Find the turning points of f(x) = x³ − 6x² + 7x + 2.","steps":["Graph it. The graph rises, turns down, then turns back up.","The top of the first hump is at about (0.71, 4.30). That is the relative maximum.","The bottom of the valley is at about (3.29, −4.30). That is the relative minimum."]},"graph":{"fn":"x^3-6x^2+7x+2","x":[-2,6],"y":[-10,10]}},{"title":"How many turning points?","text":["A polynomial of degree n has at most n − 1 turning points.","It can have fewer. For example, y = x³ has degree 3 but no turning points."],"example":{"problem":"What is the most turning points f(x) = x⁴ − 5x² + 4 can have? How many does it have?","steps":["The degree is 4, so it has at most 4 − 1 = 3 turning points.","Its graph goes down, up, down, up, so it has exactly 3."]},"graph":{"fn":"x^4-5x^2+4","x":[-3,3],"y":[-5,10]}}],"questions":[{"id":"tp1-q1","type":"input","prompt":"What is the most turning points a polynomial of degree 5 can have?","answers":["4"],"hint":"Use n − 1.","solution":"A polynomial of degree n has at most n − 1 turning points. 5 − 1 = 4."},{"id":"tp1-q2","type":"input","prompt":"f(x) = 5x⁷ + 20x⁶ − 75x² + 5. What is the most turning points it can have?","answers":["6"],"hint":"Find the degree first, then subtract 1.","solution":"The degree is 7, so at most 7 − 1 = 6 turning points."},{"id":"tp1-q3","type":"input","prompt":"f(x) = −3x⁸ − x⁷ + x³ − 20x − 8. What is the most turning points it can have?","answers":["7"],"hint":"Find the degree first, then subtract 1.","solution":"The degree is 8, so at most 8 − 1 = 7 turning points."},{"id":"tp1-q4","type":"choice","prompt":"A turning point that is higher than every nearby point is called a…","choices":["relative maximum","relative minimum","zero","leading coefficient"],"answer":0,"hint":"Think of the top of a hill.","solution":"A high turning point is a relative maximum. A low one is a relative minimum."},{"id":"tp1-q5","type":"choice","prompt":"The graph shows f(x) = x³ − 3x² − 3. What is the relative maximum?","choices":["(0, −3)","(2, −7)","(−3, 0)","(3, −3)"],"answer":0,"hint":"Find the top of the hump. You can also graph it in the calculator.","solution":"The graph rises to a peak at x = 0, where f(0) = −3, then turns down. The relative maximum is (0, −3).","graph":{"fn":"x^3-3x^2-3","x":[-3,5],"y":[-10,10]}},{"id":"tp1-q6","type":"choice","prompt":"The graph shows f(x) = x³ − 3x² − 3. What is the relative minimum?","choices":["(2, −7)","(0, −3)","(−7, 2)","(2, −3)"],"answer":0,"hint":"Find the bottom of the valley. Write the point as (x, y).","solution":"The graph falls to its lowest nearby point at x = 2, where f(2) = 8 − 12 − 3 = −7. The relative minimum is (2, −7).","graph":{"fn":"x^3-3x^2-3","x":[-3,5],"y":[-10,10]}},{"id":"tp1-q7","type":"input","prompt":"The graph shows f(x) = x⁴ + x³ − 4x² + 5. How many turning points does it have?","answers":["3"],"hint":"Count every place where the graph changes from going down to going up, or up to down.","solution":"The graph goes down, up, down, then up again. That is 3 turning points, the most a degree-4 polynomial can have.","graph":{"fn":"x^4+x^3-4x^2+5","x":[-3,2.5],"y":[-5,15]}}]},{"id":"turning-points-2","teach":[{"title":"Increasing and decreasing","text":["Read the graph from left to right. It is increasing where it goes up and decreasing where it goes down.","Write intervals with x-values only. The turning points' x-values are where the intervals start and stop. Use parentheses, and ∪ to join two intervals."],"example":{"problem":"Where is f(x) = −x³ + 3x increasing and decreasing?","steps":["The turning points are (−1, −2) and (1, 2).","From the far left to x = −1, the graph goes down: decreasing on (−∞, −1).","From x = −1 to x = 1, it goes up: increasing on (−1, 1).","After x = 1, it goes down again. Decreasing: (−∞, −1) ∪ (1, ∞)."]},"graph":{"fn":"-x^3+3x","x":[-3,3],"y":[-5,5]}},{"title":"Domain and range","text":["The domain of every polynomial is all real numbers: (−∞, ∞).","An odd-degree polynomial also has range (−∞, ∞), because one end goes up forever and the other goes down forever.","An even-degree polynomial's range stops at its lowest point (if the ends go up) or its highest point (if the ends go down)."],"example":{"problem":"What is the range of f(x) = x⁴ − 2x²?","steps":["The degree is 4 (even) and both ends go up.","The lowest points are (−1, −1) and (1, −1), so the lowest y-value is −1.","Range: [−1, ∞). Use a bracket because −1 is reached."]},"graph":{"fn":"x^4-2x^2","x":[-2.5,2.5],"y":[-3,5]}}],"questions":[{"id":"tp2-q1","type":"choice","prompt":"What is the domain of any polynomial function?","choices":["(−∞, ∞)","[0, ∞)","(−∞, 0]","It depends on the degree."],"answer":0,"hint":"Can you put any x-value into a polynomial?","solution":"You can put any real number into a polynomial, so the domain is always (−∞, ∞)."},{"id":"tp2-q2","type":"choice","prompt":"The graph shows f(x) = x³ − 3x² − 3. Its turning points are (0, −3) and (2, −7). Where is f increasing?","choices":["(−∞, 0) ∪ (2, ∞)","(0, 2)","(−∞, −3) ∪ (−7, ∞)","(−∞, 2)"],"answer":0,"hint":"Use x-values only. Where does the graph go up as you move right?","solution":"It goes up until x = 0, down from x = 0 to x = 2, then up again. Increasing: (−∞, 0) ∪ (2, ∞).","graph":{"fn":"x^3-3x^2-3","x":[-3,5],"y":[-10,10]}},{"id":"tp2-q3","type":"choice","prompt":"The graph shows f(x) = x³ − 3x² − 3. Its turning points are (0, −3) and (2, −7). Where is f decreasing?","choices":["(0, 2)","(−7, −3)","(−∞, 0) ∪ (2, ∞)","(2, ∞)"],"answer":0,"hint":"Use x-values only. Where does the graph go down as you move right?","solution":"The graph goes down between the two turning points, from x = 0 to x = 2. Decreasing: (0, 2).","graph":{"fn":"x^3-3x^2-3","x":[-3,5],"y":[-10,10]}},{"id":"tp2-q4","type":"input","prompt":"The graph shows f(x) = x³ + 6x² + 8x. What are its zeros?","answers":["0, -2, -4"],"hint":"Zeros are where the graph crosses the x-axis. Type them separated by commas.","solution":"The graph crosses the x-axis at x = −4, −2, and 0. You can check by factoring: x(x + 2)(x + 4).","graph":{"fn":"x^3+6x^2+8x","x":[-6,2],"y":[-6,6]}},{"id":"tp2-q5","type":"choice","prompt":"The graph shows f(x) = x³ + 6x² + 8x. What is the relative maximum, to two decimal places?","choices":["(−3.15, 3.08)","(−0.85, −3.08)","(0, 0)","(−4, 0)"],"answer":0,"hint":"Find the top of the hump. The calculator lists the turning points when you graph it.","solution":"The hump on the left peaks at about (−3.15, 3.08). The other turning point, (−0.85, −3.08), is the relative minimum.","graph":{"fn":"x^3+6x^2+8x","x":[-6,2],"y":[-6,6]}},{"id":"tp2-q6","type":"choice","prompt":"What is the range of f(x) = x³ + 6x² + 8x?","choices":["(−∞, ∞)","[−3.08, 3.08]","[−3.08, ∞)","(−∞, 3.08]"],"answer":0,"hint":"The degree is odd. What do the two ends do?","solution":"Odd degree: one end goes down forever and the other goes up forever. The range is all real numbers, (−∞, ∞).","graph":{"fn":"x^3+6x^2+8x","x":[-6,2],"y":[-6,6]}},{"id":"tp2-q7","type":"choice","prompt":"The graph shows f(x) = x⁴ + x³ − 4x² + 5. Its lowest point is about (−1.84, −3.31). What is its range?","choices":["[−3.31, ∞)","(−∞, ∞)","[5, ∞)","(−∞, −3.31]"],"answer":0,"hint":"Even degree with both ends up: the range starts at the lowest y-value.","solution":"Both ends go up, and the lowest y-value is about −3.31. Range: [−3.31, ∞).","graph":{"fn":"x^4+x^3-4x^2+5","x":[-3,2.5],"y":[-5,15]}}]},{"id":"turning-points-3","teach":[{"title":"Reading extrema from the calculator","text":["Graph the function. The calculator lists each turning point as max or min, with its coordinates.","A relative maximum or minimum is the whole point (x, y). The y-value tells how high or low the graph gets there."],"example":{"problem":"Find the relative maximum and minimum of f(x) = −x³ + 3x² + 9x − 2.","steps":["Graph it. The calculator shows min (−1, −7) and max (3, 25).","Relative minimum: (−1, −7). Near x = −1, the graph is lowest there.","Relative maximum: (3, 25). Near x = 3, the graph is highest there."]},"graph":{"fn":"-x^3+3x^2+9x-2","x":[-4,6],"y":[-15,30]}},{"title":"Fewer turning points than the most","text":["A polynomial of degree n has at most n − 1 turning points, but it can have fewer.","Count the hills and valleys on the graph. Each one is a turning point."],"example":{"problem":"How many turning points does f(x) = x⁴ + 4x have?","steps":["The degree is 4, so it can have at most 3.","The graph comes down, turns once at (−1, −3), and goes back up.","It has exactly 1 turning point."]},"graph":{"fn":"x^4+4x","x":[-3,2],"y":[-5,10]}}],"questions":[{"id":"tp3-q1","type":"input","prompt":"What is the most turning points a polynomial of degree 6 can have?","answers":["5"],"hint":"Use n − 1.","solution":"A polynomial of degree n has at most n − 1 turning points. 6 − 1 = 5."},{"id":"tp3-q2","type":"input","prompt":"f(x) = 4x³ − x⁶ + 2x − 9. What is the most turning points it can have?","answers":["5"],"hint":"Find the degree first. The first term is not the one with the greatest exponent.","solution":"The greatest exponent is 6, so the degree is 6 and there are at most 6 − 1 = 5 turning points."},{"id":"tp3-q3","type":"choice","prompt":"A polynomial has degree 4. Which number of turning points is impossible for it?","choices":["4","3","1"],"answer":0,"hint":"What is the most a degree-4 polynomial can have?","solution":"Degree 4 allows at most 4 − 1 = 3 turning points, so 4 is impossible. f(x) = x⁴ − 5x² + 4 has 3, and f(x) = x⁴ + 4x has 1."},{"id":"tp3-q4","type":"input","prompt":"The graph shows f(x) = x³ + 3x. How many turning points does it have?","answers":["0"],"hint":"Does the graph ever switch from going up to going down?","solution":"The graph goes up the whole way and never turns. It has 0 turning points, even though a cubic can have up to 2.","graph":{"fn":"x^3+3x","x":[-3,3],"y":[-10,10]}},{"id":"tp3-q5","type":"input","prompt":"The graph shows f(x) = x⁵ + x³ − 2x. How many turning points does it have?","answers":["2"],"hint":"Count the hills and the valleys.","solution":"The graph rises to a hill near x = −0.63, falls to a valley near x = 0.63, then rises again. That is 2 turning points. The most for degree 5 is 4, but this one has fewer.","graph":{"fn":"x^5+x^3-2x","x":[-1.6,1.6],"y":[-2,2]}},{"id":"tp3-q6","type":"choice","prompt":"The graph shows f(x) = −x³ + 3x + 4. What is the relative maximum?","choices":["(1, 6)","(−1, 2)","(6, 1)","(0, 4)"],"answer":0,"hint":"Find the top of the hill. Write it as (x, y).","solution":"The graph rises to a peak at x = 1, where f(1) = −1 + 3 + 4 = 6. The relative maximum is (1, 6).","graph":{"fn":"-x^3+3x+4","x":[-3,3],"y":[-4,10]}},{"id":"tp3-q7","type":"choice","prompt":"The graph shows f(x) = −x³ + 3x + 4. What is the relative minimum?","choices":["(−1, 2)","(1, 6)","(2, −1)","(−1, 0)"],"answer":0,"hint":"Find the bottom of the valley. Write it as (x, y).","solution":"The graph falls to its lowest nearby point at x = −1, where f(−1) = 1 − 3 + 4 = 2. The relative minimum is (−1, 2).","graph":{"fn":"-x^3+3x+4","x":[-3,3],"y":[-4,10]}},{"id":"tp3-q8","type":"choice","prompt":"The graph shows f(x) = x³ − 4x² + 2x + 1. What is the relative minimum, to two decimal places?","choices":["(2.39, −3.42)","(0.28, 1.27)","(−3.42, 2.39)","(3.30, 0)"],"answer":0,"hint":"Graph it in the calculator. It lists the turning points under the graph.","solution":"The valley is at about (2.39, −3.42). (0.28, 1.27) is the relative maximum, and (3.30, 0) is a zero, not a turning point.","graph":{"fn":"x^3-4x^2+2x+1","x":[-1.5,4.5],"y":[-6,4]}}]},{"id":"turning-points-4","teach":[{"title":"Describing a graph completely","text":["Domain: always (−∞, ∞) for a polynomial.","Increasing and decreasing: the x-values of the turning points split the x-axis into intervals.","Range: (−∞, ∞) for odd degree. For even degree, it stops at the highest or lowest y-value."],"example":{"problem":"Describe f(x) = x³ − 3x².","steps":["Turning points: relative maximum (0, 0) and relative minimum (2, −4).","Increasing on (−∞, 0) ∪ (2, ∞). Decreasing on (0, 2).","Odd degree, so the domain and the range are both (−∞, ∞).","End behavior: as x → −∞, f(x) → −∞; as x → ∞, f(x) → ∞."]},"graph":{"fn":"x^3-3x^2","x":[-2,4],"y":[-6,4]}}],"questions":[{"id":"tp4-q1","type":"choice","prompt":"The graph shows f(x) = x³ + 3x² − 9x − 5. Its turning points are (−3, 22) and (1, −10). Where is f decreasing?","choices":["(−3, 1)","(−∞, −3) ∪ (1, ∞)","(−10, 22)","(1, ∞)"],"answer":0,"hint":"Use x-values only. Where does the graph go down as you move right?","solution":"The graph goes down between the two turning points, from x = −3 to x = 1. Decreasing: (−3, 1).","graph":{"fn":"x^3+3x^2-9x-5","x":[-6,4],"y":[-15,25]}},{"id":"tp4-q2","type":"choice","prompt":"The graph shows f(x) = x³ + 3x² − 9x − 5. Its turning points are (−3, 22) and (1, −10). Where is f increasing?","choices":["(−∞, −3) ∪ (1, ∞)","(−3, 1)","(−∞, −10) ∪ (22, ∞)","(−3, ∞)"],"answer":0,"hint":"Use x-values only. Where does the graph go up as you move right?","solution":"It goes up until x = −3, down until x = 1, then up again. Increasing: (−∞, −3) ∪ (1, ∞).","graph":{"fn":"x^3+3x^2-9x-5","x":[-6,4],"y":[-15,25]}},{"id":"tp4-q3","type":"choice","prompt":"The graph shows f(x) = −x⁴ + 2x² + 3. Its turning points are (−1, 4), (0, 3), and (1, 4). Where is f increasing?","choices":["(−∞, −1) ∪ (0, 1)","(−1, 0) ∪ (1, ∞)","(−∞, 0)","(3, 4)"],"answer":0,"hint":"Read from left to right. The graph changes direction at x = −1, 0, and 1.","solution":"It rises to (−1, 4), falls to (0, 3), rises to (1, 4), then falls. Increasing: (−∞, −1) ∪ (0, 1).","graph":{"fn":"-x^4+2x^2+3","x":[-2.5,2.5],"y":[-5,6]}},{"id":"tp4-q4","type":"choice","prompt":"The graph shows f(x) = −x⁴ + 2x² + 3. What is its range?","choices":["(−∞, 4]","(−∞, ∞)","[3, 4]","[4, ∞)"],"answer":0,"hint":"Both ends go down. What is the highest y-value the graph reaches?","solution":"The ends go down forever, and the highest points are (−1, 4) and (1, 4). Range: (−∞, 4].","graph":{"fn":"-x^4+2x^2+3","x":[-2.5,2.5],"y":[-5,6]}},{"id":"tp4-q5","type":"input","prompt":"The graph shows f(x) = x⁴ − 2x³ − 3x² + 4x + 1. What is the x-coordinate of its relative maximum?","answers":["1/2"],"hint":"The relative maximum is the top of the hill between the two valleys. The calculator lists it.","solution":"The turning points are min (−1, −3), max (0.5, 2.06), and min (2, −3). The relative maximum is at x = 0.5 = 1/2.","graph":{"fn":"x^4-2x^3-3x^2+4x+1","x":[-2.5,3.5],"y":[-5,10]}},{"id":"tp4-q6","type":"choice","prompt":"The graph shows f(x) = x⁴ − 2x³ − 3x² + 4x + 1. What is its range?","choices":["[−3, ∞)","(−∞, ∞)","[1, ∞)","[−3, 2.06]"],"answer":0,"hint":"Both ends go up. What is the lowest y-value the graph reaches?","solution":"Both valleys reach y = −3, and the ends go up forever. Range: [−3, ∞).","graph":{"fn":"x^4-2x^3-3x^2+4x+1","x":[-2.5,3.5],"y":[-5,10]}},{"id":"tp4-q7","type":"choice","prompt":"The graph shows f(x) = x³ − 6x² + 9x + 1. Which describes its turning points?","choices":["relative maximum (1, 5), relative minimum (3, 1)","relative maximum (3, 1), relative minimum (1, 5)","relative maximum (5, 1), relative minimum (1, 3)","relative maximum (1, 5), no relative minimum"],"answer":0,"hint":"The hill is the maximum and the valley is the minimum. Write each point as (x, y).","solution":"The graph peaks at (1, 5) and bottoms out at (3, 1). Check: f(1) = 1 − 6 + 9 + 1 = 5 and f(3) = 27 − 54 + 27 + 1 = 1.","graph":{"fn":"x^3-6x^2+9x+1","x":[-1,5],"y":[-4,8]}},{"id":"tp4-q8","type":"choice","prompt":"Use the calculator to graph f(x) = x³ − 5x + 3. What is its relative maximum, to two decimal places?","choices":["(−1.29, 7.3)","(1.29, −1.3)","(7.3, −1.29)","(0, 3)"],"answer":0,"hint":"Type the function into the calculator. Look for the max in the list of turning points.","solution":"The calculator shows max (−1.29, 7.3) and min (1.29, −1.3). The relative maximum is (−1.29, 7.3). (0, 3) is the y-intercept, not a turning point."}]}]},{"id":"zeros","title":"Zeros and multiplicity","lessons":[{"id":"zeros-1","teach":[{"title":"Zeros","text":["A zero is an x-value where f(x) = 0. On the graph, it is where the graph crosses or touches the x-axis.","A polynomial of degree n has at most n real zeros.","An even-degree polynomial has an even number of real zeros (or none). An odd-degree polynomial has an odd number, so always at least one."],"example":{"problem":"Find the zeros of f(x) = x³ + x² − 2x from its graph.","steps":["The graph crosses the x-axis three times.","It crosses at x = −2, x = 0, and x = 1.","Zeros: −2, 0, 1. Degree 3 is odd, and 3 zeros is an odd number."]},"graph":{"fn":"x^3+x^2-2x","x":[-3,3],"y":[-5,5]}},{"title":"Linear factors show the zeros","text":["If (x − a) is a factor of f(x), then a is a zero. So (x − 4) gives the zero 4, and (x + 6) gives the zero −6.","Factor the polynomial completely, then set each factor equal to 0."],"example":{"problem":"Write f(x) = x³ − 2x² − 15x in factored form and find the zeros.","steps":["GCF: x(x² − 2x − 15).","Two numbers that multiply to −15 and add to −2: −5 and 3. So x(x − 5)(x + 3).","Set each factor to 0: x = 0, x = 5, x = −3."]}}],"questions":[{"id":"ze1-q1","type":"input","prompt":"If (x − 4) is a factor of f(x), what is a zero of f(x)?","answers":["4"],"hint":"Set the factor equal to 0 and solve.","solution":"x − 4 = 0 gives x = 4."},{"id":"ze1-q2","type":"input","prompt":"If (x + 6) is a factor of f(x), what zero does it give?","answers":["-6"],"hint":"Set x + 6 = 0. Watch the sign.","solution":"x + 6 = 0 gives x = −6. A + in the factor means a negative zero."},{"id":"ze1-q3","type":"input","prompt":"The graph shows f(x) = −x⁴ + 5x² − 4. List all its zeros, separated by commas.","answers":["1, -1, 2, -2"],"hint":"Find every place where the graph crosses the x-axis.","solution":"The graph crosses at x = −2, −1, 1, and 2. Check: −x⁴ + 5x² − 4 = −(x² − 1)(x² − 4).","graph":{"fn":"-x^4+5x^2-4","x":[-3,3],"y":[-5,5]}},{"id":"ze1-q4","type":"input","prompt":"Factor f(x) = x³ − 12x² + 35x and find its zeros. Type them separated by commas.","answers":["0, 5, 7"],"hint":"Take out the GCF x first.","solution":"x(x² − 12x + 35) = x(x − 5)(x − 7). Zeros: 0, 5, 7."},{"id":"ze1-q5","type":"input","prompt":"Factor f(x) = 3x³ − 21x² − 54x and find its zeros. Type them separated by commas.","answers":["0, 9, -2"],"hint":"Take out the GCF 3x first.","solution":"3x(x² − 7x − 18) = 3x(x − 9)(x + 2). Zeros: 0, 9, −2."},{"id":"ze1-q6","type":"input","prompt":"A polynomial has degree 5. What is the greatest number of real zeros it can have?","answers":["5"],"hint":"Degree n means at most n real zeros.","solution":"A degree-5 polynomial has at most 5 real zeros."},{"id":"ze1-q7","type":"choice","prompt":"Which statement is true?","choices":["An odd-degree polynomial always has at least one real zero.","An even-degree polynomial always has at least one real zero.","A degree-4 polynomial can have 5 real zeros.","Every zero of a polynomial is positive."],"answer":0,"hint":"Think about the end behavior of an odd-degree polynomial.","solution":"An odd-degree graph goes down on one end and up on the other, so it must cross the x-axis at least once. An even-degree graph like y = x² + 1 never touches the x-axis."},{"id":"ze1-q8","type":"choice","prompt":"A polynomial function has zeros at −1, 2, and 7, each with multiplicity 1. Which function in standard form could it be?","choices":["f(x) = x³ − 8x² + 5x + 14","f(x) = x³ + 8x² + 5x − 14","f(x) = x³ − 8x² − 5x + 14","f(x) = x³ − 10x² + 5x + 14"],"answer":0,"hint":"Each zero a gives a factor (x − a). Multiply (x + 1)(x − 2)(x − 7).","solution":"(x + 1)(x − 2) = x² − x − 2. Times (x − 7): x³ − 7x² − x² + 7x − 2x + 14 = x³ − 8x² + 5x + 14."}]},{"id":"zeros-2","teach":[{"title":"Multiplicity","text":["The multiplicity of a zero is how many times its factor appears.","In f(x) = x(x − 3)², the factor (x − 3) appears twice, so the zero 3 has multiplicity 2. The zero 0 has multiplicity 1."],"example":{"problem":"Write f(x) = x³ − 6x² + 9x in factored form and give each zero's multiplicity.","steps":["GCF: x(x² − 6x + 9).","x² − 6x + 9 = (x − 3)².","f(x) = x(x − 3)². Zero 0 has multiplicity 1. Zero 3 has multiplicity 2."]}},{"title":"What multiplicity does to the graph","text":["Odd multiplicity: the graph crosses the x-axis at that zero.","Even multiplicity: the graph touches the x-axis and turns around (it bounces).","The graph shows f(x) = x(x − 3)²: it crosses at 0 and bounces at 3."],"graph":{"fn":"x^3-6x^2+9x","x":[-2,5],"y":[-5,8]}}],"questions":[{"id":"ze2-q1","type":"input","prompt":"f(x) = x²(x − 1)⁴(x + 5). What is the multiplicity of the zero 1?","answers":["4"],"hint":"Look at the exponent on the factor (x − 1).","solution":"(x − 1) appears 4 times, so the zero 1 has multiplicity 4."},{"id":"ze2-q2","type":"choice","prompt":"f(x) = x²(x − 1)⁴(x + 5). What does the graph do at x = 1?","choices":["It touches the x-axis and turns around.","It crosses the x-axis.","It never reaches the x-axis.","It crosses the x-axis twice."],"answer":0,"hint":"Is the multiplicity of the zero 1 even or odd?","solution":"The zero 1 has multiplicity 4, which is even. Even multiplicity means the graph touches and turns around."},{"id":"ze2-q3","type":"choice","prompt":"f(x) = −2x(3x + 1)²(x + 7)⁷. Which describes the factor (3x + 1)?","choices":["Zero −1/3, multiplicity 2, touches","Zero −1/3, multiplicity 2, crosses","Zero 1/3, multiplicity 2, touches","Zero −1, multiplicity 2, touches"],"answer":0,"hint":"Solve 3x + 1 = 0 for the zero. The exponent is the multiplicity.","solution":"3x + 1 = 0 gives x = −1/3. The exponent 2 is the multiplicity. 2 is even, so the graph touches."},{"id":"ze2-q4","type":"input","prompt":"f(x) = −2x(3x + 1)²(x + 7)⁷. What is the multiplicity of the zero −7?","answers":["7"],"hint":"Look at the exponent on (x + 7).","solution":"(x + 7)⁷ means the zero −7 has multiplicity 7. It is odd, so the graph crosses there."},{"id":"ze2-q5","type":"choice","prompt":"Factor f(x) = x⁴ − 16x³ + 64x². What are the zeros and their multiplicities?","choices":["0 (multiplicity 2) and 8 (multiplicity 2)","0 (multiplicity 2) and −8 (multiplicity 2)","0 (multiplicity 1) and 8 (multiplicity 2)","0, 8, and −8 (multiplicity 1 each)"],"answer":0,"hint":"Take out x² first. Then factor the trinomial.","solution":"x²(x² − 16x + 64) = x²(x − 8)². Zero 0 has multiplicity 2 and zero 8 has multiplicity 2."},{"id":"ze2-q6","type":"choice","prompt":"f(x) = −8x³ − 20x². What happens at each zero?","choices":["0 touches (multiplicity 2); −5/2 crosses (multiplicity 1)","0 crosses (multiplicity 1); −5/2 touches (multiplicity 2)","0 touches (multiplicity 2); 5/2 crosses (multiplicity 1)","0 touches (multiplicity 2); −4 crosses (multiplicity 1)"],"answer":0,"hint":"Take out the GCF −4x².","solution":"−4x²(2x + 5). The zero 0 has multiplicity 2, so it touches. 2x + 5 = 0 gives x = −5/2 with multiplicity 1, so it crosses."},{"id":"ze2-q7","type":"choice","prompt":"The graph shows f(x) = −2x⁴ + 4x³ + 16x². Where does it touch the x-axis without crossing?","choices":["x = 0","x = 4","x = −2","Nowhere"],"answer":0,"hint":"Factor out −2x². Which zero has an even multiplicity?","solution":"−2x²(x² − 2x − 8) = −2x²(x − 4)(x + 2). The zero 0 has multiplicity 2 (even), so the graph touches there. It crosses at −2 and 4.","graph":{"fn":"-2x^4+4x^3+16x^2","x":[-3,5],"y":[-20,100]}},{"id":"ze2-q8","type":"choice","prompt":"A polynomial has a zero at −6 with multiplicity 2 and a zero at 2 with multiplicity 1. Which function in standard form could it be?","choices":["f(x) = x³ + 10x² + 12x − 72","f(x) = x³ − 10x² + 12x + 72","f(x) = x² + 4x − 12","f(x) = x³ + 10x² − 12x − 72"],"answer":0,"hint":"The factors are (x + 6)² and (x − 2).","solution":"(x + 6)² = x² + 12x + 36. Times (x − 2): x³ − 2x² + 12x² − 24x + 36x − 72 = x³ + 10x² + 12x − 72."}]},{"id":"zeros-3","teach":[{"title":"Zeros from factors like (ax + b)","text":["Set each factor equal to 0 and solve. The factor (2x − 3) gives 2x = 3, so x = 3/2, not 3.","A factor of x by itself gives the zero 0."],"example":{"problem":"Find the zeros of f(x) = x(2x − 3)(x + 4).","steps":["x = 0.","2x − 3 = 0 gives x = 3/2.","x + 4 = 0 gives x = −4.","Zeros: 0, 3/2, −4."]}},{"title":"Write a polynomial from its zeros","text":["Each zero a gives a factor (x − a). Multiply the factors and write the answer in standard form."],"example":{"problem":"Write a polynomial in standard form with zeros −2, 1, and 3.","steps":["Factors: (x + 2), (x − 1), and (x − 3).","(x + 2)(x − 1) = x² + x − 2.","(x² + x − 2)(x − 3) = x³ − 3x² + x² − 3x − 2x + 6.","Answer: f(x) = x³ − 2x² − 5x + 6"]}}],"questions":[{"id":"ze3-q1","type":"input","prompt":"f(x) = (x − 9)(x + 2). What are its zeros? Type them separated by commas.","answers":["9, -2"],"hint":"Set each factor equal to 0.","solution":"x − 9 = 0 gives x = 9. x + 2 = 0 gives x = −2. Zeros: 9, −2."},{"id":"ze3-q2","type":"input","prompt":"f(x) = x(3x − 4)(x + 5). What are its zeros? Type them separated by commas.","answers":["0, 4/3, -5"],"hint":"Solve 3x − 4 = 0 for x. The answer is a fraction.","solution":"x = 0. 3x − 4 = 0 gives x = 4/3. x + 5 = 0 gives x = −5. Zeros: 0, 4/3, −5."},{"id":"ze3-q3","type":"input","prompt":"Factor f(x) = x³ + 3x² − 10x and find its zeros. Type them separated by commas.","answers":["0, -5, 2"],"hint":"Take out the GCF x first.","solution":"x(x² + 3x − 10) = x(x + 5)(x − 2). Zeros: 0, −5, 2."},{"id":"ze3-q4","type":"input","prompt":"The graph shows f(x) = x³ − 7x − 6. List all its zeros, separated by commas.","answers":["-1, -2, 3"],"hint":"Find every place where the graph crosses the x-axis.","solution":"The graph crosses at x = −2, −1, and 3. Check: (x + 1)(x + 2)(x − 3) = x³ − 7x − 6.","graph":{"fn":"x^3-7x-6","x":[-4,5],"y":[-15,10]}},{"id":"ze3-q5","type":"input","prompt":"Factor f(x) = 2x³ − 8x and find its zeros. Type them separated by commas.","answers":["0, 2, -2"],"hint":"Take out 2x. What is left is a difference of squares.","solution":"2x(x² − 4) = 2x(x + 2)(x − 2). Zeros: 0, 2, −2."},{"id":"ze3-q6","type":"input","prompt":"Factor f(x) = x⁴ − 13x² + 36 and find its zeros. Type them separated by commas.","answers":["2, -2, 3, -3"],"hint":"Treat x² as one variable: two numbers that multiply to 36 and add to −13.","solution":"(x² − 4)(x² − 9) = (x + 2)(x − 2)(x + 3)(x − 3). Zeros: ±2, ±3."},{"id":"ze3-q7","type":"choice","prompt":"A polynomial function has zeros at 3, −3, and 1, each with multiplicity 1. Which function in standard form could it be?","choices":["f(x) = x³ − x² − 9x + 9","f(x) = x³ + x² − 9x − 9","f(x) = x³ − x² + 9x − 9","f(x) = x³ − 9x² − x + 9"],"answer":0,"hint":"Each zero a gives a factor (x − a). Multiply (x − 3)(x + 3)(x − 1).","solution":"(x − 3)(x + 3) = x² − 9. Times (x − 1): x³ − x² − 9x + 9."},{"id":"ze3-q8","type":"choice","prompt":"Which function has zeros at 0, 4, and −1/2?","choices":["f(x) = x(x − 4)(2x + 1)","f(x) = x(x + 4)(2x − 1)","f(x) = (x − 4)(2x + 1)","f(x) = x(x − 4)(x + 2)"],"answer":0,"hint":"Set each factor equal to 0. Which choice gives 0, 4, and −1/2?","solution":"x = 0 gives 0. x − 4 = 0 gives 4. 2x + 1 = 0 gives −1/2. So f(x) = x(x − 4)(2x + 1)."}]},{"id":"zeros-4","teach":[{"title":"Multiplicity and the degree","text":["The exponent on a factor is the multiplicity of its zero. Odd multiplicity: the graph crosses. Even multiplicity: it touches and turns around.","The multiplicities add up to the degree."],"example":{"problem":"f(x) = (x − 2)³(x + 1)². Describe each zero.","steps":["2 has multiplicity 3 (odd): the graph crosses there, flattening out as it goes through.","−1 has multiplicity 2 (even): the graph touches the x-axis and turns around.","Degree: 3 + 2 = 5."]},"graph":{"fn":"(x-2)^3(x+1)^2","x":[-2,3],"y":[-15,10]}},{"title":"Write a polynomial from zeros with multiplicity","text":["Write each factor as many times as its multiplicity, then multiply."],"example":{"problem":"Write a polynomial in standard form with a zero at 1 of multiplicity 2 and a zero at −3 of multiplicity 1.","steps":["Factors: (x − 1)² and (x + 3).","(x − 1)² = x² − 2x + 1.","(x² − 2x + 1)(x + 3) = x³ + 3x² − 2x² − 6x + x + 3.","Answer: f(x) = x³ + x² − 5x + 3"]}}],"questions":[{"id":"ze4-q1","type":"input","prompt":"f(x) = (x + 3)²(x − 6)⁵. What is the multiplicity of the zero 6?","answers":["5"],"hint":"Look at the exponent on the factor (x − 6).","solution":"(x − 6) appears 5 times, so the zero 6 has multiplicity 5."},{"id":"ze4-q2","type":"choice","prompt":"f(x) = (x + 3)²(x − 6)⁵. What does the graph do at x = −3?","choices":["It touches the x-axis and turns around.","It crosses the x-axis.","It does not reach the x-axis there.","It crosses the x-axis and flattens out."],"answer":0,"hint":"Find the multiplicity of the zero −3. Is it even or odd?","solution":"(x + 3)² gives the zero −3 with multiplicity 2. Even multiplicity means the graph touches the x-axis and turns around."},{"id":"ze4-q3","type":"input","prompt":"f(x) = x³(x − 2)(x + 4)². What is the degree of f?","answers":["6"],"hint":"Add up the multiplicities. (x − 2) has an exponent of 1.","solution":"3 + 1 + 2 = 6. The degree is 6."},{"id":"ze4-q4","type":"choice","prompt":"Factor f(x) = x³ + 8x² + 16x. What are the zeros and their multiplicities?","choices":["0 (multiplicity 1) and −4 (multiplicity 2)","0 (multiplicity 1) and 4 (multiplicity 2)","0 (multiplicity 2) and −4 (multiplicity 1)","0, −4, and 4 (multiplicity 1 each)"],"answer":0,"hint":"Take out x first. Then the trinomial is a perfect square.","solution":"x(x² + 8x + 16) = x(x + 4)². The zero 0 has multiplicity 1 and the zero −4 has multiplicity 2."},{"id":"ze4-q5","type":"choice","prompt":"f(x) = 3x⁴ − 12x³ + 12x². Where does the graph touch the x-axis without crossing?","choices":["At x = 0 and at x = 2","Only at x = 0","Only at x = 2","Nowhere. It crosses at every zero."],"answer":0,"hint":"Factor out 3x². Which zeros have an even multiplicity?","solution":"3x²(x² − 4x + 4) = 3x²(x − 2)². Both zeros, 0 and 2, have multiplicity 2, so the graph touches at both."},{"id":"ze4-q6","type":"choice","prompt":"f(x) = (2x − 1)³(x + 4). Which describes the zero that comes from (2x − 1)³?","choices":["Zero 1/2, multiplicity 3, crosses","Zero 1/2, multiplicity 3, touches","Zero 2, multiplicity 3, crosses","Zero −1/2, multiplicity 3, crosses"],"answer":0,"hint":"Solve 2x − 1 = 0. The exponent is the multiplicity.","solution":"2x − 1 = 0 gives x = 1/2. The exponent 3 is the multiplicity. 3 is odd, so the graph crosses."},{"id":"ze4-q7","type":"choice","prompt":"The graph of a cubic touches the x-axis at x = 2 and crosses it at x = −1. Which function could it be?","choices":["f(x) = (x − 2)²(x + 1)","f(x) = (x + 2)²(x − 1)","f(x) = (x − 2)(x + 1)²","f(x) = (x − 2)(x + 1)"],"answer":0,"hint":"Touching means even multiplicity. Crossing means odd multiplicity. A cubic has degree 3 in all.","solution":"The zero 2 needs multiplicity 2: (x − 2)². The zero −1 needs multiplicity 1: (x + 1). Degree 2 + 1 = 3. f(x) = (x − 2)²(x + 1).","graph":{"fn":"x^3-3x^2+4","x":[-2,4],"y":[-6,8]}},{"id":"ze4-q8","type":"choice","prompt":"A polynomial has a zero at 3 with multiplicity 2 and a zero at −1 with multiplicity 2. Which function in standard form could it be?","choices":["f(x) = x⁴ − 4x³ − 2x² + 12x + 9","f(x) = x⁴ + 4x³ − 2x² − 12x + 9","f(x) = x² − 2x − 3","f(x) = x⁴ − 4x³ − 10x² + 12x + 9"],"answer":0,"hint":"The factors are (x − 3)² and (x + 1)². Multiply (x − 3)(x + 1) first, then square it.","solution":"(x − 3)(x + 1) = x² − 2x − 3. (x² − 2x − 3)² = x⁴ − 4x³ + 4x² − 6x² + 12x + 9 = x⁴ − 4x³ − 2x² + 12x + 9."},{"id":"ze4-q9","type":"input","prompt":"f(x) = −x²(x − 5)(x + 1)³. List the zeros where the graph crosses the x-axis, separated by commas.","answers":["5, -1"],"hint":"The graph crosses at zeros with odd multiplicity.","solution":"0 has multiplicity 2 (even), so the graph touches there. 5 has multiplicity 1 and −1 has multiplicity 3, both odd, so the graph crosses at 5 and −1."}]}]},{"id":"solving","title":"Solving polynomial equations","lessons":[{"id":"solving-1","teach":[{"title":"Solve by factoring","text":["Step 1: move all terms to one side so the equation equals 0.","Step 2: factor the polynomial completely.","Step 3: set each factor equal to 0 and solve for x."],"example":{"problem":"Solve 4x³ − 7x² = 3x².","steps":["Move 3x² over: 4x³ − 10x² = 0.","Factor: 2x²(2x − 5) = 0.","2x² = 0 gives x = 0. 2x − 5 = 0 gives x = 5/2.","Solutions: x = 0 and x = 5/2."]}},{"title":"When a factor won't factor","text":["If a quadratic factor will not factor, solve it with square roots or the quadratic formula.","Simplify every radical. If x² equals a negative number, the solutions are imaginary: x² = −4 gives x = ±2i."],"example":{"problem":"Solve 5x⁵ − 80x = 0.","steps":["GCF: 5x(x⁴ − 16) = 0.","Difference of squares: 5x(x² + 4)(x² − 4) = 0.","5x = 0 gives x = 0. x² − 4 = 0 gives x = ±2. x² + 4 = 0 gives x² = −4, so x = ±2i.","Solutions: 0, ±2, ±2i."]}}],"questions":[{"id":"so1-q1","type":"input","prompt":"Solve 12x³ − 3x² = 0. Type every solution, separated by commas.","answers":["0, 1/4"],"hint":"Take out the GCF 3x².","solution":"3x²(4x − 1) = 0. 3x² = 0 gives x = 0. 4x − 1 = 0 gives x = 1/4. Solutions: 0, 1/4."},{"id":"so1-q2","type":"input","prompt":"Solve 2x³ − 16x² − 40x = 0. Type every solution, separated by commas.","answers":["0, 10, -2"],"hint":"Take out the GCF 2x, then factor the trinomial.","solution":"2x(x² − 8x − 20) = 2x(x − 10)(x + 2) = 0. Solutions: 0, 10, −2."},{"id":"so1-q3","type":"input","prompt":"Solve x³ = x² + 20x. Type every solution, separated by commas.","answers":["0, 5, -4"],"hint":"Move everything to one side first: x³ − x² − 20x = 0.","solution":"x(x² − x − 20) = x(x − 5)(x + 4) = 0. Solutions: 0, 5, −4."},{"id":"so1-q4","type":"input","prompt":"Solve x³ − 8x² + 16x = 0. Type every different solution, separated by commas.","answers":["0, 4"],"hint":"x² − 8x + 16 is a perfect square trinomial.","solution":"x(x² − 8x + 16) = x(x − 4)² = 0. Solutions: 0 and 4 (4 has multiplicity 2, but you list it once)."},{"id":"so1-q5","type":"input","prompt":"Solve 2x³ − 3x² − 32x + 48 = 0. Type every solution, separated by commas.","answers":["4, -4, 3/2"],"hint":"Four terms: try grouping.","solution":"x²(2x − 3) − 16(2x − 3) = (x² − 16)(2x − 3) = (x + 4)(x − 4)(2x − 3) = 0. Solutions: 4, −4, 3/2."},{"id":"so1-q6","type":"input","prompt":"Solve 4x³ + 5x² − 16x − 20 = 0. Type every solution, separated by commas.","answers":["2, -2, -5/4"],"hint":"Group the first two terms and the last two terms.","solution":"x²(4x + 5) − 4(4x + 5) = (x² − 4)(4x + 5) = (x + 2)(x − 2)(4x + 5) = 0. Solutions: 2, −2, −5/4."},{"id":"so1-q7","type":"choice","prompt":"What is the first step to solve x³ + 3x² = 24x + 72?","choices":["Move every term to one side so the equation equals 0.","Divide both sides by x.","Take the cube root of both sides.","Factor x³ + 3x² and set it equal to 24x + 72."],"answer":0,"hint":"Factoring only works when one side is 0.","solution":"Move everything to one side first: x³ + 3x² − 24x − 72 = 0. Dividing by x would lose solutions."},{"id":"so1-q8","type":"choice","prompt":"Solve x³ + 3x² = 24x + 72.","choices":["x = −3, 2√6, −2√6","x = 3, 2√6, −2√6","x = −3, 24, −24","x = −3, 4√6, −4√6"],"answer":0,"hint":"Move everything to one side, then group: x²(x + 3) − 24(x + 3).","solution":"x³ + 3x² − 24x − 72 = 0. Group: (x² − 24)(x + 3) = 0. x = −3, or x² = 24 so x = ±√24 = ±2√6."}]},{"id":"solving-2","teach":[{"title":"Imaginary solutions from cubes","text":["A sum or difference of cubes leaves a quadratic factor that does not factor.","Use the quadratic formula on it: x = (−b ± √(b² − 4ac)) / 2a. A negative under the root gives imaginary solutions."],"example":{"problem":"Solve x³ + 125 = 0.","steps":["Sum of cubes: (x + 5)(x² − 5x + 25) = 0.","x + 5 = 0 gives x = −5.","Quadratic formula on x² − 5x + 25: x = (5 ± √(25 − 100)) / 2 = (5 ± √−75) / 2 = (5 ± 5i√3) / 2.","Solutions: −5 and (5 ± 5i√3)/2."]}},{"title":"Word problems","text":["Set the model equal to the given value. Move everything to one side, factor, and solve.","Keep only answers that make sense: no negative lengths, times, or years."],"example":{"problem":"A box has sides (x − 3), (x − 1), and (x − 8), and a volume of 33x. Find the sides.","steps":["(x − 3)(x − 1)(x − 8) = 33x expands to x³ − 12x² + 35x − 24 = 33x.","Move 33x over: x³ − 12x² + 2x − 24 = 0.","Group: x²(x − 12) + 2(x − 12) = (x² + 2)(x − 12) = 0. The only real solution is x = 12.","Sides: 12 − 3 = 9, 12 − 1 = 11, 12 − 8 = 4."]}}],"questions":[{"id":"so2-q1","type":"choice","prompt":"Solve x⁴ − 64 = 0.","choices":["x = ±2√2, ±2i√2","x = ±8, ±8i","x = ±4, ±4i","x = ±2√2 only"],"answer":0,"hint":"x⁴ − 64 = (x² + 8)(x² − 8).","solution":"x² − 8 = 0 gives x = ±√8 = ±2√2. x² + 8 = 0 gives x² = −8, so x = ±2i√2."},{"id":"so2-q2","type":"choice","prompt":"Solve x³ + 512 = 0.","choices":["x = −8, 4 ± 4i√3","x = −8, −4 ± 4i√3","x = 8, 4 ± 4i√3","x = −8 only"],"answer":0,"hint":"512 = 8³. Factor as a sum of cubes, then use the quadratic formula.","solution":"(x + 8)(x² − 8x + 64) = 0. x = −8. Quadratic formula: x = (8 ± √(64 − 256)) / 2 = (8 ± √−192) / 2 = (8 ± 8i√3)/2 = 4 ± 4i√3."},{"id":"so2-q3","type":"choice","prompt":"Solve x⁴ + x² − 42 = 0.","choices":["x = ±√6, ±i√7","x = ±√7, ±i√6","x = ±6, ±7i","x = ±√6, ±√7"],"answer":0,"hint":"Treat x² as one variable: two numbers that multiply to −42 and add to 1.","solution":"(x² + 7)(x² − 6) = 0. x² = 6 gives ±√6. x² = −7 gives ±i√7."},{"id":"so2-q4","type":"choice","prompt":"Solve 4x⁴ + 35x² − 9 = 0.","choices":["x = ±1/2, ±3i","x = ±2, ±3i","x = ±1/2, ±3","x = ±1/4, ±9i"],"answer":0,"hint":"Factor like a trinomial in x²: (4x² − 1)(x² + 9).","solution":"4x² − 1 = 0 gives x² = 1/4, so x = ±1/2. x² + 9 = 0 gives x² = −9, so x = ±3i."},{"id":"so2-q5","type":"choice","prompt":"Solve 5x³ − 3x² + 32x = 2x + 18.","choices":["x = 3/5, ±i√6","x = 3/5, ±√6","x = −3/5, ±i√6","x = 5/3, ±i√6"],"answer":0,"hint":"Move everything to one side: 5x³ − 3x² + 30x − 18 = 0. Then group.","solution":"x²(5x − 3) + 6(5x − 3) = (x² + 6)(5x − 3) = 0. 5x − 3 = 0 gives x = 3/5. x² = −6 gives x = ±i√6."},{"id":"so2-q6","type":"input","prompt":"A business's revenue in thousands of dollars is R(t) = 2t³ − 12t² + 3t + 57, where t is years since 1995. In what year did revenue reach $75,000?","answers":["2001"],"hint":"Set R(t) = 75 (it is in thousands). Then group.","solution":"2t³ − 12t² + 3t + 57 = 75 gives 2t³ − 12t² + 3t − 18 = 0. Group: 2t²(t − 6) + 3(t − 6) = (2t² + 3)(t − 6) = 0. t = 6, so 1995 + 6 = 2001."},{"id":"so2-q7","type":"input","prompt":"A species' population is p(t) = −t⁴ + 56t² + 240, where t is years. About how many years until the species is extinct? Round to the nearest hundredth.","answers":["7.75"],"hint":"Extinct means p(t) = 0. Treat t² as one variable.","solution":"−t⁴ + 56t² + 240 = 0 gives t⁴ − 56t² − 240 = 0, so (t² − 60)(t² + 4) = 0. t² = 60 gives t = √60 ≈ 7.75 years. (Negative time and t² = −4 do not make sense.)"},{"id":"so2-q8","type":"input","prompt":"A trapezoid has bases x + 5 and 5x − 1, height x² + 1, and area 30x + 20 square feet. Find the area in square feet.","answers":["110"],"hint":"Set ½(base₁ + base₂)(height) = 30x + 20, solve for x, then find the area.","solution":"½(6x + 4)(x² + 1) = (3x + 2)(x² + 1) = 3x³ + 2x² + 3x + 2. Set equal to 30x + 20: 3x³ + 2x² − 27x − 18 = 0, so (x² − 9)(3x + 2) = 0 and x = 3. Area = 30(3) + 20 = 110 square feet."}]},{"id":"solving-3","teach":[{"title":"Do not divide by x","text":["Dividing both sides by x throws away the solution x = 0.","Instead, move every term to one side and factor out the x."],"example":{"problem":"Solve 3x³ = 12x.","steps":["Move 12x over: 3x³ − 12x = 0.","Factor: 3x(x² − 4) = 3x(x + 2)(x − 2) = 0.","Solutions: x = 0, x = −2, and x = 2.","Dividing by x first would give only ±2 and miss 0."]}},{"title":"Equations in quadratic form","text":["If the exponents are 4 and 2, treat x² as one variable and factor like a trinomial.","Then solve each x² = k. If k is positive, x = ±√k."],"example":{"problem":"Solve x⁴ − 10x² + 9 = 0.","steps":["Two numbers that multiply to 9 and add to −10: −1 and −9. So (x² − 1)(x² − 9) = 0.","x² = 1 gives x = ±1. x² = 9 gives x = ±3.","Solutions: ±1, ±3."]}}],"questions":[{"id":"so3-q1","type":"input","prompt":"Solve x(x − 6)(2x + 3) = 0. Type every solution, separated by commas.","answers":["0, 6, -3/2"],"hint":"The equation is already factored. Set each factor equal to 0.","solution":"x = 0. x − 6 = 0 gives x = 6. 2x + 3 = 0 gives x = −3/2. Solutions: 0, 6, −3/2."},{"id":"so3-q2","type":"input","prompt":"Solve 5x³ − 20x² = 0. Type every different solution, separated by commas.","answers":["0, 4"],"hint":"Take out the GCF 5x².","solution":"5x²(x − 4) = 0. 5x² = 0 gives x = 0. x − 4 = 0 gives x = 4. Solutions: 0, 4."},{"id":"so3-q3","type":"input","prompt":"Solve x³ + 2x² − 15x = 0. Type every solution, separated by commas.","answers":["0, -5, 3"],"hint":"Take out x, then factor the trinomial.","solution":"x(x² + 2x − 15) = x(x + 5)(x − 3) = 0. Solutions: 0, −5, 3."},{"id":"so3-q4","type":"input","prompt":"Solve x³ = 9x. Type every solution, separated by commas.","answers":["0, 3, -3"],"hint":"Do not divide by x. Move 9x to the left side first.","solution":"x³ − 9x = 0, so x(x² − 9) = x(x + 3)(x − 3) = 0. Solutions: 0, 3, −3."},{"id":"so3-q5","type":"input","prompt":"Solve x⁴ − 17x² + 16 = 0. Type every solution, separated by commas.","answers":["1, -1, 4, -4"],"hint":"Treat x² as one variable: two numbers that multiply to 16 and add to −17.","solution":"(x² − 1)(x² − 16) = 0. x² = 1 gives ±1. x² = 16 gives ±4. Solutions: 1, −1, 4, −4."},{"id":"so3-q6","type":"input","prompt":"Solve x³ − 5x² − 4x + 20 = 0. Type every solution, separated by commas.","answers":["2, -2, 5"],"hint":"Four terms: group them.","solution":"x²(x − 5) − 4(x − 5) = (x² − 4)(x − 5) = (x + 2)(x − 2)(x − 5) = 0. Solutions: 2, −2, 5."},{"id":"so3-q7","type":"input","prompt":"Solve 2x³ + 3x² = 8x + 12. Type every solution, separated by commas.","answers":["2, -2, -3/2"],"hint":"Move everything to the left side, then group.","solution":"2x³ + 3x² − 8x − 12 = 0. x²(2x + 3) − 4(2x + 3) = (x² − 4)(2x + 3) = 0. Solutions: 2, −2, −3/2."},{"id":"so3-q8","type":"input","prompt":"Solve x³ + 4x² + 4x = 0. Type every different solution, separated by commas.","answers":["0, -2"],"hint":"Take out x. The trinomial left over is a perfect square.","solution":"x(x² + 4x + 4) = x(x + 2)² = 0. Solutions: 0 and −2 (−2 has multiplicity 2, but you list it once)."},{"id":"so3-q9","type":"choice","prompt":"Solve x³ − 3x² − 2x + 6 = 0.","choices":["x = 3, ±√2","x = −3, ±√2","x = 3, ±2","x = 3, ±i√2"],"answer":0,"hint":"Group: x²(x − 3) − 2(x − 3).","solution":"(x² − 2)(x − 3) = 0. x − 3 = 0 gives x = 3. x² = 2 gives x = ±√2."}]},{"id":"solving-4","teach":[{"title":"When x² is negative","text":["If a factor gives x² = −k with k positive, the solutions are imaginary: x = ±i√k.","Simplify the radical: √−36 = 6i and √−8 = 2i√2."],"example":{"problem":"Solve x⁴ + 5x² − 36 = 0.","steps":["Treat x² as one variable: (x² + 9)(x² − 4) = 0.","x² = 4 gives x = ±2.","x² = −9 gives x = ±3i.","Solutions: ±2, ±3i."]}},{"title":"Word problems with grouping","text":["Set the model equal to the value you are given. Move everything to one side and factor by grouping.","Keep only answers that make sense, like a positive number of years."],"example":{"problem":"A company's profit, in thousands of dollars, is P(t) = t³ − 4t² + 2t + 10, where t is years after 2015. In what year was the profit $18,000?","steps":["Set P(t) = 18: t³ − 4t² + 2t + 10 = 18, so t³ − 4t² + 2t − 8 = 0.","Group: t²(t − 4) + 2(t − 4) = (t² + 2)(t − 4) = 0.","t = 4. t² = −2 has no real solution.","2015 + 4 = 2019."]}}],"questions":[{"id":"so4-q1","type":"choice","prompt":"Solve x³ + 49x = 0.","choices":["x = 0, ±7i","x = 0, ±7","x = ±7i only","x = 0, ±49i"],"answer":0,"hint":"Take out x. Then x² + 49 = 0 means x² = −49.","solution":"x(x² + 49) = 0. x = 0, or x² = −49, so x = ±7i."},{"id":"so4-q2","type":"choice","prompt":"Solve x⁴ − 81 = 0.","choices":["x = ±3, ±3i","x = ±3 only","x = ±9, ±9i","x = ±3i only"],"answer":0,"hint":"x⁴ − 81 = (x² + 9)(x² − 9).","solution":"x² − 9 = 0 gives x = ±3. x² + 9 = 0 gives x² = −9, so x = ±3i."},{"id":"so4-q3","type":"choice","prompt":"Solve x⁴ − 3x² − 10 = 0.","choices":["x = ±√5, ±i√2","x = ±√2, ±i√5","x = ±5, ±2i","x = ±√5, ±√2"],"answer":0,"hint":"Treat x² as one variable: two numbers that multiply to −10 and add to −3.","solution":"(x² − 5)(x² + 2) = 0. x² = 5 gives ±√5. x² = −2 gives ±i√2."},{"id":"so4-q4","type":"choice","prompt":"Solve x³ − 27 = 0.","choices":["x = 3, (−3 ± 3i√3)/2","x = 3, (3 ± 3i√3)/2","x = −3, (3 ± 3i√3)/2","x = 3 only"],"answer":0,"hint":"Difference of cubes: (x − 3)(x² + 3x + 9). Use the quadratic formula on the second factor.","solution":"x − 3 = 0 gives x = 3. For x² + 3x + 9: x = (−3 ± √(9 − 36)) / 2 = (−3 ± √−27) / 2 = (−3 ± 3i√3)/2."},{"id":"so4-q5","type":"choice","prompt":"Solve 8x³ + 1 = 0.","choices":["x = −1/2, (1 ± i√3)/4","x = 1/2, (−1 ± i√3)/4","x = −1/2, (1 ± i√3)/2","x = −1/2 only"],"answer":0,"hint":"Sum of cubes: (2x + 1)(4x² − 2x + 1). Use the quadratic formula on the second factor.","solution":"2x + 1 = 0 gives x = −1/2. For 4x² − 2x + 1: x = (2 ± √(4 − 16)) / 8 = (2 ± 2i√3) / 8 = (1 ± i√3)/4."},{"id":"so4-q6","type":"choice","prompt":"Solve x³ − 2x² + 9x − 18 = 0.","choices":["x = 2, ±3i","x = 2, ±3","x = −2, ±3i","x = 2, ±9i"],"answer":0,"hint":"Group: x²(x − 2) + 9(x − 2).","solution":"(x² + 9)(x − 2) = 0. x = 2, or x² = −9 so x = ±3i."},{"id":"so4-q7","type":"choice","prompt":"Solve x⁴ = 4x² + 45.","choices":["x = ±3, ±i√5","x = ±3, ±√5","x = ±9, ±5i","x = ±√5, ±3i"],"answer":0,"hint":"Move everything to one side: x⁴ − 4x² − 45 = 0. Then treat x² as one variable.","solution":"(x² − 9)(x² + 5) = 0. x² = 9 gives ±3. x² = −5 gives ±i√5."},{"id":"so4-q8","type":"input","prompt":"A company's profit, in thousands of dollars, is P(t) = t³ − 5t² + 3t + 20, where t is years after 2018. In what year was the profit $35,000?","answers":["2023"],"hint":"Set P(t) = 35 (it is in thousands). Move everything to one side, then group.","solution":"t³ − 5t² + 3t + 20 = 35 gives t³ − 5t² + 3t − 15 = 0. Group: t²(t − 5) + 3(t − 5) = (t² + 3)(t − 5) = 0. t = 5, so 2018 + 5 = 2023."},{"id":"so4-q9","type":"input","prompt":"A box has length x − 1, width x − 2, and height x − 3, in inches. Its volume is 10x cubic inches. What is the volume in cubic inches?","answers":["60"],"hint":"Set (x − 1)(x − 2)(x − 3) = 10x. Expand, move 10x over, then group.","solution":"(x − 1)(x − 2)(x − 3) = x³ − 6x² + 11x − 6. Set equal to 10x: x³ − 6x² + x − 6 = 0. Group: x²(x − 6) + 1(x − 6) = (x² + 1)(x − 6) = 0, so x = 6. Volume = 10 · 6 = 60 cubic inches (sides 5, 4, and 3)."}]}]}],"test":{"questions":[{"id":"t-q1","type":"choice","prompt":"Simplify (−6a⁴b³)² · −2ab⁵.","choices":["−72a⁹b¹¹","72a⁹b¹¹","−12a⁹b¹¹","−72a⁸b¹⁵"],"answer":0,"hint":"Square everything in the parentheses first.","solution":"(−6a⁴b³)² = 36a⁸b⁶. Times −2ab⁵: 36 · −2 = −72, a⁸·a = a⁹, b⁶·b⁵ = b¹¹. Answer: −72a⁹b¹¹."},{"id":"t-q2","type":"choice","prompt":"Simplify 8x⁻³y · 5x⁵y / (10x⁶y²). Use positive exponents only.","choices":["4/x⁴","4x⁴","40/x⁴","4/x¹⁴"],"answer":0,"hint":"Simplify the top first, then divide.","solution":"Top: 40x²y². Divide by 10x⁶y²: 4x²⁻⁶y⁰ = 4x⁻⁴ = 4/x⁴."},{"id":"t-q3","type":"choice","prompt":"Write −2x² + x⁴ + 3 in standard form and classify it.","choices":["x⁴ − 2x² + 3, quartic trinomial","x⁴ − 2x² + 3, quadratic trinomial","3 − 2x² + x⁴, quartic trinomial","x⁴ − 2x² + 3, quartic polynomial"],"answer":0,"hint":"Highest exponent first. Then name the degree and count the terms.","solution":"Standard form: x⁴ − 2x² + 3. Degree 4 is quartic, and 3 terms is a trinomial."},{"id":"t-q4","type":"choice","prompt":"Write −7 + 5m³ + 9m − 3m² in standard form and classify it.","choices":["5m³ − 3m² + 9m − 7, cubic polynomial","5m³ − 3m² + 9m − 7, cubic trinomial","5m³ + 9m − 3m² − 7, cubic polynomial","5m³ − 3m² + 9m − 7, quartic polynomial"],"answer":0,"hint":"Order the exponents 3, 2, 1, 0. Count all the terms.","solution":"Standard form: 5m³ − 3m² + 9m − 7. Degree 3 is cubic, and 4 terms is a polynomial."},{"id":"t-q5","type":"choice","prompt":"Simplify (4h³ + 6h² + 1) − (5h² − 8h⁴ + 6).","choices":["8h⁴ + 4h³ + h² − 5","−8h⁴ + 4h³ + h² − 5","8h⁴ + 4h³ + 11h² + 7","8h⁴ + 4h³ + h² + 7"],"answer":0,"hint":"Change every sign in the second part. −(−8h⁴) is +8h⁴.","solution":"4h³ + 6h² + 1 − 5h² + 8h⁴ − 6 = 8h⁴ + 4h³ + h² − 5."},{"id":"t-q6","type":"choice","prompt":"Multiply (x + 2)(2x² − x − 9).","choices":["2x³ + 3x² − 11x − 18","2x³ + 3x² − 7x − 18","2x³ − 5x² − 11x − 18","2x³ + 3x² − 11x + 18"],"answer":0,"hint":"Multiply x by every term, then 2 by every term.","solution":"x: 2x³ − x² − 9x. 2: 4x² − 2x − 18. Combine: 2x³ + 3x² − 11x − 18."},{"id":"t-q7","type":"choice","prompt":"Multiply 3x(x − 7)(x − 1)².","choices":["3x⁴ − 27x³ + 45x² − 21x","3x⁴ − 27x³ + 45x² + 21x","3x³ − 27x² + 45x − 21","3x⁴ − 24x³ + 21x²"],"answer":0,"hint":"Expand (x − 1)² first, then multiply by (x − 7), then by 3x.","solution":"(x − 1)² = x² − 2x + 1. Times (x − 7): x³ − 9x² + 15x − 7. Times 3x: 3x⁴ − 27x³ + 45x² − 21x."},{"id":"t-q8","type":"choice","prompt":"Divide (21c¹⁰d³ + 56c⁶d² − 7c²d) / (7c²d).","choices":["3c⁸d² + 8c⁴d − 1","3c⁸d² + 8c⁴d","3c⁵d³ + 8c³d² − 1","3c⁸d² + 8c⁴d − 7c²d"],"answer":0,"hint":"Divide each term by 7c²d. Subtract the exponents.","solution":"21c¹⁰d³/7c²d = 3c⁸d². 56c⁶d²/7c²d = 8c⁴d. −7c²d/7c²d = −1. Answer: 3c⁸d² + 8c⁴d − 1."},{"id":"t-q9","type":"choice","prompt":"Factor 27p³ − 1.","choices":["(3p − 1)(9p² + 3p + 1)","(3p − 1)(9p² − 3p + 1)","(3p + 1)(9p² − 3p + 1)","(3p − 1)(9p² + 6p + 1)"],"answer":0,"hint":"Difference of cubes: 27p³ = (3p)³ and 1 = 1³.","solution":"a = 3p, b = 1. (a − b)(a² + ab + b²) = (3p − 1)(9p² + 3p + 1)."},{"id":"t-q10","type":"choice","prompt":"Factor 10x⁵y − 40xy³ completely.","choices":["10xy(x² + 2y)(x² − 2y)","10xy(x⁴ − 4y²)","10xy(x² − 2y)²","10x(x⁴y − 4y³)"],"answer":0,"hint":"GCF first, then a difference of squares.","solution":"10xy(x⁴ − 4y²). x⁴ = (x²)² and 4y² = (2y)². Answer: 10xy(x² + 2y)(x² − 2y)."},{"id":"t-q11","type":"choice","prompt":"Factor 250m³ + 54 completely.","choices":["2(5m + 3)(25m² − 15m + 9)","2(5m + 3)(25m² + 15m + 9)","(5m + 3)(25m² − 15m + 9)","2(5m − 3)(25m² + 15m + 9)"],"answer":0,"hint":"GCF 2 first: 125 = 5³ and 27 = 3³.","solution":"2(125m³ + 27) = 2(5m + 3)(25m² − 15m + 9)."},{"id":"t-q12","type":"choice","prompt":"Factor 6x² + 7x − 20.","choices":["(2x + 5)(3x − 4)","(2x − 5)(3x + 4)","(6x − 5)(x + 4)","(3x + 5)(2x − 4)"],"answer":0,"hint":"a · c = −120. Find two numbers that multiply to −120 and add to 7.","solution":"15 and −8. 6x² + 15x − 8x − 20 = 3x(2x + 5) − 4(2x + 5) = (2x + 5)(3x − 4)."},{"id":"t-q13","type":"choice","prompt":"Factor 3w³ − 2w² + 27w − 18.","choices":["(w² + 9)(3w − 2)","(w + 3)(w − 3)(3w − 2)","(w² + 9)(3w + 2)","(w² + 6)(3w − 3)"],"answer":0,"hint":"Group the first two terms and the last two terms.","solution":"w²(3w − 2) + 9(3w − 2) = (w² + 9)(3w − 2). w² + 9 does not factor."},{"id":"t-q14","type":"choice","prompt":"Factor 3p³ + 5p² − 12p − 20 completely.","choices":["(p + 2)(p − 2)(3p + 5)","(p² − 4)(3p + 5)","(p² + 4)(3p + 5)","(p + 2)(p − 2)(3p − 5)"],"answer":0,"hint":"Group, then check for a difference of squares.","solution":"p²(3p + 5) − 4(3p + 5) = (p² − 4)(3p + 5) = (p + 2)(p − 2)(3p + 5)."},{"id":"t-q15","type":"choice","prompt":"Without graphing: which function has this end behavior? As x → −∞, f(x) → ∞; as x → ∞, f(x) → −∞.","choices":["f(x) = −x³ − 12x + 20","f(x) = 5x² + x − 14","f(x) = −x⁶ + 4x² − 11x − 17","f(x) = −2x⁴ − 7x³ + x² − 6x"],"answer":0,"hint":"Up on the left and down on the right means odd degree and a negative leading coefficient.","solution":"−x³ − 12x + 20 has degree 3 (odd) and leading coefficient −1 (negative).","calculator":false},{"id":"t-q16","type":"choice","prompt":"Look at the graph. Is the degree even or odd, and is the leading coefficient positive or negative?","choices":["Odd degree, negative leading coefficient","Odd degree, positive leading coefficient","Even degree, positive leading coefficient","Even degree, negative leading coefficient"],"answer":0,"hint":"Compare the two ends, then look at the right end.","solution":"The left end goes up and the right end goes down. Opposite ways means odd. The right end goes down, so the leading coefficient is negative.","graph":{"fn":"-x(x^2-1)(x^2-9)/10","x":[-4,4],"y":[-6,6]}},{"id":"t-q17","type":"input","prompt":"f(x) = −x³ + 8x² − 15x. What are its zeros? Type them separated by commas.","answers":["0, 3, 5"],"hint":"Take out the GCF −x.","solution":"−x(x² − 8x + 15) = −x(x − 3)(x − 5). Zeros: 0, 3, 5."},{"id":"t-q18","type":"choice","prompt":"f(x) = −x(3x − 2)²(x + 9)⁵. Which describes all the zeros?","choices":["0 crosses; 2/3 touches; −9 crosses","0 crosses; −2/3 touches; −9 crosses","0 touches; 2/3 crosses; −9 touches","0 crosses; 2/3 touches; 9 crosses"],"answer":0,"hint":"Find each zero from its factor. Even multiplicity touches; odd crosses.","solution":"x gives 0 (multiplicity 1, crosses). 3x − 2 = 0 gives 2/3 (multiplicity 2, touches). x + 9 = 0 gives −9 (multiplicity 5, crosses)."},{"id":"t-q19","type":"choice","prompt":"A polynomial has a zero at 4 with multiplicity 3 and a zero at 0 with multiplicity 1. Which function in standard form could it be?","choices":["f(x) = x⁴ − 12x³ + 48x² − 64x","f(x) = x⁴ + 12x³ + 48x² + 64x","f(x) = x³ − 12x² + 48x − 64","f(x) = x⁴ − 64x"],"answer":0,"hint":"The factors are x and (x − 4)³.","solution":"(x − 4)³ = x³ − 12x² + 48x − 64. Times x: x⁴ − 12x³ + 48x² − 64x."},{"id":"t-q20","type":"choice","prompt":"Solve x⁴ − x² = x² + 8.","choices":["x = ±2, ±i√2","x = ±2, ±√2","x = ±4, ±2i","x = ±2√2, ±i"],"answer":0,"hint":"Move everything to one side: x⁴ − 2x² − 8 = 0.","solution":"(x² − 4)(x² + 2) = 0. x² = 4 gives ±2. x² = −2 gives ±i√2."},{"id":"t-q21","type":"choice","prompt":"Solve 2x⁴ = 24x².","choices":["x = 0, ±2√3","x = 0, ±12","x = ±2√3 only","x = 0, ±4√3"],"answer":0,"hint":"Move 24x² over and take out 2x². Don't divide by x².","solution":"2x⁴ − 24x² = 0, so 2x²(x² − 12) = 0. x = 0, or x² = 12 so x = ±√12 = ±2√3."},{"id":"t-q22","type":"input","prompt":"A species' population is p(t) = −t⁴ + 72t² + 225, where t is years. About how many years until the species is extinct? Round to the nearest hundredth.","answers":["8.66"],"hint":"Set p(t) = 0 and treat t² as one variable.","solution":"t⁴ − 72t² − 225 = 0, so (t² − 75)(t² + 3) = 0. t² = 75 gives t = √75 ≈ 8.66 years."},{"id":"t-q23","type":"choice","prompt":"Factor 9y⁶ + 6y⁴ + y² completely.","choices":["y²(3y² + 1)²","y²(9y⁴ + 6y² + 1)","y(3y² + 1)²","y²(3y + 1)²"],"answer":0,"hint":"GCF y² first. What is left is a perfect square trinomial in y².","solution":"y²(9y⁴ + 6y² + 1). 9y⁴ + 6y² + 1 = (3y² + 1)². Answer: y²(3y² + 1)²."}]}}];
